export default [{"id":110,"question":"هل هذا القول صحيحٌ: الطلاق أبغض الحلال إلى الله؟","title":"درجة حديث \"أبغض الحلال إلى الله الطلاق\"","answer":"الجواب: ... هذا الحديث، نعم، هو حديثٌ صحيحٌ، يقول ﷺ: أبغض الحلال إلى الله الطلاق، وهذا يُفيد أنَّ تركه أوْلى مهما أمكن، فإن تيسر تركه فهو أوْلى.","link":"https://binbaz.org.sa/fatwas/3547/درجة-حديث-ابغض-الحلال-الى-الله-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0094.mp3","categories":["الحكم على الأحاديث","الطلاق"]},{"id":111,"question":"ما حكم زواج المتعة؟ وما حكم الطلاق فيه؟","title":"حكم زواج المتعة والطلاق فيه","answer":"الجواب: زواج المتعة لا يجوز، وهو باطل، وهو أن يتزوَّجها مدةً معلومةً، يعني: يتفقون على أن يتزوَّجها سنةً ثم يُفارقها، أو شهرًا، أو شهرين.\nوكان مباحًا في أول الإسلام، ثم نهى عنه النبيُّ ﷺ ونُسِخَ وقال: إنَّ الله حرَّمه إلى يوم القيامة.\nوإذا تزوَّج متعةً يُطلِّق؛ لأن فيه خلافًا بين أهل العلم، فإذا تزوَّجها متعةً طلَّقها طلقةً واحدةً؛ حلًّا للمشكل، وإزالةً لهذا النكاح المُشتبه، طلقة واحدة فقط.","link":"https://binbaz.org.sa/fatwas/3548/حكم-زواج-المتعة-والطلاق-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0095.mp3","categories":["الأنكحة المحرمة","الطلاق"]},{"id":112,"question":"هل يقع الطلاق المُحَرَّم أم لا؟","title":"هل يقع الطلاق المُحَرَّم والطلاق بالثلاث؟","answer":"الجواب: مثلما تقدم: الصحيح أنه لا يقع، والجمهور على أنه يقع، والصحيح أنه في الحيض والنِّفاس لا يقع عند الأقل، وهو الصواب، والجمهور على أنه إذا طلَّق في الحيض أو النفاس يقع.\nأما طلاق الثلاث فيقع منه واحدةً إذا كان بكلمةٍ واحدةٍ، كأن يقول: أنتِ طالق بالثلاث، أو: هي طالق بالثلاث، فالصواب أنه يحسب واحدة.","link":"https://binbaz.org.sa/fatwas/3549/هل-يقع-الطلاق-المحرم-والطلاق-بالثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0096.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":113,"question":"سائلٌ يقول: هل قول الرجل في الحلف: \"عليَّ الطلاق\" يُعدُّ من الحلف بغير الله؟ وهل يقع الطلاق؟","title":"ما حكم قول \"عليَّ الطلاق\"؟","answer":"الجواب: لا، ليس من الحلف بغير الله، ويُعَدُّ حَلِفًا من حيث اللغة، فيُسمَّى: يمينًا من جهة اللغة، فإذا أراد به المنع أو الحثَّ أو التَّصديق أو التَّكذيب يُسمَّى: يمينًا من حيث اللغة، وفيه الكفَّارة، فإذا قال: \"عليه الطلاق ما يُسافر\"، وقصد الامتناع من السفر، ولم يقصد إيقاع الطلاق، أو قال: \"عليَّ الطلاق ما تذهبين في هذا اليوم\"، أو: \"عليَّ الطلاق ما أُكلمك اليوم\"، وقصده الامتناع، وليس قصده فراقها؛ فهذا يُسمَّى: يمينًا، حكمه حكم اليمين، وليس بمحرمٍ، بل مكروه، وله كفَّارة يمين.\nفإذا قال: \"عليه الطلاق ما يُكلِّمها\" وقصد الامتناع، ولم يقصد فراقها، أو قال: \"عليه الطلاق ما تذهبين هذا اليوم\"، وقصد منعها، ولم يقصد فراقها؛ ففيه كفَّارة يمين، أو قال: \"عليه الطلاق ما يأكل طعامَ فلانٍ\"، أو: \"عليَّ الطلاق ما آكل طعامه ولا آكل ذلك اليوم\"، وقصد الامتناع، ولم يقصد فراق أهله؛ ففيه كفَّارة يمين إذا جلس وأكل الطعام.","link":"https://binbaz.org.sa/fatwas/3550/ما-حكم-قول-علي-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0097.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":114,"question":"سائل يقول: إذا طلبت المرأةُ من زوجها الطلاق وأبى، فما العمل؟","title":"ماذا تعمل من يأبى زوجها تطليقها؟","answer":"الجواب: إذا طلبت الطلاقَ لأسبابٍ شرعيةٍ فينبغي له ألَّا يأبى، ينبغي له أن يخاف الله ويطلب مهره، حقَّه. فإن أبت أن تُعطيه حقَّه فلا طلاقَ لها، لا بدَّ أن تُعطيه حقَّه كاملًا، فإن أبى فعليهم أن يذهبوا إلى المحكمة وتنظر في الأمر.","link":"https://binbaz.org.sa/fatwas/3551/ماذا-تعمل-من-يابى-زوجها-تطليقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0098.mp3","categories":["الطلاق"]},{"id":115,"question":"ما الفرق بين الطلاق والخُلع والفَسخ؟","title":"ما الفرق بين الطلاق والخُلع والفَسخ؟","answer":"الجواب: الطلاق مثل: أنتِ طالق.\nوالخُلع: كونه يخلعها على مالٍ مُعيَّنٍ، فيُسمَّى: خُلْعًا.\nوالفَسخ من جهة الحاكم، ويكون إذا امتنع الزوجُ من الطلاق، ورأى الحاكمُ الفسخَ؛ فإنه يفسخ النكاح، فالفسخ يكون من جهة القاضي.","link":"https://binbaz.org.sa/fatwas/3553/ما-الفرق-بين-الطلاق-والخلع-والفسخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0100.mp3","categories":["الطلاق"]},{"id":116,"question":"امرأة تزوجت من زوجها، فاكتشفت بعد الزواج أنه متزوجٌ بواحدةٍ أخرى غيرها، ولم يُخبرها قبل الزواج، وكذلك يقوم بعض المرات بلعنها وشتمها، ويُعاملها بأخلاق سيئة، فهل يجوز لهذه المرأة أن تطلب الطلاقَ من زوجها؟","title":"حكم طلب الطلاق لسوء الخُلُق والعِشْرة","answer":"الجواب: هي أعلم بنفسها؛ إذا كان عليها ضررٌ بيِّنٌ فلها طلب الطلاق، وإن لم يكن عليها ضررٌ بيِّنٌ فلا تطلب الطلاق، يقول النبيُّ ﷺ: أيُّما امرأة طلبت الطلاقَ من غير ما بأسٍ لم ترح رائحة الجنة، فليس لها أن تسأل إلَّا من علَّة بغضاء، أو ضرر، كالضَّرَّاب للنساء، أو ما جعل الله بينهما محبَّةً؛ فتطلب الطلاق.\nأما مجرد كونه عنده زوجة له حلال فهذا يجوز، فله أن ينكح ثانيةً وثالثةً ورابعةً، إلَّا إذا شُرط عليه ألا يتزوج ثانيةً، فلها شرطها، وأما إذا لم يُشرط عليه فله أن يتزوَّج ثنتين وثلاثة وأربعة.","link":"https://binbaz.org.sa/fatwas/3554/حكم-طلب-الطلاق-لسوء-الخلق-والعشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0101.mp3","categories":["الطلاق"]},{"id":118,"question":"لقد حصل خلافٌ بيني وبين أهل زوجتي عندما وضعت زوجتي مولودها في المستشفى، حيث طلب والدها أن أذهب إلى أهل بيتها، ورفضتُ، وبعد ذلك ذهب بها إلى بيت أهلها وبقيت عندهم، وعندما أردتُ أن آخذها رفضوا، فسألتني والدتي: أين زوجتُك؟ فقلت: لا أرغبها.. إلى آخر السؤال، فيسأل: هل قولي \"لا أرغبها\" يُعتبر طلاقًا؟","title":"هل يعد طلاقاً من قال لزوجته: لا أرغبك؟","answer":"الجواب: \"لا أرغبها\" ليس طلاقًا، إلَّا إذا أردتَ به الطلاق.","link":"https://binbaz.org.sa/fatwas/3556/هل-يعد-طلاقا-من-قال-لزوجته-لا-ارغبك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0103.mp3","categories":["الطلاق"]},{"id":253,"question":"هل يجوز إخراج كفَّارة اليمين نقودًا؟ جزاكم الله خيرًا.","title":"حكمكفَّارة اليمين وهل تجوزنقودًا؟","answer":"الجواب: الشيخ: كفَّارة اليمين لا تخرج نقودًا، الله بيَّنها في كتابه العظيم، يقول سبحانه: لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، هذه كفَّارة اليمين التي بيَّنها الله في كتابه العظيم: طعام، أو كسوة، أو عتق رقبة، فمَن لم يستطع صام ثلاثة أيام، إن كان فقيرًا عاجزًا صام ثلاثة أيام.\nبعض العامَّة يظن أنَّ الصوم مُقدَّم، لا، ما الصوم مُقدَّمًا، المُقدَّم الإطعام والكسوة والعتق، هذا المقدم، ومَن عجز عن الثلاثة من الرجال والنساء صام ثلاثة أيام، ومَن لم يعجز فعليه أن يُطعم أو يكسو أو يعتق.\nإطعام عشرة مساكين من أوسط طعام أهله، أوسط الطعام الذي يتعاطاه، سواء كان يأكل الذرة أو الأرز أو الشَّعير أو غير ذلك، وهكذا إذا كساهم يكسوهم كسوةً تُجزئهم في الصلاة، أو يُعتق رقبةً. أما النقود فلا، لا يُخرج نقودًا، هذا الذي عليه جمهورُ أهل العلم، وهو الحق؛ لأنَّ هذا خلاف ما شرعه الله، النقود خلاف ما شرع الله، فالواجب إعطاء ما تقدَّم من طعامٍ أو كسوةٍ أو عتقٍ، فمَن عجز صام ثلاثة أيام، أما النقود فلا.\nس: الخلاف فيه للتخيير؟\nصيام ثلاثة أيام فيه خلافٌ: بعضهم يرى أنها مُتتابعة، وهذا معروفٌ عن ابن مسعود: ثلاثة أيام متتابعات، وقال بعضُ أهل العلم: ليس بشرطٍ، لكن صومها متتابعة أوْلى وأحوط، وهو قول جمعٍ من أهل العلم، وهو معروفٌ عن عبدالله بن مسعودٍ، فالذي ينبغي أن تكون متتابعةً، ثلاثة أيام متتابعة، هذا هو الذي ينبغي للمؤمن والمؤمنة.","link":"https://binbaz.org.sa/fatwas/4244/حكم-كفارة-اليمين-وهل-تجوزنقودا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0295.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":272,"question":"ورد حديثٌ منسوبٌ إلى رسول الله ﷺ يتضمَّن أنه قال في حقِّ الولد: لاعبه سبعًا، وأدّبه سبعًا، وآخه سبعًا، ثم اترك حبله على غاربه، وكثيرٌ ما يُحتجُّ به على بعض الآباء الذين يُشدّدون على أولادهم عند انحرافهم أو تقصيرهم في أداء الصَّلوات مع الجماعة، ما مدى صحَّة هذا الحديث أثابكم الله؟","title":"درجة حديث \"داعب ولدك سبعاً، وأدِّبه..\"","answer":"الجواب: هذا الحديث لا أصل له، ولا يُعرف، بل هو من المكذوبات -نسأل الله العافية: لاعبه سبعًا، وأدبه سبعًا، وآخه سبعًا كل هذا لا أصلَ له -الله المستعان.\nيقول النبيُّ ﷺ: مُروا أولادكم بالصلاة لسبعٍ، واضربوهم عليها لعشرٍ، وفرِّقوا بينهم في المضاجع، فالوالد مأمورٌ بالعناية بأولاده، وتوجيههم إلى الخير، وضربهم عند الحاجة إلى الضرب بعد العشر، ولا يتخلَّى عنهم أبدًا ولو كبروا -والله المستعان.","link":"https://binbaz.org.sa/fatwas/4268/درجة-حديث-داعب-ولدك-سبعا-وادبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0317.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":286,"question":"سمعتُ أنه لا يجوز أن يقسم بصفة الله، إلا بأن تُضاف إلى الموصوف، فما قولكم؟","title":"ما حكم وكيفية القسم بصفات الله تعالى؟","answer":"الجواب: لا بدّ من ذلك، لا يقسم بصفةٍ إلا مضافة، فيقول: بعزَّة الله، بقدرة الله، بعلم الله، بكلام الله، أو معروفة أنَّها صفة الله، مثل: والقرآن، أو بالقرآن، معروفٌ أنَّ القرآن كلام الله، فلا بأس، أما المخلوق فلا يجوز؛ يقول النبيُّ ﷺ: مَن كان حالفًا فليحلف بالله أو ليصمت.","link":"https://binbaz.org.sa/fatwas/4284/ما-حكم-وكيفية-القسم-بصفات-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0333.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":353,"question":"رجلٌ تزوَّج امرأةً، وأنجبت منه، ثم طلَّقها وحرَّمها على نفسه مُتلفِّظًا بكلمة: \"هي عليه حرام، تحلّ للكلاب السود ولا تحلّ له\"، وبعد عشرين سنة حاول أحدُ أبنائها منه إقناعه بالزواج منها من جديدٍ بمُوجب عقدٍ، فهل عليه شيءٌ؟ علمًا بأنَّ له منها أبناء ومن غيرها.","title":"ما حكم من يقول لزوجته: أنت عليَّ حرام؟","answer":"الجواب: هذا لا يحتاج إلى نظر في الطلاق، لا بدّ أن ينظر في الطلاق الذي صدر منه، فإذا ثبت أن الطلاق واحدةٌ أو اثنتان فله الرجوع إليها بعقدٍ جديدٍ، وإذا ثبت أنه طلَّقها الطلقة الثالثة، وأنها الثالثة؛ فإنها لا تحلّ له حتى تنكح زوجًا غيره.\nفلا بد من النظر، لا ريب في ذلك، يتصل هو وهي ووليها بالعالم الذي يُفتيه، والقاضي الذي يُفتيه من أهل العلم، حتى يشرحوا جميعًا صفة الطلاق، الزوج والمطلقة ووليها يجتمعون عند الحاكم الشرعي أو عند العالم ليُفتيهم، حتى يشرحوا له الواقعة، وحتى يعرف الحقيقة، ثم تكون الفتوى على ضوء ذلك.\nوالقاعدة: أنه إذا كان الطلاقُ واحدةً أو اثنتين فإنها لا تحرمها، بل تجوز له بعقدٍ جديدٍ إذا كانت قد خرجت من العدَّة، أما إذا طلَّقها الطلقة الأخيرة الثالثة فإنها لا تحلّ له عند جميع المسلمين حتى تنكح زوجًا غيره؛ لقوله سبحانه: فَإِنْ طَلَّقَهَا يعني: الثالثة فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ [البقرة:230].\nأما التحريم فله شأنٌ آخر، إذا حرَّمها فتحريمه له شأنٌ آخر: إذا قال: \"هي عليه حرام\" أو \"كظهر أمه\" ولم يُطلقها، إنما حرمها؛ فهذا له كفَّارة، حرمها فقط ولم يُطلق، فإنَّ عليه كفَّارة قبل أن يمسَّها، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا قبل أن يمسَّها.","link":"https://binbaz.org.sa/fatwas/4545/ما-حكم-من-يقول-لزوجته-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0406.mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":368,"question":"رجلان تبايعا ثم اختلفا في المجلس، فقال البائع بالطلاق، وكررها أكثر من مرتين بألا يبيع على المُشتري الحاضر معه في المجلس أبدًا، ثم بدا له من بعد ذلك أن يبيع، فما حكم ذلك؟","title":"حكم من حلف بالطلاق بشأن بيع بضاعة","answer":"الجواب:\nأولًا لا ينبغي استعمال الطلاق في هذا، وأقل أحواله الكراهة؛ لأنه قد يُفضي إلى الطلاق، قد يُفضي إلى الفُرقة وضياع البيت.\nثم التعبير بالطلاق لا يجوز؛ لأنه حلفٌ بغير الله، فقوله بالطلاق أو بالتحريم أو بالحرام لا يجوز؛ لأنه حلف بغير الله، لا يجوز.  لكن إذا قال: \"عليه الطلاق لا يبيع\"، \"عليه الطلاق لا يُكلم فلانًا\" هذا فيه تفصيلٌ: إن كان قصده منع نفسه من هذا الشيء، ما قصده طلاقها، ليس قصده فراق زوجته، وإنما قصده التأكيد على نفسه أنه ما يبيع عليه، هذا مقصوده: لا يبيع عليه هذا؛ عليه كفَّارة يمين إذا باع عليه. أما إن كان قصده إيقاع الطلاق: هو باع الآن على أن يقع الطلاقُ على زوجته، فإنه إذا باع يقع الطلاق، فلا يبع إذا كان يُحب أن تبقى زوجته معه وأن لا يقع الطلاق. أما إذا كان لا، ما قصد إلا مجرد التأكيد ومنع نفسه من البيع، ليس قصده إيقاع الطلاق، وليس قصده مفارقة زوجته، ولكنه أراد بهذا التأكيد على أنه لا يبيع؛ فهذا فيه كفَّارة اليمين إذا باع.","link":"https://binbaz.org.sa/fatwas/4620/حكم-من-حلف-بالطلاق-بشان-بيع-بضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0423.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":470,"question":"عفا الله عنك يا شيخ، حديث:  لا تدخل الملائكة بيتًا فيه كلب ولا صورة ولا جنب؟","title":"درجة حديث \"لا تدخل الملائكة بيتًا فيه كلب\"","answer":"الجواب: زيادة \"الجنب\" فيها نظر؛ لأن الرسول ﷺ كان يبيت وهو جنب، وهو أفضل البيوت.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6195/درجة-حديث-لا-تدخل-الملاىكة-بيتا-فيه-كلب","audio":"https://files.zadapps.info/binbaz.org.sa/beat030.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":471,"question":"حديث عائشة الأول: لا أبيح المسجد لحائض ولا جنب درجة الحديث؟","title":"ما صحة حديث \"لا أبيح المسجد لحائض..\"؟","answer":"الجواب: لا بأس به.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6196/ما-صحة-حديث-لا-ابيح-المسجد-لحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/hadeth031.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":488,"question":"درجة حديث أبي سعيد الخدري: ذكاة الجنين ذكاة أمه؟","title":"ما صحة حديث \"ذكاة الجنين ذكاة أمه\"؟","answer":"الجواب: لا بأس به.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6247/ما-صحة-حديث-ذكاة-الجنين-ذكاة-امه","audio":"https://files.zadapps.info/binbaz.org.sa/7'odry049.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":490,"question":"حديث ابن عباس: فإن المسلم في اسم من أسماء الله؟","title":"هل صح أن \"المسلم في اسم من أسماء الله\"؟","answer":"الجواب: هذا ضعيف، المسلم غير أسماء الله، اسم الله: السلام.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6249/هل-صح-ان-المسلم-في-اسم-من-اسماء-الله","audio":"https://files.zadapps.info/binbaz.org.sa/asmaa051.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":542,"question":"الزواج بنية الطلاق يسميه أهل العلم: نكاح الغريب؟","title":"هل يُفضل ترك النية في الزواج بنية الطلاق؟","answer":"الجواب: ما أدري عنه، المقصود أن الجمهور يرى أنه لا بأس به إن كان بينه وبين الله فقط، ولكن الشرط لا، والأفضل ترك النية كما قال الأوزاعي رحمه الله وجماعة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6373/هل-يفضل-ترك-النية-في-الزواج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/maram108 - 04 - .mp3","categories":["الطلاق"]},{"id":544,"question":"لو عرفت المرأة أن هذا مسافر وأنه سيطلق بعد شهر وهي موافقة، لكن ما اشترطت؟","title":"حكم الطلاق بدون معرفة الزوجة","answer":"الجواب: ما يضر، الصحيح أنه لا يضر، هذا شيء بينه وبين الله، له أن يطلق ولو ما درت له أن يطلق، إذا ما ناسبته، ولو بعد ساعة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6375/حكم-الطلاق-بدون-معرفة-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/maram110 - 04 - .mp3","categories":["الطلاق"]},{"id":549,"question":"رجل طلق زوجته وهي ترضع، ومكث بينهما بعد الفراق سنة كاملة، هل هذا الطلاق صحيح أم ليس صحيح؟","title":"حكم طلاق المُرْضِع","answer":"الجواب: لا يجوز أن يطلقها حتى يجتنبها، يطلقها بعد أن يمسها، فإذا طلقها بعد أن يمسها هذا منكر لا يجوز، كما ذكر ابن عمر عن النبي ﷺ، قال: ثم ليمسكها حتى تطهر يطلق قبل أن يمس.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6380/حكم-طلاق-المرضع","audio":"https://files.zadapps.info/binbaz.org.sa/maram115 - 01 -  Start.mp3","categories":["الطلاق"]},{"id":551,"question":"إذا قال: \"أنت عليّ حرام\" يُنظر في نيته؟","title":"حكم من قال لامرأته: \"أنت عليّ حرام\"","answer":"الجواب: لا، إذا قال: \"أنتِ علي حرام\"؛ فحكمه حكم الظهار، إلا إذا عَلّق.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6382/حكم-من-قال-لامراته-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/maram117 - 02 - .mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":553,"question":"يقول: كنت أنا وزوجتي أمام التلفاز وليس بيني وبينها أي نزاع، يقول: فقلت بدون شعور: أنتِ طالق. ثم ذهبت تبكي، بدون أي نزاع بيننا، يقول: هل هذا من الكلام الخطأ؟","title":"ما حكم الطلاق بدون شعور؟","answer":"الجواب: تحسب الطلقة، إلا إذا أراد شيئًا وغلط، إذا أراد: أنت طاهر، أو أنت طيبة، وغلط؛ فما يحصل إذا كان صادقًا. أما إذا تعمد الطلاق تُحسب.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6384/ما-حكم-الطلاق-بدون-شعور","audio":"https://files.zadapps.info/binbaz.org.sa/maram119 - 02 - .mp3","categories":["الطلاق"]},{"id":554,"question":"إذا قال: إذا خرجت وإذا فعلت ِ كذا فأنتِ عليّ حرام، فهل يُسأل عن نيته؟","title":"ما معنى وحكم الطلاق المُعَلّق؟","answer":"الجواب: هل قصده تحريمها أو منعها بس؟ أما إذا كان قصده منعها فهذا عليه كفارة يمين، وإذا كان قصده تحريمها فحكمه الظهار.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6385/ما-معنى-وحكم-الطلاق-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/maram120.mp3","categories":["الأيمان والنذور","الطلاق","الظهار"]},{"id":556,"question":"طلاق السكران؟","title":"ما حكم طلاق السكران؟","answer":"الجواب: إذا عُلم أنه سكران؛ ما يقع الطلاق. أما دعواه ما تقبل حتى يُعلم بالدليل أنه سكران.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6387/ما-حكم-طلاق-السكران","audio":"https://files.zadapps.info/binbaz.org.sa/maram122 - 01 -  Start.mp3","categories":["الطلاق"]},{"id":558,"question":"إذا قال: إذا خرجت من البيت فأنت طالق، وإذا ركبت مع أخوك فأنت طالق، فهل تقع طلقتين أو طلقة؟","title":"ما حكم الطلاق المُعَلَّق؟","answer":"الجواب: إذا كان قصده منعها ففيه كفارة يمين، وإذا كان قصده الطلاق فيقع طلقتان، بالخروج من البيت طلقة، وركوبها مع أخيها طلقة، إذا كان قصده الطلاق.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6389/ما-حكم-الطلاق-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/maram124 - 02 - .mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":650,"question":"حديث ابن عباس كان يلزق صدره ووجهه بالملتزم؟","title":"درجة حديث \"كان يلزق صدره بالملتزم\"","answer":"الجواب: هذا ضعيف، لكن ثبت من فعل بعض الصحابة كابن عمرو وابن عباس، والحديث فيه ضعف من رواية الشيعة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6680/درجة-حديث-كان-يلزق-صدره-بالملتزم","audio":"https://files.zadapps.info/binbaz.org.sa/maram218 - 03 -  - 03 - .mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":672,"question":"س: من غربت عليه الشمس يوم العيد ولم يطف هل يعود حرمًا؟","title":"درجة حديث \"من غربت الشمس ولم يطف\"","answer":"الجواب: لا، حديث ضعيف الحديث فيه أبو عبيدة وهو مستور الحال لا يحتج به.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6710/درجة-حديث-من-غربت-الشمس-ولم-يطف","audio":"https://files.zadapps.info/binbaz.org.sa/maram240 - 01 -  Start.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":792,"question":"بالنسبة لسيرة الطلاق يا شيخ، يعني: الإخوان يسألون كثيرًا عن الطلاق، ما رأيك؟","title":"ما الحكم الشرعي للطلاق؟","answer":"الجواب:\nالطلاق شرعه الله لعباده رحمةً لهم؛ لأنَّ المرأة قد تكون غلًّا في عنقه، شاقَّةً على الزوج، ولا تُناسبه، ولا ينبغي أن تكون غلًّا في عنقه، فلهذا شرع الله الطلاقَ إذا دعت الحاجةُ إليه أُبيح، وعند عدم الحاجة يُكره، فالأحكام الخمسة تدخله: قد يكون مباحًا، ومُستحبًّا، ومُحَرَّمًا، وواجبًا، ومكروهًا، تدخله الأحكام الخمسة، فإذا دعت الحاجةُ إليه فهو مباحٌ، وإذا تضرر به الزواج صار سنةً –الطلاق- وإذا آلى منها وجب عليه الطلاقُ أو الفيئةُ عند الإيلاء، ويحرُم في الحيض أو النِّفاس، أو في طُهْرٍ جامعها فيه، ويُكره من غير حاجةٍ.","link":"https://binbaz.org.sa/fatwas/20783/ما-الحكم-الشرعي-للطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0614حكم الطلاق؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطلاق"]},{"id":824,"question":"إنَّ بعض الناس تعوَّدوا حين تهديد زوجاتهم بالطلاق، كأن يقول لزوجته: إذا خرجتِ من الدار فأنت طالقة، وإذا ذهبتِ إلى دار فلانٍ فأنت طالق، وهكذا يتكرر هذا الأمر منهم مرات عديدة، فهل يصحّ ذلك؟ أو هل يقع منهم طلاقٌ أم أنه يمينٌ؟","title":"حكم الطلاق للتهديد وحكم طلاق الثلاث","answer":"الجواب: هذا فيه تفصيل، هذا الكلام فيه تفصيل: فإذا قال: إن خرجتِ فأنت طالق، أو قال: إذا ذهبتِ إلى أهلك فأنت طالق، أو قال: إن كلمتِ فلانًا فأنت طالق، هو يقصد منعها وتهديدها وتخويفها، وليس قصده إيقاع الطلاق، إنما قصده أن يُحذِّرها من ذلك، ويمنعها منه؛ فهذا إذا خالفته فعليه كفَّارة يمين.\nوهي ليس لها أن تُخالفه، لا يجوز لها أن تعصي زوجها في مثل هذا، عليها السمع والطاعة، ولو ما طلَّق، إذا قال: لا تخرجي، لا تخرجي، لا تُكلِّمي فلانًا، لا تُكلِّمي  فلانًا، حتى يرضى، وحتى تستسمحه، فإذا طلَّق صار الأمرُ أشدَّ، فليس لها أن تعصيه في المعروف.\nوإذا كان المقصود منعها وتخويفها وتهديدها لعلها ترتدع، ثم فعلت وعاندت، فهي آثمةٌ، وعليه كفَّارة يمين هو وهي: إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبةٍ، فمَن لم يستطع صام ثلاثة أيامٍ، إذا لم يستطع إطعام عشرة مساكين ولا كسوتهم ولا العتق فإنه يصوم ثلاثة أيام، والأفضل أن تكون مُتتابعةً، أما مَن يستطيع الإطعام أو الكسوة أو العتق فليس له الصيام، بل يُكفِّر بإطعامٍ أو بكسوةٍ أو بعتقٍ.\nأما إذا كان قصدُه إيقاع الطلاق، قال: إن كلمتِ فلانًا فأنت طالق، ونيته أنه متى كلمته فهي طالق، قصده فراقها، فإنه يقع طلقة في ذلك، أو قال: إذا ذهبتِ إلى أهلك بغير إذني فأنت طالق، وذهبت وقصده إيقاع الطلاق؛ يقع الطلاق.\nأما إذا كان قصده التَّهديد والتَّخويف والتَّحذير، وليس قصده إيقاع الطلاق؛ فهذا لا يقع، وعليه كفَّارة يمينٍ، أما إذا كان قصده إيقاع الطلاق وتنفيذه مع منعها، هو يريد منعها وإيقاع الطلاق أيضًا، فإنه يقع الطلاقُ، يكون طلقةً واحدةً، إذا قال: أنت طالق، أو قال: طالق بالثلاث، فهي تُعتبر واحدةً على الصحيح، الثلاث بلفظٍ واحدٍ تُعتبر طلقةً واحدةً في أصحِّ قولي العلماء.","link":"https://binbaz.org.sa/fatwas/20867/حكم-الطلاق-للتهديد-وحكم-طلاق-الثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0662بعض الناس تعود أن يهدد زوجاتهم بالطلاق,فهل يقع منه الطلاق ؟ ابن باز.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":910,"question":"هناك رجلٌ طلَّق امرأته في غضبٍ خفيفٍ، وقال بأنَّ الطلاق لم يقع، واحتجَّ بما رواه الإمام أحمد: لا طلاقَ ولا عتاقَ في إغلاقٍ؟","title":"ما حكم طلاق الغضبان غضبًا خفيفًا؟","answer":"الجواب: الإغلاق: شدَّة الغضب، أو الإكراه، أو السُّكْر، أما الغضب الخفيف ما يُسمَّى: إكراهًا، ولا يُسمَّى: إغلاقًا، يعني: انغلق عليه قصده بشدَّة الغضب، أو بالإكراه بالضرب ونحوه، أو بزوال العقل بالسُّكْر ونحوه، هذا هو الإغلاق. أما هذا الذي يُفتي نفسه بأن الغضب اليسير يُسمَّى: إغلاقًا، هذا غلطٌ، غالب الناس يُطلِّقون عند الغضب، فيقع الطلاق. والغضب ثلاثة أقسام:\nغضبٌ يزول معه العقل، هذا لا يقع عند الجميع، إذا زال عقله.\nوالغضب الثاني: يشتدُّ معه الغضب، ولا يستطيع التَّحكم في نفسه، بسبب المسابَّة والمشاتمة والمضاربة، أسبابه واضحة، فهذا فيه خلافٌ بين العلماء، والأرجح أنه لا يقع؛ لهذا الحديث وما جاء في معناه.\nوالغضب الثالث: الغضب العادي الذي ليس فيه ما يُوجب اختلال العقل، وليس هناك شدَّة تمنع من تعقُّله الطلاق، وتوقّفه عنه، فهذا يقع به الطلاق عند الجميع.","link":"https://binbaz.org.sa/fatwas/20950/ما-حكم-طلاق-الغضبان-غضبا-خفيفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0746حكم من يحتج بحديث لا طلاق ولا اعتاق في أعلاق على عدم طلاق الغضبان الغضب البسيط؟ ابن باز.mp3","categories":["الطلاق"]},{"id":964,"question":"عن أبي هريرة  قال: بينما رجلٌ يُصلي أسبل إزاره، قال له ﷺ: اذهب فتوضأ، ثم جاء، فقال: اذهب فتوضأ، فقال له رجلٌ: يا رسول الله، أمرته أن يتوضأ ثم سكتَّ عنه! قال: إنه كان يُصلي وهو مُسْبِلٌ إزاره، وإن الله لا يقبل صلاةَ رجلٍ مُسبلٍ رواه أبو داود بإسنادٍ صحيحٍ على شرط مسلم، وهذا الحديث في \"رياض الصالحين\" فما حكمكم على هذا الحديث من ناحية السَّند والمتن؟ أجيبونا أثابكم الله.","title":"حكم الإسبال وحكم وضوء وصلاة المُسْبِل","answer":"الجواب: هذا الحديث مثلما ذكر السائلُ في \"رياض الصالحين\"، قد حكم عليه النووي بأنه صحيح، ولكن ليس كما قال النووي، بل في إسناده ضعفٌ وجهالةٌ وتدليسٌ. ولكن معناه صحيح، فإن الإسبال محرَّمٌ، ولا يجوز، يجب على المسلم أن يبتعد عن الإسبال، لا في الصلاة، ولا في غيرها. والإسبال هو: إرخاء الثياب تحت الكعبين من الرِّجْل، إرخاء الثياب –الملابس: سراويل أو إزار أو بشت أو قميص- حتى تنزل عن الكعبين، هذا يُسمَّى: إسبال، وقد نهى النبيُّ عن هذا، وتوعَّد عليه عليه الصلاة والسلام وقال: ما أسفل من الكعبين من الإزار فهو في النار.\nوفي هذا الحديث أنه قال: ارجع فتوضأ ولم يأمره بإعادة الصلاة، فدلَّ على أن صلاته صحيحة، لو صحَّ الحديثُ فهو لم يأمره بالإعادة، ولكن توعَّده، ونفي القبول لا يلزم منه نفي صحَّة الصلاة؛ لأنه لم يأمره بالإعادة، فقد تُقبل الصلاةُ وتُجزئ، ولكن يفوته ثوابها، هذا لو صحَّ معناه التَّشديد في الإسبال، وأنه من أسباب عدم قبول الصلاة، كما قال في الحديث الآخر: مَن أتى عرَّافًا فسأله عن شيءٍ لم تُقبل له صلاة أربعين ليلةً، ومع ذلك أهلُ العلم لا يأمرونه بالإعادة، يعني: يفوته ثوابها بسبب سؤاله العرَّافين الذين يدَّعون علوم الغيب.\nفالحاصل: أن الإسبال محرَّمٌ، ولا يجوز تعاطيه من الرَّجُل، وقد قال عليه الصلاة والسلام: ثلاثٌ لا يُكلمهم الله، ولا يُزكيهم، ولا ينظر إليهم، ولهم عذابٌ أليمٌ: المسبل إزاره، والمنان بما أعطى، والمنفق سلعته بالحلف الكاذب، فالواجب الحذر من الإسبال، والتناصح في ذلك.\nوأما قول بعض الفقهاء أنه يحرم إذا كان للخيلاء فقط، فليس بصحيحٍ، بل هو حرامٌ مطلقًا، ولكن إذا كان مع الخيلاء صار أشدَّ إثمًا، كما قال عليه الصلاة والسلام: مَن جرَّ ثوبه خيلاء لم ينظر الله إليه يوم القيامة، إذا جرَّه من التَّكبر صار أعظم في الإثم، وإذا تساهل في إسبال الثياب ولم يقصد التَّكبر صار آثمًا، ولكنَّ إثمه دون مَن كان يجرُّها تكبُّرًا.\nوالغالب أنَّ مَن جرَّها إنما يجرُّها تكبرًا وخيلاء وتعاظمًا، هذا هو الغالب، وقد يجرُّها عن تساهلٍ وكسلٍ، فلا يكون عليه إثمٌ من جرِّها تكبرًا، ولكنه آثمٌ بتساهله.\nأما مَن غلبه ذلك وهو يعتني، ويرفع إزاره ويعتني، لكن قد يرتخي من غير قصدٍ، فهذا لا يضرُّه ذلك، كما قال الصديقُ  للنبي ﷺ: إنه يتفلَّت عليَّ، إلا أني أتعاهده، قال: لستَ ممن يجرُّه خيلاء.\nفالمسلم يُلاحظه ويعتني به، فإذا فاته فوات..... بأن انفتق إزاره... أو حصل شيءٌ من الخلل، ثم تلافاه في الحال واعتنى؛ فلا شيء عليه، أما إنسانٌ يتعمد إسبال ثيابه ويقول: ما قصدتُ الخيلاء! هذا غلطٌ، القلوب إلى الله، الله الذي يعلم ما في القلوب، وإنما علينا الإنكار عليك فيما فعلتَ من الإسبال، أما قلبك فإلى الله .","link":"https://binbaz.org.sa/fatwas/21007/حكم-الاسبال-وحكم-وضوء-وصلاة-المسبل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0804ما صحة حديث بينما رجل يصلي أسبل إزاره قال له رسول الله صلى الله عليه وسلم أذهب وتوضأ؟ابن باز.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":993,"question":"أنا شابٌّ متزوج، ويجيئني دائمًا وسواس بالطلاق، علمًا بأني لم أجهر بشيءٍ من ذلك، فما حكم هذا؟","title":"حكم من تأتيه وساوس الطلاق دون جهر بها","answer":"الجواب: هذا يقع لكثيرٍ من الناس من الشيطان، والوسوسة فيما بينه وبين نفسه أنه يُطلق زوجته، وأنه يقول: طأ، طأ، طأ، طالق، طا، فيما بينهم، كعمل المجنون والمخبول، وما دام بهذه الوسوسة لا يقع شيءٌ حتى يعزم عزمًا صادقًا عن قصدٍ وعن نيةٍ، حتى يقول: طالق، أو فلانة طالق، أو امرأتي طالق. أما ما دام من طريق الوسوسة فهذا ليس بشيءٍ، ولا عمل عليه، بل هو مُصابٌ بمرضٍ خطيرٍ، فينبغي له العلاج، وينبغي له الإقبال على ذكر الله، والتَّعوذ بالله من الشيطان، والحذر من هذه الوساوس، لعله ينجو من شرِّها.","link":"https://binbaz.org.sa/fatwas/21043/حكم-من-تاتيه-وساوس-الطلاق-دون-جهر-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من تأتيه وساوس الطلاق دون جهر بها.mp3","categories":["الطلاق"]},{"id":1022,"question":"هل من كلمةٍ ترونها توجيهًا بمناسبة الحديث عن الطلاق، ومع كثرة الأسئلة عن الطلاق والتَّساهل بها مع الأسف الشديد، وكثرة إطلاق ألفاظ التحريم؟","title":"ما النصيحة لمن يتساهل في مسائل الطلاق؟","answer":"الجواب: نعم، نعم، نُوجِّه إخواننا بأن يتَّقوا الله، ويحذروا أسبابَ الطلاق: من الغضب، والخصومات، والمنازعات، وإذا غضب فليستعذ بالله من الشيطان، ولا يعجل في الطلاق، لا يعجل، ولو غاضبته فليكن أحلم منها، وأقوى منها، وأكمل إيمانًا، وأكمل تقوى، ليصبر، وليتحمّل، ولا يعجل في الطلاق، فإذا عزم على الطلاق ورأى المصلحة فيُطلِّق طلقةً واحدةً فقط في حال طهرٍ ما جامعها فيه، أو في حال حملها، هذا هو حال الطلاق، حالان: إما في حال الحمل، وإما في حال طهرٍ لم يُجامعها فيه.\nولا يُطلِّق في غير هذين الحالين، لا يُطلِّق في الحيض، ولا في النفاس، ولا في طهرٍ جامعها فيه، لا يُطلِّق في هذه الأحوال الثلاثة، ولكن يُطلِّق في حالين: أحدهما: أن تكون حاملًا فلا بأس بطلاقه؛ لقول النبي عليه الصلاة والسلام لابن عمر: طلِّقها طاهرًا أو حاملًا، أو في حال طهرٍ لم يُجامعها فيه، بعد طُهرها من الحيض، أو من النفاس، إذا عزم على الطلاق يُطلِّقها في الحال قبل أن يمسَّها -قبل أن يُجامعها- طلقةً واحدةً فقط، قال الله تعالى: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1]، قال العلماء في تفسيرها: طلاقهنَّ للعدَّة أن يُطلَّقن طاهرات من غير جماعٍ، هذا هو طلاق العدَّة، طاهرات من غير جماعٍ، أو في حال الحمل، هذا طلاقهنَّ للعدَّة.\nولا يُطلِّق بالثلاث، لا يجوز أن يُطلِّق بالثلاث، لا مجموعة، ولا مُفرَّقةً، ولكن يُطلِّقها واحدةً فقط إذا عزم، طلقة واحدة حتى تكون لها الرجعة، حتى لا يسدّ الباب.","link":"https://binbaz.org.sa/fatwas/21068/ما-النصيحة-لمن-يتساهل-في-مساىل-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0864كلمة موجة للذي يتساهل في مسائل الطلاق؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطلاق"]},{"id":1069,"question":"ما صحَّة الحديث الذي قال فيه رسولُ الله ﷺ: مَن استطاع منكم أن يموت بالمدينة فليَمُتْ فيها؛ فإني أشفع لمَن مات بها؟","title":"هل صحت أحاديث في فضل الموت بالمدينة؟","answer":"الجواب:\nالأحاديث صحيحة في هذا الباب: يقول ﷺ: مَن صبر على لأوائها وشدَّتها كنتُ له شفيعًا –أو: شهيدًا- يوم القيامة، فمَن صبر على لأوائها واستقام على دين الله فهذا من أسباب أن يكون النبيُّ ﷺ شهيدًا وشفيعًا له، بهذه الشريطة: الصبر على لأوائها وشدَّتها، مع الاستقامة على طاعة الله، روى بعضَها مسلمٌ.","link":"https://binbaz.org.sa/fatwas/21113/هل-صحت-احاديث-في-فضل-الموت-بالمدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0909ما صحة حديث من استطاع منكم أن يمت بالمدينة فليمت بها فإني أشفع من مات بها؟ ابن باز.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1101,"question":"سمعتُ من أحد المشايخ حديثًا عن رسول الله ﷺ يقول: مَن تعلَّم لغةَ الأعاجم فقد خب أي: نافق، فهل هذا الحديث صحيحٌ؟ وإذا كان صحيحًا فما حكم السفر إلى بلاد الكفر لتعلم اللغة الإنجليزية؟ أفيدونا حفظكم الله.","title":"درجة حديث \"من تعلم لغة الأعاجم فقد خَب\"","answer":"الجواب:\nهذا لا أصلَ له، مَن تعلَّم لغة الأعاجم فقد خب أو: فقد هلك هذا غلطٌ، ما له أصلٌ، وهكذا ما شاع على ألسنة الناس: \"مَن تعلَّم لغة قومٍ أَمِن مكرهم\" ليس بحديثٍ. لكن يجوز تعلم لغة القوم إذا كانت فيها مصلحة: إنجليزية أو فرنسية أو غير ذلك، إذا كان لها حاجة: مصلحة دنيوية، أو دينية، لا بأس بتعلّمها للمصلحة، لا للرغبة فيها، ولكن لمصلحةٍ: ليتوظَّف بها، ليعمل في التِّجارة، يحتاجها في التجارة، إذا تعلَّمها على وجهٍ لا يضرّه في دينه، ولا يُسبب له مضرَّة في دينه؛ فلا بأس بذلك عند الحاجة، وقد أمر النبيُّ ﷺ زيدَ بن ثابت أن يتعلم لغةَ اليهود للحاجة إلى ذلك.","link":"https://binbaz.org.sa/fatwas/21150/درجة-حديث-من-تعلم-لغة-الاعاجم-فقد-خب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0946ما صحة حديث من تعلم لغة الأعاجم فقد خبَّأ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1124,"question":"قلتُ لزوجتي: إذا فعلتِ هذا الخطأ سوف أُطلقك، وقلتُ هذا الكلام مرتين، وأنا في حالة غضبٍ، أفيدونا جزاكم الله خيرًا، ماذا يترتب عليَّ؟","title":"حكم من تكلم بطلاق امرأته في حالة غضب","answer":"الجواب:\nليس هذا بطلاقٍ، هذا وعيدٌ، إذا قال الرجلُ لزوجته: إذا فعلتِ هذا سوف أُطلقك، أو طلقتُك، أو فإني أُطلقك، هذا ليس بطلاقٍ، هذا وعيدٌ، فإن شاء طلَّق، وإن شاء لم يُطلِّق.\n\"إذا فعلتِ\" بخلاف إذا قال: \"إن فعلتِ فأنت طالق\":  \"إن فعلتِ هذا فأنت طالق\": هذا تعليقٌ للطلاق، إذا قصد إيقاع الطلاق يقع الطلاق، وإن قصد تخويفها ومنعها وما قصد إيقاع الطلاق، لكن أراد أن يُخوفها ويُهددها؛ فهذا حكمه حكم اليمين على الصحيح، ولا يقع به الطلاق، وعليه كفَّارة يمين.\nإن قال: \"إن كلَّمْتِ فلانًا..\" أو: \"إن خرجتِ بغير إذني فأنت طالق\"، يقصد وعيدها وتخويفها وتهديدها وتحذيرها، ولا يقصد إيقاع الطلاق؛ هذا حكمه حكم اليمين، عليه كفَّارة يمين إذا خالفت يمينه.\nأما إذا قصد إيقاع الطلاق فإنه يقع الطلاق إذا خالفته: إذا خرجت، أو كلَّمَتْ؛ يقع الطلاق الذي عُلِّق على خروجها أو كلامها، أما إذا قال: سوف أُطلقك، أو: سأُطلقك، فهذا وعيدٌ، ولا يقع به شيءٌ.","link":"https://binbaz.org.sa/fatwas/21180/حكم-من-تكلم-بطلاق-امراته-في-حالة-غضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0976قلت لوزجتي إذا فعلتي هذا الخطأ سوف أطلقك وقلت هذا الكلام مرتين وأنا في حالة غضب فما الحكم؟.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":1158,"question":"قرأتُ في بعض الكتب هذا الحديثَ، فكيف يكون من حيث الصحة والعمل به؟ والحديث هو: مَن صلَّى عليَّ في يومٍ ألف مرةٍ لم يمت حتى يرى مقعدَه من الجنة أخرجه ابن غازي، وإسناده لا بأس به، أخرجه ابن شاهين، وابن بشكوال؟","title":"درجة حديث \"مَن صلَّى عليَّ في يومٍ ألف..\"","answer":"الجواب:\nلا أعرف له أصلًا، وهذه الكتب تروي الغثَّ والسَّمين، والموضوع والصحيح، ما يُعتمد عليها، لكن إذا كانت النسخةُ المخطوطة موثوقةً، والسند صحيحًا؛ فلا يُستنكر، الصلاة على النبي من أفضل القربات، ولو أقلّ من ألفٍ، ولو واحدة: مَن صلَّى عليَّ واحدةً صلَّى الله عليه بها عشرًا. والصلاة عليه من أسباب حياة القلوب، ومن أسباب السَّعادة في الدنيا والآخرة، لكن نفس هذا اللَّفظ لا أعلم له أصلًا، ولا أظنُّه إلا موضوعًا.","link":"https://binbaz.org.sa/fatwas/21205/درجة-حديث-من-صلى-علي-في-يوم-الف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1001فضل الصلاة على النبي صلى الله عليه وسلم ؟ ابن باز.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1203,"question":"إني أحبُّك في الله، ما صحَّة هذه الأحاديث: قوله ﷺ: مَن قرأ قُلْ هُوَ اللَّهُ أَحَدٌ إحدى عشرة مرةً بُني له بيتٌ في الجنة؟","title":"ما صحة قراءة الإخلاص إحدى عشرة مرة؟","answer":"الجواب:\nالشيخ: أولًا: أحبَّك الله الذي أحببتنا له، نسأل الله أن يجعلنا وإيَّاكم من المتحابين بجلاله.  أما هذا الحديث فلا أعرف صحَّته، لا أصل له فيما نعلم، لكن قُلْ هُوَ اللَّهُ أَحَدٌ لها فضلٌ عظيمٌ، تعدل ثلث القرآن، فهي سورة عظيمة، فالإكثار من قراءتها طيب، أما هذا الحديث: مَن قرأها إحدى عشرة مرة بُني له بيتٌ في الجنة فلا أعلم له أصلًا.","link":"https://binbaz.org.sa/fatwas/21266/ما-صحة-قراءة-الاخلاص-احدى-عشرة-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1128ما صحة حديث من قرأ قل هو الله أحد أحدى عشرة مرة بنى له بيتاًفي الجنة؟ ابن باز.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1204,"question":"وفيما معناه: قال ﷺ: مَن صلَّى عليَّ عشر مراتٍ حين يُصبح أو يُمسي بلغته شفاعتي يوم القيامة؟","title":"درجة حديث \"من صلّى علي عشر مرات..\"؟","answer":"الجواب:\nما أعرف صحَّته، ولكن الصلاة على النبي ﷺ فيها خيرٌ عظيمٌ، ولو مرةً واحدةً، يقول النبي ﷺ: مَن قال حين يسمع النِّداء: اللهم ربَّ هذه الدَّعوة التامَّة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدتَه؛ حلَّت له شفاعتي يوم القيامة مرة واحدة، وقال عليه الصلاة والسلام: إذا سمعتُم المؤذنَ فقولوا مثلما يقول، ثم صلُّوا عليَّ، فإنه مَن صلَّى عليَّ واحدةً صلَّى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلةٌ في الجنة لا تنبغي إلا لعبدٍ من عباد الله، وأرجو أن أكون أنا هو، فمَن سأل الله لي الوسيلة حلَّت له الشَّفاعة، فالصلاة على النبي من أسباب حلول شفاعته عليه الصلاة والسلام، في أي وقتٍ، وإذا صلَّى عليه الإنسانُ بعد الأذان ثم سأل الله له الوسيلة حلَّت له الشَّفاعة.","link":"https://binbaz.org.sa/fatwas/21265/درجة-حديث-من-صلى-علي-عشر-مرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1129ماصحة حديث من صلى عليَّ عشر مرات حين يصبح وحين يمسي بلغته شفاعتي؟.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1329,"question":"حديث: كفارة من اغتبته أن تستغفر له؟","title":"درجة حديث \"كفارة من اغتبته أن تستغفر له\"","answer":"الجواب:\nحديث ضعيف، لكن المعنى: إذا تيسر، أو إذا تيسر أنه يستبيحه، وإلا يدعو له ويستغفر له في ظهر الغيب، ويذكِّره بالأعمال الطيبة التي يعرفها منه في المجالس التي اغتابه فيها ويذكر صفاته الطيبة التي يعرفها منه، تكون هذه بهذه.","link":"https://binbaz.org.sa/fatwas/21420/درجة-حديث-كفارة-من-اغتبته-ان-تستغفر-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث كفارة من اغتبته أن تستغفر له.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1396,"question":"من يقول أن في حديث ورد بلفظ: \"اعمل لدنياك كأنك تعيش أبدًا\"؟","title":"ما صحة قول: اعمل لدنياك كأنك تعيش أبدًا؟","answer":"الجواب:\nهذا يُروى عن علي، لو صح ما يخالف هذا، \"اعمل لآخرتك كأنك تموت غدًا واعمل لدنياك كأنك تعيش أبدًا\" هذا من كلام بعض السلف، وما هو على إطلاقه.\nس: والمعنى الصحيح؟\nج: المعنى إذا لم يخالف الشرع. ما هو بيقول باخلي عيالي وما أنا بمتجّر أخاف أموت باكرً! لا، اتَّجِر وأعمل ولا تقل أموت باكرًا، بس استعد للآخرة كأنك تموت باكرًا، واعمل للدنيا كأنك تعيش سنتين أو مائة سنة، الحمد لله.","link":"https://binbaz.org.sa/fatwas/21489/ما-صحة-قول-اعمل-لدنياك-كانك-تعيش-ابدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث اعمل لدنياك كأنك تعيش أبدًا.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1453,"question":"حديث النبي ﷺ: صلاةٌ بسواكٍ خيرٌ من سبعين صلاةً بدون سواك؟","title":"درجة حديث \"صلاةٌ بسواكٍ خيرٌ من سبعين\"","answer":"الجواب:\nفيه نظر، يحتاج إلى مراجعة أسانيده، ذكره ابنُ القيم رحمه الله وغيرُه، ويحتاج إلى مراجعة أسانيده، والسواك سُنَّةٌ على كل حال.","link":"https://binbaz.org.sa/fatwas/21550/درجة-حديث-صلاة-بسواك-خير-من-سبعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث صلاةٌ بسواكٍ خيرٌ من سبعين صلاةً بدون سواك.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1454,"question":"كثير من الشباب يُطلِّق زوجته بعد زواجه بفترةٍ وجيزةٍ، ويقول: لا أحبها، أو: لا أحب لونها، هل هذا يكون من الظلم إن لم يكن هناك سببٌ مُقْنِعٌ؟","title":"هل مِن الظلم الطلاق دون سبب مُقْنع؟","answer":"الجواب:\nيَحْرُم عليه الغِيبة، هذا من الغِيبة، يدعو لها بالستر والعافية. أما إذا استشاره أحدٌ يريد الزواج منها فيُشير عليه بما يعلم؛ لأنه نُصْح.\nس: يكون معها شهرًا أو شهرين أو ثلاثة أو سنةً ثم يقول: لا أُحبُّها، أُريد أن أُطَلِّقها، هل يكون ظالمًا في تطليقه لها أم لا؟\nج: هذا يرجع إلى حاله وإياها، إن كان يرى المصلحة طلَّقها، فهذا يتعلق بمصلحته.\nس: تأكيدًا لكلامه يقول: هي متعلِّقةٌ بي؟\nج: ولو، ينظر إلى المصلحة، إن كان في بقائها مصلحةٌ أبقاها، وإن كانت المصلحة له في طلاقها طلَّقها، هو أعلم بنفسه، وهو أعلم بحاله معها.","link":"https://binbaz.org.sa/fatwas/21551/هل-من-الظلم-الطلاق-دون-سبب-مقنع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الطلاق.mp3","categories":["الطلاق"]},{"id":1461,"question":"إن الحمد لله، نحمده، ونستغفره، ونستهديه، هل ورد في خطبة الحاجة؟","title":"هل وردت لفظة \"نستهديه\" في خطبة الحاجة؟","answer":"الجواب:\nنطلب منه الهداية.\nس: \"نستهديه\" هل وردت في خطبة الحاجة عن النبي ﷺ؟\nج: أظن أنه في بعض الروايات، ولكن يحتاج إلى مراجعة حديث ابن مسعودٍ وما جاء في معناه، يُراجع الحديث.","link":"https://binbaz.org.sa/fatwas/21558/هل-وردت-لفظة-نستهديه-في-خطبة-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل وردت لفظة نستهديه في خطبة الحاجة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1465,"question":"أكثر موت أمتي بعد قضاء الله وقدره من العين ما درجة صحته؟","title":"درجة حديث \"أكثر موت أمتي.. من العين\"","answer":"الجواب:\nما أعرفه.","link":"https://binbaz.org.sa/fatwas/21562/درجة-حديث-اكثر-موت-امتي-من-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما درجة حديث أكثر موت أمتي بعد قضاء الله وقدره من العين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1473,"question":"حديث: مَنْ بَدا فقد جَفا صحيح؟","title":"ما صحة حديث \"مَنْ بَدا فقد جَفا\"؟","answer":"الجواب:\nما أذكر حاله، ويغلب على ظني أنه لا بأس به، لكني بعيد العهد بسنده.\nس: لكن هل معناه صحيح؟\nج: من أسباب الجفاء، فالنبي ﷺ نهى عن التَّعرب بعد الهجرة، لكن إذا دعت الحاجةُ فلا بأس، يقول النبي ﷺ في الحديث الصحيح لما سُئل: أي الناس أفضل؟ قال: مؤمن مجاهد في سبيل الله، قيل: ثم أي؟ قال: مؤمنٌ في شعب من الشِّعاب يعبد الله ويدع الناسَ من شره، هذا حمله العلماء عند الفتن، وعند وجود الشر في المدن والقرى.\nس: إلى وقتنا هذا؟\nج: لا، ما هو على كل حالٍ، فهناك محلات يمكن أن يعبد فيها ربَّه، ولا يحتاج إلى البادية.","link":"https://binbaz.org.sa/fatwas/21571/ما-صحة-حديث-من-بدا-فقد-جفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث من بدا فقد جفا صحيح.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1482,"question":"حديث: إذا رأيتم الرجلَ يعتاد المساجدَ فاشهدوا له بالإيمان؟","title":"درجة حديث \"إذا رأيتم الرجلَ يعتاد المساجدَ\"","answer":"الجواب:\nفيه بعض الضعف، حديث أبي سعيدٍ فيه بعض الضعف. ولكن على كل حالٍ الاستقامة على الصلاة من علامات الخير.","link":"https://binbaz.org.sa/fatwas/21580/درجة-حديث-اذا-رايتم-الرجل-يعتاد-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث ذا رأيتم الرجلَ يعتاد المساجدَ فاشهدوا له بالإيمان.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1505,"question":"هل يجوز للرجل أن يُطلق امرأته لطُهْرٍ جامعها فيه؟","title":"هل يجوز للرجل الطلاق في طُهْرٍ جامع فيه؟","answer":"الجواب:\nلا، ما يجوز، إذا لم تكن آيسةً وتأتيها العادة الشهرية. أما إذا كانت آيسةً -عجوز كبيرة أو حامل- فلا بأس أن يُطلقها في الطهر. أما إذا كانت تأتيها العادة ويخشى أن تحمل فلا يُطلق حتى يعرف أنها حملت أو حاضت ثم طهرت، ثم يطلق قبل أن يطأ، هكذا أمر النبيُّ ﷺ ابنَ عمر.","link":"https://binbaz.org.sa/fatwas/21604/هل-يجوز-للرجل-الطلاق-في-طهر-جامع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الطلاق البدعي ومتى يكون.mp3","categories":["الطلاق"]},{"id":1508,"question":"حديث: إنَّما الدنيا لأربعة: رجل آتاه الله مالًا وعلمًا، فهو يتَّقي الله في ماله، ويعرف الله في حقّه، فهو في أحبِّ المنازل إلى الله... صحيح؟","title":"ما صحة حديث \"إنَّما الدنيا لأربعة..\"؟","answer":"الجواب:\nصحيح، وإذا صار مع العمل الصالح فهو أفضل.","link":"https://binbaz.org.sa/fatwas/21607/ما-صحة-حديث-انما-الدنيا-لاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إنَّما الدنيا لأربعة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1510,"question":"معلم يسأل عن حديث: رضا الله في رضا الوالدين، وسخط الله في سخط الوالدين؟","title":"ما صحة حديث \"رضا الله في رضا الوالدين\"؟","answer":"الجواب:\nلا بأس به، رواه ابن حبان وجماعة، وصححه.","link":"https://binbaz.org.sa/fatwas/21609/ما-صحة-حديث-رضا-الله-في-رضا-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث رضا الله في رضا الوالدين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1519,"question":"معلمة تسأل وتقول: سمعتُ أحد الدعاة في شريطٍ يقول أنَّ النبي ﷺ يقول: رحم الله المُتَسَرْوِلات من النساء؟","title":"ما صحة حديث \"رحم الله المُتَسَرْوِلات..\"؟","answer":"الجواب:\nالتَّسرول ما فيه بأس، السروال لا بأس به، لبسه الصحابة، ولبسه الأخيار، ولا بأس به، ويلبسه النساء، والإزار والسروال كله جائز، والحديث لا أصلَ له.","link":"https://binbaz.org.sa/fatwas/21618/ما-صحة-حديث-رحم-الله-المتسرولات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث رحم الله المُتسرولات من النساء.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1535,"question":"صحة حديث: اللهم إني أُحَرِّج حقَّ الضعيفين (اليتيمِ والمرأَةِ)؟","title":"درجة حديث \"اللهم إني أُحَرِّج حقَّ الضعيفين\"","answer":"الجواب:\nما تتبعته، لكن الظاهر أنه صحيح، فيما مضى من علمي به أنه لا بأس به.","link":"https://binbaz.org.sa/fatwas/21635/درجة-حديث-اللهم-اني-احرج-حق-الضعيفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث اللهم إني أحرج حقَّ الضعيفين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1543,"question":"سماحة الوالد، الأحاديث في الحثِّ على تعلم الفرائض؟","title":"درجة الأحاديث التي تحث على تعلم الفرائض","answer":"الجواب:\nفيها ضعف، لكن تعلم الفرائض من أهم العلوم، أحاديث تعلم الفرائض فيها ضعف، حديث: العلم ثلاثة: آية محكمة، وسنة قائمة، وفريضة عادلة. والرسول ﷺ علمه الأمة في القرآن، وبيَّن لهم حكم الفرائض.\nفتعلم الفرائض من أعظم العلوم النافعة، من أعظم علوم الإسلام، يقول ﷺ: مَن سلك طريقًا يلتمس فيه علمًا سهَّل الله له به طريقًا إلى الجنة، فعلم الفرائض من أعظم العلوم النافعة، من علوم الإسلام النافعة التي يحتاجها الناس كلهم، والأحاديث الضعيفة تتقوى بالأحاديث الصَّحيحة.","link":"https://binbaz.org.sa/fatwas/21643/درجة-الاحاديث-التي-تحث-على-تعلم-الفراىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأحاديث التي فيها الحث على تعلم الفرائض.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1548,"question":"صحة حديث: لا يُسأل الرجلُ فِيمَ ضرب امرأتَه؟","title":"هل صح \"لا يُسأل الرجلُ فِيمَ ضرب امرأته\"؟","answer":"الجواب:\nفيه نظر، ولو صحَّ فيكون المقصود الناس الآخرين، أما إذا دعت الحاجة فالحاكم يسأل، لكن الإنسان الآخر لا يدخل في الأمور هذه.","link":"https://binbaz.org.sa/fatwas/21649/هل-صح-لا-يسال-الرجل-فيم-ضرب-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث لا يسأل الرجل فيم ضرب امرأته.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1559,"question":"يقول: حدثنا هناد، أخبرنا ملازم بن عمرو، وحدثني عبدالله بن بدر، عن قيس بن طلق، عن أبيه طلق بن علي .. الحديث (إِذَا دَعَا الرَّجُلُ زَوْجتَهُ لِحَاجتِهِ فَلْتَأْتِهِ وإِنْ كَانَتْ عَلَى التَّنُّور)؟","title":"درجة حديث \"إذا دعا امرأتَه فلتأته وإنْ..\"","answer":"الجواب:\nالسند جيد.","link":"https://binbaz.org.sa/fatwas/21661/درجة-حديث-اذا-دعا-امراته-فلتاته-وان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث إذا دعا امرأتَه فلتأته وإن كانت على التنور.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1562,"question":"(حديث) لو كنتُ آمرًا أحدًا أن يسجد لأحدٍ لأمرتُ المرأة أن تسجد لزوجها يقول: حدثنا محمود بن غيلان، أخبرنا النضر بن شميل، أخبرنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة  .. الحديث رواه الترمذي..؟","title":"درجة حديث \"لو كنتُ آمرًا أحدًا أن يسجد..\"","answer":"الجواب:\nجيد، لا بأس به، سنده جيد.","link":"https://binbaz.org.sa/fatwas/21664/درجة-حديث-لو-كنت-امرا-احدا-ان-يسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/درجة حديث لو كنت آمرا أحدا أن يسجد لأحد لأمرت المرأة أن تسجد لزوجها.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1564,"question":"الحديث الوارد في \"سنن النسائي\": أحسن ما غيَّرتم به الشَّيب الحناء والكتم ما درجة الحديث؟","title":"درجة حديث \"أحسن ما غيَّرتم به الشَّيب..\"","answer":"الجواب:\nلا بأس به، الأفضل تغيير الشيب بالحناء والكتم، الحناء أحمر، والكتم سواد، فإذا اختلطا صار بين السواد والحمرة.\nس: يعني هو أفضل من الحناء؟\nج: أفضل من الحناء المجرد.","link":"https://binbaz.org.sa/fatwas/21666/درجة-حديث-احسن-ما-غيرتم-به-الشيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/درجة حديث أحسن ما غيَّرتم به الشَّيب الحناء والكتم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1566,"question":"إذا خلعت زوجَها كيف تكون عدَّتُها؟","title":"ما عدة من خالعت زوجها؟","answer":"الجواب:\nوَضْع الحمل، عدتها وَضْع الحمل، جميع المطلقات وجميع المتوفى عنهنَّ والمخلوعات كلهن إذا كُنَّ حُمَّلًا: وَضْع الحمل: وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4]، الطلاق والخلع والموت جميعًا.\nس: مدة النفاس ما تدخل في العدة؟\nج: لا، ما تدخل، إذا وضعت حملها اليوم؛ حلَّتْ للزوج الجديد، ولو كانت في النفاس.\nس: وإذا كان الحملُ أبْعَدُ الأجلين؟\nج: ولو أبْعَدُ الأجلين، عدتها وَضْعُ الحمل مطلقًا.","link":"https://binbaz.org.sa/fatwas/21669/ما-عدة-من-خالعت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عدة من خالعت زوجها.mp3","categories":["الطلاق","العِدَد","الخلع"]},{"id":1597,"question":"سند الحديث معي، يقول: حدثنا أحمد بن محمد، حدثنا عبدالله بن المبارك، عن حيوة بن شريح، عن شرحبيل بن شريك، عن أبي عبدالرحمن الحبلي، عن عبدالله بن عمرو قال: قال رسول الله ﷺ: خير الأصحاب عند الله خيرهم لصاحبه، وخير الجيران عند الله خيرهم لجاره، قال أبو عيسى: هذا حديثٌ حسنٌ غريبٌ، وأبو عبدالرحمن الحبلي اسمه عبدالله بن يزيد؟","title":"درجة حديث \"خير الأصحاب عند الله..\"","answer":"الجواب:\nأبو عبدالرحمن الحبلي ثقة، لكن في إسناده شرحبيل بن شريك، وهو محل نظر.\nالطالب: رواه الدارمي والإمام أحمد كذلك.\nالشيخ: الحاشية؟\nالطالب: نعم، قال الشيخ شعيب الأرناؤوط: وإسناده صحيح، وصححه الحاكم، ووافقه الذهبي.\nالشيخ: على حاشية \"رياض الصالحين\"؟\nالطالب: نعم.\nالشيخ: أيش قال عن شرحبيل بن شريك؟\nالطالب: شرحبيل بن شريك كذا ذكره صاحب \"الكمال\"، صوابه: شريك بن حنبل، أبو داود والترمذي، وغيره: شرحبيل بن شريك المعافري، أبو محمد، المصري، ويقال: شرحبيل بن عمرو بن شريك، صدوق، من السادسة. (البخاري في \"الأدب المفرد\"، ومسلم، وأبو داود، والترمذي، والنسائي).\nالشيخ: مثلما قال، لا بأس به، جيد.","link":"https://binbaz.org.sa/fatwas/21701/درجة-حديث-خير-الاصحاب-عند-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث خير الأصحاب عند الله خيرهم لصاحبه.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1623,"question":"الحديث الذي أخرجه الإمامُ أحمد وغيره: ليس الخبرُ كالمُعاينة ما درجته؟","title":"ما صحة حديث \"ليس الخبرُ كالمُعاينة\"؟","answer":"الجواب:\nما أتذكر حاله، لكن غالب ظني أنه لا بأس بإسناده: ليس الخبرُ كالعيَان، وهذا معروفٌ، لكن الجزم بسنده ما أعرف حاله، غالب ظني أنه لا بأس به.","link":"https://binbaz.org.sa/fatwas/21728/ما-صحة-حديث-ليس-الخبر-كالمعاينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث ليس الخبرُ كالمُعاينة ما درجته.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1639,"question":"حدثنا ابن أبي عمر، حدثنا سفيان، عن عطاء بن السَّائب، عن أبي عبدالرحمن السُّلمي، عن أبي الدرداء قال: إنَّ رجلًا أتاه فقال: إنَّ لي امرأةً، وإنَّ أمي تأمُرني بطلاقها، فقال أبو الدرداء: سمعتُ رسول الله ﷺ يقول: الوالد أوسط أبواب الجنة، فإن شئتَ فأضع ذلك البابَ أو احفظه..؟","title":"ما صحة حديث \"الوالد أوسط أبواب الجنة\"؟","answer":"الجواب:\nسنده جيد؛ لأنَّ عطاء بن السائب اختلط، لكن سفيان سمع قبل الاختلاط.","link":"https://binbaz.org.sa/fatwas/21744/ما-صحة-حديث-الوالد-اوسط-ابواب-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث الوالد أوسط أبواب الجنة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1647,"question":"حديث أبي أُسيد (هل بقي من بر أبوي شيء أبرهما به بعد موتهما..) ذكر بعضُ المُحَشِّين أنه يدور على علي بن عبيد الساعدي، ولم يُوثِّقْه ابنُ حبان؟","title":"درجة حديث \"هل بقي من بر أبوي شيء..\"؟","answer":"الجواب:\nالذي أعرفه أنه صحيح.\nطالب: معي سند الحديث.\nج: حديث أبي أسيد؟\nالطالب: نعم، يقول: حدثنا إبراهيم بن مهدي، وعثمان ابن أبي شيبة، ومحمد بن العلاء، المعنى، قالوا: حدثنا عبدالله بن إدريس، عن عبدالرحمن بن سليمان، عن أسيد بن علي بن عبيد مولى بني ساعدة، عن أبيه، عن أبي أسيد مالك بن ربيعة الساعدي  قَالَ: بَيْنا نَحْنُ عِنْدَ رَسُول اللَّهِ ﷺ.....\nج: السند يحتاج إلى تأمُّلٍ، لكن المعروف أنه لا بأس به.","link":"https://binbaz.org.sa/fatwas/21752/درجة-حديث-هل-بقي-من-بر-ابوي-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث هل بقي من بر أبوي شيء أبرهما به بعد موتهما.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1657,"question":"حدثنا محمد بن المثنى، أخبرنا يزيد بن بيان العُقيلي، حدثني أبو الرحال الأنصاري، عن أنس بن مالك قال: قال رسولُ الله ﷺ: ما أكرم شابٌّ شيخًا لسِنِّه إلا قيَّض الله له مَن يُكرمه عند سِنِّه، هذا حديثٌ غريبٌ لا نعرفه إلا من حديث هذا الشيخ يزيد بن بيان، وأبو الرحال الأنصاري آخر، وفي \"الجامع الصحيح\" يقول: وأبو الرجال. انتهى كلامه.","title":"ما صحة حديث \"ما أكرم شابٌّ شيخًا لسِنِّه..\"؟","answer":"الجواب:\nج: أيش قال عن الشيخين: يزيد وأبي الرحال، أو أبي الرجال؟\nالطالب: في \"تحفة الأحوذي\" يقول: أخبرنا يزيد بن بيان العقيلي بالضم، أبو خالد البصري، ضعيف من التاسعة. وقال في \"تهذيب التهذيب\": يزيد بن بيان العقيلي أبو خالد البصري المعلم الضَّرير المؤذن، روى عن أبي الرحال الأنصاري عن أنسٍ حديث: ما أكرم شابٌّ شيخًا لسِنِّه... الحديث. حدثني أبو الرحال الأنصاري -بفتح الراء وتشديد الحاء المهملة- البصري، اسمه محمد بن خالد، وقيل: خالد بن محمد، اعلم أنَّ كون أبي الرحال -بفتح الراء وتشديد الحاء المهملة- هو الصواب في هذا السند. وأما قول الترمذي في آخر هذا الباب: \"وأبو الرجال الأنصاري آخر\"، فهو بكسر الراء وتخفيف الجيم، فاحفظ هذا، وقد وقع في النسخة الأحمدية في هذا السند: أبو الرجال بكسر الراء وتخفيف الجيم، قال في هامشها: قوله: أبو الرجال بالجيم، وفي آخر الباب بالحاء هذا ما وجدتُه في الكتب الدّهلوية، وفي نسخة صحيحة منقولة من العرب عكسه، وعليهما فيه علامة الصحة. قلت: ما في النسخة الصَّحيحة المنقولة من العرب من كون أبي الرحال بالحاء المهملة في هذا السند، وكون أبي الرجال بالجيم في آخر الباب: هو الصواب؛ لما عرفت آنفًا في عبارة \"تهذيب التهذيب\" من أن يزيد بن بيان العقيلي روى حديثَ الباب عن أبي الرحال؛ ولأن الحافظ رمز على أبي الرحال -بفتح الراء وتشديد الحاء المهملة- بحرف تاء، ورمز على أبي الرجال -بكسر الراء وتخفيف الجيم- بحروف \"خ. م. س. ق\"؛ ولأنَّ الحافظ قال في ترجمة أبي الرحال بالحاء المهملة: \"روى عن أنسٍ وغيره، وعنه يزيد بن بيان العقيلي وغيره\"، فهذه الوجوه الثلاثة تدل بمجموعها على أنَّ في هذا السند أبا الرحال بالحاء المهملة، دون أبي الرجال بالجيم، وأبو الرحال -بفتح الراء وتشديد الحاء المهملة- الأنصاري البصري اسمه محمد بن خالد، وقيل: خالد بن محمد، ضعيف من الخامسة، وأما أبو الرجال فقال.....\nج: المقصود أنَّ فيه ضعيفين: يزيد وأبا الرحال، كلاهما ضعيف؛ ولهذا قال الترمذي رحمه الله: \"غريب\"، لكن شواهده معروفة من أدلةٍ أخرى، فإكرام الشَّاب للشيخ شواهده معروفة.","link":"https://binbaz.org.sa/fatwas/21762/ما-صحة-حديث-ما-اكرم-شاب-شيخا-لسنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث ما أكرم شابٌّ شيخًا لسِنِّه...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1723,"question":"صحة حديث أسماء بنت يزيد (مَرَّ عَلَيْنَا النَّبيُّ ﷺ فِي نِسْوَةٍ فَسَلَّمَ عَلَيْنَا...)؟","title":"درجة حديث \"مَرَّ عَلَيْنَا النَّبيُّﷺفِي نِسْوَةٍ..\"","answer":"الجواب:\nلا أعلم فيه شيئًا، لكنه حديث مشهور معروف.\nس: إسناد الحديث معي، يقول: حدثنا أبو بكر ابن أبي شيبة.\nج: مَن هذا؟\nس: \"عون المعبود\"، حدثنا أبو بكر ابن أبي شيبة، أخبرنا سفيان بن عيينة، عن ابن أبي حسين، سمعه من شهر بن حوشب، يقول: أخبرته أسماء بنت يزيد: مرَّ علينا النبيُّ ﷺ في نسوةٍ فسلَّم علينا.\nج: لا بأس به، شهرٌ إذا حدَّث بالسماع فلا بأس به.","link":"https://binbaz.org.sa/fatwas/21830/درجة-حديث-مر-علينا-النبيﷺفي-نسوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث مَرَّ عَلَيْنَا النَّبيُّ ﷺ فِي نِسْوَةٍ فَسَلَّمَ عَلَيْنَا.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1738,"question":"صحة حديث أنسٍ لما جاء أهلُ اليمن: قد جاءكم أهلُ اليمن، وهم أول مَن جاء بالمصافحة؟","title":"درجة حديث أنس: \"قد جاءكم أهلُ اليمن..\"؟","answer":"الجواب:\nما راجعتُه.\nس: معي إسناد الحديث، يقول: حدثنا موسى بن إسماعيل، أخبرنا حماد، أنبأنا حميد، عن أنس بن مالك قال: لما جاء أهلُ اليمن قال رسولُ الله ﷺ: قد جاءكم أهلُ اليمن، وهم أول مَن جاء بالمُصافحة.\nج: سنده جيد، لا بأس به.","link":"https://binbaz.org.sa/fatwas/21845/درجة-حديث-انس-قد-جاءكم-اهل-اليمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث قد جاءكم أهلُ اليمن..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1739,"question":"سند حديث البراء: يقول: حدثنا أبو بكر ابن أبي شيبة، أخبرنا أبو خالد وابن نمير، عن الأجلح، عن أبي إسحاق، عن البراء قال: قال رسولُ الله ﷺ: ما من مُسْلِمَين يلتقيان فيتصافحان إلا غُفِرَ لهما قبل أن يفترقا.","title":"هل صح \"ما من مُسْلِمَين يلتقيان فيتصافحان\"؟","answer":"الجواب:\nله شواهد، والأرجح أنَّ فيه ضعفًا، لكن له شواهد.","link":"https://binbaz.org.sa/fatwas/21846/هل-صح-ما-من-مسلمين-يلتقيان-فيتصافحان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/درجة حديث ما من مُسْلِمَين يلتقيان فيتصافحان..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1744,"question":"صحة حديث صفوان (قال يهوديٌّ لصاحبه: اذهب بنا إلى هذا النبي.. )؟","title":"ما صحة حديث \"اذهب بنا إلى هذا النبي..\"؟","answer":"الجواب:\nما أعلم فيه بأسًا.\nس: سنده معي: يقول: حدثنا أبو كريب، أخبرنا عبدالله بن إدريس وأبو أسامة، عن شعبة، عن عمرو بن مرة، عن عبدالله بن سلمة، عن صفوان بن عسالٍ قال: قال يهوديٌّ لصاحبه: اذهب بنا إلى هذا النبي..\nج: سندٌ جيدٌ، لا بأس به.","link":"https://binbaz.org.sa/fatwas/21851/ما-صحة-حديث-اذهب-بنا-الى-هذا-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث قال يهوديٌّ لصاحبه اذهب بنا إلى هذا النبي..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1746,"question":"صحة حديث ابن عمر: \"فدنونا من النبي ﷺ فقبَّلنا يده\"؟ إسناد الحديث معي، يقول في \"عون المعبود\".","title":"درجة حديث \"فدنونا من النبيﷺفقبَّلنا يده\"","answer":"الجواب:\nقاعدة المؤلف أنه يتحرَّى الأحاديث الصَّحيحة.\nس: حدثنا أحمد بن يونس، أخبرنا زهير، أخبرنا يزيد بن أبي زياد: أنَّ عبدالرحمن بن أبي ليلى حدَّثه: أن عبدالله بن عمر حدَّثه .. وذكر قصةً، قال: فدنونا –يعني: من النبي ﷺ- فقبَّلنا يده.\nج: يزيد بن أبي زياد فيه بعض اللِّين.","link":"https://binbaz.org.sa/fatwas/21853/درجة-حديث-فدنونا-من-النبيﷺفقبلنا-يده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث فدنونا من النبي ﷺ فقبَّلنا يده.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1753,"question":"حديث ابن عباس الذي ذكرته أمس: ما من مسلمٍ يعود مسلمًا فيقول سبع مرات: أسأل الله العظيم، رب العرش العظيم .. إلى آخره، معي إسناده؟","title":"حكم حديث \"ما من مسلمٍ يعود مسلمًا فيقول..\"","answer":"الجواب:\nنعم.\nس: قال الترمذي: حدثنا محمد بن المثنى، قال: حدثنا محمد بن جعفر، قال: حدثنا شعبة، عن يزيد أبي خالد قال: سمعتُ المنهال بن عمرو يُحدِّث عن سعيد بن جبير، عن ابن عباسٍ قال: قال رسولُ الله ﷺ: ما من مسلمٍ يعود مسلمًا فيقول سبع مرات: أسأل الله العظيم، ربّ العرش العظيم أن يشفيك؛ إلا شُفي، إلا أن يكون قد حضر أجلُه.\nج: هذا الحديث ضعيف؛ لأن يزيد بن خالد هذا -يُقال له: الدَّالاني- يُضَعّف في الحديث، لكن على كل حالٍ هو دعاء طيب، الدعاء للمريض طيب.\nس: مداره على المنهال بن عمرو؟\nج: لا، الذي قبله يزيد بن خالد هو الضعيف، أما المنهال فلا بأس به.","link":"https://binbaz.org.sa/fatwas/21860/حكم-حديث-ما-من-مسلم-يعود-مسلما-فيقول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث ما من مسلمٍ يعود مسلمًا فيقول سبع مرات.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1761,"question":"هناك حديث يُوزَّع في المساجد منسوب إلى مسلم، هل نقرؤه عليك؟","title":"ما صحة حديث \"يا علي، لا تنم قبل خمسة..\"؟","answer":"الجواب:\nنعم.\nس: يقول: بسم الله الرحمن الرحيم، حديثٌ رواه مسلم: قال عليه الصلاة والسلام: يا علي، لا تنم قبل أن تأتي بخمسة أشياء: قراءة القرآن كله، التَّصدق بأربعة آلاف درهم، زيارة الكعبة، حفظ مكانك في الجنة، إرضاء الخصوم، فقال علي: كيف ذلك يا رسول الله؟! فقال عليه الصلاة والسلام: أما علمتَ أنَّك إذا قرأتَ: قُلْ هُوَ اللَّهُ أَحَدٌ ثلاث مرات كأنَّك قرأتَ القرآنَ كله، وإذا قرأتَ الفاتحة أربع مراتٍ كأنَّك تصدَّقتَ بأربعة آلاف درهم، وإذا قلتَ: لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، يُحيي ويميت، وهو حيٌّ دائمٌ لا يموت أبدًا، بيده الخير، وهو على كل شيءٍ قدير، عشر مرات، كأنَّك زرتَ الكعبة، وإذا قلتَ: لا حول ولا قوة إلا بالله العلي العظيم، عشر مرات، كأنَّك حفظتَ مكانك في الجنة، وإذا قلتَ: أستغفر الله العظيم الذي لا إله إلا هو، الحي القيوم، وأتوب إليه، مرةً واحدةً، كأنَّك أصلحتَ الخصوم، فقال الإمام عليّ: صدقتَ يا رسول الله. فهنيئًا لمَن قرأ هذا الحديثَ وعمل به.\nج: هذا كذبٌ موضوعٌ، كله كذب، هذا من وضع الشيعة، لكن الإكثار من ذكر الله مطلوب، فينبغي للإنسان أن يُكثِر من ذكر الله دائمًا: وَاذْكُرُوا اللَّهَ كَثِيرًا [الجمعة:10]، وكان النبي يذكر الله كثيرًا ويقول: لأن أقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، أحبّ إليّ مما طلعت عليه الشمس عليه الصلاة والسلام، ويقول: أحبّ الكلام إلى الله أربع: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ويقول: الباقيات الصَّالحات: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله.\nفالإنسان يُكثر من ذكر الله: في سفره، في إقامته، في الطريق، في البيت، وخبر عليٍّ هذا ما حصل.","link":"https://binbaz.org.sa/fatwas/21868/ما-صحة-حديث-يا-علي-لا-تنم-قبل-خمسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث يا علي، لا تنم قبل أن تأتي بخمسة أشياء.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1772,"question":"قوله: روى الإمام أحمد رحمه الله تعالى في \"المسند\"، قال: حدثنا هارون بن معروف، قال: حدثنا ابن وهب، قال: حدثني عمرو -يعني: ابن الحارث- عن عمرو بن شعيب، عن أبيه، عن جده، عن النبي ﷺ أنه قال: مَن ترك الصلاة سُكْرًا مرةً واحدةً فكأنَّما كانت له الدنيا وما عليها..؟","title":"ما صحة حديث \"مَن ترك الصلاة سُكْرًا\"؟","answer":"الجواب:\nنسأل الله العافية، نعم.\nالطالب: ومَن ترك الصلاة سُكْرًا أربع مراتٍ كان حقًّا على الله  أن يسقيه من طينة الخبال، قيل: وما طينةُ الخبال يا رسول الله؟ قال: عصارة أهل جهنم.\nالشيخ: نسأل الله العافية، هذا سَنَدٌ جيدٌ.","link":"https://binbaz.org.sa/fatwas/21879/ما-صحة-حديث-من-ترك-الصلاة-سكرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث من ترك الصلاة سكرا مرة...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1773,"question":"أبي يُجبرني على مفارقة زوجتي لأنها لم تُنجب؟","title":"حكم مفارقة الزوجة التي لا تنجب","answer":"الجواب:\nإن كانت إنسانةً جيدةً لا تُطلقها، إنسانة بنت حلال وطيبة وجيدة، استسمح والدك بالكلام الطيب.\nس: والدي رفض إلا أن أطلع من البيت؟\nج: لا، إذا كانت طيبةً لا تُطلقها، لكن تستسمح الوالد بالكلام الطيب، والأسلوب الحسن، والعبارات الطيبة، حتى يهديه الله إن شاء الله، إذا كانت طيبةً وصاحبة دينٍ وصلاةٍ وخيرٍ.","link":"https://binbaz.org.sa/fatwas/21880/حكم-مفارقة-الزوجة-التي-لا-تنجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مفارقة الزوجة التي لا تنجب.mp3","categories":["الطلاق"]},{"id":1839,"question":"حديث: إن العبدَ ليُحرَمُ الرِّزقَ بالذنب هل هو صحيح؟","title":"درجة حديث \"إن العبدَ ليُحرَمُ الرِّزقَ بالذنب\"","answer":"الجواب:\nلا بأس به، ذكره ابنُ القيم وغيره في \"الجواب الكافي\"، والظاهر أنه لا بأس بسنده.","link":"https://binbaz.org.sa/fatwas/21948/درجة-حديث-ان-العبد-ليحرم-الرزق-بالذنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أن العبد ليُحرم الرزق بالذنب يُصيبه.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1853,"question":"هل كفارة الظهار تسقط بطلاق الزوجة؟","title":"هل تسقط كفارة الظهار بطلاق الزوجة؟","answer":"الجواب:\nكفارة الظهار ما تجب عليه إلا إذا كان يُجامعها، وإذا طلَّقها ما عنده كفارة ظهار، لكن لو عادت إليه لا يطأها حتى يُكفِّر.","link":"https://binbaz.org.sa/fatwas/21962/هل-تسقط-كفارة-الظهار-بطلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلاق الزوجة هل يسقط كفارة الظهار.mp3","categories":["الطلاق","الظهار"]},{"id":1865,"question":"صحة حديث ابن مسعود (أَوَّلَ مَا دخَلَ النَّقْصُ عَلَى بَنِي إِسْرائيلَ...)؟","title":"ما صحة \"أَوَّلَ مَا دخَلَ النَّقْصُ بَنِي إِسْرائيلَ\"؟","answer":"الجواب:\nحديث ابن مسعود في بني إسرائيل فيه بعض الضعف، لكن له طرق، أما حديث الصِّدِّيق فهو صحيح، رواه أحمد وأبو داود والترمذي بإسنادٍ صحيحٍ، أما حديث ابن مسعود فالمؤلف تساهل فيه؛ لأنَّه من باب الترغيب والترهيب، وشواهده كثيرة، ونصَّ القرآن يكفي: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ [المائدة:78]، فنصّ القرآن كافٍ في قصة بني إسرائيل –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21974/ما-صحة-اول-ما-دخل-النقص-بني-اسراىيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث إِنَّ أَوَّلَ مَا دخَلَ النَّقْصُ عَلَى بَنِي إِسْرائيلَ..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1893,"question":"حديث: أفضل الذكر: لا إله إلا الله؟","title":"ما صحة حديث \"أفضل الذكر لا إله إلا الله\"؟","answer":"الجواب:\nثابت من حديث أبي هريرة وغيره، يقول النبي ﷺ: الإيمان بضع وسبعون شعبة، فأفضلها قول: لا إله إلا الله رواه مسلم في \"الصحيح\".","link":"https://binbaz.org.sa/fatwas/22004/ما-صحة-حديث-افضل-الذكر-لا-اله-الا-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حديث أفضل الذكر لا إله إلا الله ثابت.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1905,"question":"حديث قبيصة صحيح إنَّ العيافةَ والطَّرقَ والطِّيرةَ منَ الجِبْتِ ؟","title":"درجة حديث \"العيافةَ والطَّرق والطِّيرةَ...\"","answer":"الجواب:\nلا بأس به، السند جيد، رواه الإمام أحمد بإسنادٍ جيدٍ.\nس: يقول: فيه حيان بن العلاء مجهول؟\nج: لا بأس به، لا، ما هو مجهول، مقبول وله شواهد.\nس: تفسير أبي داود للطرق والعيافة فيه قلب، قال: العيافة: الخط، والطرق: الزجر؟\nج: لا، الطرق: الخطّ، والعيافة: زجر الطير، هذا غلطٌ في النقل، والطيرة: التشاؤم بالمرئيات والمسموعات.","link":"https://binbaz.org.sa/fatwas/22017/درجة-حديث-العيافة-والطرق-والطيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث العِيَافة والطّرق والطِّيرة من الجبت.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1915,"question":"حديث عروة بن عامر (ذُكِرتِ الطِّيَرَةُ عِنْد رَسُولِ اللَّه ﷺ...) صحيح؟","title":"درجة حديث \"ذُكِرتِ الطِّيَرَةُ عِنْد رَسُولِ اللَّه..\"","answer":"الجواب:\nمثلما قال المؤلف: ما أعرف له عِلَّة، قال: سنده صحيح، ولا أتذكر فيه علة.\nس: ذكر فيه بعضُ الشُّرَّاح علتين، قال: أولها عروة بن عامر مختلف في صحبته، وقال: فيه تدليس حبيب ابن أبي ثابت، وقد عنعن؟\nج: يحتاج إلى تأمّل في الطرق.","link":"https://binbaz.org.sa/fatwas/22028/درجة-حديث-ذكرت-الطيرة-عند-رسول-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث ذُكِرتِ الطِّيَرَةُ عِنْد رَسُولِ اللَّه...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":1937,"question":"إذا طلَّق الرجلُ امرأتَه وهي حائض هل يثبت أم لا يثبت؟","title":"ما حكم طلاق الحائض؟","answer":"الجواب:\nإذا كان يعرف ذلك وهي تعرف ذلك؛ فالصحيح أنه لا يقع عند بعض أهل العلم، والجمهور على أنه يقع، لكن الأصح أنه لا يقع؛ لحديث ابن عمر، إذا كان يعلم ذلك.\nس: إذا كان ما يعلم؟\nج: يقع عليه؛ لأنه ما ابتدع، ما تعمَّد بدعةً، إن كان يعلم فقد تعمَّد بدعةً، تعمَّد مُنكرًا فلا يقع، وإذا كان ما يعلم أو حكم به القاضي فإنه يقع، فأكثر القضاة يحكم بهذا، والأصح عند الأقل أنه لا يقع، والجمهور على أنه يقع؛ لأن ابن عمر أمضاه على نفسه.","link":"https://binbaz.org.sa/fatwas/22050/ما-حكم-طلاق-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقع طلاق الحائض.mp3","categories":["الطلاق","الحيض والنفاس"]},{"id":1986,"question":"حديث أنس الأول إياك والالتفات في الصلاة صحيح؟","title":"ما صحة حديث \"إياك والالتفات في الصلاة\"؟","answer":"الجواب:\nالشيخ: يحتاج تأمل، الترمذي قال فيه: حسن صحيح، ويحتاج إلى مراجعة، لأن في قوله \"فإنه هلكة\" يحتاج مراجعة.\nس: ابن القيم أعله في الزاد بعلتين؟\nالشيخ: نراجعه إن شاء الله، ونشوف.","link":"https://binbaz.org.sa/fatwas/22102/ما-صحة-حديث-اياك-والالتفات-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إياك والالتفات في الصلاة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2038,"question":"من يقول: \"باللات والعزى أنت طالق\" يقع الطلاق؟","title":"حكم من قال \"باللات والعزى أنت طالق\"","answer":"الجواب:\nيقع بقوله: أنت طالق.  وعليه التوبة من هذا اليمين.","link":"https://binbaz.org.sa/fatwas/22155/حكم-من-قال-باللات-والعزى-انت-طالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من قال لامرأته باللات والعزى أنت طالق.mp3","categories":["الطلاق"]},{"id":2091,"question":"يقول بعضُ الناس: \"ما خاب مَن استشار، ولا ندم مَن استخار\"، فهل هذا حديث أو حكمة أو كلام عامّ؟","title":"ما صحة القول: \"ما خاب مَن استشار...\"؟","answer":"الجواب:\nمعناه صحيح، فالنبي ﷺ أمر بالاستخارة، وأمر بالمشاورة، والله يقول: وَأَمْرُهُمْ شُورَى بَيْنَهُمْ [الشورى:38]، وهو يُروى عن النبي ﷺ، ولكن ما أعرف سنده، لكن معناه صحيح.","link":"https://binbaz.org.sa/fatwas/22209/ما-صحة-القول-ما-خاب-من-استشار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما خاب مَن استشار، ولا ندم مَن استخار.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2169,"question":"والسؤال الثالث يقول: حصل بيني وبين قريبٍ لي شغار، وطبعًا العقد باطل، والآن طلَّق أحدُنا، ويريد الآخر الاستمرار على زوجته؟","title":"حكم شخصين تزوجا بالشغار ثم طَلَّق أحدهما","answer":"الجواب:\nيُجدد العقد بدون شرط الشّغار، مع التوبة مما مضى.","link":"https://binbaz.org.sa/fatwas/22290/حكم-شخصين-تزوجا-بالشغار-ثم-طلق-احدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الطلاق في زواج الشغار.mp3","categories":["الأنكحة المحرمة","الطلاق"]},{"id":2188,"question":"المستشار مُؤْتَمن هل هو حديث؟","title":"ما صحة حديث: «المستشار مُؤْتَمن»؟","answer":"الجواب:\nيُروى عن النبي ﷺ، لكن ما أعرف حال سنده، ومعناه صحيح، فالمستشار مُؤتمن، يجب عليه أن يُؤدي الأمانة.","link":"https://binbaz.org.sa/fatwas/22311/ما-صحة-حديث-المستشار-موتمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المستشار مؤتمن هل هو حديث.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2224,"question":"الربا ثلاثة وسبعون بابًا، أيسرها أن ينكح أُمَّه، وإنَّ أربى الربا عِرْض الرجل المسلم هل هذا الحديث صحيح؟","title":"ما صحة حديث \"الربا ثلاثة وسبعون بابًا..\"؟","answer":"الجواب:\nمحلُّ نظرٍ، ما أعرف حال سنده، ولكنه من كلِّ الوجوه يُفيد الحذر من الاستطالة في عِرْض المسلم دون حقٍّ، فالغيبة نصَّ عليها الربُّ جلَّ وعلا: وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] \nفيجب على المؤمن الحذر مما نصَّ الله على تحريمه، وهكذا ما نصَّ عليه الرسولُ ﷺ.\nس: عند احتمال صحته: كيف يكون الربا أعظم من نكاح الرجل لأمِّه؟\nج: المقصود: التَّحذير من الربا، وأن الرجل يجب عليه أن يحذر الربا غاية الحذر، وهكذا الاستطالة في عِرْض أخيه المسلم.\nس: كيف يكون عِرْضُ الرجل المسلم أكبر من نكاح الأمِّ؟\nج: لو صحَّ فالمقصود: التحذير من هذا البلاء العظيم الذي قد يترتب عليه فسادٌ كبيرٌ.","link":"https://binbaz.org.sa/fatwas/22347/ما-صحة-حديث-الربا-ثلاثة-وسبعون-بابا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث الربا ثلاثة وسبعون بابًا...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2237,"question":"ما صحَّة حديث أبي أمامة: أنا زعيمٌ ببيتٍ في ربض الجنة؟","title":"درجة حديث \"أنا زعيمٌ ببيتٍ في ربض الجنة\"","answer":"الجواب:\nالزعيم يعني: الضَّامن.\nس: ما صحَّة الحديث؟\nج: لا بأس به، جيد.","link":"https://binbaz.org.sa/fatwas/22360/درجة-حديث-انا-زعيم-ببيت-في-ربض-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث أنا زعيمٌ ببيتٍ في ربض الجنة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2243,"question":"سياق قول الله : إِنْ تَتُوبَا إِلَى اللَّهِ [التحريم:4]، ثم بعد ذلك: عَسَى رَبُّهُ إِنْ طَلَّقَكُنَّ [التحريم:5]، هل يدل ذلك على جواز التَّهديد بالطلاق؟","title":"ما حكم التهديد بالطلاق؟","answer":"الجواب:\nنعم، فالطلاق مملوكٌ له، وإذا هدّد به؛ لا بأس؛ لعلها تستقيم.","link":"https://binbaz.org.sa/fatwas/22366/ما-حكم-التهديد-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التهديد بالطلاق.mp3","categories":["الطلاق"]},{"id":2270,"question":"ما صحة الحديث القدسي: جعلتُ لي نسبًا، وجعلتُ لكم نسبًا، فقلتُ: إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، فأبيتُم إلا فلان وفلان، فاليوم أرفع نسبي، وأضع نسبَكم، أين المتقون؟؟","title":"ما صحة الحديث القُدُسي: \"جعلتُ لي نسبًا..\"؟","answer":"الجواب:\nما أعرفه، إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] صدق الله العظيم.","link":"https://binbaz.org.sa/fatwas/22393/ما-صحة-الحديث-القدسي-جعلت-لي-نسبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث جعلتُ لي نسبًا، وجعلتُ لكم نسبًا.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2272,"question":"ما صحة حديث: رُبَّ صائمٍ ليس له من صيامه إلا الجوع؟","title":"ما صحة حديث \"رُبَّ صائمٍ ليس له...\"؟","answer":"الجواب:\nما أعرف حاله، لكن يُروى مشهورًا، ومعناه صحيح مثلما قال ﷺ في الحديث الصحيح في هذا المعنى، وبيَّن ﷺ أنَّ الذي يصوم ولا يضبط صيامَه حظُّه الجوع والعطش –نسأل الله العافية: مَن لم يدع قولَ الزور والعملَ به والجهلَ فليس لله حاجةٌ في أن يدع طعامَه وشرابه رواه البخاري في \"الصحيح\" –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22395/ما-صحة-حديث-رب-صاىم-ليس-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث رُبَّ صائمٍ ليس له من صيامه إلا الجوع.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2286,"question":"حديث: مَن أهان السلطانَ أهانه اللهُ ما درجة صحته؟","title":"ما صحة حديث \"مَن أهان السلطانَ أهانه اللهُ\"؟","answer":"الجواب:\nما أعرف حاله، ولا تتبعتُ سنده، لكن مقتضى الأدلة تُؤيد ذلك؛ لأنَّ إهانته تُنزل قدره عند الناس، وتُضعف شوكتَه، ويتساهل به الناس، فالواجب احترامه، والسمع والطاعة له في المعروف؛ حتى يُحترم ويُهاب ويأمن الناسُ.","link":"https://binbaz.org.sa/fatwas/22409/ما-صحة-حديث-من-اهان-السلطان-اهانه-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/درجة حديث مَن أهان السلطانَ أهانه اللهُ.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2300,"question":"هل صحَّ أنَّ النبي ﷺ قال: استعينوا على قضاء حوائِجكم بالكتمان؟","title":"ما صحة \"استعينوا على حوائِجكم بالكتمان\"؟","answer":"الجواب:\nلا، ما هو بحديثٍ، يُروى عن عمر.","link":"https://binbaz.org.sa/fatwas/22424/ما-صحة-استعينوا-على-حواىجكم-بالكتمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استعينوا على قضاء حوائِجكم بالكتمان.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2313,"question":"بالنسبة لطلاق الحائض: سواء كان الرجلُ عالمًا بحيضها أو ..؟","title":"حكم طلاق الحائض عالمًا بحيضها أو جاهلًا","answer":"الجواب:\nبشرط أنه يعلم، وإلا فلا إثم عليه، يقع الطلاق، فلا بد أن يكونا صادقين جميعًا.\nس: ابن عمر حسب الطلقة؟\nج: اجتهادًا منه، وهو قول الجمهور.","link":"https://binbaz.org.sa/fatwas/22437/حكم-طلاق-الحاىض-عالما-بحيضها-او-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلاق الحائض عالما بحيضها أو جاهل.mp3","categories":["الطلاق","الحيض والنفاس","قضايا المرأة"]},{"id":2352,"question":"ما صحَّة حديث: أن رجلًا أكل فلم يذكر التَّسمية إلا عند آخر لقمةٍ، فقال النبيُّ ﷺ أن الشيطان قد استقاء عندما ذكر الله؟","title":"هل صح أن \"الشيطان استقاء عندما ذُكر الله\"؟","answer":"الجواب:\nما راجعتُ سنده، ما عندك مَن خرَّجه؟ تقدَّم في الدرس الماضي: فقاء الشيطان كل ما في بطنه لما سمى الله في آخره.\nالطالب: عندي تخريجه، قال: صحيحٌ بشواهده، أخرجه أبو داود، والنَّسائي في \"عمل اليوم والليلة\"، وأحمد، وابن السني في \"عمل اليوم والليلة\"، والحاكم، وابن سعدٍ في \"الطبقات الكبرى\"، وغيرهم من طريق جابر بن صبح، قال: حدَّثنا مثنى بن عبدالرحمن الخزاعي، عن عمِّه أمية بن مخشي، به، قال الحاكم: صحيح الإسناد، ووافقه الذهبيُّ، قلتُ (المحشي): كلا؛ فإنَّ المثنى بن عبدالرحمن قد قال فيه الذهبي في \"الميزان\": لا يُعْرَف، تفرَّد عنه جابر بن صبح، وقال ابن المديني: مجهول؛ لهذا قال الحافظُ في \"التقريب\": مستور، لكن يشهد له حديث عائشة رضي الله عنها في الباب الذي قبله.\nج: الله المستعان.","link":"https://binbaz.org.sa/fatwas/22477/هل-صح-ان-الشيطان-استقاء-عندما-ذكر-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحَّة حديث أن رجلًا أكل فلم يذكر التَّسمية إلا عند آخر لقمةٍ...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2389,"question":"حديث بريدة (بَشِّر المَشَّائين في الظُّلَم..) صحيح؟","title":"ما صحة حديث \"بَشِّر المَشَّائين في الظُّلَم..\"؟","answer":"الجواب:\nأي حديث بريدة؟\nس: بَشِّر المَشَّائين؟\nالشيخ: ما راجعت سنده، عندك عليه حاشية؟\nالطالب: رواه أبو داود والترمذي، وله شاهد من حديث أنس عند ابن ماجه ومستدرك الحاكم، وعن سهل بن سعد الساعدي عند الحاكم، والحديث صحيح.\nالشيخ: يحتاج مراجعة أسانيده، وهو بهذه الشواهد -إذا كانت أسانيده جيدة- يكون من باب الصحيح لغيره، وإن كانت أسانيده فيها لين؛ فهي من باب الحسن لغيره.","link":"https://binbaz.org.sa/fatwas/22514/ما-صحة-حديث-بشر-المشاىين-في-الظلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث بشروا المَشائين في الظلم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2404,"question":"راوية أبي داود لا يزال الرجل يتأخر عن الصف المقدم حتى يؤخره الله في النار صحيحة؟","title":"ما صحة الوعيد بالنار لمن يتأخر عن الصف؟","answer":"الجواب:\nلا أعلم بها بأسًا من حديث عائشة رضي الله عنها لا يزال الرجل يتأخر عن الصف المقدم حتى يؤخره الله في النار إسناده لا بأس به، هذا من باب الوعيد.","link":"https://binbaz.org.sa/fatwas/22529/ما-صحة-الوعيد-بالنار-لمن-يتاخر-عن-الصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة راوية أبي داود حتى يؤخرهم في النار.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2429,"question":"حديث: لا صلاة لجار المسجد إلا في المسجد؟","title":"ما صحة ألَّا صلاة لجار المسجد إلا بالمسجد؟","answer":"الجواب:\nالمعروف أنه ضعيف، لكنه محفوظ عن علي، لكن يغني عنه الحديث الصحيح: من سمع النداء فلم يجبه فلا صلاة له إلا من عذر يكفي عنه، وقوله ﷺ للأعمى لما قال: يا رسول الله إني ليس قائد يقودني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ قال: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب وهو أعمى ليس له قائد، يجب عليه أن يصلي ولو ما هو بجار ما دام يسمع النداء.","link":"https://binbaz.org.sa/fatwas/22557/ما-صحة-الا-صلاة-لجار-المسجد-الا-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حصة حديث لا صلاة لجار المسجد إلا في المسجد.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2488,"question":"يقول في الحاشية عن حديث سعد بن أبي وقاص: أخرجه أبو داود وأخرجه البيهقي، وفي سنده موسى بن يعقوب السمعي وهو سيئ الحفظ، وشيخه يحيى بن الحسن بن عثمان مجهول، لكن في الباب عند أبي داود والترمذي من حديث أبي بكرة «أن النبي ﷺ كان إذا جاءه أمر يُسَرُّ به خَرَّ ساجدًا شاكرًا لله تعالى» وسنده حسن، وسجد كَعْب بن مالك في عهد النبي ﷺ لما بُشِّر بتوبة الله عليه.","title":"ما صحة حديث سجود كَعْب لما بُشِّر بالتوبة؟","answer":"الجواب:\nهذا صحيح، لما جاءه خبر التوبة سَجَد كَعْب لله .","link":"https://binbaz.org.sa/fatwas/22618/ما-صحة-حديث-سجود-كعب-لما-بشر-بالتوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث أن النبي كان إذا جاءه أمر يسر به خر ساجدًا..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2530,"question":"حديث: إن أشد الناس على الدجال بنو تميم، صحيح؟","title":"مَنْ أتباع الدجال وأشد الناس عليه؟","answer":"الجواب:  هم أشَدُّ أُمَّتي على الدَّجَّالِ صحيح، يعني في مخالفته والرد عليه. س: هل يحمل هذا أنه منهم الرجل هذا؟\nالشيخ: محتمل، الله أعلم، كل أهل الإيمان ضده.\nس: اليهود؟\nالشيخ: هم أتباعه، يتبعه من يهود أصبهان سبعون ألفًا من الشرق، واليهود في فلسطين هم قومه وجنده فيقتلهم المسلمون مع المسيح عيسى ابن مريم.\nس:في آخر الزمان يرفع القرآن، فهل يقع هذا للسنة؟\nالشيخ: بعد الدجال بعد مدة وبعد طلوع الشمس من مغربها.\nس: والسنة تكون موجودة؟\nالشيخ: ما جاء فيها ذِكر، لكن بعد خروج الدجال يرفع القرآن، ثم تأتي الريح الطيبة تقبض أرواح المؤمنين والمؤمنات.\nس: الرجل الذي أتى للدجال وأخبره أن النبي عليه السلام أخبر به، بالدجال، ألا يدل أن السنة باقية إلى زمن الدجال؟\nالشيخ: نعم السنة باقية، السنة والقرآن باقيان، نزع القرآن بعد الدجال بمدة بعد طلوع الشمس من مغربها.","link":"https://binbaz.org.sa/fatwas/22661/من-اتباع-الدجال-واشد-الناس-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث إن أشد الناس على الدجال بني تميم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2556,"question":"هل \"لا حياء في الدين\" صحيح؟","title":"ما صحة قول \"لا حياء في الدين\"؟","answer":"الجواب: ما أعرف له أصلًا، مأخوذ هذا من كلام أم سُلَيْم قالت بمعناه: يا رسول الله إن الله لا يستحيي من الحق، مأخوذ من هذا فقالت: يا رسول الله هل على المرأة مِن غُسْل إذا هي احتلمت؟ تسأل ما أنا بمستحية، باسأل عن هذا الأمر العظيم، هل على المرأة مِن غُسْل إذا احتلمت؟ قال النبي ﷺ: نعم إذا رأت الماء. والله يقول: وَاللَّهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ [الأحزاب:53].","link":"https://binbaz.org.sa/fatwas/22688/ما-صحة-قول-لا-حياء-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة قول لا حياء في الدين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2561,"question":"من لزم الاستغفار جعل الله له من كل هم مخرجا، ومن كل ضيق فَرَجًا، هل هذا صحيح؟","title":"ما درجة حديث \"من لزِم الاستغفار..\"؟","answer":"الجواب: لا بأس به، الظاهر أن سنده لا بأس به.","link":"https://binbaz.org.sa/fatwas/22693/ما-درجة-حديث-من-لزم-الاستغفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لزوم الاستغفار.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2601,"question":"هل الحديث الأول صحيح، حديث ابن عباس (من لزم الاستغفار..)؟","title":"ما صحة ما جاء في فضل الاستغفار ولزومه؟","answer":"الجواب: ما أذكر فيه بأسًا، حشَّى عليه المُحَشِّي: من لزم الاستغفار؟\nالطالب: نعم من لزم الاستغفار.. أخرجه أبو داود والإمام أحمد في المسند وابن ماجه والحاكم، وفي سنده الحكيم بن مصعب، قال أبو حاتم: مجهول: وذكره ابن حبان في الضعفاء، وقال الأزدي: لا يتابع على حديثه.\nالشيخ: يحتاج متابعة، وأيش قال على الثاني؟\nالطالب: يقول: من قال أستغفر الله الذي لا إله إلا هو.. أخرجه أبو داود والترمذي، وفي سنده من لم يوثقه غير ابن حبان، وأخرجه الحاكم من طريق آخر وصححه ووافقه الذهبي، وهو كما قالا.\nالشيخ: وبكل حال حتى لو ما صحت التوبة إلى الله والاستغفار يمحو الله بها الذنوب بنص القرآن، المهم الصدق في التوبة والاستغفار، وآية القرآن كافية في هذا صريحة، المهم الصدق، نسأل الله للجميع التوفيق للصدق.","link":"https://binbaz.org.sa/fatwas/22735/ما-صحة-ما-جاء-في-فضل-الاستغفار-ولزومه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث من لزم الاستغفار..، وحديث من قال أستغفر الله الذي لا إله إلا هو.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2665,"question":"بالنسبة لحديث الترمذي الذي حسّنه الترمذي (أحَبُّ عبادي إليَّ أعجلهم فِطْرًا)؟","title":"ما صحة حديث: «أحَبُّ عبادي أعجلهم فِطْرًا»؟","answer":"الجواب: إيه؟\nالطالب: في هذا التحسين نظر؛ لأن مدار إسناده على قرة بن عبدالرحمن، وهو ضعيف لسوء حفظه، وأحضرت معي السند: قال الإمام الترمذي: باب ما جاء في تعجيل الفطر: حدثنا إسحاق بن موسى الأنصاري، قال: حدثنا الوليد بن مسلم عن الأوزاعي عن قرة بن عبدالرحمن عن الزهري عن أبي سلمة عن أبي هريرة قال قال رسول الله ﷺ: قال الله : أحب عبادي إلي أعجلهم فطرا قال في الخلاصة: قرة بن عبدالرحمن المعافري عن الزهري وأبي الزبير وعن الليث وابن لهيعة وثقه ابن حبان، وقال ابن عدي: أرجو أنه لا بأس به، وقال أحمد: منكر الحديث جدا، وقال ابن يونس توفي سنة47 قرنه مسلم بآخر، وقال الحافظ: صدوق له مناكير من السابعة، ونسبه إلى مسلم...\nالشيخ: هي الأقرب أن مثل هذا له شواهد، مثل هذا له شواهد تدل على صحة روايته في هذا.\nس: في رواية مسلم في المتابعات؟\nالشيخ: نعم في المتابعات، هذه عادته، حديث: لا يزال الناس بخير ما عَجَّلوا الفِطْر يشهد له بهذا.","link":"https://binbaz.org.sa/fatwas/22803/ما-صحة-حديث-احب-عبادي-اعجلهم-فطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أحب عبادي إلي أعجلهم فطرا.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2677,"question":"الزيادة التي رواها أبو داود أنه: لا تدخل الملائكة بيتًا فيه كلب أو صورة أو جُنُب؟","title":"هل صح أن الملائكة لا تدخل بيتًا فيه جُنُب؟","answer":"الجواب: هذا محل نظر، كان النبي ﷺ يبيت وهو جُنُب عليه الصلاة والسلام، يتوضأ وضوء الصلاة وينام وهو جُنُب عليه الصلاة والسلام، فلو كانت الملائكة تمتنع من الجُنُب ما بات وهو جُنُب عليه الصلاة والسلام قد يأتيه الوحي.\nس: يعني لو صحت تكون شاذة؟\nالشيخ: ما هو ظاهر أنها صحيحة، الصورة والكلب صح.","link":"https://binbaz.org.sa/fatwas/22815/هل-صح-ان-الملاىكة-لا-تدخل-بيتا-فيه-جنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة لفظ جنب في حديث لا تدخل الملائكة بيتًا فيه كلب أو صورة أو جنب.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2684,"question":"أحضرنا إسناد مجيبة الباهلية؟","title":"حكم حديث مجيبة الباهلية في صوم التطوُّع","answer":"الجواب: اقرأه؟\nالطالب: قال أبو داود: باب في صوم أشهر الحرم: حدثنا موسى بن إسماعيل قال: أخبرنا حماد عن سعيد الجريري عن أبي سليل عن مجيبة عن أبيها أو عمها ثم ساق لفظه أنه أتى رسول الله ﷺ ثم انطلق فأتاه بعد سنة وقد تغير حاله وهيأته فقال يا رسول الله أما تعرفني؟ قال: ومن أنت؟ قال: أنا الباهلي الذي جئتك العام الأول. قال: فما غيّرك وقد كنت حسن الهيئة؟ قال: ما أكلت طعامًا منذ فارقتك إلا بليل. فقال رسول الله ﷺ: عذّبت نفسك، ثم قال: صم شهر الصبر ويومًا من كل شهر، قال: زدني فإن بي قوة. قال: صم يومين قال: زدني. قال: صم ثلاثة أيام قال: زدني. قال: صم من الحُرُم واترك، صم من الحرم واترك، صم من الحرم واترك وقال بأصابعه الثلاث فضمها ثم أرسلها.\nوقال ابن ماجه: حدثنا أبو بكر بن أبي شيبة حدثنا وكيع عن سفيان عن الجريري عن أبي السليل عن أبي مجيبة الباهلي عن أبيه أو عن عمه هنا قال عن أبي مجيبة في ابن ماجه قال: أتيت النبي ﷺ فقال يا نبي الله أنا الرجل الذي أتيتك العام الأول. قال: فما لي أرى جسمك ناحلًا؟ قال: يا رسول الله ما أكلت طعامًا بالنهار ما أكلته إلا بالليل. قال: من أمرك أن تعذّب نفسك؟ قلت: يا رسول الله إني أقوى. قال: صم شهر الصبر ويومًا بعده. قلت: إني أقوى قال: صم شهر الصبر ويومين بعده. قلت: إني أقوى. قال: صم شهر الصبر وثلاثة أيام بعده، وصم أشهر الحُرُم. وعن أبيها وذكره الحافظ ابن حجر قال: عبدالله بن الحارث الباهلي، ثم أحال إلى ترجمته إلى أبي مجيبة، وعندما رجعت إلى الكنى أحال أيضًا إلى مجيبة، وقال: بضم أوله وكسر الجيم بعدها تحتانية ثم موحدة الباهلي، وقيل: هي امرأة روى لها ابن ماجه من الصحابة لكنها خلاف، حتى المحشي ذكر خلاف ما ذكره ابن ماجه.\nالشيخ: ... لأنه إذا كانت تابعية سواء مجيبة أو أبي مجيبة هو الحديث فيه علة بجهالة التابعي.\nس: الحافظ قال: وهي امرأة روى لها ابن ماجه لكن ابن ماجه قال عن أبي مجيبة؟\nالشيخ: محتمل عندك شيء غير هذا؟\nالطالب: عندي في عون المعبود شرح سنن أبي داود في الحاشية قال المنذري: وأخرجه النسائي وابن ماجه إلا أن النسائي قال فيه: عن مجيبة الباهلي عن عمه، وقال ابن ماجه: عن أبي مجيبة الباهلي عن أبيه أو عمه، وذكره أبو القاسم البغوي في معجم الصحابة وقال: فيه عن مجيبة يعني الباهلية قالت: حدثني أبي أو عمي، وسمّى أباه عبدالله بن الحارث، فقال: سكن البصرة وروى عن النبي ﷺ حديثًا، وقال في موضع آخر: أبو مجيبة الباهلية أو عمها سكن البصرة وروى عن النبي ﷺ حديثًا ولم يسمه وذكر هذا الحديث، وذكره ابن قانع في معجم الصحابة، وقال: فيه عن مجيبة عن أبيها أو عمها، وسماه أيضًا عبدالله بن الحارث هذا آخر كلامه، وقد وقع فيه هذا الاختلاف كما ترى، وأشار بعض شيوخنا إلى تضعيفه لذلك، وهو متوجه، ومجيبة بضم الميم وكسر الجيم.\nالشيخ: ضعيف؛ لأنه مجيبة مجهولة.\nس: اسم أبيها عبدالله بن الحارث الباهلي.\nالشيخ: هو بهذا السند ضعيف.....\nالشيخ: وفيه نكارة، متن الأشهر الحرم ما جاء إلا في هذا الحديث، من حديث أفضل الصيام بعد رمضان شهر الله المحرم عاشوراء، بس هذا فيه الأشهر الحرم، والأحاديث الصحيحة: الحث على صوم الإثنين والخميس وثلاثة أيام من كل شهر، كما في حديث عبدالله بن عمرو بن العاص وغيره، ما فيه ذكر الأشهر الحرم، فهذا غريب من هذا الوجه، المقصود أن الحديث ضعيف.","link":"https://binbaz.org.sa/fatwas/22822/حكم-حديث-مجيبة-الباهلية-في-صوم-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سند حديث مجيبة الباهلية والحكم عليه.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2781,"question":"سائل يقول: قال رسول الله ﷺ: افترقت اليهود على إحدى وسبعين فرقة، وافترقت النصارى على اثنين وسبعين فرقة، وستفترق هذه الأمة على ثلاث وسبعين فرقة، كلهم في النار إلا واحدة قيل: من هي يا رسول الله؟ قال: من كان على مثل ما أنا عليه وأصحابي. يقول هل: كلهم في النار إلا واحدة، قيل: من هي يا رسول الله؟ قال: من كان على مثل ما أنا عليه يقول: هذه زيادة أحسن الله إليك في الحديث؟","title":"ما صحة زيادة: \"على مثل ما أنا عليه\"؟","answer":"الجواب: نعم هذه رواها الترمذي الزيادة، وفي اللفظ الآخر: وهي الجماعة، وقد أجمع أهل السنة أن الفرقة الناجية هم أهل السنة والجماعة بإجماع المسلمين، هم أتباع الرسل ﷺ من الصحابة ومن بعدهم. أما من خالفهم فهم أقسام، ثنتان وسبعون فرقة: فيهم الكافر، وفيهم العاصي، وفيهم المبتدع، لكن ليسوا كلهم كفارًا، فيهم الكافر وفيهم غير الكافر، لكنهم متوعدون بالنار لخلافهم الحق، إما بالبدع وإما بالمعاصي الكبيرة، والعياذ بالله، وإما بالكفر، يدخل فيهم الجهمية والمعتزلة والمرجئة والرافضة وغيرهم من أهل البدع المضلة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22929/ما-صحة-زيادة-على-مثل-ما-انا-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة من كان على مثل ما أنا عليه في حديث افترقت اليهود على إحدى وسبعين فرقة..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2812,"question":"حديث طلب العلم فريضة على كل مسلم؟","title":"ما صحة حديث \"طلب العلم فريضة..\"؟","answer":"الجواب: لا بأس به، له طرق جيدة.","link":"https://binbaz.org.sa/fatwas/22961/ما-صحة-حديث-طلب-العلم-فريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث طلب العلم فريضة على كل مسلم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2831,"question":"صحة حديث أبي سعيد الخدري (لن يشبع مؤمن مِن خير حتى يكون مُنتهاه الجنة)؟","title":"درجة حديث \"لن يشبع مؤمن من خير حتى..\"","answer":"الجواب: ما تتبعت أسانيده، يحتاج تتبع أسانيده.\nالطالب: يقول المُحَشِّي: من حديث دَرَّاج عن أبي الهيثم.\nالشيخ: درَّاج ضعيف عن أبي الهيثم، لكن إنْ كان له طريق أخرى، وإلا درّاج عن أبي الهيثم فيه ضعف.","link":"https://binbaz.org.sa/fatwas/22980/درجة-حديث-لن-يشبع-مومن-من-خير-حتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لن يشبع مؤمن من خير حتى يكون منتهاه الجنة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2832,"question":"الحديث الذي يقول فيه: ثلاث من الجفاء: أن يبول الرجل قائمًا، أو يمسح جبهته قبل أن يفرغ من صلاته، أو ينفخ في سجوه ذكره ابن القيم في الزاد؟","title":"ما صحة حديث \"ثلاث من الجفاء..\"؟","answer":"الجواب: ما أعرف له صحة، والظاهر غير صحيح؛ لأن الرسول ﷺ فعل ما تقدم: كونه بال قائمًا لما دعت الحاجة إلى ذلك؛ أتى سُباطة قوم فبال قائمًا، إذا دعت الحاجة لا بأس مع التستر. أما كونه يمسح وجهه هذا الأفضل تركه، يترك المسح حتى ينتهي من الصلاة. والثالثة: النفخ، كان النبي ينفخ في سجوده عليه الصلاة والسلام، لا حرج.\nس: لو صح إسناده يعتبر شاذًّا مخالفًا للأحاديث الصحيحة؟\nالشيخ: نعم؛ لو صح يكون شاذًّا.","link":"https://binbaz.org.sa/fatwas/22981/ما-صحة-حديث-ثلاث-من-الجفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث ثلاث من الجفاء أن يبول الرجل قائما...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2844,"question":"قول النبي ﷺ أفضل الجهاد جهاد المرء نفسه في طاعة اللهحديث صحيح؟","title":"هل صح حديث أن أفضل الجهاد جهاد النفس؟","answer":"الجواب: ما أدري والله، المعروف: المجاهد من جاهد نفسه لله، هذا يعني الجهاد العام، غير الجهاد الخاص، وإن صح اللفظ هو بمعنى اللفظ الآخر، المجاهد من جاهد نفسه لله، يعني الجهاد الكامل؛ الذي يجاهد نفسه دائمًا في الجهاد وفي غير الجهاد، في الأوقات الأخرى، هذا عام، في الجهاد يجاهد، وفي الرخاء يجاهد نفسه.","link":"https://binbaz.org.sa/fatwas/22997/هل-صح-حديث-ان-افضل-الجهاد-جهاد-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أفضل الجهاد جهاد المرء نفسه..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2852,"question":"حديث ابن مسعود: إن أولى الناس بي يوم القيامة أكثرهم صلاة علي)؟","title":"درجة حديث \"أولى الناس بي يوم القيامة..\"","answer":"الجواب: إسناده جيد إن أوْلى الناس بي يوم القيامة أكثرهم صلاة علي رواه أبو داود بإسناد جيد.","link":"https://binbaz.org.sa/fatwas/23005/درجة-حديث-اولى-الناس-بي-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث إن من أفضل أيامكم يوم الجمعة.. وحديث أولى الناس بي يوم القيامة أكثرهم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2865,"question":"الكَمْأةُ مِنَ المَنِّ؟","title":"ما صحة حديث \"الكَمْأةُ مِنَ المَنِّ\"؟","answer":"الجواب: الكَمْأةُ مِنَ المَنِّ، وماؤُها شِفاءٌ للعين صحيح، الحديث صحيح، والكَمْأةُ: الفقع يعني.","link":"https://binbaz.org.sa/fatwas/23019/ما-صحة-حديث-الكماة-من-المن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكمأة من المن.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2870,"question":"روى الطبري في تفسير وَسَلَامٌ عَلَى الْمُرْسَلِينَ [الصافات:181] الآية قال: حدثنا بشر قال حدثنا يزيد قال حدثنا سعيد عن قتادة قال: إذا سلّمتم عليّ فسلّموا على المرسلين فإنما أنا من المرسلين؟","title":"هل صح حديث \"فسلّموا على المرسلين\"؟","answer":"الجواب: هذا مُرْسَل، ما هو حُجّة.","link":"https://binbaz.org.sa/fatwas/23025/هل-صح-حديث-فسلموا-على-المرسلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث إذا سلمتم عليّ فسلموا على المرسلين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2880,"question":"في أبي داود: حدثنا سليمان بن داود المهري أنبأنا ابن وهب أخبرني جرير بن حازم وسَمَّى آخر عن أبي إسحاق عن عاصم بن ضمرة والحارث الأعور عن علي عن النبي ﷺ في بعض أول هذا الحديث قال: فإذا كانت زكاة مائة درهم وحال عليها الحول (ففيها خمسةُ دراهمَ)....","title":"ما صحة حديث: «إذا كانَت لَكَ مائتا درهمٍ..»؟","answer":"الجواب: معروف الحديث، المقصود أبو إسحاق فيه عنعنة، لكن الموقوف في حكم المرفوع؛ لأنه لا يقال من جهة الرأي، سواء كان مرفوعًا أو موقوفًا كله صحيح.\nالطالب: الحارث الأعور؟\nالشيخ: ضعيف، لكن معه عاصم بن ضَمرة، مع عاصم بن ضمرة لا بأس به.","link":"https://binbaz.org.sa/fatwas/23035/ما-صحة-حديث-اذا كانت لك-ماىتا درهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث فإذا كانت زكاة مائة درهم وحال عليها الحول..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2898,"question":"\"أفضل الذكر القرآن\" هل هو حديث أو أثر؟","title":"هل \"أفضل الذكر القرآن\" حديث؟","answer":"الجواب: جاء في حديث معناه: ما تقرب المتقربون إلى الله بشيء أفضل مما خرج منه. يعني القرآن، لكن في سنده بعض النظر، لكن أجمع العلماء على أن القرآن أفضل الذكر، محل إجماع، ما هو محل خلاف.","link":"https://binbaz.org.sa/fatwas/23053/هل-افضل-الذكر-القران-حديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أفضل الذكر القرآن هل هذا حديث.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2910,"question":"هل ورد عن الرسول ﷺ أنه قال: صلوا صلاة مُوَدِّع؟","title":"هل صح في الحديث: صلوا صلاة مُوَدِّع؟","answer":"الجواب: ما أذكر شيئًا في هذا، أقول: لا أعلم في هذا شيئًا من الأحاديث، إنما بعض السلف يُوصِي بذلك.","link":"https://binbaz.org.sa/fatwas/23066/هل-صح-في-الحديث-صلوا-صلاة-مودع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلوا صلاة مودع هل هذا حديث.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2922,"question":"حديث سعد بن أبي وقاص صحيح (أنه دخل مع رسول الله على امرأة وبين يديها نوى أو حصى تسبح به)؟","title":"حكم التسبيح بالنوى والسبحة ونحوها","answer":"الجواب: ما أذكر في سنده مقالًا، لكن يكفي فضلُ الذكر، يكفي الأحاديث الصحيحة الدالة على هذا الشيء.\nالطالب: في تخريجه أحسن الله إليك؟\nالشيخ: عندك التخريج عليه: حديث سبحان الله عدد ما خلق في السماء..؟\nالطالب: الشيخ سليم الهلالي.\nالشيخ: أيش قال عليه؟\nالطالب: قال: ضعيف أخرجه أبو داود والترمذي بإسناد ضعيف، فيه خزيمة راويه عن عائشة بنت طلحة وهو مجهول، وأصل الحديث عند مسلم من حديث جويرية دون ذكر النوى والحصى؛ مما يدل على نَكارة هذا اللفظ.\nالشيخ: حديث جويرية في مسلم: سبحان الله عدد خلقه، سبحان الله زنة عرشه، سبحان الله مداد كلماته، ثلاث مرات. وعلى كل حال الإكثار من ذكر الله مطلوب.\nس: ذكر النوى والحصى؟\nالشيخ: لا بأس به، لا بأس تسبح بالنوى أو بالعقد أو بالسبحة، لكن الأصابع أفضل.","link":"https://binbaz.org.sa/fatwas/23078/حكم-التسبيح-بالنوى-والسبحة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث سعد بن أبي وقاص أنه دخل مع رسول الله على امرأة وبين يديها نوى أو حصى.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2942,"question":"حديث عائشة رضي الله عنها أنها قالت: «ربما نام النبي ﷺ من جنابة ولم يمس ماء» صحيح؟","title":"ما حكم نوم الجُنُب دون غسل أو وضوء؟","answer":"الجواب: أعَلُّوه، فيه عِلة؛ لأنه من رواية أبي إسحاق السبيعي وقد عنعن. والمعروف عنه ﷺ أنه كان إذا أتى أهله توضأ وغسل فرجه وتوضأ ونام، وربما قَدَّم الغُسل، ما كان ينام إلا على وضوء مثلما قال لعمر: توضأ ثم نَمْ لما قال: يا رسول الله أينام وهو جُنُب؟ قال: لا، توضأ ثم نَمْ»، وفي اللفظ الآخر: يتوضأ وينام.\nس: إذا لم يتوضأ؟\nالشيخ: يُكره.","link":"https://binbaz.org.sa/fatwas/23098/ما-حكم-نوم-الجنب-دون-غسل-او-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث ربما نام النبي من جنابة ولم يمس ماء.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":2984,"question":"صحة حديث ابن مسعود الأخير (أسألك موجبات رحمتك)؟","title":"ما صحة حديث \"أسألك موجبات رحمتك\"؟","answer":"الجواب: ما راجعت سنده، عليه حاشية عندك؟\nالطالب: نعم، وفي سنده حميد الأعرج قال الذهبي في الميزان: متروك، وقال أحمد: ضعيف، وقال أبو زرعة: واهٍ، وقال الدارقطني: متروك.\nالشيخ: حتى لو ما ورد عن النبي ﷺ، الدعاء طيب.","link":"https://binbaz.org.sa/fatwas/23141/ما-صحة-حديث-اسالك-موجبات-رحمتك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث اللهم إني أسألك موجبات رحمتك.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3022,"question":"أتيتُ بحديث كِسْرى: تبشير النبي عليه الصلاة والسلام بقتله؟","title":"ما صحة وروايات حديث التبشير بقتل كِسْرى؟","answer":"الجواب: وأيش يقول؟\nالطالب: بسم الله الرحمن الرحيم. قال: بَابُ مَا جَاءَ فِي مَوْتِ كِسْرَى وَإِخْبَارِ النَّبِيِّ ﷺ بِذَلِكَ أَخْبَرَنَا أَبُو عَلِيٍّ الْحُسَيْنُ بْنُ مُحَمَّدٍ الرُّوذْبَارِيُّ، قَالَ: أَخْبَرَنَا إِسْمَاعِيلُ بْنُ مُحَمَّدٍ الصَّفَّارُ، قَالَ: حَدَّثَنَا أَحْمَدُ بْنُ الْوَلِيدِ الْفَحَّامُ، قَالَ: حَدَّثَنَا شَاذَانُ أَسْوَدُ بْنُ عَامِرٍ قَالَ: أَخْبَرَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ حُمَيْدٍ، عَنِ الْحَسَنِ، عَنْ أَبِي بَكْرَةَ، أَنَّ رَجُلًا مِنْ أَهْلِ فَارِسَ أَتَى النَّبِيَّ ﷺ، فَقَالَ ﷺ: إِنَّ رَبِّي قَدْ قَتَلَ رَبَّكَ يَعْنِي كِسْرَى. قَالَ: وَقِيلَ لَهُ -يَعْنِي النَّبِيَّ ﷺ- إِنَّهُ قَدِ اسْتَخْلَفَ ابْنَتَهُ، فَقَالَ: لَا يُفْلِحُ قَوْمٌ تَمْلِكُهُمُ امْرَأَةٌ. وَرُوِيَ فِي حَدِيثِ دِحْيَةَ بْنِ خَلِيفَةَ الْكَلْبِيِّ، أَنَّهُ لَمَّا رَجَعَ إِلَى النَّبِيِّ ﷺ مِنْ عِنْدِ قَيْصَرَ وَجَدَ عِنْدَهُ رُسُلَ عَامِلِ كِسْرَى عَلَى صَنْعَاءَ، وَذَلِكَ أَنَّ النَّبِيَّ ﷺ قَدْ كَانَ كَتَبَ إِلَى كِسْرَى، فَكَتَبَ كِسْرَى إِلَى صَاحِبِهِ بِصَنْعَاءَ يَتَوَعَّدُهُ وَيَقُولُ: أَلَا تَكْفِينِي رَجُلًا خَرَجَ بِأَرْضِكَ يَدْعُونِي إِلَى دِينِهِ، لَتَكْفِنِيهِ أَوْ لَأَفْعَلَنَّ بِكَ، فَبَعَثَ صَاحِبُ صَنْعَاءَ إِلَى النَّبِيِّ ﷺ، فَلَمَّا قَرَأَ النَّبِيُّ ﷺ كِتَابَ صَاحِبِهِمْ تَرَكَهُمْ خَمْسَ عَشْرَةَ لَيْلَةً، ثُمَّ قَالَ لَهُمْ: اذْهَبُوا إِلَى صَاحِبِكُمْ فَقُولُوا: إِنَّ رَبِّي قَدْ قَتَلَ رَبَّكَ اللَّيْلَةَ، فَانْطَلَقُوا فَأَخْبَرُوهُ، قَالَ دِحْيَةُ: ثُمَّ جَاءَ الْخَبَرُ بِأَنَّ كِسْرَى قُتِلَ تِلْكَ اللَّيْلَةَ.\nوَذَكَرَهُ أَيْضًا دَاوُدُ بْنُ أَبِي هِنْدٍ عَنْ عَامِرٍ الشَّعْبِيِّ بِمَعْنَاهُ، وَسَمَّى الْعَامِلَ الَّذِي كَتَبَ إِلَيْهِ كِسْرَى، فَقَالَ: بَاذَانُ صَاحِبُ الْيَمَنِ، فَلَمَّا جَاءَ بَاذَانَ الْكِتَابُ اخْتَارَ رَجُلَيْنِ مِنْ أَهْلِ فَارِسَ وَكَتَبَ إِلَى النَّبِيِّ ﷺ بِمَا كَتَبَ بِهِ كِسْرَى مِنْ رُجُوعِهِ إِلَى دِينِ قَوْمِهِ أَوْ تَوَاعُدِهِ يَوْمًا بِلِقَائِهِ فِيهِ، ثُمَّ ذَكَرَ مَعْنَاهُ فِي قَوْلِ النَّبِيِّ ﷺ: وَأَبْلِغَاهُ أَنَّ رَبِّي قَتَلَ رَبَّهُ فَكَانَ كَمَا أَخْبَرَ أَخْبَرَنَا أَبُو عَبْدِاللهِ الْحَافِظُ وَأَبُو سَعِيدِ بْنُ أَبِي عَمْرٍو، قَالَا: حَدَّثَنَا أَبُو الْعَبَّاسِ مُحَمَّدُ بْنُ يَعْقُوبَ قَالَ: حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، قَالَ: حَدَّثَنَا أَبُو بَكْرِ بْنُ عَيَّاشٍ، عَنْ دَاوُدَ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ: أَقْبَلَ سَعْدٌ إِلَى النَّبِيِّ ﷺ فَقَالَ: إِنَّ وَجْهَ سَعْدٍ خَيْرٌ، أَوْ قَالَ: الْخَيْرُ، قَالَ: قَالَ: يَا رَسُولَ اللهِ، هَلَكَ، أَوْ قَالَ: قُتِلَ كِسْرَى، فَقَالَ: لَعَنَ اللهُ كِسْرَى، أَوَّلُ النَّاسِ هَلَاكًا فَارِسُ ثُمَّ الْعَرَبُ.\nورجاله كالآتي: أبو عبدالله الحافظ هو محمد بن عبدالله الحاكم الإمام صاحب المستدرك، وأبو سعيد ابن أبي عمرو هو محمد بن موسى وثقة الذهبي، وأبو العباس الأصم هو محمد بن يعقوب السناني وثقه ابن خزيمة وأبو نعيم والذهبي وغيرهم، وقال عنه الذهبي في السير: سمع من الآباء والأبناء والأحفاد، وكفاه شرفا أن يحدث طول تلك السنين ولا يجد أحد فيه مغمزا بحجة، وأحمد بن يونس هو أحمد بن عبدالله بن يونس ينسب لجده ثقة حافظ من كبار العاشرة، روى له الجماعة، وأبو بكر بن عياش هو الأسدي المقرئ مشهور بكنيته والأصح أنها اسمه، رجح ذلك أبو الحجاج المزي في تهذيب الكمال، وابن حجر ثقة عابد إلا أنه لما كبر ساء حفظه، وكتابه الصحيح من السابعة روى مسلم في المقدمة وأهل السنن، وداود هو داود بن علي بن العباس بن عبدالمطلب الهاشمي أبو سليمان أمير مكة وغيرها مقبول من السادسة، روى له البخاري في الأدب المفرد والترمذي، وأبوه علي بن العباس ثقة عابد من الثالثة روى له البخاري في الأدب المفرد ومسلم وأهل السنن، وقال الإمام أحمد في مسنده: حدثنا أسود بن عامر حدثنا حماد بن سلمة عن حميد عن الحسن عن أبي بكرة رضي الله عنه أن رجلا من أهل فارس أتى النبي ﷺ فقال: إن ربي تبارك وتعالى قد قتل ربك -يعني كسرى- قال فقيل له يعني النبي صلى الله عليه وسلم إنه قد استخلف ابنته، قال: فقال: لا يفلح قوم ولوا أمرهم امرأة قلت: هذه العبارة الأخيرة رواها البخاري في صحيحه، والحديث بكامله رواه البيهقي في دلائل النبوة من طريق أسود بن عامر، قال الألباني بعده في الصحيحة: وإسناده على شرط مسلم ولا علة فيه سوى ما يخشى من عنعنة الحسن البصري من التدليس، ولكنه صرح بالتحديث في رواية أخرى عند أحمد؛ فصح الحديث والحمد لله.\nوأخرج أبو نعيم عن دحية بن خليفة الكلبي أن النبي ﷺ قال: اذهبوا إلى صاحبكم فأخبروه أن ربي قد قتل ربه الليلة يعني كسرى، وصححه الألباني في صحيح الجامع، ولم أقف على سنده عند أبي نعيم.\nورواه ابن جريج الطبري في التاريخ عن يزيد بن أبي حبيب مرسلًا.\nالشيخ: بارك الله فيك، فيه الإخبار بموته، لا بأس به، السند الأول مقبول، لكن له شاهد، الثاني يكون به حَسَنًا.","link":"https://binbaz.org.sa/fatwas/23181/ما-صحة-وروايات-حديث-التبشير-بقتل-كسرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث كسرى، تبشير النبي بقتله.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3035,"question":"صحة قول الرسول ﷺ: ما ينبغي لنبي أن يكون له خائنة أعْين؟","title":"ما صحة أنه لا ينبغي لنبي خائنة الأعْين؟","answer":"الجواب: ما أذكر، لكن الذي يغلب على ظني أنه لا بأس بإسناده.","link":"https://binbaz.org.sa/fatwas/23195/ما-صحة-انه-لا-ينبغي-لنبي-خاىنة-الاعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حديث ما ينبغي لنبي أن يكون له خائنة أعين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3040,"question":"حديث \"لا غِيبة لفاسق\"؟","title":"ما صحة حديث \"لا غِيبة لفاسق\"؟","answer":"الجواب: ما أعرف له أصلًا، لكن مأخوذ من الأحاديث الصحيحة، لما دخل عليه رجل قال: ائذنوا له بئس أخو العشيرة، وفي لفظ بئس ابن العشيرة فدل على أن مَنْ أظهر الشر لا بأس، والحديث الذي تقدم كما سمعتم أنه مر عليه بجنازة فأثنوا عليها شرًّا فقال: وجبت فإذا أظهر الشر وبارز بالمعاصي ما له غِيبة فيما أظهر، نسأل الله العافية.\nس: ممكن الكلام فيه؟\nالشيخ: حتى بعد موته إذا دعت الحاجة إلى ذلك؛ لئلا يُغْتَرَّ به.","link":"https://binbaz.org.sa/fatwas/23200/ما-صحة-حديث-لا-غيبة-لفاسق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لا غيبة لفاسق.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3044,"question":"حديث مَنْ ردّ عن عِرْض... معي إسناده..؟","title":"ما صحة حديث \"مَنْ ردّ عن عِرْض أخيه\"؟","answer":"الجواب: الظاهر أنه لا بأس به.\nالطالب: قال الإمام أحمد رحمه الله تعالى: حدثنا إسماعيل عن ليث عن شهر بن حوشب عن أم الدرداء عن أبي الدرداء عن النبي ﷺ قال: من رد عن عرض أخيه المسلم كان حقًّا على الله جل وعلا أن يرد عنه نار جهنم يوم القيامة وفي سنده ليث بن أبي سليم خرج له الأربعة ومسلم مقرونًا، وقال الإمام أحمد في رواية المروذي في العلل: ليس هو بذاك، وقال فيه مرة أخرى: مضطرب الحديث، ولكن حدث عنه الناس، وضعفه يحيى والنسائي، وقال ابن معين: لا بأس به، وشهر بن حوشب الأشعري مولى أسماء بنت يزيد بن السكن خرج له الأربعة ومسلم مقرونًا، قال الإمام أحمد: روى عن أسماء بنت يزيد بن السكن أحاديث حسان، وقال في رواية حرب الكرماني: ما أحسن حديثه، ووثقه، وقال في رواية حنبل: ليس به بأس، وروى ابن أبي خيثمة ومعاوية بن صالح عن ابن معين قال: ثقة، وقال أبو حاتم: ليس هو بدون أبي الزبير، ولا يحتج به، وقال أبو زرعة: لا بأس به، وقال النسائي وابن عدي: ليس بقوي.  وخرّجه الإمام أحمد رحمه الله تعالى من طريق آخر قال: حدثنا علي بن إسحاق قال أخبرنا عبدالله يعني ابن المبارك قال أخبرنا أبو بكر النهشلي عن مرزوق أبي بكير التيمي عن أم الدرداء عن أبي الدرداء عن النبي ﷺ قال: من رد عن عرض أخيه رد الله عن وجهه النار يوم القيامة. ومن هذا الطريق أيضًا خرّجه الترمذي كما في سننه، وأبو بكر النهشلي هو الكوفي ابن عبدالله بن أبي القطاف، وقيل ابن قطاف، وقيل اسمه عبدالله بن قطاف، وقيل ابن معاوية، قال أبو داود: ثقة كوفي، وقال عبد الله بن الإمام أحمد عن أبيه: ثقة، ووثقه ابن معين والعجلي وابن مهدي، وقال أبو حاتم: شيخ صالح يكتب حديثه، ومرزوق أبو بكير التيمي الكوفي اختلف في اسمه فذكره الذهبي رحمه الله تعالى في ميزان الاعتدال فقال: مرزوق وأبو بكر عن أم الدرداء ما روى عنه سوى أبي بكر النهشلي، أما في التهذيب فشك ابن حجر فقال: مرزوق أبو بكر التيمي عن أم الدرداء عن أبي الدرداء عن النبي ﷺ قال: مَن ردّ عن عِرْض أخيه الحديث، وعنه أبو بكر النهشلي خرج له الترمذي ثم قال بعد ذلك: أظنه الذي بعده، ثم ذكر تمييز مرزوق أبو بكير التيمي الكوفي مؤذن لتيم روى عن سعيد بن جبير وعكرمة ومجاهد وعنه ليث بن أبي سليم وإسرائيل وعمر بن محمد بن زيد العمري والثوري وشريك ذكره ابن حبان في الثقات، وقال أصله من الكوفة وسكن الري، وفي التقريب قال مرزوق: أبو بكر التيمي مقبول من السادسة، خرج له الترمذي، وقال مرزوق أبو بكير بالتصغير التيمي الكوفي المؤذن سكن الري من السادسة أيضًا. تمييز.\nوقال المنذري رحمه الله على هذا الحديث: رواه الإمام أحمد بسند حسن، وأبو الشيخ الأصبهاني في التوبيخ ولفظه: مَن ذَبّ عن أخيه ردّ الله عنه عذاب النار يوم القيامة، وتلا رسول الله ﷺ:  وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ [الروم:47]. وتكلم على ذلك الدارقطني كما في كتابه العلل في السؤال الواحد والتسعين بعد الألف، وسئل عن حديث أم الدرداء عن أبي الدرداء قال: قال رسول الله ﷺ: من رد عن عرض أخيه كان حتمًا على الله أن يرد عنه نار جهنم، ثم قال: إِنَّا لَنَنْصُرُ رُسُلَنَا وَالَّذِينَ آمَنُوا [غافر:51]. يرويه ليث بن أبي سليم، واختلف عنه، ورواه أبو بكر بن عياش وجرير بن عبدالحميد ومعتمر بن سليمان وموسى بن أعين واختلف عنه فيه، واختلف عن ليث عن شهر عن أم الدرداء عن أبي الدرداء عن النبي ﷺ، ووقفه عبدالسلام بن عبدالحميد عن موسى بن أعين فقال علي بن معبد عن موسى بن أعين عن ليث عن عمرو بن مرة عن شهر عن أم الدرداء عن أبي الدرداء عن النبي ﷺ، وليس بمحفوظ، والصواب: قول من قال: عن ليث عن شهر. انتهى قوله. الشيخ: على كل حال الحديث حسن جيّد، وكل سند يَعْْضُد آخر.\nس: ما الراجح في مرزوق أبو بكر هل هما اثنان؟\nالشيخ: الله أعلم.","link":"https://binbaz.org.sa/fatwas/23204/ما-صحة-حديث-من-رد-عن-عرض-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سند حديث من رد عن عرض أخيه.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3084,"question":"حديث ابن عباس (لا تشربوا كشرب البعير) صحيح، أحسن الله إليك؟","title":"ما صحة حديث \"لا تشربوا كشرب البعير\"؟","answer":"الجواب: أيش؟\nس: لا تشربوا كشرب البعير؟\nالشيخ: ما تتبعته، ما راجعت سنده، عندك عليه الحاشية على حديث ابن عباس.\nالطالب: رواه الترمذي وفي سنده يزيد بن سنان أبو فروة الرهاوي، وهو ضعيف وشيخه فيه متروك، لذا ضعفه الحافظ في الفتح.\nالشيخ: لكن يكفي عنه غيره، كان يتنفس في الإناء ثلاثًا عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23244/ما-صحة-حديث-لا-تشربوا-كشرب-البعير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لا تشربوا كشرب البعير.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3098,"question":"حديث: صلاة بسواك خير من سبعين صلاة بغير سواك؟","title":"درجة حديث: \"صلاة بسواك خير من سبعين\"","answer":"الجواب: الشيخ: في سنده نظر، ذكره ابن القيم رحمه الله في رسالة، محل نظر.","link":"https://binbaz.org.sa/fatwas/23258/درجة-حديث-صلاة-بسواك-خير-من-سبعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث صلاة في سواك خير من سبعين صلاة بغير سواك.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3110,"question":"قوله ﷺ: فَمَنْ نَسِيَ فليَسْتقِئ؟","title":"ما صحة حديث \"فَمَنْ نَسِيَ فليَسْتقِئ\"؟","answer":"الجواب: هذا منسوخ؛ لأن النبي ﷺ شَرِب قائمًا ولم يَسْتقِئ.","link":"https://binbaz.org.sa/fatwas/23270/ما-صحة-حديث-فمن-نسي-فليستقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث فمن نسي فليستقئ.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3119,"question":"حديث: من قرأ الواقعة كل ليلة لم تصبه فاقة؟","title":"ما درجة حديث فضل سورة الواقعة؟","answer":"الجواب: ضعيف، حديث ضعيف.","link":"https://binbaz.org.sa/fatwas/23279/ما-درجة-حديث-فضل-سورة-الواقعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث من قرأ الواقعة كل ليلة لم تصبه فاقة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3127,"question":"صحة حديث ابن عباس البسوا من ثيابكم البياض..؟","title":"درجة حديث \"البسوا من ثيابكم البياض\"","answer":"الجواب: كلها صحيحة، حديث سمرة وحديث ابن عباس.\nس ما المقصود من قوله ﷺ: فإنها أطهر وأطيب هل الطهارة حسية أم معنوية؟\nالشيخ: الله أعلم.","link":"https://binbaz.org.sa/fatwas/23288/درجة-حديث-البسوا-من-ثيابكم-البياض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث البسوا من ثيابكم البياض..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3130,"question":"صحة حديث \"وعليه ثوبان أخضران\"؟","title":"ما صحة حديث \"وعليه ثوبان أخضران\"؟","answer":"الجواب: هذا حديث أبي رِمْثة، لا بأس به، واللفظ الأخر: طاف وعليه بُرْد أخضر كذلك.","link":"https://binbaz.org.sa/fatwas/23291/ما-صحة-حديث-وعليه-ثوبان-اخضران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث رأيت رسول الله وعليه ثوبان أخضران.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3162,"question":"حديث إن الله يُحِبُّ أنْ يُرَى أثَرُ نعمته على عبده سند الحديث معي أحسن الله إليك.","title":"ما صحة حديث \"يُحِبُّ أن يُرَى أثرُ نعمته..\"؟","answer":"الجواب: نعم.\nالطالب: يقول: حدثنا الحسن بن محمد الزعفراني أخبرنا عفان بن مسلم أخبرنا همام عن قتادة عن عمرو بن شعيب عن أبيه عن جده قال: قال رسول الله ﷺ: إن الله يحب أن يُرَى أثرُ نعمته على عبده وفي الباب عن أبي الأحوص عن أبيه وعمران بن حصين وابن مسعود قال أبو عيسى: هذا حديث حسن.\nالشيخ: مثل ما قال: حسن صحيح لولا عنعنة قتادة، وإلا الرجال كلهم ثقات؛ لأن قتادة مدلس وقد عنعن، ولكن ذكر شواهده المؤلف وشواهده كثيرة خير الصدقة ما كان عن ظَهْر غِنى، واليد العليا خير من اليد السفلى، كثيرة، فالإنسان يُظهر نعمة الله عليه ولا يتشبّه بالفقراء والله قد أغناه.\nالطالب: في حاشية.\nالشيخ: نعم.\nالطالب: يقول: رواه الترمذي وإسناده حسن، وفي الباب عن أبي الأحوص أن أباه أتى النبي ﷺ وهو أشعث سيئ الهيئة فقال له رسول الله ﷺ: أما لك مال؟ قال: من كل المال قد آتاني الله ، فقال: فإن الله  إذا أنعم على عبد نعمة أحب أن تُرى عليه أخرجه أحمد والنسائي وإسناده قوي.\nالشيخ: معناه مثل ما دلّ عليه الحديث، لكن إذا لبس الإنسان البِذْلَة من باب كَسْر النفس وكَسْر التَّكَبُّر؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/23325/ما-صحة-حديث-يحب-ان-يرى-اثر-نعمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سند حديث إن الله يحب أن يرى أثر نعمته على عبده.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3191,"question":"صحة حديث عمرو بن شعيب \"لا يَحِلُّ لرَجُل أنْ يُفَرِّق بين اثنين\"؟","title":"ما صحّة حديث \"لا يَحِلُّ لرَجُل أنْ يُفَرِّق..\"؟","answer":"الجواب: النهي عن التفريق بين اثنين؟\nالطالب: نعم.\nالشيخ: مثل ما تقدّم لا يقيم الرجلُ الرجلِ مِنْ مَجْلِسه.. هو مثله في المعنى.","link":"https://binbaz.org.sa/fatwas/23354/ما-صحة-حديث-لا-يحل-لرجل-ان-يفرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لايحل لرجل أن يفرق بين اثنين..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3195,"question":"صحة حديث حذيفة \"لَعَن مَن جلسَ وسط الحلقة\"؟","title":"ما صحّة حديث \"لَعَن مَن جلسَ وسط الحلقة\"؟","answer":"الجواب: لا أعلم به بأسًا، لا أعرف به بأسًا.\nالطالب: الإسناد معي يقول: حدثنا موسى بن إسماعيل أخبرنا أبان أخبرنا قتادة حدثني أبو مجلز عن حذيفة «أن رسول الله ﷺ \"لَعَن مَن جلسَ وسط الحلقة».\nالشيخ: هذا سند صحيح.","link":"https://binbaz.org.sa/fatwas/23358/ما-صحة-حديث-لعن-من-جلس-وسط-الحلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لعن رسول الله من جلس وسط الحلقة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3196,"question":"صحة حديث أبي برزة: كان رسول الله ﷺ يقول بآخره إذا أراد أن يقوم من المجلس: سبحانك اللهم وبحمدك ...؟","title":"درجة حديث كفارة المجلس (سبحانك اللهم..)؟","answer":"الجواب: أصل الحديث ثابت، ذكره المفسرون عند قوله: وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ [الطور:48] جاء في سورة الطور.\nالطالب: إسناد الحديث معي.\nالشيخ: ما يخالف.\nالطالب: حدثنا محمد بن حاتم الجرجرائي وعثمان بن أبي شيبة المعنى أن عبدة بن سليمان أخبرهم عن الحجاج بن دينار عن أبي هاشم عن أبي العالية عن أبي برزة.\nالشيخ: أبو هاشم عندك حاشية؟\nالطالب: يقول وأبو هاشم -هذا في عون المعبود- وأبو هاشم هو الرماني من رجال الصحيحين بس.\nالشيخ: تكلم على الحجاج بن دينار؟\nالطالب: الحجاج بن دينار صدوق وثقه غير واحد.\nالشيخ: سنده جيد لا بأس.","link":"https://binbaz.org.sa/fatwas/23359/درجة-حديث-كفارة-المجلس-سبحانك-اللهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث كان رسول الله يقول بآخره إذا أراد أن يقوم من المجلس.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3199,"question":"صحة حديث: إلا قاموا عن مثل جيفة حمار؟","title":"درجة حديث \"إلا قاموا عن مثل جيفة حمار\"","answer":"الجواب: ما راجعت أصله، لكن مشهور الحديث.\nالطالب: سند الحديث معي، أحسن الله إليك.\nالشيخ: نعم.\nالطالب: يقول: حدثنا محمد بن الصباح البزاز أخبرنا إسماعيل بن زكريا عن سهيل بن أبي صالح عن أبيه عن أبي هريرة قال: قال رسول الله ﷺ: ما من قوم يقومون من مجلس لا يذكرون الله فيه إلا قاموا عن مثل جِيفة حمار وكان لهم عليهم حسرة.\nالشيخ: سنده جيد.","link":"https://binbaz.org.sa/fatwas/23362/درجة-حديث-الا-قاموا-عن-مثل-جيفة-حمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إلا قاموا عن مثل جيفة حمار.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3204,"question":"هل عن النبي ﷺ حديث أن العبد إذا انتهى من صلاته لا يقومن مِن مقامه حتى ينتهي مِن ذِكْره أم لا؟","title":"ما حكم القيام بعد الصلاة قبل إكمال أذكارها؟","answer":"الجواب: ما بلغني شيء، لكن هذا هو الأفضل يُكْمِل الذكر المشروع.\nس: لكن ليس على الوجوب؟\nالشيخ: لا ما هو على الوجوب، إذا سلّم انتهت الصلاة.","link":"https://binbaz.org.sa/fatwas/23367/ما-حكم-القيام-بعد-الصلاة-قبل-اكمال-اذكارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا انتهى العبد لا يقومن حتى ينتهي من ذكره هل في هذا حديث.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3206,"question":"صحة الحديث \"الرؤيا على جناح طائر\"؟","title":"ما درجة حديث \"الرؤيا على جناح طائر..\"؟","answer":"الجواب: ضعيف.","link":"https://binbaz.org.sa/fatwas/23369/ما-درجة-حديث-الرويا-على-جناح-طاىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث الرؤيا على جناح طائر.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3256,"question":"حديث عائشة «أن النبي ﷺ قَبَّل بعض نسائه ثم خرج إلى الصلاة ولم يتوضأ» صحيح؟","title":"هل صح حديثُ التقبيل دون إعادة الوضوء؟","answer":"الجواب: نعم جيد، رواه أحمد بإسناد جيد، قال أحمد: حدثنا وكيع عن هشام بن عروة عن أبيه عن عائشة.  السند على شرط الصحيح، ورواه النسائي وفيه انقطاع، لكنه شاهد لهذا.","link":"https://binbaz.org.sa/fatwas/23420/هل-صح-حديث-التقبيل-دون-اعادة-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أن النبي قبّل بعض نسائه ثم خرج إلى الصلاة ولم يتوضأ.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3295,"question":"حديث الحاكم: لا تَسُبُّوا ورقة بن نوفل، فإني رأيت له جنة أو جنتين؟","title":"ما درجة حديث \"لا تَسُبُّوا ورقة بن نوفل\"؟","answer":"الجواب: ما أعرف حاله، لكن ظاهر السياق هنا يدل على إسلامه؛ لأنه قال: (هذا الناموس) أقر به، وقال: (ليتني فيها جذعًا) (لئن أدركني زمانك لأنصرنك نصرًا مؤزرًا) كل هذا يدل على إسلامه وإيمانه.","link":"https://binbaz.org.sa/fatwas/23460/ما-درجة-حديث-لا-تسبوا-ورقة-بن-نوفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لا تسبوا الورقة بن نوفل..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3297,"question":"حديث أن \"خالد بن سنان نَبِيٌّ ضَيّعَه قومه\" صحيح؟","title":"هل صح أثر\"خالد بن سنان نَبِيٌّ ضَيّعَه قومه\"؟","answer":"الجواب: لا أعرف له أصلاً.","link":"https://binbaz.org.sa/fatwas/23462/هل-صح-اثرخالد-بن-سنان-نبي-ضيعه-قومه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أن خالد بن سنان نبي ضيعه قومه.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3316,"question":"\"إن من عبادي من لا يُصْلِحُه إلا الغِنَى ولو أفقرته لأفسده ذلك\" صِحَتُه؟","title":"هل صَحَّ: مِنْ عبادي من لا يُصْلِحُه إلا الغِنَى؟","answer":"الجواب: هذا أثر إسرائيلي، ما أذكر له سندًا صحيحًا، لكن معناه صحيح.","link":"https://binbaz.org.sa/fatwas/23482/هل-صح-من-عبادي-من-لا-يصلحه-الا-الغنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إن من عبادي من لا يصلحه إلا الغنى..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3374,"question":"(المستحاضة) لها أن تَجْمَع؟","title":"هل يجوز للمستحاضة جمع الصلاة؟","answer":"الجواب: ولها أن تَجْمَع إذا دعت الحاجة إلى هذا، لها أن تجمع كما أذِن لحمنة.","link":"https://binbaz.org.sa/fatwas/23542/هل-يجوز-للمستحاضة-جمع-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تجمع المستحاضة بين الصلاة.mp3","categories":["الطلاق","الحيض والنفاس","قضايا المرأة"]},{"id":3474,"question":"المَسْحُور إذا طَلّق امرأته؟","title":"ما حكم طلاق المَسْحُور؟","answer":"الجواب: إذا كان عقله معه يَنْفُذُ الطلاق.","link":"https://binbaz.org.sa/fatwas/23651/ما-حكم-طلاق-المسحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم طلاق المسحور.mp3","categories":["الطلاق"]},{"id":3475,"question":"في كلام لشيخ الإسلام في الاقتضاء عن حديث: مَنْ سَكَنَ البادية جَفا شيخ الإسلام ذكره في الاقتضاء، وقال: قال رحمه الله: ولهذا روى أبو داود، وغيره من حديث الثوري حدثني أبو موسى عن وهب بن منبه، عن ابن عباس رضي الله عنهما، عن النبي ﷺ - قال سفيان مرة: ولا أعلمه إلا عن النبي ﷺ- قال: من سكن البادية جفا، ومن اتبع الصيد غفل، ومن أتى السلطان افتتن.ورواه أبو داود أيضًا من حديث الحسن بن الحكم النخعي عن عدي بن ثابت عن شيخ من الأنصار، عن أبي هريرة ، عن النبي ﷺ - بمعناه -، وقال: ومن لزم السلطان افتتن، وزاد: وما ازداد عبد من السلطان دنوًا إلا ازداد من الله  بُعدًا، ولهذا كانوا يقولون لمن يستغلظونه: إنك لأعرابي جافٍ، إنك لجِلْفٌ جاف، يشيرون إلى غِلَظِ عقله وخلقه.","title":"الحكم على حديث \"مَنْ سَكَنَ البادية جَفا\"","answer":"الجواب: الطريقان كلاهما ضعيف، الثانية فيها شيخ مجهول، والأولى فيها أبو موسى مجهول.\nس: وطريق أحمد الأخير؟\nالشيخ: كلاهما ضعيف.\nس: السند هذا يا شيخ: حدثنا محمد قال: حدثنا إسماعيل بن زكريا عن الحسن بن الحكم النخعي عن عدي بن ثابت عن أبي حازم عن أبي هريرة.\nالشيخ: ينظر في الحسن بن الحكم أيش قال عليه؟\nالطالب: الحسن بن الحكم هو النخعي أبو الحكم الكوفي صدوق يخطئ من السادسة.\nالشيخ: هذا من التقريب؟\nالطالب: نعم، وعدي بن ثابت ثقة رمي بالتشيع من الرابعة.\nالشيخ: ظاهر هذا أنه قد يشهد له البقية، ويشهد له الواقع؛ لأن السكنى في البادية لا شك أنها من أسباب الجَفا، واتّباع الصيد، والشُّغل بالصيد غفلة، ولزوم السلاطين لا شك أنه من أسباب الفتنة، يشهد بعضها لبعض.","link":"https://binbaz.org.sa/fatwas/23652/الحكم-على-حديث-من-سكن-البادية-جفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كلام شيخ الاسلام بن تيمية عن حديث من سكن البادية جفا.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3707,"question":"إذا كانت الزوجة الأولى رفضت أن تعيش مع الثانية بعد الزواج، وطلبت الطلاق، ما حكم الطلاق؟","title":"هل تطلق الزوجة لرفضها العيش مع أخرى؟","answer":"الجواب: ما يلزمه طلاقها، عليها أن تخضع لحكم الله وتصبر.\nس: هي طلبت الطلاق ورفضت تعود؟\nالشيخ: إذا أحب يطلقها لا بأس، لكن ما يلزمه، إذا أحب يطلقها لا بأس.","link":"https://binbaz.org.sa/fatwas/23898/هل-تطلق-الزوجة-لرفضها-العيش-مع-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلاق الزوجة الأولى إذا رفضت العيش مع الزوجة الثانية.mp3","categories":["الطلاق"]},{"id":3726,"question":"حديث أم سلمة أوعمياوان أنتما؟","title":"الحكم على حديث \"أو عمياوان أنتما\"","answer":"الجواب: ضعيف، هذا ضعيف، ولهذا يجوز أن ترى المرأة الكفيف ولا تحتجب عنه، قال النبي ﷺ لفاطمة بنت قيس: اعْتَدِّي عند ابن أم مكتوم فإنه رجل أعمى تضعين ثيابك فلا يراك، وقال ﷺ في الاستئذان: إنما جعل الاستئذان من أجل النظر.","link":"https://binbaz.org.sa/fatwas/23918/الحكم-على-حديث-او-عمياوان-انتما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أوعمياوان أنتما.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3805,"question":"سؤال عن حديث أبي ثعلبة الخشني [إنا بأرض قوم من أهل الكتاب، أفنأكل في آنيتهم...]؟","title":"هل صح حديث أبي ثعلبة \"أفنأكل في آنيتهم\"؟","answer":"الجواب: لا بأس بسنده، لكن أحسن ما يُقال فيه: إنه شاذٌّ مخالفٌ للأحاديث الصحيحة؛ لأنَّ القاعدة: إذا خُولف الصحيح فهو دونه، ويكون المخالف شاذًّا؛ لأن حديث عدي في \"الصحيحين\" وثابت ومعلّل، وهو ظاهر القرآن أيضًا: فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ [المائدة:4].  وحديث أبي ثعلبة عند أبي داود وبعض السنن، وإن كان سنده ماشيًا.....، لكن مخالف للأحاديث الصحيحة، مثل: حديث عدي، وابن عباس، وأيضًا مخالف لظاهر القرآن، فإنه... ما أمسك عليه إنما أمسك على نفسه.\nس: يكون هذا من باب الترجيح؟\nج: نعم، أحسن ما قيل فيه الترجيح، مثلما قيل في أحاديث كثيرة مثل: الوضوء من مسِّ الذكر، أحاديث كثيرة فيها الترجيح، والقاعدة أنه إذا لم يتيسر الجمع ولا النسخ ولا توفرت شروطه ما بقي إلا الترجيح.\nس: ويسمى هذا شذوذاً أو ترجيحًا؟\nج: الشاذ يرجّح عليه الصحيح، ويُسمَّى المرجوح: شاذًّا، شرط الصحيح ألا يكون شاذًّا، فإذا شذَّ صار ضعيفًا، ولو استقام سنده.","link":"https://binbaz.org.sa/fatwas/24006/هل-صح-حديث-ابي-ثعلبة-افناكل-في-انيتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إنا بأرض قوم من أهل الكتاب، أفنأكل في آنيتهم...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3838,"question":"حديث الفضة فالعبوا بها كيف شئتم؟","title":"ما صحة \"الفضة فالعبوا بها كيف شئتم\"؟","answer":"الجواب: في صحته نظر، والظاهر أنه شاذ مخالف للأحاديث الصحيحة؛ لأن فيها التحريم من لبس الذهب...، واحتج به من حرم الحلقة، ويظهر من الأحاديث أنه حديث شاذ، ومن أدلة شذوذه وعدم صحته قول: الفضة فالعبوا بها لعبًا، هذا يُستغرب أن يقوله النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/24040/ما-صحة-الفضة-فالعبوا-بها-كيف-شىتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث الفضة فالعبوا بها كيف شئتم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3852,"question":"حديث: إذا تغوَّلت الغيلان صحته؟","title":"درجة حديث \"إذا تغوَّلت لكم الغيلان..\"","answer":"الجواب: ما أعرف حاله، لكن ظاهر كلام المؤلف أنه صحيح؛ لأنه احتجّ به وسكت عنه، والذي يغلب على ظني أنه لا بأس به مثلما سكت عنه المؤلف.","link":"https://binbaz.org.sa/fatwas/24061/درجة-حديث-اذا-تغولت-لكم-الغيلان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إذا تغوَّلت الغيلان.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":3984,"question":"ما عُبِّد وحُمِّد؟","title":"هل صح أن \"خَيْرَ الأسماء ما عُبِّد وحُمِّد\"؟","answer":"الجواب: ما له أصل، \"خَيْرُ الأسماء ما عُبِّد وحُمِّد\" ما له أصل.","link":"https://binbaz.org.sa/fatwas/24212/هل-صح-ان-خير-الاسماء-ما-عبد-وحمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث خير الأسماء ما عبد وحمد.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4023,"question":"حديث إذا تصافح المؤمنان تحاتت خطاياهما؟","title":"هل صح الحديث في المغفرة للمتصافحين؟","answer":"الجواب: لا بأس به، جاء في عدة أحاديث إذا تلاقيا وتصافحا، وفي بعضها فحمدا الله واستغفراه غفر لهما، يشدّ بعضها بعضًا.","link":"https://binbaz.org.sa/fatwas/24259/هل-صح-الحديث-في-المغفرة-للمتصافحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إذا تصافح المؤمنان تحاتت خطاياهما...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4076,"question":"رواية \"الدعاء مخ العبادة\"؟","title":"درجة حديث \"الدعاء مخ العبادة\"","answer":"الجواب: الرواية فيها ضعف .... الدعاء هو العبادة  في الحديث الصحيح.","link":"https://binbaz.org.sa/fatwas/24315/درجة-حديث-الدعاء-مخ-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رواية الدعاء مخ العبادة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4259,"question":"ما صحة حديث عائشة: لا نَذْر في معصية...؟","title":"الحكم على حديث \"لا نذر في معصية\"","answer":"الجواب: لا بأس به، نعم، وله شواهد أيضًا عن ابن عباس وغيره.","link":"https://binbaz.org.sa/fatwas/24529/الحكم-على-حديث-لا-نذر-في-معصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لا نذر في معصية، وكفارته كفارة يمين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4289,"question":"الرجل إذا قال لزوجته هي عليه حرام بنية الطلاق يكون طلاقًا؟","title":"حكم من قال لزوجته هي عليه حرام بنية الطلاق","answer":"الجواب: لا - يكون ظهارًا .","link":"https://binbaz.org.sa/fatwas/24561/حكم-من-قال-لزوجته-هي-عليه-حرام-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقع الطلاق إذا قال لزوجته هي عليه حرام بنية الطلاق.mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":4323,"question":"حديث: إنما أخاف على أمتي الأئمة المضلين درجته؟","title":"درجة حديث \"أخاف على أمتي الأئمة المضلين\"","answer":"الجواب: لا بأس به، حديث معتبر رواه جماعة، وجاء في معناه أحاديث صحيحة كثيرة.","link":"https://binbaz.org.sa/fatwas/24598/درجة-حديث-اخاف-على-امتي-الاىمة-المضلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إنما أخاف على أمتي الأئمة المضلين.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4339,"question":"ما صحة حديث النبي ﷺ: من استعاذ بالله فقد عاذ بمعاذ؟","title":"درجة حديث \"من استعاذ بالله فقد عاذ بمعاذ\"","answer":"الجواب: نعم هذا صحيح، في قصة المرأة التي أراد أن يتزوجها ولم استعاذت منه قال: لقد عذت بمعاذ، الحقي بأهلك هذا في البخاري.\nس: هذا اللفظ؟\nج:  نعم، لقد عذت بمعاذ الحقي بأهلك.","link":"https://binbaz.org.sa/fatwas/24614/درجة-حديث-من-استعاذ-بالله-فقد-عاذ-بمعاذ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث من استعاذ بالله فقد عاذ بمعاذ.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4341,"question":"هذا امرأة عقد عليها زوجها ثم بعد ذلك اتضح أن في عضوه شيء من الخلايا السرطانية، فأخذت تتكلم وتشاءمت، فهل يجوز لها أن تطلب منه الطلاق؟ وهل هذا من التشاؤم يعتبر؟","title":"ما يحلُّ لمن اكتشفت مرضًا بزوجها بعد العقد","answer":"الجواب: لا ما هو من التشاؤم، هذا من باب الاحتياط، إذا طلبت الطلاق فلا بأس، إذا ثبت أنه السرطان وما أشبه هذا عذر شرعي، هذا ما هو من التشاؤم، هذا من البعد عن الخطر.\nس: هو عالج نفسه وطاب؟\nالشيخ: إذا طاب الحمد لله.\nالطالب: لكن ما زالت تطالبه بالطلاق؟\nالشيخ: لا، لا ينبغي لها أن تطالب.","link":"https://binbaz.org.sa/fatwas/24616/ما-يحل-لمن-اكتشفت-مرضا-بزوجها-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عقد عليها زوجها ثم بعد العقد اتضح أن فيه مرضا.mp3","categories":["الطلاق"]},{"id":4347,"question":"حديث: العلم فريضة على كل مسلم؟","title":"الحكم على حديث \"العلم فريضة على كل مسلم\"","answer":"الجواب: لا بأس به له طرق جيدة يشد بعضها بعضا، فريضة على كل مسلم، يعني: طلب العلم الشرعي الذي يعرف به دينه.","link":"https://binbaz.org.sa/fatwas/24622/الحكم-على-حديث-العلم-فريضة-على-كل-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث العلم فريضة على كل مسلم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4382,"question":"المطلقة ثلاثًا هل لها النفقة والسكنى؟","title":"هل للمطلقة ثلاثًًا النفقة والسكنى؟","answer":"الجواب: إذا حكم ببينونتها ليس لها شيء، بينونتها بثلاث أو بالخلع، ما لها النفقة، للرجعية التي لها رجعة إذا كان له رجعة عليها.","link":"https://binbaz.org.sa/fatwas/24659/هل-للمطلقة-ثلاثا-النفقة-والسكنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للمطلقة ثلاثًا النفقة والسكنى.mp3","categories":["الطلاق"]},{"id":4392,"question":"أفضل الأسماء ما حمُّد وعُبّد؟","title":"هل صح أن أفضل الأسماء ما حمُّد وعُبّد؟","answer":"الجواب: ما له أصل، ليس له أصل، الصحيح: أحب الأسماء إلى الله عبدالله، وعبدالرحمن يعني ما عبد لله.\nس: هذا موضوع؟\nج: ما له أصل، ما له أساس.","link":"https://binbaz.org.sa/fatwas/24669/هل-صح-ان-افضل-الاسماء-ما-حمد-وعبد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أفضل الأسماء ما حمُّد وعُبّد.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4435,"question":"حديث يأتي قومٌ يصبغون كحواصل الحمام صحيح؟","title":"درجة حديث \"قومٌ يصبغون كحواصل الحمام\"","answer":"الجواب: لا بأس به، إسناده جيد، بعضهم أعلَّه بأنَّ فيه عبدالكريم....، وهو غلطٌ، الذي فيه عبدالكريم الجزري، وهو ثقة.\nس: هل يقتضي أنه من الكبائر؟\nج: يقتضي أنه من الكبائر؛ لأنهم لا يريحون رائحةَ الجنة.","link":"https://binbaz.org.sa/fatwas/24713/درجة-حديث-قوم-يصبغون-كحواصل-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث يأتي قومٌ يصبغون كحواصل الحمام..mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4553,"question":"قوله في الحديث: إنَّ سورة ثلاثون آية ... صحيح؟","title":"ما صحة حديث \"إنَّ سورة ثلاثون آية..\"؟","answer":"الجواب: لا أعلم الآن فيه قادحًا، راجعتُه قديمًا ولا أتذكر فيه قادحًا، لا باس به. أيش قال عليه المحشي؟ تكلَّم عليه المحشي؟\nالطالب: حسَّنه الترمذيُّ، وهو من رواية عباس الجشمي، عن أبي هريرة ، قال المنذري: وأخرجه النَّسائي وابن ماجه. انتهى، وأخرجه الحاكم وابن حبان وصحَّحاه. وأعلَّه البخاري في \"التاريخ الكبير\" بعدم معرفة سماع الجشمي من أبي هريرة ، ولكن ذكره ابنُ حبان في \"الثقات\"، وله شاهد عن أنسٍ  عند الطبراني في \"الكبير\" بإسنادٍ صحيحٍ.\nالشيخ: ..... حيث يدل الأصل مع المعاصرة ..... الأصل مع المعاصرة هو اللقاء والسماع، هذا هو الأصل، ولهذا جرى على هذا مسلم رحمه الله وجماعة آخرون، وأنَّ التابعي إذا عاصر الصحابي وروى عنه ولم يُعرف بالتدليس فهو محمولٌ على السماع، إلا إذا عُرف عنه التَّدليس.","link":"https://binbaz.org.sa/fatwas/24834/ما-صحة-حديث-ان-سورة-ثلاثون-اية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث إنَّ سورة ثلاثون آية...mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4650,"question":"هذا اجتهادٌ من عليٍّ؟","title":"ما دلالة قول علي: \"في كل شهر عمرة\"؟","answer":"الجواب: الظاهر أنه اجتهادٌ من عليٍّ، لكن ما عزاه للنبي ﷺ، فكأنه رأى أنَّ هذا أيسر وأسهل.","link":"https://binbaz.org.sa/fatwas/24940/ما-دلالة-قول-علي-في-كل-شهر-عمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على قول علي بن أبي طالب في كل شهر عمرة.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4651,"question":"قول عائشة: وعمرة في شوال؟","title":"هل اعتمر النبي عليه الصلاة والسلام في شوال؟","answer":"الجواب: الظاهر أنه وهمٌ، لم يعتمر في شوال عليه الصلاة والسلام، إنما اعتمر في ذي القعدة، غنائم حنين وزَّعها في ذي القعدة.","link":"https://binbaz.org.sa/fatwas/24941/هل-اعتمر-النبي-عليه-الصلاة-والسلام-في-شوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على قول عائشة وعمرة في شوال.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4777,"question":"ما صحة حديث: لا سمر إلا لثلاثة: مصل، أو مسافر، أو عروس؟","title":"ما صحة حديث: «لا سمر إلا لثلاثة»؟","answer":"ما أعرف حاله، الحديث الصحيح أن النبي ﷺ كره السمر بعد العشاء والنوم قبلها، هذا في الصحيح، فالسهر مكروه إلا في مصلحة المسلمين كالعلم وفي مصالح المسلمين، وأما السمر بغير حاجة فهو مكروه وهو السهر.","link":"https://binbaz.org.sa/fatwas/25141/ما-صحة-حديث-لا-سمر-الا-لثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث لا سمر إلا لثلاثة مصل، أو مسافر، أو عروس.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":4821,"question":"إذا طلق الرجل امرأته في طهر لم يجامعها فيه، ثم أراد أن يوقع الطلقة الثانية والثالثة، متى يكون هذا، أحسن الله إليك؟","title":"حكم مَن طلَّق في طُهرٍ وأراد الطلقة الثانية","answer":"يكفي طلقة واحدة، لا يطلق، السُّنة أن يكتفي بطلقة واحدة ولا يتبعها شيء.\nس: لو أراد؟\nج: لا ينبغي له.","link":"https://binbaz.org.sa/fatwas/25226/حكم-من-طلق-في-طهر-واراد-الطلقة-الثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلق زوجته في طهر لم يجامعها فيه، وأراد أن يوقع الطلقة الثانية والثالثة.mp3","categories":["الطلاق"]},{"id":4938,"question":"حديث ابن عباس يقول إنه ﷺ تزوجها وهو محرم؟","title":"حكم حديث ابن عباس في زواج المُحْرِم","answer":"الجواب: هذا الحديث أيضًا وهم من ابن عباس، وهو حديثٌ صحيحٌ عن ابن عباسٍ، لكن هو الذي وهم -ابن عباس- ظنَّ أنه تزوَّجها وهو مُحْرِم، والصواب أنه ﷺ تزوَّجها وهو حلال. هذا ما هو غلط في الرواية، غلط في فهم ابن عباس وما رواه.","link":"https://binbaz.org.sa/fatwas/27092/حكم-حديث-ابن-عباس-في-زواج-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حديث ابن عباس في زواج المُحْرِم.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5060,"question":"والحديث الثاني يقول: مَن حُلِفَ له بالله فليَرْضَ، ومَن لم يَرْضَ فليس من الله؟","title":"ما صحة حديث \"مَن حُلِفَ له بالله فليَرْضَ\"؟","answer":"الجواب: حديث لا بأس به، جيد، النبي ﷺ قال: مَن حلف بالله فليصدق، ومَن حُلِفَ له بالله فليرضَ، ومَن لم يرضَ فليس من الله، هذا في الخصومات، إذا توجَّهت اليمينُ عليه، ما عند المدعي بيِّنة، إذا حلف الخصمُ يرضى بحكم الله، والحساب يوم القيامة إن كان كاذبًا، إذا قال: نعم عندك مئة ريـال، أو ألف ريـال، أو أكثر، ما عنده بينة، فليس له إلا اليمين، فعلى صاحب اليمين أن يتَّقي الله، وعلى المدعي أن يرضى بحكم الله.","link":"https://binbaz.org.sa/fatwas/29326/ما-صحة-حديث-من-حلف-له-بالله-فليرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما صحة حديث من حُلِفَ له بالله فليرض؟.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5105,"question":"هنالك أيضًا أخت أخرى تسأل وتقول: ما مدى صحة الحديث الذي يقول: من لم يهتم بأمر المسلمين فليس منهم؟","title":"ما صحة حديث \"من لم يهتم بأمر المسلمين فليس منهم\"؟","answer":"الجواب: هذا الحديث رواه الطبراني وجماعة، وفيه ضعف، لكن معناه صحيح، وأن الواجب على المسلمين أن يهتم بعضهم ببعض، يقول النبي ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه، ويقول عليه الصلاة والسلام: المؤمن للمؤمن كالبنيان يشد بعضه بعضًا وشبك بين أصابعه، وقال عليه الصلاة والسلام: مثل المؤمنين في توادهم وتراحمهم وتعاطفهم كمثل الجسد إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى.","link":"https://binbaz.org.sa/fatwas/30013/ما-صحة-حديث-من-لم-يهتم-بامر-المسلمين-فليس-منهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 30.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5154,"question":"هذا السائل يقول: ما حكم زواج المتعة؟ وما حكم الطلاق فيه؟","title":"ما حكم زواج المتعة؟ وما حكم الطلاق فيه؟","answer":"الجواب: زواج المتعة لا يجوز، وهو باطل، وهو أن يتزوَّجها مدةً معلومةً، يعني: يتفقون على أن يتزوَّجها سنةً ثم يُفارقها، أو شهرًا، أو شهرين. وكان مباحًا في أول الإسلام، ثم نهى عنه النبيُّ ﷺ ونُسِخَ وقال: إنَّ الله حرَّمه إلى يوم القيامة. وإذا تزوَّج متعةً يُطلِّق؛ لأن فيه خلافًا بين أهل العلم، فإذا تزوَّجها متعةً طلَّقها طلقةً واحدةً؛ حلًّا للمشكل، وإزالةً لهذا النكاح المُشتبه، طلقة واحدة فقط. ونكاح المتعة هو المؤقت، يتزوجها سنة سنتين شهر شهرين، يسمى نكاح متعة، فهو باطل.","link":"https://binbaz.org.sa/fatwas/30072/ما-حكم-زواج-المتعة-وما-حكم-الطلاق-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 95.mp3","categories":["الأنكحة المحرمة","الطلاق"]},{"id":5155,"question":"يقول هذا السائل: هل يقع الطلاق المُحرَّم أم لا؟","title":"هل يقع الطلاق المُحرَّم وطلاق الثلاث أم لا؟","answer":"الجواب: مثلما تقدم: الصحيح أنه لا يقع، والجمهور على أنه يقع، والصحيح أنه في الحيض والنِّفاس لا يقع عند الأقل، وهو الصواب، والجمهور على أنه إذا طلَّق في الحيض أو النفاس يقع. أما طلاق الثلاث فيقع منه واحدةً إذا كان بكلمةٍ واحدةٍ، كأن يقول: أنتِ طالق بالثلاث، أو: هي طالق بالثلاث، فالصواب أنه يحسب واحدة.","link":"https://binbaz.org.sa/fatwas/30073/هل-يقع-الطلاق-المحرم-وطلاق-الثلاث-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 96.mp3","categories":["الطلاق"]},{"id":5157,"question":"سؤاله الثالث يقول: إذا طلبت المرأةُ من زوجها الطلاق وأبى، فما العمل؟","title":"ما الحكم إذا طلبت المرأةُ الطلاق وأبى زوجها؟","answer":"الجواب: إذا طلبت الطلاقَ لأسبابٍ شرعيةٍ فينبغي له ألَّا يأبى، ينبغي له أن يخاف الله، ويطلب مهره، حقَّه، فإن أبت أن تُعطيه حقَّه فلا طلاقَ لها، لا بدَّ أن تُعطيه حقَّه كاملًا، فإن أبى فعليهم أن يذهبوا إلى المحكمة وتنظر في الأمر.","link":"https://binbaz.org.sa/fatwas/30075/ما-الحكم-اذا-طلبت-المراة-الطلاق-وابى-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 98.mp3","categories":["الطلاق"]},{"id":5296,"question":"يقول: هل صحيح أن الحجر الأسود من الجنة؟","title":"ما صحة حديث أن الحجر الأسود من الجنة؟","answer":"الجواب: جاء فيه حديث جيد لا بأس به أنه نزل من الجنة كاللبن بياضًا ثم سوّدته خطايا أهل الشرك، رواه الترمذي وجماعة ولا بأس به.[1]","link":"https://binbaz.org.sa/fatwas/30946/ما-صحة-حديث-ان-الحجر-الاسود-من-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 016.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5298,"question":"يقول: ذكر مسلم في مقدمة صحيحه حديث عائشة مرفوعًا إلى النبي ﷺ قالت: أُمرنا أن ننزل الناس منازلهم فما مدى صحة هذا الحديث؟ وما معناه؟","title":"ما صحة حديث «أُمرنا أن ننزل الناس منازلهم»؟","answer":"الجواب: هذا الحديث في سنده ضعف، لكن معناه لو صح: كُلٌّ ينزل منزلته فرئيس القوم وكبير القوم له منزلته، والمؤمن له منزلته، والفقير السائل له منزلته، والكافر له منزلته، كُلٌّ له منزلته، وفي بعض الروايات أنه جاءها فقير يسأل فأعطته لقمة أو لقمتين، وجاءها فقير آخر ظاهره الحشمة فأمرت بإجلاسه في محل وإعطائه طعامًا يناسبه فسُئلت عن ذلك فقالت: إن الرسول أمرنا أن ننزل الناس منازلهم، فالحديث معناه صحيح، وإن كان السند فيه ضعف. فينبغي للمؤمن أن ينزل الناس منازلهم ولا يجعلهم كشيء واحد، فرئيس القوم والمؤمن وأقاربه وغيرهم لهم حق، والذين يطوفون على الأبواب لهم حق آخر، هم أقسام.[1]","link":"https://binbaz.org.sa/fatwas/30948/ما-صحة-حديث-امرنا-ان-ننزل-الناس-منازلهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 018.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5339,"question":"تفريعًا على القول بوقوع الطلاق في الحيض وقد اتفق القائلون بوقوعه على أن الحيضة التي وقع فيها الطلاق غير محسوبة في العدة، و متى تبدأ العدة؟ هل تبدأ بأول طهر بعد الحيضة التي وقع فيها الطلاق؟ أم متى؟","title":"متى تبدأ عدة المرأة إذا طُلِقت حائضًا؟","answer":"الجواب: تبدأ بالحيضة التي بعدها، إذا قيل بوقوعه تبدأ بالحيضة التي بعدها، الحيضة التي وقع فيها الطلاق لا تُحسب، لكن الصحيح أن الطلاق إذا كان في الحيض لا يقع، إذا كان الزوج يعرف ذلك ويعلم ذلك، والزوجة كذلك، إذا كانا صادقين، كلهم يعلمون ذلك أنه في الحيض: الصواب أنه لا يقع، إلا إذا حكم به حاكم، إذا قضى به قاضٍ فالأكثرون يوقعونه، إذا حكم به الحاكم نفذ، وإلا فالأصل أنه لا يقع؛ لأن النبي ﷺ أنكر على عبدالله بن عمر لما طلق في الحيض غضب عليه وأنكر وأمره أن يرد الزوجة وقال: أمسكها حتى تطهر ثم تحيض ثم تطهر ثم طلقها إن شئت في الطهر قبل أن يمسها، هذا هو المشروع، والله قال: فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق: 1] لعدتهن إذا كن طاهرات من غير جماع، هذا طلاق العدة، أن يكون على طُهر ليس فيه جماع، كما قال تعالى: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق: 1]. س: وما تحسب طلقة؟ ج: على الصحيح، إلا إذا حكم بها قاضٍ، حكم بها حاكم، فحكم الحاكم يرفع الخلاف، عند الأكثر.[1]","link":"https://binbaz.org.sa/fatwas/31012/متى-تبدا-عدة-المراة-اذا-طلقت-حاىضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 060.mp3","categories":["الطلاق"]},{"id":5397,"question":"حديث: صلُّوا صلاةَ مُودِّعٍ؟","title":"ما صحة حديث \"صلُّوا صلاةَ مُودِّعٍ\" وحكم قولها؟","answer":"الجواب: الحديث لا بأس به، حديث العرباض: \"صلَّى بهم\"، أمَّا \"صلِّ\" ما أعرف حاله، لكن: \"صلَّى بهم النبيُّ ﷺ صلاةً عظيمةً\"، قال: \"فكأنَّها صلاةَ مُودِّعٍ\"، ووعظهم موعظةً كأنَّها موعظة مُودِّع، أمَّا \"صلِّ صلاةَ مُودِّعٍ\" ما أعرف سنده، لكن ينبغي للمؤمن في كلِّ صلاةٍ أن يعتني بها؛ لأنَّه لا يدري: هل يُصلِّي بعدها أو لا؟ فيعتني ويُكمِّل. س: هل يقول الإمامُ للمأمومين: صلُّوا صلاةَ مودعٍ، وما يقول: استووا؟ الشيخ: ما أعرف لها أصلًا، يقول مثلما قال النبيُّ ﷺ: اعتدلوا، استووا، تراصُّوا، تقاربوا، شيء جديد ما أعرفه، وفيما فعله النبيُّ ﷺ الكفاية.[1]","link":"https://binbaz.org.sa/fatwas/31145/ما-صحة-حديث-صلوا-صلاة-مودع-وحكم-قولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 013.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5426,"question":"ما صحة حديث: اللهم إني أسألك بحقِّ السَّائلين عليك؟","title":"ما صحة حديث \"أسألك بحقِّ السَّائلين عليك\"؟","answer":"الجواب: هذا حديث ضعيف عند أهل العلم.\nلكن يأتي بأشياء مشروعة: بسم الله، توكلتُ على الله، لا حول ولا قوة إلا بالله، اللهم إني أعوذ بك أن أَضِلَّ أو أُضَلَّ، أو أَزِلَّ أو أُزَلَّ، أو أظلمَ أو أُظلمَ، أو أجهلَ أو يُجهل عليَّ إذا خرج من بيته للصلاة وغيرها، وإذا كان خارجًا للصلاة: اللهم اجعل في قلبي نورًا، وفي سمعي نورًا، وفي بصري نورًا، وفي لساني نورًا، وفي شعري نورًا، وفي بَشَري نورًا، وفي عظمي نورًا، وفي لحمي نورًا، وفي عصبي نورًا، وفي دمي نورًا، وأمامي نورًا، وخلفي نورًا، وعن يميني نورًا، وعن شمالي نورًا، وفوقي نورًا، وتحتي نورًا، اللهم أعطني نورًا، وأعظم لي نورًا، هذا من حديث ابن عباس في \"الصحيح\".[1]","link":"https://binbaz.org.sa/fatwas/31205/ما-صحة-حديث-اسالك-بحق-الساىلين-عليك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 043.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5507,"question":"اشفعوا تؤجروا حديث صحيح؟","title":"ما درجة حديث \"اشفعوا تؤجروا\"؟","answer":"الجواب: نعم، والله يقول: مَنْ يَشْفَعْ شَفَاعَةً حَسَنَةً [النساء:85]، والنبي ﷺ في الحديث الصحيح -الذي رواه البخاري ومسلم أو أحدهما- يقول: اشفعوا تُؤجروا، وقد شفع في بريرة، وهي امرأة جارية عتيقة، من تواضعه ﷺ، أعتقتها عائشة، اشترتها وأعتقتها، وكان لها زوجٌ عبد مملوك، فاختارت نفسها، قالت \"ما أبغيه\"، يُسمَّى \"مُغيث\"، وكان يُحبها كثيرًا، وكان يبكي، فلما رأى النبيُّ ﷺ حاله وحبّه لها أتاها وقال لها: يا بريرة، لو أنك قبلته وصبرت معه، قالت: يا نبي الله، تأمرني أو تشفع؟ هي تفهم، قال: لا، ما آمرك، ولكن أشفع، قالت: لا حاجةَ لي فيه.[1]","link":"https://binbaz.org.sa/fatwas/31437/ما-درجة-حديث-اشفعوا-توجروا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 022.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5572,"question":"حديث: إنما هو بُضعة منك؟","title":"ما صحة حديث \"إنما هو بُضعة منك\"؟","answer":"الجواب: حديث ضعيف، وبعضهم حمل على أنه منسوخ، وبعضهم قال: شاذّ، في سنده بعض المقال، ولكن أحسن الجواب عنه أنه شاذّ أو منسوخ. س: مَن قال أنَّ هذا يحمل؟ ج: لا، غلط، الأحاديث الصحيحة كثيرة في وجوب الوضوء.[1]","link":"https://binbaz.org.sa/fatwas/31524/ما-صحة-حديث-انما-هو-بضعة-منك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 012.mp3","categories":["الطلاق","الحكم على الأحاديث"]},{"id":5687,"question":"قد عزمني أحد الإخوة، وقال لي: لازم تحضر أحد أخويك العزيمة، وحرمت على الذي أمون عليه منهم، ولم يذهب معي؟","title":"حكم من حلف على شخص ولم يبر بقسمه","answer":"الجواب: إذا ما ذهب معه ما عليه شيء، لكن لو أنه أجاب الداعي، وراح معه بعض إخوانه كان أحسن، يحضر له بعض إخوانه معه الذين دعاهم يكون أحسن، ولكن هو لما حرم عليه أن يذهبوا معه، ولم يذهبوا معه، وتمموا له ما عليه شيء. السؤال: ما عليه إطعام؟ الجواب: لا، ما راحوا عليه، حرم عليهم أن يروحوا، وما راحوا، ما نقضوا عليه. السؤال: .......؟ الجواب: أين السائل؟ على كل حال إن كان قصده: أنه شدد عليهم حرم عليهم يروحوا معه، وما راحوا عليه كفارة يمين، وإن كان قصده أن حرم عليهم أنهم ما يروحون وأطاعوه فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/989/حكم-من-حلف-على-شخص-ولم-يبر-بقسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_18.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5691,"question":"قد عزمني أحد الإخوة، وقال لي: لازم تحضر أحد أخويك العزيمة، وحرمت على الذي أمون عليه منهم، ولم يذهب معي؟","title":"حكم من حلف على شخص ولم يبر بقسمه","answer":"الجواب: إذا ما ذهب معه ما عليه شيء، لكن لو أنه أجاب الداعي، وراح معه بعض إخوانه كان أحسن، يحضر له بعض إخوانه معه الذين دعاهم يكون أحسن، ولكن هو لما حرم عليه أن يذهبوا معه، ولم يذهبوا معه، وتمموا له ما عليه شيء. السؤال: ما عليه إطعام؟ الجواب: لا، ما راحوا عليه، حرم عليهم أن يروحوا، وما راحوا، ما نقضوا عليه. السؤال: .......؟ الجواب: أين السائل؟ على كل حال إن كان قصده: أنه شدد عليهم حرم عليهم يروحوا معه، وما راحوا عليه كفارة يمين، وإن كان قصده أن حرم عليهم أنهم ما يروحون وأطاعوه فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/989/حكم-من-حلف-على-شخص-ولم-يبر-بقسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_18.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5758,"question":"مرض ولدي وهو صغير مرضًا شديدًا، وقلت: إن أحياه الله أصوم من كل سنة شهر رجب، وأنا الآن لم أصم ولو شهرًا واحدًا، حيث إني كل سنة حامل، أو مرضع، ومضى لهذا النذر حوالي تسع سنوات، وأنا لا أستطيع، وغير صحيحة، فماذا أفعل؟","title":"نذرت صيام شهر رجب من كل عام","answer":"الجواب:  هذا نذر مكروه، نذرها أن تصوم شهر رجب كل سنة مكروه، فعليها كفارة يمين، ويكفي، فإنه صوم مكروه، والنذر مكروه، فيكفي فيه كفارة يمين، فإذا كفرت كفارة يمين، أطعمت عشرة مساكين لكل مسكين نصف صاع من قوت البلد، أو تكسوهم؛ كفى ذلك، والحمد لله، وليس عليها صيام.","link":"https://binbaz.org.sa/fatwas/1097/نذرت-صيام-شهر-رجب-من-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_103.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5773,"question":"مرض ولدي وهو صغير مرضًا شديدًا، وقلت: إن أحياه الله أصوم من كل سنة شهر رجب، وأنا الآن لم أصم ولو شهرًا واحدًا، حيث إني كل سنة حامل، أو مرضع، ومضى لهذا النذر حوالي تسع سنوات، وأنا لا أستطيع، وغير صحيحة، فماذا أفعل؟","title":"نذرت صيام شهر رجب من كل عام","answer":"الجواب:  هذا نذر مكروه، نذرها أن تصوم شهر رجب كل سنة مكروه، فعليها كفارة يمين، ويكفي، فإنه صوم مكروه، والنذر مكروه، فيكفي فيه كفارة يمين، فإذا كفرت كفارة يمين، أطعمت عشرة مساكين لكل مسكين نصف صاع من قوت البلد، أو تكسوهم؛ كفى ذلك، والحمد لله، وليس عليها صيام.","link":"https://binbaz.org.sa/fatwas/1097/نذرت-صيام-شهر-رجب-من-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_103.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5834,"question":"حلف بالطلاق أن لا يذهب إلى محل كذا، وحلف بقوله: هي علي طالق ثلاث مرات، وهو لم يقصد بهذا الطلاق، بل قصد أن يمنع نفسه عن هذا المحل، وللأسف لقد جهل الأمر، ولم تمض مدة قصيرة حتى ذهب إلى نفس المحل، فحينئذ لم يكن ناسيًا، وإنما ذاكرًا، وإنما تجاهل الأمر فقط، فما حكم ذلك؟","title":"من حلف بالطلاق ونسيه","answer":"الجواب:  إذا طلق الإنسان على شيء يفعله، أو شيء لا يفعله؛ فهذا فيه تفصيل، إذا قال: عليه الطلاق لا يزور فلانًا، ولا يدخل بيت فلان، وعليه الطلاق ألا يأكل ذبيحة فلان، وعليه الطلاق أن تأكل ذبيحتي يا فلان، وأن تبقى حتى تأكل ذبيحتي، أو عليه الطلاق ما يكلم فلانًا، أو ما يسافر إلى كذا.  كل هذه الأمور تقع من الناس، ففيه تفصيل: إن كان أراد إيقاع الطلاق، إذا فعل هذا الشيء، أو ما فعل هذا الشيء يقع عليه الطلاق أنه يسافر، ونيته أنه إذا ما سافر تطلق امرأته؛ فهو على نيته، أو قال: عليه الطلاق أنك تأكل الذبيحة، ونيته إنه إن ما أكلها أنها تطلق؛ فهو على نيته. أما إن كان أراد التأكيد على الموضوع، ولا أراد فراقها، ولا خطر بباله فراقها، ولكن أراد التأكيد، أراد على هذا أن يأكل ضيافته، وهو ليس قصده فراق أهله، ولكن يريد منه أن يأكل الضيافة إذا سمع الطلاق؛ لعله يخضع، لعله يجلس فيأكل الضيافة، فهذا حكمه حكم كفارة يمين، حكمه حكم اليمين، وعليه كفارتها، ولا يقع الطلاق. وهكذا إذا قال: عليه الطلاق أنه ما يزور بيت فلان، أو ما يدخل بيت فلان، ثم فعل ذلك، وقصده منع نفسه من هذا الشيء، ليس قصده فراق أهله، ولكن أراد أن يمنع نفسه من هذا الشيء، وأكد عليها، فهذا يكون له حكم اليمين؛ عليه كفارة يمين، إطعام عشرة فقراء، كل فقير له نصف صاع من قوت البلد، ويكفي ذلك، أو يكسوهم كسوة قميص لكل واحد، أو يعطي لكل واحد إزارًا ورداء، هذه الكسوة مما يجزي في الصلاة. هذا جواب هذه المسائل المتعددة الكثيرة إن أراد إيقاع الطلاق؛ وقع الطلاق، وإن كان ما أراد ذلك، وإنما أراد منع نفسه، أو حثها على الشيء الذي يريده، منع نفسه أنه عليه الطلاق أنه ما يسافر، ما يكلم فلانًا، هذا قصده منع  نفسه من السفر، والكلام، أو أراد حثها عليه، عليه الطلاق أنه يصوم يوم الإثنين والخميس، عليه الطلاق أنه يذبح ذبيحة لفلان، فهذا قصده حث نفسه على الشيء، فهذا حكمه حكم اليمين أيضًا، إذا كان ما قصد إلا حث نفسه، وإلزامها بهذا  الشيء.","link":"https://binbaz.org.sa/fatwas/1180/من-حلف-بالطلاق-ونسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_176.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5854,"question":"أنا مدرس في المرحلة المتوسطة، وإذا دخلت الفصل؛ قام التلاميذ لي تقديرًا، واحترامًا من دون ما آمرهم به، بل إني أكره  ذلك، فما حكم ذلك؟","title":"حكم قيام الطلاب للمدرس عند دخوله","answer":"الجواب: هذا الذي نبه عليه أيضًا الشيخ محمد، وهو مسألة القيام، هذا مما جاء في السنة في النهي عنه، قال أنس : كان الصحابة إذا دخل عليهم النبي لا يقومون له لما يعلمون من كراهيته لذلك، وكان يقولﷺ: من أحب أن يتمثل له الرجال قيامًا؛ فليتبوأ مقعده من النار.  فالواجب على الطلبة إذا دخل الأستاذ ألا يقوموا، بل يلزموا أماكنهم، ويسلموا عليه، ويصبحونه بالخير، ويمسونه بالخير، طيب، أما أنهم يقومون له وقوفًا؛ فلا ينبغي ذلك، أقل أحواله الكراهة الشديدة، وهو لا يحب ذلك ما يجوز له أن يحب ذلك، والأستاذ ما دام أنه لا يحب ذلك، فهو على خير، النبي -عليه الصلاة والسلام- قال: من أحب أن يتمثل له الناس قيامًا؛ فليتبوأ مقعده من النار وفي لفظ: من سره. فالحاصل: أنه إذا كان لا يحب ذلك؛ لا حرج عليه، لكن يلزمه أن يعظهم، وأن يقول لهم: لا تفعلوا، وإذا عرفوا منه الصدق، وأنه لا يرضا بذلك؛ جلسوا، لكن أخشى أنه لا يحب ذلك دعوى، وليست حقيقة، ولو كان لا يحبه حقيقة؛ لأمرهم بالجلوس، ولقال لهم: لا تقوموا. فالحاصل: أن هذا الشيء على الأستاذ أن ينبههم، وأن يقول لهم: لا تفعلوا، لا تقوموا، ولا يرضى عنهم، لا أرضى عنكم أن تفعلوا هذا، فإذا رأوا منه الصدق ما قاموا ما هم حريصين على القيام، لكن خوفًا من شره، أو يرسبهم، أو يفعل بهم أشياء تضرهم. فالحاصل: أنه إذا صدق في ذلك، وقال لهم: لا تقوموا ما قاموا، وهذا الواجب أيضًا على وزارة المعارف؛ أنها تنبه المديرين أن هذا لا يجوز، وأن الأستاذ إذا دخل لا يقومون له، وهكذا البنات، المدرسة لا يقمن لها، وعلى  الرياسة العامة للتعليم أن تنبه على ذلك؛ حتى يزول هذا الشر الذي في المدارس. أما القيام الذي معناه المواجهة، والمقابلة للمصافحة، هذا لا بأس به، إذا دخل الأستاذ، فقام له واحد ليسأله عن شيء، ليصافحه، ليقدم في مكان، أو ليجلسه في مكانه، أو في مجلس من المجالس، قام ليصافحه، ويسأله عن حاله؛ لا بأس. مثلما قام طلحة بن عبيدالله التيمي أحد العشرة المشهود لهم بالجنة، لما دخل كعب بن مالك، لما تاب الله عليه، وجاء إلى الناس، والنبي في المسجد، وعنده الحلقة، ولما رأى كعبًا أقبل؛ قام من الحلقة، وقابله، وصافحه، وهنأه بتوبة الله عليه، ولم ينكر النبي ﷺ عليه، ولم يقل له شيئًا؛ فدل على جوازه في هذا.  ولما جاء سعد بن معاذ الأنصاري  ليحكم في بني قريظة على دابة له، على حمار، لما أقبل قال النبي ﷺ: قوموا إلى سيدكم فقاموا إليه، وسلموا عليه، وأنزلوه من دابته، وكانت فاطمة -رضي الله عنها- إذا دخل والدها النبي -عليه الصلاة والسلام- قامت إليه، وأخذت بيده، وأجلسته في مكانها، وكان إذا دخلت عليه هو قام إليها، وأخذ بيدها، عليه الصلاة والسلام. هذا إذا كان القيام للمقابلة، والمواجهة، والمصافحة، أو القيام ليمشي معه حتى يخرج من المحل، هذا لا حرج فيه، فعله النبي، وفعله الصحابة، المنكر كونهم يقومون، ثم يجلسون، ما في مصافحة، ولا شيء، إنما يقومون تعظيمًا للداخل، ثم يجلسون، هذا الذي أقل أحواله الكراهة، أو التحريم، وكونه يحب ذلك في الداخل، ويسر لهذا، ويحبه هذا، لا يجوز، وقد توعد بالنار على هذا الشيء، وهم لا ينبغي لهم أن يقوموا، يكره لهم القيام، وهو لا يجوز له أن يحب ذلك، ولا يجوز له أن يأمرهم بهذا الشيء، والواجب عليه أن ينهاهم عن هذا الشيء؛ حتى يجلسوا، وحتى يعتادوا على هذا الشيء، وهو الجلوس في أماكنهم؛ حتى يأخذ مكانه، ويبدأ بالدرس، سواء كانوا ذكورًا، أو إناثًا. السؤال: بعض المدرسين يقول: إن هذا تنبيه للطلاب؟ الجواب: لا؛ هذه شبهة شيطانية، يتنبهوا بدخوله إذا قال: السلام عليكم؛ تنبهوا، وإذا واحد نعس يقول: يا فلان صاح، انتبه للدرس، لا بأس أن ينصحهم، ويحذرهم من النعاس. السؤال: ذكر فضيلة المحاضر أن القيام قد يفضي إلى الشرك، وهناك بعض المسؤولين إذا لم يقم له الإنسان؛ فقد يغضب عليه، ويعاقبه، فماذا أعمل معه؟ الجواب: يبين له مر الكلام هذا، وأنه لا يجوز القيام، والذي لا يرضى ينبه، يقال له: إن هذا لا يجوز، لولا أن الرسول كره ذلك، وأنت والحمد لله من أتباع الرسول، أنت لا تحب الشيء الذي لا يحبه الرسول ﷺ.","link":"https://binbaz.org.sa/fatwas/1203/حكم-قيام-الطلاب-للمدرس-عند-دخوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_199.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5909,"question":"يدعي البعض أن إتلاف المال مكروه، وليس حرامًا، ومن إتلاف المال في الدخان يقولون أيضًا: إن التحريم يحتاج إلى نص، فما رأيكم في هذا القول؟","title":"حكم إتلاف المال في الدخان وغيره","answer":"الجواب:  إتلاف المال بغير وجه شرعي هو محرم بلا شك، وليس فيه خلاف بين العلماء في هذا؛ بل هو محل إجماع أن إتلاف المال في غير أمر مباح في غير أمر شرعي لا يجوز لوجوه كثيرة، وأدلة كثيرة؛ لأن المال جعله الله، وخلقه الله لنفع الناس، ولتقضى به الحوائج، ويجاهد به في سبيل الله، ويواسى به الفقير، والمسكين، وتقام به المشاريع الخيرية، والمصالح العامة، فلا يجوز أن يضاع.  ومن ذلك قوله -جل وعلا-: وَلَا تُبَذِّرْ تَبْذِيرًا [الإسراء:26] قال العلماء: التبذير إضاعة المال، يعني صرفه في غير وجهه، كصرفه في المسكرات، وصرفه في الدخان، وصرفه في المعاصي، وطرحه في البحر، وما أشبه ذلك، هذا من التبذير.  وكذلك الإسراف، الله نهى عن الإسراف، وقال: وَلَا تُسْرِفُوا [الأنعام:141] فالإسراف: الزيادة على الحاجة، فإن كانت الزيادة عن الحاجة تمنع، فكيف بإضاعة المال أصلًا، ورأسًا! كذلك ما صح في الصحيحين عن النبي ﷺ من حديث المغيرة بن شعبة عن النبي ﷺ قال: إن الله يكره لكم، أو الله يسخط لكم: قيل وقال، وإضاعة المال، وكثرة السؤال أخبر أن الله يسخط لنا: قيل وقال، وكثرة السؤال، وإضاعة المال. والله يسخط هذا، وما سخطه الله؛ وجب علينا تركه في أدلة كثيرة غير هذا؛ لأن صرفه في الدخان، والمسكرات لا ريب أنه من التبذير، والحرام، ولا شك في ذلك، مع ما هو متقرر، ومعلوم من كون الدخان من الخبائث الضارة، والله سبحانه إنما أباح لنا الطيبات، حيث قال : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قال الله لنبيه: قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] ولا يقول عاقل، لا طبيب، ولا غير طبيب: إن الدخان من الطيبات، فعلم حينئذ بنص القرآن أنه ليس من المباحات.  وقال سبحانه في وصف النبي محمد ﷺ: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157] فكل شيء ليس بطيب؛ فهو من قسم الخبائث، والله بعث نبيه ﷺ يحل الطيبات المآكل، والمشارب، والمراكب، والملابس، وغير ذلك، ويحرم الخبائث التي تضر العبد ضررًا عظيمًا، إما غالبًا، وإما محضًا، والدخان أضراره محضه، خبيثة، لا خير فيها، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1234/حكم-اتلاف-المال-في-الدخان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_231.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5919,"question":"هل يطلق الرجل امرأته لطلب والديه، أو أحدهما، مع أن الوفاق بين الزوجين سائد؟","title":"حكم طلاق الزوجة مراعاة لطلب والد الزوج","answer":"الجواب: تقدم هذا المعنى، وأن الواجب أن يحل المشكل بالكلام الطيب مع والديه، ومعها، فيحثها على إحسان السيرة معهما، والتلطف لهما، وكذلك يتكلم مع والديه بأنها امرأة صالحة، ومناسبة لي، فأرجو منكما يعني السماح، وعدم المطالبة بفراقها، يعني يفعل ما يستطيع إذا كانت في نفسها طيبة، وسليمة.  أما إذا كانت المطالبة من الأبوين لعلة فيها؛ لأنها منحرفة عن الطريق السوي، ومتهمة بالسوء، والقرائن ظاهرة، والأسباب ظاهرة؛ فالواجب طاعتهما في هذه الحال.","link":"https://binbaz.org.sa/fatwas/1273/حكم-طلاق-الزوجة-مراعاة-لطلب-والد-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_260.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5921,"question":"قال أحد الخطباء في خطبة الجمعة: إن على الزوج أن لا يخبر زوجته أنه طلقها، فهل هذا الحكم صحيح، وله سند من الكتاب، والسنة؟","title":"حكم إعلام الزوج بطلاق زوجته","answer":"الجواب: الطلاق لا بدّ أن تخبر به المرأة حتى تعرف أنها مطلقة، أو غير مطلقة، إذا طلقها؛ لا بدّ أن يعرفها الطلقة، ويبين لها الطلاق حتى تحتسب الطلقة، وإذا طلقها الثانية عرفتها، وإذا طلقها الثالثة عرفت أنها حرمت عليه، لا بدّ أن يعرفها ذلك. لكن إذا رأى أن لا يبادر بذلك؛ لعلة، ولأسباب يخشى أن يصدمها بهذه الطلقة، وأن يكون لها رد فعل سيئ ، وأجل إعلامها إلى وقت آخر في غير وقت الطلقة، فالظاهر أنه لا حرج في ذلك، إذا أجل إعلامها بالطلقة إلى وقت آخر، يعني غير وقت الطلاق الذي طلقها فيه؛ لأنه يرى أن في هذا خطر عليه، أو خطر عليها، أو لأسباب أخرى وجيهة، فلا مانع من ذلك. لكن لا بدّ من إعلامها، ولو بعد ذلك، لا بدّ من إعلامها حتى تعرف، وحتى تحسب، وإذا أعلم أيضًا وليها؛ كان هذا أكمل؛ حتى لا يغلب عليه الشيطان، فيجحدها بعد ذلك، أو ينساها، فإعلامها، وإعلام وليها أمر مهم، وحق، لكن لا مانع من تعجيلها إلى وقت ما إذا كان يخشى من ذلك مضرة عليها، أو عليه، فيؤجل بعض الوقت، ثم يخبرها، أو يكتبها عنده كتابة يقيده عنده؛ حتى لا ينسى؛ حتى لا يستحلها بغير ما أنزل الله، جل وعلا.","link":"https://binbaz.org.sa/fatwas/1279/حكم-اعلام-الزوج-بطلاق-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_266.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5922,"question":"هل الطلاق الذي يعد في عهد الرسول طلقة واحدة هل هو الذي يطلق ثلاث متتاليات، أي من ثلاث كلمات في مجلس واحد، أم هو نطق بالطلاق من لفظ واحد، مثل أن يقول: أنتِ طالق بالثلاث، نرجو بيان ذلك؟","title":"التفصيل في الطلاق بلفظ واحد","answer":"الجواب: ثبت عنه من حديث ابن عباس أنه قال: كان الطلاق على عهد النبي ﷺ الطلاق الثلاث بواحدة، فلما كان عمر قال: إن الناس استعجلوا في أمر كانت لهم فيه أناة، فأمضاه عليهم. والمشهور عند العلماء أن المراد بهذه الثلاث الطلاق بفم واحد كلمة واحدة، أنت مطلقة ثلاثًا، أنت طالق بالثلاث، هي طالق بالثلاث، هذا هو الأظهر في هذه المسألة: أن التطليق بكلمة واحدة ... الثلاث، وهذا هو المروي عن ابن عباس: أن التطليق بالثلاث .. واحدة أنت طالق بالثلاث، أنت مطلقة بالثلاث.  وذهب بعض أهل العلم إلى أن الطلاق بالثلاث، ولو تكرر ما دام في مجلس واحد، وبعضهم قال: حتى ولو في مجالس ما دام ما بينهما رجعة، ولا نكاح؛ فإنه لا يقع إلا الأولى، والثانية والثالثة لا تقعان، وجعل الحديث يعم الجميع، وليس هذا بواضح من الأحاديث، فإنها رجعية، المطلقة طلقة واحدة رجعية، فإذا طلقها الثانية؛ لحقتها الثانية، فإذا طلقها الثالثة؛ لحقتها، وإنما يمتنع اللحوق إذا كانت بائنة بخلع المخالعة المفسوخة، لم تلحقها الثانية، ولا الثالثة. أما إذا طلقها طلاقًا رجعيًا واحدًا، ثم أتبعها ثانية، وثالثة؛ فإن الأظهر من كلام العلماء أنه يقع عليها الطلاق، وتحرم في الثانية، والثالثة، وهذا هو الذي أفتي به، وهو الذي ظهر لي مما جاء في النصوص، ومن آثار الصحابة -رضي الله عنهم وأرضاهم- أن الطلاق بالثلاث تحتسب واحدة إذا جمعها بكلمة واحدة، أو كتبه جملة واحدة، هي طالق بالثلاث كتابة أو لفظًا، كان هذا واحدة في عهد النبي ﷺ وفي عهد الصديق، وفي أول خلافة عمر، ثم نظر عمر في هذا وقال : إن الناس استعجلوا في هذا الأمر ... فيه فلأمضينه عليهم، فأمضاه عليهم  وتابعه أكثر الصحابة في هذا. وروي عن علي، والزبير، وعبدالرحمن بن عوف، وابن عباس أنهما جعلوه واحدة على ما كان في عهد النبي ﷺ وهذا هو الأرجح للدليل، وهذا هو الأنفع للمسلمين أيضًا، والأرفق بهم.","link":"https://binbaz.org.sa/fatwas/1274/التفصيل-في-الطلاق-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_261.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5926,"question":"هل الطلاق يكون طلقة في كل طهر، أم الأفضل أن يطلق طلقة واحدة في طهر، ثم يتركها حتى تنتهي العدة، فيكون بذلك بائن بينونة صغرى؟","title":"حالات الطلاق السني","answer":"الجواب:\n\nهذا هو السنة، أن تطلقها طلقة واحدة في طهر لم يجامعها فيه، ثم يتركها حتى تنتهي عدتها، أو يراجعها، أما كونه يطلق في كل طهر لا، هذا يروى عن ابن عباس، لكن ليس بجيد، بل يفوتها عليه، ويضره بدون حاجة، وإنما السنة أن يطلقها واحدة في طهر لم يجامعها فيه، كما أمر بذلك النبي ﷺ ابن عمر، ثم ليمسكها، فإذا طهرت بعد الحيضة الثانية؛ فليطلقها قبل أن يمسها، فتلك العدة التي أمر الله أن تطلق لها النساء، لقوله سبحانه: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ[الطلاق:1] الآية، فتطليقها للعدة أن يطلقها طاهرة بغير جماع، هذا هو الطلاق الشرعي. \n\nوالمرأة لها أحوال خمسة: ثلاث حالات الطلاق فيها بدعي، وحالان الطلاق فيها شرعي، فالطلاق البدعي في حال الحيض، وفي حال النفاس، وفي حال الطهر الذي جامعها فيه، في هذه الأحوال الثلاثة لا يطلقها، لا في الحيض، ولا في النفاس، ولا في طهر جامعها فيه.\n\nأما الحالتان اللتان فيهما الطلاق الشرعي فهما: حال الحمل كونها حاملًا، وكذلك إذا طلقها في طهر لم يجامعها فيه، فهذا هو الطلاق الشرعي المندوب.\n\nوينبغي للرجل أن يلاحظ هذه الأشياء، وأن لا يعجل في الطلاق؛ لأن الطلاق مبغوض إلى الله، أبغض الحلال إليه الطلاق، والله -جل وعلا- يحب بقاء النكاح، لا فصل النكاح؛ لما فيه من المصالح، والفوائد الكثيرة. \n\nفينبغي للزوج أن لا يعجل، وأن يتحرى أوقات الطلاق الشرعي إذا عزم على الطلاق، وألا يعجل في الأمور، فليتأنى، وينظر، فإذا طابت نفسه، ورأى أن الطلاق أصلح؛ طلقها طلقة واحدة في طهر لم يجامعها فيه، ثم يتركها حتى تنتهي عدتها، فتكون بائنة بذلك بينونة صغرى، لا يحلها إلا عقد شرعي، هذا هو المشروع في هذه المسائل.","link":"https://binbaz.org.sa/fatwas/1275/حالات-الطلاق-السني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_262.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5927,"question":"رجل متزوج، لكن أهله يرغبون أن يطلق زوجته لعدم التفاهم معها، بينه وبين إخوته في المنزل، ولم تأت بشيء يوجب طلاقها، علمًا بأن المحبة، والتفاهم سائد بين الرجل، وامرأته، فما العمل، جزاكم الله خيرًا؟","title":"ما حكم تطليق الرجل تلبية لرغبة أهله؟","answer":"الجواب: إذا تزوج الرجل امرأة لم تناسب أهله، ولم يحصل تواطؤ بينها، وبين أهله، فهذا محل تفصيل، إن كان ذلك لسوء تصرفاتها، وسوء عملها، وأنها تتهم بالشر، فينبغي له فراقها، والنساء سواها كثير.  أما إذا كان لأمر آخر؛ فينبغي له أن يعالج الأوضاع بالهدوء، والكلام الطيب، والعبارات الحسنة، والأساليب الطيبة، ولا يعجل في الأمور، بل ينبغي أن يعالجها بالعلاج الحسن، ولاسيما إذا كان الخلاف بينه، وبين إخوته فأمره أسهل. أما إن كان بين الأبوين فهو أشد، فينبغي له أن يجتهد في علاج الموضوع مع أبويه؛ لأن حقهما عظيم؛ ولأن برهما واجب، فينبغي أن يعالج الأوضاع بأن يقول لها: أن تتأدب معهما، وأن تحسن الصلة بهما، وأن تكف عما يسيئ إليهما إذا كانت صالحة في نفسها؛ حتى تهدأ الأمور، وحتى يرضيا عنها، وتزول أسباب المطالبة بفراقها. أما إذا كان هذا لانحرافها، وسوء عقيدتها، أو سوء خلقها باتهامها بالفواحش، والانحراف عن الدين؛ فينبغي أن يطيع إخوته، ووالديه في ذلك، وأن يبعدها ،وسوف يغنيه الله خيرًا منها، كما قال الله -جل وعلا-: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا  ۝  وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2، 3] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/1270/ما-حكم-تطليق-الرجل-تلبية-لرغبة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_257.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5928,"question":"قال لزوجته: لا تدخلي هذا الباب، وإن خرجتِ منه؛ فأنت طالق، وفعلًا أن زوجته خرجت، فهل هي طلقت؟","title":"حكم من طلق امرأته لفعلها ما نهاها عنه","answer":"الجواب: كما سمعتم، الكلام فيه أنه إذا قال: إذا خرجت فأنت طالق، أو كلمت فلانًا، إذا كان قصده منعها، ما قصده فراقها؛ فعليه كفارة يمين -كما سمعتم- إذا قال: إن كلمتِ فلانًا، أو خرجت إلى بيت فلان، أو خرجت بغير إذني؛ فأنت طالق، قصده منعها، ما قصده فراقها، فهذا حكمه حكم اليمين، وعليه كفارتها.  وأما إذا كان مقصوده فراقها إذا خرجت؛ فهي مطلقة، تحسب عليه طلقة، فإن طلقها قبلها طلقتان؛ تمت الطلقات، وحرمت عليه حتى تنكح زوجًا غيره. أما إذا كان ما قبلها إلا طلقة واحدة، أو ما قبلها شيء، فيراجعها.","link":"https://binbaz.org.sa/fatwas/1281/حكم-من-طلق-امراته-لفعلها-ما-نهاها-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_268.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5929,"question":"هل يقع الطلاق إذا طلقها طلاقًا بدعيًا؟","title":"حكم إيقاع الطلاق البدعي","answer":"الجواب: اختلف العلماء في الطلاق البدعي، هل يقع، أم لا يقع؟ فذهب الجمهور إلى أنه يقع، جمهور العلماء ذهب إلى أنه يقع مع التحريم، وذهب قوم إلى أنه لا يقع، واختاره جماعة من السلف، وهو مروي عن ابن عمر، وعن طاوس بن كيسان اليماني التابعي الجليل، وعن خلاد بن عمرو التابعي الجليل، واختاره شيخ الإسلام ابن تيمية، وابن القيم، وجماعة، قالوا لأنها وقع على خلاف أمر الله؛ فلا يقع. والجمهور قالوا: أخطأ، وأساء، وينفذ عليه؛ لأن ابن عمر احتسب طلقته التي طلقها في الحيضة، احتسبها، وأمضاها على نفسه، احتسبت عليه تطليقة، لكن لم يثبت أن النبي حسبها عليه، ولكن هو اعتبرها، وأمضاها على نفسه في ظاهر النصوص التي جاءت عنه.  وسئل في رواية عنه عمن طلقها في حال الحيض، فقال: لا يعتد بها، فهذا مما يبين أنه احتسب طلقتها التي طلقها في الحيض، احتسبها اجتهادًا منه والرسول ﷺ قال له: راجعها، ثم أمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شئت فطلق، وإن شئت فأمسك ولو كانت الطلقة واقعة؛ لكان المعنى تكثير الطلاق.","link":"https://binbaz.org.sa/fatwas/1276/حكم-ايقاع-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_263.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5931,"question":"رجل متزوج، لكن أهله يرغبون أن يطلق زوجته لعدم التفاهم معها، بينه وبين إخوته في المنزل، ولم تأت بشيء يوجب طلاقها، علمًا بأن المحبة، والتفاهم سائد بين الرجل، وامرأته، فما العمل، جزاكم الله خيرًا؟","title":"ما حكم تطليق الرجل تلبية لرغبة أهله؟","answer":"الجواب: إذا تزوج الرجل امرأة لم تناسب أهله، ولم يحصل تواطؤ بينها، وبين أهله، فهذا محل تفصيل، إن كان ذلك لسوء تصرفاتها، وسوء عملها، وأنها تتهم بالشر، فينبغي له فراقها، والنساء سواها كثير.  أما إذا كان لأمر آخر؛ فينبغي له أن يعالج الأوضاع بالهدوء، والكلام الطيب، والعبارات الحسنة، والأساليب الطيبة، ولا يعجل في الأمور، بل ينبغي أن يعالجها بالعلاج الحسن، ولاسيما إذا كان الخلاف بينه، وبين إخوته فأمره أسهل. أما إن كان بين الأبوين فهو أشد، فينبغي له أن يجتهد في علاج الموضوع مع أبويه؛ لأن حقهما عظيم؛ ولأن برهما واجب، فينبغي أن يعالج الأوضاع بأن يقول لها: أن تتأدب معهما، وأن تحسن الصلة بهما، وأن تكف عما يسيئ إليهما إذا كانت صالحة في نفسها؛ حتى تهدأ الأمور، وحتى يرضيا عنها، وتزول أسباب المطالبة بفراقها. أما إذا كان هذا لانحرافها، وسوء عقيدتها، أو سوء خلقها باتهامها بالفواحش، والانحراف عن الدين؛ فينبغي أن يطيع إخوته، ووالديه في ذلك، وأن يبعدها ،وسوف يغنيه الله خيرًا منها، كما قال الله -جل وعلا-: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا  ۝  وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2، 3] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/1270/ما-حكم-تطليق-الرجل-تلبية-لرغبة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_257.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5932,"question":"قال لزوجته: لا تدخلي هذا الباب، وإن خرجتِ منه؛ فأنت طالق، وفعلًا أن زوجته خرجت، فهل هي طلقت؟","title":"حكم من طلق امرأته لفعلها ما نهاها عنه","answer":"الجواب: كما سمعتم، الكلام فيه أنه إذا قال: إذا خرجت فأنت طالق، أو كلمت فلانًا، إذا كان قصده منعها، ما قصده فراقها؛ فعليه كفارة يمين -كما سمعتم- إذا قال: إن كلمتِ فلانًا، أو خرجت إلى بيت فلان، أو خرجت بغير إذني؛ فأنت طالق، قصده منعها، ما قصده فراقها، فهذا حكمه حكم اليمين، وعليه كفارتها.  وأما إذا كان مقصوده فراقها إذا خرجت؛ فهي مطلقة، تحسب عليه طلقة، فإن طلقها قبلها طلقتان؛ تمت الطلقات، وحرمت عليه حتى تنكح زوجًا غيره. أما إذا كان ما قبلها إلا طلقة واحدة، أو ما قبلها شيء، فيراجعها.","link":"https://binbaz.org.sa/fatwas/1281/حكم-من-طلق-امراته-لفعلها-ما-نهاها-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_268.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5933,"question":"هل يقع الطلاق إذا طلقها طلاقًا بدعيًا؟","title":"حكم إيقاع الطلاق البدعي","answer":"الجواب: اختلف العلماء في الطلاق البدعي، هل يقع، أم لا يقع؟ فذهب الجمهور إلى أنه يقع، جمهور العلماء ذهب إلى أنه يقع مع التحريم، وذهب قوم إلى أنه لا يقع، واختاره جماعة من السلف، وهو مروي عن ابن عمر، وعن طاوس بن كيسان اليماني التابعي الجليل، وعن خلاد بن عمرو التابعي الجليل، واختاره شيخ الإسلام ابن تيمية، وابن القيم، وجماعة، قالوا لأنها وقع على خلاف أمر الله؛ فلا يقع. والجمهور قالوا: أخطأ، وأساء، وينفذ عليه؛ لأن ابن عمر احتسب طلقته التي طلقها في الحيضة، احتسبها، وأمضاها على نفسه، احتسبت عليه تطليقة، لكن لم يثبت أن النبي حسبها عليه، ولكن هو اعتبرها، وأمضاها على نفسه في ظاهر النصوص التي جاءت عنه.  وسئل في رواية عنه عمن طلقها في حال الحيض، فقال: لا يعتد بها، فهذا مما يبين أنه احتسب طلقتها التي طلقها في الحيض، احتسبها اجتهادًا منه والرسول ﷺ قال له: راجعها، ثم أمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شئت فطلق، وإن شئت فأمسك ولو كانت الطلقة واقعة؛ لكان المعنى تكثير الطلاق.","link":"https://binbaz.org.sa/fatwas/1276/حكم-ايقاع-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_263.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5934,"question":"كثيرا ما نسمع أن الحامل ليس عليها طلاق، هل هذا صحيح، أم لا؟","title":"حكم طلاق المرأة حال حملها","answer":"الجواب: هذا كلام العامة، كلام باطل، الحامل طلاقها مشروع، لها طلاق، إنما المنكر طلاق الحائض، طلاق النفساء، طلاق التي جامعها في طهر، هذا هو الذي لا يجوز الطلاق فيه، أما الحامل فطلاقها شرعي، النبي ﷺ قال لابن عمر: ثم ليطلقها طاهرًا أو حاملًا.","link":"https://binbaz.org.sa/fatwas/1285/حكم-طلاق-المراة-حال-حملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_272.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5936,"question":"لدي زوجة تؤدي الفروض الدينية كاملة، ولكنها تعاتب في بعض الأعمال حتى يحصل الزعل، ولا تقوم ببعض الأعمال إلا بزعل، وذلك أنها متعودة على الكسل، فهل يجوز لي طلاقها؟","title":"حكم تطليق الزوجة بسبب كسلها","answer":"الجواب: ينبغي لك الصبر، إن كانت طيبة، ودينة، وإن كان فيها بعض الكسل ينبغي لك الصبر، أنت عندك بعض الكسل، ما أحد سالم، ينبغي لك أن تكون طيبًا، وأن تعاونها على أمور البيت، عاونها، النبي كان يعاون أهله -عليه الصلاة والسلام- وهو أفضل الخلق، كان يساعد أهله في البيت على حاجات البيت. فأنت ساعدها، لا تجيب خادم، ساعدها حتى تسلم من الخادم، ساعدها على أمور البيت التي تعجز عنها، قد يكون معها أطفال قد أتعبنها، ساعدها على أمور البيت، شجعها على العمل بكلام طيب، ما هو يا خبيثة، يا فاجرة، يا كذا، يا كذا، يا بنت فلان، يا أم فلان، قومي كذا، عافاك الله، الله يرضى عليك، كذا كلام طيب.","link":"https://binbaz.org.sa/fatwas/1287/حكم-تطليق-الزوجة-بسبب-كسلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_274.mp3","categories":["الطلاق","الأيمان والنذور","الآداب والأخلاق المحمودة"]},{"id":5937,"question":"ما حكم طلاق الغضب الشديد الذي من عادته ألا يملك صاحبه نفسه؟","title":"حكم الطلاق حال الغضب المغلق","answer":"الجواب: تقدم الكلام في هذا وهو أن العلماء اختلفوا في ذلك، والأرجح أنه لا يقع إذا اشتد الغضب، وانغلق عليه قصده، ولم يتمالك نفسه، وظهرت الأسباب الدالة على ذلك. فإن الواقع يكون له أسباب، يكون معه أسباب تؤيد دعوى شدة الغضب، وعدم ذلك.","link":"https://binbaz.org.sa/fatwas/1307/حكم-الطلاق-حال-الغضب-المغلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_276.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5941,"question":"مدى صحة حديث: أبغض الحلال إلى الله الطلاق؟","title":"الحكم على حديث: أبغض الحلال إلى الله الطلاق","answer":"الجواب: لا بأس به جيد، روي متصلاً ومرسلاً والمتصل صحيح، من حديث ابن عمر.","link":"https://binbaz.org.sa/fatwas/1308/الحكم-على-حديث-ابغض-الحلال-الى-الله-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_277.mp3","categories":["الحكم على الأحاديث","الطلاق"]},{"id":5946,"question":"تشاجرت مع زوجتي في هذا اليوم بسبب طبخ مناسبة، ولم تأخذ أمرًا بالتنفيذ، وقلت لها: إنك طالق طالق طالق، وحضرني بعض أقربائي، وطلبوا مني أن أسترجع، وأن أذكر الله، فقلت: إنا لله وإنا إليه راجعون، ولي منها ثلاثة أولاد، وهي حامل، وهي راضية، وأنا راضي؟","title":"من طلق زوجته لخلاف حول الطعام","answer":"الجواب: هذا من عجائب الزمان، ما سوت له الطبخ يطلقها من أجل الطبخ..... كونها إذا نقصت الطبخ عما ينبغي في رأيك تطلقها؟ إن كانت رخيصة.. ما سويت كذا، امرأة أم أولادك جاءت بالألوف الكثيرة، ثم تطلقها عند أقل سبب، لا شك أنه نقص في العقل ... في الدين، ما يليق بالمؤمن هذا الشيء. أما الفتوى فتحتاج إلى حضور عندنا -إن شاء الله- ننظر في الفتوى، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/1306/من-طلق-زوجته-لخلاف-حول-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_275.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5949,"question":"ما حكم طلاق الغضب الشديد الذي من عادته ألا يملك صاحبه نفسه؟","title":"حكم الطلاق حال الغضب المغلق","answer":"الجواب: تقدم الكلام في هذا وهو أن العلماء اختلفوا في ذلك، والأرجح أنه لا يقع إذا اشتد الغضب، وانغلق عليه قصده، ولم يتمالك نفسه، وظهرت الأسباب الدالة على ذلك. فإن الواقع يكون له أسباب، يكون معه أسباب تؤيد دعوى شدة الغضب، وعدم ذلك.","link":"https://binbaz.org.sa/fatwas/1307/حكم-الطلاق-حال-الغضب-المغلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_276.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5967,"question":"كنت في مجلس مع زملائي، وحلفت بالله لئن جاء أخي أن أذبح شاة، وجاء أخي، وأنا في ذلك الوقت معسر، ولا أملك قيمة الشاة، فماذا أفعل؟","title":"حكم من عجز عن الوفاء بالنذر","answer":"الجواب: إذا تيسر تذبح الشاة، إذا تيسرت الشاة تذبحها؛ وفاء لنذرك، تذبحها على نية للفقراء، تعطيها للفقراء، على نية تأكلونها أنت، وأهل بيتك، تأكلها أنت، وأهل بيتك، إذا كان ما عندك نية؛ تعطيها الفقراء، لا تأكلها.","link":"https://binbaz.org.sa/fatwas/1338/حكم-من-عجز-عن-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_305.mp3","categories":["الطلاق","الأيمان والنذور","الآداب والأخلاق المحمودة"]},{"id":5969,"question":"أنا موظف حكومي،  وأستلم راتب الليل، ولا أحضر؛ لأنني لا أخرج في النهار إلا الساعة الثانية والنصف بعد انتهاء جميع المعاملات، فهل ما آخذه من الليل حلال، أم حرام؟","title":"حكم استلام الراتب بدون عمل","answer":"الجواب: هذا الذي يظهر أنه ليس بحلال، ينبغي أن تأخذ إذا كنت تعمل إذا كان ما هناك عمل تخبرهم أني ما أعمل، ولا أريد هذا الشيء.","link":"https://binbaz.org.sa/fatwas/1358/حكم-استلام-الراتب-بدون-عمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_316.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5971,"question":"إذا طلق رجل زوجته، وتمت ثلاثة قروء، هل تعتبر هذه طلقة، أم ثلاث؟ وإذا كان في رأس كل شهر من ذلك يقول لها: أنت طالق، فما الحكم؟","title":"ما يترتب على الطلاق الرجعي والبائن","answer":"الجواب: إذا طلقها طلقة واحدة، وتركها حتى اعتدت؛ فهي طلقة واحدة، وإذا اعتدت؛ بانت منه، وحلت لغيره من الأزواج، وإذا أحب أن يرجع إليها بعقد جديد؛ فلا بأس، إذا كان ما طلقها إلا واحدة، أو ثنتين، إذا خرجت من العدة؛ له الرجوع إليها بنكاح جديد كالأجنبي، يخطبها إذا رضيت، ورضي أهلها تزوجها. أما في العدة فله أن يراجعها في العدة ... يشهد اثنين أنه راجع زوجته، ما دامت في العدة قبل أن تروح عليها الحيضات الثلاث إن كانت تحيض، أو قبل شهور ثلاث إذا كانت لا تحيض، أو قبل الحمل إن كانت حاملًا؛ له أن يراجعها، سواء كانت طلقة، أو طلقتين. أما إذا طلقها آخر الثلاث، الطلقة الأخيرة؛ فإنها تحرم بذلك حتى تنكح زوجًا غيره، وليس له الرجوع إليها إلا بعد زوج ينكحها، ويطأها زوج شرعي، يتزوجها، ويطأها، لا نكاح تحليل، ولكن نكاح رغبة، يتزوجها زوج شرعي راغب فيها، ثم وطأها، ثم طلقها بعد ذلك، أو مات عنها؛ جاز لمن طلقها آخر الثلاث أن يتزوجها بعد ذلك.","link":"https://binbaz.org.sa/fatwas/1361/ما-يترتب-على-الطلاق-الرجعي-والباىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_319.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5976,"question":"إذا طلق رجل زوجته، وتمت ثلاثة قروء، هل تعتبر هذه طلقة، أم ثلاث؟ وإذا كان في رأس كل شهر من ذلك يقول لها: أنت طالق، فما الحكم؟","title":"ما يترتب على الطلاق الرجعي والبائن","answer":"الجواب: إذا طلقها طلقة واحدة، وتركها حتى اعتدت؛ فهي طلقة واحدة، وإذا اعتدت؛ بانت منه، وحلت لغيره من الأزواج، وإذا أحب أن يرجع إليها بعقد جديد؛ فلا بأس، إذا كان ما طلقها إلا واحدة، أو ثنتين، إذا خرجت من العدة؛ له الرجوع إليها بنكاح جديد كالأجنبي، يخطبها إذا رضيت، ورضي أهلها تزوجها. أما في العدة فله أن يراجعها في العدة ... يشهد اثنين أنه راجع زوجته، ما دامت في العدة قبل أن تروح عليها الحيضات الثلاث إن كانت تحيض، أو قبل شهور ثلاث إذا كانت لا تحيض، أو قبل الحمل إن كانت حاملًا؛ له أن يراجعها، سواء كانت طلقة، أو طلقتين. أما إذا طلقها آخر الثلاث، الطلقة الأخيرة؛ فإنها تحرم بذلك حتى تنكح زوجًا غيره، وليس له الرجوع إليها إلا بعد زوج ينكحها، ويطأها زوج شرعي، يتزوجها، ويطأها، لا نكاح تحليل، ولكن نكاح رغبة، يتزوجها زوج شرعي راغب فيها، ثم وطأها، ثم طلقها بعد ذلك، أو مات عنها؛ جاز لمن طلقها آخر الثلاث أن يتزوجها بعد ذلك.","link":"https://binbaz.org.sa/fatwas/1361/ما-يترتب-على-الطلاق-الرجعي-والباىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_319.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6091,"question":"هل الزوجة التي طلقها زوجها ثلاث طلقات، ثم تزوجت زوجًا آخر، ثم طلقها، ثم تزوجها الأول، هل لهذا الزوج ثلاث طلقات جديدة؟","title":"الطلقات المتبقية لمن تزوجت مطلقته بآخر ثم عادت إليه","answer":"الجواب: نعم، إذا طلقها الزوج آخر الطلاق، ثم تزوجت زوجًا شرعيًا، ووطئها، ودخل بها، ثم عادت إلى زوجها الأول بعد الطلاق، أو بعد الموت يكون له ثلاث طلقات مثل ما صار في النكاح الأول. لكن لو ما طلقها إلا واحدة، أو طلقها ثنتين، ثم تزوجت، ثم عادت إليه؛ فليس له إلا ما بقي من طلاقها الأول واحدة، أو اثنتين، هذا الذي بقي له، أما إذا كان قد استوفاها، ثم نكحت نكاحًا شرعيًا، ثم طلقت، أو مات زوجها بعد الدخول بها بعد وطئها؛ فإن زوجها الأول إذا تزوجها ترجع له بثلاث طلقات كالنكاح الأول. السؤال: وكذلك البائن بينونة صغرى، ثم تزوجها زوجها، فهل يحسب عليه الطلقة الأولى؟ الجواب: تقدم نعم، إذا كان طلقها واحدة، أو ثنتين، ثم رجعت إليه بنكاح جديد مخلوعة، أو مفسوخة؛ فإنها ترجع على الطلاق الباقي.","link":"https://binbaz.org.sa/fatwas/1510/الطلقات-المتبقية-لمن-تزوجت-مطلقته-باخر-ثم-عادت-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_440.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6098,"question":"الحديث لا طلاق في إغلاق حديث صحيح؟ وكذلك طلاق السكران، أو الذي يريد أن يخوف زوجته مثلًا يقول: إذا خرجت من البيت فأنت طالق؟","title":"الحكم على حديث: «لا طلاق في إغلاق»","answer":"الجواب: حديث لا طلاق، ولا عتق في إغلاق فيه لين، ولكن له شواهد تعضده، وتجبره، ويحتج به لشواهده من الكتاب والسنة، ومن ذلك قصة موسى حين ألقى الألواح بسبب الغضب، وكذلك قوله -جل وعلا-: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ [النحل:106].  فالإغلاق هو الإكراه، وشدة الغضب، الذي يغلق على الإنسان قصده، وفهمه حتى لا يتصور ما ترتب على الطلاق، بل من شدة الغضب، ومن شدة الإكراه ترخص عنده الزوجة، فلا يبالي بها أن يطلقها ليتخلص من هذا الإكراه، والظلم من ضربه، أو تهديده مما يضره، أو ما أشبه ذلك، أو شدة غضبه الذي ظهرت أسبابه، ودلائله، ووسائله حتى انغلق عليه قصده، وانغلقت عليه الدنيا بجملتها حتى لا يهمه إلا التخلص من هذه المرأة بسبب ما جرى بينه، وبينها من نزاع شديد، أو مضاربة، أو مسابة، أو ما أشبه ذلك. كذلك السكران؛ لأن السكران كالمجنون، وكالمعتوه، متى ثبت أنه حين طلق قد زال عقله بالسكر، أو بالعته، أو بالجنون، أو بالغضب الشديد الذي أزال شعوره؛ فإنه لا يقع معه الطلاق.  وهذه المسائل فيها تفصيل: إذا زال شعوره بالكلية، هذا عند الجميع، عند جميع أهل العلم، إذا زال شعوره بالكلية من شدة الغضب حتى سقط شعوره، فهذا لا يقع به الطلاق، كذلك العته الذي ما له عقل مخبول، وهكذا الجنون، فهذا لا طلاق له، وهكذا السكران الذي أكل، أو شرب ما يزيل عقله، ولم يتعمد هذا عند الجميع، لا يقع طلاقه. إنما الخلاف في مسألتين: إحداهما: السكران المتعمد للسكر حتى زال عقله متعمدًا، فالجمهور يرون أن طلاقه يقع، وذهب ... عثمان  وجماعة من أهل العلم إلى أنه لا يقع متى ثبت أنه طلق في حال السكر، ولو كان متعمدًا للشرب؛ لأن عقابه الحد الشرعي، لا فصل زوجته منه، بل عقابه معروف، وهو الحد الشرعي، أما إخراج زوجته من عصمته فليس ذاك من الحد الشرعي. كذلك المسألة الثانية: إذا كان غضبه شديدًا، ولكن لم يزل عقله بالكلية، بل اشتد به الغضب، وانغلق عليه عقله، ولم يملك نفسه، لكنه دون المجنون، لم يصل إلى حد ذهاب الشعور بالكلية، هذا محل الخلاف. وذهب قوم إلى أنه لا يقع إلحاقًا له بالمجنون المعتوه السكران، وذهب قوم إلى أنه يقع إلحاقًا له بالغضب الخفيف، إلحاقًا له بالعقلاء، والأرجح عدم وقوعه، إذا اشتد الغضب، وظهرت أسباب الغضب الشديد؛ فإنه يلحق بمن ذهب عقله؛ لأن الغضبان الشديد لا يملك نفسه، ولا يتصور العواقب، وقد يقع في أمور تضره، وهو لا يشعر.","link":"https://binbaz.org.sa/fatwas/1512/الحكم-على-حديث-لا-طلاق-في-اغلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_442.mp3","categories":["الحكم على الأحاديث","الطلاق"]},{"id":6147,"question":"رجل أضاف علي رجل آخر، وحلف بالطلاق ألا يأكل الذبيحة، وذهب، وجاء بذبيحة أخرى، وأكل منها، ماذا يلزم عليّ؟","title":"حكم الحلف بالطلاق على أمر دون قصد الطلاق","answer":"الجواب: إذا كان قصد الضيف أنه ما يكلف المستضيف الضيف النازل، طلق أنه ما يأكل ذبيحتك يا فلان، إن نزل عليك يبيه ما يتكلف، ولا يشتري ذبيحة، ويأكل من الطعام الحاضر، ثم أبى عليه المضيف، وجاء بذبيحة، وذبحها، وأكل منها، أو ما أكل منها؛ فإنه عليه الحكم في طلاقه إن كان أراد طلاق زوجته إن أكل الذبيحة، مضى عليه طلقة حسب ما قال. وإن كان إنما أراد منعه من الذبيحة، ولم يرد طلاق امرأته، ولكن أراد إذا سمع الطلاق أنه يمنعه ذلك؛ فعليه كفارة يمين، قال: عليه الطلاق ما يأكل الذبيحة، ما تذبح له، عليه الطلاق ما تذبح له، وذبح، أو عليه الطلاق ما يأكل، وأكل؛ فهذا عليه كفارة يمين، حكمه حكم اليمين، إذا كان المقصود من هذا الكلام منع النزول به من التكلف، وليس قصده فراق زوجته، وإنما قصده منع التكلف إذا سمع الطلاق يمتنع لا يأتي الذبيحة، ولا يتكلف، ثم صاحب الضيافة المنزول عليه تكلف، ولم يبال بيمينه، ولا بطلاقه، ثم أكل من ذبيحته إن كان طلاق أن لا يأكل، أو طلق أن لا يذبح، وذبح له؛ فإن الطلاق هذا يكون عن كفارة يمين إن كان ما قصد إيقاعه على الزوجة، ما قصد فراقها، وإنما قصد منعه من التكلف. هذا حكمه حكم اليمين، ما تحسب إذا كان قصده المنع، منع الرجل من التكلف عليه كفارة يمين، ولا يقع، إطعام عشرة مساكين، أو كسوتهم ..","link":"https://binbaz.org.sa/fatwas/1611/حكم-الحلف-بالطلاق-على-امر-دون-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_505.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6184,"question":"هل لي أن أتجسس على إنسان في بيته؛ لمعرفة إن كان عنده شيء من المحرمات، أو الخمور، أو يستعملها؟","title":"حكم التجسس على شخص لمعرفة إذا كان يعصي","answer":"الجواب: ليس لك التجسس؛ لأن الله يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] والنبي -عليه الصلاة والسلام- قال: لا تجسسوا. فلا يجوز التجسس، وهو التنقيب عن الشخص لعله يجده على معصية، لا بل إذا ستر الله مسلمًا فلا تحرص على كشفه، لكن متى ظهر الأمر، وبان بدون تجسس؛ وجب عليك النصيحة، والتوجيه إلى الخير، وإنكار المنكر، أما التجسس فلا يجوز.","link":"https://binbaz.org.sa/fatwas/1638/حكم-التجسس-على-شخص-لمعرفة-اذا-كان-يعصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_529.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6230,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6235,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6239,"question":"وأيضًا أخ ألح عليّ أن أعرض هذا الخطاب إلى سماحتكم، يقول فيه: نعم أنا تزوجت قبل خمس سنوات، وعندي ولد، وبنت، وحصلت مشاكل بين أبي، وأب زوجتي الأولى، وقد تغربت في السعودية حوالي سنة، ومن ثم ذهبت إلى اليمن، وزوجتي في بيت أبيها، ذهبت إلى والد زوجتي لاسترجاعها إلى بيت أبي، فطلب مني عمي أن أحضر أنا وزوجتي في بيته، لكن قال أبي: أنت تنفق عليها، وتكسوها، وهي تساعد أهلها في البيت، ولا تساعدنا، والآن والدي يخيرني بين أمرين، اختار طريق الجنة، وتتزوج امرأة غيرها، أو أن تذهب إلى طريق آخر، ولا أعرفك، ولا تعرفني، ولا أنا أبوك، تزوجت امرأة أخرى على شور أبي، وطلب مني أبي أن أطلق الأولى، وسألني عمي والد زوجتي الأخيرة: هل طلقت زوجتك الأولى، فقلت له: نعم، وأنا لم أطلقها، بل وعدته، وأنا لا أريد أن أطلق زوجتي الأولى، ولا أن أطلق الثانية، والآن أنا محتار بهذا الوعد الذي وعدت به عمي بطلاق زوجتي الأولى، وللمعلومية فإني متزوج بالثانية، فإني أخذت ابنته، وزوجت أختي من ابنه بدلًا يعني، وكل ما فكرت بالذهاب إلى اليمن؛ يضيق صدري بهذه المشاكل التي أخاف إن ذهبت أن تحصل، ما هو الحل، أرجو عند سماحتكم؟","title":"حكم طاعة الوالد في طلاق الزوجة","answer":"الجواب:  عليك يا أخي أن تجتهد في إرضاء أبيك، والمعاملة معه المعاملة الطيبة؛ لأن بره واجب، والزيارة له مهمة، عليك أن تعتني بوالدك، وتجتهد في إرضائه، ومخاطبته بالتي هي أحسن، وأن توسل بأقاربك الطيبين من أعمام، وغيرهم على أن يقنعوه إذا كانت الزوجة طيبة، إذا كانت الزوجة طيبة، ولا محذور فيها مستقيمة في دينها، فلا تحرص على طلاقها، ولا تعجل في طلاقها إذا كانت مستقيمة. أما إذا كان أبوك انتقدها؛ لأنها فاسدة، فهذه لا ينبغي بقاؤها، تطيع أباك، وتفارقها، أما إن كانت مستقيمة، دينة، معروفة بالصلاة، وغيرها من أمور الدين، ولكن أباك ما وضع الله في قلبه لها المحبة، فلا تعجل، ولا يلزمك الطلاق حينئذ إنما الطاعة في المعروف، الطاعة في المعروف لا فيما يضرك. فعليك أن لا تعجل، وأن تخاطب أباك بالتي هي أحسن، وأن تتوسل إلى إرضائه بأقاربه الطيبين، وجيرانه، ونحو ذلك؛ لعله يقنع، ولعله يرضى؛ حتى تبقى معك الزوجة، وتفوز بمرضاتك والدك، وبره. أما الزوجة الأولى التي قلت لأبيها: إنك طلقتها؛ فيقع بهذا عليها طلقة، إذا قلت: إنك طلقتها؛ فأنت مؤاخذ بإقرارك، إذا قلت طلقتها؛ فهي عليك طلقة، وعليك أن تراجعها إذا كانت في العدة، عليك أن تراجعها، فإن كانت خرجت من العدة؛ لم تحل إلا بنكاح جديد، ومهر جديد، بعد رضاها، وأولياءها بذلك، ولا ينبغي أن تستعجل في الطلاق أبدًا، ينبغي لك أن تعالج الأمور بالتي هي أحسن، بالأسلوب الطيب، وبالتعاون مع جيرانك، وإخوانك، وقراباتك على أبيك حتى يهديه الله. وخذها قاعدة: إذا كان أبوك انتقدها لأجل الدين، وسألت عنها، وعرفت أنها غير دينة، غير مستقيمة؛ فلا خير لك في بقائها، وطاعة الوالد في هذا حق، وإبعادها هو الواجب، والله يرزقك خيرا منها إذا طلقت، وأخلصت وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مِنْ أَمْرِهِ يُسْراً [الطلاق:4].","link":"https://binbaz.org.sa/fatwas/1751/حكم-طاعة-الوالد-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_590.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6246,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6270,"question":"وآخر يقول: أغضبتني أختي غضبًا شديدًا، فحلفت بالطلاق ثلاثًا أن لا أكلمها، وأن لا أسلم عليها ما دامت على قيد الحياة، ولا تدخل بيتي، وأنا الآن نادم، وأريد أن أزورها، وقد غيرت محل السكن من الطائف إلى بلاد بني مالك، فما حكمه؟","title":"حكم من حلف بالطلاق ثلاثاً أن لا يكلم أخته","answer":"الجواب: إذا طلق الإنسان أن لا يزور فلانًا، أو أن لا يكلم فلانًا؛ فالحكم ما يتعلق بالبيت، بل يتعلق بالشخص أينما كان، البيت إذا تغير ما يتغير الحكم إلا إذا قال في هذا البيت المعين، لا أزورها في هذا البيت المعين، قصده البيت المعين، أو لا يكلمها ما دامت في البيت المعين، إذا قصد البيت المعين، فإذا انتقل عنه؛ زال الحكم، لكن ما دام مقصود هجره، ما دام مقصود الزعل عليه هو؛ فالحكم يدور معه، هو سواء كان في نجد، أو في الحجاز، أو في أي مكان.  ولكن إذا كان القصد منها الطلاق، وأن لا يكلمها، وأن لا، وأن لا، إذا كان المقصود منع نفسه من زيارتها، وكلامها، وليس المقصود فراق زوجته إن كلمها، فهذا حكمه حكم اليمين، وعليه كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، وإذا عشاهم، أو غداهم؛ كفى، أو أعطى كل واحد نصف الصاع من التمر، أو الرز، أو نحو ذلك، وهو كيلو ونصف؛ كفى، هذا إن كان قصده منعها من الكلام، والزيارة. أما إن كان يقصد من ذلك أنه متى كلمها يقع الطلاق، متى كلمها يفارق زوجته، يقع في الثلاث طلقة واحدة، إذا قال: أنت طالق بالثلاث، إن زارها، أو كلمها؛ يقع فيها واحدة، إذا أراد الطلاق أن يقع، يقع طلقة واحدة، ويراجعها إذا كان ما لها طلاقان، إذا كان ما طلقها طلقتين؛ يكون بهذا طلقة إذا كلم أخته، إذا كان المقصود فراق زوجته إن كلمها.  أما إن كان المقصود ليس ذلك، المقصود منع نفسه من زيارتها، وكلامها، وليس المقصود فراق زوجته؛ فهذا فيه كفارة اليمين، ويكفي، وعليه التوبة إلى الله من هذا. السؤال: والفلوس لا تكفي في الكفارة؟ الجواب: لا، إما طعام، وإما كسوة.","link":"https://binbaz.org.sa/fatwas/1766/حكم-من-حلف-بالطلاق-ثلاثا-ان-لا-يكلم-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_605.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6275,"question":"سمعنا بعض العلماء يقول: إذا قال الرجل لزوجته: أنت طالق طالق طالق؛ فإن هذا يقع طلقة واحدة، وإذا قال: أنت طالق، أنت طالق، أنت طالق ثلاثًا؛ فإنه يقع ثلاث فما ..؟","title":"مسألة تأكيد الطلاق","answer":"الجواب: هكذا قرر أهل العلم، جمهور العلم على هذا، إذا قال: طالق طالق طالق، ولم ينو الثلاث؛ فإن اللفظ الثاني، والثالث يؤكد اللفظ الأول؛ لأنه ما كرر المبتدأ، ما كرر الجملة فقال: أنت طالق طالق طالق، مثل: جاء زيد زيد زيد، للتأكيد.  أما إذا قال: أنت طالق، أنت طالق، أنت طالق، أو هي طالق، هي طالق، هي طالق، ولم ينو تأكيدًا، ولا إسهامًا، وإنما نوى الثلاث، وأطلق؛ تقع الثلاث، بخلاف ما إذا قال: أنت طالق طالق طالق، أو هي مطلقة مطلقة مطلقة،  هذا لا يقع إلا الأولى واحدة، واللفظ الثاني، والثالث مؤكد للفظ الأول، ولا يقع فيه شيء عند أهل العلم، إلا أن تكون له نية في الثلاث، إن كان له نية في الثلاث؛ وقعت الثلاث عند جمهور أهل العلم، بل عند عامتهم، ولا يعرف خلاف في ذلك من المتقدمين.","link":"https://binbaz.org.sa/fatwas/1767/مسالة-تاكيد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_606.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6303,"question":"رجل طلق زوجته دون براءة، طلقها ثاني مرة دون براءة، ثم أرجعها، ومن ثم حرمها مرة أخرى على نفسه مثل أمه، أو أخته، وهو رجل  مقطوع، عمره خمس وستون عامًا، وهو لاجئ، ليس له أحد من الأهل، فما حكم ذلك؟","title":"رجل طلق زوجته مرتين ثم ظاهرها","answer":"الجواب: عليه التوبة إلى الله، وعليه كفارة الظهار، هذا مضى عليه طلقتان، وبقي عليه طلقة واحدة، فعليه أن يكفر كفارة الظهار، مثل ما أمر الله بذلك، وهي: عتق رقبة مؤمنة، فإن لم يستطع؛ صام شهرين متتابعين قبل أن يمسها، فإن لم يستطع؛  أطعم ستين مسكينًا، ستين فقيرًا، ثلاثين صاعًا، كل واحد له نصف صاع، تمر، أو رز من قوت البلد، رز، أو حنطة، أو شعير يعطيه الفقراء، ستين فقيرًا، ثلاثون صاعًا، كل واحد له نصف صاع قبل أن يمسها.","link":"https://binbaz.org.sa/fatwas/1891/رجل-طلق-زوجته-مرتين-ثم-ظاهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_674.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6317,"question":"رجل طلق زوجته دون براءة، طلقها ثاني مرة دون براءة، ثم أرجعها، ومن ثم حرمها مرة أخرى على نفسه مثل أمه، أو أخته، وهو رجل  مقطوع، عمره خمس وستون عامًا، وهو لاجئ، ليس له أحد من الأهل، فما حكم ذلك؟","title":"رجل طلق زوجته مرتين ثم ظاهرها","answer":"الجواب: عليه التوبة إلى الله، وعليه كفارة الظهار، هذا مضى عليه طلقتان، وبقي عليه طلقة واحدة، فعليه أن يكفر كفارة الظهار، مثل ما أمر الله بذلك، وهي: عتق رقبة مؤمنة، فإن لم يستطع؛ صام شهرين متتابعين قبل أن يمسها، فإن لم يستطع؛  أطعم ستين مسكينًا، ستين فقيرًا، ثلاثين صاعًا، كل واحد له نصف صاع، تمر، أو رز من قوت البلد، رز، أو حنطة، أو شعير يعطيه الفقراء، ستين فقيرًا، ثلاثون صاعًا، كل واحد له نصف صاع قبل أن يمسها.","link":"https://binbaz.org.sa/fatwas/1891/رجل-طلق-زوجته-مرتين-ثم-ظاهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_674.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6399,"question":"أنا قلت لزوجتي في حال غضب مني عليها: والله إذا ذهبت إلى أهلك لمدة ستة أشهر؛ فأنت طالق بالثلاثة، هل يجب الطلاق، أم يجب عليّ كفارة اليمين؟","title":"حكم طلاق الثلاث بلفظ واحد","answer":"الجواب: ينبغي للعاقل أن لا يعجل في الطلاق، ينبغي للعاقل أن يعالج الأمور بغير الطلاق، يعالج الأمور بالوعد، والوعيد، والتهديد، والتحذير بغير الطلاق،، يعدها بكذا من الكرامات، إذا استقامت؛ يتوعدها بشيء من الإهانة، وعدم إعطائها بعض المطالب، ويدع الطلاق بعيدًا، لكن هذا الذي يتوعدها بالطلاق له حالان: إحداهما: أن يقصد تنفيذ ما أراد، وأنه متى أخلت بما قالت؛ فإن الطلاق يقع بها، فهذا له ما نوى، ويقع عليها الطلاق، فإذا قال: إن مكثت عند أهلك ستة أشهر، أو يومًا، أو يومين، أو كذا، أو كذا؛ فأنت طالق، وهو يقصد طلاقها؛ وقع الطلاق، أو قال: إن كلمت فلانًا؛ فأنت طالق، وهو يقصد الطلاق؛ وقع الطلاق، أو قال: إذا خرجت إلى بيت فلا؛ن فأنت طالق، أو علي الطلاق إذا خرجت من بيتي -وهو يقصد ذلك- وقع الطلاق، يقول المصطفى -عليه الصلاة والسلام-: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى. أما الذي يقصد تهديدها، وتحذيرها، ولا يقصد فراقها، لكن يقصد تخويفها، وتحذيرها، كأن يقول: إن كلمت فلانًا؛ فأنت طالق، أو إن زرت فلانة؛ فأنت طالق، أو ذهبت إلى أهلك بغير إذني؛ فأنت طالق، يقصد تخويفها، وتحذيرها، ولم يقصد فراقها، والله يعلم ما في قلبه، وإنما أراد التحذير، فهذا حكمه حكم اليمين، وعليه كفارة ظهار إذا أخلت بالمطلوب، إذا خالفته عليه كفارة يمين، مثل قوله: والله لا تذهبين، والله ما تفعلي كذا، وكذا حكمه حكم اليمين في أصح قولي العلماء، كما أفتى بهذا جمع من أهل العلم، من السلف في عهد الصحابة، وفي عهد التابعين وأفتى بهذا أيضًا أبو العباس ابن تيمية شيخ الإسلام -رحمة الله عليه- والعلامة ابن القيم، وجمع من أهل العلم من القدماء، وغيرهم؛ لأن هذا يقع من الناس كثيرًا بالتخويف، والتحذير لا لأجل إيقاع الطلاق. أما إذا علق الطلاق على شيء ما فيه تخويف، من طبيعته أنه ليس فيه تخويف، يعني إذا دخل رمضان فأنت طالق، إذا ولدت فأنتِ طالق، إذا حملت فأنت طالق، يقع الطلاق بهذا، وما أشبه ذلك. السؤال: إذا قال لزوجته: أنتِ طالق بالثلاث الجواب: إذا قال: أنت طالق بالثلاث؛ تكون واحدة على الصحيح، إذا قال: أنت طالق بالثلاث، بهذا اللفظ، أما إذا قال: أنت طالق، ثم طالق، ثم طالق، تقع الثلاث، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1970/حكم-طلاق-الثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_757.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6410,"question":"هل يقع الطلاق البدعي؟ وهل الطلاق بالثلاث محرم، مثل أن يقول: أنت طالق، أنت طالق، أنت طالق في آن واحد؟ وهل هذا من الطلاق البدعي؟","title":"حكم وقوع الطلاق البدعي","answer":"الجواب: الطلاق البدعي مثل ما سمعت، الطلاق البدعي إذا كان باللفظ أنت مطلقة بالثلاث، أو فلانة مطلقة بالثلاث، لا يقع إلا وحدة على الراجح؛ لحديث ابن عباس أن الطلاق كان في عهد النبي ﷺ طلاق الثلاث واحدة، وهكذا في عهد الصديق، وفي أول خلافة عمر، ثم أمضاه عمر. فالصحيح: أنه لا يقع به إلا واحدة، يرد إلى السنة، أما إذا كررها، قال: طالق، ثم طالق، ثم طالق، أو أنت طالق، أنت طالق، أنت طالق، وأراد إيقاع الثلاث، أو ما أراد تأكيدًا، ولا إفهامًا، بل أطلقها هكذا: أنت طالق، أنت طالق، أنت طالق، يقع الطلاق، يقع الطلاق ثلاثًا.  أما في الحيض، والنفاس فهذا محل خلاف بين أهل العلم، فالقول بعدم وقوعه قوي جدًا؛ لأنه خالف أمر الله؛ فلا يقع، لكن الجمهور، والأكثر من أهل العلم على إيقاعه، وظاهر السنة، وظاهر القواعد الشرعية أنه لا يقع، وقد أفتى به جماعة من التابعين، وأفتى به ابن عمر نفسه  الذي وقعت عليه الحادثة، أفتى بأنه لا يقع؛ لأنه خالف السنة، خالف الشرع. السؤال: الطلاق البدعي لا يقع؟ الجواب: الذي في الحيض، والنفاس عند بعض أهل العلم، أما طلاق الثلاث جميعًا، فهذا يقع منه واحدة إذا كان بلفظ واحد أنت طالقة بالثلاث، أو مطلقة بالثلاث يقع واحدة. أما إذا كرره قال: أنت طالق، أنت طالق، أنت طالق، ولم ينو تأكيدًا، ولا إفهامًا، بل نوى الثلاث جميعًا، أو ما نوى شيئًا، بل كرره، وهكذا؛ يقع الثلاث. أو قال: أنت طالق، ثم طالق، ثم طالق، أو طلقها اليوم، ثم طلقها غدًا، ثم طلقها بعد غد في العدة؛ لحق الطلاق بها.","link":"https://binbaz.org.sa/fatwas/2125/حكم-وقوع-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_773.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6414,"question":"هل يقع الطلاق بغير ألفاظه مثل أن يقول الرجل: اذهبي إلى أهلك، وينوي بذلك الطلاق؟","title":"حكم الطلاق بالكنايات","answer":"الجواب: نعم، إذا أوقعه بالكنايات وقع، قال: الحقي بأهلك، أو روحي لأهلك، أو اذهبي إلى أهلك ناوياً الطلاق؛ يقع واحدة.","link":"https://binbaz.org.sa/fatwas/2126/حكم-الطلاق-بالكنايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_774.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6416,"question":"ما صحة حديث لا طلاق في إغلاق وما هو الإغلاق؟ وهل للغضب عند الطلاق أنواع، أم هو نوع واحد؟","title":"حكم حديث لا طلاق في إغلاق","answer":"الجواب: حديث لا طلاق، ولا عتق في إغلاق في سنده لين، ولكنه له طرق، وله شواهد، فالأولى الأخذ به، وأنه إذا كان الطلاق في إغلاق، وهو الإكراه، والغضب الشديد؛ لا يقع إذا ثبت الإغلاق، ثبت الإكراه، وثبت وقوع الغضب الشديد بإقرارهما جميعًا، أو ببينة شاهدة بذلك.","link":"https://binbaz.org.sa/fatwas/2129/حكم-حديث-لا-طلاق-في-اغلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_777.mp3","categories":["الحكم على الأحاديث","الطلاق"]},{"id":6421,"question":"هل طلاق الذي لا يحسن التصرف لكبر يعتبر طلاقًا، وهذه المرأة جلست معه أكثر من ثلاثين عامًا، لم ترزق منه بولد، وتريد الطلاق فهل عليها إثم، أم لا؟ والله الموفق.","title":"حكم طلاق من لا يحسن التصرف","answer":"الجواب: إذا طلقها وهو يعلم الطلاق، ما خرف، ولا زال عقله؛ يقع الطلاق، إذا طلقها وعقله معه يقع، أما هي فإن صبرت عليه؛ فهو أولى، تصبر عليه أحسن، وأولى، أما إن كان هناك عليها مشقة؛ لأنه عنيف عليها، أو يؤذيها، أو أسباب أخرى أوجبت ذلك؛ فلا حرج عليها في طلب الطلاق؛ لأن الرسول ﷺ قال: من غير ما بأس أما هذه قد وجدت بأسًا، قد وجدت ضررًا، فإن وجدت ضررًا، وإيذاء؛ فلا مانع من طلبها الطلاق، وإن صبرت عليه، وأحسنت فيه في كبره؛ فلها أجر عظيم.","link":"https://binbaz.org.sa/fatwas/2132/حكم-طلاق-من-لا-يحسن-التصرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_780.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6424,"question":"قال في سبل السلام: لو ظاهر الرجل يريد طلاقًا؛ كان ظهارًا، ولو طلق يريد ظهارًا؛ كان طلاقًا، فهل هذا صحيح؟ وكيف يجمع بينه، وبين إنما الأعمال بالنيات؟","title":"حكم اعتبار الظهار طلاقاً","answer":"الجواب: الله جعل الظهار ظهارًا؛ لأن الجاهلية تجعله طلاقًا، فالله حكم بأن الظهار ظهار تحريم، وبين فيه الكفارة  في كتابه الكريم، فلا يجعل الطلاق، فإذا قال: أنت علي كظهر أمي، أو كظهر أختي، أو بنتي؛ فإنه ظهار، ولو نواه طلاقًا، بل هو ظهار كما شرع الله ضد أعمال الجاهلية، قد أبطل الله أعمال الجاهلية؛ فيكون له حكم الظهار، وعليه الكفارة، وهي: عتق رقبة، فإن عجز؛ صام شهرين متتابعين، فإن عجز؛ أطعم ستين مسكينًا قبل أن يمسها. أما إذا قال: أنت طالق، ونوى الظهار، ما يصير ظهارًا؛ لأن هذا ما يرد على الظهار، أنت طالق لفظه صريح الطلاق، فلا ينتقل عن صريح الطلاق إلى معنى آخر.","link":"https://binbaz.org.sa/fatwas/2128/حكم-اعتبار-الظهار-طلاقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_776.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6442,"question":"فضيلة الشيخ يسأل رجل طلق زوجته ثلاثًا بلفظ واحد، وكتب بذلك ورقة، وأرسلت إلى الزوجة، وأشهد على ذلك، وبعد وقت قصير تأسف، واسترجع زوجته، فهل تحل له، أم ماذا؟ مع العلم أن الزوجة لها ثلاثة أولاد، وأن الطلاق في حالة غضب، أفتونا جزاكم الله خير الجزاء؟","title":"حكم الطلاق ثلاثاً بلفظ واحد","answer":"الجواب: طلاق الثلاث إن كانت بواحدة كأن يقول: فلانة طالقة بالثلاث، أو مطلقة بالثلاث، أو علي الطلاق بالثلاث فيها خلاف بين أهل العلم، أكثر أهل العلم من عهد عمر  وما بعده، أكثرهم يقولون: إنها تمضي، وتنفذ، ولا تحل له إلا بعد زوج، وهكذا قال أكثر أهل العلم.  وذهب بعض أهل العلم، وهو قول أهل العلم في عهد الصديق  وفي أول خلافة عمر، وهو الذي عليه الحال في عهد النبي ﷺ أن الثلاثة باللفظ الواحد تعتبر واحدة، طلقة واحدة رجعية، وهذا هو الذي أفتي به أنها تكون واحدة رجعية، وأفتى به جماعة من أهل العلم من عهد ابن عباس، ومن بعده، وثبت عن ابن عباس في رواية عنه  أنه أفتى بها أيضًا، وأفتى بقول الجمهور، وثبت عن جماعة من أصحابه، أفتوا بأنها واحدة، وأفتى بذلك أبو العباس ابن تيمية شيخ الإسلام -رحمه الله- وتلميذه العلامة ابن القيم رحمه الله، هذا القول أرجح من حيث الدليل أنها واحدة إلا إذا حكم الحاكم بإمضائها، فحكم الحاكم يرفع الخلاف. إذا كان الزوج قد اتصل بالمحكمة، وحكمت المحكمة بأن هذا الطلاق ماض، وأنها بانت، فالحكم يرفع الخلاف، وتكون بائنة إلا إذا رجع الحاكم عن حكمه، ورأى أن يجعلها واحدة، وأذن لغيره في ذلك؛ فلا بأس. المقصود: الصحيح أنها واحدة، لكن إذا حكم أحد الحكام الشرعيين بإمضائها عملًا بقول الجمهور، وأنها لا تحل إلا بعد زوج، فهذا قول له وجهه، وقد ذكر العلماء أن حكم الحاكم يرفع الخلاف، وله نقضه إذا رأى أن الأدلة الشرعية تقتضي ذلك، أو أن لغيره من الحكام، أو المفتيين بنقضه إذا رأى ... فلا بأس، هذا هو الجواب عن هذه المسألة.  والغضب فيه تفصيل، الغضب أنواع ثلاثة: غضب عادي لا يمنع الطلاق، وغضب شديد يغير على الإنسان حاله، وقصده، ولا يتمكن معه من الطلاق الشرعي، بل يعمى عليه قصده، ويعمى عليه طريقه بسبب طول النزاع، وشدة النزاع، والمضاربة بينهما، أو السباب، والمشاتمة بينهما، فهذا إذا اشتد الغضب، لا يقع معه الطلاق على الصحيح أيضًا. والحال الثالث: أن يوقعه الغضب في عدم الشعور، وأن يكون كسائر المجانين، والمعتوهين، قد ألجأه وأوقعه الغضب في زوال العقل، فلا يعقل ما يقول، وهذا لا يقع طلاقه عند جميع أهل العلم، ويلحق في هذه الحالة بالمعتوهين، والمجانين، فلا يقع طلاقه إذا كان غضبه قد أوقعه في هذه الحالة.","link":"https://binbaz.org.sa/fatwas/2195/حكم-الطلاق-ثلاثا-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_820.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6463,"question":"فضيلة الشيخ يسأل رجل طلق زوجته ثلاثًا بلفظ واحد، وكتب بذلك ورقة، وأرسلت إلى الزوجة، وأشهد على ذلك، وبعد وقت قصير تأسف، واسترجع زوجته، فهل تحل له، أم ماذا؟ مع العلم أن الزوجة لها ثلاثة أولاد، وأن الطلاق في حالة غضب، أفتونا جزاكم الله خير الجزاء؟","title":"حكم الطلاق ثلاثاً بلفظ واحد","answer":"الجواب: طلاق الثلاث إن كانت بواحدة كأن يقول: فلانة طالقة بالثلاث، أو مطلقة بالثلاث، أو علي الطلاق بالثلاث فيها خلاف بين أهل العلم، أكثر أهل العلم من عهد عمر  وما بعده، أكثرهم يقولون: إنها تمضي، وتنفذ، ولا تحل له إلا بعد زوج، وهكذا قال أكثر أهل العلم.  وذهب بعض أهل العلم، وهو قول أهل العلم في عهد الصديق  وفي أول خلافة عمر، وهو الذي عليه الحال في عهد النبي ﷺ أن الثلاثة باللفظ الواحد تعتبر واحدة، طلقة واحدة رجعية، وهذا هو الذي أفتي به أنها تكون واحدة رجعية، وأفتى به جماعة من أهل العلم من عهد ابن عباس، ومن بعده، وثبت عن ابن عباس في رواية عنه  أنه أفتى بها أيضًا، وأفتى بقول الجمهور، وثبت عن جماعة من أصحابه، أفتوا بأنها واحدة، وأفتى بذلك أبو العباس ابن تيمية شيخ الإسلام -رحمه الله- وتلميذه العلامة ابن القيم رحمه الله، هذا القول أرجح من حيث الدليل أنها واحدة إلا إذا حكم الحاكم بإمضائها، فحكم الحاكم يرفع الخلاف. إذا كان الزوج قد اتصل بالمحكمة، وحكمت المحكمة بأن هذا الطلاق ماض، وأنها بانت، فالحكم يرفع الخلاف، وتكون بائنة إلا إذا رجع الحاكم عن حكمه، ورأى أن يجعلها واحدة، وأذن لغيره في ذلك؛ فلا بأس. المقصود: الصحيح أنها واحدة، لكن إذا حكم أحد الحكام الشرعيين بإمضائها عملًا بقول الجمهور، وأنها لا تحل إلا بعد زوج، فهذا قول له وجهه، وقد ذكر العلماء أن حكم الحاكم يرفع الخلاف، وله نقضه إذا رأى أن الأدلة الشرعية تقتضي ذلك، أو أن لغيره من الحكام، أو المفتيين بنقضه إذا رأى ... فلا بأس، هذا هو الجواب عن هذه المسألة.  والغضب فيه تفصيل، الغضب أنواع ثلاثة: غضب عادي لا يمنع الطلاق، وغضب شديد يغير على الإنسان حاله، وقصده، ولا يتمكن معه من الطلاق الشرعي، بل يعمى عليه قصده، ويعمى عليه طريقه بسبب طول النزاع، وشدة النزاع، والمضاربة بينهما، أو السباب، والمشاتمة بينهما، فهذا إذا اشتد الغضب، لا يقع معه الطلاق على الصحيح أيضًا. والحال الثالث: أن يوقعه الغضب في عدم الشعور، وأن يكون كسائر المجانين، والمعتوهين، قد ألجأه وأوقعه الغضب في زوال العقل، فلا يعقل ما يقول، وهذا لا يقع طلاقه عند جميع أهل العلم، ويلحق في هذه الحالة بالمعتوهين، والمجانين، فلا يقع طلاقه إذا كان غضبه قد أوقعه في هذه الحالة.","link":"https://binbaz.org.sa/fatwas/2195/حكم-الطلاق-ثلاثا-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_820.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6542,"question":"إنسان طلق على أنه لا يقعد عند هذا الشخص، وفي يوم من الأيام ذهب إليه، فما حكم ذلك اليمين؟","title":"حكم من علق طلاقه على شرط","answer":"الجواب: إذا طلق الإنسان لا يقعد عند فلان، أو لا يكلم فلانًا؛ فله حالان: إحداهما: أن يقصد منع نفسه، ولا يقصد إيقاع الطلاق، إنما قصد منع نفسه من هذا الشيء، وشدد على نفسه بالطلاق، ولم يرد إيقاع الطلاق على أهله، وإنما أراد منع نفسه من قعوده عنده، أو الكلام، فهذا حكمه حكم اليمين على الصحيح، وعليه كفارة اليمين ولا يقع الطلاق. أما إذا أراد وقوع الطلاق، وأنه نوى إذا قعد عنده فزوجته طالق، أو كلمه فزوجته طالق؛ فإنه متى كلمه، أو قعد عنده يقع طلقة على زوجته؛ لأنه طلاق معلق على الشرط، مثل لو قال: إذا دخل رمضان فزوجته طالق؛ تطلق، أو قال: إذا نزل المطر فزوجته طالق، أو قال: إذا حاضت فهي طالق، وما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/2372/حكم-من-علق-طلاقه-على-شرط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_906.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6548,"question":"شخص طلق وهو في حالة سكر على ألا يركب السيارة مع أشخاص، ثم ركب معهم، ولكن في مقدمة السيارة، والبقية في المؤخرة؟","title":"حكم طلاق السكران","answer":"الجواب: السيارة كلها واحدة مقدمها، ومؤخرتها، لكن إذا كان عقله معه وقع الطلاق إن كان قصد الطلاق، وإن كان عقله ما هو معه، يتكلم وهو غير عاقل، غائب العقل؛ فهو مثل المجنون، لا يقع طلاقه، إذا تكلم وهو غير عاقل مثل المجنون لا يقع طلاقه. أما إن كان يعقل فيستفصل؛ إن كان أراد منع نفسه من الركوب مثل ما تقدم في الذي طلق ألا يكلم فلاناً، أو لا يقعد عنده إن كان طلق .. وليس قصده فراق زوجته، وإنما قصده منع نفسه من الركوب، والتشديد على نفسه؛ فهذا حكمه حكم اليمين، وعليه كفارتها، فإن كان أراد إيقاع الطلاق، يعني ركب، فيقع الطلاق على زوجته، يقع عليها طلقة في ذلك إذا كان عقله معه، سواء ركب في مقدمها، أو مؤخرها، إلا إذا قال: إنه لا يركب في المقدمة، أو في المؤخرة عيّن فهو على ما عيّن وعلى ما ...","link":"https://binbaz.org.sa/fatwas/2373/حكم-طلاق-السكران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_907.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6593,"question":"رجل طلق زوجته في طهر جامعها فيه، ولكن حيل بينه وبين فض بكارتها، فهل يقع الطلاق، أم لا؟ مع أن هذا الأمر تكرر ثلاث مرات، وراجعها في الطلقة الأولى، والثانية، فهل بانت منه، أم لا؟","title":"حكم طلاق الرجل للمرأة في طهر جامعها فيه","answer":"الجواب: هذه المسألة خلاف بين أهل العلم، جمهور أهل العلم يرون أنه إذا طلقها ولو في طهر جامعها فيه؛ يقع الطلاق، لو أنه .. الطلاق في طهر جامعها فيه، أو في الحيض، أو في النفاس. وذهب آخرون من أهل العلم إلى أنه إذا طلقها في الحيض، أو في النفاس، أو في طهر جامعها فيه وهي ليست حاملًا أنه لا يقع؛ لحديث ورد عن ابن عمر في ذلك أنه طلق امرأته وهي حائض، فغضب عليه النبي ﷺ وأنكر عليه، وقال له: ارجعها، وأمسكها حتى تحيض، ثم تطهر، ثم تحيض، ثم تطهر، ثم إن شاء طلق، وإن شاء أمسك فقال رسول الله: فتلك العدة التي أمر الله أن تطلق لها النساء. وهذا يدل على أن الطلاق الذي فعله ابن عمر غير واقع؛ لأن الرسول ﷺ أمره أن يرجعها، ولم يسأله هل واحدة، أو ثنتين، أو ثلاث، بل أمره أن يرجعها، فدل ذلك على أن الطلاق غير واقع؛ لأنه عاصٍ لله في طلاقها في الحيض، أو في النفاس، أو في طهر جامعها فيه، فعليه أن يردها وأن يراجعها، ثم إذا أراد الطلاق يطلقها بعد ذلك إذا طهرت قبل أن يطأها. وأما إذا طلقها وهي حامل؛ فطلاقها ماضٍ، أو طلقها في طهر لم يجامعها فيه؛ فطلاقها ماضٍ، ولكن إذا طلقها في الطهر الذي جامعها فيه، وهي غير حبلى، أو في الحيض، أو في النفاس، فجمع من أهل العلم يقولون: لا يقع الطلاق؛ لأنه معصية. السؤال: يعني فض البكارة ليس شرطًا؟ الجواب: لا ما هو بشرط.","link":"https://binbaz.org.sa/fatwas/2436/حكم-طلاق-الرجل-للمراة-في-طهر-جامعها-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_963.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6660,"question":"هل يحق للزوجة مطالبة زوجها بالطلاق إذا كان يسكر، لأني قرأت فتوى في إحدى المجلات تجيز ذلك إذا كان الزوج لا يؤذي زوجته، ويلبي كافة حقوقها، ولا يؤذيها، أفيدونا جزاكم الله خيرًا؟","title":"حكم المطالبة بالطلاق إذا كان الزوج يسكر","answer":"الجواب: وهل  هناك أشد من الأذى في السكر، السكران مجنون، قد يقتلها بعض الأحيان -نسأل الله العافية- لها الحق أن تطلب الطلاق إذا كان زوجها سكيرًا، أو يتساهل في الصلاة، أو يفعل جرائم أخرى، كاللواط، أو يأتيها في الدبر، لها الحق أن تطلب الطلاق؛ لأنه -زوجها- مجرم، فلها أن تطلب الطلاق.  في الحديث أيما امرأة طلبت الطلاق من غير ما بأس من غير ما علة يعني لم ترح رائحة الجنة أما هذه لها علة، إذا كان لا يصلي هذا كافر -نعوذ بالله- لا تقم عنده، ولا يجوز لها البقاء عنده: لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]. وإذا كان يسكر، أو يتعاطى الجماع في الدبر، أو ما أشبه ذلك من المعاصي؛ لها طلب الطلاق، وعليها أن تمتنع منه، لا يجوز لها أن تمكنه من دبرها، ليس له الجماع إلا في القبل، أما الدبر فلا، هذا لواط.","link":"https://binbaz.org.sa/fatwas/2549/حكم-المطالبة-بالطلاق-اذا-كان-الزوج-يسكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1044.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6987,"question":"رجل طلق زوجته ثلاث مرات متفاوتات، وقد أنجب منها عشرة أولاد، ما بين ذكور، وإناث، أفيدونا جزاكم الله خيرًا؟","title":"الطلاق الذي يحرم الزوجة من زوجها","answer":"الجواب:\n\nإذا طلقها ثلاثًا متفرقات؛ انتهت فَإِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ [البقرة:230] يعني في المرة الثالثة، قال أولًا: الطَّلَاقُ مَرَّتَانِ [البقرة: 229]، ثم قال: فَإِنْ طَلَّقَهَا [البقرة:230] يعني الثالثة، فإذا طلقها، ثم راجعها، ثم طلقها، ثم راجعها، ثم طلقها الثالثة؛ خرجت، انتهت، وحرمت عليه، حتى تنكح زوجًا غيره.\n\nوهكذا لو قال: طالق، ثم طالق، ثم طالق؛ انتهت، إذا كان الطلاق .. العقل ما وقع في حال سكر، ولا في حال شدة غضب يغير شعوره، ما ملك نفسه، ولا في حال الحيض، ولا في حال النفاس، ولا في طهر جامعها فيه، فإن الطلاق يمضي عليه على الصحيح عند أهل العلم جميعًا، إذا سلم الطلاق من الموانع؛ يمضي عليه الطلاق، إذا طلقها ثلاثًا؛ حرمت عليه، حتى تنكح زوجا غيره.\n\nأما إذا كان طالقًا بالثلاث، كلمة واحدة، أنت مطلقة بالثلاث، هذا فيه خلاف بين أهل العلم، الأكثرون يرون أنها تمضي عليه أيضًا، وتحرم عليه، إلا بعد الزوج.\n\n وذهب بعض أهل العلم إلى أنها تحسب واحدة، كما كان في عهد النبي ﷺ وعهد الصديق، وعهد عمر في أول خلافته، وهذا هو الأرجح، أنها تحسب واحدة إذا كان بكلمة واحدة، قال: هي مطلقة بالثلاث، أو طالق بالثلاث، الأرجح من قولي العلماء: أنها تحسب واحدة، وله مراجعتها.\n\nأما إذا كان في أوقات، أو بكلمات طالق، ثم طالق، ثم طالق، أو طلق، ثم راجع وطلق، ثم راجع، ثم طلق الثالثة؛ تحرم عليه حتى تنكح زوجا غيره، فهذا مقام الطلاق مقام فيه تفصيل.","link":"https://binbaz.org.sa/fatwas/2924/الطلاق-الذي-يحرم-الزوجة-من-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1372.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7007,"question":"نرجو الإجابة على سؤالي هذا: أحد الإخوة هنا يدرس في معهد، وهو من جيزان، وقته ضيق، وليس عنده راحة إلا يوم الخميس والجمعة، فيقول: أرجو الإجابة على سؤالي هذا، إنه صار بيني وبين زوجتي خلاف في شأن الحجاب، وأمور أخرى، وقد ذهبت إلى أهلها عدة مرات، وأعيدها، والمرة الأخيرة لا زالت عند أهلها إلى وقتنا الحاضر منذ ثلاثة أشهر تقريبًا، وقد أوصلتها هذه المرة في عدم الرغبة في معاشرتها مرة ثانية، وما عدا لي رغبة فيها، ولي منها بنت صغيرة، وأرغب استرجاعها، هل يجوز لي ذلك، أم لا، أرجو إفادتي جزاكم الله خيرًا؟","title":"حكم من نوى الطلاق ولم يتلفظ به","answer":"الجواب:\n\nما دامت لم تطلق، إنما نويت نية، فالنية لا يقع بها الطلاق، يقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت بها أنفسها ما لم تعمل أو تتكلم ما دام ناوي طلاقها، ولكن ما تكلمت بشيء؛ فهي زوجتك باقية.\n\nأما إن كنت تكلمت، تقول: روحي لأهلك، نويت الطلاق، أو أنت مطلقة، أو خارجة من ذمتي، أو ما أشبه ذلك؛ تعتبر طلقة واحدة، إذا قلت هذا الكلام فقط، أما إن كان مجرد نية فقط في نفسك، ولكن ما تكلمت بشيء؛ فهي باقية في عصمتك.\n\nالسؤال: ... هل ممكن يأخذ البنت؟\n\nالجواب: هي وأمها يأتي يأخذهن كلهن.\n\nالسؤال: لا، لو ما يريد يأخذ الأم ..؟\n\nالجواب: هذا عند المحكمة يا ولدي.","link":"https://binbaz.org.sa/fatwas/2930/حكم-من-نوى-الطلاق-ولم-يتلفظ-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1378.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7010,"question":"إذا قال الزوج عليه الحرام، ولا يقصد الطلاق، وكذلك لو قال: أنت علي حرام، وأراد الطلاق، فهل يكون طلاقًا؟","title":"حكم من يحرم امرأته على نفسه","answer":"الجواب:\n\nإذا قال: أنت علي حرام، وأراد الطلاق؛ فالصحيح أنه يكون طلاقًا، يكون طلقة واحدة على الصحيح، وإذا قال: عليه الحرام ما يفعل كذا، فله تفسيران:\n\nأحدهما: أن يقصد عليه الطلاق يعني: فعلى نيته إذا قصد الطلاق، وأنه إذا فعل كذا؛ وقع الطلاق، وقع الطلاق.\n\nأما إذا كان يقصد منع نفسه من هذا الشيء، عليه الطلاق ما يكلم فلانًا، عليه الطلاق ما تروحي لها، عليه الطلاق ما تكلمي فلانًا، بقصد منعها -ما قصده الطلاق- فهذا فيه خلاف بين أهل العلم، الصحيح أنه يكون في حكم اليمين، أن عليه كفارة يمين؛ لأن قصده المنع، ليس قصده الطلاق، والرسول ﷺ يقول: الأعمال بالنيات.\n\nفإذا كان قصده المنع، عليه الطلاق ما يكلم فلانُا، عليه الطلاق ما تروحي لأحد، عليه الطلاق ما تكلمي فلانًا، ما قصد إيقاع الطلاق، وإنما قصد تخويفها، ومنعها؛ فهذا الصواب فيه أنه عليه كفارة يمين.\n\nأما إذا قصد إيقاع الطلاق، منعها، وإيقاع الطلاق؛ فإنه يقع الطلاق طلقة واحدة، إلا إذا كرر عليه الطلاق، عليه الطلاق، عليه الطلاق، يقصد ثلاثًا وقعت الثلاث.","link":"https://binbaz.org.sa/fatwas/2941/حكم-من-يحرم-امراته-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1389.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7017,"question":"نرجو الإجابة على سؤالي هذا: أحد الإخوة هنا يدرس في معهد، وهو من جيزان، وقته ضيق، وليس عنده راحة إلا يوم الخميس والجمعة، فيقول: أرجو الإجابة على سؤالي هذا، إنه صار بيني وبين زوجتي خلاف في شأن الحجاب، وأمور أخرى، وقد ذهبت إلى أهلها عدة مرات، وأعيدها، والمرة الأخيرة لا زالت عند أهلها إلى وقتنا الحاضر منذ ثلاثة أشهر تقريبًا، وقد أوصلتها هذه المرة في عدم الرغبة في معاشرتها مرة ثانية، وما عدا لي رغبة فيها، ولي منها بنت صغيرة، وأرغب استرجاعها، هل يجوز لي ذلك، أم لا، أرجو إفادتي جزاكم الله خيرًا؟","title":"حكم من نوى الطلاق ولم يتلفظ به","answer":"الجواب:\n\nما دامت لم تطلق، إنما نويت نية، فالنية لا يقع بها الطلاق، يقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت بها أنفسها ما لم تعمل أو تتكلم ما دام ناوي طلاقها، ولكن ما تكلمت بشيء؛ فهي زوجتك باقية.\n\nأما إن كنت تكلمت، تقول: روحي لأهلك، نويت الطلاق، أو أنت مطلقة، أو خارجة من ذمتي، أو ما أشبه ذلك؛ تعتبر طلقة واحدة، إذا قلت هذا الكلام فقط، أما إن كان مجرد نية فقط في نفسك، ولكن ما تكلمت بشيء؛ فهي باقية في عصمتك.\n\nالسؤال: ... هل ممكن يأخذ البنت؟\n\nالجواب: هي وأمها يأتي يأخذهن كلهن.\n\nالسؤال: لا، لو ما يريد يأخذ الأم ..؟\n\nالجواب: هذا عند المحكمة يا ولدي.","link":"https://binbaz.org.sa/fatwas/2930/حكم-من-نوى-الطلاق-ولم-يتلفظ-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1378.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7041,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7043,"question":"حدث نزاع بيني وبين زوجتي، وأنا سوري، وهي سورية، وهي طالبة بكلية الصيدلة، وكانت تطلب مني الطلاق دائمًا وتقول: إني أنتظر عليك حتى أتخرج من الجامعة، وسأتركك، وأدى ذلك الأمر إلى أن بصقت في وجهي، وضربتني، وتجرأت علي، ولولا أنني أخشى الطلاق؛ لأنه يغضب الله، وتهتز له السماوات السبع؛ لطلقتها من زمن، فلقد ساءت عشرتها معي، وتحتقرني، ولقد فشل أبوها وأمها معي في ذلك، وأهلها، ويطلبون مني الصبر، فما العمل، وأنا أكرهها، وهي تكرهني؟","title":"مشروعية الطلاق عند الحاجة إليه","answer":"الجواب:\n\nلا حول ولا قوة إلا بالله، هذه يا أخي حالتها سيئة، والطلاق من قال لك: إنه يغضب الله؟! ومن قال لك: أنها تهتز لها السماوات! هذا كذب، الطلاق ما تهتز له السماوات، ولا يغضب الله إذا كان في محله، الطلاق من رحمة الله، ومن نعم الله، إذا ساءت العشرة؛ طلقها واسترح منها. \n\nفالطلاق مباح، الله -جل وعلا- قال: الطَّلَاقُ مَرَّتَانِ [البقرة:229]، قال: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] فالطلاق مباح، لكن تركه أولى، إذا كان ما في حاجة يكره إذا كان ما له حاجة، أما إذا كان فيه حاجة، واحدة تتفل في وجهك، وتصفعك .. نسأل الله السلامة.\n\nالمقصود: لا بأس إذا كنت ترى فيها الصبر، فيه خير، فلا تعجل في الطلاق، وجاهدها بالكلام الطيب، وأعطها المال، أرضها بالمال، فإن صلحت وقبلت منك؛ وإلا طلقها، ويعطيك الله أبرك منها، هذا إذا كانت طيبة، إذا كانت سيرتها طيبة، غير العمل هذا، إن كانت تصلي وطيبة في دينها، وعفيفة، وبعيدة عن الفتنة، ومتسترة ومتححبة؛ فحافظ عليها، وأرضها بالمال، وتكلم .. من جهة عملها السيئ، واستعن عليها بالله، ثم بأقاربها الطيبين، وأهلها الطيبين، حتى ينصحوها، وحتى يوجهوها، فإن استقامت؛ وإلا فأبعدها وطلقها، والطلاق ما فيه شيء عليك، الطلاق للمرأة السيئة يرضي الله، ما هو يغضب الله -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3066/مشروعية-الطلاق-عند-الحاجة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1453.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7066,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7068,"question":"حدث نزاع بيني وبين زوجتي، وأنا سوري، وهي سورية، وهي طالبة بكلية الصيدلة، وكانت تطلب مني الطلاق دائمًا وتقول: إني أنتظر عليك حتى أتخرج من الجامعة، وسأتركك، وأدى ذلك الأمر إلى أن بصقت في وجهي، وضربتني، وتجرأت علي، ولولا أنني أخشى الطلاق؛ لأنه يغضب الله، وتهتز له السماوات السبع؛ لطلقتها من زمن، فلقد ساءت عشرتها معي، وتحتقرني، ولقد فشل أبوها وأمها معي في ذلك، وأهلها، ويطلبون مني الصبر، فما العمل، وأنا أكرهها، وهي تكرهني؟","title":"مشروعية الطلاق عند الحاجة إليه","answer":"الجواب:\n\nلا حول ولا قوة إلا بالله، هذه يا أخي حالتها سيئة، والطلاق من قال لك: إنه يغضب الله؟! ومن قال لك: أنها تهتز لها السماوات! هذا كذب، الطلاق ما تهتز له السماوات، ولا يغضب الله إذا كان في محله، الطلاق من رحمة الله، ومن نعم الله، إذا ساءت العشرة؛ طلقها واسترح منها. \n\nفالطلاق مباح، الله -جل وعلا- قال: الطَّلَاقُ مَرَّتَانِ [البقرة:229]، قال: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] فالطلاق مباح، لكن تركه أولى، إذا كان ما في حاجة يكره إذا كان ما له حاجة، أما إذا كان فيه حاجة، واحدة تتفل في وجهك، وتصفعك .. نسأل الله السلامة.\n\nالمقصود: لا بأس إذا كنت ترى فيها الصبر، فيه خير، فلا تعجل في الطلاق، وجاهدها بالكلام الطيب، وأعطها المال، أرضها بالمال، فإن صلحت وقبلت منك؛ وإلا طلقها، ويعطيك الله أبرك منها، هذا إذا كانت طيبة، إذا كانت سيرتها طيبة، غير العمل هذا، إن كانت تصلي وطيبة في دينها، وعفيفة، وبعيدة عن الفتنة، ومتسترة ومتححبة؛ فحافظ عليها، وأرضها بالمال، وتكلم .. من جهة عملها السيئ، واستعن عليها بالله، ثم بأقاربها الطيبين، وأهلها الطيبين، حتى ينصحوها، وحتى يوجهوها، فإن استقامت؛ وإلا فأبعدها وطلقها، والطلاق ما فيه شيء عليك، الطلاق للمرأة السيئة يرضي الله، ما هو يغضب الله -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3066/مشروعية-الطلاق-عند-الحاجة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1453.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7071,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7073,"question":"حدث نزاع بيني وبين زوجتي، وأنا سوري، وهي سورية، وهي طالبة بكلية الصيدلة، وكانت تطلب مني الطلاق دائمًا وتقول: إني أنتظر عليك حتى أتخرج من الجامعة، وسأتركك، وأدى ذلك الأمر إلى أن بصقت في وجهي، وضربتني، وتجرأت علي، ولولا أنني أخشى الطلاق؛ لأنه يغضب الله، وتهتز له السماوات السبع؛ لطلقتها من زمن، فلقد ساءت عشرتها معي، وتحتقرني، ولقد فشل أبوها وأمها معي في ذلك، وأهلها، ويطلبون مني الصبر، فما العمل، وأنا أكرهها، وهي تكرهني؟","title":"مشروعية الطلاق عند الحاجة إليه","answer":"الجواب:\n\nلا حول ولا قوة إلا بالله، هذه يا أخي حالتها سيئة، والطلاق من قال لك: إنه يغضب الله؟! ومن قال لك: أنها تهتز لها السماوات! هذا كذب، الطلاق ما تهتز له السماوات، ولا يغضب الله إذا كان في محله، الطلاق من رحمة الله، ومن نعم الله، إذا ساءت العشرة؛ طلقها واسترح منها. \n\nفالطلاق مباح، الله -جل وعلا- قال: الطَّلَاقُ مَرَّتَانِ [البقرة:229]، قال: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] فالطلاق مباح، لكن تركه أولى، إذا كان ما في حاجة يكره إذا كان ما له حاجة، أما إذا كان فيه حاجة، واحدة تتفل في وجهك، وتصفعك .. نسأل الله السلامة.\n\nالمقصود: لا بأس إذا كنت ترى فيها الصبر، فيه خير، فلا تعجل في الطلاق، وجاهدها بالكلام الطيب، وأعطها المال، أرضها بالمال، فإن صلحت وقبلت منك؛ وإلا طلقها، ويعطيك الله أبرك منها، هذا إذا كانت طيبة، إذا كانت سيرتها طيبة، غير العمل هذا، إن كانت تصلي وطيبة في دينها، وعفيفة، وبعيدة عن الفتنة، ومتسترة ومتححبة؛ فحافظ عليها، وأرضها بالمال، وتكلم .. من جهة عملها السيئ، واستعن عليها بالله، ثم بأقاربها الطيبين، وأهلها الطيبين، حتى ينصحوها، وحتى يوجهوها، فإن استقامت؛ وإلا فأبعدها وطلقها، والطلاق ما فيه شيء عليك، الطلاق للمرأة السيئة يرضي الله، ما هو يغضب الله -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3066/مشروعية-الطلاق-عند-الحاجة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1453.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7111,"question":"ما حكم من أقسم بالطلاق على أن شيئًا ما قد يحدث، وهو يعلم أنه لم يحدث، علمًا بأنه لم يكن يقصد الطلاق، أو ينويه؟","title":"حكم الإقسام بالطلاق من دون قصد الطلاق","answer":"الجواب:\n\nإذا حلف بالطلاق على أن هذا حدث ليصدق، ما قصد إيقاع الطلاق، ولكن قصد ليصدق، فقد أخطأ وكذب، وعليه التوبة إلى الله، وعليه كفارة يمين؛ لأنه ما قصد إيقاعه، إنما قصد أن يصدق، أو قصد أن يفعل هذا الفعل.\n\nقال: عليه الطلاق من امرأته، عليه الطلاق أن تكلمي فلانًا أو فلانًا، عليه الطلاق أن تشتري هذا، عليه الطلاق أن تخرجي لكذا وكذا، قصده أمرها بهذا الشيء، وتكليفها به، وتخويفها، وليس قصده إيقاع الطلاق، هذا حكمه حكم اليمين، فيه كفارة يمين على الصحيح، فيه خلاف بين العلماء، لكن هذا هو المختار.\n\nالسؤال: يعني إذا كذب يكفر كفارة يمين إذا كان كاذبًا في هذا اليمين؟\n\nالجواب: قصده التصديق ليس قصده إيقاع الطلاق.","link":"https://binbaz.org.sa/fatwas/3140/حكم-الاقسام-بالطلاق-من-دون-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1498.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7137,"question":"رجل تزوج، وذهبت الزوجة بيت أبيه لقصد وضع الحمل، وبعد وضع الحمل (في السبوع) وقعت مشاجرة بين الزوجات بالتلفون، وطلق الزوج أربعة طلقات وأكثر، وهو في حالة انفعال، ثم بعد يومين قال: أرجعت زوجتي إلى عصمة نكاحي على ما تبقى لي من الطلاق، وأشعرت الزوجة في الرجوع علمًا أن الجميع موافقين للرجوع، وإنما الأب طلب إفتائي من الناحية الدينية، لذا أرجو إفادتي وشكرًا. ملاحظة: الزوج عنده حالة نفسية، وعند الانفعال، يتكلم ولم يشعر بشيء، وقد راجع الأطباء بذلك، ولا فائدة.","title":"حكم الطلاق في الحيض والنفاس","answer":"الجواب:\n\nالطلاق في النفاس، وفي الحيض الصحيح أنه لا يقع؛ لأنه طلاق محرم، فلا يقع، والنبي ﷺ لما طلق ابن عمر في الحيض أنكر عليه، وأمره أن يمسكها حتى تحيض، ثم تطهر، ثم تحيض، ثم تطهر، ثم إذا شاء طلقها قبل أن يمسها، وقال له -عليه الصلاة والسلام-: تلك العدة التي أمر الله أن تطلق لها النساء لقوله : يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1]\n\nالمعنى طلقوهن طاهرات من غير جماع، أو حبالى، فالطلاق المشروع إنما يكون في حال كونها حاملاً، طلاق الحامل طلاق مشروع، أو يطلقها في حال كونها طاهرًا طهرًا لم يجامعها فيه، هذا هو معنى قوله فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] يعني طاهرات من غير جماع، أو في حال الحمل، هذا هو الطلاق الشرعي، أما كونه يطلقها في حال الحيض، أو في حال النفاس فهذا طلاق منكر، فلا يجوز، أما ما يتعلق.. \n\nالسؤال: يعني لا يقع؟ \n\nالجواب: لا يقع، فهي باقية على حالها زوجة له، وعليه أن يتوب إلى الله من عمله، أما ما يتعلق بشدة غضبه، وتغير حاله، هذا له بحث آخر، لكن هذا يكفي ما دام طلقها في هذه الحال؛ فهو طلاق لاغٍ.","link":"https://binbaz.org.sa/fatwas/3166/حكم-الطلاق-في-الحيض-والنفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1524.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":7150,"question":"ذهبت زوجتي بدون إذني لزيارة أختها، فغضبت، وقلت لها: إذا ذهبت بدون إذني؛ فأنت طالق، ثم طالق، ثم طالق، وبعد فترة ذهبت مع أهلها، وأنا غير موجود، فهل يقع الطلاق؟ والآن أريد أن أتحلل، هل علي كفارة، أم ماذا أفعل؟","title":"حكم الطلاق بالثلاث في وقت واحد","answer":"الجواب:\n\nهذا يختلف إذا كنت قلت هذا لمنعها، ما قصدت الطلاق، إنما قصدت منعها، وتخويفها، فهذا يمين، عليك كفارة يمين إذا ذهبت بغير إذنك.\n\nأما إن كنت أردت الطلاق؛ فإنه يقع الطلاق ثلاث طلقات، طالق، ثم طالق، ثم طالق، إذا كنت أردت إيقاع الطلاق، إذا فعلت؛ فقد حرمت عليك حتى تنكح زوجًا غيرك.","link":"https://binbaz.org.sa/fatwas/3183/حكم-الطلاق-بالثلاث-في-وقت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1541.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7242,"question":"أقسمت على زوجتي ألا تحضر فرح بنت خالتي، أو بنت خالتها، وقلت لها: لو حضرت لا تجلسين معي في البيت مرة أخرى، ولكن عندما سافرت من اليمن إلى السعودية علمت أنها حضرت هذا الفرح؛ علمًا بأنه في بلد آخر، فما موقفي جزاكم الله خيرًا؟","title":"حكم من أقسم على زوجته أن لا تحضر عرساً فحضرته","answer":"الجواب:\n\nإذا كنت أردت الطلاق، وأنها تطلق بذلك؛ يقع طلقة، وإن كنت ما أردت الطلاق وإنما أردت تخويفها، وتحذريها؛ فليس عليك شيء، وإنما عليك كفارة يمين.","link":"https://binbaz.org.sa/fatwas/3299/حكم-من-اقسم-على-زوجته-ان-لا-تحضر-عرسا-فحضرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1624.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7277,"question":"ما حكم الكذب إذا كان كذبًا بسيطًا مثل: أن أكذب على أحد، دون أن أفقد صداقته؟","title":"خطورة التهاون في الكذب","answer":"الجواب:\n\nتقول أم كلثوم بنت عقبة ابن أبي معيط -رضي الله عنها-: لم أسمع النبي ﷺ يرخص في شيء من الكذب إلا في ثلاث: في الإصلاح بين الناس، وفي الحرب، وفي حديث الرجل امرأته، والمرأة زوجها، هذا المستثنى.\n\nفالإصلاح بين الناس، وفي الحرب، والحرب خدعة، وفيما بين الرجل وزوجته، يحدثها وتحدثه بأشياء غير حقيقة لما في هذا من إصلاح الحال بينهما، وتثبيت العشرة بينهما فيما لا يضر أحدًا من الناس، هذه الأشياء التي رخص فيها النبي ﷺ من الكذب.\n\nوأما غير هذه الثلاث فينبغي التحرز من الكذب، والحذر منه، وأن يعتني الإنسان بالصدق في أقواله، وفي أعماله، وأن يكون من ديدنه الصدق، ومن عادته الصدق في أموره، اللهم إلا أن يكون الصدق يجر عليه شرًا، ويسبب فتنًا، فهذا له بحثه، وله شأنه في محله، فإذا كان ظالم يسأل عن إنسان ليقتله، أو ليظلمه؛ فليس له الصدق في هذا، أن يقول: هو في المحل الفلاني، يقول: ما أدري؛ حتى لا يضر أحدًا، وإن كان يدري، إذا كان يعرف أن هذا السائل يضر هذا المسؤول عنه لو علم بمكانه ظلمًا وعدوانًا، فهذا من الكذب الواجب، وكذلك الذي يصلح بين الناس، فيقول خيرًا، أو ينمي خيرًا.\n\nالمقصود: أن الكذب في هذه الثلاثة لا بأس، وهكذا الكذب فيما دل الشرع على جوازه فيه لحماية المسلمين من الشر، ولحمايتهم من عدوهم، أو لحماية المسلم من ظلم من يظلمه، ويتعدى عليه، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/3352/خطورة-التهاون-في-الكذب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1673.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7279,"question":"منذ ثلاثة أيام تقريبًا مضتْ دار بيني وبين زوجتي خلاف لدرجة في هذا اليوم صرت عصبيًّا جدًا لدرجة لا أتخيله، فمسكت الحذاء -أعزكم الله- فضربت زوجتي به، يعني فقدت وعيي بالمرة رغم أنها حامل في الشهر السادس، ومعي ابنة عمرها سنتين في هذه الظروف الصعبة، وقالت لي زوجتي: طلقني -وكنت غضبان- فقلت لها: أنت طالق طالق طالق، قلتها أكثر من مرة، ولا أدري ما العدد بالضبط، ولكنني متأكد تمامًا أنها أكثر من مرة، والآن أنا في حيرة، زوجتي تبكي بالبيت، ولا تريد الفراق بعيدًا عني، كذلك أنا، فأفيدوني ماذا أعمل؛ لأني لا أنام الليل؟","title":"حكم الطلاق بأكثر من مرة في حالة الغضب","answer":"الجواب: \n\nهذا من الشيطان -نسأل الله أن يعيذنا وإياكم من الشيطان- كان الواجب عليك التثبت، وعدم العجلة في الأمور، والاستعاذة بالله من الشيطان، هذا يحتاج إلى أن تأتينا في البيت، إن شاء الله غدًا ننظر في الأمر، أو يوم السبت، كذلك لا بأس، ننظر في الموضوع معك، أو مع المرأة ووليها، لا بد من النظر في الموضوع، إن شاء الله ولا يحصل إلا الخير.","link":"https://binbaz.org.sa/fatwas/3342/حكم-الطلاق-باكثر-من-مرة-في-حالة-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1663.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":7280,"question":"هل يعد التقليد بالحركات، أو بالصوت، أو بالكلام من الغيبة؟ وإذا كان من الغيبة فإن المغتاب إذا قيل له: لا تغتاب قال: هذا ما يفعله أو يقوله فلان؟","title":"حكم الغيبة بالحركات أو بالصوت","answer":"الجواب:\n\nنعم الغيبة تكون بالكلام، وتكون بالفعال، بالكلام إذا قال فلان كذا ما يكره، وتكون الغيبة بالفعل إذا أشار إليه، وعرف الناس أنه يريده، إذا كان يمشي مشيته، أو يتكلم بكلام على سبيل العيب له، والاستهزاء به، أو ما أشبه ذلك من الإشارات التي يراد منها تحقيره، ويراد منها ذمه، فهذا غيبه بالفعل، -نسأل الله العافية- وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1].","link":"https://binbaz.org.sa/fatwas/3353/حكم-الغيبة-بالحركات-او-بالصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1674.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7281,"question":"هل يعد التقليد بالحركات، أو بالصوت، أو بالكلام من الغيبة؟ وإذا كان من الغيبة فإن المغتاب إذا قيل له: لا تغتاب قال: هذا ما يفعله أو يقوله فلان؟","title":"حكم الغيبة بالحركات أو بالصوت","answer":"الجواب:\n\nنعم الغيبة تكون بالكلام، وتكون بالفعال، بالكلام إذا قال فلان كذا ما يكره، وتكون الغيبة بالفعل إذا أشار إليه، وعرف الناس أنه يريده، إذا كان يمشي مشيته، أو يتكلم بكلام على سبيل العيب له، والاستهزاء به، أو ما أشبه ذلك من الإشارات التي يراد منها تحقيره، ويراد منها ذمه، فهذا غيبه بالفعل، -نسأل الله العافية- وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1].","link":"https://binbaz.org.sa/fatwas/3353/حكم-الغيبة-بالحركات-او-بالصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1674.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7288,"question":"إذا كان الشخص في جماعة -يعني مع ناس- وعلق على شخص منهم، علق يعني معناه: تكلم بشيء ليس بصحيح، يريد إضحاك الجماعة، والشخص عن ذلك لم يرض، فما حكم ذلك؟","title":"حكم الكذب على شخص لإضحاك الناس","answer":"الجواب:\n\nليس له أن يعلق شيئًا يؤذي بعض الحاضرين، أو يكون كذبًا، أو يكون مغضبًا لله  ولو أراد الإضحاك.\n\nيقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك القوم، ويل له، ثم ويل له ما يجوز للإنسان أن يتكلم بالباطل ليضحك الناس، عليه أن يصون لسانه، وألا يعلق شيئًا يضحك الناس، وهو لا يجوز في نفسه إما كذب، وإما سب لأحد، وإما استهزاء بأحد، كل هذا منكر.","link":"https://binbaz.org.sa/fatwas/3345/حكم-الكذب-على-شخص-لاضحاك-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1666.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7426,"question":"أنا رجل متزوج، ولدي ولد، وزوجتي حامل في شهرها الأول، ولقد خرجت زوجتي مع أخي إلى المستشفى، وذلك دون إذن مني، أو من والدي، فأثار ذلك غضبي، وليس بالغضب الذي يفقدني عقلي، ولكني أعي ما أقول، وأستطيع ان أمنع نفسي من أي كلمة لا أريد النطق بها، فحلفت على زوجتي بالطلاق بقصد التهديد، لا بقصد الفراق؛ لأنني سبق أن حلفت عليها بالله، وفجرتني وكفرت عن حلفي، فحلفت بالطلاق؛ لعلها تنتهي عن مخالفتي، وهذا نص الحلف:علي الطلاق بالثلاث المحرمات، أو الحارمات أنك لو تخرجين من المنزل من غير إذني أن أذهب بك إلى أهلك، وبعد تداول الكلام بيننا بعد ذلك قال: إذا خرجت من فتحة الباب شبرًا واحدًا بدون إذن مني؛ فأنت طالق، وبعد ذلك بيومين خرجت مع والدي إلى المستشفى بدون إذن مني مع العلم أني موجود، ولكنها تقول: إنها لم تسمع الطلاق، والآن أود استرجاعها من أجل ابني ومن أجل الجنين الذي في بطنها، أفيدونا أفادكم الله، وأنني أقصد التهديد في كلا الحالتين، وإذا كانت حاملًا في الشهر الأول فمتى تنتهي عدتها؟ أي متى آخر موعد لاسترجاعها، وهل تلزم علي نفقتها وهي الآن في منزل والدها؟","title":"حكم من حلف على زوجته بالطلاق بقصد التهديد لا الفراق","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل؛ فإن هذا الكلام يكون حكمه حكم اليمين؛ لأن المقصود تهديدها، وتخويفها، وليس المقصود إيقاع الطلاق، فمثل ما فعلت في المرة الأولى عليك كفارة يمين، وهي: إطعام عشرة مساكين، أو كسوتهم بسبب خروجها لو كانت متعمدة، ولو كانت عالمة، أما ما دامت لم تسمع الكلام؛ فليس عليك شيء؛ لأنها جاهلة أو ناسية، لو كانت فعلت ناسية كذلك؛ لأن الله يقول: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] وصح عن رسول الله ﷺ أنه قال: قال الله: قد فعلت فإذا خرجت جاهلة، ما درت عن يمينه، ما سمعت أو ناسية؛ فليس عليه كفارة، أما لو تعمدت وهي ذاكرة لو تعمدت فعليك كفارة يمين، ما دام القصد التهديد، والمنع، وليس القصد فراقها، لعلك فهمت.","link":"https://binbaz.org.sa/fatwas/3517/حكم-من-حلف-على-زوجته-بالطلاق-بقصد-التهديد-لا-الفراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1821.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7429,"question":"ما الحكم على من تستر على الذين يتركون الصلاة، ويقضون وقتهم مع لعب الورق؟","title":"حكم التستر على تارك الصلاة","answer":"الجواب: الواجب على المؤمنين التعاون، مثلما سمعت في الكلام، التعاون على الخير، وأن ينصحوا من تخلف عن الصلاة، وأن لا يتركوهم في باطلهم، ومع الشياطين، بل ينصحونهم ويوجهونهم إلى الخير، فإن استقاموا وإلا رفع الأمر إلى المسؤول عنهم حتى يقيم في حقهم ما يلزم، وحتى يبلغ عنهم ما يلزم، المقصود أن ترك الناس على باطلهم أمر منكر، والله -جل وعلا- يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ويقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:110].  ويقول النبي ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان فإذا علم أن أهل المكتب الفلاني، أو البيت الفلاني يضيعون الصلوات، ولا يبالون بهم؛ نصحهم الإخوان، واتصل بهم الإخوان، ووجهوهم إلى الخير وحذروهم من مغبة عملهم، فإن استقاموا؛ وإلا رفع بأمرهم إن كانوا في دائرة يرفع إلى رئيس الدائرة، أو إلى الهيئة، أو إلى أمير القرية، أو ما أشبه ذلك ممن يرجو أنه ينفع في هذا المقام، من باب التعاون على البر والتقوى، بعدما ينصح لهم، ويجتهد، وإذا تيسر أن يكون الناصح معه غيره لا يكون فردًا؛ يذهب معه بعض إخوانه؛ لأن كلمة الجماعة أشد أثرًا، إذا كان الناصحون اثنين، أو ثلاثة، أو نحو ذلك كان هذا أشد أثرًا في نفس المنصوح، وأقرب إلى النتيجة الصالحة.","link":"https://binbaz.org.sa/fatwas/3514/حكم-التستر-على-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1818.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7460,"question":"هذه رسالة لم يوقع فيها، وإنما أغفل مرسلها اسمه والتاريخ أيضاً، يقول: لديه قضية هي: هل المرأة الحامل يجوز عليها الطلاق، أي: تطلق وهي حامل؟ أفيدونا جزاكم الله خيراً، وأرجو من المقدمين في البرنامج عدم إهمال رسالتي.هذه رسالتك -أيها المستمع- قد عرضت ولم تهمل، لكن نرجو أن تضع اسمك في الرسائل القادمة، وأن تضع تاريخ الرسالة أيضاً.","title":"هل يقع طلاق المرأة وهي حامل؟","answer":"الجواب:  هذه المسألة تقع لبعض العامة، بعض العوام يظن أن الحامل لا يقع عليها طلاق، ولا أدري من أين جاءهم هذا الظن، وهو لا أصل له في كلام العلماء، ليس له أصل، بل الذي عليه أهل العلم قاطبة أن الحامل يقع عليها الطلاق، هذا محل إجماع من أهل العلم، ليس فيه خلاف، الحامل طلاقها إما سني وإما لا سنة ولا بدعة.\nفالحاصل: أنه يقع عليها الطلاق، وقد ثبت عنه ﷺ أنه قال لـابن عمر لما طلق امرأته في حيضها، أمره أن يمسكها حتى تحيض ثم تطهر، قال: ثم ليطلقها طاهراً أو حاملاً، فالنبي ﷺ جعل تطليق الحامل من جنس تطليق الطاهر التي لم تمس.\nفالحاصل: أن طلاق الحامل أمر لا بأس به، بل هو سنة على الراجح، يعني طلاقها سني لا بدعي الحامل، وإنما الذي ينهى عن تطليقها حال وجودها بالصفة التي ننبه عليها الحائض والنفساء، فما دامت حال الحيض أو النفاس لا يجوز للمسلم أن يطلقها، يعني لا يجوز لزوجها أن يطلقها، بل يمسك حتى تطهر، ثم إذا شاء طلق وإن شاء أمسك، أما كونه يطلقها وهي حائض أو نفساء فلا؛ لأن الرسول ﷺ غضب على ابن عمر لما طلق امرأته وهي حائض.\nوكذلك إذا طلقها في طهر قد مسها فيه؛ لأن الرسول عليه الصلاة والسلام قال: ثم ليطلقها قبل أن يمسها فتلك العدة التي أمر الله أن تطلق لها النساء في قوله سبحانه: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] قال العلماء: معناه: طاهرات من غير جماع. هذا معنى التطليق للعدة: أن يطلقها وهي طاهر لم يمسها، أو حبلى قد ظهر حملها، هذا محل السنة: تطليق المرأة في حالين:\nإحداهما: أن تكون حبلى -يعني: حامل- فطلاقها سني لا بدعي.\nالحال الثاني: أن تكون طاهراً لم يمسها الزوج، قد طهرت من حيضها أو نفاسها قبل أن يمسها، فإن هذا الطلاق سني في هذه الحالة.\nأما البدعي فله ثلاث حالات:\nتطليق الحائض.. هذه واحدة.\nتطليق النفساء.. ثنتين.\nتطليق المرأة في حال طهرها بعد المسيس بعدما جامعها.\nهذا بدعي لا ينبغي أن يقع، ينبغي للزوج أن يمسك عن الطلاق في هذه الحال حتى تحيض ثم تطهر قبل أن يمس، ويطلق.\nوالحكمة في ذلك -والله أعلم: أن الشارع يريد عدم الطلاق، ويرغب في بقاء النكاح لما فيه من الخير والمصالح، فلهذا ضيق الطريق إليه، فجعل المرأة في حال حيضها أو نفاسها أو طهر مسها فيها ليس بمحل الطلاق، حتى يمسك، فلعل الحال تحسن بعد ذلك، ولعل الوئام يحصل بعد ذلك فلا يقع الطلاق، ولا يطلقها إلا في إحدى حالين:\nإحداهما: أن تكون حبلى.\nوالثانية: أن تكون في طهر لم يمسها فيه.\nوهي في هذه الحال -في الغالب- لا يطلقها؛ لأنه يرغب فيها، إذا طهرت رغب في جماعها، وإذا جامعها منع من طلاقها حتى تبقى معه، وكذلك الحبلى ليس فيها موانع من الجماع، وهي صالحة للجماع في كل وقت، فلهذا لا يرغب في طلاقها في الغالب، ولأنه يرجو نتاج هذا الحمل، يرجو أن يشاهده وأن يربيه، فحينئذ يحصل الامتناع من الطلاق، هذا من رحمة الله لعباده ، أن جعل الطلاق في هاتين الحالين: حالة الطهر من دون مسيس، وفي حالة الحبل -حالة الحمل- حتى لا يطلقها؛ لأنه إذا كان الطلاق في هاتين الحالين فالغالب أنه لا يقع الطلاق في هاتين الحالين؛ لأن بعد الطهر يشتاق إلى جماعها بعد ما منع منها أيام في حال حيضها أو نفاسها يشتاق إلى أن يجامعها، فإذا جامعها منع من طلاقها حتى تحيض مرةً أخرى وتطهر.\nفي الحقيقة: أن المرأة إذا راعى الزوج -هذا الأمر المشروع- فإنه بذلك يقل الطلاق ويكثر الإمساك، والشارع يرغب في بقاء النكاح؛ لما يترتب عليه من المصالح الكثيرة، ولهذا كان الطلاق أبغض الحلال إلى الله أبغض الحلال إلى الله الطلاق؛ لأنه يفرق بين الرجل وأهله، ويسبب شيئاً كثيراً من الأذى على الأولاد، والزوج أيضاً قد يتأخر ما يتزوج، والمرأة قد تتأخر ما تزوجت بعد ذلك، فالحاصل: أن الطلاق فيه مساوئ، فلهذا شرع الله سبحانه وتعالى أسباب بقاء النكاح ليبقى الرجل محافظاً على زوجته ومستفيداً منها، وتبقى المرأة كذلك في عصمة زوجها في هذه الأحوال التي بينا أنه لا يطلق فيها: حالة الحيض، وحالة النفاس، حالة الطهر التي قد جامعها فيه، هذه الأحوال الثلاث لا يطلق فيها ولا يجوز له الطلاق فيها.\nوبهذا يقل الطلاق ويكثر الإمساك، وهذا من رحمة الله وإحسانه إلى عباده جل وعلا. نعم. \nالمقدم: إذاً أصبحت المسألة على عكس ما يتصوره هذا السائل وأمثاله؟\nالشيخ: نعم، عكس نعم.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4178/هل-يقع-طلاق-المراة-وهي-حامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_001/00102.mp3","categories":["الطلاق"]},{"id":7539,"question":"هذه الرسالة من إحدى الأخوات المرسلة تقول: أختكم في الله من المملكة العربية السعودية، تقول: إنني امرأة قريبة من الله، ومتمسكة بالله عز وجل، وتقول: يوجد بالقرب منا جار يمر إلى صلاة العشاء وهو متوضئ ويذهب إلى المسجد، وزوجي يبقى بدقائق قليلة، وإن زوجي قد وسوس له الشيطان ويشك بي وبجاري، وأنني بريئة، وأنني راجية جزاها من الله، لكن سمعت كلام بعض الناس أو الأخوات: أن المرأة تحرم على زوجها إذا شك فيها، أفيدونا جزاكم الله خير الجزاء، هل هذا صحيح؟ وهل المرأة تحرم على زوجها؟","title":"ما صحة أن المرأة تحرم على زوجها بمجرد اتهامها؟","answer":"الجواب: إذا شك الرجل في زوجته واتهمها بأنها تأتي الفاحشة، أو أن لها صاحباً، هذا الشك لا يحرمها عليه، بل هذا من الشيطان، والواجب عليه الحذر من وساوس الشيطان، ومن التهمة بغير حق، ليس له أن يتهم زوجته، ولا غيرها بغير الحق، وهذه التهمة وهذا الشك لا يحرمها عليه، بل ذلك يوجب الإثم إذا كان شكه فيها ليس عن أساس صحيح، وإنما هو مجرد تهمة، فليس له ذلك، أما إن وجد أمارات وعلامات فإنه ينصحها ويوجهها ويحذرها، ولا تحرم عليه أبداً. نعم.","link":"https://binbaz.org.sa/fatwas/4525/ما-صحة-ان-المراة-تحرم-على-زوجها-بمجرد-اتهامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01109.mp3","categories":["الطلاق"]},{"id":7555,"question":"هذه رسالة وردتنا من المستمع المعذب الحائر -على حسب كلامه- سالم الخليص بن مطر من قرية تليل المعز حلب من سوريا، هذه يعرض فيها مشكلة سوء التفاهم مع زوجته، ونتج عن ذلك طلاق، يقول في معرض رسالته: أنا شاب متزوج منذ سبع سنوات بقريبة لي، وقبل تاريخ هذه الرسالة بسنة حدث بيني وبين زوجتي شجار عنيف جداً دام أكثر من ثلاثة شهور يقول: بعدها أنها أصبحت تطلق عليه الشتائم الكثيرة، والكلام السيء، وأنا أعاملها معاملة حسنة؛ لأنني شاب مؤمن أعمل بما يرضي الله ورسوله، وزاد الأمر حدة وهي كل يوم على مدار ثلاثة أشهر تزيد النار حطباً والطين بلة، فأجبرتني على أن أطلق عليها كلام: طلقتك، طلقتك، طلقتك، طلقتك، أي: أكثر من مرات عديدة، وعندما أطلقت هذا الكلام كنت في حالة غضب شديد، وغياب عقل، أطلقت هذا الكلام بغية أن تكف عن أقاويلها البذيئة المرعبة للبدن، وهي تزيد في ذلك وأنا أكرر عليها ألفاظ: مطلقة، مطلقة، مطلقة، وأخيراً لم يجد الأمر نفعاً، فأرسلت إلى والدها وأخذها إلى بيته وظلت عنده أكثر من سنة وأنا لا أوافق أهلي على إرجاعها بسبب أخلاقها الشرسة وأقاويلها المرعبة الكاذبة، وأخيراً أرادوا تزويجها من شخص فلم تقبل بالزواج من أي إنسان، وقالت لأهلها: إذا أردتم تزويجي سأشرب سماً وأموت، أو أحرق نفسي بالنار وأخلص من الحياة، أثناء هذا الهجر الطويل كانت تريد أن ترجع لي، ولكنني كنت لا أقبل بها زوجة أبداً، بسبب معاملتها القاسية .. إلى آخره، فأقنعوني أهلها بتزويجها إليّ خشية أن تقتل نفسها، فأجبرت على قبولها وصار لها عندي خمسة أيام وأنا لا أقرب منها خشية الإثم والحرام، ووجدت أن أخلاقها صارت بعد هذا الهجر حسنة، يقول: إنها تعطيني حقوقي كاملة، وتحترمني، وتكفر عما بدر منها من أقاويل، فما هو الحل بالله عليكم أخبروني سريعاً، و هل وقع الطلاق ولم تعد تحل لي؟ ألا يوجد فتوى لهذه المشكلة، أفيدوني وفقكم الله؟","title":"حكم الطلاق حال الغضب","answer":"الجواب: إذا كان الطلاق المذكور وقع منك في حال شدة الغضب وغيبة الشعور، وأنك لم تملك نفسك ولم تضبط أعصابك بسبب كلامها السيء وسبها لك، وشتائمها ونحو ذلك، وأنك أطلقت هذا الطلاق في حال شدة الغضب وغيبة الشعور، وهي معترفة بذلك، أو لديك من يعرف ذلك من الشهود العدول، فإنها لا يقع الطلاق؛ لأن الأدلة الشرعية قد دلت أن شدة الغضب وإذا كان معه تغير الشعور كان أعظم لا يقع به الطلاق، ومن ذلك ما روى أحمد وأبو داود وابن ماجة، وصححه الحاكم عن عائشة رضي الله عنها أن النبي عليه الصلاة والسلام قال: لا طلاق ولا عتاق في إغلاق، قال جماعة من أهل العلم: الإغلاق: الإكراه والغضب، يعنون الغضب الشديد، فالغضبان قد أغلق عليه أمره، وقد أغلق عليه قصده، فهو شبيه بالمعتوه والمجنون والسكران، بسبب شدة الغضب، فلا يقع طلاقه، وإذا كان مع ذلك تغير الشعور، وأنه لم يحفظ ما صدر منه بسبب شدة الغضب فإنه لا يقع الطلاق، والغضبان له ثلاث حالات:\nحالة يتغير معها الشعور: فهذا يلحق بالمجانين، ولا يقع طلاقه عند الجميع، عند جميع أهل العلم.\nالحال الثاني: أن يكون قد اشتد به الغضب ولكن لم يفقد شعوره بل عنده شيء من الإحساس وشيء من العقل، ولكن اشتد به الغضب حتى ألجأه إلى الطلاق، هذا لا يقع طلاقه على الصحيح أيضاً.\nوالحال الثالث: أن يكون غضبه عادياً ليس بالشديد جداً، بل عادياً كسائر الغضب الذي يقع بين الناس، ليس بالشديد، ليس بالملجئ، فهذا يقع معه الطلاق عند الجميع.\nوالسائل حاله إما من الوسط، أو من الشديد الذي قد تغير معه الشعور حسب ما ذكر في سؤاله، فيكون طلاقه غير واقع وزوجته معه، ولا حول ولا قوة إلا بالله، نسأل الله للجميع الهداية والصلاح وحسن العاقبة.","link":"https://binbaz.org.sa/fatwas/4542/حكم-الطلاق-حال-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_013/01306.mp3","categories":["الطلاق"]},{"id":7613,"question":"هذا يقول: أنه حاول أن يتخلص من شرب الدخان، فحلف أخيراً بالطلاق قبل أن يدخل على زوجته؟ الشيخ: أعد الكلام من الأول. المقدم: يقول: أنا كنت مبتلى بشرب الدخان، وقد حاولت بشتى الوسائل على تركه، حتى أنني حدثت نفسي أنني سوف أطلق أو أحلف بالطلاق على أن لا أشربه، فقلت: يا رب! إني إن شربت الدخان فامرأتي طالق بالثلاث، وكان ذلك بعد أن عقدت النكاح وقبل الدخول عليها، والقصد من قدومي على هذا اليمين هو منع نفسي من هذه المصيبة التي هي شرب الدخان، ولكن بعد نصف ساعة لم أستطع فشربته، وكان هذا كله بيني وبين الله، لم يعلمه أحد، وبعد مدة جهزت على زوجتي وأعرست، وأنجبت منها أطفال، ثم حاولت ترك الدخان وقلت في نفسي أيضاً: إنني سوف أحلف بالطلاق عسى أن أوفق في تركه هذه المرة وقلت: يا رب! إن شربت الدخان فامرأتي طالق ثم طالق بالثلاث، وكان ذلك في مكان واحد وفي لفظ واحد ولم يفصله سوى كلمة، ثم إنني أنا كنت لا أعرف لها أي معنى في اللغة العربية، وكان ذلك الوقت وأنا في غربة وليس عندي سوى الله، ولم أبلغ الزوجة ولا غيرها، وكان هدفي ورغبتي هو منع النفس الأمارة بالسوء من شرب الدخان، ولكن في اليوم الثاني استرجعت وشربت الدخان مرة ثانية، ثم بعد مشيئة الله أقلعت عن شرب الدخان ولي خمسة عشر عام بعد أن تركته، والزوجة باقية عندي، أرجو فتواي من الله ثم من سماحة الشيخ عبد العزيز بن باز حيث هدفي من هذا كله هو منع نفسي من هذه المصيبة التي هي شرب الدخان، وماذا يجب علي من كفارة، أدام الله سماحتكم لخدمة الإسلام والمسلمين، ووفقكم الله؟","title":"حكم من حلف بالطلاق على أن يترك الدخان وعاد إليه","answer":"الجواب: لا ريب أن شرب الدخان محرم ومنكر ومضاره كثيرة، كما حقق ذلك جمع من أهل العلم، وكل من تأمل حال المدخنين وما ذكره أهل العلم وأهل الطب وأهل التجارب في الدخان عرف يقيناً مضرة الدخان وأنه من المحرمات ومن المنكرات التي يجب على كل من يتعاطاه أن يتركه وأن يحذره، وقد بين الله سبحانه وتعالى في كتابه الكريم أنه محرم وأنه منكر، لا بالنص عليه، ولكن ببيان ما أحل الله لعباده وما حرم عليهم، فإنه سبحانه قال: و يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4].\nفهو سبحانه بين أنه ما أحل إلا الطيبات و يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] فالله جل وعلا أحل الطيبات لعباده وليس هو من الطيبات بل هو من الخبائث، ومن الموبقات، إذ الطيب ما نفعك وغذاك من دون مضرة. \nأما هذا فهو ضار مؤذٍ في طعمه وآثاره السيئة ورائحته الخبيثة، فمضاره لا تحصى، وقال جل وعلا في وصف نبيه محمد ﷺ: يُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157]. \nولا شك أنه خبيث لمضاره الكثيرة كما بين ذلك أهل العلم، وكما بين ذلك الأطباء، وبين ذلك كل من جرب هذا الخبيث. \nفالواجب على كل مسلم أن يحذر هذا البلاء وأن يكون عنده عزم صادق وقوة على تركه والحذر منه؛ لعل الله يسلمه من شره. \nأما السائل فإن عليه كفارة يمين عن طلاقه في المرة الأولى والثانية؛ لأن هذا في حكم اليمين، ما دام قصده منع نفسه من شربه وليس قصده فراق أهله فإنه في حكم اليمين في أصح قولي العلماء، كما أفتى بذلك شيخ الإسلام ابن تيمية رحمة الله عليه وتلميذه العلامة ابن القيم رحمة الله عليه في مثل هذا، فعلى السائل أن يكفر كفارة يمين عن الطلقة الأولى وعن الطلاق الأخير، وكفارة اليمين إطعام عشرة مساكين أو كسوتهم، لكل مسكين نص صاع من التمر أو الحنطة أو الأرز، يعني: من قوت بلد حال المطلق، أو يكسوهم كسوة تجزيهم في الصلاة كقميص لكل واحد أو إزار ورداء لكل واحد، هذه هي الكفارة. \nفعلى هذا يكون عليه عشرة أصواع، خمسة لليمين الأولى للطلاق الأول وخمسة للطلاق الأخير، عشرة أصواع لعشرة مساكين، كل مسكين يعطى صاعاً من الأرز أو من التمر أو غيرهما من قوت البلد، نصفه عن الطلاق الأول ونصفه عن الطلاق الأخير، ونسأل الله أن يثبتنا جميعاً على الحق، وأن يعيذنا والمسلمين جميعاً من نزغات الشيطان.","link":"https://binbaz.org.sa/fatwas/4666/حكم-من-حلف-بالطلاق-على-ان-يترك-الدخان-وعاد-اليه ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_023/02302.mp3","categories":["الطلاق"]},{"id":7663,"question":"سماحة الشيخ هذه الرسالة وردتنا من مقدمها صالح علي غالب من السعودية في الخضر، يسأل عن الحلف بالطلاق يقول: إنني في يوم من الأيام حلفت يمين وقلت: علي الطلاق من امرأتي أني لن أعمل بالشركة التي أعمل بها، ولكني بعد ذلك عملت، فهل يحسب هذا اليمين بطلقة، أم يعتبر اليمين لغو، أرجو الإفادة وفقكم الله؟","title":"حكم من قال: علي الطلاق أني لن أعمل بشركة ما، ثم عمل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nالحلف بالطلاق هو التعليق الذي يراد به حث الحالف على شيء أو منعه من شيء، أو حث المستمعين المخاطبين على تصديقه أو تكذيبه، هذا هو اليمين بالطلاق، تعليق مقصوده حث أو منع أو تصديق أو تكذيب، هذا يسمى يميناً بالطلاق، بخلاف التعليق المحض هذا لا يسمى يمين كما لو قال: إذا طلعت الشمس فزوجته طالق، أو قال: إذا دخل رمضان فزوجته طالق، هذا ما يسمى يمين هذا التعليق المحض الشرط المحض، متى وجد الشرط وقع الطلاق، فإذا قال مثلاً: إذا دخل رمضان فامرأته طالق طلقت بدخول رمضان، وإذا قال مثلاً: إذا طلعت الشمس فزوجته طالق طلقت بطلوع الشمس؛ لأن هذا يسمى تعليقاً محضاً وشرطاً محضاً.\nأما إذا قال: عليه الطلاق ما يعمل في الشركة الفلانية، أو عليه الطلاق ما يكلم فلاناً، أو عليه الطلاق أن تأكل ذبيحتي أو ما أشبه ذلك فهذا يسمى يمين، لأن فيه حث ومنع هذا يسمى يمين، والأكثرون من أهل العلم على أنه يقع الطلاق إذا اختل الشرط إذا قال: عليه الطلاق أنه ما يكلم فلان فكلمه عند الأكثر يقع الطلاق، وهكذا إذا قال: عليه الطلاق ما يعمل في الشركة الفلانية ثم عمل فيقع الطلاق عند الجمهور، وقد ذهب بعض أهل العلم إلى إنه لا يقع وأن يكون حكمه حكم اليمين إذا كان مقصوده حثاً أو منعاً أو تصديقاً أو تكذيباً ليس قصده طلاق امرأته، وهذا هو الغالب على الناس في مثل هذا، يقصد حث نفسه على شيء أو منعها من شيء أو التصديق أو التكذيب، فإذا قال: عليه الطلاق أنه ما يعمل في الشركة الفلانية ومقصوده منع نفسه من العمل ليس قصده فراق أهله وإنما مقصوده أن يمنع نفسه من العمل في الشركة هذا الصحيح أنه لا يقع الطلاق، ويكون عليه كفارة يمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، ومقداره كيلو ونصف تقريباً هذه الكفارة، أو يكسوهم على قميص قميص أو على إزار ورداء أو يعتق رقبة هذه كفارة اليمين؛ لأن الله سبحانه قال: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، بعض الناس قد يظن أن الصيام يكفي ولو كان موسراً هذا غلط، الصيام إنما يكون في حق المعسر الذي ما يستطيع لا كسوة ولا إطعام ولا عتق هذا العاجز، إذا عجز عن الثلاث يصوم ثلاثة أيام متتابعة كما قال ابن مسعود رضي الله عنه، هذه الكفارة المعروفة التي جاء بها كتاب الله عز وجل، والطلاق الذي علق على شرط المقصود المنع أو الحث أو التصديق أو التكذيب حكمه حكم اليمين في أصح قولي العلماء، وهكذا قول بعض الناس: علي الطلاق أن تأكل الذبيحة، علي الطلاق أن ...... الذبيحة، علي الطلاق أن تأكل كرامتك، ثم أهمله ما طاعه راح وخلاه عليه كفارة يمين ولا يقع الطلاق إذا كان قصده إكرام الشخص وليس قصده فراق زوجته وإبعادها إن لم يجلس للكرامة، فهذا حكمه حكم اليمين، وهكذا لو قال: عليه الطلاق أنه ما يكلم فلان أو ما يزور فلان ثم دعت الحاجة إلى أن كلمه وزاره، وليس مقصوده إلا منع نفسه ما قصده فراق أهله هذا فيه كفارة اليمين، هذه الأمثلة وأشباهها هي التي تسمى يميناً في الطلاق، أما إذا كان ما فيها حث ولا منع بل شرط محض هذا تعليق محض يقع به الطلاق كما تقدم، كما إذا قال: إذا دخل رمضان فأنت طالق هذا شرط محض هذا إذا وقع وقع الطلاق؛ لأن المعلق على الشروط يقع بوقوع الشروط هذا هو الأصل. نعم.","link":"https://binbaz.org.sa/fatwas/4837/حكم-من-قال-علي-الطلاق-اني-لن-اعمل-بشركة-ما-ثم-عمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_038/03801.mp3","categories":["الطلاق"]},{"id":7680,"question":"هذا المرسل يقول في رسالته عن علاقة زوجية: إذا حدث بيني وبين زوجتي نقاش حاد وغضبت منها وقلت لها: عليك أن تختاري أن تذهبي معي الآن وإلا فلست بزوجتي، ولكنها رفضت وأصرت على ألا تذهب معي، فغضبت أنا أكثر من الأول لأنها أغضبتني فقلت لأخي بزعل: أبلغها بأنها طالقة بالثلاث، وبعد ذلك بحوالي ثلاثة أيام رجعت وأشهدت اثنين بأني رددت زوجتي إلى عصمتي، فما الحكم في ذلك؟ هل تحل لي أم لا، علماً بأن لي منها طفل أرجو إجابتي عن ذلك والسلام عليكم المرسل (ح. ع. ف) من حائل ......... ؟","title":"حكم طلاق الثلاث بكلمة واحدة حال الغضب","answer":"الجواب: هذه المسألة تحتاج إلى نظر، والعادة فيها أننا نحيل المرأة والرجل وولي المرأة إلى الحاكم حتى يأخذ كلام الجميع، وبعد ذلك تكون الفتوى، والخلاصة أن الطلاق بالثلاث بكلمة واحدة يعتبر طلقةً واحدة، لكن هذا فيه التفصيل من جهة الغضب الشديد، ومن جهة حال المرأة، فإذا صدقته له حال وإذا أنكرت كلامه له حال، فالذي أرى لهذا السائل أن يكتب إلينا فيما وقع منه، أو يحضر بنفسه ونحن نحيله لرئيس المحاكم في حائل حتى يأخذ كلام المرأة وكلام وليها وكلامه، ومن الآن ننصحه أن يذهب إلى الحاكم وأن يكتب كلامه وكلام زوجته عند الحاكم وكلام وليها ويحضر عندنا إن شاء الله، أو يرسله في البريد ويأتيه الجواب إن شاء الله. نعم.\nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/4877/حكم-طلاق-الثلاث-بكلمة-واحدة-حال-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04005.mp3","categories":["الطلاق"]},{"id":7698,"question":"سؤاله الرابع والأخير يقول: رجل قال لزوجته: علي الطلاق ما تفعلين ذلك الشيء، فعصته وفعلته في الحال، ماذا يعمل: هل تعد هذه يميناً ويكفر عنها أو ماذا؟","title":"حكم الطلاق المعلق بفعل شيء ما","answer":"الجواب: إذا قال: عليه الطلاق لزوجته أنها ما تفعل هذا الشيء، فله حالان:\nإحداهما: أن يقصد إيقاع الطلاق بها إذا فعلت، هذا يكون طلقة، مثل هذا يكون طلقة تحسب عليه، إن كان قبلها طلقتين بانت منه، وإن لم يكن قبلها طلقتان تحسب عليه طلقة، إذا كان قال: عليه الطلاق إن كلمتي فلان أو إن لم تفعلي كذا أو إن زورتي فلان أو ما أشبه ذلك، وهو يقصد إيقاع الطلاق إذا فعلت، يعني نيته إيقاع الطلاق عليها، هذا يقع طلقة، أما إذا كان قصده منعها وتخويفها وليس قصده طلاقها وإيقاع الطلاق عليها، إنما قال ذلك ليمنعها من هذا الشيء: عليه الطلاق إن كلمتي فلان أو إن دخلت بيت فلان أو ما أشبه ذلك، يقصد منعها وتخويفها وزجرها، ولم يقصد ولم ينو إيقاع الطلاق عليها ولا فراقها، هذا يكون له حكم اليمين، حكمه حكم اليمين في أصح قولي العلماء، وعليه كفارة اليمين وهي إطعام عشرة مساكين، أو كسوتهم، والإطعام لكل واحد نصف صاع من التمر أو الرز.. من قوت البلد، نصف صاع يقوم مقامه كيلو ونص من ذلك، هذا فيه كفارة اليمين في مثل هذا. نعم. \nالمقدم: أحسنتم .","link":"https://binbaz.org.sa/fatwas/4897/حكم-الطلاق-المعلق-بفعل-شيء-ما ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02809.mp3","categories":["الطلاق"]},{"id":7701,"question":"يقول في سؤاله الأخير مختار صالح حامد من السودان الخرطوم: سمعنا في برنامجكم نور على الدرب أن الحلف بغير الله حرام، كما سمعنا فيه أن شخصاً حلف بالطلاق فلا تطلق زوجته، أليس في ذلك تناقض يا سماحة الشيخ؟","title":"الحلف بالطلاق ليس حلفاً بغير الله","answer":"الجواب: الحلف بغير الله منكر، النبي ﷺ قال: من كان حالفاً فليحلف بالله أو ليصمت، وقال عليه الصلاة والسلام: من حلف بغير الله فقد كفر أو أشرك وهو حديث صحيح، وقال عليه الصلاة والسلام: من حلف بالأمانة فليس منا، وقال: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون هذا حكمه عليه الصلاة والسلام، وهو منع الحلف بغير الله كائناً من كان، فلا يجوز الحلف بالنبي عليه الصلاة والسلام، ولا بالكعبة، ولا بالأمانة، ولا بحياة فلان، ولا شرف فلان، كل هذا لا يجوز؛ لأن الأحاديث الصحيحة دلت على منع ذلك، وقد نقل أبو عمر بن عبد البر -الإمام المشهور- رحمه الله إجماع أهل العلم على أنه لا يجوز الحلف بغير الله، فالواجب على المسلمين أن يحذروا ذلك، وليس لأحد أن يحلف بحياة فلان أو بشرف فلان أو بالكعبة أو بالنبي أو بالأمانة، كل هذا لا يجوز. \nأما الطلاق فلا يسمى حلف في الحقيقة، وإن سماه الفقهاء حلفاً، لكن ليس من جنس هذا، الحلف بالطلاق معناه: إيقاعه على وجه الحث والمنع والتصديق والتكذيب مثل: والله ما أقوم، والله ما أكلم فلان، هذا يسمى يمين، فإذا قال: عليه الطلاق ما يقوم، عليه الطلاق ما يكلم فلان، نسميه يمين من هذه الحيثية، يعني: من جهة ما يتضمنه من الحث والمنع أو التصديق والتكذيب، سمي يميناً لهذا المعنى، وليس فيه حلفاً بغير الله، ما قال: بالطلاق ما أفعل كذا، لا يحلف بالطلاق، لا يقول: بالطلاق ما أفعل كذا، بالطلاق ما أكلم.. لا، هذا لا يجوز، لكن إذا قال: عليه الطلاق إنه ما يكلم فلان، عليه الطلاق إنك ما تروحي يا فلانة عند كذا وكذا، يعني زوجته، عليه الطلاق ما يسافر إلى كذا وكذا، هذا طلاق معلق يسمى يميناً؛ لأنه في حكم اليمين من جهة الحث والمنع والتصديق والتكذيب، فالصواب فيه أنه إذا كان قصد منعها أو منع نفسه أو منع غيره من هذا الشيء اللي حلف عليه يكون حكمه حكم اليمين، فيه كفارة يمين، وليس في هذا مناقضة لقولنا: إن الحلف بغير الله ما يجوز، وليس في هذا مخالفة؛ لأن هذا شيء وهذا شيء، ذاك حلف بغير الله يقول: باللات والعزى، بفلان، بحياة فلان وحياة فلان، هذا حلف بغير الله، أما هذا طلاق معلق ليس حلفاً في المعنى والحقيقة بغير الله، ولكنه حلف في المعنى من جهة منعه وتصديقه وتكذيبه، فإذا قال: عليه الطلاق ما يكلم فلان، كأنه قال: والله ما أكلم فلان، أو قال: عليه الطلاق ما تكلمي فلان يخاطب زوجته كأنه قال لها: والله ما تكلمي فلان، فإذا حصل الخلل وحنث في هذا الطلاق الصواب أنه يكفر عن يمينه كفارة يمين، يعني له حكم اليمين، إذا كان قصد منع الزوجة أو منع نفسه، ما قصد إيقاع الطلاق، إنما نوى منع هذا الشيء منع نفسه أو منع الزوجة من هذا الفعل أو من هذا الكلام، فهذا يكون له حكم اليمين عند بعض أهل العلم وهو الأصح، وعند الجمهور: يقع الطلاق، عند الأكثرين: يقع الطلاق، لكن عند جماعة من أهل العلم: لا يقع الطلاق وهو الأصح، وهو اختيار شيخ الإسلام ابن تيمية وابن القيم وجماعة من السلف رحمة الله عليهم؛ لأنه له معنى اليمين من جهة الحث والمنع والتصديق والتكذيب، وليس له معنى اليمين في تحريم الحلف بغير الله؛ لأنه ليس حلفاً بغير الله، وإنما هو تعليق، فينبغي فهم الفرق بين هذا وهذا، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/4900/الحلف-بالطلاق-ليس-حلفا-بغير-الله ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02903.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":7747,"question":"أيضاً هذه وردتنا من منفوحة من عبد الله بن سليمان يقول: إذا طلقت المرأة طلاقاً رجعياً؛ فما حكم إقامتها في بيتي، أو في بيت زوجها مدة عدتها؛ لأن كثيراً من الناس يرى ذلك منكراً، أفيدونا وفقكم الله، وجعل في إجابتكم السداد والصلاح لجميع المسلمين؟","title":"هل تقيم المطلقة طلاقاً رجعياً في بيتها حتى نهاية عدتها؟","answer":"الجواب: المطلقة الرجعية عليها أن تعتد في بيت زوجها، وليس لها الخروج من بيت زوجها إلا إذا أتت فاحشة مبينة فإنها تخرج وتخرج، أما ما دامت على السداد والعافية فإنه تبقى في بيت زوجها، وهذا من وسائل رجوعه إليها وجمع الشمل بها وترك الاستمرار في طلاقها، وقد أمر الله جل وعلا ببقائها في البيت ونهى عن إخراجها، قال جل وعلا: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ وَتِلْكَ حُدُودُ اللَّهِ وَمَنْ يَتَعَدَّ حُدُودَ اللَّهِ فَقَدْ ظَلَمَ نَفْسَهُ لا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أَمْرًا [الطلاق:1] هذه الآية الكريمة في الرجعيات؛ لأنها هي التي قد يحدث لها أمر بالمراجعة، بخلاف المطلقة طلاقاً بائناً فإن هذه لا يرجى فيها حدوث أمر وأن يبدو له مراجعتها؛ لأنها لا تراجع إذا كان قد بانت، فالطلاق المذكور في هذه الآية في الرجعيات، التي طلقها طلقة واحدة أو طلقها طلقتين فله مراجعتها ما دامت في العدة، فالواجب عليه بقاؤها في البيت وألا يخرجها وألا يرضى بإخراجها، ولو طلب أهلها خروجها ينبغي له أن يأبى، وينبغي لأهلها ألا يطلبوها، بل عليهم أن يساعدوا على بقائها في البيت لهذه الآية الكريمة: لا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ ، فإذا كانت المرأة على السداد وليس فيها أذى لأهل البيت ولم تأت الفاحشة فإنها تبقى في البيت، وربما ندم فراجعها قبل خروجها من العدة، وينبغي لها أيضاً كما قال جماعة من العلماء أن تتحسن له وأن تتزين له وأن تتعرض له حتى يراها إذا دخل وإذا خرج، فربما تاقت نفسه إليها، وربما رغب في مراجعتها إذا رآها في حالة حسنة، هكذا ينبغي.\nفبقاؤها في البيت أمر واجب، وعلى الزوج أن يبقيها، وعلى أهلها أن يوافقوا على ذلك، وعليها هي أن تبقى أيضاً في البيت، وينبغي لها أن تتحسن لزوجها وأن تتعرض له لعله يندم.. لعله يراجع قبل أن تخرج من العدة، هذا هو المشروع في هذه المسألة، وإن كان الغالب على الناس ترك ذلك والجهل بذلك، ولكن جهلهم وعملهم إذا خالف الشرع لا يحتج به. نعم.\nالمقدم: لكن بقاؤها في البيت تكون متغطية أو متحجبة أو..\nالشيخ: لا، غير متحجبة، بل تكشف وجهها، وتلبس الملابس الحسنة، وتريه من نفسها ما يرغبه كإظهار شعرها وإظهار محاسنها من يديها ورجليها ووجهها وشعرها ونحو ذلك؛ لأنها زوجة، طلاقها الرجعي لا يحرمها عليه، بل لا تزال زوجة حتى تخرج من العدة، وإظهار محاسنها له وتحسنها وتطيبها له من أعظم الأسباب في رجوعه إليها. نعم.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4944/هل-تقيم-المطلقة-طلاقا-رجعيا-في-بيتها-حتى-نهاية-عدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_042/04202.mp3","categories":["الطلاق"]},{"id":7772,"question":"هذا رجل من بلاد بني شهر يقول: رجل طلق زوجته بالثلاث قائلاً: أنت طالق، ثم طالق، ثم طالق طلقات ما لي بعدهن رجعة، وكان زعلان على زوجته لمخالفتها أمره، ثم بعد مدة شهور راجعها وجابت منه أولاد، أفتوني جعل الله مثواكم الجنة؟","title":"حكم المراجعة بعد الطلاق ثلاثاً حال الغضب","answer":"الجواب: إذا كان الرجل حين طلقها هذا الطلاق بقوله: طالق، (ثم طالق، ثم طالق طلقات ما فيها رجعة) قد اشتد به الغضب، وانغلق عليه الأمر، وصار أقرب إلى عدم الشعور فطلاقه غير واقع في أصح قولي العلماء، وإعادته لزوجته لا بأس بها، ولكن كان الواجب عليه أن يستفتي قبل ذلك، كان الواجب عليه أن يستفتي قبل أن يعيدها؛ لأن الطلاق خطير، وليس كل أحد يقدر الغضب الشديد ويعرفه.\nفالواجب عليه أن يستفتي حتى يحتاط لدينه، فإذا كان غضبه قد اشتد به، وغلب عليه شدة الغضب حتى ما تمكن من إمساك نفسه عن الطلاق، بل اضطر إلى الطلاق بسبب شدة الغضب؛ لأنها سبته، أو تسابا جميعاً أو تضاربا، أو سمع منها كلاماً يعني أوجب شدة الغضب، فهذا لا يقع معه الطلاق، لما جاء في الحديث المشهور عن عائشة رضي الله عنها أن النبي عليه السلام، قال: لا طلاق ولا عتاق في إغلاق، أخرجه أحمد رحمه الله وأبو داود وابن ماجة وصححه الحاكم .\nوالإغلاق فسره العلماء بأنه الإكراه، والغضب الشديد، ولأدلة أخرى تدل على أن شدة الغضب لا يقع معها الطلاق، وصاحبها أقرب إلى زائل العقل كالمعتوه والمجنون ونحو ذلك.\nأما إن كان غضبه عادياً ليس بشديد، بل هو غضب عادي، فالطلاق يقع، فطالق ثم طالق ثم طالق، أو طالق وطالق وطالق، أو أنت طالق، أنت طالق أنت طالق بالثلاث تقع، وليس له رجعة عليها إلا بعد زوج، إذا طلقها في حال الرضا أو في حال الغضب الخفيف، فالطلاق واقع، وليس له الرجوع إليها إلا بعد زوج؛ لأنه طلقها ثلاثاً بكلمات متعددة؛ فوقعت، لقول الله سبحانه: فَإِنْ طَلَّقَهَا فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230]، ولقوله: الطَّلاقُ مَرَّتَانِ [البقرة:229]، فهذه طلقات مكررة فوقعت. نعم.\nالمقدم: لكن إذا كان هذا الزعل يعني ليس إغلاقاً كما ذكرتم، ما حكم رجعتها هذه، وإنجاب الأولاد بعد؟\nالشيخ: هذا على كل حال يعتبر غلط أعظم منه؛ لأنه تساهل، ولكن الذي يظهر أن أولاده يحلقونه؛ لأن الشبهة أعادها بسبب شدة الغضب، فيلحقه الأولاد، ولكن قد أساء وأخطأ حيث أفتى نفسه ولم يستفت أهل العلم، كان الواجب عليه يراجع القضاة الذين حوله ويستفتي، حتى يفتوه ويدلوه. نعم.","link":"https://binbaz.org.sa/fatwas/4978/حكم-المراجعة-بعد-الطلاق-ثلاثا-حال-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_046/04602.mp3","categories":["الطلاق"]},{"id":7775,"question":"هذه رسالة وردتنا من مدينة حائل من المرسل: (ح. ج. ع. ف) يقول فيها: الأخ مقدم برنامج نور على الدرب المحترم: السلام عليكم ورحمة الله وبركاته، أما بعد: أرجو عرض مشكلتي على أحد المشايخ، وأرجو أن يكون فضيلة الشيخ: عبد العزيز بن باز جزاه الله عنا خيراً وهي كالتالي:أنا شاب متزوج وأبلغ من العمر خمساً وعشرين سنة، وذلك من ابنة عمي وأتاني منها ولد، ولكن حصل بيننا خلاف حاد، وهو أنني طلبت منها أن تذهب معي، ولكن هي رفضت وأصرت على رفضها، وغضبت منها جداً وقلت لها: إن هي تذهب معي وإلا فهي طالق، وحاولت أن تذهب معي ولكنها رفضت ثانية، وفي هذا الوقت غضبت وانفعلت وقلت: أبلغوها أنها طالقة بالثلاث، وبعد أن مضى على طلاق لها ثلاثة أيام أشهدت اثنين أنني رددتها لعصمتي الزوجية، والآن مضى حوالي خمسة شهور، ولم نجتمع، فهل يجوز لي أن أراجعها بعد هذه المدة أفيدونا جزاكم الله، علماً بأني كنت فاقد أعصابي أثناء حصول الحادثة.","title":"حكم من طلق زوجته ثلاثاً بلفظ واحد","answer":"الجواب: هذا السؤال مهم، ويمكن جوابه الآن، ويمكن جوابه -أيضاً- بطريق المكاتبة، جوابه الآن أن يقال: إذا كان قصده بالطلاق على ذهابه إن لم تذهب معه، قصده تخويفها وقصده حثها على الموافقة، ولم يقصد فراقها، وإنما أراد منعها من التخلف، وأراد أن تذهب معه، فخالفته، فهذا في حكم اليمين، وعليه كفارة اليمين عن ذلك ولا يقع الطلاق.\nأما طلاقه الأخير، قوله أنت طالق بالثلاث، فهذا يقع به طلقة واحدة، على الصحيح من أقوال العلماء لما ثبت في الصحيح أن ابن عباس رضي الله عنهما، قال: «كان الطلاق على عهد النبي ﷺ وعهد الصديق أبي بكر ، وعهد عمر  في أول خلافته، طلاق الثلاث واحدة، ثم إن عمر قال: إن الناس قد استعجلوا في أمرٍ كانت لهم فيها أناة، فلو أمضيناه عليهم فأمضاه عليهم »، باجتهاده  وأرضاه.\nوالصواب: أنه يعتبر واحدة، طلاق الثلاث بكلمة واحدة إذا قال: هي طالق بالثلاث، أو قال: أنت طالق بالثلاث، أو فلانة طالق بالثلاث، فالصواب: أنها تجعل واحدة، هذا هو المعتبر والمعتمد عند جمع من أهل العلم، وهو أرجح أقوال أهل العلم في ذلك.\nفهذا السائل إذا كان طلقها بالثلاث بلفظ واحد ، فإنها تعتبر طلقة واحدة وإن كان راجعها في العدة، فهي زوجته، وإن كان مضت العدة قبل أن يراجعها، فإنها لا تحل له إلا بنكاح جديد، بالشروط المعتبرة شرعاً، وإذا حصل في هذا إشكال فإنه يكتب إلي في ذلك، وأنا إن شاء الله أحيلهما إلى فضيلة قاضي البلد الذي هم فيها وهو يكتب كلام الجميع وننظر فيه إن شاء الله. نعم.\nالمقدم: هذه الرسالة وردتنا من المستمع يقول: ابنكم عبد الرحمن محمد العسيري من فرنسا: الحمد لله...\nالشيخ: هذا تبلغه أحسن كتابة.\nالمقدم: نعم.\nالشيخ: تبلغه، الشاب هذا أخشى ألا يسمع الكلام هنا تبلغه بالكتابة إليه. نعم.\nالمقدم: إن شاء الله تعالى.","link":"https://binbaz.org.sa/fatwas/4987/حكم-من-طلق-زوجته-ثلاثا-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_047/04704.mp3","categories":["الطلاق"]},{"id":7811,"question":"يقول هذا السائل يا سماحة الشيخ: ما هو الطلاق الجائز؟ وما هو الطلاق البدعي؟ وما هو الطلاق المحرم مع التمثيل والتوضيح؟ وبماذا تنصحون الذي يتساهلون بأحكام الطلاق؟","title":"الطلاق السني والطلاق البدعي","answer":"الجواب: الطلاق المشروع: أن يطلق طلقةً واحدة، حال .... المرأة حاملاً أو في طهر لم يجامعها فيه، طلقةً واحدة حال كونها حاملاً أو آيسة أو في طهر لم يجامعها فيه.\nوالطلاق البدعي: إذا طلقها وهي في الحيض وهو يعلم، أو في النفاس وهو يعلم، أو في طهر جامعها فيه ولم يتبين حملها، هذا بدعي، إذا طلقها في طهر قد جامعها فيه ولم يتبين حملها هذا بدعي. أما إذا تبين حملها فهو طلاق شرعي.\nفطلاق الحامل وطلاق الآيسة اللي ما يجيها الحيض كل هذا طلاق شرعي.\nوالسنة أن يطلق واحدة طلقةً واحدة لا يزيد عليها، هذا هو السنة، والطلاق بالثلاث لا يجوز، الطلاق ثنتين جميع مكروه، السني أن يطلق طلقةً واحدة هذا هو السني حال كونها حاملاً أو في طهر ليس فيه جماع.\nأما كونه يطلقها في الحيض أو في النفاس أو في طهر جامعها فيه وليست حاملاً ولا آيسة هذا لا يجوز؛ لأن الرسول ﷺ نهى عن هذا في حديث ابن عمر ، وأمر الله جل وعلا أن يطلق للعدة، قال: فَطَلِّقُوهُنََّ لِعِدَّتِهِنَّ [الطلاق:1]، وطلاق العدة يكن طاهرات من غير جماع هذه العدة.\nأما إذا كن حملاً إذا كانت المرأة حاملاً فلا بأس، أو آيسة قد ارتفع سنها لا يأتيها الحيض فلا بأس، أو في طهر جامعها فيه واتضح حملها فلا بأس. نعم.\nالمقدم: وطلاق الحائض يا سماحة الشيخ!؟\nالشيخ: .. بدعة منكر لا يجوز، وطلاق النفساء كذلك لا يجوز.\nواختلف العلماء في وقوعه، فذهب قوم إلى أنه لا يقع إذا علم بذلك، وذهب الجمهور إلى أنه يقع ولو علم لكن يأثم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/5198/الطلاق-السني-والطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05116.mp3","categories":["الطلاق"]},{"id":7830,"question":"يقول هذا السائل يا سماحة الشيخ: ما هو الطلاق الجائز؟ وما هو الطلاق البدعي؟ وما هو الطلاق المحرم مع التمثيل والتوضيح؟ وبماذا تنصحون الذي يتساهلون بأحكام الطلاق؟","title":"الطلاق السني والطلاق البدعي","answer":"الجواب: الطلاق المشروع: أن يطلق طلقةً واحدة، حال .... المرأة حاملاً أو في طهر لم يجامعها فيه، طلقةً واحدة حال كونها حاملاً أو آيسة أو في طهر لم يجامعها فيه.\nوالطلاق البدعي: إذا طلقها وهي في الحيض وهو يعلم، أو في النفاس وهو يعلم، أو في طهر جامعها فيه ولم يتبين حملها، هذا بدعي، إذا طلقها في طهر قد جامعها فيه ولم يتبين حملها هذا بدعي. أما إذا تبين حملها فهو طلاق شرعي.\nفطلاق الحامل وطلاق الآيسة اللي ما يجيها الحيض كل هذا طلاق شرعي.\nوالسنة أن يطلق واحدة طلقةً واحدة لا يزيد عليها، هذا هو السنة، والطلاق بالثلاث لا يجوز، الطلاق ثنتين جميع مكروه، السني أن يطلق طلقةً واحدة هذا هو السني حال كونها حاملاً أو في طهر ليس فيه جماع.\nأما كونه يطلقها في الحيض أو في النفاس أو في طهر جامعها فيه وليست حاملاً ولا آيسة هذا لا يجوز؛ لأن الرسول ﷺ نهى عن هذا في حديث ابن عمر ، وأمر الله جل وعلا أن يطلق للعدة، قال: فَطَلِّقُوهُنََّ لِعِدَّتِهِنَّ [الطلاق:1]، وطلاق العدة يكن طاهرات من غير جماع هذه العدة.\nأما إذا كن حملاً إذا كانت المرأة حاملاً فلا بأس، أو آيسة قد ارتفع سنها لا يأتيها الحيض فلا بأس، أو في طهر جامعها فيه واتضح حملها فلا بأس. نعم.\nالمقدم: وطلاق الحائض يا سماحة الشيخ!؟\nالشيخ: .. بدعة منكر لا يجوز، وطلاق النفساء كذلك لا يجوز.\nواختلف العلماء في وقوعه، فذهب قوم إلى أنه لا يقع إذا علم بذلك، وذهب الجمهور إلى أنه يقع ولو علم لكن يأثم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/5198/الطلاق-السني-والطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05116.mp3","categories":["الطلاق"]},{"id":7900,"question":"هذه رسالة وافتنا من عبادي الهباش من جدة الجامعة، يقول فيها: محمد سافر إلى الخارج لعدة شهور، وخوفاً من الوقوع في الحرام تزوج بامرأة وفي نيته تطليقها إذا أراد العودة إلى بلده، ما هو الحكم في ذلك، وما هو الحكم إذا لم تكن لديه نية مسبقة بطلاقها وأنجبت له طفل أو طفلة ثم طلقها؟","title":"حكم الزواج بنية جازمة للطلاق","answer":"الجواب: إذا نوى المسافر بزواجه أنه يطلق إذا عزم على الرحيل، هذا فيه اختلاف بين أهل العلم، من أهل العلم من ألحق هذا بالمتعة بنكاح المتعة، ومنهم من قال: لا يلحق بنكاح المتعة وليس منها في شيء؛ لأنه قد ينوي ولا يعزم، ليس بشرط، بخلاف المتعة فإنها مشارطة أنه يطلقها بعد شهر بعد شهرين يفارقها، أما هذا فليس بينه وبينهم مشارطة، إنما في قلبه ونيته أنه إذا أراد الرحيل مثلاً من أمريكا من لندن من كذا من كذا من المغرب من الجزائر طلق، وقد يفسخ هذه النية ويرغب فيها ويرتحل بها.\nفالأقرب والله أعلم أن هذا لا يكون من المتعة، قد يكون جائزاً ولكن الأولى ألا ينوي هذه النية، عليه أن يتزوج ناوياً إن ناسبته ارتحل بها وإلا طلقها.\nأما ينوي نية جازمة أنه يطلقها فالأولى ترك ذلك، خروجاً من خلاف العلماء، هذا هو الأولى، لكن لا يبطل النكاح ولا يكون متعة بهذه النية، هذا هو الصواب، إنما يكون نكاحاً ناقصاً؛ لأن في هذه النية والذي ينبغي أن يكون عليه الرغبة مطلقة، فإذا نوى أنه إذا أراد الرحيل طلق، فالصحيح أنه لا يبطل نكاحه لكنه ترك الذي ينبغي وهو أن ينوي نية مطلقة في الرغبة، إن ناسبته أبقاها وإلا طلقها، هذا هو الذي ينبغي للمؤمن.\nوأما إذا وقع الواقع ونكح مسلمة أو كتابية -يعني- محصنة بعيدة عن الفواحش، فإن الله إنما أباح لنا الكتابيات المحصنات، فإذا نكح كتابية محصنة جاز ذلك، والأولى البعد عن ذلك وترك ذلك؛ لأنها قد تجر عليه بلاء وقد تنجب له أولاداً وتنصرهم؛ فينبغي له الحذر من ذلك، وألا يتزوج إلا مسلمة.\nهذا هو الذي ينبغي حرصاً على سلامة دين أولاده بل على سلامته هو، فقد تجره إلى دينها وتنصره هي، فينبغي له الحذر، وقد يسلم هو ولكن لا تسلم ذريته؛ فينبغي له الحذر وألا يتزوج إلا مسلمة معروفة بالخير من بيئة صالحة؛ لأن هذا هو الذي يرجى فيه الخير، وترجى معه السلامة والإحصان. نعم.","link":"https://binbaz.org.sa/fatwas/5381/حكم-الزواج-بنية-جازمة-للطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06102.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":8019,"question":"هذه رسالة وردتنا من بغداد من محافظة ديالا أيضاً من ناحية السعدية بعث بها المرسل نبيل ناظم مزاحم يشكو فيها حالة اجتماعية بينه وبين زوجته، يقول: أنا في الرابعة والعشرين من العمر متزوج ولي طفلان من زوجتي التي هي بنت خالي، وحالتي الاجتماعية جيدة والحمد لله، حدثت مشاجرة بيني وبين زوجتي في بداية زواجنا حيث فقدت أعصابي، علماً أنني مصاب بمرض الكآبة المزمنة، وعلى إثر ذلك بالطريقة غير اعتيادية طلقت زوجتي بالثلاث، كنت في حالة غير طبيعية فعلاً وكنت لا أصلي ولا أعرف من الشريعة الإسلامية وأحكامها شيء ولو بقدر حبة رز والله أعلم، وكنت أتصور الطلاق نوع من التهديد للمرأة لا أكثر ولا أقل وأما اليوم فأنا ملتزم بالفرائض الخمسة المفروضة على المسلمين والحمد لله أصبحت اليوم أعلم كثيراً من أمور الشريعة الإسلامية، رغم كل هذا أرجو من فضيلتكم أن تنظروا بقضيتي هذه، آملاً من الله أن يوفقكم في أعمالكم الخيرة، والله يحفظكم ويرعاكم؟","title":"حكم الطلاق بالثلاث بكلمة واحدة","answer":"الجواب: الطلاق بالثلاث بكلمة واحدة فيه خلاف بين أهل العلم، الكثير منهم يراها نافذة وأنها تحرم بها الزوجة حتى تنكح زوجاً آخر ويطأها؛ لما ثبت عن عمر أنه أمضى هذا الطلاق على الناس لما رأى منهم التلاعب والمسارعة إلى إيقاعه.\nوذهب آخرون من أهل العلم إلى أنها واحدة لما ثبت عن ابن عباس رضي الله عنهما «أن الطلاق على عهد النبي ﷺ وعلى عهد الصديق وفي أول خلافة عمر ..... طلاق الثلاث واحدة » يعني: إذا طلقها بالثلاث بكلمة واحدة جعلت واحدة، وقد أفتى ابن عباس وجماعة من أصحابه وغيرهم بأنها واحدة، وهذا القول أصح وأرجح القولين عملاً بما كان عليه الحال في عهد النبي ﷺ وعهد الصديق وأول خلافة عمر ، فأنت أيها الأخ الذي هداه الله، تحتسب عليك طلقة واحدة، هذا الطلاق الذي صدر منك بالثلاث يحتسب طلقة واحدة، وزوجتك معك إذا كنت راجعتها بعد صدور هذا الطلاق، أو جامعتها بنية الرجعة حال كونها في العدة، فهي زوجتك والحمد لله.\nأما إن كنت تركتها بعد الطلاق حتى اعتدت ولم تقربها ولم تتصل بها بل تركتها بسبب الطلاق حتى اعتدت، يعني: حتى حاضت ثلاث مرات بعد الطلاق فإنك تتزوجها من جديد، إذا رضيت بذلك تتزوجها من جديد بعقد جديد ومهر جديد وشاهدين، يعني: كسائر الخطاب، تخطبها لنفسها فإذا وافقت يجدد النكاح بولي وشاهدين كسائر الأنكحة الإسلامية.\nهذا هو جواب سؤالك ونوصيك بتقوى الله، والاستقامة على دينه، والتفقه في الدين، وأبشر بالخير فمن تاب تاب الله عليه. نعم.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5586/حكم-الطلاق-بالثلاث-بكلمة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_077/007704.mp3","categories":["الطلاق"]},{"id":8110,"question":"ننتقل إلى موضوع آخر على ضوء رسالة باعثها أخونا علي سالم علي من مسقط في عمان، أخونا يقول: طلقت زوجتي مرة واحدة ولم تغادر البيت وعشنا مع بعض وذلك بدون الرجوع إلى أي من رجال الدين أو إلى المحكمة ولم يكن أيضاً على رجعتنا شاهد، هل ما فعلناه صحيح؟","title":"حكم إرجاع الزوجة المطلقة بدون شاهدين","answer":"الجواب: نعم إذا راجع الرجل زوجته بالجماع أو بقوله لها: راجعتك أو أمسكتك صحت الرجعة، ولكن الأفضل أن يشهد شاهدين، هذا هو الأفضل وإن لم يشهد أجزأ ذلك على الصحيح، فإذا جامعها بنية الرجعة، أو قال لها: راجعتك. حصل المقصود بذلك إذا كان الطلاق طلقة واحدة أو طلقتين فقط، أما إذا طلقها الأخيرة الثالثة حرمت عليه حتى تنكح زوجاً غيره، لقوله : الطَّلاقُ مَرَّتَانِ فَإمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ [البقرة:229].. إلى قوله سبحانه: فَإِنْ طَلَّقَهَا يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحََ زَوْجًا غَيْرَهُ [البقرة:230] وقال سبحانه: وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَلِكَ إِنْ أَرَادُوا إِصْلاحًا [البقرة:228] يعني: أحق بردهن في ذلك في العدة، فما دامت في العدة فبعولتهن -وهم الأزواج- أحق بردهن، يعني: بالمراجعة، بقوله: راجعتك أو أمسكتك أو رددتك أو ما أشبهها من الألفاظ أو بجماعها بنية الرجعة كل هذا كافي، ولكن الأفضل أنه يشهد على ذلك شاهدين؛ لقوله سبحانه: وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ [الطلاق:2] فإن الآية فسرت بالطلاق وفسرت بالرجعة، وفسرت بهما، فإذا أشهد فهو أولى وأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/5906/حكم-ارجاع-الزوجة-المطلقة-بدون-شاهدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10205.mp3","categories":["الطلاق"]},{"id":8116,"question":"رسالة وصلت إلينا من الأخ (م. ح. م) سوداني مقيم في الرياض يقول: إنني متزوج بامرأة موظفة حيث تعمل معلمة في السودان ولديها مجوهرات وذات مرة أرادت أن تغير شكل هذه المجوهرات، وذهبت بها إلى الصائغ فأخبرتني بذلك فوافقت لها، ثم طلبت مني إيجار الصائغ وفي تلك اللحظة لم يكن معي المبلغ الذي أرادته، وفي حالة انفعال عندما أصرت على أن أعطيها المبلغ حلفت عليها بالطلاق وقلت لها: علي بالطلاق ثاني ما تلبسي ذهب، وبعد مدة أخبرتني بأن هذا الذهب لها وليس لأبيها حيث أنها عملت من مالها الخاص. وأسأل الآن عن حكم يميني تلك لأنها لم تلبس الذهب حتى نسمع الفتوى، جزاكم الله خيرا؟","title":"حكم من حلف على امرأته بالطلاق","answer":"الجواب: إن كان المقصود من هذه اليمين ألا تلبس ذهب أبيها خاصة ولم تلبسه فلا شيء عليك، وإن كان المقصود ألا تلبس الذهب بالكلية من أجل غضبك عليها فإنها متى لبسته فيكون عليك كفارة يمين، إذا كان قصدك منعها ليس قصدك طلاقها، إنما القصد من هذه اليمين يمين الطلاق أن تمنعها من لبس الذهب، سواء إن كان الذهب ذهب أبيها أو ذهبها الخاص الذي طلبت منك الأجرة من أجله، إذا كان المقصود منعها من ذلك وترهيبها وتهديدها وليس المقصود أنها متى لبست فارقتها، فإن عليك كفارة يمين وهي إطعام عشرة مساكين أو كسوتهم في أصح قولي العلماء.\nأما إن كنت أردت فراقها وأنها متى لبست فارقتها بالطلاق فإن هذا الطلاق يقع ويكون طلقة واحدة لك مراجعتها في العدة لك مراجعتها ما دامت في العدة، إذا كنت لم تطلقها قبل هذا طلقتين.\nأما إن كنت طلقتها قبل هذا طلقتين فإن هذا الطلاق يكون هو الثالث فليس لك رجعة بعده إذا كنت أردت إيقاعه.\nأما إن كنت أردت منعها وتهديدها وتخويفها ولم ترد إيقاع الطلاق إن لبست الذهب فإنه يكون عليك كفارة اليمين؛ لأنه يكون في حكم اليمين، وهذه الكفارة هي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، مما تطعم أهلك من تمر أو أرز أو حنطة أو غير ذلك من الطعام، ومقداره بالوزن كيلو ونصف تقريباً، أو كسوة تكسو الفقراء كل واحد يكسى قميص أو إزار ورداء يكفي، أو عتق رقبة إذا تيسرت، يعني: عتق عبد أو عبدة إذا تيسر ذلك، فإن عجزت ولم تستطع هذه الأمور فإنه يكفيك عن ذلك ثلاثة أيام تصومها، تصوم ثلاثة أيام كما نص الله على هذا في كتابه العظيم في سورة المائدة حيث قال ﷺ: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [البقرة:225].. الآية، فبين  أن هذه هي كفارة الأيمان، إطعام عشرة مساكين من أوسط الطعام أو كسوتهم أو عتق رقبة يعني: مؤمنة، يعني: عتق عبد مملوك أو أمة مملوكة عند وجود العبيد وتيسر ذلك، فإن لم تجد لا طعاماً ولا كسوة ولا عتقاً بل كنت فقيراً عاجزاً عن هذه الأشياء فإنك تصوم ثلاثة أيام عن يمينك، وهكذا هذا الطلاق حكمه حكم اليمين إذا كنت أردت به منعها وتهديدها وتخويفها ولم ترد إيقاع الطلاق عليها، فأما إن كنت أردت إيقاع الطلاق إن لبست الذهب فإنه يقع عليها طلقة واحدة ولك أن تراجعها في العدة قبل أن تعتد، والعدة تكون بثلاث حيض إذا كانت تحيض، إذا حاضت ثلاث مرات بعد الطلاق خرجت من العدة ولم تصلح إلا بعقد جديد، فإن كانت لا تحيض لكبر سنها أو لأسباب أخرى فعدتها ثلاثة أشهر كما بين الله ذلك في كتابه العظيم، وأنت أعلم بنفسك وأعلم بنيتك وعليك تقوى الله في ذلك .","link":"https://binbaz.org.sa/fatwas/5911/حكم-من-حلف-على-امراته-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10207.mp3","categories":["الطلاق"]},{"id":8189,"question":"أيضاً يقول في رسالته شلوي محمد علي ، يقول في رسالته: إنه يلاحظ من كثير من المبتعثين إذا عادوا إلى بلادهم بعد الابتعاث، أن كثيراً منهم يطلقون زوجاتهم، ما الذي يفسر به هذا وفقكم الله؟","title":"ظاهرة طلاق المبتعثين لزوجاتهم بعد عودتهم","answer":"الجواب: هذا ما سمعته إلا الآن، ويمكن أن يكون السر في ذلك أنه يزهد فيها بعدما يرى النساء الكافرات، وبعدما يتصل بالبغايا هناك والعياذ بالله، فقد يبدو له أن زوجته بالنسبة إليهن إلى أولئك البغايا لا تناسبه وأنهن أجمل منها، أو أنهن آدم منها، أو أعلم منها، أو ما أشبه ذلك، قد يكون هذا من الأسباب، وقد يكون من الأسباب أنها تخالفه في بعض المسائل التي تخالف الدين، وتنصحه وتريد له الخير وهي أحسن ديناً منه، فإذا جاء كرهها؛ لكونها خيراً منه، ولكونها تنكر عليه بعض أعماله السيئة، وربما يخشى أن تخبر بعوراته وأعماله الرديئة، هذا ممكن، هذا وهذا، ممكن أن يكون أن يطلقها زهداً فيها؛ لأنه رأى من هو أجمل منها وصحب من هو أجمل منها من البغايا، وقد يكون طلقها؛ لأنها تخالفه في آرائه الفاسدة، ولأنها تنكر عليه أعماله الرديئة، فلهذا كرهها وزهد فيها، لفسقه ولديانتها واستقامتها، هذا محتمل وهذا محتمل.\nالمقدم: شكراً فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/5999/ظاهرة-طلاق-المبتعثين-لزوجاتهم-بعد-عودتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_092/09205.mp3","categories":["الطلاق"]},{"id":8249,"question":"أسئلتها بسيطة لكن رجتنا ألا نهمل رسالتها سماحة الشيخ، تقول أيضاً: إن زوجي حلف بالطلاق إذا لم ترجع أخته الدينار لصاحبه ولكن أخته لم ترجعه وأخذته، وفي المرة الثانية كان الأمر كذلك، فماذا يكون الحكم؟","title":"حكم من حلف بالطلاق للتشديد والتخويف","answer":"الجواب: هذا فيه تفصيل: إن كان قصد بذلك إيقاع الطلاق إن لم ترجع الدينار وقع طلقة على زوجته بذلك وله مراجعتها ما دامت في العدة إذا كان ليس قبل ذلك طلقتان، وإن كان أراد التشديد عليها أو تخويفها ولا يريد إيقاع الطلاق فلم تفعل فعليه كفارة يمين؛ لأن هذا في حكم اليمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، يعني: كيلو ونص من قوت البلد من التمر أو الأرز أو غيرهما أو كسوتهم كسوة تجزئهم الصلاة كالقميص لكل واحد، أو عتق رقبة مؤمنة، فإن عجز وكان فقيراً لا يستطيع صام ثلاثة أيام ويكفي ذلك.","link":"https://binbaz.org.sa/fatwas/6064/حكم-من-حلف-بالطلاق-للتشديد-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%A7%D9%84%D8%AD%D9%84%D9%81%20%D8%A8%D8%A7%D9%84%D8%B7%D9%84%D8%A7%D9%82%20%D8%A7%D9%84%D9%85%D8%B9%D9%84%D9%82.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8253,"question":"رسالة بعث بها أخونا عبد الرحمن طاهر من اليمن الشمالي ويقول: إنه مقيم في الرياض يقول: كنت جالساً مع أحد أصدقائي نمزح، وقال لي أحدهم: الذي يطلق زوجته ماذا يقول؟ فقلت: يقول: أنت طالق، أنت طالق، أنت طالق، فقالوا: أنت الآن طلقت زوجتك، فوضعوا في نفسي الشك ولا سيما وقد أخبروا زوجتي بما قلت، أفيدوني لو تكرمتم؟","title":"حكم التلفظ بالطلاق مكرراً من باب التعليم","answer":"الجواب: إذا كان مقصودك بيان كيف يعمل المطلق فليس عليك شيء، ولا يعتبر منك طلاق إذا كان المقصود من هذا الكلام أنك تبين لهم كيف يطلق من أراد الطلاق هذا ليس عليك منه شيء، ولكنك غلطت في تكرار الطلاق في هذا التعليم، يكفيه مرة واحدة، يقول: (أنت طالق) ويكتفي بهذا ولا يكرر، هذا هو المشروع، ولا يجب تكراره ثلاثاً؛ لأن هذا سد لباب اليسر؛ الله جل وعلا جعل الطلاق مرتباً واحدة ثم ثنتين ثم ثلاث حتى لا يضيق الأمر على الزوج، قد يطلقها واحدة ثم يحب أن يرجع فيكون له مجال في الرجوع، ويطلقها ثنتين فيحب أن يرجع فيكون له مجال في الرجوع، فإذا طلقها الأخيرة انتهى لم تحل له حتى تنكح زوجاً غيره، فأنت علمته الطلاق الذي يحرمها عليه، فليس الأمر كما قلت، ولكن السنة أن يطلق واحدة، تقول: السنة للرجل إذا أراد الطلاق يقول: أنت مطلقة، أنت طالق، أو فلانة طالق، هذا هو المشروع، مرة واحدة فقط.\nوبكل حال فأنت ليس عليك شيء، مادمت أردت بذلك البيان وإن غلطت في البيان فليس على زوجتك شيء والزوجة باقية في عصمتك ولو بلغها الخبر إذا كان الواقع هو ما قلت إذا كنت لم تكذب في الكلام، إذا كان الواقع هو ما قلته فليس عليك شيء، وليس على زوجتك شيء، والحمد لله.\nلكن عليك أن تتأدب فلا تفت بشيء وأنت على غير علم، إذا سئلت عن شيء لا تقل إلا ما تعلم بالدليل عن كلام الله أوكلام الرسول ﷺ، أو مما سمعت من أهل العلم، تقول: سمعت للعالم الفلاني يقول كذا وكذا، تنقل عن العالم الفلاني ما ضبطت وحفظت أنه قال كذا وكذا في الصلاة.. في الصيام.. في الحج.. في الزكاة.. في غير ذلك، وأما أن تقول شيئاً وأنت جاهل فلا يجوز لك؛ لأن الله يقول : قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] فالمسلم لا يقول على الله بغير علم، وقال : يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169] فبين سبحانه أن الشيطان يأمرنا بالفحشاء والمنكر والقول على الله بغير علم، يأمرنا بالسوء والفحشاء والقول على الله بغير علم.\nفليس لنا أن نطيع الشيطان بل يجب أن نحاربه وألا نقول إلا بعلم، وإلا فعلينا الإمساك والكف عن ذلك حتى نتعلم وحتى نسأل أهل العلم، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6061/حكم-التلفظ-بالطلاق-مكررا-من-باب-التعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09802.mp3","categories":["الطلاق"]},{"id":8300,"question":"أولى رسائل هذه الحلقة وردتنا من المستمع عبد الله عبد الجواد عبد الله مصري يقول في رسالته: حلفت طلاقاً على زوجتي بهذا اللفظ: علي الطلاق بالثلاث إذا لم تفعلي العمل كذا وأنكرتيه لأطلقك، علماً بأن العمل المشار إليه كان من أعمال البر، وبعد ذلك سمعت منها كلاماً في حق ذلك العمل وهي في حالة غضب مع الأولاد، فقلت في نفسي: إذا لم أطلقها طلقة رجعية يقع عليها الطلاق بالثلاث المعلق السابق ذكره، فقلت لها: إذاً أنت طالق، وبعد ذلك راجعتها في العدة بعد توبتها، علماً بأن العمل الذي تخالفنا عليه هو المواظبة على الصلاة، و هل ما صنعته من هذه الرجعة صحيح، أم أن الطلاق الأول يقع، أفيدوني أفادكم الله؟","title":"حكم قول: علي الطلاق بالثلاث إذا لم تفعلي كذا لأطلقك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه..\nأما بعد:\nفالجواب عن هذا السؤال نحيلك به إلى القاضي في طرفكم حتى ينظر فيما جرى بينك وبينها ثم يجيبكم على ذلك، أو تحضر عندنا إذا كنت في المملكة وننظر في الأمر بإعطائك كتاباً إلى قاضي طرفك حتى ينظر في الأمر بحضورك وحضور الزوجة ووليها حتى نتأكد من صفة الواقع ونكون على بينة في ذلك، ونسأل الله للجميع التوفيق. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6111/حكم-قول-علي-الطلاق-بالثلاث-اذا-لم-تفعلي-كذا-لاطلقك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20101.mp3","categories":["الطلاق"]},{"id":8307,"question":"هذه رسالة من السائل المهندس (أبو محمد . س. م) من إيران طهران، يقول في رسالته: سمعت فتوى بعدم اعتبار طلاق المرأة وهي حائض، ولكنني قرأت أن ابن رجب الحنبلي رحمه الله في جامع العلوم والحكم قد ساق الكلام عن العلماء بأن ابن عمر في تطليقه لامرأته وهي حائض قد راجعها مع اعتبار تلك الطلقة طلقة واحدة، وذلك في شرح الحديث الخامس عن عائشة رضي الله عنها في حديث: من أحدث في أمرنا هذا ما ليس منه فهو رد فهل كلام ابن رجب مردود، أم أن في المسألة تفصيلاً، أفتونا مأجورين؟","title":"حكم طلاق الحائض والنفساء","answer":"الجواب: الجمهور -أيها السائل الكريم- الجمهور يرون أن طلاق الحائض واقع، وهكذا طلاق النفساء، وهكذا طلاق من طلقت في طهر جامعها زوجها فيه، يرون طلاق البدعة محرماً وواقعاً هذا قول الأكثرين كما حكاه غير واحد من أهل العلم كـابن عبد البر وغيرهم، ويحتجون بأن ابن عمر طلق وأمره النبي ﷺ بالمراجعة وزوجته حائض، قالوا: فلما أمره بالمراجعة دل على أن الطلقة وقعت.\nوقال آخرون من أهل العلم: ليس ذلك بواضح، فإن المراجعة معناها: الرد، ردها إلى عصمته إلى بيته، ولا يلزم منها المراجعة الشرعية، ولا يلزم منها القول بوقوع الطلقة، بدليل أنه ﷺ قال: ثم ليمسكها حتى تطهر ثم تحيض ثم تطهر، ثم إن شاء طلق وإن شاء أمسك فالرسول ﷺ لا يأمر بتكرار الطلاق وتكثيره، وإنما أراد إيقاع الطلاق الذي أراده ابن عمر ، وأما الطلقة الأولى فهي لاغية؛ لأنها وقعت في غير محلها، وقعت على غير الوجه الشرعي فلا تكون معتبرة، والطلاق المعتبر هو الأخير الذي بعد طهرها من حيضتها الثانية التي بعد الحيضة التي طلقها فيها، وفي لفظ آخر: ثم إن شاء طلق وإن شاء أمسك وفي لفظ آخر: ثم ليطلقها طاهراً أو حاملاً فدل ذلك على أن الطلقة التي طلقها في الحيض غير واقعة.\nوقد سئل ابن عمر عن ذلك، سأله رجل وقال: «يا أبا عبد الرحمن! رجل طلق امرأته وهي حائض أيعتد بها؟ فقال له: لا يعتد بها» وهو نفس الذي وقعت عليه القصة رواه محمد بن عبد السلام الخشني بإسناد صحيح عن ابن عمر أنه سئل عن ذلك فقال: «لا يقع»، وهو صاحب القصة، ذكر هذا أبو العباس ابن تيمية وابن القيم وغيرهما عن الشيخ محمد الإمام العلامة محمد بن عبد السلام الخشني أنه روى هذا بإسناده الصحيح إلى ابن عمر، وقال هذا المعنى طاوس بن كيسان اليماني أحد أصحاب ابن عباس وأحد كبارهم، وقاله أيضاً خلاس بن عمرو الهجري، وذهب إليه جماعة من أهل العلم؛ لأنه طلاق لم يوافق الشرع فلم يعتبر، وقد قال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد يعني: مردود، وهذا طلاق ليس عليه أمر النبي ﷺ فيكون مردوداً، وقد قال لابن عمر : ثم ليمسكها حتى تطهر ثم تحيض ثم تطهر، ثم إن شاء طلق وإن شاء أمسك وفي رواية قال: فردها علي ولم يرها شيئاً، وقال: إذا طهرت فأمسكها أو طلقها فهذا كله واضح في أنها لم تقع، وأن المطلقة في طهر جامعها فيه أو في حيض أو في نفاس طلاقها غير واقع؛ لأنه طلاق بدعة، وطلاق في غير محله فلا يقع، وهذا هو الذي أفتى به أبو العباس ابن تيمية وابن القيم وجماعة آخرون من أهل العلم أخذاً بحديث ابن عمر نفسه، وبفتواه  ورحمة.\nأما ما جاء في بعض الروايات أنه احتسبها، أو أنها حسبت عليه فهذا ليس بواضح أنه بأمر النبي ﷺ، وإنما هو من اجتهاده  حسبها باجتهاده ثم بان له بعد ذلك أن احتسابها غير واقع وغير مناسب؛ فلهذا أفتى بأنها لا تقع، نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم.\nالشيخ: أما كلام ابن رجب فلم أطلع عليه ولا أذكره الآن، وعلى كل حال إن كان ابن رجب قال: إنه يقع، فهو جرى على ما قاله الأكثرون، ولكن شيخه ابن القيم وشيخ شيخه أبو العباس ابن تيمية قالا: إنه لا يقع، وهما أعلم من ابن رجب وأبصر بدين الله وأبصر بالسنة. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/6124/حكم-طلاق-الحاىض-والنفساء","audio":"","categories":["الطلاق"]},{"id":8326,"question":"وهذه رسالة من المرسل (محمود . ت. س) مصري يعمل بالمملكة يقول في رسالته: لقد حلفت على زوجتي بأن تكون طالق إذا فعلت كذا، وكان بنية التهديد، مع العلم أنه حدث مني ثلاث مرات، وكل ما وقع في الحالات الثلاث عاشرتها بعد الحلف من غير أن أسأل عن ذلك؛ لأنني لم أقصد بأنها يمين صحيح أو يمين طلاق، بل كانت يمين بنية التهديد، فوقع مني يمين رابع وكان بنية الطلاق، فأريد أن تفتوني في الحكم؟","title":"حلف على زوجته بالطلاق للتهديد فما حكمه؟","answer":"الجواب: أما الأيمان الثلاث الأولى التي بقصد التهديد وليس بقصد إيقاع الطلاق ولكن لتخويفها وتهديدها، فهذه الثلاث الصواب فيها أنها في حكم اليمين، وعلى السائل كفارة اليمين في كل واحدة، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، والكسوة: إزار ورداء أو قميص، أما الإطعام: فهو نصف صاع من التمر أو من الرز أو غير ذلك من قوت البلد، هذا هو الإطعام، وإن غداهم أو عشاهم كفى ذلك، ولا يقع الطلاق بذلك في أصح قولي العلماء، وذهب الجمهور إلى أنه يقع الطلاق بهذه اليمين إذا قال: إن كلمت فلان فأنت طالق، أو إن ذهبت إلى بيت أهلك فأنت طالق، أو إن فعلت شيئاً آخر فأنت طالق، قصده التهديد، فالأكثرون على أنه يقع ولا تنفعه هذه النية، ولكن الصحيح الذي عليه المحققون من أهل العلم أن هذا في حكم اليمين، ولا يكون طلاقاً بل عليه كفارة اليمين، وهذا هو الذي نفتي وهو الأصح، وهو الذي أفتى به شيخ الإسلام ابن تيمية رحمه الله والعلامة ابن القيم، وهو ظاهر ما نقل عن جماعة من السلف الصالح من التابعين، وهو ظاهر ما نقل عن ابن عمر وعن صفية زوجته بنت أبي عبيد، وعن جماعة فيمن حلفت بالعتق والصدقة بمالها وعتق عبيدها على أنه لا يفعل كذا فلم يفعل، قالوا لها: عليك كفارة يمين؛ لأنها إنما قصدت إلزامه لم تقصد العتق ولا الصدقة، وإنما أرادت إلزام هذا الشخص بأن يطلق زوجته ... فقالوا: عليك بهذا كفارة يمين، ولا يلزمك أن يكون مالك صدقة ولا عتق الرقاب؛ لأنها لم ترد ذلك وإنما أرادت إلزامه والتأكيد عليه، فإذا كان هذا في المحبوب إلى الله من الصدقة والعتق وهما محبوبان إلى الله، فالطلاق المبغوض إلى الله من باب أولى أنه لا يقع مع التهديد وقصد التأكيد والتشديد والتخويف لا بقصد إيقاع الطلاق هذا هو الصواب.\nأما الرابعة التي علقها على شرط يريد إيقاع الطلاق فهي تقع، فإذا قال: إن خرجت بغير إذني فأنت طالق، وقصده إيقاع الطلاق وقع إذا خرجت، أو قال: إن كلمت فلاناً وقصده إيقاع الطلاق وقع على نيته، الأعمال بالنيات. نعم.\nالمقدم: جزاكم الله خير، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6142/حلف-على-زوجته-بالطلاق-للتهديد-فما-حكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20207.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":8327,"question":"الرسالة الثانية في حلقة هذه الليلة من المستمعة (ع. ف) مصرية الجنسية وتعمل بالمملكة، رسالتها طويلة ولكن خلاصتها، تقول: بأنها متزوجة وهي تعصي زوجها وجاهلة ودائماً تغضب منه، ودائماً لا تعطيه حقه كزوج، وتطلب منه الطلاق كثيراً، وقد طلقها مرتين، وعندما يذهبان للمأذون يرفض المأذون هذا الطلاق لأنه في حالة غضب، ولكنها تصر هي على طلب الطلاق فيوافق المأذون حتى أصبح عدد الطلقات ثلاث طلقات على يد المأذون، وبما أنها -كما تقول- تحبه وهو يحبها ويرغبان الرجوع إلى بعضهما فقد اعترض دون ذلك والدها، وهو من حملة الكتاب -كما تقول- ونصحها بأنها لا تحل لزوجها حتى تتزوج رجلاً غيره، في هذه الحالة ذهبا إلى مأذون بلدتهما، فقال لها: يمكنك أن تأتي بمحلل.وفعلاً قد اتفقا مع رجل طيب يريد لهما الصلاح -كما تقول في رسالتها- على أن يعقد عليها، وثاني يوم يطلقها دون أن يمسسها كزوج وأكملت عدته، ورجعت لزوجها بعد العدة، وعاشت على هذه الحال خمس سنوات أنجبت خلالها طفلين وهي تعيش مع زوجها في عناد وفي مشاكل وفي جحود وهو صابر ومتحمل كما تقول هي في رسالتها.وقد سافرت إلى الخارج منذ سنة، والتقت بأناس طيبين نصحوها بأنه لا يجوز لها أن تعصي زوجها، وبينوا لها حكم الله، وهي الآن نادمة وتائبة، وتريد أن تعرف ما الحكم في بقائها مع زوجها، هل تبقى معه، أم أنه يفرق بينهما، وإذا فرق بينهما فما مصير الطفلين اللذين جاءا بعد الطلقة الأخيرة، هذه خلاصة رسالتها يا سماحة الشيخ؟","title":"نصيحة في طاعة المرأة لزوجها، وحكم المحلل","answer":"أولاً: الواجب على الزوجة طاعة زوجها في المعروف، ومعاشرته بالمعروف؛ لأن حقه عظيم، وقد قال الله جل وعلا: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] وأوصى النبي ﷺ المرأة بالسمع والطاعة لزوجها، وقال: إذا باتت المرأة وزوجها ساخط عليها لعنتها الملائكة حتى تصبح وفي لفظ آخر: كان الذي في السماء ساخطاً عليها حتى يرضى عنها زوجها فالأمر عظيم والخطر كبير، وقال أيضاً عليه الصلاة والسلام: أيما امرأة سألت الطلاق من غير ما بأس لم ترح رائحة الجنة هذا وعيد شديد، فسؤال الطلاق من غير علة من غير بأس لا يجوز، وعلى المرأة السمع والطاعة، والكلام الطيب، والمعاشرة الحسنة في المعروف فيما أباح الله وشرعه ، وليس لها عصيان زوجها ولا تكديره وإيذاؤه لا بالكلام ولا بالفعال، متى طلبها لحاجته في نفسها أجابت، ومتى أمرها أطاعت فيما يتعلق بشئونهما، وهكذا ما يتعلق بخدمة البيت وإحضار الطعام، وما جرت به العادة بين الزوجين، هذه أمور يلزمها أن تطيع زوجها في ذلك، وأن تخاطبه بالتي هي أحسن، وأن تسير معه المسيرة الحسنة التي عرفها الأخيار من المسلمين فيما بينهم، وأما الطلاق فقد حدد الله الطلاق وجعله ثلاثاً، فإذا طلقها ثم راجعها، ثم طلقها ثم راجعها، وهو عاقل، طلقها على الوجه الشرعي، ثم طلقها الثالثة فإن الطلقة الثالثة تحرمها، وليس له أن ينكحها إلا بعد زوج شرعي يطؤها ثم يطلقها أو يموت عنها، بعد ذلك تحل له أن يراجعها، أما التحليل: فهو لا يجوز بل هو منكر وهو نكاح باطل، والرسول ﷺ لعن المحلل والمحلل له والعياذ بالله! فكونه ينكحها زوج محلل يتفقان معه على أنه ينكحها ثم يفارقها، هذا منكر ومن كبائر الذنوب وصاحبه ملعون، المحلل والمحلل له جميعاً، ولا يحلها للزوج السابق؛ فالذي فعلوا مع المحلل أمر منكر وطريق فاسد، وصاحبه قد تعاطى كبيرة عظيمة، وهي لا تزال محرمة على زوجها، وعليها أن تفارقه حتى تتزوج زوجاً شرعياً، وحتى يطأها الزوج الشرعي ثم يفارقها بموت أو بطلاق ثم تعتد. أما الأولاد الذين جاءوا بعد ذلك بهذا النكاح الباطل فهم أولاد زوجها بالشبهة لأجل الشبهة؛ لأن هذا وقع عن شبهة وعن جهل فيلحق الأولاد هذا الزوج وينسبون إليه، ولكن عليها وعلى زوجها التوبة إلى الله، والندم، والإقلاع، والعزم الصادق أن لا يعودا إلى مثل هذا المنكر، ومتى تزوجت زوجاً شرعياً لا محللاً ثم وطئها ثم طلقها أو مات عنها فإنها تحل لزوجها هذا. المقدم: يعني إذاً: الخلاصة -فضيلة الشيخ- أنها تفارق زوجها ويفارقها الآن. الشيخ: الخلاصة أنها مقيمة معه على حرام، وعليها أن تفارقه ويفارقها، وعليهما التوبة إلى الله جل وعلا جميعاً، أما أولادهما فلاحقون بأبيهم؛ لأجل الشبهة، لأجل وطء الشبهة، وليس لها أن تعود إليه أبداً إلا بعد زواج شرعي، بعد زوج شرعي يطؤها ثم يفارقها بموت أو طلاق، ثم بعد ذلك يتزوجها زوجها الأول إذا شاء، نعم. نسأل الله السلامة. نعم. المقدم: أحسنتم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6137/نصيحة-في-طاعة-المراة-لزوجها-وحكم-المحلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20202.mp3","categories":["الطلاق","الحقوق الزوجية"]},{"id":8422,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الشقيقة وباعثها أخونا صبري محمد ضحى فيما يبدو مصري، أخونا بدأ رسالته بقوله: أحييكم بتحية الإسلام التي في أولها: السلام عليكم، وفي آخرها: الرحمة والبركات من عند المولى . سلام الله عليكم ورحمته وبركاته وحسناته ومرضاته، وبعد: نحن متابعون برنامجكم العظيم، فنفعنا الله بعلمكم، وجزاكم الله خيراً، وبارك لنا فيكم، وإني أتوجه إليكم بسؤالين، وفقنا الله وإياكم لما فيه الخير، السؤال الأول: ما حكم الإسلام في يمين الطلاق أمام الزوجة أو غيابها؟","title":"حكم يمين الطلاق","answer":"الجواب: وعليكم السلام ورحمة الله وبركاته، نعم، الطلاق له صور كثيرة، فإذا كان الطلاق معلقاً على وجه اليمين كأن يقول لها مشافهةً: إذا كلمت فلاناً فأنت طالق، أو إذا خرجت إلى بيت فلان فأنت طالق، أو ما أشبه ذلك مما يقصد منه الحث أو المنع أو التصديق أو التكذيب، هذا الطلاق يقال له: يمين؛ لأنه في معنى اليمين؛ ولأن مقصوده مقصود اليمين، فإذا كان قصد المطلق منعها من شيء، أو حملها عليه، أو التصديق أو التكذيب، فهذا عند المحققين من أهل العلم في حكم اليمين، وذهب الأكثرون إلى أنه يقع، له حكم الشرط حكم المعلق، ولكن الصواب الذي عليه جمع من أهل التحقيق أنه في حكم اليمين، فعليه كفارتها إذا لم يقصد إيقاعه، وإنما قصد منعاً، أو حثاً، أو تصديقاً، أو تكذيباً؛ فإنه يكون له حكم اليمين في عدم الوقوع والاكتفاء بالكفارة، فإذا قال لها: إن كلمت فلاناً فأنت طالق، قصده أن يمنعها من ذلك، ليس قصده إيقاع الطلاق، إنما قصده منعها من تكليمه، فإنها إذا كلمته يكون على زوجها كفارة اليمين، ولا يقع الطلاق في أصح قولي العلماء.\nوهكذا لو قال لزوجته: إن خرجت من بيتك اليوم أو غداً أو قصده دائماً بغير إذني فأنت طالق، ومقصوده منعها من الخروج، وليس قصده إيقاع الطلاق؛ فإنها بذلك إذا خرجت بغير إذنه يكون عليه كفارة، ولا يقع الطلاق؛ لأنه لم يقصد إيقاعه وإنما قصد المنع، أما إن قصد إيقاع الطلاق فإنه يقع متى خرجت. نعم.","link":"https://binbaz.org.sa/fatwas/6306/حكم-يمين-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11813.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8435,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: لقد تزوجت وأنا عمري ثلاث عشرة سنة، وكنت أجهل أمور الزواج وحقوق الزوج، وكثيراً ما كنت أطلب منه الطلاق، تكرر ذلك مني كثيراً حتى اضطر أن يقول في مرة من المرات: أنت طالق، أنت طالق، أنت طالق، وبعد أربعة أشهر وفي ذلك اليوم الذي كتب به ورقة الطلاق، وشهدا على طلاقي شاهدان كانت عليها العادة، وتسأل عن حكم الطلاق والحالة هذه شيخ عبد العزيز ؟","title":"حكم طلب المرأة للطلاق وحكم طلاق الحائض","answer":"الجواب: أولاً: الواجب على المرأة تقوى الله، والمعاشرة الطيبة لزوجها، وعدم إيذائه بطلب الطلاق ولا بغيره من الأذى كالسب، والشتم، وعدم السمع والطاعة، كل هذا لا يجوز، ما دام الزوج قائماً بحقها، فالواجب عليها أن تقوم بحقه أيضاً، الله يقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، ويقول : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228]، فعليها المعاشرة بالمعروف وعليه المعاشرة بالمعروف، بالكلام الطيب والفعل الجميل، في الفراش، وفي البيت، وفي جميع الأحوال، تقول له الكلام الطيب وهو يقول لها الكلام الطيب، وتؤدي له ما يجب من الطاعة في بيته، في خدمته، في طاعته في الفراش، في غير هذا مما أباح الله .\nوهو كذلك يعاملها بالمثل، بالكلام الطيب، والسيرة الحميدة، والإنفاق عليها كما أمر الله، إلى غير هذا من وجوه المعاشرة الطيبة، وليس لها طلب الطلاق مع الاستقامة، بل هذا لا يجوز، أما إذا كانت الحالة غير ذلك بأن كان أساء العشرة، أو ما كتب الله لها في قلبه المحبة مثلاً: تبغضه ولا تستطيع القيام بحقه للبغضاء، فلا مانع أن تخبره بذلك، وأن تطلب منه الطلاق، حتى لا تخل بالواجب، فإن سمح بذلك فالحمد لله وإلا فعليها الصبر حتى يجعل الله فرجاً ومخرجاً.\nأما ما وقع من الطلاق في حال الحيض، فهذا فيه خلاف بين أهل العلم، جمهور أهل العلم يرون أنه يقع الطلاق وهذا قول الأكثرين من أهل العلم، والقول الثاني: أنه لا يقع في الحيض، ولا في النفاس، ولا في طهر جامعها فيه الرجل؛ لما ثبت من حديث ابن عمر رضي الله تعالى عنهما في الصحيحين أنه طلق امرأته وهي حائض فرفع ذلك إلى النبي ﷺ فغضب وأنكر عليه ذلك، وأمره أن يراجعها، وأن يمسكها حتى تطهر ثم تحيض ثم تطهر، ثم إن شاء أمسك، وإن شاء طلق قبل أن يمسها، فهذا يدل على أن الطلاق في حال الحيض والنفاس منكر، وهكذا في الطهر الذي جامعها فيه، وإنما السنة أن يطلقها في طهر لم يجامعها فيه، أو في حال حملها، ولهذا في اللفظ الآخر: فليطلقها طاهراً أو حاملاً.\nفالصواب أنه لا يقع في هذه الحالة، وإن كان قول الأقل والأكثرون على وقوعه، لكن قول الأقل في هذا أصح؛ لهذا الحديث الصحيح، والله المستعان. نعم.\nالمقدم: بارك الله فيكم، كأن أختنا تحمل كونها زوجت وعمرها ثلاث عشرة سنة تحمل هذا الموضوع كل هذه الأخطاء؟\nالشيخ: لا حرج، النبي ﷺ تزوج عائشة وهي بنت سبع سنين، ودخل بها وهي بنت تسع سنين، فالأمر في هذا واسع، لكن على أهلها أن يعلموها إذا أرادوا تزويجها في هذا السن، عليهم أن يعلموها ويوجهوها ويشرحوا لها حقوق الزوج، وأن عليها كذا وكذا وكذا حتى تكون على بصيرة، وإلا فلا يعجلوا حتى تأخذ العلم بنت خمسة عشرة بنت ستة عشر سبعة عشر، يعني: ينبغي لهم أن يزوجوها في الأوقات المناسبة، التي يرون أنها أهل لذلك، فإذا أرادوا التبكير بأن خطبها الكفء وخافوا فوت الكفء، خافوا فوق الرجل الطيب، فينبغي أن يغتنموا الرجل الطيب، ولو كانت بنت ثلاثة عشر لكن يعلمون عليهم أن يعلموها ويوجهوها حتى تعرف ماذا تعمل مع الزوج، رزق الله الجميع الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/6319/حكم-طلب-المراة-للطلاق-وحكم-طلاق-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11912.mp3","categories":["الطلاق"]},{"id":8474,"question":"شيخ عبد العزيز اجتمع لي في هذه الحلقة أربع رسائل أصحابها يسألون عن الطلاق.فالرسالة الأولى من ليبيا وباعثها أخونا محمد عبدالحميد سعيد وطلق امرأته أربع مرات ويستفتي.أما الرسالة الثانية فمن بغداد حي الشعب أخونا يقول: إنه طلق ثلاث مرات ويستفتي أيضاً.ثم الأخ شوقي ميلود من الجزائر يقول: كتب كتابة ونصها إنها في غرضها وهذه العبارة لديهم يقول: إنها تعرف بالطلاق.أما أخونا صالح السيد الجرجاوي فيقول: إنه طلق بالثلاث وبعثه مسجلاً في شريط وحدد فترة الطلاق لمدة سنة، يستفتون عن هذه المواضيع في باب الطلاق لو تكرمتم سماحة الشيخ؟","title":"مسائل متعلقة بالطلاق","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وصفوته من خلقه وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فإني أجيب إخواني السائلين عن هذه المسائل المتعلقة بالطلاق، أن يراجعوا المفتي لديهم في بلادهم ويشرحوا له الواقع وفيما يراه إن شاء الله الكفاية، أو إلى المحكمة التي تنظر في الأحوال الشخصية على هدى الإسلام حتى يفتوهم في ذلك لأن المقام يحتاج إلى حضور الزوج وحضور المرأة المطلقة وحضور وليها وحضور من شهد الواقع، قد يحتاج إلى هذا كله، فالقاضي أو المفتي ينظر في ذلك ويسأل الحاضرين يسأل الزوج ويسأل الزوجة عما لديها، ويسأل الولي فقد يقول الزوج شيئاً والحقيقة بخلافه، فالمقام يحتاج إلى عناية وإلى احتياط فنصيحتي لهؤلاء السائلين أن يتصلوا بالمفتين عندهم، ويشرحوا لهم الواقع والمفتي أو القاضي ينظر في الأمر، وإذا دعت الحاجة إلى أن يكتب إلي القاضي أو المفتي في شيء من ذلك للتفاهم معه فيما قد يشكل فليس عندي مانع من ذلك، وهذا كله من باب التعاون على البر والتقوى والتناصح في الله .\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6509/مساىل-متعلقة-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12501.mp3","categories":["الطلاق"]},{"id":8515,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع (م. م) من جمهورية مصر العربية يعمل بالرياض، يقول في رسالته: حدثت مشادة كلامية بيني وبين حماتي أم زوجتي وذلك بحضور الزوجة، وازداد الكلام حدة حتى خرجت من فمي كلمة كنت أود أن لا تخرج ولا ينطق بها لساني، فقد قلت: ابنتك هذه طالقة، وكنت أقولها دون حقد أو كره لزوجتي على الإطلاق، ولم تكن هناك نية مسبقة على أن أتلفظ بهذا اللفظ الذي ندمت عليه، فهل كوني قلت لأم زوجتي وفي حضور الزوجة: (ابنتك طالقة) تصبح طلقة، مع العلم بأنه بناء على معلوماتي السطحية عن حكم الشرع أنه مجرد لغو طالما هو في لحظة انفعال، فقد قمت بمباشرة حياتي الزوجية العادية مع زوجتي، ولكن أريد أن أعرف الفتوى ليطمئن قلبي؟","title":"حكم طلاق الغضبان وحكم الطلاق البدعي","answer":"بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا محمد وعلى آله وأصحابه أجمعين.\nأما بعد: فالطلاق ينبغي للمؤمن أن لا يعجل فيه، فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: أبغض الحلال إلى الله الطلاق فينبغي للمؤمن أن لا يعجل في الطلاق ويتثبت، وألا يطلق إلا عن روية وعن رغبة في الطلاق؛ لأنها قد طابت نفسه من المرأة، ورأى أن الأصلح طلاقها، فيطلقها على بصيرة، وإذا طلق فليطلق واحدة فقط، لا يزيد على طلقة واحدة، هذا هو السنة، لكن إذا كان الطلاق في حال شدة الغضب الذي يمنعه من التعقل وضبط نفسه بسبب طول النزاع بينه وبينها والمسابة والمشاتمة أو المضاربة، فإذا تحقق شدة الغضب الناشئ عن أمر واضح من مسابة ومشاتمة أو مضاربة أو أشباه ذلك مما يعلم منه شدة الغضب وعدم استطاعته أن يملك نفسه في هذا المقام فإن هذا على الأصح لا يقع؛ لأنه في هذه الحالة أشبه شيء بالمعتوه والمجنون فلا يقع طلاقه، أما الغضب العادي الذي تجري العادة به بين الناس ليس بغضب شديد قد توافرت أسبابه وشدته؛ فإن هذا يقع معه الطلاق، وإذا كان طلقة واحدة راجعها وشهد اثنين، يقول: اشهد يا فلان وفلان أني راجعت زوجتي، أو رددت زوجتي، أو أمسكت زوجتي ونحو ذلك، هذه السنة؛ لأن الله قال: وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ [الطلاق:2] وهذا في الطلاق والرجعة، فيشهد على ذلك اثنين أنه راجعها، وإن طابت نفسه منها أشهد اثنين على أنه طلقها، ثم هكذا إذا طلقها الثانية إن كان عن رغبة في الطلاق أو غضب عادي ليس بشديد فهذا تقع الثانية أيضاً وله مراجعتها، فيشهد اثنين أنه راجعها إذا رغب في ذلك، هذا هو السنة، فإن اشتد الغضب معه شدة واضحة بسبب أسباب اقتضت ذلك من مضاربة أو مسابة أو مشاتمة أو نحو ذلك مما يكون معه الغضب شديداً يعجز المرء عن ضبط نفسه فلا يقوى بسبب ما غلب عليه من الغضب، فإنه في هذه الحال يشبه بالمعتوه والمجنون فلا يقع الطلاق، ثم تبقى الطلقة الثالثة، إذا وقعت الطلقتان الأوليان فالطلقة الأخيرة تحرمها إلا بعد زوج، إذا وقع قبلها طلقتان فإن الطلقة الأخيرة هي المحرمة لها حتى تنكح زوجاً غيره.\nفالمؤمن يحاسب نفسه في هذه الأمور ويتقي الله ، فإذا وقع منه الطلاق عن طيب نفس ورغبة في الطلاق أو في غضب عادي فإنه يحتسب عليه، وتعتبر المرأة طالقاً طلقة واحدة، ثم هكذا الثانية ثم هكذا الثالثة على حسب ما يقع من العبد، وهناك أمور أخرى قد يقع فيها الطلاق وهي: حال الحيض، حال النفاس، حال الطهر الذي جامعها فيه.\nقد ذهب بعض أهل العلم إلى أنه في هذه الحالة لا يقع الطلاق، بل هو طلاق بدعي منكر لا يجوز، فليس للمسلم أن يطلق في الحيض ولا في النفاس، ولا في طهر جامعها فيه؛ لما ثبت في الصحيحين عن ابن عمر رضي الله تعالى عنهما أنه طلق امرأته وهي حائض، فأنكر عليه النبي ﷺ، وأمره أن يراجعها، وأن يمسكها حتى تحيض ثم تطهر ثم تحيض ثم تطهر، ثم إن شاء طلق قبل أن يمس، وإن شاء أبقاها وفي لفظ قال له: فإذا طهرت فليطلقها طاهراً أو حاملاً يعني: قبل أن يمسها، وقرأ قوله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] هذا هو الطلاق للعدة أن يطلقها في طهر لم يجامعها فيه، أو في حال حملها.\nبعض العامة يظن أن طلاق الحامل لا يقع، وهذا غلط، طلاق الحامل شرعي يقع، إنما الذي فيه الخلاف طلاق الحائض والنفساء، أو طلاق المرأة التي هي طاهر قد جامعها وليست حاملاً، هذا هو محل الخلاف، والأكثرون من أهل العلم على أنه يقع الطلاق، الأكثرون من العلماء على أنه يقع الطلاق في حال الحيض، في حال النفاس، في حال الطهر الذي جامعها فيه، مثل حال الحامل، وذهب قوم من أهل العلم إلى أنه لا يقع لكونه طلاقاً منكراً لم يوافق الشرع فلا يقع؛ لكون النبي أنكره عليه الصلاة والسلام، وحذر الأمة منه، وأمر من طلق أن يمسك حتى تحيض ثم تطهر، ثم تحيض حيضة أخرى ثم تطهر، ثم إن شاء طلق وإن شاء أمسك، وهذا القول الذي قاله بعض أهل العلم أظهر في الدليل وأرجح في الدليل، ولكن يجب على المؤمن أن يحذر الطلاق في هذه الأمور، فإنه إذا طلق في حال الحيض فقد أثم، أو طلق في النفاس فقد أثم، وهكذا إذا طلقها في طهر جامعها فيه لا يجوز، فعليه التوبة من ذلك وأن لا يعود إلى ذلك، أما الوقوع فقد عرفت أن الأكثرين على أنه يقع، وقد ذهب جمع من أهل العلم إلى أنه لا يقع، منهم ابن عمر ، فإنه ثبت عنه أنه استفتي في ذلك، فقال: «لا يعتد بها ». وهكذا جاء معنى ذلك عن طاوس التابعي الجليل وعن خلاس بن عمرو الهجري التابعي الجليل، وذهب إليه جمع من أهل العلم، فينبغي للمؤمن أن يحذر التساهل في هذه الأمور، وأن يحفظ لسانه عن الطلاق إلا عند الحاجة إليه والرغبة فيه في حال طهر لم يجامعها فيه أو في حال الحمل، هذا هو الطلاق الشرعي، أما طلاقها في حيض أو في نفاس أو في طهر جامعها فيه فهذا لا يجوز، والواجب التوبة من ذلك والحذر من ذلك وعدم العود إليه، والله المستعان. نعم.\nالمقدم: لكن صاحبنا هذا يظهر أن طلقته هذه تحتسب طلقة واحدة؛ لأنه من كلامه يقول: قال لحماته: ابنتك هذه طالقة، ثم يذكر بأنه باشرها بعد ذلك.\nالشيخ: هي المقصود أنه إذا كان الطلاق لم يستحكم عليه ولم يشتد معه الغضب بسبب نزاع جرى بينهم أو مضاربة أو مسابة فإن الطلقة تحسب عليه، ويكون جماعه رجعة لها، يكون جماعه رجعة لها. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6584/حكم-طلاق-الغضبان-وحكم-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20301.mp3","categories":["الطلاق"]},{"id":8542,"question":"رسالة رابعة في حلقة هذه الليلة وردتنا من السودان أيضاً، من السائل عبد الله قادم أحمد ، يقول الأخ عبد الله في رسالته: مشكلتي أنني طلقت زوجتي ثلاث طلقات على النحو التالي، في بداية زواجنا سافرت لبلد آخر وكتبت لي إحدى أخواتي بسوء معاملة زوجتي لوالدي، فأرسلت لها خطاباً بأنها مطلقة، وعند عودتي رأيت بأن هذا كذب، فقلت لها: أنت راجعة دون أن أعطيها نظير ذلك مالاً، أو أن أحضر شخصاً يشهد على ردها، وبعد سنتين من المرة الأولى غضبت مني والدتي وادعت أنني أقول لزوجتي أن تعاملها معاملة سيئة وبذلك غضبت فطلقت حتى يتحسن جو المعاملة بيني وبين والدتي، وأخيراً: رأيت ظروف أولادي الصغار وقلت لها: أنت راجعة دون أن أعطيها مالاً أو أن أشهد واتفقنا على ذلك، ثم حصل نقاش أسري أدى إلى خصومة الأسرتين وأغضبني الأمر فطلقتها بعد إصرار والدي على أن أطلقها، فعند ذلك لم أتمكن من تركيز أعصابي وغضبت غضباً شديداً فطلقتها وانتهى الأمر؛ ولظروف أولادي الأربعة من هذه الزوجة؛ ولأنني لم أجد من يعولهم إذا أخذتهم منها، ولا أطمئن على حالهم عندها، فأنا أسأل الآن هل يمكن أن أعيدها إلى عصمتي أم لا؟","title":"مسألة في الطلاق","answer":"الجواب: تراجع فضيلة مفتي البلد لديكم أو المحكمة أنت وولي المرأة حتى ينظر في الواقع على بصيرة، وحتى يفتي فيه أو يحكم فيه على بصيرة، إن كان مفتي أو قاضي ينظر في الأمر، تراجعه أنت والزوجة ووليها، وهو ينظر في الواقع.. في المرات الثلاث ويفتيكم إن شاء الله بما يتضح له. نعم.\nالمقدم: جزاكم الله خير، يعني: لابد من حضور الطرفين عند القاضي. الشيخ: لأن ... قد يصدقونه وقد يكذبونه، لابد يحضرون معه، تحضر المرأة ووليها معه عند المفتي أو عند القاضي حتى ينظر في كلامهم جميعاً. نعم. المقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6621/مسالة-في-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20512.mp3","categories":["الطلاق"]},{"id":8550,"question":"له سؤال آخر في هذه الرسالة، يقول فيه: إذا طلق الإنسان زوجته وهي حامل ثلاث طلقات، فهل تكون طالق أم يحق له الرجوع إليها؟","title":"إذا طلق زوجته ثلاثا وهي حامل فهل يحق له الرجوع؟","answer":"الجواب: إذا طلق الرجل امرأته وهي حامل وقع الطلاق؛ لأن الطلاق للحامل طلاق شرعي؛ ولهذا ثبت في الصحيح عن النبي ﷺ أنه قال لـعبد الله بن عمر لما طلق امرأته وهي حائض قال: أرجعها ثم أمسكها حتى تطهر، ثم تحيض ثم تطهر، ثم إن شئت طلقها طاهراً أو حاملاً فطلاق الحامل طلاق مشروع، ولكن بعض العامة يظن أن طلاقها لا يقع، بعض العامة يظن أن طلاق الحبلى لا يقع، وهذا غلط، بل الصواب: أنه واقع بإجماع المسلمين، لا خلاف في طلاق الحامل وأنه يقع، لكن إذا كان طلقها بالثلاث بلفظ واحد كأن قال لها: أنت مطلقة بالثلاث، أو فلانة مطلقة بالثلاث، فهذا فيه خلاف بين أهل العلم، فذهب جمهور أهل العلم وأكثرهم إلى أنه يقع الطلاق ثلاثاً، وتحرم عليه حتى تنكح زوجاً غيره.\nوذهب بعض أهل العلم إلى أنه لا يقع إلا واحدة، وله مراجعتها ما دامت في العدة قبل أن تضع حملها؛ لأنه ثبت عن النبي ﷺ من حديث ابن عباس رضي الله عنهما ما يدل على أن الثلاث إذا وقعت بلفظ واحد فإنها تعتبر طلقة واحدة، وقد أفتى بهذا حبر الأمة عبد الله بن عباس رضي الله تعالى عنهما في بعض الروايات عنه، ويروى ذلك عن علي  ، وعن الزبير بن العوام ، وعن عبد الرحمن بن عوف ، وعن جماعة من التابعين ، وهو الأرجح في الدليل. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6629/اذا-طلق-زوجته-ثلاثا-وهي-حامل-فهل-يحق-له-الرجوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20602.mp3","categories":["الطلاق"]},{"id":8566,"question":"هذه رسالة وردتنا من جمهورية مصر العربية من محافظة الشرقية، من سائل رمز لاسمه بـ (ع. س. م) يقول: حدث بيني وبين زوجتي خلاف فضربتها بغضب في ذات يوم فبكت وقالت: أريد أن تطلقني، فقلت لها: ارتدي ملابسك حتى أوصلك لأهلك وننظر من يبحث عنك هناك، ولما أرادت أن ترتدي ملابسها منعتها من ذلك، وتصالحنا في ذلك اليوم، وكأن شيئاً لم يكن، ولكن نفسي تحدثني من وقت لآخر عما حصل بيننا هل يعتبر طلاقاً أم لا، أفيدوني أفادكم الله؟","title":"حكم قول الرجل لزوجته: (ارتدي ملابسك واذهبي إلى أهلك)","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل فليس بطلاق؛ بل زوجة السائل معه ولم يقع عليها شيء، وقوله: ارتدي ملابسك ليس بطلاق. نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6641/حكم-قول-الرجل-لزوجته-ارتدي-ملابسك-واذهبي-الى-اهلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20702.mp3","categories":["الطلاق"]},{"id":8568,"question":"هذه رسالة وردتنا من سوريا من المرسل محمد الأحمد الفواز، يقول: عندي حاجة نافعة مفيدة لكل إنسان، وهذه الحاجة أعطيتها لأحد أقاربي فضيعها، وحلفت بالطلاق طلقة واحدة إذا وجدتها لا أعطيها لأحد، وفعلاً وجدت هذه الحاجة، وصار لها عندي خمسة عشر سنة، وكل إنسان يسألني عنها أقول: ليست موجودة احتفاظاً بكلمة الطلاق مع أنها موجودة عندي، فهل علي في ذلك إثم؟","title":"حكم من أقسم بالطلاق ألا يعطي أحداً شيئاً عنده","answer":"الجواب: هذا فيه تفصيل: فإن كانت الحاجة تنفع الناس فينبغي له أن يعيرها الناس وينفع الناس والطلاق ينظر فيه، فأما إن كانت الحاجة ليس لها أهمية بالنسبة إلى الناس، بالنسبة إلى أقاربه أو غيرهم فإن الأمر فيها سهل، وليس في حاجة إلى أن يسأل عن الطلاق، لكن الطلاق فيه تفصيل، فإن كان أراد بذلك منع نفسه من تسليم الحاجة لأحد من الناس، ولم يرد إيقاع الطلاق، وإنما أراد أن يمنع نفسه بهذا الطلاق من تسليمها للناس، فهذا عليه كفارة يمين، ويجوز له ولا حرج عليه إذا سلمها للناس ولا يقع طلاق.\nإذا كنت -أيها السائل- أردت بذلك منع نفسك من تسليم الحاجة لأحد من الناس ولم ترد إيقاع الطلاق، فإنه لا يقع طلاق بذلك وعليك كفارة يمين إذا أعطيتها أحداً من الناس.\nأما إن كنت أردت إيقاع الطلاق إن أعطيتها أحداً من الناس فإنه يقع طلقة على زوجتك إذا أعطيتها أحداً من الناس، والطلقة الواحدة لا تحرمها عليك، لك المراجعة في الحال، لك أن تراجعها في الحال، فتشهد شاهدين بأنك راجعت زوجتك فلانة، وتصح الرجعة والحمد لله، إذا أعطيتها لأحد هذه الحاجة، وأنت تريد بالطلاق إيقاع الطلاق.\nهذا إذا كانت المرأة لم تطلقها قبلها طلقتين، أما إذا كان زوجتك قد سبق لها طلقتان، فإن هذه الطلقة تحرمها عليك الطلقة الأخيرة، إذا أعطيت الحاجة لأحد من الناس وأنت مريد إيقاع الطلاق تكون هذه الطلقة هي الثالثة، وبها تحرم المرأة على زوجها حتى تنكح زوجاً غيره، نكاحاً شرعياً، نكاح رغبة لا نكاح تحليل، ويطأها الزوج الذي نكحها، لابد أن يطأها ثم يفارقها بعد هذا إما بموت أو طلاق. نعم.\nالمقدم: بارك الله فيكم\nالمقدم: لكنه يسأل في آخر الرسالة أو ذكر أنه يكذب إذا سأله أحد عن هذه الحاجة، قال: ليست موجودة عندي وهي عنده خوفاً من وقوع الطلاق؟\nالشيخ: هذا غلط، والواجب عليه في هذا التوبة إلى الله ، فإن المؤمن ليس له أن يكذب، وإذا كان هناك حاجة لعدم بيان وجودها فيعرض بشيء، ليست موجودة، يعني: في المكان المعين الذي هي فيه، أو ليست موجودة في أي محل معين، يعني: ينوي مكاناً غير موجودة فيه، مثلاً: في المجلس وهي في مكان آخر في المخزن، أو ينوي ليست عندي في الدهليز، أو ليست عندي في الدكان، أو في المكتب أو ما أشبه ذلك، حتى يكون غير كاذب، يتأول في هذا حتى يكون لا يقع عليه الكذب. نعم.\nالمقدم: أحسنتم، جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6642/حكم-من-اقسم-بالطلاق-الا-يعطي-احدا-شيىا-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8570,"question":"هذه رسالة وردتنا من جمهورية مصر العربية من محافظة الشرقية، من سائل رمز لاسمه بـ (ع. س. م) يقول: حدث بيني وبين زوجتي خلاف فضربتها بغضب في ذات يوم فبكت وقالت: أريد أن تطلقني، فقلت لها: ارتدي ملابسك حتى أوصلك لأهلك وننظر من يبحث عنك هناك، ولما أرادت أن ترتدي ملابسها منعتها من ذلك، وتصالحنا في ذلك اليوم، وكأن شيئاً لم يكن، ولكن نفسي تحدثني من وقت لآخر عما حصل بيننا هل يعتبر طلاقاً أم لا، أفيدوني أفادكم الله؟","title":"حكم قول الرجل لزوجته: (ارتدي ملابسك واذهبي إلى أهلك)","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل فليس بطلاق؛ بل زوجة السائل معه ولم يقع عليها شيء، وقوله: ارتدي ملابسك ليس بطلاق. نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6641/حكم-قول-الرجل-لزوجته-ارتدي-ملابسك-واذهبي-الى-اهلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20702.mp3","categories":["الطلاق"]},{"id":8575,"question":"[ما هو قولكم فيمن يحلف بالطلاق]؟","title":"تفصيل قولي العلماء في الحلف بالطلاق دون قصده","answer":"الجواب: ........ أن يزور فلان، عليه الطلاق أن يكلم فلان قصده الحث، هذا كله في حكم اليمين، وعليه كفارة اليمين إذا فعل ما حلف على تركه أو ترك ما حلف على فعله عليه كفارة اليمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن لم يجد صام ثلاثة أيام.\nأما إن كان قصد إيقاع الطلاق، قال: عليه الطلاق ما يكلم فلاناً، عليه الطلاق ما يشتري السيارة الفلانية، وقصده أنه متى فعل وقع الطلاق فإنه يقع الطلاق، لقول النبي ﷺ: الأعمال بالنيات وإنما لكل امرئ ما نوى هذا هو الصواب من قولي العلماء.\nوذهب الأكثر إلى أنه يقع الطلاق مطلقاً ولو قصد الحث والمنع أو التصديق أو التكذيب، ولكن الصواب التفصيل، الصواب التفصيل، فإن كانت النية حثاً ومنعاً أو تصديقاً أو تكذيباً ليس قصده إيقاع الطلاق إنما قصده تخويف زوجته من أن تفعل كذا وردعها عن ذلك، أو قصده أن يمنع نفسه من كذا وليس قصده إيقاع الطلاق فهذا حكمه حكم اليمين في أصح قولي العلماء، واختار هذا القول أبو العباس شيخ الإسلام ابن تيمية رحمه الله والعلامة ابن القيم رحمه الله وجماعة من أهل العلم المحققين، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6659/تفصيل-قولي-العلماء-في-الحلف-بالطلاق-دون-قصده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_208/20807.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8580,"question":"له سؤال ثان أيضاً يقول فيه: كنت أتناقش مع زميلي في موضوع فأثار غضبي، وبعدما انصرف زميلي قلت: بيني وبين نفسي لكنني تلفظت، قلت: علي الطلاق أنت وسخ، وأعني بكلمة وسخ أنه يحب نفسه دون مصلحة الآخرين أو كذا، فهل هذا يمين أم طلاق؟ وهل علي كفارة أفيدوني أفادكم الله؟","title":"حكم من قال علي الطلاق أنا كذا.","answer":"الجواب: إذا كنت تعتقد ذلك حين قلت: علي الطلاق أن تقول: أنك وسخ، إذا كنت تعتقد ذلك وأنك صادق فيما أردت من الوساخة، وأنه أناني يحب نفسه، هذا قصدك بالوساخة، فأنت ليس عليك شيء؛ لأنك قلت شيئاً تعتقد صدقك فيه، وما دمت تعتقد أنك صادق فيما وصفته به، فليس عليك شيء. نعم.\nالمقدم: بارك الله فيكم، وإذا كان لا يعتقد هذا إنما هو للغضب، يعني: يكفر أم يعتبر يمين فضيلة الشيخ؟\nالشيخ: ... هذا يختلف إذا قال: أنت وسخ، وهو يعتقد أنه كاذب، فالظاهر أنه يقع عليه الطلقة، يقع على زوجته طلقة واحدة؛ لأنه ما أراد بهذا مخاطبة أحد من الناس، بينه وبين نفسه، فإذا قال: علي الطلاق أنك وسخ، أو عليه الطلاق إن فلان قدم وهو يعلم أنه ما قدم، يقع طلقة على زوجته. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6670/حكم-من-قال-علي-الطلاق-انا-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20909.mp3","categories":["الطلاق"]},{"id":8612,"question":"وأولى رسائل هذه الحلقة رسالة وردتنا من المستمع (عبد الله . ن. س) من الدلم يقول فيها: أولاً: المرأة إذا طلقت طلقة واحدة أو طلقتين وعاد زوجها إليها بعقد جديد هل تحتسب عليه الطلقات السابقة؟","title":"ما عدد الطلقات التي تحسب لمن رجعت بعد طلاق بائن؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن المطلقة إذا كانت رجعية وهي التي طلقت طلقة واحدة أو طلقتين على غير مال وقد دخل بها فإنها تعود إليه على بقية الطلاق، لا يبقى له إلا ما بقي من الثلاث، فإن كان طلقها واحدة عادت إلى طلقتين، وإن كان طلقها طلقتين عادت .. طلقة، لم يبق لها إلا طلقة، هذا هو الذي عليه أهل العلم. نعم.\nالمقدم: وإذا طلقت بائناً ثم عاد إليها بعد زوج هل تحتسب عليه الطلاق السابق؟\nالشيخ: كذلك ولو عاد بعد نكاح من زوج آخر، إذا كان لم يطلقها إلا طلقة فإنها تعود عليه بطلقتين، وإن كان طلقها طلقتين تعود بطلقة؛ لأن الزوج الجديد لا يهدم الطلاق السابق إذا كان أقل من ثلاث، وإنما يهدمه إذا كان ثلاثاً، وأما إذا كان أقل من ثلاث فإنه لا يهدم البقية عند جمهور أهل العلم، بل ترجع إليه على ما بقي لها من الطلاق، حتى ولو كان بعد زوج. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6735/ما-عدد-الطلقات-التي-تحسب-لمن-رجعت-بعد-طلاق-باىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21001.mp3","categories":["الطلاق"]},{"id":8615,"question":"وأولى رسائل هذه الحلقة رسالة وردتنا من المستمع (عبد الله . ن. س) من الدلم يقول فيها: أولاً: المرأة إذا طلقت طلقة واحدة أو طلقتين وعاد زوجها إليها بعقد جديد هل تحتسب عليه الطلقات السابقة؟","title":"ما عدد الطلقات التي تحسب لمن رجعت بعد طلاق بائن؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن المطلقة إذا كانت رجعية وهي التي طلقت طلقة واحدة أو طلقتين على غير مال وقد دخل بها فإنها تعود إليه على بقية الطلاق، لا يبقى له إلا ما بقي من الثلاث، فإن كان طلقها واحدة عادت إلى طلقتين، وإن كان طلقها طلقتين عادت .. طلقة، لم يبق لها إلا طلقة، هذا هو الذي عليه أهل العلم. نعم.\nالمقدم: وإذا طلقت بائناً ثم عاد إليها بعد زوج هل تحتسب عليه الطلاق السابق؟\nالشيخ: كذلك ولو عاد بعد نكاح من زوج آخر، إذا كان لم يطلقها إلا طلقة فإنها تعود عليه بطلقتين، وإن كان طلقها طلقتين تعود بطلقة؛ لأن الزوج الجديد لا يهدم الطلاق السابق إذا كان أقل من ثلاث، وإنما يهدمه إذا كان ثلاثاً، وأما إذا كان أقل من ثلاث فإنه لا يهدم البقية عند جمهور أهل العلم، بل ترجع إليه على ما بقي لها من الطلاق، حتى ولو كان بعد زوج. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6735/ما-عدد-الطلقات-التي-تحسب-لمن-رجعت-بعد-طلاق-باىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21001.mp3","categories":["الطلاق"]},{"id":8652,"question":"هذه رسالة وردتنا من السائل (أ. أ. س) من سوهاج جمهورية مصر العربية، يقول: قد حلفت على زوجتي بالطلاق، وصيغته: أنت طالق ثلاث مرات، أي: كررت أنت طالق.. أنت طالق.. أنت طالق، من مدة أربع سنوات تقريباً، وبعد ذلك أنجبت منها طفلان بعد الطفل الذي كانت تحمله، يعني: ثلاثة أطفال حتى الآن؛ لأن الموضوع الذي أثار شعوري إلى الغضب والحلف وكان في نيتي أنه طلقة واحدة، كل ذلك علماً بأنني سألت قبل رد اليمين فأفتوني بأنه طلاق بدعة؛ لأنها كانت حامل، وآخر قال: إنه طلاق رجعة، عند ذلك أرجعت زوجتي بشهادة اثنين ومهر قليل جديد وعاشت معي حتى الآن، ولكنني سمعت فتوى من إذاعة المملكة العربية السعودية برنامج نور على الدرب فتوقفت عن مباشرة زوجتي حتى تفتوني فيما حصل بارك الله فيكم؟","title":"حكم من قال: (أنت طالق) ثلاث مرات دفعة واحدة","answer":"الجواب: إذا كنت أردت بهذا التكرار التأكيد وأنك ما أردت إلا واحدة حين قلت لها: أنت طالق.. أنت طالق.. أنت طالق إنما أردت واحدة وهي الأولى، وكررت ذلك للتأكيد فإنه لا يقع إلا واحدة. وزوجتك تكن معك على حل النكاح ولا حرج عليك إن شاء الله في ذلك، أما إذا كنت أردت إيقاع الثلاث تقع الثلاث، إذا كانت في ذاك الوقت حاملاً كما قلت فإن الطلاق يقع، طلاق الحامل ليس بدعة بل هو شرعي، وإنما البدعة طلاق الحائض، طلاق النفساء وطلاق المرأة في طهر جامعها فيه وهي غير حبلى لم يتبين حملها هذا هو البدعة، أما طلاق الحامل فليس بدعة، وهكذا طلاق المرأة في طهر لم يجامعها زوجها فيه ليس بدعة.\nفالمقصود: أنك إذا كنت أردت التأكيد ما أردت إلا واحدة فلا ينبغي لك الوساوس وزوجتك حلال لك، والواقع واحدة، الواقع طلقة واحدة؛ لأن الأعمال بالنيات، فما دمت نويت طلقة واحدة وكررتها للتأكيد فإنه لا يقع إلا واحدة، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6794/حكم-من-قال-انت-طالق-ثلاث-مرات-دفعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21309.mp3","categories":["الطلاق"]},{"id":8683,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع أحمد إبراهيم أحمد من محافظة منيا القمح من جمهورية مصر العربية، يقول: أنا أعمل في المملكة منذ سنة وعند نزولي إلى البلد وجدت زوجتي طلقت طلاقاً شرعياً وأنا لم أطلقها؛ لأن لي منها ثلاثة أولاد والآن طلقت، فماذا أفعل أفيدوني بارك الله فيكم؟","title":"حكم طلاق المحاكم الشرعية من دون علم الزوج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالطلاق الذي يصدر من المحاكم الشرعية هي المسئولة عنه، وله أسباب قد يكون لأجل عدم قيام الزوج بالنفقة أو لأسباب أخرى، فعليك أن تراجع القاضي الذي طلقها هو يفيدك عن الأسباب، ونسأل الله للجميع التوفيق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6814/حكم-طلاق-المحاكم-الشرعية-من-دون-علم-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21501.mp3","categories":["الطلاق"]},{"id":8687,"question":"هذه رسالة أيضاً وردت من السائل (أ. م. ع) مدرس مصري معار بالجمهورية العربية اليمنية، يقول: في ظروف طارئة مع زوجتي وكنت في لحظة يأس وغضب بعدما حصل منها، صدر مني يمين وقلت: علي الطلاق لازم أتزوج ولو على آخر يوم من عمري، وكانت النية صريحة وأنا في لحظة غضب، ما حكم هذا اليمين؟","title":"حكم من حلف بالطلاق على امرأته أن يتزوج","answer":"الجواب: إذا كان المقصود من هذا التأكيد على نفسك أنك تتزوج وإغاظتها في ذلك، وليس قصدك إخراقها إن لم تتزوج، فإن هذا حكمه حكم اليمين، لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فإذا كنت أردت بهذا التأكيد على نفسك أنك تتزوج ولو لم ترض الزوجة وإنما أردت بهذا التأكيد ولم تقصد أنك إن لم تتزوج فهي مطلقة إنما أردت التأكيد على نفسك، فهذا حكمه حكم اليمين وعليك كفارة اليمين، وما دمت أردت ولو في آخر حياتك فالأمر في هذا فيه سعة. نعم.\nالمقدم: بارك الله فيكم، يضيف أيضاً ويقول: صدر مني يمين قبل ذلك وأنا في لحظة غضب أيضاً بسبب امتناعها عن حقوقي الشرعية، وللعلم بأنني رزقني الله منها بولدين وأربع بنات وإذا فعلت ذلك -أظنه يشير إلى الزواج- سأكون السبب في تشريد هؤلاء الأولاد وضميري لا يسمح بذلك، فهل علي كفارة أو ماذا أفعل؟\nالشيخ: إذا كان المقصود السؤال الأول وأنك طلقت أنك تتزوج ولو في آخر حياتك، فأنت بالخيار إن شئت تزوجت ووفيت بيمينك وإن شئت كفرت عن يمينك، إذا كان المقصود من هذا التأكيد على نفسك، ليس المقصود فراق زوجتك إنما المقصود في أن تؤكد على نفسك أنك تتزوج فأنت بعد هذا بالخيار، إن شئت تزوجت ولا شيء عليك وإن شئت كفرت كفارة يمين ولا شيء عليك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6815/حكم-من-حلف-بالطلاق-على-امراته-ان-يتزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21502.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8721,"question":"أولى رسائل هذه الحلقة وردتنا من المرسل سيد أحمد عثمان مصري الجنسية ومقيم بالعراق محافظة صلاح الدين يقول: قبل أن أتجه إلى العراق حلفت بالطلاق بالثلاث لزوجتي، بأن لو ذهبت إلى بيت أهلك لا يكن لك ردة علي، إلا إذا كان هناك وفاة أو مرض خطير جداً، وأنا هنا لي سنة وستة أشهر فما رأي فضيلتكم إذا أرسلت لها بأن تذهب لتزورهم، وفقكم الله؟.","title":"الطلاق بالثلاث يعتبر واحدةفي أصح قولي العلماء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فهذا السؤال يختلف الجواب عنه بحسب نية المطلق، فإن كنت أيها السائل أردت بذلك منعها من الذهاب إلى أهلها ولم ترد إيقاع الطلاق، وإنما قصدت المنع، هذا له حكم اليمين، فمتى ذهبت إلى أهلها فإن عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمن لم يجد صام ثلاثة أيام.\nوهذا أفتى به جمع من السلف الصالح وأفتى به أبو العباس ابن تيمية شيخ الإسلام ابن تيمية رحمه الله وابن القيم وجماعة من أهل العلم، لأنه ما أراد الطلاق، والرسول عليه الصلاة والسلام يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\nوهذا إنما أراد منعها ولم يرد إيقاع الطلاق عليها، فتكون له نيته كما قاله النبي عليه الصلاة والسلام، أما إن كنت أردت إيقاع الطلاق عليها إن ذهبت أنه يقع الطلاق فإنه يقع عليها طلقة واحدة، لأن إيقاع الطلاق بالثلاث في أصح قولي العلماء يعتبر واحدة، لما ثبت في الصحيحين من حديث ابن عباس رضي الله تعالى عنهما قال: كان الطلاق على عهد النبي ﷺ، وعهد أبي بكر وسنتين من خلافة عمر طلاق الثلاث واحدة، فقال عمر: إن الناس قد استعجلوا في أمر كانت لهم فيه أناة فلو أمضيناه عليهم فأمضاه عليهم رواه مسلم في الصحيح.\nفهذا هو الذي وقع في عهد عمر  وأرضاه، والصواب والأرجح: هو ما كان عليه الحال في عهد النبي ﷺ وعهد الصديق وفي أول خلافة عمر رضي الله تعالى عنه، فإذا كنت أردت الطلاق إن ذهبت فإنه يقع عليها واحدة ولك مراجعتها مادامت في العدة، ومتى خرجت العدة ولم تراجع، فلك العود إليها بنكاح جديد بشروط معتبرة شرعاً، إذا كنت ما طلقتها قبل هذا طلقتين، وهذا إن لم تكن أردت ...إلا بإذنك، فإن كنت أردت بهذا الكلام إلا بإذنك، قلت: علي الطلاق بالثلاث أنك ما تذهبي لأهلك إلا عند وفاة أو مرض، يعني: أردت في نيتك إلا بإذنك، يعني: أردت في قلبك إلا بإذنك فإنك متى أذنت لها فلا يقع شيء، لا كفارة ولا طلاق، متى أذنت لها أن تذهب إليهم فإنه لا يقع شيء، أما إن كنت قلت هذا الكلام ولم ترد إلا بإذنك، بل أطلقت الكلام فإن كنت أردت منعها فقط فإنه كفارة يمين على الصحيح من قولي العلماء.\nأما إن أردت إيقاع الطلاق عند ذهابها إلى أهلها فإنه يقع عليها طلقة واحدة كما تقدم، والله ولي التوفيق.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6870/الطلاق-بالثلاث-يعتبر-واحدة-في-اصح-قولي-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21601.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8735,"question":"أحد الإخوة يقول عوض ثابت أحمد مصري يعمل بالعراق، يقول: اتهمني صاحبي ذات يوم أنني تحدثت إلى أحد أقاربه بكلام يسيء إليه، ثم قمت بإحضار قريبه ذلك وأثبت له أنني بريء من تهمته، وفي لحظة غضب أقسمت بالطلاق أنني لابد أن آخذ منه حقي ولو بعد حين، وبعدها سافرت للعراق وعلمت بعد فترة أن صديقي هذا توفي، ماذا علي؟","title":"حلف بالطلاق أن ينتقم من شخص لكنه توفي","answer":"","link":"https://binbaz.org.sa/fatwas/6889/حلف-بالطلاق-ان-ينتقم-من-شخص-لكنه-توفي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16107.mp3","categories":["الطلاق"]},{"id":8760,"question":"وأولى رسائل هذه الحلقة وردتنا من السائل (ع. ش) من الرياض يقول في رسالته في سؤاله الأول: هل يقع طلاق السكران؟ فإن كان يقع فهل يحاسب على تصرفاته المتعدية الأخرى كالزنا والقتل والسرقة؟ فإن كان كذلك فما الفرق بين الحالين أفيدونا أفادكم الله؟","title":"حكم طلاق السكران وسائر تصرفاته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد اختلف العلماء في طلاق السكران هل يقع أم لا؟ فذهب الجمهور إلى أنه يقع طلاقه كما يؤخذ بأفعاله ولا تكون معصيته عذراً له في إسقاط الطلاق، كما أنها لا تكون عذراً له في مؤاخذته بأفعاله من قتل أو سرقة أو زنا أو غير ذلك، وذهب بعض أهل العلم إلى أن طلاق السكران لا يقع، وهذا هو المحفوظ عن عثمان  الخليفة الراشد؛ لأنه لا عقل له فلا يؤخذ بأقواله التي تضر غيره والطلاق يضره ويضر غيره فلا يؤخذ بالطلاق؛ لأن عقوبة السكران الجلد وليس من عقوبته إيقاع طلاقه وهكذا عتقه وتصرفاته الأخرى كالبيع والشراء والهبة ونحو ذلك كلها باطلة، أما أعماله وأفعاله فإنه يؤخذ بها، ولا يكون سكره عذراً له لا في الزنا ولا في السرقة ولا في القتل ولا غير هذا؛ لأن الفعل يؤخذ به الإنسان عاقلاً أو غير عاقل، ولأن السكر قد يتخذ وسيلة إلى ما حرم الله من الأفعال المنكرة وقد يحتج به فتضيع أحكام هذه المعاصي، ولهذا أجمع أهل العلم على أخذه بأفعاله.\nأما القول: فالصحيح أنه لا يؤخذ به، فإذا علم أنه طلق في السكر عند زوال العقل؛ فإن الطلاق لا يقع، وهكذا لو أعتق عبيده في حال السكر أو تصدق بأمواله في حال السكر؛ فإنه لا يؤخذ بذلك أو باع أمواله أو اشترى فجميع التصرفات التي تتعلق بالعقل لا تقع ولا تثبت من تصرفاته القولية كما بينا، وهذا هو المعتمد وهو الذي نفتي به أن طلاقه غير واقع متى ثبت سكره حين الطلاق وأنه لا عقل له، أما إذا كان غير آثم بأن سقي شراباً لا يعلم أنه مسكر، أو أجبر عليه وأسقي الشراب عمداً بالجبر والإكراه، فإنه غير آثم ولا يقع طلاقه في هذه الحال؛ لأن سكره ليس عن قصد فيؤخذ به، بل هو مظلوم أو مغرور فلا يقع طلاقه عند الجميع. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6903/حكم-طلاق-السكران-وساىر-تصرفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21701.mp3","categories":["الطلاق"]},{"id":8766,"question":"هذه رسالة وردت إلينا من السائل سليمان أبو خليل مصري الجنسية يعمل بالدمام يقول: حلفت على زوجتي وأنا في حالة غضب يمين بالطلاق بالثلاث وأن تكون محرمة علي مثل أمي وأختي إذا ذهبت إلى منزل والدها طول غيابي، وحتى الآن لم تذهب، وعندما قرأت حديثاً عن الرسول ﷺ يقول: لا يدخل الجنة قاطع رحم أود أن أرسل لها رسالة وأقول لها: اذهبي إلى أهلك، لكن ما الحكم في يميني؟","title":"حكم الحلف بالطلاق ثلاثاً مع التحريم على فعل شيء","answer":"الجواب: إذا كنت أردت بذلك منعها فقط ولم ترد فراقها إن ذهبت وإنما أردت منعها فقط من الذهاب إلى بيت والدها، فهذا له حكم اليمين، وعليك كفارة يمين إذا ذهبت ولا بأس بذلك، وإن كنت أردت إلا بإذنك، ليس لها الذهاب ناوٍ إلا بإذنك ثم أذنت لها فلا شيء عليك، أما إذا كنت ما نويت إلا بإذنك وأردت طلاقها وتحريمها إن ذهبت فإنك إذا أذنت لها وذهبت يقع طلقة واحدة عليك، يقع طلقة واحدة عليها في أصح قولي العلماء، وعليك كفارة الظهار إن كنت أردت تحريمها، فعليك كفارة الظهار وهي: عتق رقبة عبد أو أمة مؤمنة فإن عجزت ولم تستطع هذا العتق فصيام شهرين متتابعين، فإن لم تستطع أطعمت ستين مسكيناً ثلاثين صاعاً لكل مسكين نصف صاع، وهو كيلو ونص تقريباً قبل أن تمسها سواءً كان من رز أو من تمر أو من حنطة يعني من قوت البلد، هذا هو الواجب عليك قبل أن تمسها ويقع عليها طلقة واحدة، إذا كنت أردت إيقاع الطلاق عليها وتحريمها، وإن كنت ما أردت الطلاق وإنما أردت المنع منعها من الذهاب فقط، فإنك عليك كفارة يمين إذا ذهبت إلى والدها إلا أن تكون أردت في قلبك إلا بإذنك ناوياً إلا بإذنك، فإنك إذا أذنت لها فلا شيء عليك، والله أعلم. فينبغي لك أن تحذر هذا، هذا ما يجوز ليس للمسلم أن يحرم أهله وليس له أن يطلق بالثلاث، الطلاق الشرعي واحدة، يطلق واحدة فقط، ثم إذا طابت نفسه طلق الثانية وهكذا، أما كونه يجمع الطلاق الثلاث لا يجوز، كما أنه لا يجوز له أن يحرم زوجته بل هو منكر من القول وزور كما بينه الله في كتابه العظيم، فالواجب على المسلم أن يتقي الله وأن يحذر ما حرمه الله عليه، ومما حرمه الله عليه الطلاق بالثلاث، والتحريم من زوجته والظهار منها كل هذا منكر، فالواجب على كل زوج أن يتقي الله وأن يتحرى الطلاق الشرعي فيطلقها طلقة واحدة .... إذا عزم على الطلاق يطلق واحدة فقط حال كونها طاهراً لم يجامعها وليست في حيض ولا في نفاس، هذا هو المشروع يطلقها في حال طهرها وعدم الوقوع بها يعني: عدم جماعها أو في حال حملها كونها حامل، هذا هو الطلاق الشرعي ويكون الطلاق واحدة لا بالثلاث، وأما التحريم فلا يجوز ليس له أن يحرمها يقول: حرام علي أو هي علي مثل أمي أو أختي كل هذا لا يجوز، بل هذا مما أنكره الله على عباده، وأرشدهم إلى تركه . نسأل الله للجميع الهداية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6926/حكم-الحلف-بالطلاق-ثلاثا-مع-التحريم-على-فعل-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21808.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8767,"question":"هذه رسالة وردت إلى البرنامج من خلف مصطفى محمد حسن مصري ويقيم بسامراء بالعراق يقول: بعد سوء تفاهم بيني وبين زوجتي بمصر سافرت إلى العراق للعمل ثم ضاقت بي الظروف النفسية نتيجة لما أعانيه من التعب النفسي وتأنيب الضمير على ما حدث بيننا قبل أن أسافر، وتخيلت زوجتي أمامي وأنا بالعراق ثم انفعلت بغضب وقلت: أنت طالق ثلاث مرات، فهل يقع الطلاق في مثل هذه الحالة التي يسميها علم النفس: أحلام اليقظة أفيدونا أفادكم الله؟","title":"حكم من تخيل زوجته أمامه فطلقها ثلاثاً","answer":"الجواب: إذا كان المتكلم بهذا عقله معه فإنه يقع الطلاق ولو كانت غائبة؛ فإنه تخيلها وقال: أنت طالق أنت طالق أنت طالق، يتخيلها في نفسه ويتصورها أمامه، أو قال: هي طالق هي طالق، أو فلانة طالق طالق يقع الطلاق، لكن على حسب ما وقع منه إن كان وقع له مرة فهي مرة، إن كان مرتين فمرتين، إن كان ثلاث فثلاث، فإذا قال: أنت طالق أنت طالق أنت طالق أو هي طالق هي طالق هي طالق وقع ثلاث، إلا أن يريد التأكيد ما أراد إيقاع الثلاث، كررها للتأكيد تأكيد الكلام فقط ما أراد الثلاث فهو على نيته، لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئٍ ما نوى فهو على نيته، وأما إن كان قاله وليس له نية أو أراد الثلاث فإنها تقع الثلاث، إلا إذا كان شعوره غائباً قد فقد الشعور هذا شيء آخر، وأما ما دام شعوره معه وعقله معه فإنه يقع. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير!","link":"https://binbaz.org.sa/fatwas/6921/حكم-من-تخيل-زوجته-امامه-فطلقها-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21803.mp3","categories":["الطلاق"]},{"id":8773,"question":"هذه رسالة وردتنا من السائل أحمد سيد حزين من جمهورية مصر العربية ومقيم بالعراق يقول: أقسمت على زوجتي طلاق بالثلاث بأن تخرج من منزلي وتكون علي حرام كأمي وأختي مع سبق النية بأن أطلقها، وفعلاً خرجت من المنزل وذهبت إلى أهلها، وبعد فترة من الزمن عادت إلى المنزل بواسطة الأهل وبدون علمي وإلى الآن لم أعاشرها معاشرة الأزواج، أفيدوني أفادكم الله؟","title":"حكم من طلق بالثلاث وظاهر في نفس الوقت","answer":"الجواب: ما دمت قصدت بهذا طلاقها وفراقها فإن هذا الطلاق يقع به واحدة، إذا كان بهذا اللفظ الذي قلته، قلت: طالق بالثلاث يقع به واحدة على الصحيح من أقوال العلماء، ولك الرجوع إليها ما دامت في العدة، تقول: راجعت زوجتي فلانة ويكفي هذا، والسنة أن يكون بحضرة شاهدين، تقول هذا الكلام بحضرة شاهدين من أخيار المسلمين، تقول: راجعت زوجتي فلانة ويكفي، إذا كنت ما طلقتها قبل هذا طلقتين.. إذا كان ما سبق منك شيء قبل هذا من طلاق مرتين، فإن هذا يكون واحدة، فإن كان سبق منك واحدة قبل هذا يكون هذه ثانية ولك المراجعة، فإن كان سبق منك طلقتان فهذه تكون الثالثة ولا رجعة ما دمت أردت بهذا طلاقها وفراقها بالكلية وإخراجها من بيتك مطلقة، ومتى رجعت إليك لأن هذا الطلاق ما قبله طلقتان فإن عليك أيضاً كفارة الظهار؛ لأنك حرمتها أيضاً، فعليك مع ذلك كفارة الظهار قبل أن تقربها قبل أن تمسها، وكفارة الظهار هي: عتق أمة أو عبد إذا تيسر ذلك لوجه الله، فإن لم تستطع ذلك تصوم شهرين متتابعين عن هذا الظهار، فإن لم تقدر على ذلك لظروفك فعليك أن تطعم ستين مسكيناً، عليك عند العجز عن الصيام إطعام ستين مسكيناً، أي: ستين فقير من فقراء المسلمين تعطيهم ثلاثين صاع كل صاع بين اثنين، والصاع أربع حفنات باليدين الممتلأتين المعتدلتين كل حفنة مد، والأربع صاع بصاع النبي عليه الصلاة والسلام ملء اليدين المعتدلتين المملوءتين وهو معروف، أو تكسوهم كسوة كل واحد يعطى قميص أو إزار ورداء، أو تعتق عبد أو عبدة، لكن تقدم إذا عجزت عن..، المقصود في هذا ما فيه إلا الإطعام ما فيه كسوة الكسوة هذا في كفارة اليمين، المقصود عليك في هذا إطعام ستين مسكين كل مسكين له نصف الصاع فقط، ومقداره بالوزن كيلو ونصف تقريباً من قوت البلد من تمر أو أرز أو حنطة أو ذرة إن كانت قوت البلد أو شعير إن كانت كان قوت البلد يكفي هذا، قبل أن تمسها قبل أن تقربها إذا عجزت عن الصيام وعن العتق، هذا عن الظهار، أما الطلاق فعرفت أن عليك أنه يقع طلقة واحدة ولك مراجعتها في حال عدتها، فإن كانت قد خرجت من العدة فلا بد من نكاح جديد بالشروط المعتبرة شرعاً. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6925/حكم-من-طلق-بالثلاث-وظاهر-في-نفس-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21807.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":8888,"question":"سؤاله الثاني: هل المطلقة التي طلقها زوجها وهي في عذرها أو في طهر مسها فيه هل يقع هذا الطلاق أو لا؟","title":"هل يقع الطلاق للحائض والنفساء؟","answer":"الجواب: إذا طلق الزوج المرأة في حال الحيض، أو في حال النفاس أو في حال طهر جامعها فيه وليست حاملاً ولا آيسة اختلف العلماء في ذلك؛ فالجمهور على أنه يقع الطلاق مع أنه بدعة ومنكر لا يجوز؛ لأن الرسول ﷺم أنكر على ابن عمر لما طلق امرأته وهي حائض، أنكر عليه النبي ﷺ وأمره أن يمسكها حتى تحيض ثم تطهر، ثم يطلق بعد ذلك، أمره أن يمسكها حتى تطهر من حيضها الذي وقع فيه الطلاق ثم تحيض مرة أخرى ثم تطهر، ثم قال: إن شاء طلق وإن شاء أمسك وقال ﷺ: فتلك العدة التي أمر الله أن تطلق عليها النساء.\nفالجمهور ذهبوا إلى أن الطلاق وقع ولكنه مأمور بأن يراجعها إذا كان الطلاق طلقة واحدة أو طلقتين يراجعها ويبقيها كما قال النبي ﷺ: حتى تطهر ثم تحيض ثم تطهر، ثم إن شاء طلق وإن شاء أمسك قبل أن يمس، إن شاء طلق قبل أن يمس وإن شاء أبقاها، هذا هو المعروف عند جمهور أهل العلم، وذهب آخرون من أهل العلم وهو مروي عن طاوس وخلاس بن عمرو وجماعة وهو ثابت عن ابن عمر أن الطلاق في الحيض لا يقع، وأن الرسول ﷺ ردها عليه من دون احتساب الطلاق عليه، وإنما حسبها هو ابن عمر اجتهاداً منه حسب الطلقة، ولكن لم يحسبها عليه النبي ﷺ وقال هؤلاء: إن هذا الطلاق بدعة منكر فلا يقع لقول النبي ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد ، وهذا طلاق ليس عليه أمر النبي ﷺ فلا يقع، وهذا هو اختيار أبي العباس ابن تيمية تلميذه العلامة ابن القيم رحمة الله عليهما واختيار جماعة من أهل العلم وهو أظهر في الدليل وأقوى في الدليل؛ لأن رسول الله أنكر على ابن عمر وأغلظ في ذلك عليه الصلاة والسلام، وأمره أن يمسكها حتى تحيض ثم تطهر، ثم قال: إن شاء طلق، وإن شاء أمسك، إن شاء طلق قبل أن يمس وإن شاء أمسكها، وفي لفظ: ثم ليطلقها طاهراً أو حاملاً.\nالمقدم: معنى هذا أن الطلاق السابق لم يقع؟\nالشيخ: نعم، هذا على أنه لم يقع؛ لأن إيقاعه ثم ردها تكثير للطلاق، كونه يوقع الطلاق الأول ثم يأمره بإطلاقها مرة أخرى معناه التكثير للطلاق، فالشارع يتشوف لقلته لا لكثرته، فالحاصل أن قوله: فليراجعها ليس معناه الرجعة المعروفة التي هي الرجعة بعد الطلاق وإنما المراد عند هؤلاء يعني فليردها، أن يردها إلى نفقته عليها وإلى حباله وإلى كونها عنده حتى تطهر من حيضتها التي طلقها فيها ثم تحيض مرة أخرى ثم تطهر، ثم بعد هذا إن شاء طلق وإن شاء أمسك، قال النبي ﷺ: فتلك العدة التي أمر الله أن تطلق عليها النساء، يعني في قوله سبحانه: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] الآية، قال العلماء: معنى ذلك طاهرات من غير جماع، هذه معنى: (طلقوهن لعدتهن) يطلقن طاهرات من غير جماع أو في حال الحمل، كما في حديث ابن عمر: فليطلقها طاهراً أو حاملاً.\nوهذا القول أظهر في الدليل؛ لأنه موافق لحديث ابن عمر وموافق للآية الكريمة، ولما ذكره أهل العلم في تفسيرها وإن كان خلاف الأكثرين، لكن المعول في المسائل هو ما يقرب من الدليل وما يقتضيه الدليل، ثم هو أرفق بالأمة وأنفع للأمة؛ لأن كثيراً من الناس يغضب ويطلق في الحيض والنفاس وفي طهر جامع فيه، فإذا ردت عليه ففيه جمع الشمل وجمع الأسرة وربما كان لديهما أولاد فيجمع الشمل بينهم وبين أولادهما.\nفالحاصل والخلاصة: أن هذا مع كونه أظهر في الدليل هو أرفق بالأمة، والله يقول سبحانه: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]، ويقول جل وعلا: وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ هُوَ اجْتَبَاكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]، ويقول النبي ﷺ: يسروا ولا تعسروا.\nفالتيسير للأمة والتسهيل عليها مهما أمكن مطلوب، وهو أقرب إلى قواعد الشرع التي جاءت بالتيسير والتسهيل والرحمة وما أكثر ما يقع الطلاق من الناس في حال الغضب الشديد، وفي حال الحيض وفي حال النفاس وفي حال الطهر الذي جامع فيه ثم يندم الجميع، ففي هذا القول رحمة للأمة وجمع للشمل، وتيسير للأمور وتقليل للفرقة، ولا يخفى على كل من له أدنى خبرة بأحوال الناس ما يترتب على الطلاق من شر عظيم في الغالب وفرقة للأولاد مع والديهم، وضياع بعض الأحيان للأولاد ومتاعب كثيرة للأب والأم جميعاً والأولاد، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً ونفع بكم.","link":"https://binbaz.org.sa/fatwas/7044/هل-يقع-الطلاق-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14002.mp3","categories":["الطلاق"]},{"id":8890,"question":"يقول أخونا: ماذا نقول للذين يرون أن الطلاق لا يقع بمجرد اللفظ به إذا لم يشهد على الطلاق شاهدا عدل، ويجوز في نظرهم متابعة الحياة الزوجية بما فيها كما لو لم يقع أي شيء، ويعتمدون في فهمهم وحكمهم على قول عطاء رحمه الله تعالى وهو: أنه لا يجوز في نكاح ولا طلاق ولا جماع إلا شاهدا عدل؟","title":"حكم الطلاق دون إشهاد","answer":"الجواب: الذي عليه أهل العلم أن الطلاق يقع ولو لم يشهد، إنما الإشهاد سنة، والله  أخبر عن الطلاق في آيات كثيرات ولم يشترط سبحانه الإشهاد، وهكذا نبيه ﷺ، يروى عن عمران بن حصين  أنه قال: أشهد على طلاقها وعلى رجعتها وقال: من طلق في غير إشهاد فقد طلق بغير السن.\nفهذا يستدل به ويحتج به على أن المشروع أن يشهد على الطلاق؛ لأنه قد يطلق وينكر، فإذا أشهد على الطلاق كان عوناً له على إثبات الحق وعلى عدم العودة إلى الباطل بإنكار الطلاق، فالإشهاد يعينه على أداء الحق ويثبت الحق للمرأة، فالسنة أن يشهد على الطلاق ويشهد على الرجعة، ويحتج على هذا أيضاً بقوله : وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ [الطلاق:2]، فإن هذا فسر بالإشهاد على الطلاق وفسر بالإشهاد على الرجعة، والآية تحتملهما فيشرع هذا وهذا، يشرع إشهاده على الطلاق ويشرع إشهاده على الرجعة، ولكن ليس ذلك بشرط، فالرجعة صحيحة وإن لم يشهد عليها إذا اعترفت بها الزوجة وأسمعها الرجعة في العدة.\nوكذلك الطلاق يقع وإن لم يشهد لكنه خالف المشروع، خالف ما ينبغي. نعم.\nالمقدم: بارك الله فيكم. إذاً: قول أولئك خاطئ؟\nالشيخ: نعم، الأظهر خلافه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7046/حكم-الطلاق-دون-اشهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14003.mp3","categories":["الطلاق"]},{"id":8906,"question":"نعود في بداية هذا اللقاء إلى رسالة الأخ آدم محمد عثمان، السوداني والمقيم بالعراق، أخونا يسأل في هذه الحلقة ويقول: يوجد بعض من الناس عندما يطلق زوجته يقول: أنت في مكان والدتي، فما حكمه إذا أرجعها، وهل يحق له رجوعها أو لا؟","title":"حكم من قال لزوجته عند تطليقها: (أنت في مكان والدتي)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا كان الطلاق رجعيًا، إن كان طلقها طلقة واحدة أو طلقتين فله مراجعتها ما دامت في العدة، فإذا خرجت من العدة قبل أن يراجعها جاز له أن يعود إليها بنكاح جديد بالشروط المعتبرة شرعًا من الولي والشاهدين، والرضا كما هو معلوم.\nأما قوله: أنت في مكان والدتي، بعدما طلقها، هذا يرجع إلى نيته، إن كان قصده من ذلك: أنها عنده عزيزة، وكريمة وأنه يقدرها، هذا ليس بشيء ولا حرج فيه وليس من الظهار في شيء، يعني: عبارة موهمة.\nأما إن كان قصده (أنت في مكان والدتي)، يعني: أنت محرمة علي، وأنت علي حرام كوالدتي، فهذا يسمى الظهار، ولا تحل له إذا كان الطلاق رجعيًا إلا بعد الكفارة، لا يمسها ولو راجعها، يراجعها لا بأس أو يعقد عليها إذا كانت قد خرجت من العدة، لا بأس، لكن لا يمسها حتى يكفر كفارة الظهار وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، كل صاع يقسم بين اثنين، كل واحد له نصف الصاع من التمر، من الرز، من الحنطة، من قوت البلد، هذا هو الواجب، وليس له أن يمسها حتى يخرج هذه الكفارة، بعدما يراجعها أو بعدما يعقد عليها ليس له أن يمسها يعني: ليس له أن يجامعها إلا بعدما يخرج هذه الكفارة.\nأولًا: رقبة -عتق رقبة مؤمنة- إن قدر.\nثانيًا: صيام شهرين متتابعين، إذا عجز عن الرقبة.\nثالثًا: أن يطعم ستين مسكينًا ثلاثين صاعًا من قوت البلد، إذا عجز عن الصيام، ثم بعد هذا له أن يباشرها.\nأما إن كان الطلاق كاملًا، طلقها الطلقة الأخيرة -الثالثة- فهذه لا تحل له حتى تنكح زوجًا غيره، حتى تنكح زوجًا آخر نكاحًا شرعيًا لا نكاح تحليل، وحتى يطأها أيضًا الزوج الثاني، فإذا طلقها الطلقة الأخيرة-الثالثة- فإنها تحرم عليه تحريمًا مؤقتًا مادامت لم تتزوج، فإذا تزوجت زواجًا شرعي ووطئها الزوج الجديد ثم طلقها أو مات عنها فإنها تحل للأول، إذا كان النكاح شرعي مو بنكاح تحليل، أما نكاحها للتحليل ليحللها للأول هذا نكاح باطل لا يجوز، لكن إذا تزوجها الزوج الجديد بنية الرغبة فيها لكن لم يقدر الله له الرغبة بل طلقها بعد الدخول بها، أي: بعد أن جامعها أو مات عنها، فإنها تحل للأول بعقد جديد، ........... جديد بشروطه المعتبرة شرعًا.\nوإذا كان قال لها بعدما طلقها الطلقة الأخيرة: أنت في مكان أمي، فهذا لا يؤثر شيء، ولو كان أراد التحريم، لأنها صارت أجنبية، صارت أجنبية ما يكون تحريمها تحريم الظهار، إذا كانت بعد الطلقة الأخيرة، قال: أنت في مكان أمي، قصده تحريمها، قصده أن ينوي هذا تحريمها، أو قال: أنت كظهر أمي، أو أنت محرمة علي، فإنه لا يلحقها هذا كالزوجة، ولكن يجب فيه كفارة يمين، مثل: تحريم الطعام والشراب ونحو ذلك، لأنها صارت أجنبية بعد الطلقة الأخيرة، فإذا قال لها: أنت محرمة علي، أو أنت علي كظهر أمي، بعد الطلاق الأخير، فإنها تكون في حكم تحريم الطعام واللباس والشراب، يعني: يستحلها بكفارة اليمين، كفارة يمين ويكفي، إطعام عشرة مساكين أو كسوتهم، ولا يكون ظهارًا؛ لأن الظهار إنما يكون مع النساء مع الزوجات، كما قال تعالى: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3] هي بعد الطلقة الأخيرة ما عاد صارت من النساء، صارت أجنبية، فيكون تحريمه لها مثل تحريم الثياب والطعام ونحو ذلك والجواري فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7062/حكم-من-قال-لزوجته-عند-تطليقها-انت-في-مكان-والدتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/16901.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":8995,"question":"يسأل سماحة الشيخ عن طلاق الغضبان؟","title":"هل يقع طلاق الغضبان؟","answer":"الجواب: الغضبان له ثلاث حالات:\nإحداها: أن يزول عقله بسبب شدة الغضب فلا يميز ولا يضبط ما يقول، فهذا لا يقع طلاقه كالمجنون.\nالحال الثاني: أن يشتد معه الغضب حتى لا يستطيع أن يملك نفسه بسبب شدة الغضب، أو مسابة أو مضاربة، أسباب واضحة تجعله يشتد غضبه، هذه الحالة اختلف فيها العلماء، فمنهم من أوقع الطلاق فيها، ومنهم من لم يوقعه وألحقها بالأولى، وهذا هو الأظهر والأقرب أنها تلحق بالأولى إذا اتضحت أسباب شدة الغضب، فإن بعض الناس يدعي شدة الغضب وليس هناك أسباب توجب شدة الغضب، لكن متى اتضحت الأسباب كالمضاربة بين الشخصين، أو بين الرجل وزوجته، أو بينه وبين أبيها أو أخيها ونحو ذلك، والمسابة والمشاتمة التي يظهر منها شدة الغضب ويتضح منها شدة الغضب وتصدقه المرأة، أو الحاضرون يصدقون في ذلك، فهذا لا يقع على الصحيح، أما مجرد دعوى شدة الغضب من دون دليل ولا بيان ما يكفي.\nالحال الثالثة: الغضب الذي ليس بشديد؛ العادي، هذا يقع الطلاق فيه عند جميع العلماء، وهو الغضب العادي الذي ليس هناك فيه شدة واضحة، فهذا عند جميع أهل العلم يقع فيه الطلاق. نعم.","link":"https://binbaz.org.sa/fatwas/7153/هل-يقع-طلاق-الغضبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17606.mp3","categories":["الطلاق"]},{"id":9114,"question":"والدي حلف يمين على عدم إدخال الفيديو في البيت، ونظرًا لحالتي فقد أدخلت الفيديو دون علمه، ما الحكم، انصحوني جزاكم الله خيرًا؟","title":"حكم مخالفة الابن لأبيه في عدم إدخال الفيديو البيت","answer":"الجواب: أولًا: أنت عاصٍ في هذا الحال؛ لأن الواجب عليك طاعة والدك في المعروف، وهذا من المعروف والفيديو لا يأتي بخير لا يأتي إلا بالشر؛ لأن الغالب على الفيديو أن يكون فيه الصور الخليعة والأغاني والملاهي، فليس لك أن تدخله حتى ولو كان سليمًا عليك أن تطيع والدك، من باب سد الذريعة، فأنت عاصٍ بهذا وعليك التوبة إلى الله وإخراج الفيديو، والوالد ليس عليه كفارة؛ لأنه لم يعلم، لكن أنت العاصي وأنت الذي عليك التوبة إلى الله وإخراج الفيديو من البيت طاعة لأبيك وحذرًا من شر الفيديو؛ لأنه في الغالب لا يسلم من أن يكون فيه ما يغضب الله من الصور الخليعة والكلام المحرم والأغاني المنكرة ونحو ذلك، نسأل الله لنا ولك الهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/7274/حكم-مخالفة-الابن-لابيه-في-عدم-ادخال-الفيديو-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17908.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9124,"question":"هذه رسالة وصلت إلى البرنامج من المنطقة الشرقية وباعثها أحد الإخوة من هناك يقول: سيد (ع. ع. ع) أخونا يقول في رسالته: في مرة من المرات حلفت على زوجتي وقلت: إذا استعملت أي نوع من العطور أو الحناء والتي تستعمل بالعطور أو جاملت بها لإحدى النساء، وذلك أثناء وجودي بالشقة التي نسكنها فإنك تكوني طالق، ولم أتخذ هذا القرار إلا بعد جهد وتكرار ومحاولات لإقناعها لتترك استعمالها أثناء وجودي، حيث أن هذه العطور والروائح تسبب لي صداع ومضايقات شديدة، علمًا بأن الشقة لا تتسرب منها رائحة العطور بسرعة، وبعد مضي عدة أشهر نسيت زوجتي بهذا الحلف وأخذت زجاجة عطر وفتحتها وأدخلت أصبعها داخل الزجاجة ومسحت بها، وبعد ذلك تذكرت بالحلف وأسرعت إلى مكان آخر وأخبرتني بذلك، علمًا بأنني كنت نائم داخل المنزل، أرجو من سماحتكم إفادتي عما حدث مني جزاكم الله خيرًا؟","title":"حكم من حلف بالطلاق على امرأته أن تفعل كذا وفعلته","answer":"الجواب: إذا كانت المرأة فعلت ذلك نسيانًا كما قلت في السؤال فليس عليك شيء وليس عليها شيء، يقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، وصح عن رسول الله عليه الصلاة والسلام أن الله قال: قد فعلت، فالناسي ليس عليه شيء والحمد لله، أما إن تعمدت ذلك وأنت تقصد منعها ولا تقصد فراقها وإنما قصدت منعها وتخويفها، فإذا فعلت ذلك عمدًا فعليك كفارة يمين ولا يقع الطلاق إذا كان المقصود منعها وتخويفها وتحذيرها، أما إن كان المقصود إيقاع الطلاق إذا فعلت، فإنها إذا فعلت ذلك عمدًا يقع طلقة واحدة بهذا الكلام الذي قلت، وإن كان عن نسيان فإنه لا يقع شيء والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7284/حكم-من-حلف-بالطلاق-على-امراته-ان-تفعل-كذا-وفعلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17910.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9132,"question":"وهذه رسالة وصلت إلى البرنامج من الأخ (محمود . ع) من الكويت الجهرة، يقول في رسالته وفي بدايتها: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، تحية طيبة مباركة أتقدم بها إلى الأفاضل المشايخ في برنامج نور على الدرب، أنا شاب مصري أعمل بالكويت واسمي محمود ذهبت إلى مصر لقضاء إجازتي، وفي أثناء وجودي في البلدة حصل حوار بيني وبين زوجتي وغضبت منها غضباً شديداً فقلت: علي الطلاق تكوني خالصة لو ذهبت إلى البلدة التي يعيش فيها أهلها، وأقصد بذلك بيت أهلها، فبعد سفري إلى الكويت مرة ثانية أرسلت لي خطاباً تقول: أريد أن أذهب إلى بيت أهلي، وتقصد أنها كانت متضايقة مما قلته لها، فوافقت وبعثت إليها بخطاب بالموافقة وأنا ما زلت في الكويت وذهبت بموافقتي، هل اليمين يكون واقعاً، علماً أنني حلفت اليمين وأقصد به تخويفها ولم أشعر باليمين، هل علي كفارة يمين أم اليمين واقعة، وإذا كان علي كفارة يمين هل أدفعها لعشرة أفراد أم أدفعها لفرد واحد، وإذا كانت تقدر بالدينار كما عندنا في الكويت أدفع كم دينار أفيدونا أفادكم الله؟","title":"حكم الحلف بالطلاق بنية المنع والتخويف","answer":"الجواب: إذا كان الواقع كما ذكرت وأنك طلقت عليها أن لا تذهب لأهلها بقصد تخويفها ومنعها لا لقصد إيقاع الطلاق فإنه لا يقع الطلاق؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى، فما دمت حين منعتها من أهلها أو طلقت على ذلك أردت بذلك منعها وتخويفها لا إيقاع الطلاق عليها إن ذهبت فإنه عليك كفارة يمين فقط، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من التمر أو من الرز أو غيرهما من قوت البلد، عشرة لا يعطاها واحد بل لا بد من عشرة ولا بد من طعام ولا تجزي النقود لا دينار ولا غيره، الواجب إخراجها من الطعام تعشيهم في بيتك أو تغديهم ولو متفرقين ولو اثنين اثنين واحد واحد حتى تكمل العشرة، أو تعطيهم الطعام بأيديهم نصف صاع كيلو ونصف من التمر من الأرز من الحنطة يعني: من قوت البلد ويكفي ذلك والحمد لله ولا يقع الطلاق.\nوإن كنت أردت بهذا الكلام إلا بإذنك أنها لا تخرج إليهم إلا بإذنك، ناوي هذا ناوي الإذن ثم أذنت لها فلا شيء عليك لا كفارة ولا غيرها، إذا كنت نويت بإذنك يعني: ليس لكي الخروج إلى أهلك والذهاب إلى أهلك إلا بإذني هذا نيتك وأنك متى أذنت فلا شيء فقد أذنت لها ولا يقع شيء الحمد لله، أما إذا كنت ما نويت الإذن بأن قلت: عليك الطلاق ألا تذهبي لأهلك وإذا ذهبت فأنت طالق وقصدك منعها وتخويفها فإنها بهذا الإذن يباح لها أن تذهب إلى أهلها وعليك الكفارة المذكورة وهي كفارة يمين وهي إطعام عشرة مساكين عشرة فقراء. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7293/حكم-الحلف-بالطلاق-بنية-المنع-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22906.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9152,"question":"السؤال الثاني في رسالة الأخ (م. ج) سوريا الرقة يقول فيه: عندنا الكثير من الناس يحلفون بغير الله، فهل هذا جائز؟ مثلاً يقولون: وحياة النبي محمد عليه الصلاة والسلام، وحياة عيسى أو موسى عليهما السلام، أو وحياة القرآن، أو وحياة قبر أبوي، أو أقسم في شرفي. أفيدوني بهذا جزاكم الله خير الجزاء.","title":"حكم الحلف بالأنبياء والآباء والشرف والقرآن","answer":"الجواب: الحلف بغير الله لا يجوز، بل يجب أن يكون الحلف بالله وحده سبحانه وتعالى؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: من كان حالفاً فلا يحلف إلا بالله أو ليصمت، وقال عليه الصلاة والسلام: من حلف بغير الله فقد أشرك وفي اللفظ الآخر: فقد كفر وفي اللفظ الآخر: فقد كفر أو أشرك، فالحلف بغير الله من المحرمات الكفرية، ولكنه من الشرك الأصغر؛ إلا إذا قصد أن محلوفه عظيم كعظمة الله أو أنه يتصرف في الكون أو أنه يصلح أن يدعى من دون الله صار كفراً نعوذ بالله، فإذا قال: وحياة فلان أو وحياة الرسول أو وحياة عيسى أو وحياة موسى أو شرفي أو قبر أبي أو ما أشبه ذلك كله حلف بغير الله كله لا يجوز، أو حلف بالأمانة أو بالكعبة كل ذلك منكر. الواجب أن لا يحلف إلا بالله وحده سبحانه وتعالى أو بصفة من صفاته أو باسم من أسمائه عز وجل، والقرآن من كلام الله، القرآن من صفات الله، فإذا قال: والقرآن أو وحياة القرآن هذا لا بأس لأن القرآن كلام الله سبحانه وتعالى، فإذا حلف بالقرآن أو قال: بعزة الله أو بعلم الله أو بحياة الله فلا بأس، صفات الله يقسم بها، لكن المخلوقون لا لا يقسم بمخلوق، لا بالنبي صلى الله عليه وسلم وهو أشرف الخلق ولا بالكعبة ولا بالأمانة ولا بحياة فلان ولا شرف فلان ولا غير ذلك؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وحذر منه عليه الصلاة والسلام، وقال ابن عبد البر الإمام المشهور رحمه الله: أجمع العلماء على أنه لا يجوز الحلف بغير الله.\nفيجب على المؤمن أن يحذر هذه الأيمان الباطلة، وأن يحذر إخوانه من ذلك، وأن يدعوهم إلى أن يحلفوا بالله وحده . نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7310/حكم-الحلف-بالانبياء-والاباء-والشرف-والقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23102.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":9168,"question":"السؤال الثاني في رسالة الأخ (م. ج) سوريا الرقة يقول فيه: عندنا الكثير من الناس يحلفون بغير الله، فهل هذا جائز؟ مثلاً يقولون: وحياة النبي محمد عليه الصلاة والسلام، وحياة عيسى أو موسى عليهما السلام، أو وحياة القرآن، أو وحياة قبر أبوي، أو أقسم في شرفي. أفيدوني بهذا جزاكم الله خير الجزاء.","title":"حكم الحلف بالأنبياء والآباء والشرف والقرآن","answer":"الجواب: الحلف بغير الله لا يجوز، بل يجب أن يكون الحلف بالله وحده سبحانه وتعالى؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: من كان حالفاً فلا يحلف إلا بالله أو ليصمت، وقال عليه الصلاة والسلام: من حلف بغير الله فقد أشرك وفي اللفظ الآخر: فقد كفر وفي اللفظ الآخر: فقد كفر أو أشرك، فالحلف بغير الله من المحرمات الكفرية، ولكنه من الشرك الأصغر؛ إلا إذا قصد أن محلوفه عظيم كعظمة الله أو أنه يتصرف في الكون أو أنه يصلح أن يدعى من دون الله صار كفراً نعوذ بالله، فإذا قال: وحياة فلان أو وحياة الرسول أو وحياة عيسى أو وحياة موسى أو شرفي أو قبر أبي أو ما أشبه ذلك كله حلف بغير الله كله لا يجوز، أو حلف بالأمانة أو بالكعبة كل ذلك منكر. الواجب أن لا يحلف إلا بالله وحده سبحانه وتعالى أو بصفة من صفاته أو باسم من أسمائه عز وجل، والقرآن من كلام الله، القرآن من صفات الله، فإذا قال: والقرآن أو وحياة القرآن هذا لا بأس لأن القرآن كلام الله سبحانه وتعالى، فإذا حلف بالقرآن أو قال: بعزة الله أو بعلم الله أو بحياة الله فلا بأس، صفات الله يقسم بها، لكن المخلوقون لا لا يقسم بمخلوق، لا بالنبي صلى الله عليه وسلم وهو أشرف الخلق ولا بالكعبة ولا بالأمانة ولا بحياة فلان ولا شرف فلان ولا غير ذلك؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وحذر منه عليه الصلاة والسلام، وقال ابن عبد البر الإمام المشهور رحمه الله: أجمع العلماء على أنه لا يجوز الحلف بغير الله.\nفيجب على المؤمن أن يحذر هذه الأيمان الباطلة، وأن يحذر إخوانه من ذلك، وأن يدعوهم إلى أن يحلفوا بالله وحده . نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7310/حكم-الحلف-بالانبياء-والاباء-والشرف-والقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23102.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":9177,"question":"أولى قضايا هذه الحلقة شيخ عبدالعزيز قضية تتعلق بالطلاق، صاحب القضية يقول: طلقت ثلاث مرات؛ المرة الأولى وكانت الزوجة حامل وراجعتها وهي عندي وتمت المراجعة في نفس اليوم الذي كان فيه الطلاق، والمرة الثانية كانت حائض وراجعتها أيضًا في نفس اليوم وهي عندي وكان الطلاق مرتين. له منها الآن خمسة عيال وهي عنده في البيت ويشكو من مرض يسيطر عليه ويقول: لو سئل عن حالته العقلية أثناء الطلاق لقال: إنه مختل الشعور. يرجو من سماحة الشيخ إرشاده جزاكم الله خيرًا؟","title":"حكم طلاق الحامل والحائض","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله  شرع الطلاق لمصالح كثيرة قد يحتاجها الزوج وقد تحتاجها الزوجة، فمن نعمته سبحانه أن شرع الطلاق حيث قال جل وعلا: الطَّلاقُ مَرَّتَانِ فَإمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ [البقرة:229] الآية. فإذا احتاج المسلم للطلاق لكون المرأة لم تناسبه أو لأسباب أخرى تقتضي الطلاق شرع له أن يطلق طلقة واحدة فقط، هذا هو السنة طلقة واحدة فقط؛ لأنه قد يبدو له أن يراجع فإذا هو في سعة، فيطلق واحدة فقط في طهر لم يجامع فيه، أو في حال الحمل، لقوله سبحانه: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] قال علماء التفسير: معناه طاهرات من غير جماع، يعني في حال الطهر من حيض أو نفاس وقبل أن يمسها، أو في حال الحمل، كما ثبت في الصحيح من حديث ابن عمر رضي الله تعالى عنهما أن النبي ﷺ قال له لما طلق امرأته وهي حائض: راجعها ثم أمسكها حتى تطهر ثم تحيض ثم تطهر ثم إن شئت طلقها قبل أن تمسها، فتلك العدة التي أمر الله أن تطلق لها النساء، وفي لفظ قال: ثم ليطلقها طاهرًا أو حاملًا فهذا هو المشروع أن يطلق الزوج امرأته إذا احتاج إلى ذلك طلقة واحدة في إحدى حالين:\nإما في حال كونها حاملًا أو في حال كونها طاهرة في طهر لم يجامعها فيه وهي حائل هذا هو الطلاق الشرعي، ويكره أن يطلق ثنتين من دون حاجة بل يطلق واحدة فقط، ولا يجوز له أن يطلقها في حال الحيض ولا في حال النفاس، ولا في حال طهر جامعها فيه؛ لأن الرسول ﷺ أنكر على ابن عمر ذلك وجعل هذا من تفسير قوله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] المعنى: في طهر لم يجامعها فيه، فعلم بهذا أن الطلاق في حيض أو نفاس أو في طهر جامعها فيه يخالف نص الآية الكريمة، ويخالف التعليم النبوي الذي وجهه ﷺ لـابن عمر وهو للأمة كلها؛ لأن تعليمه ﷺ للواحد تعليم للأمة كلها.\nثم اختلف العلماء في وقوعه هل يقع إذا كان في حال لا يشرع فيها كالحيض والنفاس والطهر الذي جامعها فيه، فذهب جمهور أهل العلم وأكثرهم إلى أنه يقع مع الإثم، يأثم الزوج ويقع الطلاق، وذهب جمع من أهل العلم إلى أنه لا يقع؛ لأنه طلاق غير مشروع فلا يقع، لقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد وهذا عمل ليس عليه أمر النبي ﷺ فيكون مردودًا، ولأن الرسول ﷺ رد المرأة على ابن عمر لما طلقها وهي حائض ردها عليه النبي ﷺ ولم يرها شيئًا، كما ثبت في الصحيح، وقال: فإذا طهرت فليطلق أو ليمسك، وسئل ابن عمر عن ذلك  فقال: لا يعتد بها مع أنه  حسب ما وقع من تطليق حسبها اجتهادًا منه، حسب ما وقع من تطليقة ولم يحسبها عليه النبي عليه الصلاة والسلام.\nوهذا القول أرجح من حيث الدليل، أنه لا يقع الطلاق في حال الحيض والنفاس ولا في طهر جامعها فيه، وإن كان خلاف قول الجمهور لكنه أظهر في الدليل، والأصل بقاء النكاح وعدم وقوع الطلاق الذي لم يشرع، فالله  شرع لعباده ما فيه مصلحتهم ونهاهم عما يضرهم، ولا ريب أن وقوع الطلاق في حال الحيض والنفاس وفي الطهر الذي جامعها فيه يضر الزوج ويضر المرأة في الغالب، فكان من محاسن الإسلام ومن رحمة الله  القول بأنه لا يقع، قال من لم يوقعه: ومما يؤيد ذلك أن الإنسان في حال كون امرأته حائضًا أو نفساء يسهل عليه الطلاق؛ لأنها لا تصلح للجماع، وممنوع من جماعها فيسهل عليه الطلاق، وهكذا إذا كان قد قضى وطره وجامعها يسهل عليه الطلاق، فمن رحمة الله أن منعه من ذلك وحرم عليه ذلك، فمتى أقدم على التحريم لم يقع منه ذلك لكونه خلاف أمر الله.\nوهذا السائل طلق الأولى وهي حامل فالطلاق واقع لأن طلاق الحامل أمر مشروع، أما الطلاق الثاني إذا كان في الحيض باتفاقهما واعترافهما جميعًا فإنه لا يقع على الصحيح، إلا أن يحكم حاكم بذلك فإن حكم حاكم بوقوعه وقع ؛ لأن حكم الحاكم يرفع الخلاف، فإذا حكم الحاكم ممن يرى إيقاع الطلاق كما هو قول الجمهور فحكم عليه بوقوع الطلاق فإنه يرتفع الخلاف ويقع الطلاق وينفذ وليس لأي مفتي أن ينقض ذلك؛ لأن المسألة خلافية يسوغ فيها الاجتهاد.\nأما كونه مختل الشعور فهذا يحتاج إلى أن يستفتي قاضي بلده إذا وقع منه شيء يستفتي قاضي بلده حتى ينظر في الأمر، وحتى يطالب بالبينة الدالة على ما قاله، فليس كل من ادعى شيئًا يسلم له، يقول المصطفى عليه الصلاة والسلام: لو يعطى الناس بدعواهم لادعى ناس دماء رجال وأموالهم ولكن البينة على المدعي، فالذي يدعي أنه طلق في حال زوال عقله يطالب بالبينة على ما قال، وإذا ثبت ذلك لم يقع الطلاق، وإذا أقرت الزوجة بأنه وقع منه في حال غير شعورية كالسكران الذي طلق في حال غيبوبة عقله بتعاطيه ما حرم الله، فالصحيح أنه لا يقع كالمجنون، ولو كان آثمًا فإن الآثم عليه التوبة إلى الله وعلى ولي الأمر أن يقيم عليه الحد إذا رفع إلى ولي الأمر، وليس من عقوبة السكران إيقاع الطلاق.\nفالصواب الذي عليه المحققون من أهل العلم وبه أفتى الخليفة الراشد عثمان  أن طلاق السكران الذي قد فقد عقله لا يقع حتى ولو كان آثمًا، أما غير الآثم فلا يقع عند الجميع كالمجنون، فلو أن إنسانًا سقي ما يسكره ويغير عقله بغير علمه أو أجبر عليه وأكره عليه لم يقع طلاقه عند أهل العلم، وإنما الخلاف فيمن شرب السكر عمدًا، فهذا هو محل الخلاف فهو آثم ويجب أن يقام عليه الحد إذا رفع للسلطان، ولكن لا يقع الطلاق إذا كان في حال الطلاق فاقد العقل كالمعتوه والمجنون، والله المستعان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7337/حكم-طلاق-الحامل-والحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18001.mp3","categories":["الطلاق"]},{"id":9178,"question":"سماحة الشيخ إذا أذنتم لي أسأل بعض الأسئلة: هل يلزم المطلق أن يشهد أحدًا على طلاقه وعلى رجعته، أو يبقى ذلك بينه وبين زوجته وبين نفسه؟","title":"حكم الإشهاد على الطلاق والرجعة","answer":"الجواب: السنة أن يشهد، لقوله تعالى: وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ [الطلاق:2] فالسنة أن يشهد شاهدين؛ لأن الله جل وعلا قال في سورة الطلاق: وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ [الطلاق:2] قال بعض أهل العلم: المراد به الطلاق، وقال بعضهم: المراد به الرجعة، ولا مانع من كون الآية في الأمرين جميعًا فيشهد على طلاقها ويشهد على رجعتها، فإذا طلق أشهد حتى لا ينكر ذلك؛ فإن الشيطان قد يزين له الإنكار، فإذا أشهد كان هذا من أسباب السلامة والعافية من طاعة الشيطان في إنكار الطلاق، وهكذا الرجعة، عليه أن يشهد على رجعتها؛ لأنه قد يتأخر في إبلاغ الزوجة فيكون الشهود بينة له تعينه على حصول المطلوب من الرجعة.\nفالمقصود أنه يشهد على الطلاق والرجعة هذا هو المشروع. نعم.\nالمقدم: ومن لم يفعل هذا فعليه أن ...\nالشيخ: الطلاق واقع، والرجعة صحيحة إذا راجعها في العدة وأخبرها بذلك ولو لم يشهد صحت الرجعة؛ لأن الله قال: وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَلِكَ إِنْ أَرَادُوا إِصْلاحًا [البقرة:228]، ولم يقل بشرط كذا وكذا. نعم.\nالمقدم: طيب لكن عليه أن يتدارك الكتابة أو ليس عليه ذلك؟\nالشيخ: لا يلزمه فيما يظهر لكن لو فعل امتثالًا للأمر واحتياطًا حسن. نعم.","link":"https://binbaz.org.sa/fatwas/7338/حكم-الاشهاد-على-الطلاق-والرجعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18002.mp3","categories":["الطلاق","الظهار","الرجعة"]},{"id":9179,"question":"الرسالة التالية أيضًا عن موضوع الطلاق وباعثتها إحدى الأخوات أشارت إلى نفسها بقولها: بنت فلان، وبعثت رسالتها بهذا البريد الذي يسمونه البريد الممتاز، تقول: السلام عليكم ورحمة الله وبركاته، أرجو عرض رسالتي على سماحة الشيخ عبدالعزيز بن باز تقول: إنها فتاة متزوجة وحصل بيني وبين زوجي طلاق للمرة الأخيرة ثم سأل وأفتوه بأنه يجوز والطلاق لم يصح- هكذا تعبر سماحة الشيخ- لأنه في حالة غضب ورجعت مع زوجي واستمرت الحياة بيننا لمدة سنة، ثم عرفت أن الذي يفقد وعيه طلاقه لا يصح وزوجي لم يفقد وعيه، وبعدما عرفت ذهبت إلى أهلي ولم يكتب لي ورقة طلاق، وقال لي زوجي: لا يلزمك ورقة طلاق، ما دام عرفنا أن جلوسنا على غير صح، ثم قال لي: إذا أراد الله ثم تزوجتي وتطلقتي سوف أراجعك، وحصل أن تزوجت فعلًا وطلقت من زوجها الأخير واسترجعها، لكنها تشكو من الطريقة التي اعتدت بها حيث لم تمكث إلا عشرين يومًا في العدة، وترجو من سماحة الشيخ التوجيه جزاكم الله خيرًا؟","title":"حكم زواج المرأة قبل انتهاء عدتها","answer":"الجواب: الواجب ألا يتزوجها إلا بعد العدة، فإذا كان تزوجها وهي في عدة الزوج الثاني فالزواج باطل؛ لأن الله يقول: وَلا تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتَّى يَبْلُغَ الْكِتَابُ أَجَلَهُ [البقرة:235] يعني: حتى تنتهي من العدة، وهذا أمر أجمع عليه أهل العلم، فإذا تزوجت الزوج الثاني زواجًا شرعيًا ليس بقصد التحليل بل زواجًا شرعيًا، ووطئها الزوج الثاني فليس للزوج الأول أن يتزوجها إلا بعد خروجها من العدة بثلاث حيض إن كانت تحيض، أو بثلاثة أشهر إن كانت لا تحيض.\nوالحاصل أن الزواج هذا باطل إذا كان في العدة، وعليه أن يتجنبها ويصبر حتى تعتد فإذا اعتدت أعاد النكاح من جديد مع التوبة والاستغفار، عليهما التوبة جميعًا من الله سبحانه وتعالى، هذا إذا كانت الطلقة الأخيرة الثالثة لقد وقعت، وأما إن كانت لم تقع؛ لأنه حين الطلاق قد اشتد غضبه شدة واضحة بينة بأسباب النزاع الشديد أو المسابة أو المضاربة فإنها لا تقع على الصحيح ولا يحتاج إلى زواج ثاني.\nلكن مادامت تزوجت فليس له أن ينكحها إلا بعد خروجها من العدة؛ لأن الزوج الثاني له حرمته، وقد تزوجها زواجًا شرعيًا بعد عدتها من الأول، هذا إذا كان الزوج الثاني بعد العدة، يعني بعد خروجها من عدة الأول، فإن زواجه حينئذ صحيح إذا كان ليس بقصد التحليل بل عن رغبة ثم وطئها أيضًا فإنها تحل للأول على القول بوقوع الطلقة الثالثة فإنها تحل له إذا انتهت من العدة، أما زواجها في العدة فلا يصح، وعليه التوبة إلى الله، وعليها التوبة إلى الله، فإذا فرغت من العدة فإنه يتزوجها بعد ذلك، فعليها العدة، إكمال عدة الأول، وعليها إكمال العدة من الثاني الذي وطئها بغير حق، إذا كان وطئها بالنكاح الجديد هذا الفاسد تعتد العدة من الأول وعليها أن تعتد من الثاني عدة شرعية بثلاث حيض أيضًا ثم يتزوجها بعد ذلك.\nوفيه قول آخر: أن عدتها من الثاني لا تلزم لأن الماء ماؤه لو حملت وإنما عليها أن تكمل العدة من الأول هذا أمر معلوم عند أهل العلم، فعليها أن تكمل العدة ...... من الأول ثم إن أكملت العدة من الثاني فحسن وإن تزوجت في عدة الثاني لأن الماء ماؤه فلا بأس زواجًا شرعيًا.\nأما نكاحها في حال عدة الأول فإنه غير صحيح كما تقدم. نعم.\nوعليهما أن يرجعا إلى المحكمة فيما أشكل عليهما، عليهما أن يرجعا إلى المحكمة فيما أشكل عليهما.\nالمقدم: تقول: إنها تعيش الآن مع الزوج الأخير ثمان سنوات رغم ذلك الخلط الذي حصل بينها وبين أزواجها.\nالشيخ: كيف؟\nالمقدم: تقول: إنها تعيش مع الزوج الأخير..\nالشيخ: اقرأ كلامها الأول.\nالمقدم: وحتى الزوج الثاني لم يعلم ما بنفسي وجلست معه يومين وحصل جماع بيننا مرتين وحصل خصام ولكن لم يكن متعمد مني وقال: بالحرام من أهلي وكررها مرة ثانية وجعلت هذه الكلمة عذرًا وطلبت منه الطلاق فلم يرض وخالعته عن طريق المحكمة ثم أكملت العدة ثلاثة أشهر وعشرة أيام ثم رجعت إلى زوجي الأول وأنا الآن عائشة معه ثمان سنوات ورزقنا الله بولد ولم أعرف هذه الأشياء كلها إلا الآن بعدما جلست معه هذه المدة، وأنا الآن في حيرة من أمري، هل جلوسي معه صح أم غير صحيح؟\nالشيخ: عليها أن تراجع المحكمة هي وزوجها حتى تنظر المحكمة في الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/7339/حكم-زواج-المراة-قبل-انتهاء-عدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18003.mp3","categories":["الطلاق","العِدَد","الرجعة"]},{"id":9181,"question":"هذه رسالة وصلت إلى البرنامج من المستمع (س. م. ع) من العراق نينوى أخونا يقول: حدث مشكلة بيني وبين أخي حول السيارة التي نمتلكها نحن، وقد غضبت غضبًا شديدًا وحلفت طلاقًا وقلت: بطلاقي الثلاثة لا أقوم بقيادة السيارة وفعلًا لم أقم بقيادة السيارة أكثر من ثمانية أشهر، ونتيجة للظروف التي يمر بها أخي حيث لا يستطيع هو قيادة السيارة فما هو الواجب الذي يجب أن أعمله أنا، هل نقوم ببيع هذه السيارة ونشتري سيارة أخرى لا أقوم بقيادتها أنا؟ أم أقوم بقيادة السيارة نفسها، وما هو حكم الطلاق بالنسبة لي في هذه الحالة؟","title":"حكم الحلف بالطلاق والواجب فيه","answer":"الجواب: إذا كنت أيها السائل المطلق إنما أردت منع نفسك من قيادة السيارة ولم ترد إيقاع الطلاق وإنما أردت منع نفسك من قيادة السيارة غضبًا على أخيك فإن عليك كفارة اليمين ولا حرج أن تقود السيارة، وهذا يكون له حكم اليمين في أصح قولي العلماء، فعليك كفارة يمين وهي إطعام عشرة مساكين أو كسوتهم، لكل مسكين نصف صاع من قوت البلد، وهو كيلو ونصف تقريبًا، أو كسوة العشرة مما يحزئهم في الصلاة، أما إن كان قصدك إيقاع الطلاق سقتها فإنه يقع الطلاق فإنك إذا سقتها يقع طلقة واحدة على زوجتك، ولك مراجعتها ما دامت في العدة في الحال، إذا كنت لم تطلقها قبل هذا طلقتين.\nأما بيع السيارة وعدم بيع السيارة فهذا يرجع إليكما، لكما أن تبيعاها ولكما أن تتركاها لكن إن كان قصدك هذه السيارة بعينها فإذا بيعت لك أن تقود غيرها ولا يقع شيء، أما إن كان قصدك ترك مساعدة أخيك لا في هذه السيارة ولا في غيرها، وأنك تريد أن لا تسوق معه سيارة وأن لا تخدمه في هذا الشيء فلا فرق بين هذه السيارة وغيرها، ولا تنحل اليمين ببيعها حتى السيارة الأخرى إذا جاءت ليس لك أن تقودها؛ لأنك قصدت بذلك مغاضيه أخيك وهجران مساعدته، فإذا قدت السيارة الثانية فهي كالأولى إن كنت أردت إيقاع الطلاق وقع الطلاق وإن كنت لم ترد ذلك وإنما أردت هجران أخيك وعدم مساعدته في هذا الشيء فعليك كفارة اليمين كما تقدم. نعم.","link":"https://binbaz.org.sa/fatwas/7341/حكم-الحلف-بالطلاق-والواجب-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/180005.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9232,"question":"الأخ علي إبراهيم علي من السودان له سؤال ثان في رسالته يقول فيه: إن أخي متزوج من بنت خالته، وأنجبت له طفلين لكنها ظهرت له بأنها مريضة بمرض كريه، لا يعالجه الدكاترة ولا الأولياء، ويرميها في النار، وتأكد هذا الأخ بأن هذه الزوجة مريضة قبل الزواج، لكنه لا يعرفها، وأراد طلاقها فماذا عليه؟","title":"حكم طلاق من بان مرضها بعد الزواج منها","answer":"الجواب: لا حرج في طلاقها إذا أحب أن يطلقها لمرضها المذكور فلا بأس، لكن إذا كان ليس لها من يقوم بحالها ويؤويها ويعالجها ويصبر عليها فالأولى له أن يصبر هو ويحتسب الأجر حتى يصونها وحتى يحميها عن وقوعها في النار وعما يضرها هذا هو الذي ينبغي له، ينبغي للمؤمن أن يرحم زوجته ولا سيما أم أولاده ويعطف عليها حتى يشفيها الله من فضله أو يختار لها الموت.\nلكن إذا كان لها أهل يقومون عليها، ويعطفون عليها، ويتولونها، فلا مانع من طلاقه لها.\nأما إن كانت ليس لها أحد فالأفضل له والأولى به الصبر؛ لعله يستطيع أن يعمل شيئاً معها من المعروف من علاج أو غيره، وأقل شيء أن ينفق عليها ويحسن إليها حتى يتم شفاؤها أو يختار الله لها الوفاة.\nوقوله: لا يستطيع علاجها الأطباء ولا الأولياء هذا فيه تفصيل: فإن الأولياء هم المؤمنون، وبعض الناس يظن أن الأولياء ناس لهم خصوصية يتصرفون في الناس، أو لهم كرامات خاصة، أو لهم تصرف في الكون، هذا غلط عظيم، فأولياء الله هم أهل الإيمان، هم أهل التقوى، كل من كان مسلماً مؤمناً هو ولي لله، قال تعالى: أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ۝ الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ [يونس:62-63]، قال سبحانه في سورة الأنفال: وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ [الأنفال:34]، فأولياء الله هم أهل التقوى، هم أهل الخير والاستقامة، هم صالحو المسلمين، فينبغي لك أن تعلم ذلك، فليس الولي شخصاً له خصوصية بالتصرف في الكون، أو بشفاء المرضى، أو بعلم الغيب، أو ما أشبه ذلك، هذا يظنه بعض الجاهلين، ويظنه بعض الصوفية الغالطين الجاهلين، فالأولياء هم المؤمنون، ليس لهم خصوصية أخرى غير المؤمنين، هم المؤمنون، هم مطيعون لله ولرسوله، هم أهل التقوى والهدى، يقال لهم: أولياء الله، ويقال لهم: مؤمنون، ويقال لهم: مسلمون، ويقال لهم: الأبرار، ويقال لهم: الصالحون، وهم ليس في أيديهم شيء من علم الغيب، ولا من شفاء المرضى، ولا من التصرف بعباد الله بما ليس في طوق العبد، وإنما قد يدعون فينفع الله بدعائهم، قد يرقون الميت فينفع الله برقيتهم كسائر المؤمنين ليس لهم صفة خاصة، بل كل مؤمن فهو ولي لله ، وليس في أيديهم التصرف في العباد أو في الكون كما يظن بعض الجهلة من الصوفية وغيرهم، فمن ظن أو اعتقد أن بعض الناس يتصرف في الكون مع الله يدبر الكون، يشفي المرضى، يعلم الغيب، هذا كفر وضلال، كفر أكبر نعوذ بالله من ذلك، وإنما شفاء المرضى بيد الله، وعلم الغيب إلى الله ، والتصرف بالعباد بيده جل وعلا، لا أحد يتصرف بالعباد غيره ، فينبغي للسائل أن يعلم هذا، وأن يكون على بينة، حتى لا يقع فيما وقع فيه الجاهلون من اعتقادات فاسدة فيما يظن فيما يسمونهم بالأولياء، نسأل الله للجميع التوفيق والهداية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7395/حكم-طلاق-من-بان-مرضها-بعد-الزواج-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23405.mp3","categories":["الطلاق"]},{"id":9237,"question":"الرسالة الثالثة في هذه الحلقة وردت إلى البرنامج من السائل أحمد محمد بيشي علوي من المنطقة الشرقية سلاح الحدود بالخبر، الأخ أحمد محمد بيشي يقول في رسالته: أفيدكم بأنه قد جرى بيني وبين زوجتي سوء تفاهم، وكان عندي منها في هذا الوقت بنت، فطلقتها طلقةً واحدة وراجعتها من وقتها، واستمرت معي في العشرة الزوجية أربع سنوات، وتكرر منها نفس الكلام حتى غضبت غضباً شديداً فقدت أعصابي ولم أتحمل هذا الكلام فطلقتها ثلاث طلقات في آن واحد، علماً أنه يوجد لدي منها ثلاثة أطفال، وبعد أربع وعشرين ساعة ذهبت إلى أهلها للمراجعة، فطلبوا مني أن أستفتي فضيلتكم في أمري هذا، زوجتي تريدني وأنا أريدها وهي أم أطفالي وشريكة حياتي، أفيدوني أفادكم الله؟","title":"الطلاق بالثلاث في المجلس الواحد عند الغضب الشديد","answer":"الجواب: تكتب لنا غير هذه الكتابة وتحضر أو تحضر بنفسك حتى نكتب معك لقاضي البلد التي تقيم فيها بحضور الزوجة ووليها معك عند القاضي حتى يسأل الجميع عما وقع وعن صفة الواقع السابق واللاحق، ثم تكون الفتوى على ضوء ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7393/الطلاق-بالثلاث-في-المجلس-الواحد-عند-الغضب-الشديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23403.mp3","categories":["الطلاق"]},{"id":9247,"question":"وهذه رسالة وردت من السائلة (ن. ع. م) من مكة المكرمة تقول في رسالتها: أنا امرأة متزوجة منذ عشر سنوات، تزوجت رجلاً وعشت معه أربع سنوات كلها سعادة، وفي السنوات الأخيرة راح زوجي يختلط بالناس الذين يمشون في طريق سيئ، فراح يشرب المسكر أبعدنا الله وإياكم عن ذلك، ويحضر إلى البيت وهو في حالة غير طبيعية فيضربني ضرباً قوياً بدون أي سبب، وأنا امرأة مسلمة لا أستطيع أن أعيش مع إنسان يفعل شيئاً يخالف الإسلام، لكن المشكلة أن لدي منه أربعة أطفال، وأكبرهم يبلغ من العمر خمس سنين فلا أدري ماذا أفعل أفيدوني أفادكم الله؟","title":"بقاء الزوجة مع زوجها السكران وطلب الطلاق منه","answer":"الجواب: عليك أن تنصحيه وقت صحوه، وتطلبي من أبيه إن كان موجوداً أو جده أو إخوته الكبار أو أمه أو من يعز عليه من أخوال وأعمام، حتى ينصحوه وحتى يوجهوه إلى الخير، لعله يهتدي بأسبابك، فإن هداه الله وتاب فالحمد لله، وإن أصر على حاله السيئة فلك أن تطلبي الطلاق، تتصلي بالمحكمة حتى يحصل الطلاق؛ لأن بقاءه معك وهو بهذه الحالة يضرك، ويضر أولادك، وأنت أحق بأولادك ما دام بهذه الحالة، فعليك أن تفعلي المستطاع من أسباب هدايته مع والده ووالدته، وأقاربه الكبار الذين يحترمهم، ويستفيد من كلامهم ويقدر كلامهم لعل الله يهديه بأسبابهم، وأنت مع هذا تدعين له في ظهر الغيب، في صلاتك وفي الليل وفي آخر الليل، تدعين له أن الله يهديه، وأن الله يرده للتوبة وأن يعيذه من هذا العمل السيئ ومن أصحاب الشر وصحبتهم، لعل الله يستجيب لك، ويرده إلى الخير، لعل الله يستجيب سبحانه وتعالى دعاءك ويرد هذا الرجل إلى الخير والاستقامة، فإن أصر على حالته السيئة، على تعاطيه المسكر فلا مانع من طلب الطلاق؛ لأن بقاءه معك وهو على هذه الحال لاشك أن فيه مضرة عليك وعلى أولادك، نسأل الله لنا وله الهداية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7409/بقاء-الزوجة-مع-زوجها-السكران-وطلب-الطلاق-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23508.mp3","categories":["الطلاق","الحقوق الزوجية"]},{"id":9291,"question":"وهذه رسالة وردت إلينا من المرسل أحمد علي معوضة طالب من أبناء اليمن الشمالي في جامعة الملك سعود بالرياض، يقول في رسالته: إذا طلق الرجل زوجته بقوله: هي طالق، هي طالق، هي طالق، في وقت واحد، فهل تعتبر عليه طلقة واحدة ويأثم بالباقي، أم تعتبر عليه ثلاثاً، كذلك إذا قال لها: هي طالق طلاق خلوع لا نية رجوع، فما الحكم في هذا؟","title":"حكم من قال لزوجته: (أنت طالق.. أنت طالق.. أنت طالق)","answer":"الجواب: إذا قال الزوج يخاطب زوجته: أنت طالق، أنت طالق، أنت طالق، أو قال يقصدها: هي طالق، هي طالق، هي طالق، أو قال: تراك طالق، تراك طالق، تراك طالق، أو قال: تراك مطلقة، تراك مطلقة، تراك مطلقة، أو أنت مطلقة، أنت مطلقة، أنت مطلقة، أو هي مطلقة.. وهي مطلقة.. وهي مطلقة فيقع الثلاث، يقع عليها الطلقات الثلاث.\nوهكذا لو قال: طالق، ثم طالق، ثم طالق. أو أنت مطلقة ثم مطلقة، ثم مطلقة، أو طالق وطالق وطالق، كل هذه الألفاظ وأشباهها يقع بها الثلاث، إذا كانت ليست حائضاً ولا نفساء ولا في طهر جامعها فيه، بل كانت سليمة، كان الطلاق هذا في طهر لم يجامعها فيه، أو في حال الحمل، فإن هذا الطلاق يقع، وتحرم عليه حتى تنكح زوجاً غيره.\nأما إن كان حين قال: هي طالق، هي طالق، هي طالق. ما قصده الثلاث، إنما قصده الأولى، وأراد بالثانية والثالثة تأكيد الأولى وتفهيم الزوجة، فلا يقع إلا الأولى، إذا كان مقصوده حين قال: هي طالق، هي طالق، هي طالق، أو أنت طالق، أنت طالق، أنت طالق، أو تراك طالق.. تراك طالق.. تراك طالق، مقصوده الأولى، وأعاد الثانية والثالثة لأجل تفهيم المرأة أو لأجل تأكيد الأولى، هو أعلم بنيته والله الذي يحاسبه عن نيته، فإذا أراد بهذا تفهيمها الأولى أو تأكيد الأولى ولم يرد إيقاع الثانية ولا الثالثة، فإنه لا يقع إلا واحدة فقط حسب نيته لأنه ما أراد إلا واحدة، وإنما أراد بقوله: هي طالق، هي طالق الثانية والثالثة تأكيد الأولى أو تفهيم الزوجة، هذا لا يقع إلا واحدة، أما إذا كرر ذلك وقصده الثلاث، أو ما له نية بل كرر بغير قصد الطلاق حين قال: هي طالق. هي طالق، هي طالق. أو أنت طالق، أنت طالق، أنت طالق، أو تراك طالق، تراك طالق، تراك طالق، أو قال: تراك مطلقة، تراك مطلقة، تراك مطلقة. أو هي مطلقة.. هي مطلقة.. هذا يقع الثلاث، ... ما أراد إلا إيقاع الثلاث، أو ما أراد شيئاً إلا الطلاق، فهذا يقع الثلاث، مثل لو قال: أنت طالق، ثم طالق، ثم طالق، تقع الثلاث، أما إذا أراد من التكرار تأكيد الأولى وتفيهم الزوجة حين قال: هي مطلقة، هي مطلقة. أو تراك مطلقة.. تراك مطلقة، أو أنت طالق، أنت طالق، أنت طالق، أراد تفيمها الأولى، أو تأكيد الأولى فهو على نيته، يقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى ، بخلاف لو قال: أنت طالق ، ثم طالق، ثم طالق هذا يقع الثلاث، ولو قال: نويت الأولى، هذا ما هو محل تأكيد، لما أتى بثم دل على أنه أراد الثانية والثالثة، نعم.\nكذلك طالق طلاق مخلوع، أو طلاق خلوع لا نية، هذا لا يقع به إلا واحدة، إذا قال: أنت طالق طلاق خلوع لا نية رجوع فيه، هذا لا يقع به إلا واحدة على الصحيح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7467/حكم-من-قال-لزوجته-انت-طالق-انت-طالق-انت-طالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23609.mp3","categories":["الطلاق"]},{"id":9293,"question":"وهذه رسالة وردت إلى البرنامج من السائل منصور الدوسري من منطقة الخرج، يقول: في يوم من الأيام حدث خلاف خفيف بيني وبين الوالد؛ لأنه توجد سيارة ملك لوالدي فغضب من أجل سيارته وأخفاها، وقال لي: امش على رجليك، فطلقت زوجتي بالثلاث على أن أشتري سيارة جديدة ولا أركب سيارة الوالد، لكنني اضطررت واحتجت إلى سيارة الوالد لكي أوصل زوجتي لأهلها، ورجعت واشتريت سيارة جديدة من مالي الخاص، ثم ذهبت إلى الزوجة وأرجعتها إلى بيتي من غير ما تدري عن الطلاق الذي حدث في وقت الزعل، وتندمت على ما حدث، وأتوب إلى الله، ثم أعدكم أن لا يتكرر مني هذا الطلاق مرة أخرى، أفيدوني أفادكم الله؟","title":"حكم من حلف بالطلاق على عدم فعل شيء ثم فعله","answer":"الجواب: إذا كان المقصود من هذا الطلاق منع نفسك من ركوب سيارة الوالد، وحتى تجتهد في شراء السيارة الجديدة، وليس قصدك فراق أهلك وإيقاع الطلاق عليهم، وإنما أردت بذلك منع نفسك من ركوب سيارة الوالد، وحث نفسك على الشراء شراء السيارة الجديدة، فهذا الشيء يكون في حكم اليمين، يكون طلاقك هذا في حكم اليمين، وعليك كفارة اليمين ويكفي، ولا يقع الطلاق، والحمد لله.\nأما إن كان قصدك إيقاع الطلاق إن ركبت سيارة أبيك فإنه يقع طلقة على زوجتك؛ لأن الثلاث بكلمة واحدة تعتبر واحدة في أصح قولي العلماء، ويكون جماعك لها بعد ذلك مراجعة ويقع عليها طلقة إن كان لم يسبقها شيء، فإن كان سبقها طلقة تضاف إلى الطلقة السابقة، أما إن كان سبقها طلقتان، فهذه تكون الطلقة الثالثة، ولا تحل لك إذا أردت إيقاع الطلاق، أما إن كنت ما أردت إيقاع الطلاق وإنما أردت منع نفسك من ركوب سيارة الوالد، وحث نفسك على شراء السيارة الجديدة، فهذا مثل ما تقدم حكمه حكم اليمين، وعليك كفارة اليمين وزوجتك معك، لا يقع عليها طلاق، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7457/حكم-من-حلف-بالطلاق-على-عدم-فعل-شيء-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23603.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9299,"question":"وهذه رسالة وردت إلينا من السودان من (الصادق . م. أ) يقول في رسالته: علمنا مما سبق في هذا البرنامج بأنه لا يقع الطلاق على الحائض والحامل، فهل لا يقع إطلاقاً أم أنه يقع بعد الطهر، أفيدونا أفادكم الله؟","title":"حكم طلاق الحائض والحامل","answer":"الجواب: طلاق الحائض لا يقع في أصح قولي العلماء، خلافاً لقول الجمهور، جمهور أهل العلم يرونه يقع، يرون طلاق الحائض يقع، وطلاق النفساء يقع، ولكن الصحيح من قولي العلماء الذي أفتى به بعض التابعين، وأفتى به ابن عمر رضي الله تعالى عنهما واختاره شيخ الإسلام ابن تيمية وتلميذه العلامة ابن القيم وجمع من أهل العلم: هذا الطلاق لا يقع؛ لأنه خلاف شرع الله؛ لأن الله شرع أن تطلق المرأة في حال الطهر من النفاس والحيض، وفي حال لم يكن جامعها الزوج فيها، هذا هو الطلاق الشرعي، فإذا طلقها في حيض أو نفاس أو في طهر جامعها فيه، فإن هذا الطلاق بدعة ولا يقع على الصحيح من قولي العلماء؛ لقول الله جل وعلا: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1]، والمعنى: طاهرات من غير جماع، هكذا قال أهل العلم في طلاقهن العدة، أن يكن طاهرات من دون جماع أو حوامل، هذا هو الطلاق للعدة.\nأما طلاق الحامل فإنه يقع، طلاق الحامل يقع عند أهل العلم، ومن قال: أنه لا يقع، فقد غلط، طلاق الحامل يقع عند أهل العلم، فإنما الذي لا يقع هو طلاق الحائض والنفساء، وهكذا الطاهر التي ليست بحامل إذا كان في طهر جامعها فيه ولم يبن حملها، هذا في أصح قولي العلماء لا يقع؛ لأنه خلاف شرع الله؛ ولأنه في حال لم يشرع الله فيها الطلاق كما تقدم، وبعض العامة يهم ويقول: إن طلاق الحامل لا يقع. وهذا غلط، هذا من أقوال العامة لا أصل له في الشرع، ولا أصل له في كلام العلماء، الحامل يقع الطلاق عليها، فينبغي أن يفهم ذلك، نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7460/حكم-طلاق-الحاىض-والحامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23604.mp3","categories":["الطلاق"]},{"id":9301,"question":"وهذه رسالة وردت إلى البرنامج من يوسف محمد با بكر سوداني مقيم في المملكة في تربة ... يقول: لقد حلفت قبل سنة بكلمة علي الطلاق، وذلك لابن أخي حيث يريد أن يذهب إلى مكان لا أريده أن يذهب إليه، وقد رفض الرجوع واستمرت المقاطعة مدة سنة كاملة بيننا ثم أرسل إلي ..الشيخ: ماذا قال؟ أعد؟المقدم: قال: عليه الطلاق، وهو يريد يمنع أن ابن أخيه..الشيخ: اقرأ كما قال؟المقدم: بكلمة علي الطلاق لا يدي ولا يدك إذا لم ترجع معي، وكانت ذلك لابن أخي وهو يريد أن يذهب إلى مكان كنت لا أريده أن يذهب إليه، ورفض الرجوع معي واستمرت المقاطعة مدة سنة كاملة لا سلام ولا كلام بيننا وبعدها أرسل ابن أخي خطاباً يطلب مني أن أسامحه، وعند قراءة الخطاب، تأثرت وكبتت له بالمسامحة، وأعرفكم بأني متزوج بامرأتين، فهل يقع الحلف على الاثنتين، أم على واحدة، أفيدوني أفادكم الله؟","title":"حكم من حلف على شخص بالطلاق ألا يفعل شيئاً ففعله","answer":"الجواب: هذا فيه تفصيل، إن كنت أردت بهذا الطلاق منعه من الذهاب إلى الجهة التي تريد منعه منها، وأن يرجع إلى قولك، ليس قصدك إيقاع الطلاق، وإنما قصدت تخويفه والتشديد عليه لعله يوافق ولعله يترك ما أردت تركه له، هذا حكمه حكم اليمين، وعليك كفارة اليمين في مسامحته ولا يقع الطلاق على زوجتيك جميعاً، إذا كان المقصود من هذا هو حثه على الرجوع إلى قولك، وترك ما أراد وليس قصدك إيقاع الطلاق على زوجتيك، فهذا حكمه حكم اليمين، أما إذا كنت أردت بذلك إيقاع الطلاق، وأنك متى سامحته وتركت ما قلت من أجله أن الطلاق يقع على زوجتيك فأنت على نيتك، النبي ﷺ، يقول: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى.\nفإذا كنت أردت إيقاع الطلاق فإنه يقع الطلاق على زوجتيك جميعاً، إلا إذا كنت أردت واحدة منهما فأنت على نيتك أيضاً، أما إذا كان المقصود تخويفه وتحذيره من هذا العمل، ولم ترد أنك متى فعل هذا العمل أنه لا تصالحه وأنك متى صالحته يقع الطلاق على زوجتيك، إذا كنت نويت هذا فأنت على نيتك من وقوع الطلاق، وإذا كنت ما نويت ذلك، وإنما نويت وأردت منعه من هذا العمل، وتخويفه حتى لا يفعل ولم ترد إيقاع الطلاق على زوجتيك فإن الأعمال بالنيات، وعليك كفارة اليمين ولا يقع الطلاق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7471/حكم-من-حلف-على-شخص-بالطلاق-الا-يفعل-شيىا-ففعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23612.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9304,"question":"هذه رسالة وردت إلى البرنامج من العراق من محافظة كركوك من المستمعة زهراء ، تقول في رسالتها: تقدم لي شاب وطلبني من أهلي، وتم عقد قراني عليه، واشترى لي الحلي الذهبية وأثث لي بيتاً كاملاً، وفي ليلة الزفاف رفضته لا أعلم لماذا فطلقني، ثم تقدم لي شاب آخر وعقدنا القران وفي ليلة الزفاف رفضته أيضا، وأردت الطلاق منه فطلقني وأنا الآن حائرة لا أعرف ماذا أفعل، ولا أعرف لماذا أخاف من الزواج، وأنا أكره الرجال جميعاً، وقد يكون كرهي لهم هو أنني أثناء خروجي من بيتنا لقضاء بعض الحاجات أتعرض للسب والشتم من الرجال، فأصبحوا الرجال جميعاً في نظري لا شيء، بل هم صنف واحد مع احترامي لأهل الخير منهم، فماذا عساي أن أفعل، وهل علي إثم في رفض الرجلين السابقين اللذين عقد نكاحي عليهما أم لا، وما هي الأدعية التي يمكن أن تقال في ليلة الزفاف، أفيدوني أفادكم الله؟","title":"حكم رفض المرأة زوجها بعد العقد","answer":"الجواب: إذا كان الرفض لهما بسبب بغضاء حدثت في القلب وكره وقع في القلب لم تستطيعي دفعه فلا شيء عليك، الله الذي يجمع القلوب ، أما إذا كان مجرد تساهل وهوى فعليك التوبة إلى الله من ذلك؛ لأن طلب الطلاق من دون عذر أمر لا يجوز، فالواجب على المرأة أن لا تطلب الطلاق إذا كان ما هناك موجباً لطلب الطلاق، فإن كان نزل بك كره لهما وبغضاء لهما لم تستطيعي أن تجيبي إلى الدخول على الأول والثاني لما وقع في قلبك من الكراهة الشديدة حتى لم تستطيعي فهذا شيء غلبك والأمر إلى الله وليس عليك فيه شيء، أما إذا كان مجرد تساهل، ومجرد طاعة للشيطان هذا لا يجوز، بل الواجب على المرأة إذا تم عقد القران أن تجيب إلى الدخول وأن تمكن الزوج منها كما شرع الله .\nوالآن عليك أن تسألي الله جل وعلا أن يزيل ما في قلبك من كراهة الرجال الطيبين، وأن يشرح صدرك للزواج الشرعي، وتلحي على الله، والله يحب الإلحاح بالدعاء ، يقول: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، فعليك أن تلحي في الدعاء، وتكرري الدعاء في مثل السجود... في آخر التحيات.. في آخر الليل، في كل وقت، عليك أن تسألي الله  أن يشرح صدرك للزواج، وأن يزيل ما في قلبك من كراهة الرجال الطيبين، وأن يسهل لك الزوج الصالح، وإذا حصل ذلك فعليك أن تجيبي إلى الدخول، ولا تطاوعي الشيطان في طلب الطلاق، نسأل الله لنا ولك الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/7472/حكم-رفض-المراة-زوجها-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23613.mp3","categories":["الحقوق الزوجية","الطلاق"]},{"id":9332,"question":"أحد الإخوة سوداني أيضاً بعث يسأل ويقول: رجل قال لزوجته: أنت مثل أختي وهو لا يقصد في ذلك عدم المعاشرة الزوجية، هل يخرج بدل الإطعام نقداً أم لا، نرجو أن تفيدونا هذا جزاكم الله خيراً؟","title":"حكم من قال لزوجته: أنت مثل أختي دون قصد تحريمها","answer":"الجواب: هذا يختلف بحسب نيته، إن كان قال لزوجته: أنت مثل أختي أو مثل أمي من باب الاحترام، من باب الإكرام، من باب يعني: التقدير لها فهذا ليس بحرام وليس عليه شيء، لكن ترك هذا أولى ينبغي تركه؛ لأنه يوهم، ينبغي أن لا يستعمل هذا معها.\nأما إن كان أراد تحريمها، يعني: أنها محرمة مثل أخته، أو أنها محرمة كأمه، أو كبنته هذا هو الظهار المعروف وعليه كفارة الظهار وهي مرتبة بنص القرآن.\nأولاً: عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ما فيها نقود، ستين مسكين طعام يعشيهم أو يغديهم أو يدفع لهم طعامًا نيئًا نصف صاع لكل واحد ثلاثين صاعاً من الحنطة، من البر، من الشعير، من قوت البلد من التمر، ويكفي ذلك حتى يمسها بعد ذلك، يعني: لا يمسها حتى يدفع عليه الكفارة، أما النقود فلا تصلح. نعم.\nالمقدم: النقد في هذا لا يصلح؟\nالشيخ: لا يصلح لا، خلاف النص. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7486/حكم-من-قال-لزوجته-انت-مثل-اختي-دون-قصد-تحريمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15506.mp3","categories":["الطلاق","الظهار"]},{"id":9338,"question":"هذه رسالة وردت إلينا من المرسل (ع. ز. م) مصري يعمل بالمملكة يقول في رسالته: امرأة ذهبت إلى المحكمة تطلب الطلاق من زوجها فسألتها المحكمة أين زوجك؟ قالت: ليس موجوداً ولا أعرف له طريق، فطلبت منها المحكمة شاهدين لإثبات ذلك، فأحضرت شاهدين فشهدا بأنه غير موجود وأنهم لا يعرفون له طريق، لكنهم يعرفون أنه موجود في البلد، ويعمل ومتأكدين جداً من هذا، فقد أعلنت المحكمة الطلاق وبعد ذلك تزوجت هذه المرأة من رجل ثانٍ والزوج الثاني يعرف الموضوع من أوله،  ما الحكم على الشاهدين والمرأة والزوج الثاني وما الحل في ذلك أفيدونا أفادكم الله؟","title":"قيام المحكمة بتطليق الزوجة دون علم زوجها","answer":"الجواب: هذا تراجع فيه المحكمة التي حكمت تراجع ويبين لها الواقع، والمحكمة تنظر في حكمها، هذه المسألة تتعلق بالمحكمة، فالمحكمة يبين لها الواقع وأن الرجل موجود، وأن الشهود قد كذبوا إذا كانوا قالوا إنه غير موجود وأنه لا يدرى عنه، على كل حال هذا تراجع فيه المحكمة التي حكمت حتى تنظر في حكمها، نعم.\nالمقدم: والإثم فضيلة الشيخ؟\nالشيخ: على الشهود إذا كانوا كاذبين، إذا كذبوا عليهم الإثم وعلى المرأة معهم.\nالمقدم: والزوج الذي يعلم الثاني، وهو يعلم ... ؟\nالشيخ: كذلك شريك في الإثم، ولا يجوز له أن ينكحها وهو يعلم أن زوجها حاضر وأنه شهد بغير حق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7512/قيام-المحكمة-بتطليق-الزوجة-دون-علم-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23808.mp3","categories":["الطلاق"]},{"id":9339,"question":"الرسالة الثانية في هذه الحلقة وردت إلى البرنامج من السائل آدم عبد الله أبكر من نجامينا بجمهورية تشاد، يقول في رسالته: ما الحكم في ثلاث طلقات في كلمة واحدة، هل تقع واحدة أم ثلاثاً؟","title":"حكم طلاق الثلاث بلفظ واحد","answer":"الجواب: هذا الطلاق بالوصف المذكور فيه خلاف بين أهل العلم، الجمهور من أهل العلم، والأئمة الأربعة يقولون: إن الطلاق بالثلاث ولو بكلمة واحدة يقع، فإذا قال لزوجته: أنت طالق بالثلاث أو مطلقة بالثلاث، أو قال: هي طالق بالثلاث، يعني: زوجته طلق عند الأكثرين من أهل العلم، وحرمت عليه حتى تنكح زوجاً غيره، وذهب جماعة من العلماء: إلى أنه لا يقع بذلك إلا واحدة، إذا كان الطلاق بلفظ واحد، بأن قال: هي مطلقة بالثلاث، أو أنت طالقة بالثلاث، أو مطلقة بالثلاث، ذهب جمع من أهل العلم: إلى أن هذا الطلاق لا يقع إلا واحدة رجعية، وله مراجعتها ما دامت في العدة، روي هذا عن ابن عباس في رواية صحيحة عنه، وجاء عنه خلاف ذلك، وروي هذا عن جماعة من الصحابة ، وقال به جماعة من التابعين، واختاره محمد بن إسحاق صاحب السيرة وآخرون وأفتى به أبو العباس ابن تيمية الإمام المشهور -رحمه الله-، وأفتى به أيضاً تلميذه العلامة المحقق ابن القيم رحمه الله، وهذا هو الذي أفتي به لما فيه من التيسير على المسلمين والتسهيل، والأصل في هذا ما ثبت عنه ﷺ من حديث ابن عباس رضي الله عنهما، قال: كان الطلاق على عهد النبي ﷺوعهد أبي بكر وسنتين من خلافة عمر رضي الله عنهما طلاق الثلاث واحدة، فلما كان عمر  قال: إن الناس قد استعجلوا في شيء كانت لهم فيه أناة، فلو أمضيناه عليهم، فأمضاه عليهم ، خرجه مسلم في الصحيح.\nوروى الإمام أحمد بن حنبل رحمه الله بإسناد جيد عن ابن عباس رضي الله عنهما: أن أبا ركانة طلق امرأته ثلاثاً فحزن عليها، فردها عليه النبي ﷺ وقال: إنها واحدة، والظاهر أنه طلقها ثلاثاً يعني: بكلمة واحدة، هذا هو الظاهر من الحديثين، وهذا هو المعتمد وهو الذي أفتي به كما تقدم، وذهب بعض أهل العلم إلى أن الثلاث ولو متفرقة لا يقع منها إلا واحدة، واختاره أبو العباس ابن تيمية رحمه الله، فإذا قال: طالق وطالق وطالق، أو طالق ثم طالق ثم طالق لا يقع إلا واحدة، ولكن الذي ظهر لي من كلام أهل العلم ومن كلام ابن عباس في الرواية التي أفتى فيها بأنها واحدة، أن جعلها واحدة إنما يختص بما إذا تلفظ بالثلاث بلفظ واحد.\nأما إذا كرر الطلاق فإنه يقع، إذا كرره على وجه يغاير فيه الثاني الأول، والثالث الثاني، كأن يقول: طالق، ثم طالق، ثم طالق، أو طالق وطالق وطالق، هذا تقع الثلاث على المعتمد وهو الذي عليه جمهور أهل العلم، ومثله لو قال: أنت طالق، أنت طالق، أنت طالق، فإنها جمل ثلاث تامة فيقع بها الطلاق، إلا إذا أراد بالثانية والثالثة التأكيد، أو إفهام المرأة فله نيته، أما إذا قال: أنت طالق طالق طالق بغير واو ولا ثم ولا إعادة المبتدأ بل قال: أنت طالق طالق طالق، أو أنت مطلقة مطلقة مطلقة، فهذا ذكر فيه أهل العلم: أنه لا يقع به إلا واحدة؛ لأن الكلمة الثانية المعادة والثالثة بدون إعادة الجملة وبدون إعادة المبتدأ لا تقع إلا مؤكدة، أنت طالق طالق طالق، أنت مطلقة مطلقة مطلقة، أو هي مطلقة مطلقة مطلقة، وليس له نية الثلاث، فهذا الصواب فيه أنه يعتبر واحدة، حتى عند من أوقع الثلاث بكلمة واحدة؛ لأن هذا لم يقصد الثلاث وإنما كرر اللفظ لغضبه أو لأسباب أخرى لم يقصد به إيقاع الطلاق، فهذا يعتبر واحدة، كما لو قال: زيد زيد زيد في الكلام، مثل ما جاء في حديث عائشة: أيما امرأة نكحت بغير إذن وليها فنكاحها باطل باطل باطل، مثل هذا يستعمل للتأكيد، فالصواب في هذا أنه يحكم بأنه واحدة ويكون اللفظ الثاني والثالث مؤكد للفظ الأول، ولا يقع بهما شيء كما نص على هذا جمع من أهل العلم في باب ما يختلف به عدد الطلاق، وأعيد الجملة هذه حتى تفهم هي أن يقال: طالق طالق طالق، أو يقول: مطلقة مطلقة مطلقة، هذا هو محل جعلها واحدة، ويكون اللفظ الثاني والثالث مؤكدين للفظ الأول، وهذا هو الصواب كما نص عليه جمع من أهل العلم، وأما إذا كرر بالجمل أو بحروف العطف هذا يقع، طالق ثم طالق ثم طالق، تقع الثلاث عند الجمهور وهو الأظهر من الأدلة، أو طالقة وطالقة وطالقة تقع بها الثلاث، وهكذا لو قال: أنت طالق أنت طالق أنت طالق، أو أنت مطلقة أنت مطلقة أو أنت مطلقة، فهكذا تكرار الجمل، أو تراك طالق تراك طالق تراك طلاق، هذا يقع به الثلاث إلا إذا نوى التأكيد بالثانية والثلاثة في قوله: أنت طلاق أنت طالق أنت طالق، أو تراك طالق تراك طالق تراك طالق؛ لأنها جمل فإن نوى بها التأكيد والإفهام وإلا وقعت الثلاث، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/7508/حكم-طلاق-الثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23805.mp3","categories":["الطلاق"]},{"id":9340,"question":"هذه رسالة وردت من عبدالمنعم أحمد عبدالعزيز مقيم بالدمام يقول: أنا وبعض الإخوة في مجال العمل أحياناً تخرج من أفواهنا ألفاظ عندما نتناقش أو نحتدم في الحديث يقول الواحد منا: علي الطلاق لا أفعل كذا أو أن أفعل كذا، وتتكرر كلمة علي الطلاق، لكن بدون نية الطلاق، أو قصد الزوجة، ولكنه لفظ تعودنا عليه بكثرة، فقد سألنا وقيل سواء كنتم قصدتم أو لم تقصدوا فهي تعتبر طلقة واحدة، أفيدونا أفادكم الله؟","title":"حكم قول علي الطلاق","answer":"الجواب: أولاً: لا ينبغي لكم هذا، أولاً لا ينبغي للمؤمن أن يتخذ الطلاق لهجة له وديدناً له في أكثر كلامه وأحاديثه، ينبغي له أن يحترم الطلاق، وهو أمر شرعي وأمر يتعلق به أحكام، فينبغي له أن يصون لسانه عن ذلك إلا عن قصد وعن نية وعن رغبة، وإلا فليصن لسانه عن ذلك حتى لا تقع الطلقة عليه وهو لا يشعر، أو يقع الطلاق الكثير عليه وهو لا يشعر، يعني: على زوجته، ينبغي له أن يصون لسانه عن ذلك، وأن يبتعد عن إيقاع الطلاق، والكلام فيه إلا عن قصد واضح، يقصد به طلق زوجته إذا طابت نفسه منها، أما إذا تلاعب بالطلاق ويكثر من الطلاق فهذا لا ينبغي له ويخشى عليه من الإثم، لكن الحكم في هذا يختلف، إذا كان قال عليه الطلاق ما يفعل كذا، عليه الطلاق ما يكلم فلان، عليه الطلاق ما يعمل العمل الفلاني، وهو قصده من ذلك منع نفسه من هذا الشيء أن يمنع نفسه، وليس قصده إيقاع الطلاق على زوجته، إنما أراد منع نفسه عليه الطلاق ما يكلم فلان، علي الطلاق أن تأكل هذه الذبيحة، على الطلاق أن تسافر معي، أن تذهب معي إلى فلان، هذا كله في حكم اليمين على الصحيح، وعليه كفارتها إذا لم ينفذ مطلوبه.\nيكون حكمه حكم اليمين فيما ذكره جماعة من أهل العلم وروي عن جماعة من السلف، وعن بعض الصحابة ما يدل على ذلك، وهذا هو الذي قرره أبو العباس ابن تيمية وابن القيم وجماعة وذكروا أنه في حكم اليمين، واحتجوا على هذا بآثار سلفية، وبعض الأحاديث الواردة في هذا الباب.\nوالخلاصة: أن الواجب على هؤلاء عدم التلاعب بالطلاق والحذر من ذلك، فإذا وقع الطلاق بهذه الصيغة، عليه الطلاق ما يفعل كذا، عليه الطلاق أن يكلم فلان، عليه الطلاق أن يسافر، عليه الطلاق أنه ما يأكل عند فلان، وما أشبه هذه الأشياء، فإن نفذ فلا شيء عليه، وإن لم ينفذ بل أخل بما قال فعليه كفارة اليمين إذا كان المقصود هو تنفيذ هذا الشيء أو عدم تنفيذه، ليس المقصود فراق الزوجة، فهو بمثابة لو قال: والله لا أفعل كذا، والله لا أكلم فلان، والله لا أسافر، عليه كفارة اليمين. نعم.\nالمقدم: وإذا كان لا يقصد لا يمين ولا طلاق لكن ألفاظ جرت على اللسان؟\nالشيخ: لابد أن يقصد منع نفسه من شيء، مثل هذا أو حمله على شيء، الناس يستعملونه إما لحملها على شيء، وإلا لمنعها من شيء، هذا هو القاعدة المعروفة عند كما يفعلون مع الضيوف، علي الطلاق أن تأكل الذبيحة، علي الطلاق أن تجلس تأكل كرامتك، علي الطلاق أني ما أكلم فلان لأنه فعل وفعل، عليه الطلاق أنه ما يزور فلان لأنه غضبان عليه وهكذا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7513/حكم-قول-علي-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23809.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9359,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من أحد الإخوة يقول: عبدالله محمد هلال أخونا رسالته مطولة في الواقع لكنها تحكي قصة يمين بالطلاق، أستأذن سماحة الشيخ في قراءتها كما وردت؟يقول: في لحظة غضب وانفعال قلت لزوجتي التي كانت السبب في هذا الغضب: علي الطلاق ما أنت ذاهبة إلى المدرسة بكرة، وكررت ذلك ثلاث مرات، وأنا لا أدري ما أقول، ولا أقصد الطلاق أبداً؛ لأني أبغضه ولا أعرف أحكامه، بل أريد منعها عن المدرسة، فهي تعمل مدرسة وكان ذلك ليلة أول يوم في العام الدراسي، في الصباح ألحت علي زوجتي بأنه من الضروري الذهاب إلى المدرسة وخاصة في أول يوم من العام الدراسي، فاضطررت إلى توصيلها إلى المدرسة وكلي خوف من الله؛ لأني لا أعرف بالضبط حكم ما قلت: هل هو يمين طلاق أم لا، بسؤالي بعض الإخوة المتفقهين في الدين عن حكم ذلك فأفاد البعض أن هذا حلف بغير الله  ويستوجب الكفارة وهي: إطعام عشرة مساكين أو كسوتهم أو صيام ثلاثة أيام متتابعة، وقد كفرت عن هذا اليمين بإطعام عشرة مساكين، أفيدوني جزاكم الله خيراً، هل ما فعلت وهو إطعام عشرة مساكين صحيح ويكفي، وأن هذا اليمين حلف بغير الله، أم أنه يعتبر يمين طلاق أستغفر الله، إنني أعيش في خوف وفزع وصراع نفسي رهيب، أخشى أن أكون أعيش مع زوجتي في الحرام وأن ما حدث يعتبر يمين طلاق، علماً بأنني ندمت على ذلك ندماً كبيراً وتبت إلى الله وعزمت على عدم العودة إلى ذلك أبداً، إنني أدعو الله أن يبارك فيكم ويكثر من أمثالكم، والسلام عليكم ورحمة الله؟","title":"متى يكون حكم الحلف الطلاق حكم اليمين؟","answer":"الجواب: هذا الطلاق حكمه حكم اليمين، مادمت تقصد منعها ولا تريد إيقاع الطلاق وإنما قصدت منعها من الذهاب إلى المدرسة فهذا حكمه حكم اليمين وقد فعلت الكفارة والحمد لله، ولا حرج عليك في أصح قولي العلماء، ولا يعتبر في حكم الحلف بغير الله، يعني: يكون شرك، لا. ليس في حكم الحلف بغير الله، ولكنه له حكم اليمين من جهة الكفارة فقط، فينبغي لك أن لا تعود إليه؛ لأن الكثير من أهل العلم يرونه يقع به الطلاق، فينبغي لك أن لا تعود إلى ذلك.\nوأما الصواب: فهو الذي فعلته وهو الكفارة هذا هو الصواب، أنه تكفي فيه الكفارة؛ لأنك لم ترد إيقاع الطلاق وإنما أردت منع زوجتك من الذهاب إلى المدرسة فيكفي في هذا كفارة اليمين وهي إطعام عشرة مساكين أو كسوتهم وقد فعلت ذلك، لكن من عجز عن الإطعام والكسوة والعتق فإنه يصوم ثلاثة أيام؛ لأن الكفارة فيها تخيير وفيها ترتيب، فالتخيير هو عتق رقبة أو إطعام عشرة مساكين أو كسوتهم أي واحدة فعلها من هذه الثلاث أي واحدة فعلها كفى، فإن عجز عن الثلاث كلها صام ثلاثة أيام.\nولكن مثلما تقدم ليس هذا حكمه حكم الحلف بغير الله من جهة أنه شرك كما لو قال: والنبي أو والأمانة، أو بالنبي هذا شرك لا يجوز، أما قول: علي الطلاق أو علي الحرام ليس حكمه حكم الحلف بغير الله ولكنه ما ينبغي فعله، ولاسيما الحرام لا يجوز تحريم الإنسان ما أحل الله له، وعليه في هذا كفارة اليمين إذا كان قصد منع من حلف عليه، منع زوجته أو منع غيره كأن يقول: علي الحرام ما أكلم فلان، علي الطلاق ما أكلم فلان، علي الطلاق ما تروحي يا فلانة إلى كذا وكذا، هذا كله حكمه حكم اليمين إذا قصد المنع. نعم.\nالمقدم: بارك الله فيكم، لو افترضنا أنه حصل شيء من المعاشرة الزوجية قبل تكفير اليمين؟\nالشيخ: لا حرج، الكفارة إن شاء قدمها وإن شاء أخرها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7523/متى-يكون-حكم-الحلف-الطلاق-حكم-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15605.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9404,"question":"مع مطلع هذه الحلقة نعود إلى رسالة إحدى الأخوات المستمعات من العراق تقول (خ. م. ص) أختنا عرضنا سؤالًا من رسالتها في حلقة مضت.وفي هذه الحلقة تسأل وتقول: إذا حرمت المرأة نفسها على زوجها فما الحكم؟","title":"حكم تحريم المرأة نفسها على زوجها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخليله، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فإن التحريم لما أحل الله أمر لا يجوز، فليس للمرأة أن تحرم زوجها، وليس للرجل أن يحرم زوجته، وليس لأحد من الناس أن يحرم ما أحل الله، فلا يقول: اللحم علي حرام، أو اللبن علي حرام، أو الفاكهة علي حرام، أو الحبوب علي حرام، أو غير هذا مما أحل الله، يقول الله : يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ [التحريم:1] وقال سبحانه في الذين يظاهرون نسائهم، يعني: يحرمون نساءهم: وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا [المجادلة:2].\nفليس للمؤمن ولا لمؤمنة تحريم ما أحل الله، فالرجل إذا حرم زوجته وظاهر منها يكون عليه الكفارة وهي عتق رقبة مؤمنة، فإن لم يجد صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكينًا ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد من تمر أو غيره، وليس له أن يقربها حتى يؤدي الكفارة كما نص عليه كتاب الله في سورة المجادلة.\nأما المرأة فليس لها حكم الظهار، وإنما هو للرجل؛ لأن الله قال: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3].\nأما المرأة إذا حرمت زوجها بأن قالت: أنت علي كظهر أبي، أو أنت علي حرام، أو أنا محرمة عليك أو ما أشبه ذلك، فإنها بهذا قد غلطت وأخطأت وعليها التوبة والاستغفار؛ لأنها حرمت ما أحل الله لها، وعليها كفارة يمين فقط؛ لقول الله جل وعلا: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] فسمى تحريمه ﷺ للعسل كما في الرواية المشهورة أو لـمارية الجارية سماه يمينًا.\nوهكذا الرجل إذا حرم طعامًا أو شرابًا أو فاكهة أو امرأة ليست زوجة له فإن عليه كفارة يمين، وهكذا المرأة إذا حرمت زوجها أو حرمت فاكهة أو كلام فلان أو زيارة فلان يكون عليه كفارة يمين، وليس عليها ظهار، الظهار للزوج خاصة، أما هي فعليها كفارة اليمين وهي إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة، فإن عجزت، يعني: صارت فقيرة فإنها تصوم ثلاثة أيام، هكذا بين الله سبحانه في قوله جل وعلا: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية.\nفبين  أن الواجب حفظ اليمين، وأن من عقد اليمين ثم حنث عليه الكفارة، والله قال سبحانه في قصة نبيه ﷺ لما حرم العسل: قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:2] فالتحريم لما أحل الله حكمه حكم اليمين.\nقال ابن عباس في هذا: «هو يمين يكفرها». نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7569/حكم-تحريم-المراة-نفسها-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18901.mp3","categories":["الطلاق","الظهار"]},{"id":9431,"question":"مستمع مصري يقول: (ي. ق. م) يسأل هذا السؤال، يقول: إنني في يوم حلفت على أختي أنني لا أدخل بيتك خمس سنوات، وعندما كنت مسافرًا قلت لنسيبي: أحضر أختي لكي أسلم عليها خارج البيت في الشارع، وعندما حضرت أختي سلمت عليها وجذبتني إلى داخل البيت، فهل وقع يميني أم لا؟ وكان حلفي هو: علي الطلاق لا أدخل بيتك خمس سنوات، وكنت غضبانا؟","title":"حكم من حلف بالطلاق ألا يدخل بيت أخته ثم دخله","answer":"الجواب: نعم، لما جرتك ودخلت البيت باختيارك ووافقت على الدخول فقد حنثت في اليمين هذه، فإن هذا العمل يسمى يمينًا إذا كنت قصدت منع نفسك من الدخول ولم تقصد إيقاع الطلاق فهذه يمين وقد حنثت فيها وعليك كفارة يمين، ولا يقع الطلاق على زوجتك، إذا كنت إنما قصدت منع نفسك من الدخول وهجر أختك ولم تقصد إيقاع الطلاق على زوجتك، فإن هذا يسمى يمينًا في الحكم الشرعي من جهة الكفارة، ولا يقع الطلاق في أصح قولي العلماء، وزوجتك باقية في عصمتك.\nوالكفارة هي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، وإطعامهم يكون بإطعامهم عشاء أو غداء ولو متفرقين، أو إعطائهم نصف صاع لكل واحد من التمر أو من الرز أو غيرهما من قوت البلد، كل واحد نصف صاع، كيلو ونصف تقريبًا، أو تعطي كل واحد كسوة تجزئه في الصلاة كقميص أو إزار ورداء ويكفي، والحمد لله، مع التوبة والاستغفار عن قطيعتك لأختك، فإن المؤمن يجب عليه أن يصل أن أرحامه، والأخت من أقرب الرحم، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: لا يدخل الجنة قاطع رحم هذا وعيد عظيم، والله يقول في كتابه العظيم : فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ ۝ أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22-23]، هذا وعيد عظيم أيضًا، فالقطيعة من الكبائر.\nفعليك -يا أخي- أن تتوب إلى الله، وأن تصل أختك، وأن تدع هذا اليمين الخاطئة، وعليك كفارة يمين إذا كنت أردت منع نفسك من الدخول على أختك ولم ترد إيقاع الطلاق.\nأما إن كنت أردت إيقاع الطلاق فإنه يقع طلقة واحدة بدخولك على أختك، ولك أن تراجعها حالًا بإشهاد اثنين أنك راجعت زوجتك، إذا كنت لم تطلقها قبل هذا طلقتين.\nأما إن كنت طلقتها قبلها طلقتين فإن هذه تكون الثالثة، ولا تحل إلا بعد زوج إذا كنت أردت إيقاع الطلاق، أما إن كنت ما أردت إيقاع الطلاق وإنما غضبت على أختك فأردت منع نفسك منها وعدم الدخول عليها ولم ترد أنك لو دخلت فإن الطلاق يقع على زوجتك لم ترد هذا، وإنما في بالك وفي نفسك إنما هو المنع، منع نفسك من الدخول على أختك؛ ولهذا طلقت للتأكيد على نفسك ومنعها من الزيارة لأختك، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/7596/حكم-من-حلف-بالطلاق-الا-يدخل-بيت-اخته-ثم-دخله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/190014.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9436,"question":"يسأل أيضاً ويقول: بأنه متزوج وله أولاد ويعيش في أحسن حال، فأراد أخوه أن يتزوج من أخت زوجته وهي مطلقة بسبب عدم الخلف كذا يقول، وأنا رفضت وقلت لأهل زوجتي: إذا زوجتم أخي فتكون زوجتي طالق، والنية صادقة في الطلاق إذا حدث زواج، لكن أخي تزوج من هذه المرأة فهل تصبح زوجتي طالق، علماً بأنني لا أريد طلاقها لكن أريد أن أمنعهم من هذا الزواج أفتوني بارك الله فيكم؟","title":"الطلاق المعلق بنية المنع","answer":"الجواب: إذا كان قصدك من ذلك منعه من الزواج وليس قصدك إيقاع الطلاق إن تزوج فعليك كفارة يمين، وليس على زوجتك طلاق، إذا كان هذا قصدك ونيتك أنك قلت هذا حتى يمتنع أخوك، فإن هذا يكون له حكم اليمين وعليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن لم تستطع هذا كله فعليك أن تصوم ثلاثة أيام.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7609/الطلاق-المعلق-بنية-المنع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23910.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9449,"question":"يسأل أيضاً ويقول: حلفت فقلت: علي الحرام عن الحرمة، فهل هذا يمين أو أنه طلاق؟ وهل له كفارة أم لا أفيدوني أفادكم الله؟","title":"حكم تحريم الزوجة","answer":"الجواب: هذا القول حكمه حكم الظهار، إذا قال: عليه الحرام من زوجتي، أو علي الحرام من زوجتي، أو زوجتي محرمة علي أو كأمي أو كأختي أو كبنتي، وما أشبه هذه الألفاظ، فهذا حكمه حكم الظهار في أصح أقوال أهل العلم، وعليه كفارة الظهار، إذا كان لم ينو بها الطلاق، إنما نوى التحريم أو أطلقها ولم ينو شيئاً، فهذا فيه كفارة الظهار المنصوص عليها في سورة المجادلة، وهي عتق رقبة مؤمنة، فإن لم يتيسر صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكيناً قبل أن يمسها، قبل أن يقربها، هذا هو الواجب في الظهار، فإذا قال: زوجته عليه حرام، أو علي الحرام من زوجتي، أو محرمة زوجتي، أو حرام علي كأمي، أو كظهر أمي، أو كأختي أو كظهر أختي، أو ما أشبه هذه الألفاظ، فإن هذا يسمى: ظهاراً وعليه كفارته، وهو محرم لا يجوز هذا الكلام، سماه الله منكراً من القول وزور، فهي ليست حراماً عليه، فتحريمه لها منكر، فعليه التوبة إلى الله من ذلك، والاستغفار والندم، وعلى من فعل هذا الكفارة، وهي كما تقدم عتق عبد أو عبدة من أهل الإسلام، فإن لم يتيسر ذلك صام شهرين متتابعين، ستين يوماً، فإن لم يتيسر ذلك ولم يستطع أطعم ستين مسكيناً، يعني: ستين فقير لكل مسكين نصف صاع من قوت البلد، من تمر أو أرز أو حنطة أو غير هذا من قوت البلد، قبل أن يمسها قبل أن يقربها.\nأما لو قال: عليه الحرام إن فعل كذا، أو عليه الحرام إن كلم فلاناً، أو عليه الحرام ما يسافر إلى كذا وكذا، هذا تحريم معلق، إذا كان قصد منه منع نفسه من العمل الذي أراد وهو السفر أو الكلام، هذا يكون له حكم اليمين لا يكون له حكم الظهار في أصح أقوال أهل العلم، فإذا قال الزوج: علي الحرام ما أسافر اليوم، علي الحرام ما أكلم فلان، علي الحرام ما أزور فلان، علي الحرام ما تروحين إلى فلانة يبي يمنعها، علي الحرام ما تروحين لأهلك اليوم، لقصد منعها، أو منع نفسه من السفر أو ما أشبه ذلك، فهذه ألفاظ لها حكم اليمين في أصح أقوال أهل العلم، وعليه كفارة اليمين وهي إطعام عشرة مساكين، أو كسوتهم أو عتق رقبة، فمن عجز عن ذلك صام ثلاثة أيام، هذا هو الواجب في هذه المسائل، أما إن كان أراد الطلاق فله حكم آخر، إن كان أراد الطلاق ولم يرد التحريم، بل أراد طلاقها قال: علي حرام فلانة، أو زوجتي علي حرام وقصده طلاقها يكون طلقة واحدة، يكون هذا طلقة واحدة تحسب عليه، فإن كان قد طلقها قبلها طلقتين تمت الثلاث وحرمت عليه، حتى تنكح زوجاً غيره، فإن كان ما طلقها سابقاً أو ما طلقها إلا واحدة سابقاً، فإنه يراجعها ما دامت في العدة، والسنة أن يشهد شاهدين عدلين أنه راجعها ما دامت في العدة، فإن كان قال ذلك لمنع أو لحث أو تصديق أو تكذيب ما قصد إيقاع الطلاق، قال: عليه الحرام يقصد الطلاق، أو قال: علي الطلاق ما أسافر، ما أكلم فلان، ما أزور فلان، أو عليه الطلاق ما تزورين أهلك، أو عليه الطلاق ما تكلمي فلان، قصده منعه، فهذا مثل ما تقدم حكمه حكم اليمين، فيه كفارة اليمين، والله ولي التوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7624/حكم-تحريم-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24003.mp3","categories":["الطلاق","الظهار"]},{"id":9465,"question":"المستمع شيخون حنفي محمد مصري الجنسية ويعمل بالمملكة في جدة، بعث برسالة إلى البرنامج يقول فيها: لقد سرقت لي سلسلة من الذهب في البيت، وقد حلفت على زوجتي بالطلاق وقلت لها: بأنت محرمة علي إذا لم توجد السلسلة، ثم إنني عرفت بأنها بريئة وأن سارقًا هو الذي سرق السلسلة، أرجو الإفادة جزاكم الله خيرًا فيما صدر مني؟","title":"كفارة الظهار","answer":"الجواب: هذا فيه تفصيل:\nوفي الحقيقة أنك استعجلت، ولكن هذا فيه تفصيل: فإن كنت أردت أنها محرمة عليك ولو لم تكن عندها السلسلة، وأنها إذا لم تحضر السلسلة فهي محرمة عليك لأنك ظننت أنها عندها وأنها خانتك فيها، فلو كنت جازمًا بهذا وأنها حرام عليك إلا أن تؤدي السلسلة فهذا حكمه حكم الظهار وعليك كفارة الظهار، وهي عتق رقبة مؤمنة ذكر أو أنثى، فإن لم تجد صمت شهرين متتابعين، فإن لم تستطع أطعمت ستين مسكينًا لكل مسكين نصف صاع تكون من قوت البلد من تمر أو أرز أو غيرهما قبل أن تمسها، قبل أن تتصل بها، هذا هو الواجب عليك ؛ لأن هذا في حكم الظهار.\nأما إن كنت ما أردت تحريمها وإنما أردت تشجيعها على البيان والإيضاح، وأنك تتهمها بهذا لكن تريد من هذا الكلام حثها على البيان وعلى رد السلسلة ولم ترد تحريمها، ولكن أردت تخويفها أو تحذيرها من الكتمان، وحثها على البيان فهذا حكمه حكم اليمين، وعليك كفارة اليمين وتكفي، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، من تمر أو أرز أو حنطة أو غير ذلك، أو كسوتهم بما يجزئهم في الصلاة كقميص أو إزار ورداء، أو عتق عبد أو أمة مؤمنة، هذا هو الكفارة، هذه هي الكفارة للظهار، فإذا عجز الحالف عن هذه الكفارة ولم يكن عنده قدرة صام ثلاثة أيام.\nوأسأل الله لنا ولك الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/7625/كفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19109.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9478,"question":"المستمع الذي رمز إلى اسمه بـ (ع. م. ر) من الطائف- رانية، يقول في سؤاله: قلت في إحدى المرات: تحرم علي زوجتي مثل أمي وأختي لو عملت هذا، فما رأيكم في هذه المشكلة وأفيدوني بالنصيحة أفادكم الله؟","title":"حكم الظهار وكفارته","answer":"الجواب: إذا قال الرجل تحرم عليه زوجته كحرمة أمه أو أخته إذا فعلت كيت وكيت، هذا يسمى ظهارًا، وعليه كفارة الظهار وعليه التوبة إلى الله؛ لأن الظهار منكر من القول وزور ليس له فعله، لكن متى قال تحرم عليه زوجته كأمه أو أخته أو جدته أو عمته أو خالته أو نحو ذلك فإذا كلمت فلانًا أو إذا لم تبت عندي أو إذا فعلت كيت وكيت فهذا يسمى ظهارًا.\nفعليه التوبة إلى الله من ذلك، وإذا فعلت ما منعها منه فإنه يكون عليه كفارة الظهار وهي عتق عبد أو أمة مؤمنة، وإن لم يستطع صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، والصاع أربعة حفنات باليدين الممتلئتين المتوسطتين، هذا صاع النبي ﷺ، فعليه ثلاثون صاعًا بصاع النبي ﷺ يقسم بين ستين مسكينًا، كل مسكين له نصف الصاع، وهو كيلو ونصف تقريبًا بالوزن، قبل أن يمسها قبل أن يتصل بها كفارة لما وقع منه من التحريم والظهار، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7637/حكم-الظهار-وكفارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19204.mp3","categories":["الطلاق","الظهار"]},{"id":9528,"question":"يقول أخيراً في رسالته: هل يقع الطلاق على المرأة وأنا في خارج البيت وفي عملي، وحلفت بالطلاق على فعل شيء أو تركه ووقعت في ما حلفت فيه؟ فهل يقع الطلاق بالرغم أن المرأة لم تسمع هذا الكلام؟ وهل هناك فرق بين الطلاق في غيبة المرأة أو في حضورها؟","title":"حكم وقوع الطلاق في غياب الزوجة.","answer":"الجواب: ليس من شرط وقوع الطلاق أن تحضر.. يقع الطلاق في غيبتها وفي حضورها لو طلقها في بلاد بعيدة وقع الطلاق، فليس من شرط الطلاق أن تكون حاضرة، ولكن الطلاق المعلق على شيء يختلف، فإذا كان المعلق عليه شيئاً يقصد منعه أو حصوله أو التصديق أو التكذيب فهذا له حكم اليمين على الصحيح من أقوال العلماء له حكم اليمين يكفر كفارة يمين ولا يقع الطلاق كأن يقول: عليه الطلاق ما يكلم فلان، عليه الطلاق أن لا يسافر في يوم كذا، عليه الطلاق أن لا تخرجي إلى أهلك، عليه الطلاق أن لا تكلمي فلاناً أو فلانة يقصد من هذا منعها من الكلام أو الخروج، كونه يقصد من قوله: (عليه الطلاق أن لا يسافر) منع نفسه من السفر وما أشبه ذلك فهذا حكمه حكم اليمين عليه الكفارة وهي إطعام عشرة مساكين أو كسوتهم ولا يقع الطلاق على زوجته، أما إذا كان قصده إيقاع الطلاق قال هذا الكلام مقصوده التخويف من هذا الشيء ولكنه يقصد وقوع الطلاق قال: علي الطلاق أن لا تخرجي إلى بيت أهلك، علي الطلاق أن لا تكلمي فلاناً هو يقصد منعها ويقصد إيقاع الطلاق إذا فعلت، فإنه يقع الطلاق عليها. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7699/حكم-وقوع-الطلاق-في-غياب-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24511.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9550,"question":"هذه رسالة وردت إلينا من كمال كامل حسن مصري الجنسية يعمل في الدمام بالمملكة، يقول في رسالته: يوجد عندنا في مصر مشايخ عندما يحلف الرجل بالطلاق يذهب لهذا الشيخ ويضع يده في يده، ويقول له كلام وهو يردده، وبعد ذلك يقول له: خلاص قد حل اليمين، الرجاء أن تفيدونا عن صحة هذا بارك الله فيكم؟","title":"مسألة في الحلف بالطلاق","answer":"الجواب: هذا الكلام الذي ذكرته أيها السائل غير معقول! وضع اليد في اليد والكلام الذي يقوله الأستاذ أو العالم، مجرد كلام يقوله تقول: حل الطلاق هذا ليس بمعقول! ولا يعرف وجهه، لكن إذا كان يستفتيه فأفتاه بأن يفعل كذا ويفعل كذا يفتيه على الوجه الشرعي، يقول له: طلاقك هذا واقع أو طلاقك غير واقع؛ لأن شروط وقوعه لم تتوفر هذا محل نظر، يعني: لا بد يعرف وايش يقول الأستاذ حين وضع يده في يده ماذا يقول له؟ ماذا أفتاه به؟ كيف وقع الطلاق؟ لا بد من تفصيل.\nفإذا كان المستفتي سأل العالم أنا قلت لامرأتي: أنت طالق إن فعلت كذا، إن كلمت فلاناً، فقال له العالم: إذا كانت ما كلمت فلان ما صار طلاق، هذا صحيح.\nأو قال: أنت طالق إن أكلت كذا، أو إن شربت كذا فلم تشرب ولم تأكل هذا الشيء الذي منعها منه، ما وقع الطلاق.\nأو قال لها: أنت طالق إن زرت آل فلان يقصد منعها، فقال له العالم: عليك كفارة يمين، إذا كان قصده منعها على الصحيح من أقوال العلماء فيه كفارة يمين حكمه حكم اليمين؛ لأنه ما أراد إيقاع الطلاق وإنما أراد منعها من الزيارة مثلاً، فهذا فيه كفارة اليمين عند جمع من أهل العلم وهو الصواب، فالحاصل أنه لا بد من تفصيل، ومعرفة ماذا يقول العالم لهذا المستفتي، أما وضع اليد على اليد وقراءة شيء، أو اختار كلامًا ليس له تعلق بالفتوى، فهذا لا يحل شيئاً، ولا يترتب عليه إزالته حكم الطلاق. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7715/مسالة-في-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25512.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9551,"question":"هذه رسالة وردت من جمال عبدالباسط مصري الجنسية مقيم بالمملكة يقول: أنا أشرب الدخان وقد قلت: علي الطلاق، ثم علي الطلاق، ثم علي الطلاق، أن لا أشرب الدخان مرة أخرى، ثم شربته أفيدوني ما الحكم بارك الله فيكم؟","title":"حكم الحلف بالطلاق بقصد منع النفس من شيء ما","answer":"الجواب: أولاً: يا أخي! ننصحك بأن تدع الدخان؛ لأنه خبيث ومضر ضرره عظيم، فالواجب عليك تركه وأن تستعين بالله على ذلك، وأن تتعاطى الأمور التي تعينك على ذلك، حسب الطاقة، وأن تستفيد من الأطباء في ذلك لعلهم يفيدونك بشيء يعينك على تركه.\nأما هذا الطلاق فأنت فيه بين أمرين: إن كنت نويت فراق أهلك بالطلقات الثلاث إن شربت الدخان، فقد طلقت زوجتك ثلاث طلقات، إذا كنت نويت إيقاع الطلاق الثلاث عليها بهذا الكلام إذا شربت الدخان. أما إذا كنت لا، إنما أردت منع نفسك تقصد من هذا أن تمنع نفسك من الدخان، ما قصدت إيقاع الطلاق، ولا تريد الطلاق، ولكن تريد أن تمنع نفسك وأن تشدد على نفسك لعلك تتركه، لعلك تسلم من شره، فهذا له حكم اليمين، فعليك كفارة اليمين وهي إطعام عشرة مساكين أو كسوتهم، هذا هو الذي عليك ولا يقع الطلاق؛ لأنه لم يرد ولم يقصد وإنما أردت منع نفسك من الدخان، فإذا شربته فعليك التوبة إلى الله؛ لأنه محرم وعليك كفارة اليمين؛ لأنك ما قصدت إيقاع الطلاق وإنما قصدت منع نفسك من هذا الدخان، فعليك كفارة اليمين وهي كما تقدم إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، وهو كيلو ونصف تقريباً، أو كسوتهم بما يجزئهم في الصلاة كالقميص، أو إزارٍ ورداء، أو عتق رقبة لو وجدت الرقاب عتق رقبة، هذه كفارة اليمين. فمن عجز عن ذلك لأنه فقير لا يستطيع الإطعام ولا الكسوة ولا العتق فإنه يجزئه صيام ثلاثة أيام كما بين الله ذلك في كتابه العظيم في سورة المائدة. نعم.","link":"https://binbaz.org.sa/fatwas/7716/حكم-الحلف-بالطلاق-بقصد-منع-النفس-من-شيء-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25513.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9552,"question":"أولى الرسائل وردت من محمد الباز مصري الجنسية يعمل في الأردن يقول: بأنه متزوج منذ عشر سنوات ولديه ثلاثة أولاد، ولكن حصل منه أيمان بالطلاق منها يمين بالطلاق على أن يتزوج ولو آخر يوم في عمره، يقول: وقد كنت غاضباً ولم أشعر كيف حلفت بهذا اليمين، وبعد عشرين يوم حلفت يميناً آخر بالطلاق على زوجتي أن أطلقها ولم أحدد متى أطلقها، وكنت غاضباً ولم أشعر كيف حلفت هذا اليمين. أفيدوني أفادكم الله، مع أنني لن أطلق ولن أتزوج بارك الله فيكم؟","title":"حكم من حلف بالطلاق على زوجته أن يطلقها ولم يحدد متى يطلقها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وصفوته من خلقه وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فهذا الطلاق على أنك تتزوج وعلى أنك تطلق فيه تفصيل: فإن كنت أردت فراقها وإيقاع الطلاق إن لم تتزوج وقع طلقة في آخر حياتك ولك مراجعتها، ولا يقع الآن شيء لأنك قلت ولو في آخر حياتك، فإذا جاء في آخر الحياة قبل أن تموت بقليل تقع الطلقة إن كنت أردت إيقاع الطلاق، أما إن كنت ما أردت إيقاع الطلاق وإنما أردت حث نفسك على الزواج أو تكدير زوجتك وأنت ما أردت إيقاع الطلاق إنما أردت حث نفسك على الزواج فهذا في حكم اليمين عليك كفارة يمين ويكفي، أو إطعام عشرة مساكين أو كسوتهم، وهكذا قولك: عليك الطلاق أنك تطلقها، إذا كان مقصودك حث نفسك على أن تطلق وليس مقصودك إيقاع الطلاق إن لم تطلق فإن عليك كفارة يمين مثلما تقدم إطعام عشرة مساكين أو كسوتهم، عشرة، كل مسكين.. نصف الصاع تمر أو رز أو غيره من قوت البلد، أما إن كنت أردت إيقاع الطلاق في وقت معين نويته إن لم تطلقها فإنها طالق بهذه النية يقع طلقة إذا كنت نويت ذلك وإلا فالواجب كفارة يمين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7717/حكم-من-حلف-بالطلاق-على-زوجته-ان-يطلقها-ولم-يحدد-متى-يطلقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27001.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9557,"question":"هذه رسالة وردتنا من (م. د. أ) سوداني الجنسية مقيم في منطقة بدر قرب المدينة المنورة يقول: إذا طلق الرجل زوجته طلقة واحدة وأثناء طلاقه لها كان معهم بعض الإخوة، فقال هذا الرجل الموجود معهم: هي مرجوعة، لكن الرجل والمرأة سكتا ولم يتحدثا، فما الحكم هل تكون هذه رجعة أم لا؟","title":"حكم من طلق امرأته فقال شخص: هي مرجوعة وسكت المطلق","answer":"الجواب: ... ما تكون رجعة، ما دام المطلق ما قال شيء، إذا كان طلقها طلقة واحدة أو طلقتين فله مراجعتها إذا كان قد دخل بها ... قد خلى بها أو جامعها بعد العقد، إذا طلقها واحدة أو طلقها ثنتين فله المراجعة ما دامت في العدة قبل أن تحيض ثلاث حيض إذا كانت تحيض، وقبل أن يمر عليها ثلاثة أشهر إذا كانت لا تحيض كالكبيرة والصغيرة، فإن راجعها في العدة قبل أن تحيض ثلاث حيض أو قبل أن يمر عليها ثلاثة أشهر إن كانت لا تحيض ..... الصحيح يقول: راجعت امرأتي أو أمسكتها أو أنا مراجعها، إذا قال ذلك تمت الرجعة إذا كانت في العدة، والسنة أن يشهد على ذلك، السنة أن يشهد شاهدين على المراجعة، وأما قول الحاضر هي مرجوعة وهو ساكت المطلق ما ينفع، أما إن كان طلقها الطلقة الأخيرة الثالثة فلا رجعة لها بعد ذلك.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7722/حكم-من-طلق-امراته-فقال-شخص-هي-مرجوعة-وسكت-المطلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27006.mp3","categories":["الطلاق","الرجعة"]},{"id":9572,"question":"الرسالة السادسة في هذه الحلقة وردت من سائل ذكر اسمه فيصل فقط ولم يذكر عنواناً، يقول فيصل في رسالته: أنا أعرف أناساً يحبون السهر إلى وقت متأخر في الليل، فنمت عندهم مرة ولم أتحمل ضجتهم، فقمت من النوم غاضباً وأقسمت بالطلاق أنني لو كنت أدري أن هذه حالتهم ما دخلت البيت، وفي المرة الثانية كان لي عندهم أغراض وحاجات فاضطررت إلى أن أدخل البيت لآخذ هذه الأشياء من عندهم، فما الحكم في مثل هذه الحال؟","title":"حكم من حلف بالطلاق على شيء مضى","answer":"الجواب: ما دمت أقسمت أنك لو عرفت حالهم لم تدخل عليهم أقسمت بالطلاق وأنت على قصدك صحيح ليس كاذباً فليس عليك شيء، أما دخولك الأخير فليس له تعلق بهذا؛ لأنك أقسمت على الشيء الماضي أنك لو علمت لم تدخل عليهم، أما دخولك الأخير فلا تعلق له بهذا الطلاق؛ لأنك لم تقل: علي الطلاق لا أدخل عليهم، وإنما قلت: علي الطلاق لو علمت حالهم ما جلست عندهم أو ما نمت عندهم فليس عليك شيء. نعم.\nوبهذه المناسبة ينبغي لأهل الإسلام أن يدعوا هذا السهر وأن يحذروا السهر، فإن السهر مضرته عظيمة، وقد زجر النبي ﷺ عن السمر بالليل وكره النوم قبل العشاء وبعدها.. وكره النوم قبلها والحديث بعدها، فينبغي للمؤمن ألا يسهر إلا من حاجة كسهر في طلب العلم لا يضره أو مع الضيف سهراً لا يضر، أما السهر الذي لسماع التلفاز أو مشاهدة التلفاز أو قيل وقال أو أشياء لا ضرورة إليها فينبغي له ألا يسهر، بل ينبغي له أن يجاهد نفسه حتى يتقدم بالنوم فينشط في قيامه آخر الليل وفي قيامه لصلاة الفجر، وإذا كان السهر يجره إلى ترك صلاة الفجر مع الجماعة حرم ذلك، ولو كان في قراءة القرآن ولو كان في طلب العلم، إذا كان السهر يضره ضرراً يوقعه في ترك صلاة الفجر مع الجماعة، أو ترك صلاتها في وقتها حتى لا يصلي إلا بعد طلوع الشمس هذا محرم.","link":"https://binbaz.org.sa/fatwas/7732/حكم-من-حلف-بالطلاق-على-شيء-مضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24704.mp3","categories":["الطلاق"]},{"id":9575,"question":"الرسالة السادسة في هذه الحلقة وردت من سائل ذكر اسمه فيصل فقط ولم يذكر عنواناً، يقول فيصل في رسالته: أنا أعرف أناساً يحبون السهر إلى وقت متأخر في الليل، فنمت عندهم مرة ولم أتحمل ضجتهم، فقمت من النوم غاضباً وأقسمت بالطلاق أنني لو كنت أدري أن هذه حالتهم ما دخلت البيت، وفي المرة الثانية كان لي عندهم أغراض وحاجات فاضطررت إلى أن أدخل البيت لآخذ هذه الأشياء من عندهم، فما الحكم في مثل هذه الحال؟","title":"حكم من حلف بالطلاق على شيء مضى","answer":"الجواب: ما دمت أقسمت أنك لو عرفت حالهم لم تدخل عليهم أقسمت بالطلاق وأنت على قصدك صحيح ليس كاذباً فليس عليك شيء، أما دخولك الأخير فليس له تعلق بهذا؛ لأنك أقسمت على الشيء الماضي أنك لو علمت لم تدخل عليهم، أما دخولك الأخير فلا تعلق له بهذا الطلاق؛ لأنك لم تقل: علي الطلاق لا أدخل عليهم، وإنما قلت: علي الطلاق لو علمت حالهم ما جلست عندهم أو ما نمت عندهم فليس عليك شيء. نعم.\nوبهذه المناسبة ينبغي لأهل الإسلام أن يدعوا هذا السهر وأن يحذروا السهر، فإن السهر مضرته عظيمة، وقد زجر النبي ﷺ عن السمر بالليل وكره النوم قبل العشاء وبعدها.. وكره النوم قبلها والحديث بعدها، فينبغي للمؤمن ألا يسهر إلا من حاجة كسهر في طلب العلم لا يضره أو مع الضيف سهراً لا يضر، أما السهر الذي لسماع التلفاز أو مشاهدة التلفاز أو قيل وقال أو أشياء لا ضرورة إليها فينبغي له ألا يسهر، بل ينبغي له أن يجاهد نفسه حتى يتقدم بالنوم فينشط في قيامه آخر الليل وفي قيامه لصلاة الفجر، وإذا كان السهر يجره إلى ترك صلاة الفجر مع الجماعة حرم ذلك، ولو كان في قراءة القرآن ولو كان في طلب العلم، إذا كان السهر يضره ضرراً يوقعه في ترك صلاة الفجر مع الجماعة، أو ترك صلاتها في وقتها حتى لا يصلي إلا بعد طلوع الشمس هذا محرم.","link":"https://binbaz.org.sa/fatwas/7732/حكم-من-حلف-بالطلاق-على-شيء-مضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24704.mp3","categories":["الطلاق"]},{"id":9579,"question":"أولى الرسائل في هذه الحلقة وردت من صلاح أحمد محمد، مصري الجنسية مقيم بالمملكة الأردنية الهاشمية يقول: حلفت بالطلاق وأنا في شبه الغضب على أن أسافر إلى مصر في رمضان المقبل، فهل إذا جاء رمضان المقبل وكان في العمر بقية ولم أسافر هل تعتبر طلقة؟ وإذا كانت تقع وسافرت فهل ترتفع، أفيدوني أفادكم الله؟","title":"من حلف بالطلاق أن يسافر هل يقع لو سافر؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الطلاق المعلق فيه تفصيل: فإن كنت أيها السائل أردت بذلك التأكيد على نفسك وحثها على السفر، ولم ترد إيقاع الطلاق على زوجتك إن لم تسافر فهذا حكمه حكم اليمين في أصح قولي العلماء، وعليك كفارتها إن لم تسافر ولا يقع شيء، وزوجتك باقية في عصمتك، هذا إذا كنت إنما أردت التأكيد على نفسك وحثها على السفر في رمضان.\nأما إن كنت أردت إيقاع الطلاق إن لم تسافر فإنه يقع طلقة على زوجتك واحدة، ولك مراجعتها في الحال بإشهاد اثنين من المسلمين الطيبين على أنك راجعت زوجتك فلانة، تخبرهم بالواقع وتقول: راجعتها، إلا إذا كنت قد طلقتها قبلها طلقتين فهذه تكون الثالثة ما فيها مراجعة، أما إذا كنت ما طلقتها قبل هذا طلقتين فإنك تراجعها إذا كنت أردت إيقاع الطلاق إن لم تسافر. والله أعلم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7744/من-حلف-بالطلاق-ان-يسافر-هل-يقع-لو-سافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24801.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9595,"question":"هذه رسالة وردتنا من سائلةٍ رمزت لنفسها بالحائرة (س. ش) من الرياض، هذه السائلة في الحقيقة تعرض مشكلةً طويلة تتلخص في أنها تزوجت من مدة لا تتجاوز سبعة أشهر من إنسانٍ لم تكن مقتنعة به في الأول، ولكن بعد الزواج أحبته وحملت منه، لكنها أجهضت بسبب سوء حالتها الصحية والنفسية، وتقول: إن سبب سوء الحالة: هو أنها سكنت مع عائلته الكبيرة وهي موظفة، وتخرج من عملها متعبة فتجد المشاكل في المنزل من أهل زوجها، وتقول: إنهم يجبرونها على أشياء لا ترغب فيها وهي محرمة؛ كالخروج أمام إخوة زوجها الكبار، والجلوس معهم والأكل معهم، مع أنه لا يجوز شرعاً، والرسول ﷺ قال: الحمو الموت تقول: قد لاقيت أنواعاً من العذاب عند هؤلاء، وصبرت واستسلمت، ولكن زادت الأمور عن حدها المعقول، ووصل الأمر بهم أن اتهموني في عرضي وشرفي، وقلت لزوجي: ما الحل؟ قال: تحملي واصبري، ولكن عجزت وكان سلبياً زوجي معي، فهو يخرج من البيت ويتركني، ولا يعود إلا بعد منتصف الليل، فقررت أن أخرج أنا وهو في بيت مستقل فاعترض والده ووالدته، وهدداه بأن يحرماه من الميراث إن خرج في بيت مستقل، فطلب منه أبوه أن يعيدني إلى أهلي، وأنا الآن عند أهلي منذ ثلاثة أشهر، وقد تدهورت حالتي الصحية وحالة زوجي أيضاً، ولم يقم بإرجاعي ولم يسأل عني بالرغم أن كلاً منا يحب الآخر، بسبب خوفه من والديه ومن أخيه الأكبر، فتسأل، تقول: ما الحل في هذا؟ هل أطلب الطلاق منه، رغم أنني أريده وهو يريدني، أم ماذا أفعل؟ ولكن لا تقولوا جزاكم الله خيراً: عودي وعيشي مع أهله، فليس من المعقول أن أعيش معهم بعد أن اتهموني في عرضي، وأنا لا أوافق على الخروج أمام إخوته الرجال أبداً مهما كانت الظروف، أفيدوني أفادكم الله؟","title":"أساء أهله معاملتها ويرفضون انتقالها مع زوجها في بيت مستقل","answer":"الجواب: إذا كان الواقع هو ما ذكرته السائلة، فلا مانع من خروجه في بيت مستقل، ولا يلزمه طاعة والديه في هذا، لأن والديه لم ينظرا إلى حاله، ولم يرحما حاله، ولم يقدرا ظروفه التي أشارت إليها السائلة، فلا حرج عليه أن يخرج في بيتٍ مستقل، ويستسمح والديه، وإن أبيا أن يسمحا فلا حرج عليه، ولكن يجاهد في استرضائهما، والحرص على مخاطبتهما بالتي هي أحسن، وأما الميراث فالله أعلم من يموت الأول، وليس لهما أن يحرمانه، ليس لهما أن يحرماه الميراث، حتى لو أوصيا بحرمانه، لا حق لهما في ذلك، والوصية بحرمانه باطلة، ليس الأمر إليهما، متى ماتا قبله ورثهما وإن أبيا، فلا ينبغي أن يخاف من هذا، ولكن المهم عدم العقوق، وإذا كانا لم يقدرا حاله فخروجه حينئذٍ ليس بعقوق، لأن الرسول ﷺ يقول: إنما الطاعة في المعروف فعليه أن يخرج إن شاء، ويكون في بيتٍ مستقل، ويعيدك إلى المسكن المناسب، ويسترضي والديه حسب الطاقة والإمكان في المستقبل، وعلى والديه أن يرضيا، وأن يساعداه على ما يجمع شمله بأهله وألا يشددا عليه في هذا.\nوأما خروجك بين إخوته، وبين غير محارمك كاشفةً، وإلزامهم لك بذلك، فهذا منكر لا يجوز، وهذا يدل على ضعف إيمانهما، إن كنت صادقة فيما قلت، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: بارك الله فيكم، ولكن على فرض أنه لم يستجب ولم يخرج، وهي باقية عند أهلها، يجوز لها طلب الطلاق؟\nالشيخ: إذا كان الحال كما ذكرت لها طلب الطلاق. نعم، لأنها معذورة.\nالمقدم: ولا تدخل في الوعيد؟\nالشيخ: لا ما تدخل.. لها طلب الطلاق؛ لأنها معذورة، بسبب ما ذكرت. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7761/اساء-اهله-معاملتها-ويرفضون-انتقالها-مع-زوجها-في-بيت-مستقل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27102.mp3","categories":["الطلاق","الحقوق الزوجية"]},{"id":9608,"question":"وهذه رسالة وردت إلينا من الأخ أبو قرشي سوداني مقيم بجدة، يقول في رسالته: كثير من الناس يطلقون زوجاتهم، وتكون الطلقة رجعية، وعندما يطلقها تذهب فوراً لمنزل أهلها ليلاً أو نهاراً، فهل هذا يجوز؟ وماذا تفعل المرأة بعد طلاقها طلقةً رجعية؟ هل تقعد في بيتها أم أن عليها مفارقة بيت زوجها أفيدونا أفادكم الله؟","title":"حكم خروج المطلقة الرجعية من بيت زوجها في العدة","answer":"الجواب: الواجب على المطلقة طلاقاً رجعياً أن تبقى في البيت عند زوجها؛ لعله يراجعها، وليس له إخراجها، وليس لها الخروج؛ لقول الله سبحانه: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ [الطلاق:1] فالله سبحانه بين أنهن لا يخرجن ولا يخرجن، هذا هو الواجب على المرأة أن تبقى في البيت حتى تنتهي العدة، وليس لها الخروج، وليس له إخراجها أيضاً.\nأما إذا كانت بائنة طلقها آخر ثلاث؛ فإنها تخرج إلى بيت أهلها، وإن جلست في بيت زوجها وهي مصونة عندها نساء بحيث يعني لا يكون خطراً من جهة صلته بها وهي بائن فلا حرج، إن خرجت فلا بأس فقد طلقت فاطمة بنت قيس واعتدت خارج بيت زوجها، وقال لها النبي ﷺ: إنه ليس لك عليه سكنى كنه ولا نفقة لأنه قد أبانها طلق آخر ثلاث.\nوأما الرجعية فكما تقدم الواجب بقاؤها في البيت، وليس لها الخروج وليس له إخراجها؛ لأن هذا وسيلة إلى رجعته لها، قد قال الله سبحانه بعد ذلك. بعد ما ذكر النهي عن خروجها وإخراجها قال: لا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أَمْرًا [الطلاق:1] والمراد يعني: الرجعة، ربما راجعها وسهل عليه أمر المراجعة؛ لأنها في البيت.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7773/حكم-خروج-المطلقة-الرجعية-من-بيت-زوجها-في-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24904.mp3","categories":["الطلاق","العِدَد"]},{"id":9623,"question":"أولى رسائل هذه الحلقة وردت من المستمعة (أ. س) من محافظة كركوك من العراق، تقول في رسالتها: عقد قراني على شاب ولم يدخل بي بعد، وأنا الآن أريد الطلاق منه لأسباب عديدة، منها: أنه رجل غير مؤدب وغير مثقف، فأثناء جلوسنا في المجلس يشتمني ويسبني أمام الناس هذا من ناحية، ومن ناحية أخرى: مضى على عقد النكاح بيننا أكثر من خمسة أشهر لكنه لا يصرف علي ولا يعطيني فلساً واحداً، فأضطر إلى أن أمد يدي إلى والدي ووالدتي وأطلب النقود منهما، ومن ناحية ثالثة: فهو رجل لا يصلي وإن صلى فيصلي يومين ويتركها شهر، فماذا عساي أن أفعل فقد نصحته مراراً ولم يفد معه، أفيدوني أفادكم الله هل يجوز لي الطلاق أم أنا آثمة بارك الله فيكم؟","title":"حكم طلب المرأة الطلاق من زوجٍ لا يصلي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا كان حال الزوج هو ما ذكرت أيها السائلة! من كونه يصلي بعض الأحيان ولا يصلي في أكثر الأحيان، فإن هذا لا يجوز لك أن تبقي معه؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، ولو لم يجحد وجوبها.\nفالواجب عليك التخلص منه، ولا يجوز لك الدخول عليه، ولا يجوز بقاء هذا النكاح، بل هو والحال ما ذكر عقد باطل في أصح قولي العلماء، وعليك أن تحذري أن يمسك أو يقربك، وإذا لم يتيسر الطلاق ففي إمكانك أن ترفعي الأمر إلى المحكمة لهذه العلة، مع كونه أيضاً خبيث اللسان سباباً شتاماً فهذه علة أخرى، لكن علة ترك الصلاة أكبر وأعظم، نسأل الله السلامة والعافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7789/حكم-طلب-المراة-الطلاق-من-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25001.mp3","categories":["الطلاق","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":9630,"question":"هذه رسالة من سعيد السيد حسن من جمهورية مصر العربية مقيم في ...... في المملكة، يقول: في يوم من الأيام تشاجرت مع زوجتي وقلت لها: علي الطلاق بالثلاث لن تبيتي هنا، يعني: في بيت الزوجية، ولكن أصرت على البقاء لظروف خلاف مع والديها بسببي، وهجرتها لمدة عشرة أيام ثم جامعتها فهل علي إثم؟ وهل علي كفارة يمين أم أن هذا طلاق أفيدوني أفادكم الله؟","title":"حلف بالطلاق لمنع زوجته من المبيت عند والدها","answer":"الجواب: هذا الطلاق، وأشباهه يختلف بحسب النية؛ لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى فإن كان قصدك أيها السائل! منعها من المبيت ولم تقصد إيقاع الطلاق، وإنما أردت منعها وتحذيرها وتخويفها لعلها تخرج وتبيت خارج البيت، فهذا حكمه حكم اليمين وعليك كفارة اليمين.\nأما إن كنت أردت إيقاع الطلاق إن لم تخرج فإنه يقع عليها طلقة ولك مراجعتها، وجماعك لها بنية الرجعة رجعة، إلا أن تكون قد طلقتها قبل هذا طلقتين فهذه تكون الثالثة فلا تحل إلا بعد زوج؛ لقول الله جل وعلا: فَإِنْ طَلَّقَهَا [البقرة:230] يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230].\nفالواجب عليك النظر في هذا الأمر، وخوف الله  ومراقبته، فإن كانت الطلقة هذه هي الأخيرة وقبلها طلقتان وأنت قصدت إيقاع الطلاق فقد تمت الثلاث، أما إن كنت ما قصدت إيقاع الطلاق وإنما نويت إلزامها بالخروج وعدم المبيت وتخويفها بالطلاق، فهذا له حكم اليمين، في أصح قولي العلماء وعليك كفارة اليمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو حنطة أو غيرها من قوت البلد، أو كسوتهم تكسو كل واحد قميصاً أو إزاراً ورداء، أو عتق رقبة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7801/حلف-بالطلاق-لمنع-زوجته-من-المبيت-عند-والدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25009.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9643,"question":"السؤال الرابع في رسالة الأخ (ح. ع. س) من الأردن يقول فيه: هل المرأة المسلمة إذا سبت زوجها أو دين زوجها أصبحت طالق في الشرع كما نسمع من أكثر الناس أفيدونا أفادكم الله؟","title":"حكم القول بطلاق المرأة إذا سبت زوجها أو دينه","answer":"الجواب: إذا سبت زوجها لا، لا تكون طالق ولكن عليها التوبة إلى الله واستسماح زوجها، فإذا سمح عنها فلا بأس، وإن سبها مثلما سبته قصاصًا لا يزيد على ذلك فلا بأس، وإن سمح عنها فهو أفضل، لأن الله يقول: وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237] والنبي ﷺ يقول: ما زاد الله عبدًا بعفو إلا عزًا.\nأما سبها لدين زوجها وهو مسلم فهذا كفر نسأل الله العافية، إذا كان مسلم وهي مسلمة وسبت دين زوجها هذا سب للإسلام نعوذ بالله، فلا يتساهل معها بل تؤدب وتضرب على هذا العمل السيئ وتستتاب، فإن تابت عن عملها السيئ وإلا وجب أن تقتل، وجب على ولي الأمر قاضي البلد وأمين البلد يستتيبوها فإن تابت وإلا قتلت؛ لأن سب الدين سب الإسلام من أعظم أنواع الكفر ومن نواقض الإسلام نسأل الله العافية، وهكذا سب الرسول ﷺ، سب القرآن. نعم.","link":"https://binbaz.org.sa/fatwas/7809/حكم-القول-بطلاق-المراة-اذا-سبت-زوجها-او-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19406.mp3","categories":["الطلاق","نواقض الإسلام"]},{"id":9650,"question":"تسأل الأخت من مكة أيضاً وتقول: أنا متزوجة من مدة عشر سنوات، وقد حصل بيني في يوم من الأيام وبين زوجي خصام، حيث قال لي: أحضري طعام العشاء فرفضت طاعته، وقلت له: لن أحضر لك الطعام حتى توصلني إلى أهلي، فوقف معي ساعتين ثم اتجه إلى منطقة أخرى ولم يقل لي أي شيء، فهل هو آثم وأنا آثمة في عدم طاعته، أم لا، أفيدوني وماذا أفعل حتى أرضي زوجي وفقكم الله؟","title":"رفضت طاعة زوجها وتخاف من الإثم","answer":"الجواب: الواجب على المرأة السمع والطاعة لزوجها في المعروف، وإحسان الخلق، وطيب الكلام، وتنفيذ الأوامر من إحضار الطعام أو غيره من الشاي أو القهوة أو حاجات أخرى مما أباح الله، هذا هو الواجب على الزوجة، والواجب على الزوج كذلك أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، كما قال الله سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال الله : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] فحق الزوج أكبر وهي لها حق عليه أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، بالإنفاق عليها نفقة أمثالها، كسوتها كسوة أمثالها، يخاطبها بالكلام الطيب لا بالسب واللعن، بل بالكلام الطيب والأسلوب الحسن، وهي كذلك تخاطبه بالكلام الطيب والأسلوب الحسن، وتسمع وتطيع في أوامره، لا تعصيه في الأوامر التي ليس فيها حرج شرعاً، ليس فيها منكر، كإحضار الطعام، إحضار الشاي، عمل شيء آخر مما أباح الله مما جرت به العادة، أن تفعله الزوجة مع زوجها، هذا هو الواجب على المرأة حتى تستقيم الأحوال، وحتى تستمر العشرة الطيبة.\nأما إذا أمرها بما لا يجوز كأن يقول لها: تحضر له الخمر أو الدخان أو ما أشبهه مما حرم الله، أو تسمع معه الأغاني والملاهي لا يلزمها ذلك؛ لأن الله يقول جل وعلا: وَلا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12] ويقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فإذا أمرها بالمعصية ليس لها أن تطيعه، ولكن ترد عليه بالرد الطيب: يا فلان! هذا لا يجوز، هداك الله، أعاذك الله من الشيطان، هذا أمر لا يجوز لي ولا لك، وليس لي أن أعينك على ما حرم الله، يكون عندها أسلوب حسن تعضه وتذكره بالله عز وجل، ولكن لا تطيعه في المعاصي، وعليها أن تخدمه الخدمة المعروفة المعتادة بين أمثالهم؛ لأن الأسر تختلف فإذا كان مثلها يخدم مثله والعادة أنها تخدمه في الأسر المماثلة لهم في بلادهم فإنها تخدمه.\nأما إذا كانت من أسرة تخدم فإن عليه أن يخدمها إذا استطاع ذلك عليه أن يخدمها عملاً بالعادة المعروفة؛ لأن الشرط العرفي كالنطقي ولكن إذا تسامحت وخدمت كما خدمت فاطمة رضي الله عنها بنت النبي ﷺ زوجها علي ، كانت تطحن وتخدم وتصلح الطعام رضي الله عنها وأرضاها، فهكذا ينبغي للزوجة أن تتسامح وأن تخدم حتى ولو كان مثلها يخدم إذا تنازلت وتسامحت كان هذا من طيب الأخلاق ومن حسن السيرة، ومن أسباب استمرار العشرة، لكن إذا كان مثلها يخدم وأسرة تخدم وتيسر للزوج أن يخدمها فذلك حق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7821/رفضت-طاعة-زوجها-وتخاف-من-الاثم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25106.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9653,"question":"الرسالة الثالثة في هذه الحلقة وردت من المرسل عبدالله علي محمد اليماني مقيم في جدة، يقول في رسالته: لي زوجة وأولاد في اليمن وحصلت مشاكل بين أهلي وزوجتي، فكتبت ورقة طلاق إلى قاضي المحكمة بجدة، وأحضرت اثنين من الشهود، لكن القاضي لم يحضر إلى المحكمة في ذلك اليوم، بعد ذلك عدلت عن الطلاق، فهل يكون الطلاق وقع بذلك أم لا أفيدوني أفادكم الله؟","title":"بعض أحكام الطلاق بالكتابة","answer":"الجواب: إذا كنت كتبت الطلاق فإنه يقع الطلاق؛ لأن الطلاق يقع بالكتابة ويقع باللفظ، فإذا كنت قد كتبت الطلاق وقع الطلاق، فإن كان واحدة فهي واحدة، وإن كان طلاقاً مكرراً كأن قلت: طالق ثم طالق ثم طالق وقعت الثلاث، فإن كانت الثلاث بلفظ واحد قلت: هي طالق بالثلاث، أو مطلقة بالثلاث، فهذا يحسب واحدة على الصحيح من أقوال أهل العلم، يحسب واحدة فقط ولك المراجعة إذا كانت لم تطلق قبل هذا، إذا كنت ما طلقتها قبل هذا ثنتين طلقتين، فلك المراجعة ما دامت في العدة.\nنعيد: أولاً: إذا كنت كتبت الطلاق فإنه يقع الطلاق، لكن إن كان المكتوب واحدة وقعت واحدة، وإن كان بالثلاث بلفظ واحد كتبت: مطلقة بالثلاث، أو طالقة بالثلاث وقعت واحدة أيضاً على الصحيح من أقوال أهل العلم، ولك المراجعة تشهد اثنين أنك مراجعها قبل أن تخرج من العدة، إذا كنت ما طلقتها قبل هذا طلقتين.\nأما إن كان المكتوب هي طالق ثم طالق ثم طالق، ونحو ذلك فهذا يقع به الثلاث، وليس لك الرجعة إلا بعد زوج، بعد زوج وإصابة، يعني: إلا بعد زوج شرعي يدخل بها ويطؤها ثم يفارقها بموت أو طلاق. نعم.\nالمقدم: وإن كان المكتوب معروف، يقول: أرغب في طلاق زوجتي، أو أن تجروا لي طلاق زوجتي؟\nالشيخ: ما يصير طلاق، إذا كان المكتوب إنه يريد أن يطلق عند القاضي يريد، أو يقصد أن يكتب الطلاق، أو قصده، أن أكتب الطلاق عندكم، فهذا ما يكون طلاق، يكون عزم على الطلاق ولا يكون طلاق متى عدل عنه فإنه لا يقع به شيء، متى عدل عن عزمه فإنه لا يقع به شيء، إذا كان مثلاً كتب للقاضي قال: أريد أن أكتب طلاق زوجتي، أو عزمي أن أكتب طلاق زوجتي، أو ما أشبه هذه العبارات هذا يكون نية وعزم وليس بطلاق.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7818/بعض-احكام-الطلاق-بالكتابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25103.mp3","categories":["الطلاق"]},{"id":9671,"question":"الرسالة التالية وصلت من الأخ السيد نصر أحمد سعيد والأخ خالد أحمد علام من جمهورية مصر العربية ومقيمين بالأردن- عمان الرسالة تحتوي على موضوعين السؤال الأول يقول فيه: ما رأيكم في رجل حلف يمين طلاق واحد بالثلاثة على أخ مسلم آخر يعمل شيئًا ما ولكن الشيء لم ينفذ، فهل اليمين يعتبر نافذة في حد ذاته على امرأته؟ وما حكم الإسلام إذا لم ينفذ بذلك اليمين في حد ذاته أفيدونا أفادكم الله؟","title":"حكم الحلف بالطلاق بالثلاث وعدم إنفاذه","answer":"الجواب: إذا حلف الإنسان بالطلاق الثلاث على أن فلان يفعل كذا ويفعل كذا كأن يقول: علي الطلاق بالثلاث أن تكلم فلان، علي الطلاق بالثلاث أن تصنع الوليمة الفلانية، علي الطلاق مثلًا أن تتزوج فلانة، فهذا ينظر في قصده، فإن كان قصده التلزيم والتأكيد وليس قصده إيقاع الطلاق فهذا يكون حكمه حكم اليمين فيه كفارة اليمين إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة فإن عجز صام ثلاثة أيام، أما إن كان قصده إيقاع الطلاق إن لم ينفذ هذا الشيء قصده إيقاع الطلاق فهذا يقع به طلقة واحدة على الصحيح ويراجع زوجته إذا كان ما طلقها قبل هذا طلقتين. نعم.","link":"https://binbaz.org.sa/fatwas/7837/حكم-الحلف-بالطلاق-بالثلاث-وعدم-انفاذه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19419.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9672,"question":"يضيف الإخوة السائلين في رسالتهم: ما حكم الإسلام في رجل حلف يمين الطلاق وهو غاضب؟ وهل يشترط سماع امرأته يمين الطلاق بأذنها أم لا أفيدونا أفادكم الله؟","title":"حكم طلاق الغاضب","answer":"الجواب: يختلف الأمر، إذا كان الغضب شديدًا يشبه المجنون ما يعقل ما يقول هذا لا يقع عند جميع أهل العلم طلاقه غير واقع لاغي؛ لفقد عقله.\nالحال الثاني: يكون غضبه شديدًا، قد تملك عليه شعوره وملك عليه نفسه وقلبه ولا يستطيع التخلص من شدة الغضب بسبب المسابة بينه وبين زوجته أو بينه وبين أبيها مسابة أو مضاربة التي أوجبت شدة الغضب فالصحيح أنه لا يقع.\nأما إن كان غضبه عاديًا فإنه يقع، هذا الصواب في مسألة الغضب بهذا التفصيل كما حرر ذلك ابن القيم رحمه الله في كتابه زاد المعاد وغيره، وكما حرر ذلك أيضًا أبو العباس ابن تيمية رحمة الله عليهما. نعم.","link":"https://binbaz.org.sa/fatwas/7838/حكم-طلاق-الغاضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19420.mp3","categories":["الطلاق"]},{"id":9673,"question":"يقول هذا السائل أيضاً: لي زوجة تزوجتها من مدة وقام أهلها بشكوى ضدي فقمت بطلاقها عند الغضب ثلاث مرات، وهذا كان في لحظة غضب، هل يصح لي أن أرجعها وأنا لم أنجب منها شيء، أفيدوني أفادكم الله؟","title":"حكم مراجعة من طلقت ثلاثاً في حال الغضب","answer":"الجواب: راجع المحكمة وتكتب تفتيك المحكمة في هذا أو تكتب لنا وننظر في الأمر إن شاء الله، محكمة بلادك، تراجعها أنت والمرأة ووليها حتى يفتيك القاضي في ذلك، أو تكتب لنا كتابة مفصلة من عند القاضي أو إلينا ونحن نحيلها للقاضي حتى يعطينا النتيجة. نعم.\nالسؤال: بارك الله فيكم الحقيقة الأخ فالح بن سعيد البلوي له سؤالان أيضاً في هذه الرسالة كلاهما فيه خصومة من حيث الإرث، ومن حيث خصومة بينه وبين إخوته.\nالجواب: هذه المحاكم هذه عند المحاكم.\nالمقدم: فعن أمر سماحتكم يحال إلى المحكمة ويراجع المحكمة.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7901/حكم-مراجعة-من-طلقت-ثلاثا-في-حال-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25410.mp3","categories":["الطلاق"]},{"id":9688,"question":"يسأل أخيراً ويقول: حلفت بالطلاق ثلاثاً على والدتي لا تفعل كذا ففعلت، وأنا أقصد من هذا منع والدتي، وذهبت إلى أحد العلماء فقال لي: تحسب عليك طلقة وَردَّ إليَّ زوجتي بيني وبينه والله شاهد على ذلك وليس فيه شهود، وقال لي: تعطي زوجتك شيئاً من النقود، وأعطيتها أيضاً مثلما قال لي: وسمعت في بعض حلقات برنامجكم إذا كان القصد ليس الطلاق فيحتسب علي كفارة يمين، أنا أستفسر عن هذا وقد مضى عليه ست سنوات أفيدوني أفادكم الله؟","title":"حكم الحلف بالطلاق لقصد المنع أو الحث","answer":"الجواب: إذا كنت قد قنعت بالفتوى السابقة واطمأن قلبك إليها وأخذت بها فاحتسبها طلقة كما أفتاك الذي أفتاك، والحمد لله، أما في المستقبل لو وقع شيء من هذا وأنت قصدك اليمين ليس قصدك إيقاع الطلاق وإنما قصدك منع الشخص من فعل ما حلفت عليه في الطلاق، أو حثه على فعله، كأن تقول: علي الطلاق أن تفعل كذا، أو تعطيني كذا وقصدك حثه على فعل الشيء، أو منعه منه كأن تقول: والله لا تفعل كذا وكذا، أو علي الطلاق لا تفعل كذا وكذا، فخالفك وأنت قصدك إنما هو الحث والمنع ليس قصدك إيقاع الطلاق، فإنه لا يقع الطلاق وعليك كفارة اليمين.\nلكن هذه الفتوى التي صدرت من المفتي وأنت اقتنعت بها تمضي على حالها. نعم.\nالمقدم: بارك الله فيكم، لا أدري سماحة الشيخ تساهل الناس بمثل هذا اللفظ بقولهم: عليه الطلاق لا تفعل، أو عليه الطلاق افعل، لو نبهتم إليه؟\nالشيخ: تقدم التنبيه على هذا وأنه مكروه لا ينبغي، ينبغي للمؤمن التباعد عن الطلاق والتلاعب بالطلاق، ينبغي له أن يحذر الحلف بالطلاق والإكثار من الطلاق في كلامه مع أهله أو غيرهم؛ لأن الطلاق أمره خطير وقد يسبب فرقته لأهله، فينبغي له الحذر من ذلك، وأن لا يطلق إلا عن حاجة وعن بصيرة وعن اقتناع بالطلاق، وإذا طلق طلق واحدة فقط، لا يطلق بالثلاث، الواجب أنه يقتصر على الواحدة فقط، هذه السنة، والرسول ﷺ غضب على من طلق بالثلاث، فينبغي للمؤمن إذا أراد الطلاق أن يحاسب نفسه وأن يتأنى ولا يعجل، فإذا عزم على الطلاق طلق واحدة فقط، في حال كون المرأة طاهراً طهراً لم يجامعها فيه، أو في حال كونها حاملاً، هذا هو السنة، الطلاق يكون في حالين:\nإحداهما: أن تكون حاملاً.\nالثانية: أن تكون طاهراً طهراً لم يجامعها فيه وليست حاملاً، هذا محل الطلاق السني، والسنة يكون واحدة فقط، طلقة واحدة فقط، أما الطلاق في الحيض أو في النفاس أو في طهر جامعها فيه فهو طلاق منكر لا يجوز، لقول الله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] قال العلماء: معناه: طلقوهن طاهرات من غير جماع، هذا معنى: طلقوهن لعدتهن أن يكن طاهرات من دون جماع أو حبالى هذا طلاق للعدة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7865/حكم-الحلف-بالطلاق-لقصد-المنع-او-الحث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25306.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9711,"question":"يسأل أيضاً ويقول: عندي بنت عقدت لها على أحد الرجال، وكان بيني وبينه وبين ابنتي وعد، لكنه أخلف الوعد، قبل أن يدخل بها، مما جعل غضبي يشتد عليه وغضب ابنتي أيضاً فاضطررت أن أقول: بالطلاق لن تكوني له زوجة، أفيدوني أفادكم الله؟","title":"توضيح ونصيحة في عدم التعجل بالحلف بالطلاق","answer":"الجواب: هذا فيه تفصيل: إن كان الوعد أنه يصلي ويستقيم ويتوب إلى الله من أعماله السيئة فهذا الوعد يجب أن يطالب به، فإن تاب واستقام ورجع إلى الله فأوفوا له بالزوجية إذا كان تركه للصلاة بعد الزواج، أما إن كان تركه للصلاة قبل الزواج فالعقد لا يصح في أصح قولي العلماء؛ لأنه لا يجوز تزويج المسلمة المصلية بشخص لا يصلي في أصح أقوال أهل العلم.\nأما إن كان الوعد بأنه يترك السكر أو يترك أمراً آخر ليس بمحرم فهذا محل نظر وفي الإمكان المصالحة بينكم وبينه وحثه على التوبة من معصيته لعله يتوب ويستقيم.\nأما طلاقك ففيه تفصيل: إن كنت أردت منعها من بقائها معه ولم ترد إيقاع الطلاق وإنما قصدت منعها حتى ترتدع إذا سمعت الطلاق، فهذا عليك فيه كفارة اليمين ولا يقع الطلاق، أما إن كنت أردت إيقاع الطلاق إن أعدتها إليه، فإنه يقع عليك على زوجك طلقة واحدة، يقع بهذا طلقة واحدة على الزوجة، ولك أن تراجعها ما دامت في العدة، إذا كنت لم تطلقها قبل هذا طلقتين، ونوصيك بعدم العجلة في الأمور، وأن لا تطلق إلا على بصيرة، وإذا غضبت فقل: أعوذ بالله من الشيطان الرجيم ولا تعجل في الأمور، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7860/توضيح-ونصيحة-في-عدم-التعجل-بالحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25302.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9742,"question":"أولى رسائل هذه الحلقة وردت من المستمع (ف. ع. م. ص) يقول في رسالته: أنا رجل متزوج وبعد زواجي بحوالي ست سنوات، سافرت إلى بلد أخرى من أجل السعي والبحث عن الرزق، وكنت أصلي وأصوم ولله الحمد، ولكن لعب بي الشيطان ومارست العادة السرية؛ لأنني بعيد عن زوجتي، وبعد هذا قلت: هذا عمل حرام ولا بد أن أتركه، فبدأت أصلي وأصوم وقلت: حلفت علي الطلاق بالثلاث لا أفعل هذا العمل مرة ثانية، وكانت نيتي الطلاق، وبعد فترة لعب بي الشيطان مرة ثانية فوقعت في هذا الأمر، ثم رجعت عنه، ف هل هذا الطلاق واقع علي أم لا، مع العلم أن زوجتي لم تسمعه، أفيدوني أفادكم الله؟","title":"حكم الحلف بالطلاق مع قصد الطلاق","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن العادة السرية التي يعتادها بعض الناس محرمة، وفيها أضرار كثيرة وهي الاستمناء، وقد قال الله عز وجل في وصف المؤمنين: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7].\nوهذه العادة الخبيثة هي غير ما أباح الله من إتيان الزوجة والسرية، فتكون محرمة وتكون من العدوان الذي بينه الله سبحانه في هذه الآية، قد بين الأطباء العارفون بهذه العادة مضرتها العظيمة وشرها الكثير.\nفالواجب على كل مؤمن أن يحذرها غاية الحذر.\nأما ما ذكره السائل من تعليقه الطلاق على العودة، فإذا كان يقصد مثل ما قال: إيقاع الطلاق، فإنه يقع طلقة واحدة؛ لعوده إليها؛ لأنه طلاق معلق على شرط يقصد منه الوقوع فوقعت بذلك طلقة واحدة على الصحيح؛ لأنه ثبت من حديث ابن عباس رضي الله عنهما عن النبي ﷺ ما يدل أن إيقاع الثلاث بلفظ واحد يعتبر طلقة واحدة.\nولك أيها السائل! مراجعتها بعدما عاودت هذه العادة الخبيثة؛ لأنه طلاق رجعي.\nأما إذا كنت لم تطلقها قبل هذا طلقتين، أما إن كنت طلقتها قبلها طلقتين فهذه تكون الثالثة ولا رجعة، نسأل الله للجميع الهداية.\nالمقدم: وبالنسبة سماحة الشيخ لما قاله: بأن زوجته لم تسمع هذا الطلاق؟\nالشيخ: ولو ما سمعت، ماله تعلق، سماعها وعدم سماعها سواء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7908/حكم-الحلف-بالطلاق-مع-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25601.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9743,"question":"يسأل أيضاً ويقول: نحن ثلاثة إخوة ولم نقسم الميراث الذي تركه لنا والدنا، وأخي الأكبر ساعدني في الزواج من نفس التركة، وأخذ علي ورقة بأنه ليس لي في الميراث شيء، ووقعت على هذه الورقة، وبعد فترة غضبت زوجتي وذهبت إلى بيت أبيها، وذهبت لإرجاعها فرفض والدها قائلاً: لن أرجعها لك حتى تأتي بالورقة التي أخذها عليك أخوك بتنازلك عن نصيبك في الميراث، فجئت إلى أخي وحلفت له، وقلت: علي الطلاق بعد أن آخذ من عندك الورقة وأريها لوالد زوجتي أعيدها، وكان في نيتي عدم الطلاق، وعدم إرجاع الورقة في نفس الوقت لأنها ظلم، وبعد أن أخذت الورقة لم أرجعها إلى أخي، فأسأل: هل وقع علي هذا الطلاق أم لا؟","title":"حكم الحلف بالطلاق مع عدم قصد إيقاع الطلاق","answer":"الجواب: إذا كنت لم تقصد إيقاع الطلاق وإنما قصدت بذلك أنه يعطيك الورقة حتى يصدقك فيما تقول ويعطيك الورقة فإنه لا يقع بهذا طلقة، لا يقع شيء بهذا الطلاق، وينبغي لك في مثل هذه الأمور أن تستعمل الأمور الواضحة التي تحل النزاع بينك وبين أخيك، أما هذا الطلاق الذي قصدت منه أن يصدقك أخوك وأن يعطيك الورقة ولم تقصد إيقاع الطلاق فإنه لا يقع بذلك الطلاق. نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: وعليك عن هذا كفارة يمين.\nالمقدم: نعم.\nالشيخ: .. عليك أيها السائل عن هذا كفارة يمين في أصح قولي العلماء. نعم.\nالمقدم: ولا يلزمه إرجاع الورقة؟\nالشيخ: هذا شيء، هذا بينه وبين أخيه خصومة عند المحكمة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7910/حكم-الحلف-بالطلاق-مع-عدم-قصد-ايقاع-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9745,"question":"أخيراً يقول الأخ المصري من مركز أبو حماد يقول: حصل بيني وبين أهل زوجتي خلاف، فقلت لزوجتي: إذا ذهبت إلى منزل أبوك فتكونين حراماً علي كأمي وأختي، فإذا ذهبت إلى منزل أبوها بعد ذلك، ماذا أفعل، أفيدوني أفادكم الله؟","title":"حكم من قال لزوجته: أنت حرام علي كأمي","answer":"الجواب: هذا يسمى الظهار، إذا فعلت يكون ظهاراً، وعليك كفارة الظهار، وهي عتق رقبة مؤمنة فإن لم يستطع صام شهرين متتابعين، فإن عجز أطعم ستين مسكيناً.\nوالواجب عليك ترك ذلك؛ لأن هذا منكر من القول فليس له فعل ذلك، بل يتقي الله ويحرص على ترك هذه الأشياء، لكن متى فعلها فعليه التوبة والاستغفار، وعليه الكفارة قبل أن يمسها: قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3]. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7920/حكم-من-قال-لزوجته-انت-حرام-علي-كامي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25611.mp3","categories":["الطلاق","الظهار"]},{"id":9749,"question":"أخيراً يقول: بجوارنا جيران سوء، وإذا اختلطنا بهم أو اختلطت بهم زوجتي لا ينالنا منهم إلا السوء والمنازعة، فقلت لزوجتي: إن كلمتيهم أو ذهبت إليهم فسوف أذهب بك إلى بيت والدك وأطلقك، وكان في نيتي التهديد لها، فأود أن أعرف هل إذا ذهبت إليهم وكلمتهم يقع عليها الطلاق أم لا، أفيدوني أفادكم الله؟","title":"حكم التهديد بالطلاق","answer":"الجواب: هذا وعيد وليس بطلاق، هذا من باب الوعيد، من باب التحذير من زيارتها لهم، وليس هذا بطلاق، وإنما هو تهديد بالطلاق ولا يقع به شيء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7911/حكم-التهديد-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25603.mp3","categories":["الطلاق"]},{"id":9751,"question":"ويسأل أيضاً ويقول: يقول النبي ﷺ: من حلف بغير الله فقد أشرك وقد علمنا من برنامجكم أن الحلف بالطلاق ليس شركاً، ونعلم أن الطلاق ليس من أسماء الله تعالى ولا من صفاته، ويفتى لمن حلف بالطلاق إذا كان يقصد الحلف واليمين، بأن عليه كفارة يمين، فكيف يعتبر يمين وهو بغير أسماء الله وصفاته، أفيدونا أفادكم الله؟","title":"بيان كون الحلف بالطلاق ليس شركاً","answer":"الجواب: يفتى بأنه يمين؛ لأنه في حكم اليمين، لأن مقصوده الحث والمنع والتصديق والتكذيب، فهو في حكمها من جهة المعنى، من جهة المعنى الذي تترتب عليه الكفارة، وليس في المعنى من جهة تحريم الحلف بغير الله لأنه ما حلف بغير الله، إنما علق تعليقاً قال: علي الطلاق ليفعلن كذا، علي الطلاق لا يكلم فلاناً بخلاف الحلف بغير الله، كالحلف بالأصنام أو بالأنبياء أو بالأمانة أو بالكعبة هذا حلف باطل، ولا تترتب عليه كفارة يمين لأنه يمين باطلة وأما التعليقات تعليق الطلاق أو العتق أو الصدقات على أشياء هذا في حكم اليمين من جهة الكفارة، وليس في حكمها من جهة التحريم.\nفإذا قال: عليه الطلاق لا يكلم فلان أو عبيده أحرار إن كلم فلان، أو أمواله صدقة إن كلم فلان، قصده منع نفسه من هذه الأشياء، هذا له حكم اليمين من جهة الكفارة، ولا تلزمه هذه الأشياء، لأنه من باب النذر الذي .... يفعل هذا في الغالب للتأكيد على نفسه، إما في منع وإما في فعل، فحكمه حكم اليمين من هذه الحيثية، وليس له حكمها من جهة أن هذا يحرم عليه؛ لأنه لم يحلف بغير الله، وإنما علق تعليق، وهذا مروي عن السلف الصالح جعلوه في حكم اليمين ولم يجعلوه محرماً، بل جعلوه في حكم اليمين في حكم الكفارة، لما نذرت امرأة يقال لها: ليلى بن العجماء أن عبيدها أحرار وأن مالها صدقة إن لم تفرق بين فلان وفلانة جارية لها، فأفتاها ابن عمر وجماعة من السلف بأن عليها كفارة اليمين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7917/بيان-كون-الحلف-بالطلاق-ليس-شركا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25608.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":9754,"question":"ويسأل أيضاً ويقول: يقول النبي ﷺ: من حلف بغير الله فقد أشرك وقد علمنا من برنامجكم أن الحلف بالطلاق ليس شركاً، ونعلم أن الطلاق ليس من أسماء الله تعالى ولا من صفاته، ويفتى لمن حلف بالطلاق إذا كان يقصد الحلف واليمين، بأن عليه كفارة يمين، فكيف يعتبر يمين وهو بغير أسماء الله وصفاته، أفيدونا أفادكم الله؟","title":"بيان كون الحلف بالطلاق ليس شركاً","answer":"الجواب: يفتى بأنه يمين؛ لأنه في حكم اليمين، لأن مقصوده الحث والمنع والتصديق والتكذيب، فهو في حكمها من جهة المعنى، من جهة المعنى الذي تترتب عليه الكفارة، وليس في المعنى من جهة تحريم الحلف بغير الله لأنه ما حلف بغير الله، إنما علق تعليقاً قال: علي الطلاق ليفعلن كذا، علي الطلاق لا يكلم فلاناً بخلاف الحلف بغير الله، كالحلف بالأصنام أو بالأنبياء أو بالأمانة أو بالكعبة هذا حلف باطل، ولا تترتب عليه كفارة يمين لأنه يمين باطلة وأما التعليقات تعليق الطلاق أو العتق أو الصدقات على أشياء هذا في حكم اليمين من جهة الكفارة، وليس في حكمها من جهة التحريم.\nفإذا قال: عليه الطلاق لا يكلم فلان أو عبيده أحرار إن كلم فلان، أو أمواله صدقة إن كلم فلان، قصده منع نفسه من هذه الأشياء، هذا له حكم اليمين من جهة الكفارة، ولا تلزمه هذه الأشياء، لأنه من باب النذر الذي .... يفعل هذا في الغالب للتأكيد على نفسه، إما في منع وإما في فعل، فحكمه حكم اليمين من هذه الحيثية، وليس له حكمها من جهة أن هذا يحرم عليه؛ لأنه لم يحلف بغير الله، وإنما علق تعليق، وهذا مروي عن السلف الصالح جعلوه في حكم اليمين ولم يجعلوه محرماً، بل جعلوه في حكم اليمين في حكم الكفارة، لما نذرت امرأة يقال لها: ليلى بن العجماء أن عبيدها أحرار وأن مالها صدقة إن لم تفرق بين فلان وفلانة جارية لها، فأفتاها ابن عمر وجماعة من السلف بأن عليها كفارة اليمين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7917/بيان-كون-الحلف-بالطلاق-ليس-شركا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25608.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":9787,"question":"هذه رسالة وردت إلينا من محمد نصر الدين مصطفى سوداني مقيم باليمن الشمالية مدينة صنعاء، الأخ محمد له عدة أسئلة في رسالته، يقول في أولها: له أخت قد طلقها زوجها قبل ثلاث سنوات، طلقة واحدة، ولهما ابن واحد عمره حوالي تسع سنوات، وهو الوحيد الذي أحياه الله لهم من بين أبنائهم وبناتهم الذين توفاهم الله عز وجل، فيقول: إنني أحاول إرجاع المياه إلى مجاريها والإصلاح بينهم، فهل الصلح جائز في هذه الحالة؟ وهل يجوز أن ترجع المرأة إلى عصمة زوجها وكيف يكون الرجوع أفيدوني أفادكم الله؟","title":"حكم إرجاع المطلقة الرجعية بعد خروجها من العدة","answer":"الجواب: إذا كانت المرأة المذكورة قد طلقت طلقة واحدة فقط ولم يطلقها أكثر من ذلك فله أن يراجعها ما دامت في العدة، فإن كانت قد خرجت من العدة جاز له الرجوع بنكاح جديد بشروطه المعتبرة شرعاً، يعني: يخطبها فإذا رضيت زوجها وليها عليه بالمهر الذي يتراضيان عليه ويكون بحضرة شاهدين.\nأما إن كانت في العدة ما بعد مضى عليها ثلاث حيض بل لا تزال في العدة، فإنه يراجعها من دون عقد، فيقول: اشهد يا فلان وفلان -شاهدين- أني راجعت زوجتي فلانة ويكفي، ولا حاجة إلى عقد ما دامت في العدة، إذا كانت تحيض ولم يأتها ثلاث حيضات فإنها تكون في العدة، فيراجعها بدون عقد، وهكذا إن كانت كبيرة السن قد انقطع عنها الحيض فإن عدتها ثلاثة أشهر، فإذا كانت لم تمر عليها الثلاثة راجعها من دون عقد، أما بعد خروجها من العدة فلا بد من عقد جديد، وذلك مثل بقية الرجال يخطبها إلى وليها وإلى نفسها ومتى وافقت ووافق وليها تراضيا على المهر الذي يرضيها ثم تم العقد، يقول له الولي: زوجتك فلانة بنتي إن كان أبوها موجود أو أخوها، زوجت بنتي أو أختي فلانة، وهو يقول: قبلت هذا الزواج، بحضرة شاهدين عدلين وتم الأمر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7953/حكم-ارجاع-المطلقة-الرجعية-بعد-خروجها-من-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25906.mp3","categories":["الطلاق","العِدَد"]},{"id":9791,"question":"هذه رسالة من السائل (ع. س. م) من محافظة الشرقية في جمهورية مصر العربية يقول: حدث بيني وبين زوجتي خلاف ثم ضربتها بغضب في ذات يوم فبكت وقالت لي: أريد أن تطلقني، فقلت لها: ارتدي ملابسك حتى أوصلك لأهلك، ولما أرادت أن ترتدي ملابسها منعتها من ذلك وتصالحنا في نفس اليوم وكأن شيئًا لم يحدث، وكان ذلك منذ حوالي شهرين، ولكن نفسي تحدثني من وقت لآخر طول هذه الفترة في حكم الشرع فيما قلت لها وقالت لي، وهل يحصل بذلك طلاق، أفيدونا جزاكم الله خير؟","title":"حكم من نوى الطلاق ولم يطلق","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل فلا طلاق؛ لأن النية وحدها لا يقع بها الطلاق وإنما يقع الطلاق بأحد أمرين: إما الكلام وإما الكتابة، أما النية فلا يقع بها الطلاق لقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت به أنفسها لم تعمل أو تتكلم، فالنية عند أهل العلم لا يقع بها الطلاق فاطمئن يا أخي واحمد الله على السلامة، وأسأل الله لنا ولك التوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7958/حكم-من-نوى-الطلاق-ولم-يطلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19607.mp3","categories":["الطلاق"]},{"id":9792,"question":"وهذا سؤال من السائل (م. ع. م) من جمهورية اليمن الديمقراطية الشعبية يقول فيه: أنا رجل متزوج وفي أحد الأيام حصل شجار بيني وبين زوجتي مما أدى إلى أني فقدت شعوري وقلت لها: إذا ذهبت عند أهلك فأنت طالق، هذه الليلة لا تنامين عندي، فذهبت عند أهلها فلما أتى الليل عرفت أني مخطئ في حقها فنامت عندي، فما هو الحل؟الشيخ: أعد أعد.يقول: حدث بيني وبين زوجتي شجار مما أدى إلى فقد شعوري من الغضب فقلت لها: إذا ذهبت عند أهلك فأنت طالق، هذه الليلة لا تنامين عندي، فذهبت عند أهلها فلما أتى الليل عرفت أنني مخطئ في حقها فأرجعتها فنامت عندي؟","title":"حكم الطلاق في حالة الغضب","answer":"الجواب: إذا كان شعورك قد تغير بشدة الغضب فهذا لا يقع به شيء، أما إن كان شعورك مضبوط وعقلك معك وقصدك منعها من الذهاب إلى أهلها فإن عليك كفارة يمين ويكفي، عليك أن تكفر كفارة يمين إذا لم تقصد إيقاع الطلاق، وإنما قصدت منعها من الذهاب إلى أهلها ومنعها من المبيت عندك فعليك كفارة يمين فقط، ويكفي؛ لأن هذا حكمه حكم اليمين، أما إن كنت أردت إيقاع الطلاق إن ذهبت وأنت شعورك مضبوط يقع عليها طلقة بذلك ولا بأس بمراجعتها إذا كانت لم يسبق لها طلقتان سابقتان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7959/حكم-الطلاق-في-حالة-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19608.mp3","categories":["الطلاق"]},{"id":9816,"question":"وهذه رسالة من حسين محمد الزبير سوداني الجنسية يعمل في الكويت، يقول في رسالته: حلفت بالحرام أن لا أمضي في هذا البلد إلا سنة واحدة وأرجع، لكني قد تجاوزت السنة ولم أرجع ولم أوف بحلفي، فماذا أعمل وأنا أريد الآن السفر وأنا متزوج فخشيت من هذا الحلف أن يؤثر علي أفيدوني أفادكم الله؟","title":"الحلف بالحرام فيه كفارة يمين","answer":"الجواب: إذا كان المقصود من هذا الحلف حث نفسك على الخروج وعدم الزيادة على السنة ولم ترد تحريم زوجتك، وإنما أردت حث نفسك على أن تخرج من البلد وتسافر قبل السنة، فإن عليك كفارة يمين، إذا زدت على السنة عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، لقوله : يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2].\nفالمقصود: أن عليك كفارة يمين وهي إطعام عشرة مساكين من قوت البلد لكل مسكين نصف صاع، يعني: كيلو ونصف تقريباً من قوت البلد من رز أو تمر أو حنطة أو غير ذلك، وعليك التوبة والاستغفار؛ لأن التحريم لا يجوز.\nأما إن كنت أردت تحريم زوجتك فإن عليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم يتيسر ذلك تصوم شهرين متتابعين، فإن لم تستطع ذلك تطعم ستين مسكيناً ثلاثين صاعاً من التمر أو الحنطة أو الرز أو الشعير لكل مسكين نصف صاع، يعني: كيلو ونصف تقريباً لكل واحد من قوت البلد من تمر أو غيره أو أرز أو حنطة ونحو ذلك قبل أن تمسها قبل أن تقربها؛ لأن هذا في حكم الظهار، إذا كنت أردت تحريم زوجتك إذا زدت على السنة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7992/الحلف-بالحرام-فيه-كفارة-يمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26013.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9823,"question":"وهذه رسالة من جلال عبد الحافظ مصري الجنسية يعمل في العراق، يقول: والدتي زوجتني سابقاً وأجبت طلبها وتزوجت على إراداتها وأنجبت طفلاً من المرأة التي زوجتني إياها، وبعد مدة طلبت مني أن أطلق هذه المرأة وفعلاً طلقتها ترضية لوالدتي، وزوجتني بأخرى غيرها، ونحن سعداء أنا وزوجتي ولكن أمي تقول لي: طلقها فأنا محتار في هذا، أفيدوني أفادكم الله؟","title":"حكم طاعة الأم إذا أمرت بطلاق الزوجة","answer":"الجواب: عليك بالتثبت في الأمور وعدم العجلة، والوالدة لها حق عظيم، الوالدة والوالد لهما حق عظيم، لكن لا تعجل في الأمور، وطاعتهما حق، وبرهما واجب، لكن لا تعجل في الأمور، واستسمح الوالدة إذا كانت الزوجة صالحة وطيبة وليس منها بأس فاستسمح الوالدة بالكلام الطيب، وتشفع إليها بالناس الطيبين من إخوانها أو أخواتها، أو غيرهم ممن يعز عليها لعلها تسمح ولا تعجل إذا كانت الزوجة طيبة.\nأما إذا كانت الزوجة غير طيبة ففارقها وأطع والدتك، فإنها إنما نصحت لك، فعليك أن تطيعها في المعروف وتفارق هذه المرأة وسوف يعطيك الله خيراً منها بسبب برك وطاعتك لأمك في الخير والمعروف. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7989/حكم-طاعة-الام-اذا-امرت-بطلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26010.mp3","categories":["الطلاق"]},{"id":9824,"question":"وهذه رسالة وردت من العراق من المواطن المصري هناك: (ن. ف. م) يقول السائل في رسالته: أنا متزوج وعندي طفل واحد، وأسكن مع عائلتي أي: مع أهلي، لكن يوجد بيني وبين أفراد عائلتي مشاكل بدون أسباب، وفوجئت في يوم من الأيام أن أفراد عائلتي يريدون مني طلاق زوجتي دون أن يصدر منها شيء يغضب الأسرة، وأنا في موقف متحير لا أريد أن أطلق زوجتي ولا أريد أن أعيش بعيداً عن أفراد أسرتي، فما رأي الشرع في ذلك؟","title":"حكم من يرغمه أهله على طلاق زوجته","answer":"الجواب: لا يلزمك أن تطلق، بل عليك أن تعالج الأمور بالكلام الطيب والفعل الطيب ولا تعجل، عليك أن تعالج الوضع بالكلام الطيب مع أسرة زوجتك ومع أهلك، مع كل من له ضلع في هذا الشيء، تعالج الأمور بالهدوء والكلام الطيب والفعل الجميل حتى تنتهي المشكلة، ولا تعجل في الطلاق.\nوإذا كانت المرأة قد قصرت في شيء تنصحها حتى تستقيم مع أهلك ومع قرابتك ومع أهلها، حتى تزول المشاكل إن شاء الله.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7984/حكم-من-يرغمه-اهله-على-طلاق-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26005.mp3","categories":["الطلاق"]},{"id":9846,"question":"أولى رسائل هذه الحلقة وردت من عبد الحميد أحمد حربي من جمهورية مصر العربية من محافظة كفر الشيخ ويقيم بالأردن، يقول في رسالته: عقد قراني ولم أدخل إلى الآن، وبعد العقد بمدة غضبت من هذه المرأة؛ لأنها مشت مشياً أغضبني فناديتها ولم ترض فحلفت عليها يمين الطلاق، إذا لم تأت تكوني على ذمة نفسك ولم ترض، فمشيت وراءها حتى أرضيها فحلفت عليها ثانية يمين الطلاق وأنا في أشد الغضب وقلت: لن تكوني لي امرأة ولن تدخلي بيتي، فما الحكم في هذا؟ بارك الله فيكم.","title":"حكم الحلف بالطلاق قبل الدخول بالزوجة المعقود عليها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الطلاق الذي وقع منك.. الأول والثاني، له معنيان:\nأحدهما: أن تكون قصدت بذلك حثها على الاستجابة والامتثال لأمرك، ولم ترد إيقاع الطلاق عليها، فهذا لا يقع الطلاق وعليك كفارة يمين عن الأول والثاني، عن الطلاق الأول والثاني، يعني: كفارتان، وكفارة اليمين هي إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد، من تمر أو أرز ونحوهما، وإن عشيت المساكين أو غديتهم مرتين العشرة عن الطلاقين كفى.\nأما إن كنت أردت بذلك الطلاق الأول إيقاع الطلاق فإنه وقع عليها الطلاق ولا يلحقها الطلاق الآخر؛ لأن الأول يكفيها؛ لأنه غير مدخول بها تبين بالطلاق الأول ولا يلحقها الطلاق الآخر.\nوإن كنت أردت بالطلاق الأول اليمين يعني: حثها على طاعتك، والاستجابة لطلبك ولم ترد إيقاع الطلاق فإن فيه كفارة يمين، ثم ينظر في الطلاق الثاني. فإن كنت أردت به أيضاً أن تمتثل وأن تطيع أمرك، ولم ترد إيقاع الطلاق، فإن هذا يكون فيه كفارة يمين، وأما إن كنت أردت إيقاع الطلاق فإنه يقع عليك الطلاق، والذي نرى فإنه يقع عليها الطلاق، والذي نرى أن تستفتي أهل العلم عندك في الأردن أو في مصر حتى تحضر أنت والمرأة ووليها تحضرون جميعاً عند المفتي أو عند الحاكم الشرعي في الأردن أو في مصر، حتى تشرحوا له جميعاً صفة الواقع، وحتى يفتيكم على بينة وعلى أمر واضح فيما وقع منك بحضور المرأة وحضور وليها جميعاً، هذا هو الأولى وهذا هو الأحوط حتى يكون كل منكم على بينة وعلى بصيرة. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8008/حكم-الحلف-بالطلاق-قبل-الدخول-بالزوجة-المعقود-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26201.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9847,"question":"هذه رسالة وردت إلينا من (م. م. ح) مقيم بنجران وهو مصري الجنسية، الأخ السائل في رسالته يقول: أنا متزوج من بنت عمي شقيق أبي، وعلى إثر خلاف كبير بيني وبين عمي وزوجته، أدى إلى تحطيم مستقبلي ومستقبل أولادي فمنعت زوجتي من الذهاب إلى أبيها وأمها، ومنعت أيضاً والد زوجتي ووالدتها من الحضور إلى بيتي و لم يزل الخلاف قائماً، وقبل حضوري إلى المملكة طلبت مني زوجتي أن ترى والدها ووالدتها وإخوتها، فأثار ذلك جنوني وغضبي الشديد ورفضت هذا المطلب وضربتها، وحلفت عليها يميناً هذا نصه: علي الطلاق بالثلاث لو ذهبت إلى بيت أبيك في غيابي لن أخليك في البيت عند عودتي، وكررت ذلك مرة ثانية، في أقل من ربع ساعة، فهل إذا ذهبت إلى بيت أبيها في غيابي تكون طالقاً مرتين، أم يعتبر يميناً معلقاً له كفارة، وإذا كان كذلك فما كفارته أفيدوني بارك الله فيكم؟","title":"حكم منع الزوجة من زيارة والديها والحلف على ذلك بالطلاق","answer":"الجواب: هذا فيه تفصيل على حسب نيتك: إن كنت نويت منعها من هذا الذهاب وتخويفها وتحريجها وليس القصد من ذلك أنها طالق، وإنما أردت تخويفها وتحذيرها ومنعها فهذا فيه كفارة اليمين يمين واحدة، أما إذا كنت أردت بذلك إيقاع الطلاق، وأنها متى خرجت متى راحت إلى أهلها وقع الطلاق، فإنه يقع عليها طلقة واحدة، وإذا كنت أردت بالتكرار طلقة ثانية، فإنه يقع طلقة ثانية، أما إذا أردت بالتكرار تأكيد الكلام وتأكيد المقام لا طلاقاً آخر، فإنه لا يقع إلا طلقة واحدة، ولك العود إليها بنكاح جديد، بشروطه المعتبرة شرعاً، هذا هو التفصيل في هذا الأمر، أما كونها تذهب إلى والديها، فهذا فيه تفصيل:\nإن كان ذهابها إليهم يضرك ويضرها لسوء أخلاقهم وسوء أعمالهم، ويفسدونها عليك فلا حرج في منعها، أما إذا كان ذهابها إليهم لا يضرك ولا يضرها، فينبغي أن تسمح بذلك، وعلى كل حال ينبغي علاج هذا الأمر بالطرق الطيبة بينك وبين والدي زوجتك؛ لأن هذا يشق عليها كثيراً إذا طال، فينبغي أن تعالج هذا الأمر بواسطة أهل الخير والإصلاح بينكم حتى يتيسر ذهابها إليهم عن رضا منك، نسأل الله للجميع الهداية.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8024/حكم-منع-الزوجة-من-زيارة-والديها-والحلف-على-ذلك-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26212.mp3","categories":["الطلاق","الأيمان والنذور","الحقوق الزوجية"]},{"id":9851,"question":"وهذه رسالة وردت من جبريل حلمي محمد من محافظة قنا في جمهورية مصر العربية، يقول: أنا أسكن في بيت على ضعف حالتي المادية ومعي والدتي بعد طلاقها من رجل آخر غير أبي، ومعي زوجتي، لكن يحصل هناك شقاق وخلاف بين أمي وزوجتي، وأنا أصلحهم عدة مرات، وقد أخذت أغضب زوجتي لأجل إرضاء والدتي وأثناء الغضب أقول لها: أنت طالق، فتذهب إلى بيت والدها، وعندما أرضى أرجعها بواسطة الشيخ لأجل تحليل اليمين، علماً أن تكون والدتي أحياناً هي الغلطانة، والمرة الثانية أيضاً، والمرة الثالثة قال لي الشيخ: ليس لها رجوع حتى تدفع لها مهراً جديداً ونقرأ السنة وقد فعلنا ذلك، وبعدها حصل خلاف أيضاً فطردت والدتي من البيت، وأقامت مع أخوالي فهل علي إثم؛ لأن والدتي لا تزال غاضبة علي، وما حكم ما حصل مني من طلاق وكلام الشيخ أفيدوني أفادكم الله؟","title":"حكم الطلاق أثناء الغضب","answer":"الجواب: عليك أن تراجع القاضي، أو مفتي البلاد مع حضور الزوجة وحضور وليها، وحضور أمك حتى ينظر في أمركم ويفتيكم بما يلزم؛ لأن هذا المقام يحتاج إلى تفصيل وعناية، فعليك أن تراجع القاضي الذي هو الشيخ الحاكم الشرعي أو المفتي في البلد، بحضرة الزوجة ووليها وأمك، حتى ينظر في الواقع كله ويفتيكم في الجميع إن شاء الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8010/حكم-الطلاق-اثناء-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26203.mp3","categories":["الطلاق"]},{"id":9855,"question":"هذه رسالة من السائل: لطفي سعيد اليماني ، يقول فيها، سؤاله الأول: ما حكم من نوى أن يطلق زوجته وتأخر عن ذلك؟","title":"حكم من نوى طلاق زوجته ولم يطلقها","answer":"الجواب: إذا نوى الرجل طلاق زوجته ثم ترك ذلك ولم يفعل شيئًا فإنه لا يقع عليها طلاق، النية لا يقع بها طلاق؛ لقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تكلم، فما دام لم يتكلم ولم يعمل لم يكتب ذلك وإنما نوى فقط فهذه النية لا يقع بها شيء وزوجته باقية في عصمته لم يقع عليها الطلاق حتى يكتب الطلاق أو يتكلم به. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8014/حكم-من-نوى-طلاق-زوجته-ولم-يطلقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19809.mp3","categories":["الطلاق"]},{"id":9858,"question":"وله استفتاء ثالث أيضًا يقول فيه: ما حكم المرأة التي تقول لزوجها: الله يحرمك عليَّ، وتروح إلى بيت أهلها وترجع بعد ذلك إلى بيت الزوجية؟","title":"حكم تحريم المرأة زوجها على نفسها","answer":"الجواب: هذا لفظه لفظ الخبر، ومعناه الدعاء، ولا وجه له ولا يحصل به شيء، ولا يترتب عليه شيء فقولها: الله يحرمك، أو الله يجعلك علي حرام، ما يترتب عليه شيء لكنه دعاء لا ينبغي منها، وهو معناه طلب شيء يجعلها محرمة عليه وهذا لا ينبغي منها.\nأما لو قالت: أنت حرام علي، أو أنت محرم علي، فإن هذا أولًا لا يجوز لها، وثانيًا عليها كفارة يمين إذا فعلت ذلك؛ لأن المسلم إذا حرم الحلال عليه كفارة يمين ؛ لقول الله سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2]، فمن حرم ما أحل الله له كأن يحرم طعام فلان، أو زيارة فلان، أو شراب فلان، أو الجلوس عند فلان، أو كلام فلان، عليه كفارة يمين، وهكذا إذا قالت المرأة: زوجي حرام علي، أو أنت علي مثل أبي أو ما أشبه ذلك فإن هذا كلام منكر وعليها التوبة إلى الله من ذلك، وعليها كفارة اليمين؛ لأن الظهار لا يكون من النساء إنما يكون من الرجال للنساء، أما المرأة فليس منها ظهار للزوج؛ لأن الله قال سبحانه: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3]، فالظهار للزوج مع المرأة، أما هي إذا ظاهرت من زوجها أو حرمت زوجها فعليها كفارة اليمين، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو غيره، أو كسوتهم للواحد ما يجزئ في الصلاة من قميص أو إزار ورداء، أو عتق رقبة؛ عتق عبد أو عبدة ، أحد الثلاث: إما إطعام عشرة مساكين، وإما كسوتهم، وإما إعتاق رقبة مؤمنة، فإن عجز عن ذلك ولم يستطع هذه الكفارة أجزأه أن يصوم ثلاثة أيام عند العجز. نعم.\nالمقدم: يعني حالة هذه لا تعتبر الآن يعني عليها كفارة فيها؟\nالشيخ: لا؛ لأنها دعاء ما ....: الله يحرمكم ما فيه كفارة. نعم.","link":"https://binbaz.org.sa/fatwas/8019/حكم-تحريم-المراة-زوجها-على-نفسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19811.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9862,"question":"يقول في بقية سؤاله يا سماحة الشيخ: أنا قلت لوالدي: طلقها وأنا أزوجك خيرًا منها، وقلت لوالدي: علي الطلاق إن لم تطلق زوجتك، فقال: لن أطلقها، فكيف أعمل بيمين الطلاق؟","title":"حكم قول الرجل علي الطلاق","answer":"الجواب: هذا تراجع فيه المحكمة من جهة ما قال أبوك ومن جهة النصيحة لأبيك، ومن جهة طلاقها وتجديد العقد معها إذا كانت تائبة، هذا شيء يتعلق بالمحكمة، لكن من جهة طلاقك أنت فيه نظر، فإن كنت قصدت بهذا حث والدك على طلاقها ولم ترد إيقاع الطلاق وإنما أردت حثه على طلاقها والعزم عليه، وإلا فلم ترد إيقاع الطلاق عليها، فعليك كفارة اليمين ولا يقع الطلاق.\nأما إن كنت أردت إيقاع الطلاق مع حث والدك على الفراق فإنه يقع عليها طلقة بذلك، وتراجعها في الحال بإشهاد شخصين من خواص المسلمين من العدول ويكفي ذلك، إذا كنت لم تطلقها قبل هذا طلقتين فإن الطلقة هذه تكون رجعية ولك أن تراجعها في الحال إذا كنت أردت إيقاع الطلاق، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8029/حكم-قول-الرجل-علي-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19815.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9868,"question":"وهذه الرسالة وردت إلينا من الأخ بدري محمد حامد مصري الجنسية يعمل بالرياض يقول: حضر إلي زميلي ومعه خطاب من الخارج، فعندما سألته عن هذا الخطاب؟ قال: إنه لك، فقلت: إنني طلقت صاحبة هذا الخطاب أعني: أنني طلقت الزوجة التي في الخارج، ونيتي ومقصدي هو ما ذكرته لكم، فقال لي: أصبحت زوجتك طالق بناءً على كلامك هذا، فما الحكم جزاكم الله خيراً؟","title":"حكم الإخبار بالطلاق","answer":"الجواب: نعم إذا كان الواقع هو ما ذكر فإنه يقع عليها طلقة؛ لأنك ... وأردتها فيقع عليها طلقة، ولك مراجعتها في الحال ما دامت في العدة، لك مراجعتها ما دامت في العدة، إذا كانت الطلقة لم يسبقها طلقتان، فإن كان سبقها طلقتان فهي الثالثة، لا رجعة بعدها، ولا ينبغي للمؤمن المسارعة في هذه الأشياء والعجلة، بل ينبغي التثبت في الأمور وعدم العجلة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/8042/حكم-الاخبار-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26310.mp3","categories":["الطلاق"]},{"id":9870,"question":"ويقول أيضاً: إذا حلف الشخص بالطلاق وهو في الرياض، وزوجته في بلاده، لأي سبب مثلاً على أخ أو صديق بحكم المجاملة في أكل أو شرب فهل يقع هذا الطلاق، وهل هو حرام؟","title":"حكم الحلف بالطلاق في غيبة الزوجة","answer":"الجواب: ما ينبغي التلاعب في الطلاق، ولا ينبغي اتخاذه الإنسان ديدنه في كلامه وأيمانه، بل ينبغي أن يبعده عن ذلك ويتحرز من ذلك، فإذا طلق في كلامه نظر في أمره يختلف، فإذا قال: عليه الطلاق أن تأكل، أو عليه الطلاق أن تروح معي إلى كذا وكذا، تذهب معي إلى محل كذا، أو علي الطلاق أنك ما تكلمي فلان، قصده منعه من الكلام أو قصده التأكيد عليه أنه يأكل من طعامه، ما قصده الطلاق، هذا له حكم اليمين، يكفر عن يمينه كفارة يمين ويكفي ولا يقع الطلاق على امرأته، سواء كانت حاضرة أو غائبة، وهكذا لو قال: عليه الطلاق أنه ما يسافر قصده منع نفسه من السفر، أو عليه الطلاق أنه ما يزور فلان، هذه وأشباهها كلها إذا كان قصده منع نفسه، أو حث نفسه على كذا، لا يقع الطلاق بل فيه كفارة اليمين.\nأما إذا كان قصده.. إذا قال: عليه الطلاق ما يزور فلان، قصده فراق أهله إن زار فلان، عازم على الطلاق، يقع الطلاق طلقة واحدة، إذا كان قبلها طلقتان انتهى تم الطلاق وحرمت عليه، وإن كان ما قبلها طلقتان فله المراجعة.\nفالحاصل أنه يختلف بحسب نيته، لقول النبي ﷺ: «الأعمال بالنيات» فمن نوى في طلاقه منع شيء أو حثاً على شيء فهو على نيته وعليه كفارة يمين إذا لم ينفذ طلاقه، إذا لم يتم أمر طلاقه إذا حنث، أما إذا كان نوى بإيقاع الطلاق نوى بـ(عليه الطلاق) أنه لا يأكل كذا، أو عليه الطلاق أنه ما يكلم فلان، أو عليه الطلاق أنه ما يسافر، وهو ناوي إيقاع الطلاق، متى كلمه أو سافر أو نحو ذلك وقع، فإنه يؤخذ بنيته ويقع الطلاق. نعم.","link":"https://binbaz.org.sa/fatwas/8043/حكم-الحلف-بالطلاق-في-غيبة-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26311.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9886,"question":"يسأل أيضاً ويقول: هل على الزوجة خدمة أم زوجها أم لا؟ وما الحكم في ذلك؛ لأن هذا سبب مشكلة عندنا في البيت، ويجعلني أحياناً ألجأ إلى التفكير في الطلاق، وقد سألت في بلدتي مصر أحد المشايخ فقال: حاول أن توفق بين أمك وزوجتك، علماً بأن الزوجة يتيمة وليس لها أحد سواي، ولي منها أبناء ووالدتي ليست كبيرة السن ولله الحمد وعندها بنات في المنزل، والتوفيق بينهما أصبح مستحيلاً، فهل يجوز لي أن أعمل لي بيتاً مستقلاً لي وزوجتي وأترك والدتي وإخوتي، ما الحكم في ذلك؟ بارك الله فيكم.","title":"هل على الزوجة خدمة أم زوجها؟","answer":"الجواب: خدمة المرأة لزوجها وأهل زوجها أمر يختلف بحسب العرف في البلاد، وكان أزواج النبي ﷺ يخدمن بيوتهن، وكانت فاطمة رضي الله عنها تخدم بيتها، في الطحن والعجن والخبز وغير ذلك؛ وكنس البيت ونحو ذلك. فالذي ينبغي للمرأة أن تخدم زوجها وتخدم البيت، وإذا كان في البيت أمه أو أخته أو بناته، فالمشروع لها أن تخدمهن إذا كان العرف في بلادها كذلك.\nأما إذا كان العرف في الأسرة أو في البلد أو في القبيلة التي هي فيها، أنها تخدم وأنها لا تقوم بالخدمة هي، بل يستجلب لها خادمة، فإنه لا يلزمها وعلى الزوج إذا استطاع أن يأتي بالخادمة إلا أن تسمح بالخدمة، وتقوم بها من غير جبر لها فقد أحسنت في ذلك.\nفالحاصل: أن هذا الأمر يختلف ويتنوع بحسب عرف البلاد، إذا حصلت المشاحة والمشاقة، والأفضل للزوج أن يتحرى في هذا الأسلوب الحسن، وأن يرضي المرأة بما يستطيع من المال عند وجود النزاع حتى تخدم بنفس طيبة، حتى تخدم أمه، تخدم بناته أخواته الصغار، ونحو ذلك يكون بالأسلوب الحسن والكلام الطيب، والمساعدة المالية إذا حصلت المشاقة ولم يتضح العرف الذي يقنعها بأن تقوم بالخدمة في بيتها، والله ولي التوفيق. نعم.\nالمقدم: أثابكم الله وبارك الله فيكم، ولكن إذا استطاع أن يرضي والدته وينتقل في بيت مستقل لا حرج عليه؟\nالشيخ: لا حرج عليه، إلا أن تأبى والدته، إذا كانت الوالدة تأبى أن يخرج؛ لأنها محتاجة إليه أو لأسباب أخرى فلا ينبغي الخروج؛ لأن برها واجب، طاعتها مهمة، وقد يكون إخوته الذين في البيت لا يقومون مقامه، ولا يسدون مسده.\nفالحاصل: أنه ينبغي له أن يلاحظ أمه، ويستشيرها، فإذا سمحت فلا مانع من خروجه في بيت مستقل.\nأما إن كانت محتاجة إليه، أو كان هناك أسباب تدعو إلى عدم سماحها بخروجه فلا يخرج، بل يصبر ويحاول التوفيق بينها وبين زوجته ويرضي الزوجة بما يستطيع ولو بالمال حتى تمشي الأمور على الوجه المطلوب وحتى لا يخسر أمه بسبب زعلها عليه وغضبها عليه، والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8045/هل-على-الزوجة-خدمة-ام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26402.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9890,"question":"هذه سائلة تقول: نرجو التعريف هل يقع الطلاق على الحائض؟","title":"حكم الطلاق في الحيض","answer":"الجواب: الطلاق في الحيض لا يجوز الرسول ﷺ زجر عن ذلك زجر عن الطلاق في الحيض، والصواب أنه لا يقع إذا اتفق عليه الزوجان إذا كان يعلم الزوج أنها حائض الصواب أنه لا يقع، وذهب الأكثرون إلى أنه يقع، أكثر العلماء على أنه يقع مع الإثم، وذهب بعض أهل العلم إلى أنه لا يقع إذا كان الزوج يعرف ذلك حين الطلاق مع الإثم، فالواجب على الزوج أن يحذر ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/8058/حكم-الطلاق-في-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27302.mp3","categories":["الطلاق"]},{"id":9907,"question":"هذا السائل (م. ع. ش) الرياض حي شبرا يقول: رجل طلق زوجته طلقتين وهددها في المرة الثالثة إن هي تلفظت بكلمة يكرهها أن يطلقها الطلقة الثالثة، وتلفظت بها وأنكرت سماعها وهو جاد في طلاقها ليس كرهًا لها، ولكن حتى لا تتلفظ بما يكرهه، فما الحكم؟ جزاكم الله خيرًا.","title":"حكم من طلق زوجته إن هي تلفظت بما يكره","answer":"الجواب: عليه أن يحضر معها ووليها لدى المحكمة في بلده حتى تفتيه المحكمة أو تكتب الواقع وترسلها إلينا حتى ننظر في الأمر إن شاء الله، يحضر السائل والزوجة ووليها كأبيها أو أخيها لدى المحكمة في بلدهم، للنظر في الموضوع، وإفتائهم بما تراه المحكمة، أو تكتب لنا المحكمة وأنا أنظر في الأمر إن شاء الله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8075/حكم-من-طلق-زوجته-ان-هي-تلفظت-بما-يكره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27319.mp3","categories":["الطلاق"]},{"id":9922,"question":"هذه رسالة وردت من طه عبدالكريم عبد العال من جمهورية مصر العربية مقيم في المملكة في الرياض، هذا السائل يقول في رسالته: كنت في إجازة في مصر وحلفت يمين الطلاق على زوجتي على شيء أريدها أن لا تفعله ولا تكرره، وقلت لها: إذا تكرر هذا الشيء فستكونين طالق، وبعدها سافرت إلى المملكة، ووصلني شريط من والدتي بأنها قد فعلت ما حلفت عليها فيه، وكررته مرة أخرى، وأنا من غضبي على ذلك سجلت شريطاً، وبعثته إلى والدتي، وفي الشريط حلفت عليها وقلت: هي طالق بالثلاث. وأنا هنا، وهي حالياً حامل مني بسبعة أشهر وعندي منها أربعة أولاد، فهل هذه الأيمان تقع؟ أفيدوني أفادكم الله. وماذا أفعل إذا سافرت إلى هناك علماً أنني لا أريد أن أطلقها؟ أفيدوني أفادكم الله.","title":"حكم المعلق والطلاق الثلاث بكلمة واحدة","answer":"الجواب: أما المعلق فهذا يرجع إلى نيتك، فإذا كنت أردت منعها من ذلك وعدم فعلها فإنه لا يقع إذا فعلته، وعليك كفارة يمين في أصح قولي العلماء، والعلماء قد تنازعوا في هذا فمنهم من رأى أن المعلق يقع متى وقع الشرط، ولو كان المعلق أراد المنع، فإذا قال: إن فعلت كذا، إن عصيت والدتي، إن شربت الدخان، إن ذهبت إلى بيت فلان فأنت طالق يقصد منعها وتخويفها لا إيقاع الطلاق هذا عند الأكثرين يقع، والصواب التفصيل: فإن كان المعلق قصد منعها وتخويفها وتحذيرها ولم يرد إيقاع الطلاق فإنه لا يقع وعليه كفارة يمين لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى وهذا ما نوى طلاق وإنما نوى تخويفاً وتحذيراً، فإذا كنت ما نويت إلا التحذير والتخويف فإنه لا يقع.\nأما الطلاق الأخير اللي سجلته.... هي طالق بالثلاث فهذا يقع به واحدة على الصحيح، قد ذهب الجمهور إلى أنها تقع الثلاث، ولكن الصواب أنه لا يقع من الثلاث المجموعة إلا واحدة إذا كانت بكلمة واحدة، فإذا قال: هي طالق بالثلاث أو مطلقة بالثلاث أو هي بالثلاث فالصواب أنه لا يقع إلا واحدة؛ لأنه ثبت عن النبي ﷺ من حديث ابن عباس رضي الله عنهما ما يدل على أن الثلاث بلفظ واحد تجعل واحدة، فلك أن تراجعها، إذا كنت في الطلاق المعلق ما أردت إلا المنع، الطلاق المعلق سابقاً فلك أن تراجعها وتحسب عليك واحدة ويبقى لها ثنتان إذا كنت ما طلقتها قبل هذا طلقتين، أما إن كنت طلقتها قبل هذا فينبغي لك أن تتصل بالعلماء هناك في بلادك وتسألهم وتبين لهم الواقع أنت والمرأة ووليها، تجتمعون تسألون أهل العلم المعروفين بالعلم والإفتاء وتشرحون لهم القضية حتى يفتوكم إن شاء الله بما يرون بعد إخبارهم بكل شيء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8098/حكم-المعلق-والطلاق-الثلاث-بكلمة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_269/26904.mp3","categories":["الطلاق"]},{"id":9942,"question":"وهذه رسالة وردت من السائل (ع. م. ح) سوداني مقيم في المملكة، يقول في رسالته: حصل أن طلقت زوجتي ومضى بعد الطلاق مدة أربعة أشهر، وراجعت زوجتي بنفس الصداق الأول، وقال لي المأذون: يجوز هذا؛ لأنه طلاق رجعي، لكنني في شك من ذلك، أفيدوني أفادكم الله؟","title":"حكم من طلق طلاقاً رجعياً ثم انقضت العدة وأراد استرجاعها","answer":"الجواب: إذا كان الطلاق الذي وقع منك طلقة واحدة أو طلقتين فقط، وكانت الرجعة في العدة بأن تأخر عنها بعض الحيض حتى راجعتها قبل الحيضة الثالثة فإن الرجعة تصح ولا حاجة إلى عقد نكاح جديد، ولا إلى صداق، لكن بهذين الشرطين:\nالشرط الأول: أن يكون الطلاق الذي وقع منك أقل من ثلاث طلقة أو طلقتين.\nوالشرط الثاني: أن تكون في العدة حين الرجعة، أما إن كان قد مضى عليها ثلاث حيض إذا كانت تحيض فإن الرجعة لا تصح حينئذ، وهكذا لو كانت لا تحيض فإنها لا تصح الرجعة لأنه مضى عليها أكثر من ثلاثة أشهر، وعدة التي لا تحيض كالآيسة والصغيرة التي لا تحيض عدتها ثلاثة أشهر بنص القرآن، فإذا كانت الرجعة منك بعد ثلاثة أشهر وهي لا تحيض أو بعد ثلاث حيض إذا كانت تحيض فالرجعة غير صحيحة، فعليك أن تجدد النكاح وعليك أن تمتنع منها، وعليك التوبة والاستغفار، وعليها كذلك التوبة والاستغفار والندم، وعليكما أن تجددا نكاحاً شرعياً بولي وشاهدين ورضاها، أما إن كانت لا ترضى فلا يصح النكاح لابد من رضاها ولابد من ولي وهو أقرب العصبة، وشاهدين يحضران العقد، وبهذا تحل لك إذا كان الواقع هو ما ذكرت، والخلاصة أنك إن كنت طلقتها طلقة واحدة أو طلقتين وكانت في العدة لم تحض ثلاث حيض فإن الرجعة صحيحة، أما إن كانت قد حاضت ... ثلاث حيض قبل رجعتك أو كان الطلاق الذي وقع منك هو الطلقة الأخيرة الثالثة فإن الرجعة لا تصح، والله ولي التوفيق. \nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8110/حكم-من-طلق-طلاقا-رجعيا-ثم-انقضت-العدة-واراد-استرجاعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27403.mp3","categories":["الطلاق","العِدَد"]},{"id":9943,"question":"وهذا سؤال ورد من (م. أ. س) مصري الجنسية مقيم بالمملكة يسأل عن الطلاق أيضاً، يقول: صدر مني طلاق لزوجتي وأنا في حالة غضب شديد جدًا فقلت لها: أنت طالق طالق مرتين، فأرجو أن تفيدوني هل وقع عليها هذا الطلاق أم لا؟","title":"ضابط الغضب الشديد الذي لا يقع معه الطلاق","answer":"الجواب: إذا كان الغضب شديدًا وله أسباب واضحة كالمضاربة والمشاتمة فإن الطلاق لا يقع مع شدة الغضب في أصح قولي العلماء؛ لأن الغضبان الغضب الشديد لا يعقل مضرة الطلاق ولا يستحضرها فهو أشبه بالمعتوه والمجنون فلا يصح الطلاق، أما إن كان الغضب خفيفاً أو لم تتضح الأسباب الداعية إليه فإن الدعوى لا تسمع ويقع الطلاق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8111/ضابط-الغضب-الشديد-الذي-لا-يقع-معه-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27404.mp3","categories":["الطلاق"]},{"id":9944,"question":"يسأل أيضاً عن طلاق مماثل فيقول: إنه يعمل في مزرعة في المملكة، وقد طلب من زميل له أن يعطيه شريط ليسجل فيه، فراوغه كثيرًا فصدر منه طلاق على أنه لن يسجل شريطًا بعد ذلك طول وجوده في المملكة، ولكن يقول: بعد ذلك رجعت عن كلامي وسجلت أشرطة، فهل يكون هذا طلاقًا واقعًا؟","title":"حلف بالطلاق لزميله أنه لن يسجل شريطًا ثم رجع","answer":"الجواب: إذا كان المقصود من الطلاق على التسجيل منع نفسك من التسجيل وليس قصدك فراق أهلك إن سجلت، إنما قصدت منع نفسك حتى لا تسجل مرة أخرى فإن هذا الطلاق في حكم اليمين، أما إن كنت قصدت إيقاع الطلاق فإنه يقع الطلاق إذا سجلت، ومادمت في المملكة ففي إمكانك أن تسأل أحد القضاة أو أحد العلماء والزوجة معك ووليها إن كان حاضراً حتى يتضح الأمر لك ولها في المسألة هذه وفي التي قبلها، أو تحضر عندنا إن كنت في الرياض حتى نسألك عما يلزم، وبكل حال فالجواب هو ما سمعت. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8112/حلف-بالطلاق-لزميله-انه-لن-يسجل-شريطا ثم-رجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27405.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9952,"question":"هذه رسالة وردت من السودان من مديرية شمال كردفان من (م. م)، يسأل ويقول: يقول الرجل لزوجته: أنت طالق بالثلاث، فهل هذا هل تكون طالقًا بالثلاث فعلًا أم تحتسب طلقة واحدة؟ أفيدونا أفادكم الله.","title":"الراجح فيمن طلق امرأته ثلاثاً بكلمة واحدة","answer":"الجواب: هذه المسألة فيها خلاف بين أهل العلم إذا طلقها بالثلاث بكلمة واحدة فقال: فلانة طالق بالثلاث، أو مطلقة بالثلاث، أو قال: يخاطبها أنت طالق بالثلاث، أو أنت مطلقة بالثلاث، فالجمهور على أن هذا الطلاق يقع لازماً وتحرم عليه حتى تنكح زوجًا غيره، نكاح رغبة لا نكاح تحليل ويطأها، ثم يفارقها بموت أو طلاق، هذا قول جمهور أهل العلم وأكثرهم، وهو الذي قضى به عمر  في خلافته وأمضاه على الناس.\nوذهب بعض أهل العلم إلى أنه يحسب واحدة رجعية؛ لأنه ثبت في صحيح مسلم من حديث ابن عباس رضي الله عنهما: أن الطلاق كان في عهد النبي ﷺ وعهد الصديق وفي أول خلافة عمر طلاق الثلاث واحدة هذا القول أرجح أنه يعتبر واحدة، إلا إذا حكم به حاكم وأمضاه فإنه يمضي، إذا رفعت المسألة إلى حاكم وأمضى الثلاث تمضي، وليس لأحد أن يفتي بجعلها واحدة إلا بإذن الحاكم الذي أمضاها.\nأما إن كانت لم يمضها حاكم فإن الصواب فيها أنها تكون واحدة، وله رجعتها ما دامت في العدة لحديث ابن عباس المشار إليه، ولما في هذا من الرأفة بالمسلمين والرحمة والعطف والإصلاح، والله جل وعلا يقول: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185] والنبي عليه الصلاة والسلام يقول: يسروا ولا تعسروا فما دامت الرخصة واضحة في الحديث الصحيح فالأولى أن تجعل واحدة هذا هو الأولى، وأما قضاء عمر فهو عن اجتهاد وتحرٍ للخير ، والسنة إذا وضحت مقدمة على رأي كل أحد. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8120/الراجح-فيمن-طلق-امراته-ثلاثا-بكلمة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27406.mp3","categories":["الطلاق"]},{"id":9953,"question":"يسأل أيضاً ويقول: يحصل أحيانًا بعض الخلافات والمناقشة الحارة بين الزوجين فتغضب الزوجةُ زوجها، وهذه المناقشة غالباً ما تكون في أمور دنيوية، فهل تأثم المرأة بإغضاب زوجها؟ أفيدونا أفادكم الله.","title":"هل تأثم المرأة بإغضاب زوجها أثناء النقاش بينهما","answer":"الجواب: إذا كان إغضابها له بغير حق تأثم ولا يجوز لها أن تنازع ولا أن تؤذيه بالكلام، أما إن كان بحق بأن أنكرت عليه منكر، يتساهل في الصلاة فأنكرت عليه، يشرب المسكر فأنكرت عليه وناصحته فغضب فهي مأجورة غير مأزورة بل مشكورة.\nفالمقصود إن كان إغضابها له بحق فهي مأجورة وإن كان بغير حق فهي آثمة ولا يجوز لها إغضابه بدون حق، وعليها الكلام الطيب والسمع والطاعة في المعروف، لكن إذا كان هو يتعاطى المعاصي فأنكرت عليه ونصحته ووجهته إلى الخير فالواجب عليه أن يقبل منها وأن يشكرها وأن لا يغضب لأنها محسنة ومأجورة وناصحة فجزاؤها أن يزداد حبها وأن يشكرها على ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8121/هل-تاثم-المراة-باغضاب-زوجها-اثناء-النقاش-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27407.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9962,"question":"وهذه رسالة وردتنا من السائل عبد الهادي محمد بكري مصري الجنسية ويعمل في نجران، يقول في رسالته: أنا ساكن مع واحد من زملائي، وقد غضبت منه وحلفت بالطلاق بالثلاث لا أبيت في نفس الغرفة، فقالوا لي الزملاء: بأن علي أن أبيت وأن هذا لا يضر، فما حكم عملي هذا وفقكم الله؟","title":"على من حلف بالطلاق يريد إيقاعه أن يستفتي المحكمة","answer":"الجواب: هذا يختلف بحسب نيتك، إن كنت أردت إيقاع الطلاق إن بت في الغرفة ثم بت بها فإنه يقع الطلاق، أما إن كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق وإنما أردت بهذا منع نفسك من المبيت، فإن عليك كفارة يمين إذا بت فيها وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمتى فعلت واحدة من هذه الثلاث حصل المقصود، إطعام عشرة مساكين كل مسكين له نصف الصاع يعني: كيلو ونصف من التمر أو غيره من قوت البلد، أو كسوتهم كل واحد يكسى بما يجزئه في الصلاة كقميص أو إزار ورداء أو عتق رقبة مؤمنة، فإن لم تستطع تصوم ثلاثة أيام، هذا إذا كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق، أما إن كنت أردت إيقاع الطلاق ثم بت فإنه يقع الطلاق، ثم عليك أن تستفتي بعد ذلك المحكمة في الطلاق أو تكتب لنا في ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8136/على-من-حلف-بالطلاق-يريد-ايقاعه-ان-يستفتي-المحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9971,"question":"وهذه رسالة وردتنا من السائل عبد الهادي محمد بكري مصري الجنسية ويعمل في نجران، يقول في رسالته: أنا ساكن مع واحد من زملائي، وقد غضبت منه وحلفت بالطلاق بالثلاث لا أبيت في نفس الغرفة، فقالوا لي الزملاء: بأن علي أن أبيت وأن هذا لا يضر، فما حكم عملي هذا وفقكم الله؟","title":"على من حلف بالطلاق يريد إيقاعه أن يستفتي المحكمة","answer":"الجواب: هذا يختلف بحسب نيتك، إن كنت أردت إيقاع الطلاق إن بت في الغرفة ثم بت بها فإنه يقع الطلاق، أما إن كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق وإنما أردت بهذا منع نفسك من المبيت، فإن عليك كفارة يمين إذا بت فيها وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمتى فعلت واحدة من هذه الثلاث حصل المقصود، إطعام عشرة مساكين كل مسكين له نصف الصاع يعني: كيلو ونصف من التمر أو غيره من قوت البلد، أو كسوتهم كل واحد يكسى بما يجزئه في الصلاة كقميص أو إزار ورداء أو عتق رقبة مؤمنة، فإن لم تستطع تصوم ثلاثة أيام، هذا إذا كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق، أما إن كنت أردت إيقاع الطلاق ثم بت فإنه يقع الطلاق، ثم عليك أن تستفتي بعد ذلك المحكمة في الطلاق أو تكتب لنا في ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8136/على-من-حلف-بالطلاق-يريد-ايقاعه-ان-يستفتي-المحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9972,"question":"وهذه رسالة وردت من سائل رمز لاسمه بأخيكم في الإسلام من السودان، يقول في رسالته: أنا شاب أبلغ من العمر الثامنة والعشرين تزوجت في هذا العام إكمالًا لديني، ولكن مع الأسف لقد حلفت بقول: علي الحرام، علمًا بأنني في شعوري ولست مخمورًا ولكنني حلفت وأنا لا أقصد بأن أحرم زوجتي علي، فبكيت وندمت أشد الندم على الذي حصل مني، وصرت أستغفر الله وأدعوه في كل صلاة أن يعفو عني وتصدقت بإطعام ستين مسكيناً لكي يغفر الله لي هذا الذنب، فأسأل عن حكم ذلك؟ بارك الله فيكم.","title":"حكم من قال: (زوجتي علي حرام)","answer":"","link":"https://binbaz.org.sa/fatwas/8127/حكم-من-قال-زوجتي-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27408.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9979,"question":"تسأل أيضاً وتقول: بأنه حدث بينها وبين زوجها خلاف فحلف زوجها عليها بالطلاق ألا تخرج من بيتها وألا تذهب إلى بيت أهلها، فتقول: لم أخرج وبقيت في بيتي، وفي هذه الأثناء خرج زوجي من البيت وتركني ورجع إلى البيت وقد نسي الخلاف الذي حدث وعادت الأمور بيننا طبيعية، فما هي كفارة هذا اليمين، وماذا يفعل زوجي حتى يزيل أثر هذا اليمين لأنه قد حلف مرة أخرى ألا أزور أهلي أبدًا، فلكنني أخرج من غير علمه فلا أدخل بيتهم إنما يخرجون ويكلمونني عند الباب، فما الحكم في ذلك؟","title":"حكم من حلف بالطلاق على امرأته ألا تخرج من بيتها","answer":"الجواب: إذا كان المقصود منعك من الذهاب إلى أهلك وليس المقصود الطلاق إنما المقصود منعك من الأهل فإنه يكفر كفارة يمين، وحكم هذا حكم اليمين، إذا منعك من الخروج إلى أهلك أو من الزيارة إلى أهلك فلا تخرجي إلا بإذنه، ومتى سمح فعليه كفارة اليمين إذا كان أراد منعك ولو بإذنه، أما إذا كانت نيته أنه أنك لا تخرجين إلا بإذنه فمتى أذن فليس عليه شيء وليس عليك شيء.\nوأما إن كان أراد منعك مطلقًا ثم بدا له أن يأذن فعليه كفارة اليمين، مادامت النية والقصد منعك لا فراقك، والأعمال بالنيات، يقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى متفق على صحته، فهو مسئول عن نيته وهو أعلم بها، والله هو الذي يسأله عنها  مادام قصد منعك لا فراقك فإذا خرجت فعليه كفارة يمين وهي إطعام عشرة مساكين أو كسوتهم، كل واحد يعطى نصف صاع تمر أو رز أو حنطة أو غير ذلك من قوت البلد أو يكسوه قميصاً من الخام المعتاد أو إزار ورداء والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8140/حكم-من-حلف-بالطلاق-على-امراته-الا-تخرج-من-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27411.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9981,"question":"وهذه رسالة من الأخ السائل أحمد سلامة سلمان رشيدي سوداني الجنسية يقول في رسالته: طلقت امرأتي ثلاث مرات وحيث كان في وقت المغرب وقالت لي كلامًا أغضبني فطلقتها وراجعتها لأنها أم لطفلين، وعادت إلى بيتي وبعد أيام حصل بيني وبينها زعل فطلقتها فدخلت علي وقالت: لأجل أطفالي أرجعني؟ فرددتها، وبعد أيام حصل بيني وبينها كما حصل في الطلاق الأول والثاني فطلقتها في الثالثة أفيدوني عن هذا؟","title":"حكم وقوع الطلاق ثلاث مرات متفرقة","answer":"الجواب: عليك أن تراجع المحكمة أو المفتي لديكم في بلادكم وهو إن شاء الله ينظر في الأمر، والأصل أن الثلاث إذا تفرقت ليس بعدها رجعة ولكن القاضي أو المفتي ينظر في ذلك، أما إن كنت في السعودية فبإمكانك أن تراجعنا بالمكاتبة حتى نحيلك وإياها إلى قاضي الطلاق.... للنظر في الموضوع ومعرفة الحقيقة عنك وعن المرأة وعن وليها حتى تكون الفتوى على أمر واضح إذا كنت في المملكة، أما إذا كنت في بلاد أخرى ففي إمكانك مراجعة المحكمة للأحوال الشخصية أو المفتي عندكم، وهو إن شاء الله يوفق للفتوى فيما يوافق الشرع.\nالمقدم: إن شاء الله، جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8141/حكم-وقوع-الطلاق-ثلاث-مرات-متفرقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20008.mp3","categories":["الطلاق"]},{"id":10021,"question":"رسالة وصلت إلى البرنامج من دولة قطر وباعثها مستمع من هناك هو (م. ع. ل) يقول: أفيد سماحتكم بأني كنت تاركًا للصلاة وتزوجت في هذه الفترة وأنجبت زوجتي أطفالًا، وكان بيننا مشاكل كثيرة لا تحصى، وكنت أحدث نفسي في كل يوم أنني سوف أطلق زوجتي وفي نظري أنها ليست الزوجة المناسبة، وبعد ذلك تبت إلى الله ولله الحمد وأصبحت أصلي ولكن المشاكل لازالت قائمة بيننا، ولازال تفكيري في طلاقها قائما، وبعد فترة غضبت غضبًا شديدًا وقلت لها: أنت طالق أنت طالق أنت طالق، هكذا ثلاث مرات متتالية، وأنا الآن أعيش في صراع مع نفسي، هل زوجتي طلاقها صحيح فأصبر وأبحث عن زوجة أخرى، أم أستطيع إعادة زوجتي فهي راغبة في الرجوع ولكنني خائف من استرجاعها والوقوع في المشاكل السابقة هذا إذا كانت تحل لي، أما إذا لم تكن تحل فأرجو منكم إفادتي وجزاكم الله خيرا؟","title":"حكم تكرار لفظ الطلاق ثلاثًا في مجلس واحد","answer":"الجواب: تراجع المحكمة عندك في بلدك تراجع المحكمة في بلدك وفيما تراه المحكمة الكفاية، أو تراجعونا إن شاء الله بالمكاتبة أو بالمباشرة حتى ننظر في أمرك مع الزوجة وغيرها، لأن هذا المقام يحتاج إلى عناية فإما أن تراجع المحكمة حتى تنظر في الأمر وإما أن تراجعنا وننظر في الأمر إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8190/حكم-تكرار-لفظ-الطلاق-ثلاثا-في-مجلس-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33203.mp3","categories":["الطلاق"]},{"id":10073,"question":"المستمع (ع. م. ق) بعث بقضية مطولة بعض الشيء يقول فيها: لقد حدث شجار بين والدتي الكبيرة في السن وزوجتي على موضوع ما، فغضبت لأنها رفعت صوتها على أمي، ثم قلت لها: من غير يمين طلاق ما عدتي جالسة في بيتي، ثم ردت علي: أنا بريء منك ثلاث مرات، ثم ذهبت إلى بيت أبيها في نفس اليوم، ومكثت شهر في بيت أبيها، وعندما أردت السفر إلى الخارج قالت لي والدتي: اذهب وأرجع زوجتك إلى أولادها، علماً بأنني خلفت منها ثلاثة أولاد قبل السفر، وعندما قابلت والدها بعد الشهر قال لي: اذهب فوراً وأحضر المأذون الشرعي من أجل أن أطلق ابنتي منك، فعدت إلى بيتي وفي الليل وفي نفس اليوم سمعت صوتاً ينادي بالليل، أي: يدق الباب ففتحت الباب وإذا بها زوجتي فدخلت إلى بيتها غصباً عن أبيها لأنها لا تريد الطلاق وبقيت في بيتها، وخلفت بنتاً بعد اليمين المذكورة دون أن أحضر فتوى من أي أحد، أرجو منكم أن تفيدوني جزاكم الله خيراً هل ما صدر مني يعتبر طلاق، علماً بأن والدها مقاطعها منذ سنتين ولا يراها ولا يبرها بأي شيء جزاكم الله خيراً؟","title":"حكم قول الزوج لزوجته: ما عدتي جالسة في بيتي","answer":"الجواب: إذا كان مقصودك الطلاق حين قلت: ما تبقين عندي فهي طلقة واحدة ومراجعتك لها صحيحة بجماعك إياها بعدما رجعت إليك بنية الرجعة، إذا كان أنت ما طلقتها قبل هذا طلقتين. أما إن كنت ما أردت الطلاق، قلت هذا الكلام من دون نية الطلاق فإنه لا يقع به شيء وزوجتك باقية في عصمتك والحمد لله، وعليك وعليها أن تجتهدا في إرضاء أبيها لأن العقوق من الجرائم العظيمة فعليك أنت والمرأة أن تجتهدا في إرضائه والتوسل إليه بالطيبين من أصحابه حتى يشفعوا إليه ليسمح عنها ويرضى عنها، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8246/حكم-قول-الزوج-لزوجته-ما-عدتي-جالسة-في-بيتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30409.mp3","categories":["الطلاق"]},{"id":10183,"question":"من المملكة الأردنية الهاشمية مستمع يقول: أنا (أ. أ) من جمهورية مصر العربية محافظة الفيوم، أسألكم هذا  رجل لم يكن ملتزماً بأحكام الإسلام، طلق امرأته مرات كثيرة، وهو ذو أولاد وبنات، ولا تزال في عصمته، وهو الآن تاب إلى الله ورجع إلى التمسك بالإسلام، فما هو حكم طلقاته تلك وهو لم يكن متمسكاً بتعاليم الإسلام؟","title":"حكم من طلق زوجته وهو غير ملتزم بالإسلام","answer":"الجواب: يحضر معها ومع وليها عند المحكمة الشرعية في الأردن، محكمة الأحوال الشخصية، أو عند بعض العلماء هناك، مثلما الشيخ: محمد إبراهيم شقرة أبو مالك ، أو عند غيره من العلماء المعروفين، أو عند الشيخ ناصر الدين الألباني الشيخ العلامة محمد ناصر الدين الألباني ويبين ما وقع منه بحضور زوجته ووليها، وسوف يفتونه إن شاء الله فيما يقتضيه الشرع المطهر؛ لأن هذا يحتاج إلى معرفة الواقع، واعتراف زوجته ووليها بالواقع، أو معارضة ذلك، لا بد من نظر العالم في ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8370/حكم-من-طلق-زوجته-وهو-غير-ملتزم-بالاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30911.mp3","categories":["الطلاق"]},{"id":10229,"question":"المستمع محمد عبد التواب حسن من محافظة المنيا بعث يسأل ويقول: سماحة الشيخ! حلفت بالطلاق على أمر من الأمور أن لا أفعله لكني فعلته، والآن أنا في حيرة من أمري، لكن زوجتي بعيدة عني، وأريد أن أستفتي عن هذا الموضوع فوجهوني جزاكم الله خيرا هل وقع الطلاق أم لا؟","title":"حلف بالطلاق ألا يفعل أمرا ثم فعله","answer":"الجواب: إذا كان مقصودك الامتناع من هذا الأمر وليس قصدك إيقاع الطلاق، إنما قصدت الامتناع من هذا الشيء والحذر منه فعليك كفارة يمين ولا يقع الطلاق، حكمه حكم اليمين في أصح قولي العلماء، فإذا قلت مثلًا: علي الطلاق أني ما أكلم فلان، أو علي الطلاق أني ما آكل طعام فلان، أو علي الطلاق أني ما أشرب الدخان، أو ما أشرب الخمر وما أشبه ذلك وأنت قصدك الامتناع ليس قصدك طلاق أهلك، تحبهم وليس مقصودك فراقهم، إنما المقصود أن تمتنع من هذا الشيء، فعليك كفارة يمين إذا فعلته مع التوبة إلى الله، أما إذا كان معصية مع التوبة إلى الله إذا كان معصية كشرب الخمر ونحوه.\nأما إذا كنت أردت الطلاق أردت إيقاع الطلاق يقع الطلاق يقع طلقة، إذا كنت قلت: علي الطلاق يقع به طلقة واحدة، إذا كنت قصدت الطلاق إذا فعلت الشيء المحلوف عليه، وفق الله الجميع.\nالمقدم: اللهم آمين جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8391/حلف-بالطلاق-الا-يفعل-امرا-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27808.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10249,"question":"عند سفري طلبت من زوجتي أن تبقى مع والدتي ووالدي، لكنها بعد سفري تركت المنزل وذهبت عند أهلها، وعندما علمت بذلك كتبت ورقة قلت فيها: أنت طالق، طالق، طالق، وأنا بريء منك، أفيدوني في عملي جزاكم الله خيرًا؟","title":"حكم الطلاق بالكتابة","answer":"الجواب: هذا يحتاج إلى حضورك معها ووليها لدى المحكمة للنظر في ذلك، وإفتاؤك بما يلزم، أو إحالة ذلك إلي وأنا أنظر في ذلك إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8420/حكم-الطلاق-بالكتابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27906.mp3","categories":["الطلاق"]},{"id":10253,"question":"رسالة وصلت إلى البرنامج من المستمع محمود أبو الحسن محمود من جمهورية مصر العربية يقول: حيث أنني وقع مني يمين، وقلت في يميني هذه: علي الطلاق بالثلاث وتروح حرمانة مثل أمي وأختي، وهذا اليمين وقع علي بسبب قطعة أرض بيني وبين أخي، وحلفت اليمين على أنني لن أضع يدي على هذه الأرض، وحاليًا مضطر لأني محتاج، أرجو إفتائي جزاكم الله خيرًا؟","title":"حكم من حلف بالطلاق ثلاثًا وبالحرام","answer":"","link":"https://binbaz.org.sa/fatwas/8424/حكم-من-حلف-بالطلاق-ثلاثا-وبالحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33606.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10258,"question":"رسالة من المنطقة الشرقية في المملكة بعث بها أحد الإخوة يقول: المتعاقد طبيب (أ. ل. ح. د): أخونا له قضية مع زوجته يذكر أولاً: أنه على خلاف دائم معها، لأسباب يصفها بأنها تافهة في كثير من الأحيان؟","title":"الخلافات الدائمة بين الزوجين ووسائل تلافيها","answer":"الجواب: ننصحهما بالحلم والرفق والتواصي بالحق والصبر وعدم النزاع وعدم الطلاق، نوصي الجميع بالتعاون على الخير والتواصي بالخير، وعدم المنازعة، نوصي المرأة بالسمع والطاعة لزوجها في المعروف، نوصي الزوج بالصبر والحلم وعدم العجلة في الطلاق أو الضرب أو السب، كل واحد منهما عليه أن يتحمل ويستعمل الرفق في كل الأمور، لقوله ﷺ: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شان ، ولأن هذا العمل داخل في وقوله تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228].\nفالمشاجرة الدائمة والنزاع من أسباب الطلاق، وهكذا السب والشتم، فالواجب على كل منهما حفظ اللسان عما لا ينبغي، وحفظ الجوارح عما لاينبغي، والرفق بالأمور والحلم والصبر. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8428/الخلافات-الداىمة-بين-الزوجين-ووساىل-تلافيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27908.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":10510,"question":"من المملكة الأردنية الهاشمية رسالة بعث بها المستمع (أ. ح. م) يسأل ويقول: قلت لزوجتي: إذا ذهبت إلى دار أهلك بدوني تكوني طالق، وبعد فترة من الزمن أجبرتها الظروف أن تذهب إلى دار أهلها برغبتي، وذهب معها زوجها ولم يدخل البيت، فما رأيكم؟","title":"حكم الطلاق المعلق بالمنع","answer":"الجواب: ما دمت ذهبت أذنت لها فلا بأس، .... قلت: بغير أذني، فإذا أذنت لها فلا حرج فالحمد لله، أما إذا لم تأذن هذا فيه التفصيل: إن كنت أردت إيقاع الطلاق يقع الطلاق، وإن كنت أردت التخويف والتحذير والمنع ولم ترد إيقاع الطلاق فهذا فيه كفارة اليمين، حكمه حكم اليمين، فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا، يقول: إنه قال لها: بدوني.\nالشيخ: بدوني وإلا بدون إذني؟\nالمقدم: بدوني، وذهب معها إلى الباب ولم يدخل البيت؟\nالشيخ: ما دام بدوني ... ذهبت معها ما ذهبت بدونك لا حرج؛ لأنك ذهبت معها إلى الباب، فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8685/حكم-الطلاق-المعلق-بالمنع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28218.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10517,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، رمزت إلى اسمها بحروف (م. م) أختنا لها رسالة مطولة كلها شكوى وملاحظات على زوجها فهي تقول: أنا فتاة في الثامنة عشرة من عمري ملتزمة والحمد لله، وقد زوجني أبي وأنا عمري في السادسة عشرة من رجل عنده امرأتان ولديه خمسة عشر ولداً، أكبرهم في سني، وأنا أشكو من زوجي الذي آمره بأن يعفي لحيته طاعة لله ورسوله، ولكنه لم يفعل بل يقصرها على آخر شيء، ولولا كثرة الشيب لكان يحلقها بالموس، ولأنه يقول: إن الموس تكثر الشيب فاتخذ القص بدلًا من الحلق، وكلما أردت أن أكرر النصيحة قال: لا تتدخلين في شأني، علماً بأنني لم أنجب أبناء منه حتى الآن، فأخبرني يا سماحة الشيخ هل أطلب الطلاق من ذلكم الرجل أم أعيش وأصبر؟ وكيف تنصحونني جزاكم الله خيرًا، علماً بأنني أعتبره عاصٍ لله ولرسوله؟","title":"حكم طلب المرأة للطلاق لامتناع الزوج من إعفاء اللحية","answer":"الجواب: لقد أحسنت في إنكار المنكر جزاك الله خيراً، وفعلت ما يجب من إنكار المنكر، والله جل وعلا هو الذي يهدي من يشاء كما قال سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، ويقول سبحانه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْْ يَشَاءُ [القصص:56]، والواجب عليه أن يتقي الله، وأن يطيع الرسول ﷺ، فالرسول عليه السلام يقول: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين، ويقول ﷺ: قصوا الشوارب ووفروا اللحى، خالفوا المشركين، فالواجب عليه أن يتقي الله وأن يطيع الرسول ﷺ، وأن يعفي لحيته ويكرمها ويوفرها طاعة لله ولرسوله، وحذرًا من غضب الله، فالواجب عليه أن يسمع ويطيع لأمر الله ورسوله، وأن يشكرك على ما فعلت من الخير، وأن يقبل منك النصيحة؛ لأنك فعلت ما ينبغي وما يجب.\nأما ما يتعلق بطلب الطلاق فهذا شيء يرجع إليك إذا رأيت المصلحة في طلب الطلاق فلا بأس، إذا كان استمر على حاله ولم تنجبي منه فلا مانع من طلب الطلاق لعل الله يرزقك من هو خير منه، ويرزقك أيضاً ذرية، فهذا عذر شرعي، لا بأس أن تطلبي الطلاق إذا سمح أن يطلق فهذا طيب، ولعل الله يرزقك بما هو أصلح منه. نعم.","link":"https://binbaz.org.sa/fatwas/8692/حكم-طلب-المراة-للطلاق-لامتناع-الزوج-من-اعفاء-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28306.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":10561,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول حسين السوداني: -سؤاله مطول بعض الشيء ومشوش أيضاً- يقول: أرسلت رسالة إلى أخي بأن الزوجة طالق، ولم يعرفها أخي بأنها طالق بعد مكاتبة بيني وبينه دامت عشرة شهور، وبعد ذلك أصر أخي على أن أراجعها، وبعد كل هذه المدة وهي معه بالمنزل ولم تعرف بادرت برسالة فيها موافقتي على رجوعها، فقال لزوجتي: كنت طالق والحمد لله رجعتك إلى زوجك، أرجو إفتائي جزاكم الله خيراً، إذ أن بعض الناس يقولون: إن هذا ليس بطلاق وأنا الآن أريد أن أستفسر لأعيش حياة صحيحة؟ جزاكم الله خيراً.","title":"حكم إرجاع المطلقة رجعياً بعد انتهاء عدتها","answer":"الجواب: إذا كان الطلاق طلقة واحدة ما قبلها طلقتان فإنه يقع عليها طلقة واحدة، ولك مراجعتها ما دامت في العدة، فإن كانت قد خرجت من العدة قبل أن تراجعها فلابد من عقد جديد ... جديد، والمدة طويلة التي ذكرت، والظاهر أنها خرجت من العدة، لأن العدة تكون بثلاث حيض فمراجعتها بعد عشرة أشهر يبعد مصادفتها للعدة؛ لأن الغالب أن المرأة ترى الحيض في كل شهر، فتكون قد خرجت من العدة بعد ثلاثة أشهر، وتكون مراجعتها ليست في محلها، وعليك أن تجدد عقداً جديداً بينك وبينها إذا كانت ترغب فيك، وفي إمكانك أن تتصل بالمفتي في البلاد وتشرح له القضية أنت والمرأة ووليها حتى يجري ما يلزم في حقكما، إذ لابد من التفصيل وسؤالها عن متى انتهت عدتها، ومتى صارت منك الرجعة، فالمسألة تحتاج إلى عناية من المفتي لديكم أو المحكمة، ونسأل الله للجميع الهداية والتوفيق.\nالمقدم: آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8735/حكم-ارجاع-المطلقة-رجعيا-بعد-انتهاء-عدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32205.mp3","categories":["الطلاق","العِدَد","الرجعة"]},{"id":10632,"question":"أيضاً سؤال لأخينا السوداني -سؤال طويل أيضاً- ملخصه: أن الأب يكره زوجته، ويسأل كيف يوفق، وهل إذا طلب الوالد من الابن طلاق زوجته، هل يلبي طلبه ويعتبر ذلك من بر الوالدين؟","title":"حكم طاعة الابن أباه في طلاق زوجته","answer":"الجواب: هذا أيضاً فيه تفصيل:\nإذا كان طلب الوالد له مبرر؛ بأن كانت المرأة سيئة الأخلاق أو سيئة الدين، أو لأسباب أخرى توجب بغض الأب لها؛ لانحراف أخلاقها، أو سوء تصرفها في البيت أو أسباب أخرى؛ فإن الولد يطيع أباه ويطلقها، أما إذا كان بغض أبيه لها لغير سبب، أو لأنها مطيعة لله جيدة في دينها، معفة لفرجها ولزوجها فإنه لا يطيعه في ذلك، لقول النبي ﷺ: إنما الطاعة في المعروف فليس من المعروف أن يطيعه في طلاق امرأته الصالحة لأنها لم توافق هوى أبيه.\nفالحاصل: أن هذا محل تفصيل: إن كان بغضه لها لإيذائها لوالديه وعدم قيامها بواجب والديه، أو لسوء تصرفها أو فساد أخلاقها يطيع والده؛ لأنه أعانه على خير، أما إذا كانت سليمة متقية لله طيبة ولكن البلاء من أبيه فإنه لا يطيع أباه، فـ إنما الطاعة في المعروف. نعم.","link":"https://binbaz.org.sa/fatwas/8816/حكم-طاعة-الابن-اباه-في-طلاق-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32818.mp3","categories":["الطلاق"]},{"id":10647,"question":"هذا السائل عبد الله من تبوك يقول: بأنه طلق بالثلاث، يقول: طلقت بالثلاث بأنني لا أفعل شيء معين، مثل الامتناع عن التدخين، ثم بعد ذلك عدت إلى شرب الدخان، وكنت في ذلك الوقت أرغب في الامتناع عنه، وليس بقصدي طلاق زوجتي فهي لا زالت معي في البيت أفيدوني جزاكم الله خيرًا بذلك مأجورين؟","title":"حكم من طلق بالثلاث ألا يفعل شيئاً معيناً ثم فعله","answer":"","link":"https://binbaz.org.sa/fatwas/8824/حكم-من-طلق-بالثلاث-الا-يفعل-شيىا-معينا-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28510.mp3","categories":["الطلاق"]},{"id":10682,"question":"هل للطلاق أقسام؟ وما هي أسماؤها إن وجدت؟ وما حكم كل قسم من هذه الأقسام أفيدونا أفادكم الله؟","title":"أقسام الطلاق","answer":"الجواب: نعم، الطلاق قسمان: طلاق سنة، وطلاق بدعة، طلاق مباح، وطلاق مشروع، وطلاق محرم، فطلاق البدعة: كونه يطلق في الحيض أو في النفاس أو في طهر جامع فيه، هذا بدعة، وكذلك تطليقها بالثلاث لا يجوز، الرسول زجر عن ذلك عليه الصلاة والسلام، وطلاق السنة: أن يطلقها طلقة واحدة فقط في طهر لم يجامع فيه، أو بحال حملها، هذا يقال له طلاق السنة، وإن طلقها طلقتين فلا بأس مباح، أما تطليقها بالثلاث فلا يجوز، هكذا جاءت السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8864/اقسام-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33014.mp3","categories":["الطلاق"]},{"id":10687,"question":"هل للطلاق أقسام؟ وما هي أسماؤها إن وجدت؟ وما حكم كل قسم من هذه الأقسام أفيدونا أفادكم الله؟","title":"أقسام الطلاق","answer":"الجواب: نعم، الطلاق قسمان: طلاق سنة، وطلاق بدعة، طلاق مباح، وطلاق مشروع، وطلاق محرم، فطلاق البدعة: كونه يطلق في الحيض أو في النفاس أو في طهر جامع فيه، هذا بدعة، وكذلك تطليقها بالثلاث لا يجوز، الرسول زجر عن ذلك عليه الصلاة والسلام، وطلاق السنة: أن يطلقها طلقة واحدة فقط في طهر لم يجامع فيه، أو بحال حملها، هذا يقال له طلاق السنة، وإن طلقها طلقتين فلا بأس مباح، أما تطليقها بالثلاث فلا يجوز، هكذا جاءت السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8864/اقسام-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33014.mp3","categories":["الطلاق"]},{"id":10704,"question":"من المستمع (م. ز. م) من مكة المكرمة المسفلة صندوق بريد 723، رسالة ضمنها هذه القضية يقول فيها: إنني مستمع لهذا البرنامج منذ سنوات وأشكر سماحتكم على تفضلكم بالإجابة على أسئلة المستمعين، ومشكلتي أنني طلقت امرأتي بثلاث وهي حائض، وعند طلاقي لم يكن أحد موجوداً سوى أنا وزوجتي، وعندي ثمانية من الأولاد ندمت جداً على فعل ذلك، وسؤالي هو: هل وقع الطلاق أم لا، وأنا أريد أن أراجعها، أفيدوني ولكم جزيل الشكر؟","title":"حكم من طلق زوجته ثلاثاً وهي حائض","answer":"الجواب: عليك أن تحضر معها ووليها لدى المحكمة لديكم أو لدى بعض المشايخ حتى يكتب كلامك وكلامها وكلام وليها، وبعد ذلك تكون الفتوى إن شاء الله، حتى نعرف الحقيقة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8879/حكم-من-طلق-زوجته-ثلاثا-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34203.mp3","categories":["الطلاق"]},{"id":10775,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من جدة وباعثها مستمع من هناك هو الأخ حمدي خليل مصري يقول: أرجو أن تتكرموا ببيان الفرق بين الطلاق السني والطلاق البدعي؟","title":"الفرق بين الطلاق السني والطلاق البدعي","answer":"الجواب: الطلاق السني: هو الذي يقع في حالة الحمل أو في حالة كون المرأة طاهراً لم يجامعها زوجها، هذا هو الطلاق السني، ويكون طلقة واحدة فقط، هي طالق أو مطلقة طلقة واحدة، ويكون ذلك في حال كونها حاملاً أو في حال كونها طاهرة طهراً لم يجامعها فيه، لقول النبي ﷺ لـابن عمر لما طلق امرأته وهي حائض: راجعها ثم أمسكها حتى تطهر ثم تحيض ثم تطهر ثم إن شئت طلقها طاهراً أو حاملاً قبل أن تمسها وفي اللفظ الآخر: ثم ليطلقها قبل أن يمسها وفي اللفظ الآخر: طلقها طاهراً أو حاملا.\nفالمقصود: أنه ﷺ أمره أن يطلقها في حالة طهر ما مسها فيه، أو في حال كونها حاملاً، وهذا هو معنى قوله جل وعلا: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] قال العلماء: معنى ذلك: أنهن طاهرات بغير جماع، أو في حال الحمل، هذا الطلاق للعدة وأن يكون طلقة واحدة ....","link":"https://binbaz.org.sa/fatwas/8954/الفرق-بين-الطلاق-السني-والطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_349/34906.mp3","categories":["الطلاق"]},{"id":10782,"question":"هذه الرسالة وردتنا من علي صالح بن صالح العمال يماني يقول: أنا متزوج منذ أربع سنوات وأنا ساكن معي والدي في بيت واحد، ولكن زوجتي تحب المشاكل مع والدي ووالدتي، كل يوم وأنا أضربها وبعض الأوقات أفكر أن أطلقها، ولكنني أحبها وهي تحبني ولا أعرف أرضي والدي ووالدتي أم أرضي نفسي بحبها حسب أن زوجتي لا تفهم ولا تقرأ شيئًا، أفيدوني جزاكم الله خير الجزاء؟","title":"حكم طلاق الزوجة التي تفتعل مشاكل مع والدي الزوج","answer":"الجواب: ينبغي لك أن تستمر في نصيحتها وتحذيرها من المشاقة لوالديك وإغضابهما لأن برهما واجب، والواجب عليها أيضاً التأدب مع والديك ومخاطبتهما بالتي هي أحسن والرفق بهما وطاعتهما فيما يسبب قطع المشاكل وجمع الكلمة وتبادل المحبة والتعاون، فأنت عليك أن تستمر في نصيحتها وتوجيهها إلى الخير مع الكلام مع والديك بأن يلاحظا حالها ويرفقا بها لعلها تستقيم ما دمت تحبها وتحبك، وليس فيها مانع من البقاء مستقيمة في دينها فإنك تلاحظ ذلك وتعتني بإصلاح الحال وتوصيها بما يلزم ولا تعجل في الطلاق، لا تعجل في الطلاق لعل الله يهديها. أما إن استمرت في المشاكل مع والديك فطلاقها أولى وسوف يعوضك الله خيراً منها، فإن من اتقى الله جعل له مخرجاً، والله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فالمرأة التي تؤذي الوالدين وتشق عليهما إبعادها أولى والتزوج بغيرها أولى، والله سبحانه سوف يعوض البار بوالديه خيراً مما فاته جزاءً له على إحسانه وبره لوالديه، ولكن الأولى عدم العجلة لعلها تهتدي ولعلها تستقيم مع النصح والتوجيه إلى الخير ولعل الوالدين يرفقان بها ويصبران على بعض الأذى منها حتى تستقيم وحتى تصلح حالها، هدى الله الجميع صراطه المستقيم.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8963/حكم-طلاق-الزوجة-التي-تفتعل-مشاكل-مع-والدي-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35009.mp3","categories":["الطلاق"]},{"id":10915,"question":"رسالة من أحد الإخوة المستمعين يقول فيها في سؤال طويل بأنه يشكو من غرور زوجته، وجفاء أهلها، واستذلالهم له، ويقول: إنه عزم على الطلاق، لكنه مقيد بأطفال له من تلك الزوجة، بم تنصحونه؟ وبم تنصحون تلك الزوجة؟ جزاكم الله خيرًا.","title":"حكم طلاق المرأة التي تغتر على زوجها","answer":"الجواب:  ننصحه بعدم العجل، لا يعجل بالطلاق، وعليه أن يوصي المرأة بعدم الغرور، وعليها أن تجتهد في أداء حقه والسمع والطاعة له في المعروف، وأن تعلم أن غرورها بجمالها، أو صحتها، أو مالها من أعظم الوسائل إلى سلبها ذلك، وأن تسلب جمالها، وأن تسلب صحتها ومالها، ومن المعاصي التي قد تجر لها بلاءً كثيرًا.  فالواجب عليها شكر الله، وحمده سبحانه على ما أعطاها، وأن تتواضع لزوجها، وتؤدي حقه، وكذلك لا مانع من كونه يطلب من أخيها أو أبيها أن ينصحها، أو أمها، أو نحو ذلك حتى تستقيم، وإذا كان أهلها جافين في حقه يتحمل ويتصبر ويعاملهم بالتي هي أحسن، يعاملهم بالتي هي أحسن بالكلام الطيب، والأسلوب الحسن، والزيارة المناسبة، وقضاء حاجتهم إذا احتاجوا له في شيء، هكذا يعالج الأمور بنصيحة المرأة، وأمره الطيب من أهلها أن ينصحها، والصبر على جفاء أهلها بالكلام الطيب، والأسلوب الحسن، والزيارة المناسبة، حتى يزول الجفاء من أهلها، وحتى يزول الغرور منها، ولا يعجل في الطلاق، لا يعجل، فإن لم تنفع الأمور، وآذته بغرورها، وآذاه أهلها بجفائهم ولم يجد بدًا من طلاقها فلا حرج والحمد لله، الله جعل الطلاق راحة للزوج من شر الزوجة، لكن ما دام يرجو أن المشكلة تزول برجوعها عن باطلها، وعن غرورها، وبأدائها حق زوجها عليها، وأن الجفاء من أهلها يزول، فإن الله -جل وعلا- قادر على كل شيء  فعليه تعاطي الأسباب، والله الموفق، فإن لم تنفع الأسباب فليفعل الأصلح من طلاق، أو عدمه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9102/حكم-طلاق-المراة-التي-تغتر-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36112.mp3","categories":["الطلاق"]},{"id":10927,"question":"رسالة وصلت إلى البرنامج من المستمع (أ. ي. أ) مصري مقيم بالرياض، أخونا رسالته مطولة بعض الشيء، يقول فيها: لظروف ما أقيم أنا وزوجتي وأولادي في منزل الأهل، وحدث خلاف في المنزل كان على أثره أنني قمت بحلف يمين الطلاق على زوجتي بعدم تركها للمبيت بمنزل الأهل، بنية الذهاب بها إلى منزل والدها، إلا أن زوجتي وقعت على الأرض فاقدة النطق والحركة، وحملتها وذهبت بها إلى الطبيب في نفس اليوم، وأحضرت لها علاجًا، وشعرت أنني لا أستطيع تنفيذ يميني؛ وخوفًا من وقوع يميني حملتها، ولأنها لا تقدر على الحركة جعلتها تبيت عند إحدى الجارات بنفس المنزل، ف هل يقع يمين الطلاق بسبب عدم الذهاب بها إلى منزل والدها، أو عند حملها للمبيت عند إحدى الجارات، ذلك أني تفاديت وقوع اليمين لعدم مبيتها معي في نفس الغرفة التي تقيم معي فيها، أرجو الإفادة؟ هل إذا وقع اليمين له رد أو كفارة؟ وكيف أرد اليمين، أو أؤدي الكفارة؟ أفيدوني جزاكم الله خيرًا.","title":"حكم الحلف بالطلاق المعلق دون الوفاء به","answer":"الجواب: سؤالك هذا فيه اشتباه من جهة أوله، فإذا كان مقصودك أنك طلقتها على أنك تنقلها إلى بيت أبيها، وبسبب الحادث الذي أصابها لم تتمكن من نقلها إلى بيت أبيها، فهذا يرجع إلى نيتك، فإن كان مقصودك بذلك الطلاق حث نفسك على نقلها إلى بيت أبيها، وعدم مبيتها في بيت أهلك إذا كان هذا قصدك أنك تنقلها من بيت أهلك إلى بيت أبيها للمبيت عند أبيها تلك الليلة، وليس المقصود فراقها إن لم تنقلها، إنما أردت حث نفسك على نقلها إلى بيت أبيها بسبب ما حدث في بيت الأهل، فهذا له حكم اليمين وعليك كفارة اليمين؛ لأنك لم تحقق ما حلفت عليه.  أما إن كان قصدك فراقها إن لم تنقلها في نيتك، وفي قصدك أنك إذا لم تنقلها إلى بيت أبيها تلك الليلة، فإنه يقع عليها الطلاق، فإنه يقع عليها طلقةً واحدة، ولك مراجعتها ما دامت في العدة، إذا كنت لم تطلقها قبل هذا طلقتين، إذا كنت لم تطلقها قبل هذا الطلاق طلقتين فلك أن تراجعها، وتقع واحدة، إذا كنت قصدت إيقاع الطلاق إن لم تنقلها إلى بيت أبيها.  فأما إن كان المقصود هو حث نفسك على نقلها، والتشديد على نفسك أن تنقلها، وليس المقصود فراقها إن لم تنقلها فهذا له حكم اليمين، وإذا كنت في الرياض قريبًا فبالإمكان أن تأتي ونسألك من الرأس عما نويت وقصدت بهذا الطلاق، وعن صفة الواقع بالتفصيل، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9116/حكم-الحلف-بالطلاق-المعلق-دون-الوفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36213.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10947,"question":"سؤال من أحد المستمعين يقول: رجل اختلف مع زوجته، وعلى إثر ذلك الخلاف طلبت منه الطلاق، فأعرض عنها، وفي اليوم الثاني مباشرةً حدث منها بعض الأخطاء فسألها: ماذا تريدين من وراء تصرفاتك؟ فأجابت: أريد الطلاق، فطلقها أكثر من ثلاث مرات وهو واقف، فقالت: هل طلقت بالثلاث؟ قال: بالعشرة، علمًا بأنه يعتقد أن الطلاق بأكثر من واحدة في مجلس واحد يعتبر واحدة، والزوجة أيضًا قد تكون حاملًا، فمتى يراجعها إذا جاز له ذلك؟","title":"حكم الطلاق بالثلاث في المجلس الواحد حال الغضب","answer":"الجواب:  هذه المسألة تحتاج إلى تأمل في حال الرجل في حال الطلاق وغضبه، وكذلك ألفاظه التي وقعت منه، فبإمكانه أن يتصل بالمحكمة، والمحكمة تنظر في أمره، تسأله عن الواقع، وتسأل الزوجة ووليها حتى يكون الجواب على بصيرة، وعلى علم بالواقع من جميع الوجوه، فأوصي السائل أن يتصل بالمحكمة، ويسأل أو يتصل بي في أي وقت، وأنا أنظر في الأمر -إن شاء الله- بعد سؤال المرأة عما عندها، وسؤال الولي عما عنده، حتى تكون الفتوى على شيء واضح، نسأل الله للجميع التوفيق والهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9120/حكم-الطلاق-بالثلاث-في-المجلس-الواحد-حال-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36304.mp3","categories":["الطلاق"]},{"id":11025,"question":"يقول: لقد حلفت بالطلاق على ألا أعمل في إحدى الشركات لكون راتبها قليل، ولكن لظروف معينة اضطررت للعمل في تلك الشركة، فما حكم ذلكم الطلاق؟","title":"حكم من حلف بالطلاق ألا يعمل ثم اضطر للعمل","answer":"الجواب:  إذا كان مقصودك الترك والامتناع، وليس قصدك إيقاع الطلاق إن عدت إلى الشركة فإنه لا يقع الطلاق، وعليك كفارة يمين، حكمه حكم اليمين، وهي إطعام عشرة مساكين -عشرة فقراء- أو كسوتهم، أو عتق رقبة، كل واحد يعطى نصف صاع، كيلو ونصف من التمر أو الحنطة أو الرز، نصف صاع، كيلو ونصف، أو قميص، أو إزار ورداء يجزئان في الصلاة، أو عتق عبد، فإن عجزت تصم ثلاثة أيام، هذا إذا كنت ما قصدت الطلاق إنما قصدت الامتناع، ومنع نفسك من الشركة. أما إن كنت قصدت إيقاع الطلاق فإنه يقع الطلاق، فإذا قلت: علي الطلاق ما أعمل عند الشركة، وقصدك إيقاع الطلاق تقع طلقة واحدة، إذا عملت عندهم تراجع زوجتك، إذا كنت ما طلقتها قبل هذا طلقتين راجعها، أما إذا كنت ما أردت إلا الامتناع من التوظف عندها، وليس قصدك إيقاع الطلاق، فهذا له حكم اليمين كما تقدم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9203/حكم-من-حلف-بالطلاق-الا-يعمل-ثم-اضطر-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36704.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":11052,"question":"من الجمهورية العربية السورية دمشق المرسل (أ. ب) رمز لاسمه بهذا الرمز، يقول: خلال ثورة غضب عارمة من الزوجة على زوجها أصرت عليه، وألحت بأن يطلقها، علمًا بأن الزوج لم يكن له الرغبة في ذلك، واستجاب لطلبها مرغمًا وتلفظ بالطلاق، فهل يعتبر هذا واقعًا؟ أفيدونا مأجورين.","title":"حكم من طلق امرأته طلبًا لرغبتها","answer":"الجواب:  نعم، ما دام طلقها باختياره وكونها اشتدت هي، ما هو بعذر له، لا يلزمه أن يطلق، لكن ما دام أجاب رغبتها وطلقها يقع الطلاق الشرعي، إذا طلقها طلاقًا شرعيًا في طهر لم يجامعها فيه، وليست حبلى ولا آيس، أو طلقها في حال الحمل يقع. أما إذا طلقها في حال حيضها، أو نفاسها وهو يعلم بذلك، يعلم أنها حائض، أو نفساء، فلا يقع الطلاق على الصحيح لحديث ابن عمر المخرج في الصحيحين، أو طلقها بطهر جامعها فيه، وليست حبلى ولا آيسة، وهو يعلم ذلك لم يقع على الصحيح لحديث ابن عمر، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9230/حكم-من-طلق-امراته-طلبا-لرغبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28808.mp3","categories":["الطلاق"]},{"id":11053,"question":"سماحة الشيخ عبدالعزيز، تساهل الناس بلفظ الطلاق، ثم يأتون إلى العلماء يستفتونهم في هذا، هل من كلمة توجيهية عن هذا مأجورين؟","title":"التساهل بالطلاق","answer":"الجواب:  نعم نوصي إخواننا جميعًا بالحذر من التساهل بالطلاق؛ لأنه يفرق بين الرجل وأهله، وفي الحديث الصحيح يقول النبي ﷺ: أبغض الحلال إلى الله الطلاق هكذا جاء عنه -عليه الصلاة والسلام- بإسناد حسن، فالمشروع للمؤمن أن يتحفظ، وأن يحذر ما يفرق بينه وبين أهله، وأن يعالج الأمور والمشاكل التي بينه وبين أهله بالحكمة، والكلام الطيب، والأسلوب الحسن، لا بالطلاق، فالطلاق يفرق بين الزوجين، فينبغي للمؤمن أن يحذر الطلاق إلا عن وطر، عن قصد، عن رغبة في الطلاق فلا بأس، وإلا فليحذر إيقاع الطلاق بسبب المشاكل والغضب، بل يتحرى حل المشاكل بالكلام الطيب، والأسلوب الحسن الذي تنهى به المشاكل من دون وقوع في الطلاق، أما إذا كان يرغب في الطلاق لسوء خلقها، أو لأسباب أخرى فلا بأس، الله شرع الطلاق، يطلق واحدة لا يزيد عليها، يطلق واحدة والحمد لله طلقة واحدة، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9231/التساهل-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28809.mp3","categories":["الطلاق"]},{"id":11166,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المستمع عبدالله مقيم في الرياض يقول: حلفت بالطلاق لأحد الإخوان حتى يأخذ مبلغًا من المال فرفض وحلف بالله أن لا يأخذ المبلغ، فهل وقع الطلاق حينئذٍ جزاكم الله خيرًا؟","title":"حكم الحلف بالطلاق بنية الحث أو المنع أو الإلزام","answer":"الجواب:  هذا فيه تفصيل: إن كان المقصود إلزامه بالأخذ، التأكيد عليه، وليس قصدك إيقاع الطلاق فإنه لا يقع الطلاق ويكون له حكم اليمين، وعليك كفارة يمين، فإذا قال الإنسان: عليه الطلاق أن تأخذ هذه الدراهم، أو عليه الطلاق أن تأكل الطعام، أو عليه الطلاق أن تخرج من البيت، أو عليه الطلاق أن تسافر إلى كذا، ولم ينفذ يكون عليك كفارة يمين، إذا كان المقصود التأكيد في الموضوع ليس المقصود إيقاع الطلاق، وإنما المقصود التأكيد فيما ذكر، فإنه يكون في حكم اليمين، وعليه كفارة اليمين، إذا أخل المحلوف عليه بالشرط ولم يمتثل، فإذا قال: عليه الطلاق أن تشرب القهوة وأبى وقصده إلزامه ليس قصده تطليق زوجته، وإنما المقصود إلزامه، والتأكيد عليه، فهذا فيه كفارة يمين، وهكذا لو قال لزوجته: عليه الطلاق أن لا تخرجي من البيت، أو أن لا تكلمي فلانًا والقصد المنع، المنع من الخروج أو من الكلام فلم تمتثل فإن عليه كفارة يمين، ولا يقع الطلاق؛ لأن هذه الأنواع كلها في حكم اليمين، والمقصود منها التأكيد بفعل شيء أو منع شيء، أما إذا كانت له نية أخرى ..... ينظر فيه إذا وقع، يستفتي فيه العلماء ويفتونه إذا كان له نية أخرى غير هذا غير نية المنع والحث. فالمقصود: أن هذه الشروط فيها تفصيل: تارة صاحبها يقصد المنع من شيء، أو الحث على شيء، وتارة يقصد هذا مع الطلاق، فإذا قصد الأمرين جميعًا وقع الطلاق، إن لم يكن هناك مانع من وقوعه، نعم، من حيض أو نحو ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9351/حكم-الحلف-بالطلاق-بنية-الحث-او-المنع-او-الالزام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37115.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":11180,"question":"من جدة رسالة بتوقيع أحد الإخوة يقول: أخوكم في الله سعد، الأخ سعد يقول: الزوجة التي لا تصلي ليس بإرادتها؛ بل بسبب الوساوس، هل يجوز لزوجها معاشرتها وأن تبقى معه، فهي لا تستطيع الوضوء ولا حتى التيمم لمرضها كما قلت: بالوسواس، هل تصلي بدون وضوء؟","title":"كيفية العمل مع الزوجة التي لا تصلي بسبب الوساوس","answer":"الجواب: الواجب تعليمها وتوجيهها، وأن الوساوس التي تعتريها لا يجوز لها أن تميل إليها وأن تستعملها حتى تضيع الصلاة، بل يجب أن تدعها وأن تصلي، وعليك أن توضح لها ذلك وأن تأمرها بذلك، ولو بالتأديب ولو بالضرب المناسب غير المبرح؛ لأن ترك الصلاة كفر أكبر، فلابد أن تعتني بهذا الأمر وأن تلزمها بالصلاة وأن توجهها إلى الخير؛ حتى تدع الوساوس وحتى تصلي الصلاة التي فرض الله عليها، هذا يحتاج إلى جهاد وصبر لابد؛ لأن الجهل داء عضال. فلابد من التعليم والتوجيه والإرشاد منك ومن أمها وأبيها إن كان لها أبوان من أقاربها، لابد من التعاون على البر والتقوى حتى تفهم الأمر الشرعي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9369/كيفية-العمل-مع-الزوجة-التي-لا-تصلي-بسبب-الوساوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37214.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":11211,"question":"هذا السائل من الطائف أبو فيصل يقول: يا سماحة الشيخ! بأنه قبل ثلاثة أعوام حلف على زوجته بكلمة الحرام، بأنك لو فعلت كذا وكذا لن تسافري إلى أهلك وقد فعلت ذلك الأمر، يقول: ولنسيان الحلف بالحرام فقد سافرنا إلى أهلها، وقد تكرر ذلك الأمر منها مرتين، وتكرر أيضًا مني الحلف بالحرام، أرجو من فضيلتكم التوجيه؟","title":"حكم من حلف بالحرام ألا تفعل زوجته شيئًا ففعلته ناسية","answer":"الجواب:  إذا كان السفر عن نسيان فلا شيء، يقول الرب جل وعلا: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، وثبت عن رسول الله: إن الله جل وعلا قد فعل، فالناسي لا شيء عليه، إذا قلت: علي الحرام لا تسافرين في يوم كذا وسافرت نسيانًا فلا شيء.  أما إن كانت عمدًا وأنت تقصد منعها ألا تسافر، قلت: علي الحرام، مقصودك منعها، لم تقصد تحريمها إنما قصدت المنع والتخويف فهذا فيه كفارة اليمين إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز صام ثلاثة أيام، إذا كان المقصود التخويف والمنع والتحذير. أما إذا كان المقصود تحريمها عليك إذا سافرت فعندها يجب عليك كفارة الظهار وهي: عتق رقبة، فإن عجزت تصوم شهرين متتابعين ستين يومًا، فإن عجزت تطعم ستين مسكينًا ثلاثين صاعًا تسعين كيلو، كل فقير له نصف الصاع كيلو ونصف. أما إذا كان المقصود التحذير والتخويف، قلت: علي الحرام لا تسافرين، وقصدك التخويف والتحذير فهذا كفارة يمين، إذا فعلت المحلوف عليه عامدة، أما إن كانت ناسية فلا شيء عليك. نعم.","link":"https://binbaz.org.sa/fatwas/9392/حكم-من-حلف-بالحرام-الا-تفعل-زوجته-شيىا-ففعلته-ناسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29111.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":11247,"question":"يسأل سماحتكم عن المرأة التي دائمًا تطلب الطلاق من زوجها، ما هو توجيهكم لها ولأمثالها جزاكم الله خيرًا؟","title":"حكم المرأة التي تكثر طلب الطلاق من زوجها","answer":"الجواب:  إن كانت مظلومة أو ظلمها وتعدى عليها فهي معذورة، أما إذا كانت تطلب الطلاق من غير بأس فلا يجوز لها ذلك؛ يقول النبي ﷺ: أيما امرأة سألت الطلاق من غير ما بأس لم ترح رائحة الجنة، كونها تطلب الطلاق من غير علة شرعية لا يجوز، الواجب عليها الصبر والاحتساب، وعدم الطلب للطلاق.  أما إذا كانت هناك علة؛ لأنه يغضبها ويؤذيها، أو لأنه يتظاهر بالفسق وشرب المسكرات، أو لأنه لم تقع في قلبها محبة له بل تبغضه كثيرًا، ولا تستطيع الصبر فلا بأس، مثلما فعلت زوجة ثابت بن قيس طلبت من النبي ﷺ أن يفرق بينها وبينه، فسألها النبي ﷺ عن ذلك؟ فقالت: إنها لا تطيقه بغضًا، إنها لا تطيقه بغضًا، فقال لها عليه الصلاة والسلام: أتردين عليه حديقته؟ -يعني: المهر، الحديقة: بستان - فقالت: نعم، فأمره أن يقبل الحديقة ويطلقها تطليقة، والعلة أنها لا تستطيع البقاء معه من أجل البغض، والحياة مع البغض ما تستقيم. فلهذا يلزمها أن ترد المهر، فإذا ردت المهر فعليه أن يطلق، والله يقول سبحانه: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ وَكَانَ اللَّهُ وَاسِعًا حَكِيمًا [النساء:130]. وهكذا إذا كان يتعاطى السكر، أو معروفًا بالتساهل في الزنا وتعاطي الفحشاء، هذا لها عذر لأن البقاء معه يضرها. أما إن كان لا يصلي فلا يجوز لها البقاء معه، إذا كان لا يصلي فالواجب عليها الامتناع منه، وعدم تمكينه من نفسها؛ لأن ترك الصلاة كفر أكبر على الصحيح، وإن لم يجحد وجوبها، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالأمر عظيم، فإذا كان لا يصلي فليس لها البقاء معه، نسأل الله العافية والسلامة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9429/حكم-المراة-التي-تكثر-طلب-الطلاق-من-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37402.mp3","categories":["الطلاق"]},{"id":11259,"question":"يسأل سماحتكم عن المرأة التي دائمًا تطلب الطلاق من زوجها، ما هو توجيهكم لها ولأمثالها جزاكم الله خيرًا؟","title":"حكم المرأة التي تكثر طلب الطلاق من زوجها","answer":"الجواب:  إن كانت مظلومة أو ظلمها وتعدى عليها فهي معذورة، أما إذا كانت تطلب الطلاق من غير بأس فلا يجوز لها ذلك؛ يقول النبي ﷺ: أيما امرأة سألت الطلاق من غير ما بأس لم ترح رائحة الجنة، كونها تطلب الطلاق من غير علة شرعية لا يجوز، الواجب عليها الصبر والاحتساب، وعدم الطلب للطلاق.  أما إذا كانت هناك علة؛ لأنه يغضبها ويؤذيها، أو لأنه يتظاهر بالفسق وشرب المسكرات، أو لأنه لم تقع في قلبها محبة له بل تبغضه كثيرًا، ولا تستطيع الصبر فلا بأس، مثلما فعلت زوجة ثابت بن قيس طلبت من النبي ﷺ أن يفرق بينها وبينه، فسألها النبي ﷺ عن ذلك؟ فقالت: إنها لا تطيقه بغضًا، إنها لا تطيقه بغضًا، فقال لها عليه الصلاة والسلام: أتردين عليه حديقته؟ -يعني: المهر، الحديقة: بستان - فقالت: نعم، فأمره أن يقبل الحديقة ويطلقها تطليقة، والعلة أنها لا تستطيع البقاء معه من أجل البغض، والحياة مع البغض ما تستقيم. فلهذا يلزمها أن ترد المهر، فإذا ردت المهر فعليه أن يطلق، والله يقول سبحانه: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ وَكَانَ اللَّهُ وَاسِعًا حَكِيمًا [النساء:130]. وهكذا إذا كان يتعاطى السكر، أو معروفًا بالتساهل في الزنا وتعاطي الفحشاء، هذا لها عذر لأن البقاء معه يضرها. أما إن كان لا يصلي فلا يجوز لها البقاء معه، إذا كان لا يصلي فالواجب عليها الامتناع منه، وعدم تمكينه من نفسها؛ لأن ترك الصلاة كفر أكبر على الصحيح، وإن لم يجحد وجوبها، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالأمر عظيم، فإذا كان لا يصلي فليس لها البقاء معه، نسأل الله العافية والسلامة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9429/حكم-المراة-التي-تكثر-طلب-الطلاق-من-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37402.mp3","categories":["الطلاق"]},{"id":11445,"question":"يقول: أتيت من عملي وأنا غضبان، فقابلتني زوجتي وهي تصرخ فقلت لها: اسكتي، أو أطلقك؟ فقالت لي: طلقني، فطلقتها ثلاثًا، وبعد ذلك أريد استرجاعها، فماذا أعمل؟ جزاكم الله خيرًا.","title":"حكم من طلق زوجته ثلاثاً حال الغضب","answer":"الجواب:  نرى حضورك معها، ووليها عند المحكمة؛ للنظر في أمركم، وإفتائكم، أو إثبات الواقع، وإيحالته إلي، وأنا أنظر في الأمر، إن شاء الله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9626/حكم-من-طلق-زوجته-ثلاثا-حال-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38102.mp3","categories":["الطلاق"]},{"id":11470,"question":"رجل في حالة غضب شديد طلق زوجته، وقال: أنت علي مثل الوالدة، وبعد فترة استرجعها، فهل ما فعله صحيح؟ جزاكم الله خيرًا.","title":"حكم الطلاق حال الغضب الشديد","answer":"الجواب: يراجع المحكمة وتنظر المحكمة في موضوعه، أو يراجعنا وننظر في الأمر -إن شاء الله- لأجل معرفة حال ما لدى المرأة وما لدى وليها، وكيفية الواقع، يحتاج إلى نظر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9651/حكم-الطلاق-حال-الغضب-الشديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38125.mp3","categories":["الطلاق"]},{"id":11565,"question":"المستمع جابر محمد علي زيدان من جمهورية مصر العربية يقول في سؤال مطول: إنني أقسمت على زوجتي بالطلاق، وعلى المذاهب الأربعة، بأنك لو ذهبت إلى منزل والدك في حال زعل بدون علمي؛ فتكوني محرمة علي مثل والدتي، علمًا بأن لديها طفل وفي حالة حمل، وعلمًا بأن هذا أول طلاق صدر بيننا، فما الحكم؟ وبم توجهوننا؟ جزاكم الله خيرًا.","title":"حكم الحلف بالطلاق مع المظاهرة من الزوجة","answer":"الجواب:  هذا فيه تفصيل: إن كنت أردت الطلاق والتحريم جميعًا، فإنها يقع عليها طلقة، وتحرم عليك كظهر أمك، وعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، فإن عجزت تطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع بين اثنين، والصاع ثلاثة كيلو تقريبًا، وكل واحد يعطى نصف الصاع كيلو ونصف من قوت البلد، من تمر أو أرز أو غيرهما، إذا كنت تعجز عن العتق، وعن صيام شهرين متتابعين، ويقع عليها طلقة واحدة تراجعها في العدة، إذا كنت لم تطلقها قبلها طلقتين. أما إن كنت قلت: علي الطلاق تريد بذلك التحريم فقط، ما أردت إيقاع الطلاق، يعني عليك الطلاق أن تحرمها، قصدك عليك الطلاق أن تحرمها قد حرمتها، وعليك كفارة الظهار فقط وهي سهلة، ولا يقع الطلاق، إذا كنت أردت بالطلاق التحريم، يعني: إن قلت: علي الطلاق يعني: أنها محرمة عليك كأمك، وليس قصدك تطليقها إنما قصدك تحريمها، فهذا يكون فيه كفارة الظهار فقط، ولا يقع طلاق. أما إن كنت أردت الأمرين: أنها يعني تطلق، وتحرم، كظهر أمك، فإنها يقع عليها طلقة واحدة، وتراجعها إذا ما كان قبلها طلقتان، وعليك أيضًا كفارة الظهار؛ لأن تحريمها كأمك، وكفارة الظهار -كما سبق- مرتبة أولًا: عتق رقبة مؤمنة إن تيسر، فإن لم يتيسر؛ فصيام شهرين متتابعين، ستين يومًا، فإن عجزت عن هذه؛ تطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع مقداره ثلاثة كيلو تقريبًا، كل مسكين يعطى صاعًا، كيلو ونصف تقريبًا من قوت البلد، من تمر أو أرز أو حنطة أو شعير أو دخن، أو على حسب حال البلد، مع التوبة والاستغفار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9748/حكم-الحلف-بالطلاق-مع-المظاهرة-من-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29714.mp3","categories":["الطلاق","الظهار"]},{"id":11634,"question":"يقول: لقد حصل بيننا في البيت نقاش ومشادات وقام والدي وطلق والدتي بالثلاث، أي قال: أنت طالق، طالق، طالق، وأخذت والدتي معي إلى بيتي، وبعد فترة جاءني أخي الأكبر، وقال: أنا استفسرت وقالوا: إنه يمكن أن تعود والدتك إلى والدك، والآن نريد عودتها، ورجعت، ثم بعد فترة عادت إلي والدتي لكي تعيش معي، أرجو الإفادة عن ذلكم الموضوع وهل يجوز رجوعها؟ وهل هناك شروط أم لا؟ جزاكم الله خيرًا.","title":"حكم من قال لزوجته: أنت طالق طالق طالق، ثم رجعت إليه","answer":"الجواب:  نرى حضورها مع والدك، ومعك لدى المحكمة، أو لدى مكتب الدعوة إن كنتم في بلد فيه مكتب دعوة. المقدم: في جدة نعم. الشيخ: في مكتب الدعوة في جدة في الشرفية، يكتب كلام والدك، وكلام الزوجة، وننظر في الأمر، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/9835/حكم-من-قال-لزوجته-انت-طالق-طالق-طالق-ثم-رجعت-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38922.mp3","categories":["الطلاق"]},{"id":11653,"question":"من سلطنة عمان المستمع: محمد بن بركات بن محمد الشلبي بعث يقول: نوى شخص طيلة حياته أنه إذا حلف بالطلاق، ووقع هذا الطلاق لا يعتد به، وكانت هذه النية عبارة عن يمين بالطلاق قال فيه: إنه إذا حلف بالطلاق، ووقع؛ لا يكون طلاقًا، فهل هذا جائز؟","title":"حكم تعميم النية عند الحلف بالطلاق بعدم وقوعه","answer":"الجواب:  هذا فيه تفصيل: كل ما وقع يكون له حكمه، وهذا التعميم لا يكفي، فإذا وقع منه الطلاق وقع الطلاق، ولو قاله في السابق: إنه لا .... هذا، العبرة بوقت الفعل، فإذا كان الوقت حين قال: فلانة طالق إن كلمت فلانًا، فلانة طالق إن ذهبت إلى بيت فلان، وهو يقصد الطلاق؛ وقع الطلاق، فالعبرة بنيته التي قرنت العمل، قرنت القول، ما هو بالشيء السابق، فالعمدة على النية التي مع قوله؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى. فإذا علق الطلاق على أمر يقصد الحث عليه، أو المنع منه، أو التصديق، أو التكذيب، هو لم يرد إيقاع الطلاق هذا له حكم اليمين، أما إذا علق الطلاق على فعل يريد إيقاع الطلاق عنده، كأن يقول: إن خرجت إلى بيت فلان فأنت طالق، وقصده إيقاع الطلاق فهو على نيته، يقع الطلاق متى خرجت، أو قال: إن كلمت فلانًا أو فلانة، فأنت طالق، وقصده إيقاع الطلاق، نيته إيقاع الطلاق؛ وقع الطلاق (الأعمال بالنيات). نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9836/حكم-تعميم-النية-عند-الحلف-بالطلاق-بعدم-وقوعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29805.mp3","categories":["الطلاق"]},{"id":11654,"question":"يقول: نفس الشخص صاحب السؤال السابق قال: في إحدى مشاجراته مع زوجته قال لها: اعتبري نفسك مطلقة أو طالقة، فهل هذا طلاق؟ وما حكمه إذا كان طلاقًا؟ وهل له كفارة؟ جزاكم الله خيرًا.","title":"حكم من قال لزوجته: اعتبري نفسك مطلقة","answer":"الجواب:  يعتبر طلاقًا، وليس له كفارة، يعتبر طلاقًا، فإن كانت الثالثة تمت الثلاث، وبانت منه، وحرمت عليه حتى تنكح زوجًا غيره، أما إن كانت هذه الأولى أو الثانية؛ فله المراجعة ما دامت في العدة؛ لقول الله سبحانه: الطَّلاقُ مَرَّتَانِ الآية [البقرة:229]، لكن متى كانت هذه الطلقة هي الثالثة؛ حرمت عليه حتى تنكح زوجًا غيره؛ لقوله سبحانه: فَإِنْ طَلَّقَهَا [البقرة:230] يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230]، إلا أن يمنع مانع من كون الطلاق وقع في حيض، أو في نفاس، أو في طهر جامعها فيه، فإن الصحيح أن هذا لا يقع؛ لحديث ابن عمر في الصحيحين أنه طلق امرأته وهي حائض، فأمره النبي ﷺ بمراجعتها وقال له: إذا طهرت؛ فطلقها، أو أمسك .  فالمقصود: أن الطلاق الأصل فيه الوقوع إلا إذا كان هناك مانع، كأن يطلقها في حال حيضها، أو نفاسها وهو يعلم ذلك، يعلم أنها في حيض، أو نفاس، أو في طهر جامعها فيه وليست حامل، ولا آيسة؛ فهذا لا يقع على الصحيح، إلا إذا حكم به حاكم إذا حكم به حاكم وقع؛ لأن حكم الحاكم يرفع الخلاف. والواجب على المسلم ألا يطلق إلا على بصيرة في طهر لم يجامعها فيه، أو في حال الحمل، حتى لا يقع في خلاف الشرع، بل يتثبت في الأمر إذا أراد الطلاق؛ يتثبت بالأمر، ولا يعجل، فإذا كانت في طهر لم يجامعها فيه، أو في حال حمل، هذا هو الطلاق .... ..... لا يزيد على طلقة، السنة واحدة فقط طلقة واحدة حتى يراجعها إذا أراد، إلا أن تكون الثالثة فالثالثة ليس بعدها رجعة، كما تقدم، وإذا علم أنها حائض، أو في نفاس لا يطلق، يمسك حتى تطهر، أو كانت في طهر جامعها فيه؛ يمسك حتى تحيض، ثم تطهر؛ لأن النبي ﷺ أمر ابن عمر بهذا لما أخبر أنه طلقها وهي حائض، غضب عليه النبي ﷺ وقال النبي ﷺ لأبيه عمر: مره فليراجعها، ثم ليمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شاء طلق قبل أن يمس وتلك العدة التي أمر الله أن تطلق عليها النساء. هذه العدة التي أمر الله أن تطلق عليها النساء أن تكون في طهر ليس فيه جماع، أو في حال الحمل، هذا هو الطلاق الشرعي. فالأحوال خمسة: حال حيض، أو نفاس، أو طهر جامعها فيه، وليست حاملًا، ولا آيسة، هذه الأحوال الثلاث لا يطلق فيها، لا يجوز له الطلاق فيها، الحالة الرابعة: أن تكون في طهر لم يجامع فيه، وليست حاملًا، هذا إذا طلق فيه لا بأس، طلاق شرعي. الحالة الخامسة: أن تكون حاملًا؛ فلا بأس أن يطلق في حال الحمل، لقول النبي ﷺ لابن عمر: طلقها طاهرًا أو حاملًا لكن لا يطلقها أكثر من واحدة، السنة واحدة فقط، حتى إذا المراجعة راجع، ثم إذا أراد أن يطلق ثانية يطلقها واحدة ثانية فقط لا يزيد، حتى لا يضيق على نفسه، ثم إذا شاء راجع، أو لم يراجع بعد الثانية، ثم تأتي الثالثة وهي النهاية. والواجب على المؤمن أن يتدبر هذا الأمر، وأن يكون على عناية بالشرع لا يتساهل، بل يطلق كما أمره الله، ويراجع كما أمره الله، ويتباعد عما حرمه الله في طلاقه، وفي غيره، هكذا المسلم ينظر فيما أوجب الله عليه، وفيما حرم الله عليه، وفيما أباح الله له، فيستقيم على الطريق السوي في فعله وتركه، وفي قوله وعمله؛ لأنه عبد مأمور، عليه أن يتبع شرع الله في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9837/حكم-من-قال-لزوجته-اعتبري-نفسك-مطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29806.mp3","categories":["الطلاق"]},{"id":11708,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (أ. أ. ب) أخونا قضيته قضية طلاق يقول: إذا طلق الرجل زوجته طلقة، ثم تزوجها رجل آخر بعد انقضاء العدة، ثم طلقها، فتزوجها زوجها الأول، ثم طلقها طلقتين، فهل تحسب الطلقة الأولى، وتصبح ثلاث طلقات؟ أم أنهما طلقتان فقط؟ جزاكم الله خيرًا.","title":"حكم من طلق زوجته وتزوجت بغيره، ثم طلقها وعادت للأول","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:  فإن الرجل إذا طلق زوجته طلقة، أو طلقتين، ثم عقد عليها بعد ذلك بعد خروجها من العدة، أو بعد زوج آخر؛ فإنها ترجع بما بقي فقط، ترجع إليه بما بقي، إن كان طلقها طلقة يبقى لها طلقتان، وإن كان طلقها طلقتين يبقى لها واحدة. نعم. المقدم: بارك الله فيكم، وأحسن إليكم، إذًا لا تأثير لذلكم الزواج على عدد الطلقات. الشيخ: لا يؤثر. المقدم: لا يؤثر. الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9888/حكم-من-طلق-زوجته-وتزوجت-بغيره-ثم-طلقها-وعادت-للاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39201.mp3","categories":["الطلاق"]},{"id":11781,"question":"المستمع سالم أبو سيل إبراهيم سوداني وهو مقيم في رابغ حين بعث الرسالة يقول: امرأة غاب عنها زوجها فترة طويلة، ولما طال بها الغياب ذهبت إلى القضاء، وطلقت نفسها، ولم تتزوج حتى عاد زوجها، واتفقا على الرجعة وتراجعا،  هل تحسب تلك طلقة على الرجل، وإذا كان الجواب نعم، ما ذنب الرجل في ذلك؟ أقصد أنه لم يتدخل في الموضوع فما دخله؟ نرجو أن تنورونا، جزاكم الله خيرًا.","title":"حكم من طلقت نفسها من زوجها ثم عاد إليها","answer":"الجواب:  عليهما أن يراجعا المحكمة التي فسخت النكاح، عليهما أن يراجعا المحكمة التي تم على يدها فسخ النكاح، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9967/حكم-من-طلقت-نفسها-من-زوجها-ثم-عاد-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39505.mp3","categories":["الطلاق"]},{"id":11815,"question":"المستمع (س. ع. ع) من الدمام بعث برسالة يقول فيها: أخبركم أنني مطلق، ولدي من مطلقتي ابن يبلغ من العمر ثلاث سنوات ونصف، وقد تم الطلاق بسبب إشاعات، وبسبب نوع من العمل الذي يراد منه التفريق بين المرء وزوجه، وبعد أن ثبت لي بطلان هذه الإشاعات -ولله الحمد- وأعانني الله على التغلب على وسوسة الشيطان بكثرة تلاوة القرآن؛ فقد أبديت لأهل زوجتي رغبتي في الرجوع إليها قبل سنة من الآن، إلا أنهم رفضوا ذلك، ربما لأنهم لا تزال في أنفسهم رواسب من الإشاعات التي ثبت بطلانها، وأنا لا أجد مبررًا لرفضهم إذ أنني -والحمد لله- إنسان مستقيم في حياتي، ومحافظ على أداء الصلاة، وأرغب أن ينشأ ابننا بين أمه وأبيه، لذلك تأثير إيجابي على نفسية الطفل -كما تعلمون جزاكم الله خيرًا- وهناك نقطة مهمة أود أن أشير إليها، وهي أن لدي شعور أن الزوجة لا تمانع كثيرًا في الرجوع، وقد لمست ذلك في السابق منها، ولكن والديها وإخوتها يحولون دون ذلك، أود أن ترشدوني للخروج من هذه المشكلة التي أرى آثارها السلبية قد انعكست على العائلة بأكملها، وعلى الابن بالذات، فما هو السبيل للخروج من هذه المشكلة؟ جزاكم الله خيرًا.","title":"حكم رفض أهل الزوجة مراجعة الزوج لزوجته بعد انتهاء العدة","answer":"الجواب:  عليك أن تراجع المحكمة، وفيما تراه المحكمة الكفاية، عليك أن تراجع المحكمة وفي ذلك الكفاية، وإن تيسر من يصلح بينكم؛ فلا بأس، الصلح خير، إذا أصلح بينكم إنسان، ثم تراجع المحكمة في الطلاق، هل يحرمها عليك، أم لا، فالطلاق ممكن أن تراجع المحكمة حتى تخبرك المحكمة إذا رضوا وسمحوا، تراجعون المحكمة في الإفتاء عن الطلاق الواقع، ومعرفة حقيقته، ثم بعد ذلك تعمل ما توجه إليه المحكمة ما تقل لك المحكمة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9999/حكم-رفض-اهل-الزوجة-مراجعة-الزوج-لزوجته-بعد-انتهاء-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42317.mp3","categories":["الطلاق","الرجعة"]},{"id":11872,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول المرسلة: (س. ف) أختنا عرضنا بعض أسئلة لها في حلقة مضت، وفي هذه الحلقة تسأل سماحتكم وتقول: أبي تزوج امرأة، وطلقها بعد أن أصبح له منها طفلة، ثم أرسل إليها بصك طلاقها، وهو راغب عنها، سامح منها، ولكن أهلها قالوا: إنه لم يطلقها سوى طلقة واحدة، وهي طلقة الصك؛ لأنه عندما طلقها كانت عند أهلها، وبعد خمس سنوات ذهب أبي ليخطب لأخي من القرية التي بها زوجة أبي، فقال والد زوجة أبي لأبي: إذا أردت أن تراجع زوجتك؛ فراجعها، فراجعها أبي، ومهر عليها مهرًا جديدًا، وهي الآن عند أبي، وفي عصمته، أرجو الإفادة ، هل يصح هذا الفعل؟ علمًا بأن أبي عندما طلقها كانت زائرة لأهلها، ولم يكلمها، بل طلقها عند الشيخ، وكان راغبًا عنها، وقد أرسل مع الصك ورقة يطلب من والدها أن يزوجها إذا جاء من يطلب يدها، جزاكم الله خيرًا.","title":"حكم مراجعة الرجل امرأته بعد طلاقها لفترة طويلة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فعلى أبيك أن يراجع المحكمة؛ ليسألها عما أشكل عليه، أو يتصل بي حتى أفهم ما وقع، ثم أخبره بما يجب، نسأل الله للجميع التوفيق. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10056/حكم-مراجعة-الرجل-امراته-بعد-طلاقها-لفترة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_424/42401.mp3","categories":["الطلاق"]},{"id":12004,"question":"رسالة مطولة باعثها مستمع يقول: التائب إلى الله (ش. ع)، يقول: كان مبتلى بشرب الخمر، وذات مرة شرب الخمر، ودخل منزله، وغاضب زوجته، وحينئذ اتصلت بأهلها، وذهبت إليهم، وأفادت بأن الرجل قد طلقها، وهو لا يعلم عن ذلك، وحينئذٍ يسأل سماحتكم عن الحكم. جزاكم الله خيرًا.","title":"حكم طلاق السكران","answer":"الجواب:  إذا كان لا يشعر، وإنما زوجته هي التي خبرت عنه، وهو لا يشعر بالطلاق، لا يقع لعدم العقل، إذا كان لا يشعر بذلك، ولكن سمعته زوجته، أو غيرها؛ فإن الطلاق لا يقع، أما إذا كان يعقله؛ وقع. المقدم: جزاكم الله خيرًا، إذًا تعود إليه زوجته، والحال ما ذكر؟ الشيخ: نعم، نعم. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10189/حكم-طلاق-السكران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43118.mp3","categories":["الطلاق"]},{"id":12014,"question":"مستمع يقول: أنا رجل طلقت زوجتي ثلاث طلقات، ولم أنطق بها، بل كتبت ذلك في ورقة، وقلت: فلانة بنت فلان طالق طالق طالق، وقد أخرجت صك الطلاق، والآن أنا ندمت، وكنت غاضبًا لظروف أحيلت علي، وللعلم أنا أريدها، وقد مر على طلاقنا ثلاث سنوات، فأرجو الإفادة جزاكم الله خيرًا.","title":"حكم الطلاق عن طريق الكتابة","answer":"الجواب:  عليك أن تراجع الذي أعطاك الصك، وفيما يراه الكفاية إن شاء الله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10199/حكم-الطلاق-عن-طريق-الكتابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43205.mp3","categories":["الطلاق"]},{"id":12038,"question":"إذا لاحظت على زوجتي أنها تعادي والدتي بكل وضوح، فهل يجب علي طلاقها؟","title":"حكم طلاق امرأة تؤذي والدة الزوج","answer":"الجواب:  هذا فيه تفصيل، إن أمكن تعديلها، ونصيحتها، وتوجيهها إلى الخير؛ حتى تستقيم مع الوالدة؛ فعلت ذلك، وهكذا الوالدة إذا أمكن أن تصلح بينها وبينها بالكلام الطيب، والأسلوب الحسن؛ فهذا أطيب، أما إذا كانت تؤذي الوالدة، ويترتب على بقائها أذى للوالدة؛ فالواجب فراقها؛ لأن هذا من عقوق الوالدة. فالمقصود: إذا كانت المرأة تؤذي الوالدة؛ فالواجب فراقها، إلا أن تسمح الوالدة وتقول: لا، لا تفارقها وأنا أتصبر، وترى المصلحة في عدم فراقها؛ فالأمر إليها. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10223/حكم-طلاق-امراة-توذي-والدة-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43307.mp3","categories":["الطلاق"]},{"id":12105,"question":"رسالة مطولة بتوقيع إحدى الأخوات المستمعات تقول المرسلة (ح. س. د) أختنا لها مشكلة في كتابة مطولة، ملخص هذه القضية أنها ابتليت بزوج سكير، وقد اكتشفت أنه كذلك بعد سنتين من الزواج، لكنه غير مدمن كما تصفه، بل يشربه بين فترة وأخرى، وحينئذٍ أنكرت عليه؛ فحلف لها بالطلاق ثلاث مرات أنه لا يسكر، لكنه عاد، ما هو توجيهكم؟","title":"حكم من حلف بالطلاق ألا يشرب الخمر ثم عاد","answer":"الجواب:  الواجب نصيحته، وتحذيره من مغبة هذا العمل السيئ، فإن الخمر من أقبح السيئات، ومن أقبح الكبائر، فالواجب على هذا الرجل أن يتقي الله، وأن يدع هذا الشراب الخبيث، والرسول ﷺ: لعن الخمر وشاربها وساقيها وحاملها والمحمولة إليه وعاصرها ومعتصرها وبائعها ومشتريها وآكل ثمنها وقال ﷺ: لا يشرب الخمر حين يشربها وهو مؤمن وهذا من باب الوعيد الشديد؛ لأنها تنافي كمال الإيمان الواجب، فالواجب عليه أن يتقي الله، وأن يتوب إلى الله، وعليك أن تنصحيه، وتحذريه من شؤمها. وأما طلاقه ألا يشرب؛ فهذا فيه تفصيل: إن كان طلق ألا يشرب وقصده الامتناع، وليس قصده وقوع الطلاق، ولكن قصده أن يمتنع منه، وأن يشدد على نفسه، وليس قصده إيقاع الطلاق، فعليه كفارة يمين، ولا يقع، أما إن كان قصده إيقاع الطلاق؛ فإنه يقع الطلاق، نسأل الله لنا وله الهداية. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا هل تنصحونه بالبقاء معه، أم تتصرف تصرفًا آخر سماحة الشيخ؟ الشيخ: نوصيها بالبقاء معه والنصيحة، فإذا لم يقبل النصيحة نوصيها بالفراق، ولو بإعطائه ماله، نعم. إذا لم يطلقها بدون مال، أو ترفع أمرها للمحكمة، نعم. المقدم: جزاكم الله خيرًا. وتلك الأيمان بالطلاق ثلاث مرات على ألا يعود ثم يعود؟ \nالشيخ: أخبرناها أن هذا فيه التفصيل: إن كان أراد الامتناع، ولم يرد إيقاع الطلاق؛ فإن عليه كفارة يمين عن كل واحدة، أما إن كان أراد الامتناع مع إيقاع الطلاق إن شرب؛ فإنه يقع الطلاق، وإذا تكرر ثلاثًا؛ حرمت عليه، نعم. حتى تنكح زوجًا غيره، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10290/حكم-من-حلف-بالطلاق-الا-يشرب-الخمر-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43708.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":12160,"question":"المستمع: سليمان ضاوي بعث برسالة يسأل فيها سماحتكم عن الحلف بالطلاق بعد كتابة العقد على الزوجة، وقبل الدخول، هل يؤثر، أو لا يؤثر؟","title":"حكم الحلف بالطلاق بنية الحث أو المنع أو التصديق","answer":"الجواب:  هذا فيه تفصيل: والمشروع ترك الحلف بالطلاق، بالكلية، لا يعتاده، لا يقل: علي الطلاق ما أفعل كذا، علي الطلاق لأفعلن كذا، إن قمت فأنت طالق، يترك هذه المسألة، المشروع للزوج أن يتباعد عن الطلاق، حتى لا يقع فيه، لكن الحلف بالطلاق معناه: تعليقه على أمر يقصد المنع منه، أو الحث عليه، أو التصديق أو التكذيب، هذا يسمى: حلف، يسمى: يمينًا، علي الطلاق ما أفعل كذا، علي الطلاق ما أسافر، علي الطلاق ما أكلم فلانًا، علي الطلاق ما تخرجين المحل الفلاني، علي الطلاق ما تكلمين فلانًا، علي الطلاق أن تدخلي في البيت، علي الطلاق أنك ما تصنيعن الطعام الفلاني، وهكذا، هذا يسمى: يمينًا، إذا كان قصده حث، أو منع، أو تصديق، أو تكذيب، علي الطلاق أني ما فعلت هذا، أني ما قلت هذا الكلام، .... حتى يصدق، يسمى: يمينًا، علي الطلاق أن فلانًا ما هو صادق، يعني يبيه يكذب . علي الطلاق عن أكل طعام فلان ..... حتى يأكله، علي الطلاق ما أكلم فلانًا حتى يمتنع، هذا يسمى: يمينًا، أما لو قال: علي الطلاق إذا دخل رمضان هذا ما يسمى يمينًا، هذا شرط، هذا معلق به، علي الطلاق إذا دخل رمضان، علي الطلاق إذا دخل شوال، علي الطلاق إذا نزل المطر، هذا معناه: التعليق فقط، ما يسمى يمينًا، يسمى: تعليقًا؛ لأن ما فيه حث، ولا منع، ولا تصديق، ولا تكذيب.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10345/حكم-الحلف-بالطلاق-بنية-الحث-او-المنع-او-التصديق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44110.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":12237,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م. ص. محمود) مصري يعمل في العراق حين كتب الرسالة، رسالته يقول فيها: أنا أقيم في دولة غير دولتي، وذات يوم وقع خلاف بيني وبين رجل حول مسألة ما، فحلفت بيمين الطلاق بعكس ما يقول الرجل، ولكن فيما بعد ثبت أن الرجل محق، فاحترت في مسألة يمين الطلاق، سألت أحد الأشخاص، فقال: طالما أنك بعيد عن زوجتك؛ فلا يقع عليك اليمين، وحيث أن الشك لا يزال يخامرني؛ فإنني أرجو الإفادة من قبلكم، جزاكم الله خيرًا.","title":"حكم الحلف بالطلاق على شيء يعتقد صحته ثم ظهر خلافه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه:  ما دمت تعتقد حين الطلاق أنك مصيب؛ فلا شيء عليك، ولا يقع الطلاق، بل هو في حكم اللغو؛ لأن الإنسان إذا حلف على شيء يظنه واقعًا، ويعتقد صدق نفسه، أو يغلب على ظنه ذلك؛ فإنه لا يقع عليه شيء، فلو قال: والله! لقد قدم فلان، والله! لقد مات فلان، وهو يعتقد صحة ما قال، ثم بان الخطأ فيمينه لا شيء عليه فيها، لا كفارة عليه، وهكذا لو قال: علي الطلاق ما صار هذا الشيء، أو قال: صار هذا الشيء، يعتقد أنه واقع ما قصد الكذب؛ فإن طلاقه لا يقع، وأنت لا يقع عليك أيها السائل! إذا كنت تعتقد صحة ما قلت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10425/حكم-الحلف-بالطلاق-على-شيء-يعتقد-صحته-ثم-ظهر-خلافه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44801.mp3","categories":["الطلاق"]},{"id":12238,"question":"رسالة أخرى في الطلاق المستمع (ط. ر. أحمد) سوداني مقيم في المملكة بعث برسالة يقول فيها: قبل ثمانية أعوام طلقت زوجتي، وكنت في حالة غضب، علمًا بأنها لم تكن موجودة أمامي، بل كانت في بيت والدها، وكانت يومها حاملًا في الشهر السابع، وقد راجعتها بعد الوضع، وقد سمعت في برنامجكم أن طلاق السنة أن تكون الزوجة في حالة طهر. أرجو إفادتي: هل ما قمت به في السابق يعتبر طلقة، أم لا؟ وإذا كان يعتبر طلقة، فماذا أفعل وزوجتي معي منذ ثمان سنوات؟ جزاكم الله خيرًا.","title":"حكم من طلق زوجته وهي حامل ثم راجعها بعد الوضع","answer":"الجواب:  إذا كان الواقع كما ذكرت؛ فإنه يقع عليها طلقة واحدة، إذا كان الغضب عاديًا، لم يشتد كثيرًا، ولم يغير الشعور؛ فإنه يقع طلقة واحدة، وأما اعتبار كونها طاهرًا هذا إذا كانت غير حامل، أما إذا كانت حاملًا؛ فطلاقها يقع، الطلاق يقع، وإن كان معها نزيف ما دامت حاملًا، ولو كانت غير طاهرة، ولو كانت على جنابة. فالمقصود من الكلام في الطهارة إذا كانت غير حامل، ينبغي للمؤمن ألا يطلق إلا في طهر لم يجامع فيه، هذا هو المقصود، ليست حاملًا، ولا آيسة، لا يطلق إلا في طهر لم يجامع فيه؛ لأن الرسول ﷺ أنكر على ابن عمر لما طلق زوجته وهي حائض، وأمره أن يمسكها حتى تحيض، ثم تطهر، ثم ليطلق وهي طاهر، أو حامل قبل أن يمسها، يعني: في حال كونها غير حامل. أما إذا وطئها وهي حامل؛ ما يمنع الطلاق، ولو وطئها وهي حامل، أو معها نزيف ليس بحيض، وهي حامل؛ لأن دم الحامل يسمى نزيفًا، ليس بحيض على الصحيح، الحامل لا تحيض. فالمقصود أن طلاق الحامل واقع إذا كان المطلق عاقلًا، معه عقله، ولو كان معه غضب لم يشتد به حتى يخرجه عن شعوره، وعن ضبطه نفسه، وإذا كنت راجعتها قبل أن تضع؛ فرجعتك صحيحة، أما إن كنت راجعتها بعد الوضع؛ فالرجعة غير صحيحة؛ لأنها خرجت من العدة بالوضع، إذا كنت طلقتها في الحمل، ثم تركتها، ولم تراجعها حتى وضعت؛ فقد راجعتها وهي أجنبية، فبقاؤك معها هذه المدة غلط، وعليك أن تمتنع منها مع التوبة إلى الله سبحانه من ذلك؛ لأنك لم تسأل، وعليك -إذا كنت ترغب فيها وهي ترغب فيك- تجديد النكاح بعقد جديد، ومهر جديد؛ لأنها أجنبية. أما إن كنت راجعتها قبل الوضع .... قلت: أنا راجعت زوجتي، أو مراجع زوجتي، أو ما أشبه ذلك قبل أن تضع الحمل؛ فهي زوجتك، وإن كنت ما رددتها للبيت إلا بعد الوضع، إذا كنت أشهدت، أو قلت لها راجعتك قبل أن تضع الحمل، أو أشهدت على ذلك؛ فرجعتها صحيحة، ولو كانت عند أهلها لم ترجعها إلا بعد الوضع، أما إذا كنت ما راجعتها بالكلية، بل سكت، ولم تقل شيئًا حتى وضعت الحمل؛ فإنها تكون بهذا قد خرجت من العدة، ومضى عليها طلقة، ولك العود لها بنكاح جديد بشروطه المعتبرة شرعًا، يعني: بشرط رضاها، وبقية الشروط، وعليكما التوبة إلى الله جميعًا من هذا العمل السيء وهو بقاؤها معك وأنت لم تراجعها إلا بعد الوضع، هذا إذا كنت لم تطلقها إلا طلقة واحدة التي أشرت إليها.  أما إن كان قبلها طلقتان؛ حرمت بهذه الطلقة الأخيرة، إن كان قبلها طلقتان واقعتان، أما إذا كنت لم تطلقها إلا هذه الطلقة التي وقعت منك وهي حامل؛ فإنها لا تحرم عليك بذلك، ولكن لا تصح الرجعة إلا إذا كانت قبل الوضع، والله ولي التوفيق. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10426/حكم-من-طلق-زوجته-وهي-حامل-ثم-راجعها-بعد-الوضع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44802.mp3","categories":["الطلاق"]},{"id":12262,"question":"هنا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، رمز إلى اسمه بالحروف (ع. ح. ب) سوداني، يعمل في بحرة المجاهدين، طريق مكة القديم، رسالته مطولة بعض الشيء، يقول: قبل أربع سنوات كنت في السودان مع أهلي وزوجتي، وحصل خصام بين زوجتي ووالدتي، وأمرت زوجتي أن تصالح والدتي، وقد رفضت تصالحها، وحلفت عليها، وقلت: إذا لم تذهبي إلى والدتي وتصالحيها؛ أنت طالق ثلاث مرات، وقلتها في دفعةٍ واحدة، وبعد هذا الطلاق لم تذهب هي إلى الوالدة، وطردتها إلى أهلها، وهي بنت عمي، وبعد ثلاثة أيام ذهبت إلى شيخ في القرية، وهو على درجةٍ عاليةٍ من الفقه، وأخبرته بما جرى، قال: هذه الزوجة تعتبر مطلقة طلقةً واحدة على قول جمهور أهل العلم، وقال لي: تعتبر هذه الطلقات واحدة؛ لأنك لم تنو الطلاق أصلًا، أرجو أن توجهوني حيال هذا الموضوع، جزاكم الله خيرًا، علمًا بأن لي منها طفلين.","title":"حكم الطلاق بالثلاث بلفظ واحد","answer":"الجواب:  إذا كان الطلاق كما قلت: بلفظ وبكلمة واحدة قلت: أنت طالق بالثلاث، أو مطلقة بالثلاث، فالذي أفتاك بأنها طلقة واحدة مصيب على الراجح، قد ثبت عن النبي ﷺ من حديث ابن عباس -رضي الله عنهما-: أنه كان الطلاق على عهد النبي ﷺ في الطلاق الثلاث كان يجعل واحدة في عهده ﷺ وفي عهد الصديق، وفي أول خلافة عمر  قال ابن عباس: \"كان الطلاق على عهد النبي ﷺ وعلى عهد الصديق، وسنتين من خلافة عمر، طلاق الثلاث واحدة\". فإذا كنت قلت: طالق بالثلاث، أو مطلقة بالثلاث، فإنها تعتبر واحدة، كما أفتاك هذا الفقيه، وجزاه الله خيرًا. ولكن ليس المقصود؛ لأنك ما نويت الطلاق، المقصود أنك طلقت بلفظٍ واحد، قلت: طالق بالثلاث، والإنسان إذا صرح بالطلاق، ولو ما نوى، يؤخذ بكلامه، النية إنما هي في الكنايات التي ليست بصريحة، أما إذا صرح الزوج بالطلاق أخذ بكلامه، وحكم عليه بالطلاق على حسب ما صدر منه، ولكن أنت في هذا أيضًا تسأل عن قصدك، هل قصدك تخويفها وحثها على المصالحة مع أمك، ولم ترد إيقاع الطلاق، وإنما أردت التخويف، فهذا لا يقع به شيء على الصحيح، ويكفيه كفارة يمين، وله حكم اليمين، في أصح قولي العلماء: وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز؛ صام ثلاثة أيام، هذا إذا كان القصد تخويفها،  وتحذيرها، وحثها على المصالحة. أما إن كان قصدك من هذا الطلاق مع التحذير والتخويف إيقاع الطلاق إن لم تذهب إلى أمك؛ فإنه يقع طلقة واحدة كما تقدم، للحديث السابق، والجمهور يرون أنه يقع الثلاث، أكثر العلماء يرى أنه يقع الثلاث، لكن الصواب أنه لا يقع إلا واحدة، إذا كنت أردت إيقاع الطلاق إن لم تصالح أمك وتذهب إليها. ونوصيك بعدم فعل هذا مرةً أخرى، لا تعجل في الطلاق، وإذا طلقت طلق واحدة فقط، قل: طالقة فقط، أو مطلقة فقط، لا تزد على هذا، هذا هو المشروع، لأن النبي ﷺ غضب على من طلق بالثلاث، وقال: أيلعبب بكتاب الله وأنا بين أظهركم فلا ينبغي، ولا يجوز التطليق بالثلاث، ثم إنه تضييق على نفسك، والله قد وسع عليك، فلا يسوغ لك أن تطلق بالثلاث، بل طلق واحدة، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10462/حكم-الطلاق-بالثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44913.mp3","categories":["الطلاق"]},{"id":12268,"question":"يقول: الحلف بالطلاق عندنا شيء عادي، يطلق المتزوج، وغير المتزوج، وعند أوهى الأسباب، والكل لا يعني به ما يقول، حيث أصبح يجري على اللسان بدون قصد، فهل يقع الطلاق في هذه الحالة، أم أنه يعتبر من لغو القول؟ أفيدونا، جزاكم الله خيرًا.","title":"الحث على عدم التلاعب بألفاظ الطلاق وكثرة الحلف بها","answer":"الجواب:  الواجب عدم التلاعب بالطلاق، ولا ينبغي للمؤمن أن يتلاعب بالطلاق، وإذا حصل له شيء؛ يسأل أهل العلم عما وقع له من المفتي، أو قاضي المحكمة في الأحوال الشخصية، أو العلماء المشهورين بالعلم والفضل، يسألهم عما حصل له؛ لأن هذه أمور تختلف بحسب الواقع، فعلى من وقع له شيء من ذلك أن يسأل أهل العلم، مفتي البلد، أو قاضيها، العالم .. الذي يقضي بين الناس في الأحوال الشخصية، أو العالم المشهور عندهم في البلد يسأله عما جرى له، وهو يفتيه بما يعلمه من الشرع المطهر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10468/الحث-على-عدم-التلاعب-بالفاظ-الطلاق-وكثرة-الحلف-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45005.mp3","categories":["الطلاق"]},{"id":12441,"question":"مع مطلع هذه الحلقة نعود إلى رسالة إحدى الأخوات المستمعات، تقول: أم خالد من مكة المكرمة، أم خالد عرضنا قضية لها في حلقة مضت، وفي هذه الحلقة بقي لها بعض القضايا نعرضها على سماحة الشيخ، فتقول في إحداها: إنه قد حصل بيني وبين زوجي مشكلة، وضربني في ليلة من رمضان، وقال لي وهو في حالة غضب شديد: أنت مائة وستون طالق، ولم يسمع هذا الكلام غيري، ولما تصالحنا، وأخبرته بموضوع الطلاق، قال لي: إنه لا يعتبر طلاقًا؛ لأنه كان في حالة غضب شديد، وأنه لم يطلقني، وبعد ثلاث سنوات من هذه المشكلة المذكورة أعلاه، حصل بيني وبينه خلاف، وأنا في حالة ولادة، وقال لي: أنت ستون طالق، ولما أخبرته بذلك بعد ذلك الحال، قال أيضًا: إنه لم يطلق؛ لأنه كان في حالة غضب، وأريد أن أخبركم بأنني امرأة وحيدة، ومقطوعة من شجرة، فإذا كنت أصبحت طالقًا، أو مطلقة منه، فهل أستطيع أن أعيش معه في بيت واحد، ولكن كل منا يبقى غريبًا عن الآخر؛ من أجل أولادي فقط، حتى ييسر الله علي؟ أرجو إفتائي في هذا، جزاكم الله خيرًا.","title":"حكم طلاق الغضبان وطلاق المرأة حال نفاسها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد سبق أن ذكرنا لك، أن الواجب عليك الامتناع منه، وعدم تمكينه منك، مادام لا يصلي؛ فهو كافر، وليس له حق عليك في التمتع بك. أما الطلاق الذي صدر منه، فإذا كان قد اشتد غضبه، ولا يعي ما يقول من شدة الغضب في المرة الأولى والثانية؛ فلا يقع الطلاق، إذا كان غضبًا شديدًا قد غير عليه شعوره بسبب طول النزاع بينك وبينه حتى اشتد غضبه، وتغير شعوره؛ فإنه لا يقع الطلاق.  أما إذا كان غضبًا خفيفًا لم يغير الشعور، ولم يشتد عليه حتى أغلق عليه عقله؛ فإنه يقع به الطلاق، فهذا يحتاج إلى أنه يسأل أهل العلم، وهذا كله بعد توبته إلى الله، بعد توبته من ترك الصلاة، أما أنت الآن فلا يقربك أبدًا حتى يتوب إلى الله من ترك الصلاة. وأما إذا كان الطلاق الأخير في النفاس فلا يقع أيضًا؛ إذا كان في النفاس ما بعد طهرت من النفاس؛ فلا يقع، يكون لعلتين شدة الغضب، وكونه في النفاس.  أما الأول فإذا كان قد تغير شعوره بسبب طول النزاع، والكلام بينك وبينه، وشدة الغضب التي أوجبت أنه ضربك، وتغير شعوره؛ فإنه لا يقع الطلاق، أما الغضب المتوسط الذي ليس فيه شدة تغلق عليه شعوره، وتضيع عليه عقله؛ فإنه يقع معه الطلاق. فأنت اتصلي بالمحكمة، وأخبريها بالواقع؛ حتى تنظر المحكمة في الموضوع، وحتى تمنعه منك، وحتى تقيم عليه حد الله في تركه الصلاة، وإذا تاب؛ تاب الله عليه، نسأل الله له الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/10641/حكم-طلاق-الغضبان-وطلاق-المراة-حال-نفاسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45601.mp3","categories":["الطلاق"]},{"id":12477,"question":"أحد الإخوة المستمعين يقول: المرسل (ج . أ. صالح) يسأل ويقول: لقد ضايقني كفيلي، وحملني أكثر مما أطيق، وذات مرة قلت: تكون زوجتي طالق إذا رجعت مرة ثانية، أسمعت بها نفسي، ثم رجعت مرة ثانية، مع العلم أنني ذهبت إلى بلدي، ومكثت فيها ستة أشهر، ثم رجعت، والآن مر أكثر من عام ونصف، مع العلم أيضًا أن ذلك من باب التحدث بالنعم أنني من حفظة كتاب الله، وأحفظ القرآن كله تقريبًا، وكنت أعلم ابن كفيلي أحكام التجويد؟ وجهوني جزاكم الله خيرًا.","title":"حكم من قال: تكون زوجتي طالقًا إذا رجعت ورجع","answer":"الجواب:  هذا فيه تفصيل: إن كنت أردت بقولك: إذا رجعت فامرأتك طالقة الامتناع من الرجوع، وليس قصدك إيقاع الطلاق، قصدك منع نفسك من الرجوع، وليس قصدك بذلك تطليق امرأتك، فهذا حكمه حكم اليمين، وعليه كفارة يمين، أما إن كنت قصدت الطلاق؛ فإنه يقع الطلاق... مانع من وقوعه. فالحاصل: أنك تسأل قاضي البلد عندك، تحضر مع المرأة ووليها حتى يرشدك القاضي إلى الواجب، فالمقصود أن هذا فيه تفصيل، وفي قرار المحكمة لديكم -إن شاء الله- الكفاية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10687/حكم-من-قال-تكون-زوجتي-طالقا-اذا-رجعت-ورجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40508.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":12478,"question":"سؤالها الأخير تقول فيه: هل يجوز للمرأة المطلقة أن تجلس مع مطلقها إذا كان لها منه أولاد، فتجلس هي وأولادها معه؟ جزاكم الله خيرًا.","title":"حكم جلوس المطلقة عند مطلقها من أجل أولادها","answer":"الجواب:  لا مانع من جلوس المطلقة مع مطلقها، سواء كان لها أولاد، أو ما لها أولاد، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237] فإذا جلست معه، أو سلمت عليه، أو ردت عليه السلام، أو سألته عن حاله، وحال عياله كل هذا لا بأس به، لكن من دون خلوة، يكون معهم غيرهم، بحضرة أخيها، أو أبيها، أو أبي زوجها، أو أمه، أو بعض أخواته. فالمقصود: لا تخلو به، لأن الرسول ﷺ نهى عن الخلوة، يقول ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما فإذا كلمته من غير خلوة، أو سلمت عليه، أو جلست في مجلس هو فيه للتحدث بالحديث الجائز؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10682/حكم-جلوس-المطلقة-عند-مطلقها-من-اجل-اولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40503.mp3","categories":["الطلاق"]},{"id":12484,"question":"سؤالها الأخير تقول فيه: هل يجوز للمرأة المطلقة أن تجلس مع مطلقها إذا كان لها منه أولاد، فتجلس هي وأولادها معه؟ جزاكم الله خيرًا.","title":"حكم جلوس المطلقة عند مطلقها من أجل أولادها","answer":"الجواب:  لا مانع من جلوس المطلقة مع مطلقها، سواء كان لها أولاد، أو ما لها أولاد، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237] فإذا جلست معه، أو سلمت عليه، أو ردت عليه السلام، أو سألته عن حاله، وحال عياله كل هذا لا بأس به، لكن من دون خلوة، يكون معهم غيرهم، بحضرة أخيها، أو أبيها، أو أبي زوجها، أو أمه، أو بعض أخواته. فالمقصود: لا تخلو به، لأن الرسول ﷺ نهى عن الخلوة، يقول ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما فإذا كلمته من غير خلوة، أو سلمت عليه، أو جلست في مجلس هو فيه للتحدث بالحديث الجائز؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10682/حكم-جلوس-المطلقة-عند-مطلقها-من-اجل-اولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40503.mp3","categories":["الطلاق"]},{"id":12561,"question":"ما حكم الشرع في بعض العوام من الناس عندما يقول: تكون العصمة في يد الزوجة، أي بمعنى: هي التي بيدها الطلاق، وليس الزوج، هل هذا جائز؟","title":"حكم الإسلام في جعل الطلاق بيد المرأة","answer":"الجواب:  الصواب في هذا أن هذا شرط غير صحيح؛ لأنه خلاف ما شرع الله، وقد صح عن رسول الله ﷺ أنه قال : كل شرط ليس في كتاب الله؛ فهو باطل، وإن كان مائة شرط فالشروط التي تخالف شرع الله ليست صحيحة، وكونه يشير لها أن الطلاق بيدها هذا بخلاف ما شرع الله، الطلاق بيد الزوج، وهذا يسبب فسادًا كثيرًا؛ لأنها قل أن تصبر على الزوج، بل عند أقل شيء؛ فيصدر منها الطلاق. فالحاصل: أن هذا لا يصح، وهذا الشرط باطل. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10770/حكم-الاسلام-في-جعل-الطلاق-بيد-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41105.mp3","categories":["الطلاق"]},{"id":12604,"question":"ما حكم طلب المرأة الطلاق من زوجها سماحة الشيخ؟","title":"طلب المرأة الطلاق من الزوج","answer":"الجواب:  .......... تعالى عنه أن زوجته أتت النبي ﷺ وقالت: يا رسول الله! ثابت لا أعيب عليه في خلق، ولا دين، ولكني أكره الكفر في الإسلام، ويروى عنها أنها قالت: إني لا أطيقه بغضًا، فقال: أتردين عليه حديقته؟ قالت: نعم، فقال ﷺ لثابت: اقبل الحديقة وطلقها تطليقة.  وظاهر هذا الوجوب؛ لأن هذا هو الأصل في الأوامر، ولأن في هذا دفعًا للضرر، وإحسانًا للجميع، والله يقول سبحانه: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130] فلا يجوز له أن يمسكها ضرارًا، أما إذا تيسر الصلح والتقارب، ورجوعها إليه، فهذا مطلوب، لكن إذا بذلت الأسباب، ولم يتيسر الوئام، فالواجب عليه أن يفارقها، سواء كان ذلك عن قبول مهره، أو السماح عنه، نعم. المقدم: جزاكم الله خيرًا، ومن حيث المعاصي سماحة الشيخ؟ الجواب: لا يلزمه طلاقها من أجل المعاصي، ولو كانت عاصية لا يلزمه الطلاق، ولا يلزمها هي أن تعافه لأجل المعاصي، ما دام ليس بكافر، لكن لها عذر إذا طلبت الفراق، إذا طلبت من الحاكم الفراق؛ لكونه سكيرًا، أو لكونه يضر بها كثيرًا بالضرب ونحوه، أو لأسباب أخرى تضرها؛ فلا بأس أن تطلب الطلاق، وللحاكم أن يلزمه بذلك إذا رأى المصلحة في ذلك. نعم. المقدم: نعم، نعم جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10836/طلب-المراة-الطلاق-من-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41424.mp3","categories":["الطلاق"]},{"id":12619,"question":"ما حكم طلب المرأة الطلاق من زوجها سماحة الشيخ؟","title":"طلب المرأة الطلاق من الزوج","answer":"الجواب:  .......... تعالى عنه أن زوجته أتت النبي ﷺ وقالت: يا رسول الله! ثابت لا أعيب عليه في خلق، ولا دين، ولكني أكره الكفر في الإسلام، ويروى عنها أنها قالت: إني لا أطيقه بغضًا، فقال: أتردين عليه حديقته؟ قالت: نعم، فقال ﷺ لثابت: اقبل الحديقة وطلقها تطليقة.  وظاهر هذا الوجوب؛ لأن هذا هو الأصل في الأوامر، ولأن في هذا دفعًا للضرر، وإحسانًا للجميع، والله يقول سبحانه: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130] فلا يجوز له أن يمسكها ضرارًا، أما إذا تيسر الصلح والتقارب، ورجوعها إليه، فهذا مطلوب، لكن إذا بذلت الأسباب، ولم يتيسر الوئام، فالواجب عليه أن يفارقها، سواء كان ذلك عن قبول مهره، أو السماح عنه، نعم. المقدم: جزاكم الله خيرًا، ومن حيث المعاصي سماحة الشيخ؟ الجواب: لا يلزمه طلاقها من أجل المعاصي، ولو كانت عاصية لا يلزمه الطلاق، ولا يلزمها هي أن تعافه لأجل المعاصي، ما دام ليس بكافر، لكن لها عذر إذا طلبت الفراق، إذا طلبت من الحاكم الفراق؛ لكونه سكيرًا، أو لكونه يضر بها كثيرًا بالضرب ونحوه، أو لأسباب أخرى تضرها؛ فلا بأس أن تطلب الطلاق، وللحاكم أن يلزمه بذلك إذا رأى المصلحة في ذلك. نعم. المقدم: نعم، نعم جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10836/طلب-المراة-الطلاق-من-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41424.mp3","categories":["الطلاق"]},{"id":12627,"question":"من جمهورية مصر العربية رسالة وصلت إلى البرنامج من إحدى المستمعات من هناك تقول أم عبدالله: أم عبدالله في سؤال طويل لها تقول: هل يجوز لزوجي أن يمنعني من زيارة أهلي -أبي وأمي وإخواني- وأن يقول لي: أنت مخيرة في البقاء معي، أو تزوري بيت أهلك إذا خرجت لزيارة أهلك لا تدخلي بيتي مرة ثانية، علمًا بأن أهلي غير ملتزمين، ولما علم زوجي بأنني حزنت بسبب هذا الكلام قال لي: إذًا في كل شهر مرة، سافر زوجي بعد ذلك، وغاب لمدة أربعة أشهر، ومنعني من الذهاب إلى أهلي وامتثلت، سؤالي هو: هل يحق لزوجي أن يمنعني من زيارة أهلي لكونهم غير ملتزمين، وهل أكون آثمة والحالة هذه؟ وجهونا جزاكم الله خيرًا.","title":"حكم منع الرجل زوجته من زيارة أهلها غير الملتزمين","answer":"الجواب:  نعم، له أن يمنعك من زيارة أهلك إذا كانت الزيارة تضرك وتضره؛ لأنهم غير ملتزمين، أما إذا كانت الزيارة لا تضرك، ولا تضره، كأن تزوريهم لصلة الرحم والبر وتنصحيهم وتوجهيهم إلى الخير؛ هذا أمر طيب، وينبغي ألا يمنعك، أما إن كانت الزيارة تضرك وتضره، وتسبب مشاكل بينكم، بينكما وبين الأهل؛ فله أن يمنعك من ذلك؛ لما في هذا من المضرة عليه وعليك. وإذا طلق ألا تزوريهم؛ لا تذهبي إليهم، وإن ذهبت إليهم؛ وقع الطلاق إن كان أراد وقوعه، أما إن كان أراد منعك، لا وقوع الطلاق، ولكن أراد أن يمنعك، وأراد تخويفك، وتهديدك، ولم يرد إيقاع الطلاق؛ فإن هذا له حكم اليمين، وعليه كفارتها. وبكل حال، فالواجب عليك السمع والطاعة فيما يقول لك إذا كان معروفًا، وليس فيه ما يخالف شرع الله، أما إذا كان شيئًا يخالف شرع الله، إذا كان منعه لك لا سبب له، ولا وجه له شرعي، فهذا يرجع إلى المحكمة إن لم تصلحي أنت وإياه، فالمرجع في هذا إلى المحكمة، والمحكمة تنظر في الأمر، وفي حل المشكلة، إلا إذا صلحتما فالصلح بينكما جائز وماضي، لكن بشرط ألا يكون ذلك في معصية الله، لابد أن يكون الصلح على وجه شرعي، ليس فيه معصية لله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10843/حكم-منع-الرجل-زوجته-من-زيارة-اهلها-غير-الملتزمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41507.mp3","categories":["الطلاق","الحقوق الزوجية","الأيمان والنذور"]},{"id":12824,"question":"المستمع (ع. ع) من جمهورية مصر العربية، ويعمل حين بعث الرسالة في المملكة يقول: لو قال الشخص لزوجته عندما يغضب منها: اذهبي إلى أهلك، أو عندما نرجع إلى بلادنا، كل واحد في طريقه، أو أنت على أهلك، وأنا على أهلي، فهل هذا يعتبر طلاقًا؟ وإذا تكرر أكثر من مرة مثلًا لو كان ثلاث مرات فهل تعتبر زوجته طالقًا وبائنًا، مع العلم لو أنه يريد الطلاق؛ لكان قال: علي الطلاق، أو أنت طالق، وكذلك لو كان يجهل تلك الألفاظ التي هي: اذهبي لأهلك، أو لا أريدك، أو ما شابه ذلك؟","title":"حكم من قال لزوجته: اذهبي إلى أهلك ...","answer":"الجواب:  ما دام لم يقصد الطلاق لا شيء عليه، لابد أن يكون له نية؛ لقول النبي ﷺ: إنما الأعمال بالنيات فإذا كان حين قال هذا الكلام: اذهبي إلى أهلك، أو كل يروح في طريقه، أو ما أشبه ذلك، ما أراد الطلاق، لا يقع طلاقًا، الأعمال بالنيات. أما إذا كان أراد الطلاق؛ فإنه يقع به طلقة بقوله: اذهبي إلى أهلك، أو كل واحد منا في طريق إذا وصلنا إلى البلد قصده الطلقة؛ الطلاق يكون طلقة واحدة، أو أنت ما أنت في ذمتي، أو لا حق لي عليك، أو ما أشبه ذلك، وقصده الطلاق؛ يكون طلقة واحدة.  أما إذا كان ما أراد الطلاق، إنما أراد شيئًا آخر؛ فهو على نيته؛ لقوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى وإن قال: إني أريد طلاقك، أو إذا جئت البلد طلقتك، هذا ما يصير طلاقًا، هذا وعد، أو وعيد، فإذا جاء البلد هو بالخيار متى شاء أن يطلق طلق، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11038/حكم-من-قال-لزوجته-اذهبي-الى-اهلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46312.mp3","categories":["الطلاق"]},{"id":12869,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: الراسل يحيى الحكيم من جمهورية السودان، الأخ: يحيى له سؤال طويل بعض الشيء، يقول فيه: لقد حدث أن طلقت زوجتي طلقة واحدة، وكنت غاضبًا لعدم احترامها لي، ولسبها والدي، وقلت لها باللفظ: أنت طالق، وهذه أول مرة في حياتنا الزوجية التي لها حتى الآن خمسة عشر شهرًا، ولكنها اتضح بعد مراجعتها أنها كانت حائضَا، وكنت لم أعاشرها لمدة أيام بسبب وجودها مع والدها المريض، ولقد سمعت يا سماحة الشيخ عن علماء مثل ابن تيمية، وابن القيم وهم يرون أن مثل هذا الطلاق لا يقع؛ لأنه لم يكن على كتاب الله، والسنة النبوية المطهرة، ولقد سألت بعض العلماء المسلمين في السودان؛ فأجازوا وقوع الطلاق، ولكن الآن -يا سماحة الشيخ- أستعين بالله، ثم بكم لمعرفة رأيكم فيما فعلت بعد استعانتي بالله العزيز، جزاكم الله خيرًا، وجهوني وانصحوني كيف أتصرف؟ وفقكم الله، وتقبل منكم.","title":"حكم طلاق الحائض","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  هذه المسألة تراجع فيها أيها السائل المفتي لديكم، وفيما يراه الكفاية -إن شاء الله- وفق الله الجميع، نعم.  المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/11084/حكم-طلاق-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46601.mp3","categories":["الطلاق"]},{"id":12872,"question":"المستمع: محمد عبدالفتاح بعث برسالة يقول فيها: أنا متزوج منذ عشر سنوات، وعندي ثلاثة أولاد، قلت لزوجتي عندما سافرت: لا تذهبي لزيارة أهلك، وإذا ذهبت أنت محرمة، وقلتها ثلاث مرات، لم أعرف معناها جيدًا في ذلك الوقت، المهم في الأمر أنها ذهبت رغم ما قلت لها، أرجو إفادتي يا سماحة الشيخ عن الحكم، جزاكم الله خيرًا.","title":"حكم تحريم الزوجة","answer":"الجواب:  هذا يختلف بحسب النية، إن كنت أردت تحريمها إذا خرجت، أو طلاقها إذا خرجت؛ فإنها تحرم إذا خرجت، وعليك كفارة الظهار، عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع من التمر، أو الأرز، أو غيرهما من قوت البلد. فأما إن كنت أردت الطلاق يقع طلقة واحدة، إذا أردت إيقاع الطلاق بخروجها، بهذا المعنى بقولك: محرمة إن أردت الطلاق فالأعمال بالنيات، يقع طلقة وتراجعها، تقول: قد راجعت زوجتي، وتشهد اثنين الأفضل من إخوانك الطيبين أنك راجعتها، إذا كنت ما طلقتها قبل ذلك طلقتين. فأما إن كنت ما أردت الطلاق، ولا التحريم، إنما أردت منعها، حين قلت: إن ذهبت أردت المنع فقط، ولم تقصد لا تحريمًا، ولا طلاقًا، إنما أردت منعها وتهديدها، فعليك كفارة يمين، ولا يقع شيء بخروجها على الصحيح من كلام أهل العلم؛ لأن هذا التعليق بهذه النية في حكم اليمين، إذا كان بنية المنع، أو التهديد، لا بنية الطلاق، ولا بنية التحريم، فهذا يكون في حكم اليمين بهذه النية، والرسول  قال: الأعمال بالنيات وأنت أعلم بنيتك، نسأل الله لنا ولك التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11087/حكم-تحريم-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46604.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":12906,"question":"رسالة وصلت إلى البرنامج من المدينة المنورة، وباعثها أحد المستمعين من هناك، يقول أبو أنور، أبو أنور له أكثر من سؤال في أحد أسئلته، يقول: حدث خلاف بين رجل مع أهل زوجته، وحلف، وأقسم، وقال: ستكون زوجتي طالقًا بالثلاث إذا ذهبت إلى زيارة أهلها، سواء كان والداها، أو إخواتها، أو أقاربها، ولكن لم يحدث خلاف بينه وبين زوجته بعد هذا القسم والحلف، ماذا يفعل الرجل إذا أراد أن يبرئ ذمته، ويجعل زوجته تذهب إلى أهلها، علمًا بأن ابنه سيتزوج من بيت أهل زوجته؟","title":"ما يلزم من قال: ستكون زوجتي طالقًا بالثلاث إذا ذهبت لزيارة أهلها؟","answer":"الجواب:  يتصل بالمحكمة، ويسأل المحكمة، وهي تفيده عما وقع منه، أو يكتب لنا، ونحن ننظر في الموضوع، ونفيده -إن شاء الله- بواسطة المحكمة، نعم. المقدم: يكتب مرة أخرى .. الشيخ: كتابة، نعم، يذكر عنوانه، ذكر عنوانه؟ المقدم: من المدينة المنورة فقط. الشيخ: لا، يذكر عنوانه الخاص، عنوان خاص، لو أنه ذكر العنوان وبعد هذا نجيبه -إن شاء الله- أو يتصل بالمحكمة، وفيها الكفاية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11121/ما-يلزم-من-قال-ستكون-زوجتي-طالقا بالثلاث-اذا-ذهبت-لزيارة-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46808.mp3","categories":["الطلاق"]},{"id":12952,"question":"هذا السائل (ع. م) سوري ومقيم في الأردن يقول: لقد حرَّمتُ زوجتي عليَّ لمدة سنة، وبعد شهر من الزمن رددتُها، فما الحكم في ذلك يا سماحة الشيخ، مأجورين؟","title":"حكم من حرم زوجته على نفسه سنة ثم ردها","answer":"الجواب:  إذا كنت جامعتها؛ عليك كفارة الظهار، وإن كنت رديتها في البيت، ولكن ما جامعتها؛ ما عليك شيء حتى تتم السنة، فإن جامعتها قبل السنة؛ فعليك كفارة الظهار المذكورة في سورة المجادلة، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، فإن لم تستطع؛ تطعم ستين مسكينًا، ثلاثين صاعًا قبل أن تقربها، ثلاثين صاعًا، لكل مسكين نصف صاع، يعني: كيلو ونصف كل واحد، تسعين كيلو، كل واحد له كيلو ونصف قبل أن تقربها عند العجز عن العتق والعجز عن الصوم، هذه كفارة الظهار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11169/حكم-من-حرم-زوجته-على-نفسه-سنة-ثم-ردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50211.mp3","categories":["الطلاق","الظهار"]},{"id":13039,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية الشقيقة، باعث الرسالة مستمع من هناك يقول: (م. أ. م)، صاحب هذه الرسالة عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة بقي له سؤالان.سؤاله الأول يقول: رجل قال لزوجته: أنت طالق لمدة سنة، ما حكم ذلك، وهو يريد مراجعة زوجته، فماذا يعمل؟","title":"حكم الطلاق المؤقت","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالمعروف عند أهل العلم أن الطلاق لا يوقت متى وقع وقع، بخلاف التحريم فإنه يوقت، أما المرأة فلا يكون طلاقها مؤقتًا، متى طلقت؛ صار طلاقها غير موقت، فإن كان رجعيًا؛ فله رجعتها، وإن كان بائنًا؛ بانت بذلك، ولكن لخطورة المقام، ووجوب الحيطة؛ نؤجل البت في ذلك إلى حلقة أخرى؛ لأن المقام جدير بالعناية، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا، إذًا في لقاء قادم نعرض هذا الموضوع، إن شاء الله. الشيخ: نعم نعم في الحلقة الأخرى، إن شاء الله. المقدم: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/11256/حكم-الطلاق-الموقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47301.mp3","categories":["الطلاق"]},{"id":13193,"question":"المستمع (ع. س. ق) بعث بقضية يقول فيها: لقد تقدم رجل لخطبة فتاة، فوافق أهلها، والمخطوبة أيضًا، وتم عقد النكاح بالمحكمة، وسيكون الزواج بعد فترة من الوقت، وسرعان ما جرى مشاكل من قبل الزوج، فطلقها دون أن يصل إليها، وقد علمنا بأنه ليس لها عدة ما دام لم يصل إليها، غير أنه قد كان دفع مبلغًا من المال، والمبلغ قد أخذ منه ذهبًا ومصاريف، وغير ذلك، هل يرد له المبلغ كله، أم لا، أو يرد نصف المبلغ، وجهونا حول هذا الموضوع جزاكم الله خيرًا؟","title":"حكم طلاق المرأة المعقود عليها قبل الدخول","answer":"الجواب: إذا كان المذكور لم يدخل بها، ولم يخلو بها خلوة كاملة، بحيث أغلق عليهم الباب، فإنه يرد عليه نصف المهر، لقول الله -جل وعلا-: وَإِنْ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّا أَنْ يَعْفُونَ أَوْ يَعْفُوَ الَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ  [البقرة:237] من عفا منهم فلا بأس، إن عفت؛ سقط حقها.  وإن عفا هو؛ سقط حقه، وإلا فعليها أن ترد النصف مما وصل إليها منه من ذهب وغيره، وليس عليها عدة، لقول الله : يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا [الأحزاب:49] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11448/حكم-طلاق-المراة-المعقود-عليها-قبل-الدخول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47602.mp3","categories":["الطلاق"]},{"id":13315,"question":"هذه السائلة الحقيقة أرسلت برسالة طويلة وكتبت بأسلوبها الخاص تقول: سماحة الشيخ! أفيدكم بأنني تزوجت منذ عامين من شاب وهو وحيد والديه وقد نال من التدليل ما كان كافيًا لإفساد حياته، ولكنه بعد زواجي منه بدأت تتحسن أخلاقه، وبدأ يتطلع إلى معرفة أمور دينه حيث إنه كان يجهل عنها الكثير والكثير والله الهادي إلى سواء السبيل، ومنذ عام مضى قام بطلاقي في وقت غضب وكانت المرة الأولى، ومنذ عدة أسابيع احتد بيننا الحديث فقال لي: أنت محرمة علي، وكان يقصد من ذلك كما فهمت منه فيما بعد هو امتناعه عن معاشرتي كزوج، ولكنني سأبقى على ذمته، فسكت عن ذلك، وأنا أشك في قرارة نفسي بأنها الطلقة الثانية، ومنذ أيام حضرتني الدورة الشهرية وكنت تعبانة وعصبية وكان ذلك سببًا لامتداد الحديث بيننا مرة أخرى وقال لي: أنت طالق وكانت صدمة لي؛ لأنني بذلك اعتبرتها الثالثة، ولكن كان تبريره بذلك بأنه كان يريد عقابي فقط ولا يقصد من ذلك المعنى الحقيقي للطلاق، وأخبرته بأن الجد والهزل في هذه الأمور لا جدال فيه، وامتنعت عن معاشرته، فما رأيكم سماحة الشيخ؟ جزاكم الله خيرًا.","title":"حكم قول الرجل لزوجته: أنت محرمة علي","answer":"الجواب: هذا موضوع يحتاج إلى حضورك، وزوجك ووليك عند بعض المشايخ لإثبات ما جرى، وبعد هذا أنظر في الموضوع -إن شاء الله- عند المحكمة في بلدكم، أو عند بعض المشايخ المعروفين يكتبون كلامك، وكلام الزوج، وكلام الولي إن كان عنده شيء مما جرى بينكما حتى ننظر في الأمر -إن شاء الله- لأن هذا موضوع مهم، يحتاج إلى عناية وتحقيق، وبعد هذا ننظر في الأمر -إن شاء الله- نعم.","link":"https://binbaz.org.sa/fatwas/11601/حكم-قول-الرجل-لزوجته-انت-محرمة-علي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52103.mp3","categories":["الطلاق"]},{"id":13336,"question":"رسالة مطولة بعض الشيء وصلت إلى البرنامج من مكة المكرمة، وباعثها رمز إلى اسمه بالحروف (ح. ح. م) يقول في رسالته: أنا متزوج منذ خمسة أعوام، ومشكلتي أنني لم أكن أصلي، وكانت حياتي ضلال في ضلال، وخلال هذه السنوات حصل بيني وبين زوجتي خلافات كثيرة، وفي يوم أتى الخلاف إلى أن كتبت لها ورقة، وفيها: أني طلقتها ثلاث طلقات، وأنا في كامل قواي العقلية، واستشهدت بشاهدين، وقبل انتهاء العدة راجعتها، وبعد ذلك حصل بيننا خلافات عدة، وكانت كلمة الطلاق في فمي دائمًا، وكانت أغلبها عندما أكون عصبيًا، ثم أهدأ، وأراجعها، ولكن الآن والحمد لله فقد هداني الله، والتزمت بديني، وندمت، وتبت إلى الله، وتركت أيام الضلالة، لكن يا سماحة الشيخ! الذي يحيرني هو قضية الطلاق الذي ذكرت، أرجو أن تبينوا لي الأمر، ولا سيما أنني كتبتها في الورقة، والطلاق المتكرر عندما كنت عصبيًا، جزاكم الله خيرًا.","title":"حكم كتابة الطلاق وحكم طلاق الغضبان","answer":"الجواب: نرى أن تتصل بالمحكمة، وتسألها، وفيما تراه المحكمة الكفاية -إن شاء الله- وإذا كنت في المملكة لا مانع أن تتصل بي شخصيًا حتى أنظر في الأمر إن شاء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11622/حكم-كتابة-الطلاق-وحكم-طلاق-الغضبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47611.mp3","categories":["الطلاق"]},{"id":13530,"question":"رسالة وصلت إلينا من أحد الإخوة المستمعين، رمز في نهاية الرسالة بقوله السائل من مكة المكرمة، يقول في أحد أسئلته: إذا قال الرجل لزوجته: أنت طالق إذا دخلت بيت فلان بغير إذني، وقد كان في نية الزوج ساعة التلفظ أنها إذا دخلت ذلك البيت لغرض في نفسه يقع الطلاق، أما إذا دخلت لحاجة أخرى كزيارة مريض، وغيرها؛ فلا يقصد الطلاق.أولًا: هل يقع الطلاق إذا دخلت المرأة ذلك البيت مطلقًا، أم يقع فقط عندما تدخل البيت للغرض الذي كان في نفس الزوج ساعة التلفظ.ثانيًا: إذا اطمأن الزوج من زوجته، ثم أراد أن يعطيها الإذن بالدخول متى أرادت؛ لأنه يشق عليها أن تستأذن منه دائمًا؛ نظرًا لظروف عمل الزوج، فما الحكم؟ جزاكم الله خيرًا.","title":"حكم تعليق الطلاق على النية","answer":"الجواب: العمل على النية إذا قال: إذا دخلت بيت فلان؛ فأنت طالق، وقصده إذا دخلت لغرض معين، إما لزيارتهم المطلقة، أو لطلب شيء منهم للاستعارة، أو ما أشبه ذلك؛ فهو على نيته، وإذا كان قصده أنه إذا زارتهم لأجل المريض، عيادة المريض أنه لا يقع فهو على نيته. المقصود: أنه على نيته؛ لقوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى وإذا نوى زجرها، أو منعها، ولم يقصد الطلاق؛ فعليه كفارة يمين، ولا يقع الطلاق. أما إن رأى قصد إيقاع الطلاق، لكن بشرط أن تكون الزيارة لمجرد الأنس، أو مجرد الشحاذة، تشحذهم شيئًا، أو ما أشبه، هذا مما ينويه فله نيته، وإذا دخلت على وجه لم ينوه؛ لم يقع الطلاق، الأعمال بالنيات. وإذا كان نوى إلا بإذنه، ثم أذن لها؛ لم تحتج إلى استئذان بعد ذلك، إذا نوى أنها إذا خرجت بإذنه؛ فلا شيء، فإنه متى أذن لها انتهت اليمين، وانتهى التعليق، ولا حرج عليها بعد ذلك، إذا قال: متى شئت فاذهبي لهم؛ لا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11846/حكم-تعليق-الطلاق-على-النية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47907.mp3","categories":["الطلاق"]},{"id":13622,"question":"المستمع مهدي علي أحمد يسأل ويقول: ما الفرق بين البينونة الكبرى، والبينونة الصغرى؟","title":"الفرق بين البينونة الكبرى والصغرى","answer":"الجواب: البينونة الكبرى تحرم الزوجة حتى تنكح زوجًا على مطلقها، يقال لها: بينونة كبرى، تحرم على الزوج حتى يتزوجها زوج آخر، ويدخل بها، يعني: يطأها، ثم يفارقها بموت، أو طلاق، ثم تخرج من العدة، وذلك إذا طلقها الطلقة الأخيرة الثالثة، فإنها تحرم عليه حتى تنكح زوجًا غيره؛ لقوله -جل وعلا- في كتابه العظيم: فَإِنْ طَلَّقَهَا [البقرة:230] يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:23] يعني: حتى يتزوجها، وحتى يطأها كما دل عليه الحديث الصحيح من حديث عائشة -رضي الله عنها- في قصة المبتوتة أن النبي ﷺ قال لها: \"بأنها لا تحل لزوجها الأول حتى تذوق عسيلة الثاني، ويذوق عسيلتها\" حتى يطأها. هذه يقال لها: بينونة كبرى، إذا طلقها الطلقة الأخيرة يقال لها: بينونة كبرى، لا تحل إلا بعد زوج شرعي، لا نكاح تحليل، بل زوج شرعي، وبعد أن يطأها، ثم يفارقها بموت أو طلاق. أما البينونة الصغرى: فهي التي تقع بعد طلقة، أو طلقتين إذا خرجت من العدة، إذا خرجت بعد الطلقة الواحدة، أو الطلقتين من العدة تسمى بينونة صغرى، يعني: يحلها العقد إذا تزوجها بعقد حلت، وهكذا إذا خالعها بمال طلقها على مال طلقة واحدة، أو طلقتين، فإنها تحل له بعقد جديد، وهذه البينونة يقال لها: بينونة صغرى؛ لأنه يحلها العقد الجديد، أما البينونة الكبرى فلا يحلها العقد، لابد من زوج جديد يطؤها، ثم تحل له بعقد جديد بعد ذلك إذا طلقها الزوج، أو مات عنها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11956/الفرق-بين-البينونة-الكبرى-والصغرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48014.mp3","categories":["الطلاق"]},{"id":13802,"question":"من المدينة النبوية هذه رسالة بعث بها المستمع (ع. ر. ص) أخونا يقول: أول ما تزوجت كنت جاهلًا تمامًا بأن الطلاق إنما يقع بكلمة، وكنت عندما أختلف مع زوجتي أحلف عليها بالطلاق، وعندما علمت أن الطلاق يقع بالكلمة توقفت تمامًا عن ذلك والحمد لله، رزقت بالأولاد وأصبحت من طلاب العلم -أي: علم الدين- وعندما أتذكر ما مضى من حلفان أحزن حزنًا شديدًا مع أنني وزوجتي وأولادي بخير والحمد لله رب العالمين، وتراودني الشكوك وأخاف من الله  وأخاف أن يكون اجتماعي مع زوجتي على طريقة غير صحيحة، أرجو توجيهي جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق جاهلاً بوقوعه","answer":"الجواب: عليك أن تراجع المحكمة في بلدك وأن تشرح لها الواقع وهي تفتيك إن شاء الله بما يلزم، أو تكتب إلينا كتابًا تشرح فيه الواقع ونحن نحيلك إلى ..... القاضي لتحضر مع المرأة ووليها وتشرح للقاضي ما وقع، وبعد ذلك تكون الفتوى إن شاء الله، وفيما يراه القاضي الخير والبركة إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12172/حكم-من-حلف-بالطلاق-جاهلا-بوقوعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60202.mp3","categories":["الطلاق"]},{"id":13809,"question":"من المدينة النبوية هذه رسالة بعث بها المستمع (ع. ر. ص) أخونا يقول: أول ما تزوجت كنت جاهلًا تمامًا بأن الطلاق إنما يقع بكلمة، وكنت عندما أختلف مع زوجتي أحلف عليها بالطلاق، وعندما علمت أن الطلاق يقع بالكلمة توقفت تمامًا عن ذلك والحمد لله، رزقت بالأولاد وأصبحت من طلاب العلم -أي: علم الدين- وعندما أتذكر ما مضى من حلفان أحزن حزنًا شديدًا مع أنني وزوجتي وأولادي بخير والحمد لله رب العالمين، وتراودني الشكوك وأخاف من الله  وأخاف أن يكون اجتماعي مع زوجتي على طريقة غير صحيحة، أرجو توجيهي جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق جاهلاً بوقوعه","answer":"الجواب: عليك أن تراجع المحكمة في بلدك وأن تشرح لها الواقع وهي تفتيك إن شاء الله بما يلزم، أو تكتب إلينا كتابًا تشرح فيه الواقع ونحن نحيلك إلى ..... القاضي لتحضر مع المرأة ووليها وتشرح للقاضي ما وقع، وبعد ذلك تكون الفتوى إن شاء الله، وفيما يراه القاضي الخير والبركة إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12172/حكم-من-حلف-بالطلاق-جاهلا-بوقوعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60202.mp3","categories":["الطلاق"]},{"id":13838,"question":"يقول السائل أيضًا من ضمن أسئلته سماحة الشيخ: رجل طلق زوجته وبعد مرضها أخذ منها كل ما دفعه لها من مهر وملابس وغير ذلك، هل يجوز لها أن ترفع قضية ضده أم لا؟وهل له الحق في هذا العمل وهو سحب صيغ الذهب والملابس من هذه المرأة وهي مريضة؟","title":"حكم أخذ الرجل مهر المرأة وملابسها بعد طلاقها","answer":"الجواب: هذه مسألة خصومة، عليها أن تراجع المحكمة إلا أن يتيسر يصلح بينهما في هذا الموضوع من أهل الخير وإلا فالمرجع المحكمة بهذا حتى تنظر في أمره وأمرها. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12206/حكم-اخذ-الرجل-مهر-المراة-وملابسها-بعد-طلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53010.mp3","categories":["الطلاق"]},{"id":13860,"question":"يسأل أخونا من الزلفي فيقول: هل يجوز التذميم بقوله لأخيه: بذمتك أو بصلاتك أو بقوله: بحرج إن فعلت كذا، فمثل هذه العادات منتشرة عند النساء والأطفال، نرجو التوجيه جزاكم الله خيرًا.","title":"حكم الحلف بالذمة وغيرها","answer":"الجواب: لا يجوز الحلف لا بالصلاة ولا بالذمة ولا بالحرج ولا بغير ذلك من المخلوقات، الحلف يكون بالله وحده، فلا يقول: بذمتي ما فعلت كذا، ولا بذمة فلان، ولا بحياتي ولا بصلاتي، ولا أن يطالب يقال قل: بذمتي ولا قل: بصلاتي، ولا قل: بزكاتي، كل هذا لا أصل له ولا يجوز؛ لأن الصلاة فعل العباد، والزكاة فعل العباد، وأفعال العباد لا يحلف بها وإنما الحلف بالله وحده ، يقول النبي عليه الصلاة والسلام: من كان حالفًا فليحلف بالله أو ليصمت، ويقول عليه الصلاة والسلام: من حلف بشيء دون الله فقد أشرك خرجه الإمام أحمد بإسناد صحيح عن عمر ، وخرج أبو داود والترمذي بإسناد صحيح عن ابن عمر رضي الله تعالى عنهما عن النبي عليه الصلاة والسلام أنه قال: من حلف بغير الله فقد كفر أو أشرك وقال عليه الصلاة والسلام: من حلف بالأمانة فليس منا.\nفالواجب على كل مؤمن ومؤمنة أن يحذر ذلك وأن لا يحلف إلا بالله وحده  يقول: بالله ما فعلت كذا، والله ما فعلت كذا، إذا دعت الحاجة، والمشروع أن يحفظ يمينه ولا يحلف إلا عند الحاجة قال تعالى: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] لكن إذا دعت الحاجة يحلف يقول: والله ما فعلت كذا إذا كان صادقًا، والله ما ذهبت إلى فلان، بالله ما فعلت كذا، تالله ما فعلت كذا، إذا كان صادق هذا يمين بالله ، أما الحلف بغير ذلك بالأمانة أو بالنبي أو بالكعبة أو بحياة فلان أو شرف فلان أو صلاتي أو ذمتي فلا يجوز.\nأما إذا قال: في ذمتي ليس بيمين، هذا ليس بيمين في ذمتي يعني: هذا الشيء في ذمتي أمانة، أو ما أخون فيه أو ما أشبه ذلك هذا ليس يمينًا، أما إذا قال بذمتي أو بصلاتي أو بزكاتي أو حياتي أو حياة والدي هذا ما يجوز، هذا من الحلف بغير الله ، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12236/حكم-الحلف-بالذمة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60307.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":13934,"question":"يقول: حلفت يمين أن أترك الدخان، وتركته فترة معينة إلا أنني رجعت ما حكم ما فعلت؟ وماذا أفعل إذا كان علي كفارة؟ جزاكم الله خيرًا.","title":"حكم من حلف على ترك الدخان ثم عاد إليه","answer":"الجواب: عليك التوبة إلى الله؛ لأن الدخان محرم خبيث ومضاره كثيرة، فعليك التوبة إلى الله جل وعلا وأن تحذر مجالسة المدخنين، فإن مجالستهم من أسباب رجوعك إليه. وعليك كفارة اليمين عن يمينك وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن كنت فقير لا تستطيع عاجز عن الطعام والكسوة والعتق فإنك تصوم ثلاثة أيام هذه كفارة اليمين، قال الله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية في سورة المائدة، فالرب جل وعلا يأمرنا بالكفارة من أوسط الطعام أو كسوة أو عتق رقبة، فإن عجز الحالف صام ثلاثة أيام، وأمر بحفظ الأيمان، وأنه لا ينبغي للإنسان أن يحلف إلا عند الحاجة. والدخان شره كثير، فينبغي لك يا عبد الله! أيها السائل! أن تحذره وأن تستمر في تركه، وألا تجالس أهله، وأن تنصحهم لعل الله يهديك ويهدي بك، بارك الله فيك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12333/حكم-من-حلف-على-ترك-الدخان-ثم-عاد-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48209.mp3","categories":["الطلاق","الأيمان والنذور","نصائح وتوجيهات"]},{"id":14003,"question":"المستمع صالح شيبان عزيز العمري، -فيما يبدو- من الباحة بعث يسأل ويقول: سماحة الشيخ! لي زوجة تزوجتها منذ سنة وثلاثة أشهر، وقد أنجبت منها طفلا، وفي يومٍ حصل بيني وبينها سوء تفاهم، وقد أغضبتني في ذلك اليوم، ورميت عليها بثلاث طلقات متفرقات في مجلسٍ واحد، وقد حضر والدها، وبدلًا من أن نتفاهم حول الموضوع، قام بإغضابي مرةً أخرى، ورميت عليها بثلاث طلقات أخرى، في مجلسٍ واحد، وفي اليوم الثاني ذهبت إلى قاضٍ في محكمة للاستفتاء، فأمرني بالاستفتاء من سماحتكم، هل يجوز لي أن أسترجعها إلى عصمتي مرةً أخرى؟ وأقسم بالله العظيم أن هذا الذي حصل بالحرف الواحد، أرجو منكم أن تفيدوني، جزاكم الله خيرا؟","title":"حكم الطلاق بالثلاث في مجلس واحد وتكرار ذلك","answer":"الجواب: عليك أن تحضر مع وليها لدى القاضي حتى يكتب الواقع بإقراركم جميعًا، ويبين صفة الغضب، وشدة الغضب وأسبابه، ثم بعد ذلك ننظر في الأمر إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12418/حكم-الطلاق-بالثلاث-في-مجلس-واحد-وتكرار-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48307.mp3","categories":["الطلاق"]},{"id":14039,"question":"يسأل أخونا عن حكم الدين في الذي يكثر الحلف بالطلاق، وهل يجوز رد الطلاق؟","title":"حكم من يكثر الحلف بالطلاق، وهل يقع طلاقه؟","answer":"الجواب: لا ينبغي للمؤمن أن يكثر من ذلك، بل يكره له ذلك، ينبغي له حفظ لسانه، الطلاق أبغض الحلال إلى الله الطلاق، فينبغي للمؤمن أن يتثبت في الأمور، ويحرص على حفظ اللسان عن كل ما لا ينبغي، ومن ذلك الطلاق، فلا ينبغي له أن يطلق إلا عن بصيرة وعن نظر وعن عناية، فإذا ظهرت المصلحة والفائدة في الطلاق؛ طلق طلقة واحدة فقط، لا زيادة؛ لأنه قد يندم، فيراجع زوجته والحمد لله.\nالمقصود: أن الإكثار من الحلف بالطلاق خطر، وهو يفضي إلى وقوع الطلاق، فإنه قد يحلف بالطلاق ناويًا وقوع الطلاق؛ فيقع، إذا فعل ما حلف على تركه، أو ترك ما حلف على فعله، أما إذا كان إنما أراد التهديد والتخويف، كأن يقول: إن كلمت فلانًا؛ فأنت طالق، أو إن ذهبت إلى فلان؛ فأنت طالق من باب التخويف والتحذير، وليس قصده إيقاع الطلاق؛ فهذا عند المحققين من أهل العلم فيه كفارة يمين، ولا يقع به الطلاق.\nهذا هو الصواب الذي اختاره جمع من أهل العلم؛ لأنه لم يرد الطلاق، وإنما أراد التهديد والتخويف والتهديد.\nولكن بكل حال ينبغي له ترك ذلك، والحذر من اعتياد الطلاق، وأن يكون في لسانه؛ لأنه قد يوقعه بالقصد، ولأن بعض أهل العلم يراه يقع وإن كان قصد التهديد والتأكيد؛ فينبغي الحذر من ذلك، وينبغي تجنب ذلك احتياطًا لدينه واحتياطًا لما يجب عليه من حفظ الفرج، والبعد عن شبهة الحرام.\nوإذا طلق فيطلق عن بصيرة، لا بالغضب والعجلة، بل يتحرى وينظر، فإذا رأى المصلحة في الطلاق؛ لأنها سيئة الأخلاق.. سيئة السيرة.. ضعيفة الدين؛ إذا رأى المصلحة في ذلك طلق طلقة واحدة، في طهر لم يجامع فيه أو في حال الحمل، هذا السنة، أن يكون الطلاق في حالين: إحداهما: حال الحمل، والثانية: أن تكون المرأة في طهر لم يجامعها فيه، هذا هو محل الطلاق الشرعي.\nأما الطلاق في الحيض أو في النفاس أو في طهر جامع فيه، فهو طلاق بدعي، مخالف لقوله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1]، بين النبي ﷺ في حديث ابن عمر أن طلاقها في العدة أن تكون طاهرة، من دون جماع أو حاملا.\nفينبغي لأهل الإسلام، ينبغي لكل مسلم أن يتحرى هذه الأمور، وأن يحافظ على السنة، وأن يحذر طاعة الشيطان في طلاقه على وجه غير شرعي، وأن يحذر العجلة في إيقاع الطلاق الثلاث.\nبل يجب أن يراعي ما شرع الله، وأن يحذر ما حرم الله، في طلاقه وفي سائر شئونه، المؤمن عبد مأمور، له شريعة إسلامية يجب أن يلتزم بها في كل شيء، وأن يتحرى ما أحل الله له في كل شيء، وأن يحذر ما حرم الله عليه، وليس له التساهل في كل شيء، بل يجب الحذر، وأن تكون أعماله وأقواله مقيدة بالشريعة، رزق الله الجميع التوفيق والهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12467/حكم-من-يكثر-الحلف-بالطلاق-وهل-يقع-طلاقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60708.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14072,"question":"رسالة وصلت إلى البرنامج من العراق بعثها مستمع من هناك يقول: أنا أخوكم في الإسلام (ج. ع. ش) من جمهورية مصر العربية محافظة الفيوم، وحاليًا أعمل في الجمهورية العراقية، أنا متزوج ابنة عمي، وقبل سفري إلى العراق قلت لها: إذا خرجت خارج المنزل وأنا غائب وبدون إذني، وأقصد خروجها من المنزل، وهو سفرها إلى القاهرة، مهما بلغت الظروف، فخرجت إلى القاهرة؛ لأن والدتها كانت مريضة حسب قولها، ما رأيكم فيما قلت؟ جزاكم الله خيرًا.","title":"حكم من قال لزوجته إن خرجت بدون أذني فأنت طالق","answer":"الجواب: إذا كان قصدك منعها من الخروج، وليس قصدك الطلاق، إنما قصدك أن تمنعها وتهددها وتخوفها؛ فعليك كفارة يمين ويكفي، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فمن عجز عن ذلك صام ثلاثة أيام كما تقدم.\nأما إن كان قصدك طلاقها؛ فإنه يقع عليها طلقة واحدة بذلك وتراجعها، تشهد اثنين (شاهدين) أنك راجعت زوجتك فلانة، إذا كانت لم تطلق قبل هذا طلقتين، فالإنسان مأخوذ بكلامه، فإذا كان قصدك الطلاق؛ فالأعمال بالنيات، إذا قلت: إن خرجت إلى أمك، أو إن خرجت من بيتي؛ فأنت طالق، وقصدك إيقاع الطلاق؛ فإنه يقع طلقة واحدة، ولك أن تراجعها إذا شئت مادامت في العدة، بأن تقول: راجعت زوجتي فلانة، أو رددت زوجتي فلانة، وتشهد شاهدين من إخوانك الطيبين على أنك راجعتها، وترجع إلى حبالك، وإلى عصمتك بذلك، إذا كنت لم تطلقها قبل هذا طلقتين، أما إن كانت هذه الطلقة هي الأخيرة هي الثالثة؛ فإنها تحرم عليك إلا بعد زوج شرعي، يعني: نكاح شرعي، ليس نكاح تحليل، بل نكاح شرعي ويطؤها الزوج، بعد الطلقة الثالثة لا تحل إلا بعد زوج شرعي، لا بنكاح التحليل، ولكن بنكاح شرعي، ولا بد مع ..... أن يطأها الزوج؛ لأن الله سبحانه يقول: فَإِنْ طَلَّقَهَا [البقرة:230]، يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230]، والنبي ﷺ لما سألته التي طلقها زوجها الطلقة الأخيرة أن تعود إليه قال: لا، حتى تذوقي عسيلته، ويذوق عسيلتك، يعني: حتى يطأك بعد النكاح الزوج الثاني، لا بد من نكاح، ولا بد من وطء في النكاح، لمن طلق زوجته الطلقة الأخيرة الثالثة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12509/حكم-من-قال-لزوجته-ان-خرجت-بدون-اذني-فانت-طالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60905.mp3","categories":["الطلاق"]},{"id":14079,"question":"رسالة وصلت إلى البرنامج من العراق بعثها مستمع من هناك يقول: أنا أخوكم في الإسلام (ج. ع. ش) من جمهورية مصر العربية محافظة الفيوم، وحاليًا أعمل في الجمهورية العراقية، أنا متزوج ابنة عمي، وقبل سفري إلى العراق قلت لها: إذا خرجت خارج المنزل وأنا غائب وبدون إذني، وأقصد خروجها من المنزل، وهو سفرها إلى القاهرة، مهما بلغت الظروف، فخرجت إلى القاهرة؛ لأن والدتها كانت مريضة حسب قولها، ما رأيكم فيما قلت؟ جزاكم الله خيرًا.","title":"حكم من قال لزوجته إن خرجت بدون أذني فأنت طالق","answer":"الجواب: إذا كان قصدك منعها من الخروج، وليس قصدك الطلاق، إنما قصدك أن تمنعها وتهددها وتخوفها؛ فعليك كفارة يمين ويكفي، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فمن عجز عن ذلك صام ثلاثة أيام كما تقدم.\nأما إن كان قصدك طلاقها؛ فإنه يقع عليها طلقة واحدة بذلك وتراجعها، تشهد اثنين (شاهدين) أنك راجعت زوجتك فلانة، إذا كانت لم تطلق قبل هذا طلقتين، فالإنسان مأخوذ بكلامه، فإذا كان قصدك الطلاق؛ فالأعمال بالنيات، إذا قلت: إن خرجت إلى أمك، أو إن خرجت من بيتي؛ فأنت طالق، وقصدك إيقاع الطلاق؛ فإنه يقع طلقة واحدة، ولك أن تراجعها إذا شئت مادامت في العدة، بأن تقول: راجعت زوجتي فلانة، أو رددت زوجتي فلانة، وتشهد شاهدين من إخوانك الطيبين على أنك راجعتها، وترجع إلى حبالك، وإلى عصمتك بذلك، إذا كنت لم تطلقها قبل هذا طلقتين، أما إن كانت هذه الطلقة هي الأخيرة هي الثالثة؛ فإنها تحرم عليك إلا بعد زوج شرعي، يعني: نكاح شرعي، ليس نكاح تحليل، بل نكاح شرعي ويطؤها الزوج، بعد الطلقة الثالثة لا تحل إلا بعد زوج شرعي، لا بنكاح التحليل، ولكن بنكاح شرعي، ولا بد مع ..... أن يطأها الزوج؛ لأن الله سبحانه يقول: فَإِنْ طَلَّقَهَا [البقرة:230]، يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230]، والنبي ﷺ لما سألته التي طلقها زوجها الطلقة الأخيرة أن تعود إليه قال: لا، حتى تذوقي عسيلته، ويذوق عسيلتك، يعني: حتى يطأك بعد النكاح الزوج الثاني، لا بد من نكاح، ولا بد من وطء في النكاح، لمن طلق زوجته الطلقة الأخيرة الثالثة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12509/حكم-من-قال-لزوجته-ان-خرجت-بدون-اذني-فانت-طالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60905.mp3","categories":["الطلاق"]},{"id":14112,"question":"المستمع حمدي حسين عبده يسأل ويقول: يأمرنا الدين بطاعة الوالدين وبرهما، ولكن الوالد والوالدة يأمرونني بطلاق زوجتي وأن أتزوج من أخرى لعدم الإنجاب، عرضنا أنفسنا نحن الاثنين على أكثر من طبيب متخصص، ويقولون: إنه لا يوجد عندكم أي مانع للإنجاب ولكنها إرادة الله، وأنا مؤمن بذلك، وعليه فإنني لا أقدر على فك الارتباط بيني وبين زوجتي، فرجائي من سماحتكم أن تخبروني؛ هل يعد تطليقي لزوجتي أو عدم تطليقها هل له علاقة ببر الوالدين؟ جزاكم الله خيرًا.","title":"هل يُطاع الوالدان في تطليق الزوجة؟","answer":"الجواب: إذا كانت الزوجة مستقيمة في دينها ولم تؤذ والديك ولم تضرهما وإنما مجرد الإنجاب فلا يلزمك طاعتهما في ذلك، يعني في الطلاق، لقول النبي ﷺ: إنما الطاعة في المعروف، وليس من المعروف طلاقها من دون سبب، ولكن في إمكانك أن تتزوج امرأة أخرى لعل الله يكتب لك الإنجاب، فهي على محبتك لها تبقى، وفي الإمكان أن تفعل الأسباب وتجتهد في التماس زوجة أخرى ولاسيما إذا كانت ولودًا قد أنجبت لعل الله يرزقك منها ولدًا أو أولادًا فتجمع بين المصلحتين؛ بين إرضاء والديك وبين الحفاظ على زوجتك القديمة التي تحبها وتحبك، رزق الله الجميع التوفيق والهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12553/هل-يطاع-الوالدان-في-تطليق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61414.mp3","categories":["الطلاق"]},{"id":14145,"question":"السائلة من المدينة المنورة الحقيقة كتبت هذه الرسالة المطولة بأسلوبها الخاص ومختصرها سماحة الشيخ: تذكر بأنها امرأة متزوجة منذ تسع سنوات تقول: ولي من زوجي ولد واحد وزوجها لا يعمل دائمًا فكان يعمل في التجارة وخسر جميع ما يملك من أمواله وأموال الناس الشركاء، ثم عمل في شركة وتركها بعد ثلاثة شهور، وهو دائم الاستلاف، وأصبح مديون للناس بمائة وخمسين ألف ريال، وهو الآن لا يعمل، علمًا بأنني دائمًا أقف إلى جواره في كل أزماته، والآن مرضت هذه الزوجة ولا تطيق أن ترى هذا الزوج تقول بسبب تصرفاته وبسبب الديون التي تراكمت عليه وعدم الاستقرار العائلي، سؤالها سماحة الشيخ تقول: لو طلبت الطلاق من هذا الرجل هل أكون آثمة علمًا بأن أهلي يريدون أن يطلقوني منه؛ لأن زوجي باع جميع ما يخصني من منزل وأثاث وذهب، فهل طلبي للطلاق حرام أم حلال؟","title":"حكم طلب المرأة الطلاق من الزوج المديون","answer":"الجواب: إذا كان يقوم بما يجب من النفقة فلا يجوز الطلب، إذا كان لا يظلمك فيقوم بما تحتاجين إليه من النفقة ولو أنه مدين فليس لك طلب الطلاق، أما إذا كان يظلمك وتخافين على نفسك منه من ضربه أو أخذ بقية مالك، يطالبك بأخذ بقية مالك فلك طلب الطلاق.\nالمقصود إذا كان يضرك في دينك أو في مالك فلك طلب الطلاق، أما إذا كان لا، قد قام بحقك ولكن عليه ديون فلا يضره ذلك عليك السمع والطاعة والبقاء في حسابه والحذر من طلب الطلاق بغير حق.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12586/حكم-طلب-المراة-الطلاق-من-الزوج-المديون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54610.mp3","categories":["الطلاق","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":14148,"question":"يقول السائل في هذا  بالنسبة لطلاق المرأة الحائض هل يقع؟ وهل هو بدعة؟","title":"حكم طلاق المرأة أثناء الحيض","answer":"الجواب: نعم، طلاق الحائض بدعة، ولا يقع إذا اعترف به الزوجان، إذا كان يعلم حين طلقها أنها حائض لا يقع على الصحيح؛ لأنه ثبت عن النبي ﷺ من حديث ابن عمر أنه أنكر عليه لما طلق وأمره أن يعيدها، ثم إذا طهرت أمسكها أو طلقها، إذا طهرت حتى تحيض حيضة أخرى ثم يطلق أو يمسك.\nفالحاصل أن تطليق الحائض لا يجوز، والصحيح أنه لا يقع أيضًا، هذا هو الصحيح خلافًا للجمهور، لكن لابد أن يكون يعرفه الزوج، أما إذا كان طلقها وهو لا يدري أنها حائض يقع الطلاق ولو قالت: أنها حائض ما يقبل قولها وحدها، لابد أن يعلم هو أنها حائض حين الطلاق، يعني: يعلم ذلك قبل أن يطلق، أما كونه يعلم من بعد أن طلق من قولها ما يكفي، إذا طلقها وهو يعلم أنها حائض فقد أثم والطلاق لا يقع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12589/حكم-طلاق-المراة-اثناء-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54613.mp3","categories":["الطلاق"]},{"id":14253,"question":"المستمع (م. ر. س) يذكر في رسالة مطولة أنه طلق زوجته كتابيًا بثلاث طلقات بدون تلفظ، ثم طلقها بعد فترة بطلقة واحدة وهي إلى الآن معه وله منها ستة أولاد أربعة قبل كتابة الطلاق واثنان بعده ويسأل: هل الطلاق وقع؟ ما حكم معاشرته لها طوال هذه الفترة؟ وهل يتركها؟ وكم بقي له من الطلقات؛ لأن هذا الأمر يقض مضجعه ويقلق راحته بعد أن هداه الله إلى الطريق المستقيم؟","title":"حكم الطلاق كتابة دون اللفظ","answer":"الجواب: على السائل أن يراجع المحكمة مع ولي المرأة حتى ترشده المحكمة إلى ما يلزمه، أو يكتب لنا حتى ننظر في الموضوع بواسطة المحكمة.\nالمقصود أن هذا يحتاج إلى مراجعة المحكمة أو الكتابة إلينا حتى نسأل المرأة ونسأل وليها عما لديهما فيما ذكره السائل، نسأل الله للجميع الهداية، وكان الواجب عليه التوقف حتى يستفتي ويسأل، نسأل الله لنا وله الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12722/حكم-الطلاق-كتابة-دون-اللفظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61712.mp3","categories":["الطلاق"]},{"id":14254,"question":"المستمع (م. ر. س) يذكر في رسالة مطولة أنه طلق زوجته كتابيًا بثلاث طلقات بدون تلفظ، ثم طلقها بعد فترة بطلقة واحدة وهي إلى الآن معه وله منها ستة أولاد أربعة قبل كتابة الطلاق واثنان بعده ويسأل: هل الطلاق وقع؟ ما حكم معاشرته لها طوال هذه الفترة؟ وهل يتركها؟ وكم بقي له من الطلقات؛ لأن هذا الأمر يقض مضجعه ويقلق راحته بعد أن هداه الله إلى الطريق المستقيم؟","title":"حكم الطلاق كتابة دون اللفظ","answer":"الجواب: على السائل أن يراجع المحكمة مع ولي المرأة حتى ترشده المحكمة إلى ما يلزمه، أو يكتب لنا حتى ننظر في الموضوع بواسطة المحكمة.\nالمقصود أن هذا يحتاج إلى مراجعة المحكمة أو الكتابة إلينا حتى نسأل المرأة ونسأل وليها عما لديهما فيما ذكره السائل، نسأل الله للجميع الهداية، وكان الواجب عليه التوقف حتى يستفتي ويسأل، نسأل الله لنا وله الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12722/حكم-الطلاق-كتابة-دون-اللفظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61712.mp3","categories":["الطلاق"]},{"id":14305,"question":"رسالة وصلت إلى البرنامج من الدوحة قطر باعث الرسالة مستمع من هناك يقول: (ع. ن. ف) يسأل ويقول: تشاجرت مع ابن عمتي والسبب قوله: إنك قلت لأهلي كذا وكذا، وأنا لا أعرف هل قلت هذا الكلام أم لا، وقلت: تحرم علي زوجتي بأني لم أقل هذا الكلام، وبعد ذهابه بدأت أفكر هل زوجتي حلال أم طالق، برغم أنني لا أعرف هل أنا قلت الكلام الذي ذكره ابن عمتي أم لم أقل، واليوم أنا في حيرة، أرشدوني جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق أو الحرام على ما يَشُك فيه","answer":"الجواب: إذا كنت قلت ذلك لقصد أن يسمح عنك وأن يصدقك ولم ترد تحريم أهلك ولا طلاق أهلك وإنما قلت ذلك ليصدقك وليعذرك وينتهي النزاع بينكما فليس عليك طلاق ولا تحريم، ولكن عليك الكفارة كفارة اليمين، وهي إطعام عشرة مساكين أو كسوتهم، أو تحرير رقبة، هذا هو الواجب في مثل هذا في أصح قولي العلماء أن التحريم والطلاق إذا كان المقصود منه الحث أو المنع أو التصديق أو التكذيب وليس القصد تحريم الزوجة ولا طلاقها وإنما أراد المطلق أو المحرم تصديق أخيه أو منعه من كذا أو الحث على كذا تلزمه كفارة يمين، فإذا كنت أردت بذلك أن يصدقك وأن ينتهي النزاع وأن ترضيه بما قلت. وإن كنت لا تعلم الواقع فأنت في هذا عليك كفارة اليمين فقط ولا يقع الطلاق ولا يقع التحريم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12794/حكم-من-حلف-بالطلاق-او-الحرام-على-ما-يشك-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62207.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14363,"question":"المستمع عبدالمحسن أسامة محمد، من اليمن الشمالية، بعث يسأل ويقول: هل الحلف بالطلاق لتأكيد كلام بدون نية الطلاق يقع طلاق أو لا؟ وهل العبارة التي تقول: (الحلف بالطلاق ليس طلاقًا) حديث عن رسول الله ﷺ؟","title":"هل يقع الحلف بالطلاق؟ وهل \"الحلف بالطلاق ليس طلاقًا\" حديث؟","answer":"الجواب: ليس حديثًا عن النبي ﷺ، ولكن فيه تفصيل: الحلف بالطلاق إن كان أراد به إيقاع الطلاق وقع الطلاق، وإن كان ما أراد أن يكون، فيه كفارة يمين عند جمع من أهل العلم، وبعض أهل العلم يراه: طلاقًا، مطلقًا، ولو قصد به اليمين. والحلف بالطلاق كأن يقول: عليه الطلاق ما يكلم فلانًا، عليه الطلاق لا تخرجي من البيت، عليه الطلاق لا تكلمي فلانًا، عليه الطلاق ألا يزور فلانًا، هذا يسمى يمين إذا كان قصد به المنع، أو الحث أو التصديق أو التكذيب، فإذا قال: عليه الطلاق أنك ما تكلمين أخاك فلانًا، أو جارك فلانًا، وقصده منعها ليس قصده فراقها، فهذا عليه كفارة يمين إذا كلمت، وهكذا لو قال: عليه الطلاق أنه ما يزور فلانًا قصده منع نفسه من الزيارة، هذا يسمى يمينًا.\nأما إن أراد إيقاع الطلاق فهذا يقع الطلاق بالزيارة؛ لأنه علقه عليها، فإذا زار وقعت طلقة واحدة كما قال، مثلما لو قال: إذا دخل رمضان فأنت طالق، هذا ما يسمى يمين هذا تعليق، إذا دخل رمضان طلقت، أو قال: متى حضت أو متى ولدت، أو نحو ذلك. المقصود: أن الطلاق المعلق إذا كان ما قصده التصديق أو التكذيب أو الحث أو المنع إنما قصده التعليق فقط فهذا يقع، إن كلمت زيدًا فأنت طالق، قصده أنه يقع الطلاق وقع الطلاق، إذا دخل رمضان فأنت طالق يقع إذا دخل رمضان، أما إذا قال: إن كلمت زيدًا وقصده منعها من الكلام ما يحب أنها تكلمه، هذا إذا كلمته يكون عليه كفارة يمين؛ لأنه أراد منعها فيسمى يمينًا في أصح قولي العلماء، وتكون فيه الكفارة فقط. وقال بعض أهل العلم: إن الطلاق يقع مطلقًا، ولو نوى به اليمين، وهذا قول ضعيف. والصواب: أنه متى نوى اليمين فإنه ليس عليه، لا يقع عليها طلاق، ولكن عليه الكفارة، واحتج العلماء على ذلك بأدلة كثيرة، منها قوله ﷺ: الأعمال بالنيات وهو لم يرد إلا منعها ما أراد إيقاع الطلاق، إنما أراد منعها، أو منع نفسه من شيء.\nومنها ما حصل من فتاوى بعض الصحابة فيمن حلف ألا يفعل كذا، وإن فعل فعبيده أحرارن وماله صدقة، قد أفتى في هذا ابن عمر وبعض الصحابيات بأنه يمين، والطلاق هو أشد، الطلاق هو مبغوض إلى الله، فإذا كان العتق والصدقة يمين فالطلاق من باب أولى.\nويروى عن جماعة من الصحابة أنهم جعلوه يمينًا، يروى عن علي والزبير وجماعة أنه جعلوه يمينًا. فالحاصل: أن هذا الطلاق لم يرده صاحبه، والرسول ﷺ يقول: إنما الأعمال بالنيات وهو إنما أراد منعًا أو حثًا أو تصديقًا أو تكذيبًا، فإذا قال: عليه الطلاق ألا يكلم فلانًا قال: أراد منع نفسه، وإذا قال: عليه الطلاق أن يزور فلانًا، أراد حث نفسه على الزيارة، وإذا قال: عليه الطلاق أنه ما فعل كذا، أراد التصديق أنه يصدق في ذلك، أو قال: عليه الطلاق مثلًا أن فلانًا كاذبًا، وأراد بذلك أن يكذب فلانًا. فالحاصل: أنه لم يرد إيقاع الطلاق إنما أراد معنىً آخر فيكون له ما أراد على الصحيح، وعليه الكفارة إذا كان أراد هذا المعنى، ولا يقع الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12843/هل-يقع-الحلف-بالطلاق-وهل-الحلف-بالطلاق-ليس-طلاقا-حديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48710.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":14387,"question":"يقول: هل الحلف بالطلاق في حالة الغضب وثورة النفس بدون نية يقع طلاقًا؟ وهل الثورة النفسية تعتبر إكراهًا؟","title":"هل الحلف بالطلاق حالة الغضب يقع طلاقًا؟","answer":"الجواب: هذا أيضًا فيه تفصيل: إن كان اشتد معه الغضب حتى ما يعقل، أو غلب عليه حتى لا يستطيع حبس نفسه، ومنع نفسه، فالصحيح: أنه لا يقع.  أما إن كان غضبًا عاديًا فإنه يقع؛ لأن الغضب ثلاثة أقسام: غضب يزول معه الشعور، هذا كالمجنون لا يقع معه الطلاق؛ لأنه زال الشعور، ما يعرف ماذا قال؟ الغضب الثاني: اشتد معه الغضب، وملكه الغضب، ولم يستطع منع نفسه لشدة الكلام الذي سمع، أو الفعل؛ لكونها مثلًا، سبته ولعنته، أو تضارب معها، فاشتد غضبه حتى ما ملك نفسه، فالصحيح: أنه لا يقع. القسم الثالث: غضب عادي لبعض الأسباب، هذا يقع معه الطلاق عند جميع أهل العلم، ولا يمنع وقوع الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12869/هل-الحلف-بالطلاق-حالة-الغضب-يقع-طلاقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48711.mp3","categories":["الطلاق"]},{"id":14402,"question":"في يوم الجمعة يقول قبل صعود الخطيب للمنبر صليت ركعتين، وقمت بمسك المصحف الشريف، وقلت: بحق هذا القرآن لا أشرب السجائر والدخان مرة ثانية طول عمري، فإذا شربت مثلًا الشيشة هل أكون قد وقعت في اليمين؟ وهل علي كفارة؟","title":"ما حكم الحلف بحق المصحف؟ وحكم شرب والدخان والشيشة","answer":"الجواب: لا يجوز لك أن تحلف بحق القرآن، حق القرآن تعظيمه، وتعظيمه من أعمالك، لكن أن تقول بالله، أو بكلام الله تحلف بالله، أو بكلامه وصفاته، لا بأس، أما بحق القرآن، حق القرآن عليك أن تعظمه، وأن تعمل به، وهذا من عملك، وعملك مخلوق، فلا تقسم بالمخلوقات، لكن تقسم بنفس القرآن، بالله، بكلام الله، بعلم الله، بعزة الله، تقسم بالله أو بصفاته لا بأس. وعليك أن تجتنب الدخان وسائر المحرمات، عليك أن تحذر الدخان والشيشة والخمر وجميع المخدرات المسكرة وإن لم تحلف، وإن لم تقسم، يجب عليك أن تجتنبها وتحذرها؛ لأنها منكرة ومحرمة، فالواجب عليك الحذر منها، وتركها مطلقًا، ولو لم تحلف. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12884/ما-حكم-الحلف-بحق-المصحف-وحكم-شرب-والدخان-والشيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55221.mp3","categories":["الأيمان والنذور","الطلاق","الأطعمة والأشربة"]},{"id":14405,"question":"هذا (المهدي . ح. ع) أرسل بمجموعة من الأسئلة، يقول في السؤال الأول: لقد ارتكبت ذنبًا، وحلفت بأن لو عدت إلى هذا الذنب مرة ثانية تكون زوجتي علي كظهر أمي، ولكنني عدت ثانيًا، و هل يقع مثل هذا الظهار؟ وما هي الكفارة سماحة الشيخ؟","title":"حكم من حلف بالظهار على ترك ذنب ثم عاد","answer":"الجواب: نعم، إذا قلت هذا، ثم عدت يكون قد ظاهرت منها، عليك كفارة الظهار لا تقربها، ولا تمسها حتى تعتق رقبة، فإن عجزت تصوم شهرين متتابعين، ستين يومًا، فإن عجزت تطعم ستين مسكينًا، هذه كفارة الظهار، ولا يجوز لك هذا العمل، هذا ما يجوز، سماه الله منكرًا من القول وزورًا. فالواجب عليك أن تحذر مثل هذه الأيمان التي فيها المظاهرة، وفيها التحريم من زوجتك، لكن متى فعلت هذا، قلت: متى فعلت هذا فإن زوجتي كظهر أمي علي، تحرم علي يكون ظهار، عليك أن تجتنبها، وتمتنع منها حتى تكفر كفارة الظهار، وهي عتق رقبة، فإن عجزت تصوم شهرين متتابعين؛ ستين يومًا، فإن عجزت تطعم ستين مسكينًا، كل مسكين له نصف الصاع، كيلو ونصف تقريبًا قبل أن تقربها، كما نص الله على هذا في كتابه الكريم في سورة المجادلة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12887/حكم-من-حلف-بالظهار-على-ترك-ذنب-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55302.mp3","categories":["الطلاق","الظهار","الرجعة"]},{"id":14434,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. ع. ق) من الدمام، أخونا له عدد من الأسئلة فيسأل في سؤاله الأول ويقول:إذا تزوج الإنسان وهو لا يصلي، لا هو ولا الزوجة، وبعد الزواج بمدة طويلة هداهم الله للصلاة والأمور الشرعية، وفي وقت العقد اكتشف أنه كان محدثًا حدثًا أكبر، ولم يغتسل وقت العقد، بل أجرى العقد وهو على ذلكم الحال، هل العقد صحيح، أم بماذا تنصحونه حيال ما ذكر؟جزاكم الله خيرًا.","title":"حكم العقد إذا كان الزوجان لا يصليان","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإذا كان الرجل والمرأة حين العقد لا يصليان، فالعقد صحيح؛ لأنهما مستويان في ترك الصلاة، وفي الكفر عند من كفرهما بذلك وفي عدمه، فالنكاح صحيح، والصواب أن ترك الصلاة كفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ولم يقل: بشرط جحدهما الوجوب، بل أطلق -عليه الصلاة والسلام-، فدل على أن من ترك الصلاة كفر، وإن أقر بالوجوب، ومن ذلك قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، لكنهما مستويان لا يصليان، فالعقد بينهما صحيح كالنصرانيين واليهوديين والوثنيين إذا تزوجا؛ لأنهما مستويان في عدم الدين. أما إذا كان أحدهما يصلي والآخر لا يصلي حين العقد فإن الواجب تجديد العقد بعدما صلى من لا يصلي وتاب إلى الله  يجدد العقد على الصحيح على القول بأن ترك الصلاة كفر أكبر، فيجدد العقد بمهر جديد، وشاهدي عدل، وبواسطة الولي، فالعقد يحضره أربعة: الولي والزوج والشاهدان، فيجدد العقد بمهر وشاهدي عدل بعدما تاب الله على من كان لا يصلي منهما، والحمد لله احتياطًا وخروجًا من خلاف العلماء الذين كفروا تارك الصلاة، وقولهم أصح لظاهر الأدلة الشرعية. وأما كونه تزوج على غير طهارة فهذا لا يضر العقد، وهكذا لو كانت المرأة على حيض حين العقد أو في نفاس لا يضر إذا كانت ليست في عدة، كالبكر عقد عليها وهي في الحيض أو امرأة قد خرجت من العدة عقد عليها وهي في الحيض لا يضر ذلك، ليس من شرط العقد أن يكون الرجل طاهرًا أو المرأة طاهرة، فإذا تم العقد والرجل على جنابة أو المرأة على جنابة أو في حيض أو في نفاس فالعقد صحيح ليس من شرطه الطهارة ما دامت ليست في العدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12909/حكم-العقد-اذا-كان-الزوجان-لا-يصليان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62401.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":14527,"question":"رسالة طويلة جدًا، باعثها مستمع يقول: (م. ع) سوداني من الرياض، مقيم، وساكن في السليمانية، يقول في رسالته: أنا شاب أبلغ من العمر خمسًا وثلاثين سنة، طيلة هذه السنين لم أصل أبدًا، تزوجت قبل ثلاث سنوات، وكانت زوجتي على خلاف معي دائمًا، كنت أعمل سائق تكسي، وزوجتي لا تثق في هذه المهنة؛ لأنها كانت غيورة جدًا جدًا، وأصرت علي أن أتخلى عن هذه المهنة، وأنا لم أوافق المهم والخلاصة كالتالي:ذهبت في يوم إلى أهلها، ولما ذهبت، لما أصرت على الطلاق، وفي منزل أهلها أمام والديها قلت لها: خلاص أنت طالق، وعدت ثاني يوم وأخذتها إلى بيتي بدون أي شيء كأنما لم يحصل شيء، وبعد مرور ستة أشهر ذهبت أيضًا إلى بيت أهلها، وأصرت مرة ثانية على الطلاق، وبعثت لها خطاب وقلت لها: خلاص أنت طالق، وبعد مرور شهر ذهبت لها، وأخذتها إلى بيتي كما حصل في المرة الأولى، أي: بدون صفاح، وعاشت معي حوالي ثلاثة عشر شهرًا، وعندما أردت السفر...الشيخ: كتب صفاح.المقدم: صفاح يقول، لا أدري ماذا يقصد بها؟وعندما أردت السفر للسعودية وبينما أجهز للسفر حضرت والدتها إلى بيتي، وأخذت العفش كله، وزوجتي وذهبت به، وأصرت أم زوجتي على أن أطلقها، المهم: دخل أصحاب الخير واسطة، لكن دون جدوى، ولظروف السفر طلقتها أمام سبعة أشخاص طلاق دون خاطري، كل هذه الطلقات كانت مجرد حل للمشاكل، ولم أنو أبدًا بقلبي على فراقها، والحمد لله وصلت إلى السعودية، وتبت من كل شيء، وأديت فريضة الحج والعمرة أكثر من ثلاث مرات. الرجاء إرشادي إلى الصواب، وهل زواجي من بدايته باطل؛ لعدم أداء الفرائض وخاصة الصلاة؟ أرجو إفادتي، والصفاح: معناه: العقد، كما يفيد الأخ صلاح، جزاكم الله خيرًا.","title":"حكم من طلق زوجته ثلاث طلقات وكان لا يصلي","answer":"الجواب: أولًا: ترك الصلاة من الجرائم العظيمة، بل من الكفر، كما قال النبي -عليه الصلاة والسلام-: بين الرجل وبين الشرك والكفر ترك الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فإذا كانت زوجتك تصلي وأنت لا تصلي وقت العقد فالعقد غير صحيح في أصح قولي العلماء، والواجب تجديده بعد التوبة. وعلى كل حال هذه المسألة تحتاج إلى مراجعة المفتي لديكم في بلدكم، تراجع المفتي لديكم أنت والمرأة ووليها، تشرح له القصة والواقع، وهو ينظر في ذلك -إن شاء الله-، ونسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، إذن في هذا الأمر المتشابك يحتاج إلى مراجعة المفتي في بلده؟\nالشيخ: نعم، نعم، حتى يحضر عنده الجماعة: الرجل والمرأة ووليها، وحتى يسألهم عن الحقائق، وحتى يكون على بينة في ذلك، ثم يفتيهم بما يقتضيه الشرع المطهر، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13022/حكم-من-طلق-زوجته-ثلاث-طلقات-وكان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63405.mp3","categories":["الطلاق"]},{"id":14732,"question":"المستمع ناصر مقبل يمني من الرياض رماح، بعث يقول: حلفت بالطلاق على ألا أعود إلى مزاولة شيء وفعلت هذا الشيء، هل علي كفارة؟ وماذا يكون حكم الدين في هذا الأمر؟ أفيدوني، أفادكم الله.","title":"ما يلزم من حلف بالطلاق ألا يفعل شيئًا ما ثم فعله؟","answer":"الجواب: هذا فيه تفصيل: إذا حلف أنه ما يفعل هذا الشيء، إن كان قصده الامتناع ومنع نفسه من هذا الشيء وليس قصده الطلاق ليس قصده إيقاع الطلاق، مثل: علي الطلاق ما آكل طعام فلان، علي الطلاق ما أزور فلانًا، قصده الامتناع ما قصده إيقاع الطلاق، ولكن قصده أن يمتنع، فهذا فيه كفارة يمين إذا فعله.  أما إذا قصد إيقاع الطلاق يقع الطلاق، إذا قال: علي الطلاق ما أكلم فلانًا وكلمه ناويًا أنه إذا كلمه يقع الطلاق، فيقع الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13222/ما-يلزم-من-حلف-بالطلاق-الا-يفعل-شيىا-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49006.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14735,"question":"والد زوجتي طلق زوجته مرتين في حالة غضب، والمرة الثالثة وقع عليها الطلاق وهو في حالة مرض، هل هذا الطلاق جائز؟ وما هو حكم الدين؟","title":"ما حكم طلاق الغضبان والمريض؟","answer":"الجواب: يراجع المحكمة -إن شاء الله- بتعلمه، أو يكتب لنا وننظر في الأمر، إما يكتب لنا وننظر في الأمر، وإلا يراجع المحكمة، وفيها الكفاية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13231/ما-حكم-طلاق-الغضبان-والمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49008.mp3","categories":["الطلاق"]},{"id":14736,"question":"شروط طلاق الحامل؟","title":"حكم طلاق المرأة الحامل","answer":"الجواب: طلاق الحامل مشروع، لا بأس به، لكن يكون طلقة واحدة؛ لأن النبي  قال لـابن عمر: طلقها طاهرًا أو حاملًا بعض العامة يرى أن طلاق الحامل لا يصلح، وهذا غلط، إنما هو من رأي العامة.  أما طلاق الحامل عند أهل العلم فلا بأس به، وقد ثبت في الحديث الصحيح عن ابن عمر -رضي الله تعالى عنهما- أن النبي ﷺ قال له: طلقها طاهرًا أو حاملًا نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13240/حكم-طلاق-المراة-الحامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63002.mp3","categories":["الطلاق"]},{"id":14738,"question":"أخيرًا يسأل أخونا عن الطلاق الرجعي والطلاق البائن بينونة صغرى وكبرى؟","title":"بيان الطلاق الرجعي والطلاق البائن","answer":"الجواب: الطلاق الرجعي هو الذي يقع في حق المرأة بعد الدخول بها، وهي قد دخل بها قد اتصل بها فإذا طلقها طلقة واحدة، أو طلقتين وهي حامل، أو في طهر لم يمسها فيه، يقال له: الطلاق الرجعي.  أما إن طلقها الطلقة الثالثة فإنه يكون طلاقًا ليس برجعي، تبين بينونة كبرى، لا تصلح له إلا بعد زوج ودخول، فهذا تفصيل الطلاق الرجعي والطلاق البائن، إذا طلقها طلقة واحدة حال كونها حاملًا، أو طلقتين حال كونها حاملًا، فهذا طلاق رجعي، له الرجوع إليها ما دامت في العدة. وهكذا لو طلقها في طهر لم يجامعها فيه طلقة واحدة، أو طلقتين أو طلقها وهي آيسة طلقة واحدة، أو طلقتين فإنه له المراجعة، ما دام في العدة، وعدة المرأة التي تحيض ثلاث حيض، وعدة الآيسة ثلاثة أشهر، أما إن طلقها في الحيض، أو في النفاس، أو في طهر جامعها فيه، فتقدم أن هذا لا يقع في أصح قولي العلماء. وأما الطلاق البائن فهو الذي يطلقها بالثلاث عند الجمهور بكلمة واحدة، والصحيح أنه ليس ببائن، الصحيح أنه يعتبر واحدة، إذا كان بلفظ واحد قال: طالق بالثلاث، فالصحيح أنه يعتبر طلقة واحدة، كما ثبت ذلك من حديث ابن عباس: عن النبي ﷺ أنه جعل الطلاق الثلاث طلقة واحدة، يعني إذا كان بلفظ الثلاث ليس بمكرر بكلمة واحدة، يقول ابن عباس: \"كان الطلاق على عهد النبي ﷺ وعلى عهد الصديق أبي بكر وعلى عهد عمر الطلاق الثلاث بواحدة\" ثم إن عمر  لما رأى الناس استعجلوا في هذا أمضاه عليهم، فالصواب أنه يعتبر واحدة إذا كان طلقها بالثلاث بكلمة واحدة، وهكذا لو قال: طالق طالق طالق، ولم ينو الثلاث فإنه يعتبر واحدة، ويكون اللفظ الثاني والثالث تأكيد للفظ الأول، كما قاله أهل العلم. أما إذا طلقها بالثلاث بألفاظ متعددة، قال: أنت طالق، أنت طالق، أنت طالق، ولم ينو إفهامًا ولا تأكيدًا، أو قال: تراك طالق، تراك طالق، تراك طالق، ولم ينو إفهامًا ولا تأكيدًا، وهي في طهر لم يجامعها فيه، أو في حال الحمل فإنه تقع الثلاث، وهكذا لو قال: طالق، ثم طالق، ثم طالق، تقع الثلاث إذا كانت حاملًا، أو في طهر لم يجامعها فيه، ويكون الطلاق هذا بائنًا، وهكذا لو كان قد طلقها طلقتين، ثم طلقها الثالثة، وهي حامل أو في طهر لم يجامعها فيه بانت بذلك بينونة كبرى، لا تحل له حتى تنكح زوجًا غيره، نكاح رغبة لا نكاح تحليل، ويطأها الزوج الثاني ثم يفارقها بموت أو طلاق. أما البينونة الصغرى فهي إذا كانت في المخالعة على المال، إذا طلقها طلقة واحدة، أو طلقتين على مال هذه تسمى بينونة صغرى، ليس له الرجوع إليها إلا بإذنها وبنكاح جديد؛ لأنها ملكت نفسها بالعوض، فإذا طلقها على مال طلقة واحدة، أو طلقتين تسمى مخالعة يسمى طلاق على مال، هذا ليس له مراجعتها إلا بإذنها بعقد جديد، يعني بنكاح جديد، وولي وشاهدين كأنه أجنبي، بسبب المال، ومثل ذلك التي طلقها طلقة واحدة أو طلقتين وخرجت من العدة يقال: قد بانت بينونة صغرى لخروجها من العدة بعد طلقة أو طلقتين، وهي امرأة رجعية قد دخل بها، وهو لم يطلقها في طهر جامعها فيه، ولا في حيض أو نفاس، فإنه في هذه الحالة إذا خرجت من العدة يقال لها: طلقت طلاقًا بائنًا بسبب خروجها من العدة بعد الطلقة أو الطلقتين، فله العود إليها بنكاح جديد كالمخلوعة، والله أعلم. المقدم: الله أعلم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13247/بيان-الطلاق-الرجعي-والطلاق-الباىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63005.mp3","categories":["الطلاق"]},{"id":14743,"question":"المستمع (ع. ن. ب) من الزرقاء بالأردن يقول في رسالة بعث بها إنه قبل حوالي عشرين عامًا حصل جدال بينه وبين شخص آخر، وقال له هذا الشخص:إن فلانًا يقول: إنك قلت كذا وكذا، فقلت له: علي علي الطلاق أنني لم أقل ذلك، وأنا كنت وقتها متأكد بأنني لم أقل ما نسب عني، ولكن الشك ساورني فيما بعد بأن أكون ربما قلت ما حلفت على أني لم أقله، أرشدوني عن إمكانية وقوع الطلاق من عدمه تجاه هذا الحلف؟ وهل علي كفارة أو أي شيء آخر؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق على شيء ثم شك فيه","answer":"الجواب: إذا كنت حين طلقت تعتقد أنك لم تقل ذلك فليس عليك شيء، والطلاق ليس بواقع؛ لأنك مسؤول عن نيتك، وعن قصدك وعن حالك حين الطلاق، فمادمت حين الطلاق تعتقد أنك صادق فليس عليك شيء.  أما لو كنت قلت ذلك لتصدق وخوفًا من معرة الاعتراف وقلت ذلك لتصدق، وأنت تعلم أنك كاذب، فعليك كفارة يمين عن ذلك؛ لأنك ما قصدت إيقاع الطلاق، وإنما قصدت أن تصدق، أما إن كنت قصدت إيقاع الطلاق فإنه يقع الطلاق، وأما يمينك المسؤول عنها طلاقك المسؤول عنه فإنه لا يقع؛ لأنك حين طلقت تعتقد أنك صادق، فلا حرج عليك ولا طلاق عليك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13259/حكم-من-حلف-بالطلاق-على-شيء-ثم-شك-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63009.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14748,"question":"سماحة الشيخ، لكم قول طيب بالنسبة لطلاق الغضبان تتكرمون بإعادته هنا؟جزاكم الله خيرًا.","title":"ما حكم طلاق الغضبان؟","answer":"الجواب: الغضبان له ثلاثة أحوال، كما ذكرها ابن القيم -رحمه الله- في كتابه إعلام الموقعين، وفي غيره، له ثلاثة أحوال:\nالحال الأولى: أن يشتد معه الغضب حتى لا يشعر ما يقع منه بسبب شدة الغضب، فهذا كالمجنون، لا يقع طلاقه عند الجميع، إذا كان لا يشعر بالطلاق بسبب شدة الغضب. الحال الثاني: يغضب غضبًا شديدًا، لكنه لم يزل شعوره، معه الشعور، لكنه اشتد غضبه بسبب المضاربة أو المسابة أو المشاتمة، أو ما أشبه ذلك مما يسبب شدة الغضب، فإذا وجدت أسبابه وعلاماته واعترف به الزوجان، أو قامت به البينة فإن هذا يعتبر طلاقًا غير واقع؛ لأنه في شدة الغضب قد فقد صوابه وفقد السيطرة على نفسه، وفقد القدرة على منع نفسه من الطلاق بسبب شدة الغضب، فهذا الراجح من قولي العلماء: أنه لا يقع، وهو الذي نفتي به، كما رجح ذلك العلامة ابن القيم -رحمه الله- وشيخه أبو العباس شيخ الإسلام ابن تيمية -رحمه الله-، وقال به جمع من أهل العلم. إذا اشتد غضبه لأسباب واضحة من مضاربة أو مسابة أو غير هذا من الأسباب الواضحة، ولكن لم يزل شعوره معه الشعور، معه بقية من الشعور، يعلم ما صدر منه، لكنه قد اشتد غضبه حتى عجز عن السيطرة على نفسه، فهذا الصواب أنه لا يقع طلاقه في هذه الحال كالذي فقد شعوره. الحال الثالث: غضب غضبًا عاديًا لا يمنعه من التعقل، ويملك نفسه، هذا يقع بالإجماع، هذا الأخير الذي غضب غضبًا لكن لا يسمى غضبًا شديدًا غضبًا عاديًا، تكلمت عليه كلامًا أغضبها، أو وجد منها ما يغضبه لكنه معه شعوره ومعه، يضبط نفسه، وليس عنده شدة تجعل الغضب غالبًا عليه، بحيث يكون قد فقد صوابه ستين في المائة، خمسين في المائة، سبعين في المائة، يعني: النصف فأكثر، يعني زال شعوره النصف فأكثر، اشتد معه الغضب فهذا لا يقع طلاقه، أما الذي غضب لكن شعوره الغالب معه، فهذا يقع طلاقه عند الجميع، عند جميع أهل العلم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13250/ما-حكم-طلاق-الغضبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63006.mp3","categories":["الطلاق"]},{"id":14750,"question":"سماحة الشيخ، لكم قول طيب بالنسبة لطلاق الغضبان تتكرمون بإعادته هنا؟جزاكم الله خيرًا.","title":"ما حكم طلاق الغضبان؟","answer":"الجواب: الغضبان له ثلاثة أحوال، كما ذكرها ابن القيم -رحمه الله- في كتابه إعلام الموقعين، وفي غيره، له ثلاثة أحوال:\nالحال الأولى: أن يشتد معه الغضب حتى لا يشعر ما يقع منه بسبب شدة الغضب، فهذا كالمجنون، لا يقع طلاقه عند الجميع، إذا كان لا يشعر بالطلاق بسبب شدة الغضب. الحال الثاني: يغضب غضبًا شديدًا، لكنه لم يزل شعوره، معه الشعور، لكنه اشتد غضبه بسبب المضاربة أو المسابة أو المشاتمة، أو ما أشبه ذلك مما يسبب شدة الغضب، فإذا وجدت أسبابه وعلاماته واعترف به الزوجان، أو قامت به البينة فإن هذا يعتبر طلاقًا غير واقع؛ لأنه في شدة الغضب قد فقد صوابه وفقد السيطرة على نفسه، وفقد القدرة على منع نفسه من الطلاق بسبب شدة الغضب، فهذا الراجح من قولي العلماء: أنه لا يقع، وهو الذي نفتي به، كما رجح ذلك العلامة ابن القيم -رحمه الله- وشيخه أبو العباس شيخ الإسلام ابن تيمية -رحمه الله-، وقال به جمع من أهل العلم. إذا اشتد غضبه لأسباب واضحة من مضاربة أو مسابة أو غير هذا من الأسباب الواضحة، ولكن لم يزل شعوره معه الشعور، معه بقية من الشعور، يعلم ما صدر منه، لكنه قد اشتد غضبه حتى عجز عن السيطرة على نفسه، فهذا الصواب أنه لا يقع طلاقه في هذه الحال كالذي فقد شعوره. الحال الثالث: غضب غضبًا عاديًا لا يمنعه من التعقل، ويملك نفسه، هذا يقع بالإجماع، هذا الأخير الذي غضب غضبًا لكن لا يسمى غضبًا شديدًا غضبًا عاديًا، تكلمت عليه كلامًا أغضبها، أو وجد منها ما يغضبه لكنه معه شعوره ومعه، يضبط نفسه، وليس عنده شدة تجعل الغضب غالبًا عليه، بحيث يكون قد فقد صوابه ستين في المائة، خمسين في المائة، سبعين في المائة، يعني: النصف فأكثر، يعني زال شعوره النصف فأكثر، اشتد معه الغضب فهذا لا يقع طلاقه، أما الذي غضب لكن شعوره الغالب معه، فهذا يقع طلاقه عند الجميع، عند جميع أهل العلم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13250/ما-حكم-طلاق-الغضبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63006.mp3","categories":["الطلاق"]},{"id":14751,"question":"متى يكون الطلاق حرامًا؟","title":"متى يكون الطلاق حرامًا","answer":"الجواب: في ثلاث أحوال: يحرم الطلاق في الحيض، وفي النفاس، وفي طهر جامع الزوج امرأته فيه، وهي ليست حاملة ولا آيسة، في هذه الأحوال الثلاث يحرم الطلاق، كما ثبت هذا في حديث ابن عمر النبي  أمره أن يطلقها قبل أن يمسها بعد طهرها من الحيض، فدل ذلك على أنها لا تطلق إلا في طهر لم يمسها فيه، ولا تطلق في حال الحيض، ولا في حال النفاس، هذه الأقوال الثلاثة يحرم فيها الطلاق:  الأول: كونها حائضًا.  الثاني: كونها نفساء.  الثالث: كونها في طهر قد جامعها فيه -قد مسها فيه- وليست حاملًا ولا آيسة.  أما إن كانت حاملًا فلا بأس بطلاقها، وإن كان قد جامعها، أو كانت آيسة كبيرة السن لا تحمل فإنه لا بأس بطلاقه لها ولو كانت في طهر جامعها فيه، نعم.\nالمقدم: بارك الله فيكم إذا طلق الرجل في أحد هذه الأحوال الثلاثة هل يقع الطلاق سماحة الشيخ؟ الشيخ: فيه خلاف بين أهل العلم: الجمهور يرونه يقع الطلاق في هذه الثلاث الأحوال، يحرم ويقع، والقول الثاني: يحرم ولا يقع.  وهو الأرجح، أرجح القولين لأهل العلم أنه يحرم ولا يقع؛ لكونه خلاف الشرع؛ لأن الرسول ﷺ لما طلق ابن عمر امرأته وهي حائض أمره الرسول أن يراجعها، ولم يعتبرها شيئًا -عليه الصلاة والسلام-، فردها عليه، ولم يرها شيئًا، وقال: إذا طهرت فليطلق أو ليمسك ولم يحسبها عليه النبي ﷺ في الأصح من قولي العلماء، فهذا هو المختار، لكن لو حكم حاكم بإمضاء الطلاق مضى حكمه واعتبر، ولم يجز نقضه لأحد من الناس، نعم. فلو عرض الموضوع على حاكم شرعي فحكم بإمضاء الطلاق في الحيض أو في النفاس أو في طهر جامع فيه مضى واعتمد؛ لأن حكم الحاكم يرفع الخلاف؛ ولأنه قول الجمهور فإذا حكم به حاكم وجب تنفيذه، نعم. المقدم: أحسن الله إليكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13245/متى-يكون-الطلاق-حراما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63004.mp3","categories":["الطلاق"]},{"id":14753,"question":"تسمحون لنا سماحة الشيخ، بأن نسأل عن طلاق متعاطي المخدرات؟الشيخ: نعم.المقدم: هل يقع أو لا؟","title":"حكم طلاق متعاطي المخدرات","answer":"الجواب: هذا فيه تفصيل:  إن كان السكر قد غلب عليه وغيّر عقله، ولم يشعر بما وقع منه شعورًا يضبط معه كيف يتكلم هذا لا يقع طلاقه، وقد أفتى به عثمان  بن عفان الخليفة الراشد، وقال به جمع من أهل العلم، واختاره أبو العباس ابن تيمية -رحمه الله- وتلميذه العلامة ابن القيم -رحمه الله-، وهذا هو الذي أفتي به.\nوهو الأرجح عندي، وعليه الفتوى، نعم. أما إذا كان السكر قد زال وهو يعقل ما يقول، يفهم ما يقول، فهذا يقع طلاقه، وذهب بعض أهل العلم إلى أنه يقع طلاقه مطلقًا إذا كان آثمًا، إذا كان سكره ليس له فيه عذر، بل تعاطى المسكرات آثمًا يقولون: لا تكون معصيته سببًا للتخفيف عنه، ويرون أن إيقاع الطلاق من العقوبة أيضًا له، هذا قول الأكثر أنه يقع عليه الطلاق إذا كان آثمًا، ولو زال عقله، وهذا قول عند من تأمله ليس بجيد، كيف يؤاخذ بشيء لا يعقله، والحد يكفي، حده الذي فرضه الله عليه يكفي في زجره عن المسكر الحد الشرعي ثمانين جلدة.  أما أنه يعاقب بشيء آخر جديد، وهو إيقاع الطلاق عليه، وتفريق بينه وبين أهله وأولاده فهذه عقوبة لا دليل عليها. فالصواب: أنه إذا كان قد فقد عقله ولو كان آثمًا فإنه لا يقع طلاقه، كما أفتى به عثمان  كما تقدم، أما الذي معذور يعني: جعل له شيئًا يسكره من غير اختياره، أو شرب شيئًا ظنه شرابًا سليمًا فبان مسكرًا ولم يتعمده وعرف من حاله ومن الأدلة الواقعة أنه لم يتعمد ذلك، فهذا لا يقع طلاقه كالمجنون؛ لأنه ليس بآثم، بأن أسقي شيئًا ظنه ليس بخمر ظنه شاهي، أو أنه شراب فصار خمرًا خدعوه، فهذا لا يقع طلاقه؛ لأنه معذور، كالمجنون، وإنما الخلاف الآثم الذي تعمد شرب المسكر، وزال عقله بسبب المسكر، هذا هو محل الخلاف.  والأرجح أيضًا أنه لا يقع طلاقه، كالذي فقد عقله بغير عمل منه، هذا هو الصواب وهذا هو الأرجح، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13256/حكم-طلاق-متعاطي-المخدرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63007.mp3","categories":["الطلاق"]},{"id":14792,"question":"السائلة: التي رمزت لاسمها بالحائرة (س. ع) من جازان، كتبت في الحقيقة رسالة مطولة مختصرها -يا سماحة الشيخ- تقول: أحيطكم علمًا -يا سماحة الشيخ- بأنني امرأة متزوجة من رجل يسيء في معاملتي، فهو قليل الصلاة، كثير السهر، كثير السب والشتم، يمنعني من زيارة أقاربي، يهددنني إن فعلت ذلك بالطلاق، ومن آخر ما وقع منه بأنه خطب لابنه الأكبر، وبعد عقد قرانه تخلى عنه، ورفض أن يعينه على تكاليف الزواج. فأنا الآن حائرة كما أنه لا يصرف علينا كما يجب، بل يضيع الأموال فيما لا يرضي الله  في السهرات وغيرها.فأنا الآن بين نارين وبناتي أصبحن كبيرات، لا أستطيع تركهن معه، ولا أستطيع الوقوف مع ابني ضده، فلسنا له أندادًا، وجهونا -يا سماحة الشيخ- في ضوء هذه الرسالة؟","title":"حكم البقاء مع زوج تارك للصلاة سيئ الخُلُق","answer":"الجواب: إن كان الرجل لا يصلي، أو يدع الصلاة في بعض الأحيان، فهذا كفر وضلال، الصحيح أن من ترك الصلاة كفر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فالواجب عليك فراقه، والذهاب إلى أهلك، والمطالبة بالطلاق من جهة المحكمة. أما إن كان يصلي، ولكن قد يتأخر عن صلاة في الجماعة، وإلا يصلي في البيت فهو عاصٍ، وقد تشبه بالمنافقين، ولكن لا يكفر بذلك. أما ما كان من جهة النفقة، ومن جهة السب والشتم فهذا عليك نصيحته أنت وأقاربه كإخوانه أو أبيه إن كان له أب أو جد، أو أقارب جيدين، أو جيران صالحين، تقولين لهم، وتستعين بالله، ثم بهم على نصيحته؛ لعل الله يهديه بأسبابكم، وإذا لم يقبل النصيحة ففي إمكانك الرفع إلى المحكمة، أو الذهاب إلى أهلك، وطلب الطلاق؛ لأن هذه الحال لا عيشة معها، حالة سيئة، فإذا لم يستقم على الطريق السوي، فلك أن تعافيه، وتطلبي الطلاق لسوء أخلاقه وسوء أعماله، ولكن إذا تيسر منك ومن أبيه أو جده أو إخوانه أو أعمامه أو جيرانه الطيبين، إذا تيسر نصيحته، لعله يهتدي، لعله يستقيم، لعل أخلاقه تصلح، لعله يترك السهر، إذا تيسر هذا فأبشري بالخير، واحتسبي الأجر.  فإن لم يتيسر هذا، فلك أن تذهبي إلى أهلك، وتطلبي الطلاق؛ لأن هذه أخلاق سيئة، لا يلزمك الصبر عليها، نسأل الله العافية، ونسأل الله لنا وله الهداية. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/13282/حكم-البقاء-مع-زوج-تارك-للصلاة-سيى-الخلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56115.mp3","categories":["الطلاق","حكم الصلاة وأهميتها","الأنكحة المحرمة"]},{"id":14807,"question":"المستمع: (س. ع. ب) مصري يعمل في العراق، بعث برسالة يقول فيها: في حالة غضب رجل سب الدين، والعياذ بالله، هل تطلق زوجته؟ وهل عليه كفارة؟ وما هي؟","title":"هل تطلق زوجة من سب الدين في حالة الغضب؟","answer":"الجواب: سب الدين ردة عن الإسلام، فإن تاب ورجع إلى الله، وأناب إليه قبل خروج زوجته من العدة؛ فهي زوجته، وإن خرجت من العدة قبل أن يتوب؛ لم تحل له إلا بنكاحٍ جديد، إذا تاب إلى الله ، ورجع إلى الحق. أما إن استمر على كفره وضلاله؛ فإنها لا تحل له حتى يتوب إلى الله، وحتى يجدد عقده عليها، بعد خروجها من العدة، إذا كانت قد خرجت من العدة، أما إذا تاب في العدة؛ فهي زوجته، ومن تاب، تاب الله عليه. أما إذا رفع إلى ولي الأمر، فولي الأمر يحيله إلى المحكمة، والمحكمة تحكم فيه بما يقتضي به الشرع المطهر، في ساب الدين، أو ساب الرسول -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13307/هل-تطلق-زوجة-من-سب-الدين-في-حالة-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64208.mp3","categories":["الطلاق","نواقض الإسلام"]},{"id":14820,"question":"المستمع (خ. أ. م) من الرياض، بعث برسالة يقول فيها: قابلني أحد أصدقائي، وقد رأى علي علامات التفكير والشرود الذهني، فسألني: هل فعلتها؟ يعني: هل طلقت؟ فقلت له: نعم فعلتها. وأنا أمازحه؛ حتى أرى مدى تأثره بذلك، وأنا لم أقصد الطلاق، إنما عندما سألني، قلت: نعم، قاصدًا بذلك أنني قد تزوجت، وهو يفهم الطلاق، ولم أتبين فهمه جيدًا لكلامي،  هل تقع طلقة أم لا؟علمًا بأن هذا الحدث منذ سنة تقريبًا، فماذا علي أن أعمل الآن وقد مر على الحدث سنة كما أفدتكم؟ أفيدوني، جزاكم الله خيرًا.","title":"حكم من سئل هل طلقت؟ فقال نعم ولم يقصد الطلاق","answer":"الجواب: ما دمت ما قصدت الطلاق فلا شيء عليك، الأعمال بالنيات، وهذه الألفاظ، هذه اللفظة من جنس ألفاظ الكنى، فلا يقع بها شيء، ما دمت لم تقصد الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13325/حكم-من-سىل-هل-طلقت-فقال-نعم-ولم-يقصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64307.mp3","categories":["الطلاق"]},{"id":14836,"question":"يقول: ما حكم من قال: تحرم علي زوجتي؟","title":"حكم من قال: تحرم علي زوجتي","answer":"الجواب: هذا حكمه حكم الظهار، إذا قال إنسان: تحرم علي زوجتي، أو هي حرام علي زوجتي، أو حرمها الله علي زوجتي، أو هي كظهر أمي، أو كظهر أختي أو كأختي، أو كأمي، يقصد تحريمها فهو ظهار، يسمى ظهارًا، وعليه كفارة الظهار قبل أن يمسها، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع بين اثنين قبل أن يمسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13328/حكم-من-قال-تحرم-علي-زوجتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63817.mp3","categories":["الطلاق","الظهار"]},{"id":14839,"question":"يقول: ما حكم من قال: تحرم علي زوجتي؟","title":"حكم من قال: تحرم علي زوجتي","answer":"الجواب: هذا حكمه حكم الظهار، إذا قال إنسان: تحرم علي زوجتي، أو هي حرام علي زوجتي، أو حرمها الله علي زوجتي، أو هي كظهر أمي، أو كظهر أختي أو كأختي، أو كأمي، يقصد تحريمها فهو ظهار، يسمى ظهارًا، وعليه كفارة الظهار قبل أن يمسها، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع بين اثنين قبل أن يمسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13328/حكم-من-قال-تحرم-علي-زوجتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63817.mp3","categories":["الطلاق","الظهار"]},{"id":14880,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: سافرت أنا ووالدي إلى اليمن، فخطب لي فتاة لم أكن أعرفها، وبعد الخطوبة زرنا أهل الفتاة، فسألني أبي: ما رأيك فيها؟ فقلت له: مناسبة، وتزوجتها وأحببتها، وبعد عدة شهور بدأ الخلاف بيننا وبين الوالدين؛ لكونها تختلف مع إخوتي الصغار، والدي يقول: إنها تنقل أسرارنا إلى الجيران، وطلب مني أن أطلقها، ما هو رأيكم؟جزاكم الله خيرًا.","title":"حكم الاستجابة للوالد في طلاق الزوجة","answer":"الجواب: لا تعجل، وانصحها حتى لا تفعل ما يخالف رأي والديك من نقل أسرارهم إلى الجيران، انصحها وعلمها وخبرها أن هذا لا يجوز، وأن عليها السمع والطاعة في المعروف، فأنت تنصحها، وهي عليها السمع والطاعة، والوالدان كذلك لا يعجلان في طلب طلاقها، وينصحانها أيضًا بالكلام الطيب، والأسلوب الحسن، حتى تزول المشكلة، وحتى تستقر الأمور.  ولا تعجل في الطلاق؛ لأن هذا مرض يحتاج إلى علاج، فعليك بعلاجها بالكلام الطيب، والأسلوب الحسن، والترغيب والترهيب، وهكذا الوالدان يعالجان معك ذلك بالكلام الطيب، والأسلوب الحسن، حتى تزول المشكلة -إن شاء الله-، وتهدأ الأمور وتستمر العشرة بينكما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13376/حكم-الاستجابة-للوالد-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64519.mp3","categories":["الطلاق","الأيمان والنذور","نصائح وتوجيهات"]},{"id":14995,"question":"يقول أيضًا: كان لي زوجتان فطلقت إحداهما، وبقيت في بيتي، وقد انتهت العدة، وما زالت في البيت أراها وتراني؛ لأن عندها أولاد فهل هذا جائز؟ وما الحكم في ذلك؟","title":"حكم بقاء المرأة في بيت زوجها بعد انتهاء العدة","answer":"الجواب: إذا كان الطلاق رجعيًا طلقة أو طلقتين، فلك العود إليها بنكاح جديد، أما إن كان الطلاق بائنًا بأن طلقتها آخر الثلاث، فإنها تحرم عليك حتى تنكح زوجًا غيرك، وبكل حال عليها بعد العدة أن تحتجب عنك، حتى ولو كان الطلاق طلقة واحدة، عليها الاحتجاب وألا تخل بها؛ لأنها صارت أجنبية بخروجها من العدة، إذا كانت رجعية طلقة أو طلقتين. أما إذا كان الطلاق بائنًا، بأن كان الطلقة آخر ثلاث، فإنها تحرم عليك من حين الطلاق، وليس لها أن تخلو بك، ولا أن تخلو بها، ولا أن تنظر إليها، بل يجب عليكما الحذر كالرجل الأجنبي مع الأجنبية. أما بقاؤها عندك في البيت هذا فيه تفصيل: إذا كان مضطرة إلى ذلك، وفي دور خاص، أو شقة خاصة، فلا حرج أن تبقى مع أولادها، أو تستأجر لها بيتًا تكون فيه مع أولادها، ولكن بكل حال لا تخلو بها، ولا تنظر إليها، يعني: لا تكشف لك، بل تغطى عنك تحتجب، ولا تخل بها، حتى يجعل الله فرجًا ومخرجًا، إما بزواجها وإلا بوجود بيت آخر تنتقل إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13493/حكم-بقاء-المراة-في-بيت-زوجها-بعد-انتهاء-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49302.mp3","categories":["الطلاق","قضايا المرأة"]},{"id":15034,"question":"أيضًا يقول: لقد حلفت لأحد الأصدقاء بالطلاق أنني أرسلت مبلغًا من النقود، وحددت ذلك المبلغ، وكنت متأكد من ذلك المبلغ، وكان عندي دليل فيه، وبعد ذلك أخذت أفتش في تلك الأوراق، فوجدت المبلغ ينقص عن التحديد، فهل يجب أن أراجع زوجتي أم أنها تطلق مني؟أفيدوني، وفقكم الله.","title":"حكم من حلف بالطلاق معتقدًا فعل شيء فبان خلافه","answer":"الجواب: إذا طلق الإنسان على شيء يعتقد أنه فعله، فإن الطلاق لا يقع، فإذا قال: عليه الطلاق أنه أرسل كذا وكذا ظانًا معتقدًا أنه أرسله، ثم بان أنه ما أرسله، أو بان أنه ناقص، فالطلاق لا يقع في هذه الحال، هذا هو الصحيح من أقوال العلماء، وهكذا لو قال: علي الطلاق إني رأيت زيدًا، أو علي الطلاق أن زيدًا قد قدم، وهو يظن ويعتقد أنه مصيب، ثم بان أنه غلطان، وأن هذا الذي قدم، أو مات ليس هو الرجل الذي أخبر عنه فإن طلاقه لا يقع؛ لأنه في حكم اليمين اللاغية، يعني: في حكم لغو اليمين؛ لأنه ما تعمد الباطل، إنما قال ذلك ظنًا منه واعتقادًا منه أنه مصيب، فلا يقع طلاقه، بل زوجته معه، هذا هو الصواب من قولي العلماء، نعم.","link":"https://binbaz.org.sa/fatwas/13531/حكم-من-حلف-بالطلاق-معتقدا-فعل-شيء-فبان-خلافه","audio":"","categories":["الأيمان والنذور","الطلاق"]},{"id":15114,"question":"أحمد عبدالله محمد علي جمعة، بعث يسأل ويقول: ما حكم الذين يحلفون بغير الله؟","title":"ما حكم الذين يحلفون بغير الله؟","answer":"الجواب: مثلما تقدم الحالف بغير الله من الشرك الأصغر، وعليهم التوبة إلى الله من ذلك، عليهم التوبة إلى الله من حلفه بغير الله، مثل: بالنبي، بالكعبة، بالأمانة، بشرف فلان، بحياة فلان، كله شرك، لكنه أصغر، فعليه التوبة إلى الله من ذلك، والندم، والإقلاع، والعزم ألا يعود في ذلك؛ لقوله ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وقال ﷺ: من كان حالفًا فلا يحلف إلا بالله، أو ليصمت وقال -عليه الصلاة والسلام-: من حلف بشيء دون الله فقد أشرك. فالواجب الحلف بالله وحده، فإذا حلف بغيره صار مشركًا شركًا أصغر، وقد يكون أكبر إذا قام في قلبه تعظيم هذا الشخص، مثل تعظيم الله، أو اعتقد أنه يصح أن يعبد من دون الله يكون شركًا أكبر، بهذه النية، وبهذا القصد. فالمقصود: إذا جرى على لسانه هذا شركًا أصغر، أما إذا كان يرى أنه يصلح أن يعبد، ويدعى من دون الله، ويحلف به، وأنه يرى أن هذا أهل لذلك، أو يقوم بقلبه تعظيمه، مثلما يعظم الله بالعبادة هذا شرك أكبر، لكن جنس الحلف بغير الله شرك أصغر، ما لم يكن في قلبه تعظيم المخلوق، مثل تعظيم الله، بحيث يرى أنه يصلح للعبادة، يدعى أو يستغاث به أو يصلى له أو يصام له أو نحو ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13614/ما-حكم-الذين-يحلفون-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49411.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":15132,"question":"هذه رسالة وردتنا من شخص متحير جدًا؛ لقرب عقد قرانه من رُبيِّع الجزار من أبناء مصر العربية، ومقيم في العراق، يقول: أرجو أن تعرض هذه الرسالة على من يتولى الإجابة في برنامج (نور على الدرب) يقول في رسالته:تعاركت مع رئيسي في العمل لبعض الأسباب؛ فقطع من راتبي خمسة أيام عقابًا لي، فأقسمت على أنه إذا أخذت الراتب ناقص فسوف أرسل برقية لرئيسه شكوى عليه، ولكنني لم أرسل برقية، وأخذت الراتب ناقصًا، والقسم هو: علي الطلاق بالثلاث من زوجتي إذا أخذت الراتب ناقصًا فسوف أرسل برقية لرئيسه، وكان هذا القسم أمام أربعة من زملائي بالعمل، وأخبر فضيلتكم بأنني عاقد قراني منذ ثمانية أشهر، ولم أدخل على زوجتي حتى الآن، فما هو حكم الدين؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق أن يرفع شكوى برئيسه ولم يفعل","answer":"الجواب: لا ينبغي للمؤمن أن يقسم بالطلاق، ولا بالحرام، فإذا كان ولا بد فليقل: والله لأفعلن كذا، أو بالله لأفعلن كذا، وأما إقسامه بالطلاق والتحريم فلا ينبغي، وأقل أحواله الكراهة، لكن هذا الذي أقسم بالطلاق أنه يرفع الأمر إلى رئيس من خصم عليه بعض راتبه، إن كان قصد حث نفسه على الرفع، وإلزامها بذلك؛ فهذا حكمه اليمين، وعليه كفارة اليمين، وهي: إطعام عشرة مساكين أو كسوتهم، يعشيهم أو يغديهم أو يعطيهم على نصف الصاع من التمر أو الأرز من قوت البلد مقداره كيلو ونصف، أو يكسوهم كسوة تجزئهم الصلاة من قميص أو إزار ورداء، ويكفي ذلك. أما إن كان هذا الذي أقسم بالطلاق أراد إيقاع الطلاق، وأنه إن لم يرفع فإن زوجته تطلق منه؛ أراد إيقاع الطلاق بها إن لم يرفع إلى رئيس هذا الموظف، فإن كان قصد الطلاق يعني: قصد إيقاع الطلاق إن لم يفعل، فإنه يقع به طلقة واحدة، هذا هو الراجح، إذا قال: عليه الطلاق بالثلاث، فالصواب من أقوال العلماء أنه يقع به طلقة واحدة، ويراجعها في العدة إذا كان ما قبلها طلقتان، إذا كان لم يطلق قبل هذا طلقتين؛ فإنه يقع بهذا طلقة واحدة، وله مراجعتها ما زالت في العدة، ويشهد شاهدين يقول لهما: أشهدكما أني راجعت امرأتي فلانة، ويكفي. أما إن كان ما أراد إيقاع الطلاق على زوجته، إنما أراد حث نفسه وإلزامها بالشكوى، ولم يرد إيقاع الطلاق بزوجته أبدًا، فهذا ليس فيه إلا كفارة اليمين، نعم.","link":"https://binbaz.org.sa/fatwas/13634/حكم-من-حلف-بالطلاق-ان-يرفع-شكوى-برىيسه-ولم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65705.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15191,"question":"هذه رسالة وردتنا من عبدالمجيد عبده أحمد، من الرياض، يسأل فيها عن الطلاق البدعي، يقول: السلام عليكم ورحمة الله وبركاته، وبعد:هل يقع الطلاق البدعي؛ كأن يطلق الرجل ثلاثًا دفعة واحدة، أو يطلق في طهر واقع فيه؟ وكيف نخرج حديث ابن عمر الذي أمره النبي ﷺ أن يراجع حينما طلق في طهر واقع فيه؟","title":"هل يقع الطلاق البدعي؟","answer":"الجواب: الطلاق البدعي يكون في الزمان، ويكون بالعدد، أما في العدد فهو أن يطلق ثلاثًا بكلمة واحدة، فيقول: طالق بالثلاث، أو بالكلمات يقول: طالق، ثم طالق، ثم طالق، أو أنت طالق، أنت طالق، أنت طالق، أو أنت طالق وطالق وطالق، أو تراك طالق، تراك طالق، تراك طالق، هذا بدعي. والسنة أن يطلق واحدة فقط، هكذا السنة، ولا يزيد عليها؛ لأنه قد يندم فيتراجع، ولا يغلق الباب على نفسه؛ ولأن الله شرع الطلاق واحدة بعد واحدة، لا دفعة واحدة؛ لأن الإنسان قد يغضب، وقد يبدو له حال، فيطلق، ثم يندم ويرى أنه قد غلط فيراجع إذا لم يطلق بالثلاث.  ولكن اختلف العلماء في إيقاع الثلاث بكلمة واحدة، هل يقع وتكون بائنًا من زوجها بذلك أم لا يقع به إلا واحدة، أم لا يقع بالكلية؟ الجمهور من أهل العلم على أنه يقع، وتكون به المرأة بائنًا، لا تحل لمطلقها إلا بعد زوج، وبعد إصابة، اتباعًا لـعمر حين قضى بذلك  وأرضاه. ويذهب بعض أهل العلم من التابعين ومن بعدهم وهو رواية عن ابن عباس -رضي الله تعالى عنهما-، ويروى عن علي والزبير بن العوام وعبدالرحمن بن عوف أنها تحسب واحدة رجعية؛ لما ثبت عن ابن عباس -رضي الله تعالى عنهما- أنه سأله أبو الصهباء فقال: \"يا ابن عباس ألم تكن الثلاث تجعل واحدة في عهد النبي ﷺ وعهد أبي بكر وفي أول خلافة عمر؟ فقال ابن عباس: بلى\" فاحتج هؤلاء العلماء بهذا الحديث على أن التطليق بالثلاث بكلمة واحدة يعتبر واحدة، وهذا رواية ثابتة عن ابن عباس أن هذا يعتبر واحدة إذا وقعت بكلمة واحدة. أما إذا وقعت بألفاظ مثل: أنت طالق، أنت طالق، أنت طالق، أوتراك طالق، وتراك طالق، تراك طالق، أو أنت طالق، وطالق، وطالق، وما أشبه ذلك، فهذا الذي أعلمه عن أهل العلم أنها تقع، تقع الثلاث كلها، وتبين بها المرأة بينونة كبرى، لا تحل لزوجها المطلق إلا بعد زوج وإصابة. ولا أعلم إلى وقتي هذا أحدًا من الصحابة، أو من التابعين صرح بأن هذا لا يقع به إلا واحدة، بل ظاهر ما سمعت وما قرأت أنه يقع كله تقع الثلاث كلها، وقد رأى شيخ الإسلام ابن تيمية -رحمه الله- أنه لا يقع إلا واحدة، كما لو طلق بالثلاث بكلمة واحدة، وجعل هذا مثل هذا، وجعل الطلاق الذي يقع بعد الأولى إنما يكون بعد نكاح أو بعد رجعة، أما إذا كان ألحقها الثانية والثالثة من دون نكاح ولا رجعة، أن هذا لا يقع، هذا كلامه -رحمه الله-، ولكني لا أعلم له أصلًا واضحًا يعتمد عليه من جهة النقل، وإن كان وجيهًا من جهة المعنى، لكن لا أعلم له أصلًا من جهة النقل؛ ولهذا فالذي أفتي به أنها تقع الثلاث على ظاهر ما نقل عن السلف الصالح في هذا، وإنما تعتبر الثلاث المجموعة طلقة واحدة إذا كان بلفظ واحد: أنت طالق بالثلاث، أو فلانة مطلقة بالثلاث، أو ما أشبه هذه الألفاظ على ما جاء عن ابن عباس إذا كان بكلمة واحدة. أما البدعي من جهة الزمان، يعني: من جهة حال المرأة، فهو إذا كانت في الحيض، أو في النفاس، أو في طهر جامعها فيه، هذا يقال له: طلاقًا بدعيًا، والأصل في ذلك ما رواه ابن عمر -رضي الله تعالى عنهما- أنه طلق امرأته وهي حائض، فبلغ ذلك النبي ﷺ بلغه عمر؛ فقال له النبي ﷺ قال لـعمر: مره فليراجعها، ثم ليمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شاء طلق وإن شاء أمسك قبل أن يمسها، فتلك العدة التي أمر الله أن تطلق لها النساء يعني في قوله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] وبهذا يعلم أن ابن عمر طلقها في الحيض لا في طهر جامعها فيه، بل طلق في الحيض، لا كما قال السائل، ابن عمر طلقها في الحيض، لا في طهر جامعها فيه، لكن الرسول ﷺ أرشده إلى أن الطلاق يكون في طهر لم يجامعها فيه، فهذا السنة، أو في حال حمل؛ ولهذا في اللفظ الآخر: ثم ليطلقها طاهرًا أو حاملًا فالطلاق السني، الطلاق السني أن يكون في حال طهر لم يجامعها فيه، أو في حال استبانة حملها، وظهور حملها، هذا هو الطلاق الشرعي. أما طلاقها وهي حائض أو نفساء، أو في طهر جامعها فيه، ولم يستبن حملها؛ فهذا يسمى طلاقًا بدعيًا في هذه الثلاثة المواضع: في حال النفاس، في حال الحيض، في حال طهر جامعها فيه، ولم يستبن حملها، هذه الثلاث الحالات الطلاق فيها بدعي، والحالان الأوليان سني: في حال كونها طاهرًا لم يجامعها في طهرها، وفي حال كونها حاملًا قد استبان حملها، فهاتان الحالتان الطلاق فيهما سني لا بدعي. أما الحالات الثلاث: حال الحيض، والنفاس، وحالة الطهر الذي جامعها فيه، هذه الطلاق فيها بدعي، لا يجوز للزوج أن يطلق في هذه الأحوال الثلاثة: لا في حال الحيض، ولا في حال النفاس، ولا في حال طهر جامعها فيه. وإذا أراد أن يطلق، يسألها ويقول: ما هي حالها، يستفصل ويتثبت في الأمر، ولا يطلق في حال الغضب؛ لأن الغضبان ضعيف البصيرة، فالذي ينبغي له ألا يطلق في حال الغضب، بل يتثبت في الأمر، ولا يعجل، ويتعوذ بالله من الشيطان في حال الغضب، ثم إذا عزم على الطلاق ينظر، فإن كانت في حيض، أو في نفاس، أو في طهر جامعها فيه، فلا يطلق، وهذا من رحمة الله؛ لأنه سبحانه يحب أن تبقى الزوجية، ويكره الطلاق كما في الحديث: أبغض الحلال إلى الله الطلاق. فمن رحمة الله أن ضيق طرق الطلاق، فجعله واحدة فقط على السنة، وجعله لا ينبغي أن يوقع إلا في حالين: في حال الطهر الذي لم يجامعها فيه، وحال ظهور حملها، أما في حال الحيض والنفاس، وفي حال الطهر الذي جامعها فيه؛ فينهى عن الطلاق، وهذا كله من تيسير الله، ومن تضييق مسالك الطلاق، وأوجه الطلاق؛ حتى تبقى الزوجية أكثر. ثم اختلف العلماء في هذا هل يقع الطلاق البدعي أم لا يقع؟ نحن اتضح الآن أنه محرم، ولا يجوز للزوج أن يقدم عليه، لكن هل يقع إذا أقدم وعصى ربه وفعل؟ هل يقع أم لا يقع؟ على قولين: أحدهما أنه يقع، مع الإثم، وهذا هو المشهور عند العلماء، وهو الذي فعله ابن عمر، فإنه أوقع على نفسه الطلقة لما طلق لما سئل قال: كيف وإن عجزت واستحمقت، قال: مه، قال: نافع وغيره إنه أوقعها، وإنه احتسبها، وروى البخاري: أنه احتسبت تطليقة عليه. وذهب جمع من أهل العلم إلى أن هذا الطلاق لا يحتسب، ولا يقع، وهو ما روي عن ابن عمر نفسه  إذ روى عنه محمد بن عبدالسلام الخشني الحافظ المشهور بإسناد جيد، أنه سئل ابن عمر عمن طلق زوجته وهي حائض هل يقع؟ قال: لا يقع. قال: لا يعتد به. وجاء هذا عن خلاس بن عمرو الهجري، وعن طاوس وآخرين أنه لا يقع؛ لأنه محرم فلا يقع؛ لأن ما نهى الله عنه فهو جدير بعدم الإيقاع؛ ولهذا البيع المنهي عنه مع أنه بيع فاسد، والنكاح مع العيب فاسد، لا يقع، فهكذا الطلاق المنهي عنه لا يقع، بخلاف الطلاق الثلاث فإنه يحتسب واحدة، تقع منه واحدة، كما تقدم إذا كان بلفظ واحد، وهذا القول الذي رآه بعض أهل العلم، وإن كان الخلاف المشهور، وخلاف الأكثر، فهذا القول أظهر في الدليل، وأقوى في الدليل أنه لا يقع؛ لكونه بدعيًاً على خلاف أمر الله، والله يقول: إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] وهذا طلقها في غير العدة فلا يقع طلاقه، بل يكون عملًا ليس عليه أمر النبي ﷺ، فيكون مردودًا، قال -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد يعني: فهو مردود، وهذا هو الأظهر، نعم.","link":"https://binbaz.org.sa/fatwas/13692/هل-يقع-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_660/nour_66002.mp3","categories":["الطلاق"]},{"id":15242,"question":"المستمع حفظالله الشعيبي، من اليمن، بعث يسأل ويقول: حدث في يوم من الأيام مشاجرة بيني وبين زوجتي في موضوع غسل ملابسي، وبعد ذلك تناوشنا مع بعض بغضب شديد، وفي ساعة هذا الغضب قلت: علي الطلاق ما تغسلي ملابسي مرة ثانية، ومن ذلك الوقت أغسل ملابسي في المغسلة خارج البيت، هل إذا أردت أن تغسل زوجتي ملابسي بعد اليمين؛ لأنني محتاج لذلك؟ هل إذا أردت أن تغسل ملابسي أن أتصرف بتصرف معين؟أرجو أن تفيدوني، جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق ألا تغسل زوجته ملابسه","answer":"الجواب: هذا يختلف بحسب نيتك، وما كان ينبغي لك التعجل بالطلاق، نصيحتي لكل زوج أن لا يتعجل بالطلاق، ولو غضب يقول: أعوذ بالله من الشيطان الرجيم، ولا يعجل في الطلاق أبدًا، ولو شدت عليه المرأة، ولو غضبت ولو طلبت لا يعجل في الطلاق، الشيطان يحضر ويزين لها ويزين لزوجها الطلاق. فالمشروع لك يا أخي، ولكل إنسان عدم العجلة في الطلاق حتى تطمئن، وحتى تعلم أن الطلاق أصلح لدينك ودنياك فلا بأس. ونصيحتي لكل امرأة أن تتقي الله، ولا تعجل في طلب الطلاق، ولا تؤذي زوجها في ذلك، ولا سيما إذا كان زوجها طيبًا صاحب دين، وصاحب صلاح، تتقي الله، ولا تعجل في الأمور، تصبر عليه، ولو أبغضها في بعض الأحيان، ولو حصل منه بعض الأذى في بعض الأحيان؛ لأن الزوج الصالح اليوم قليل، والزوجة الصالحة قليلة، فينبغي للمؤمن أن يتمسك بالزوجة الصالحة، ولا يعجل في الطلاق، ولو جرى منها بعض النقص، وهكذا المرأة إذا حصلت الزوج الصالح، فينبغي لها أن تتمسك به، وتحرص على البقاء معه، وأن لا تغضبه أبدًا، بل تتحمل، وتحرص على التحمل، فإذا غضبت تقول: أعوذ بالله من الشيطان الرجيم، وهي كذلك تقول: أعوذ بالله من الشيطان الرجيم، كرروا هذا عند الغضب ويزول الغضب؛ لما رأى النبي ﷺ شخصًا قد غضب واحمرت أوداجه من شدة الغضب قال: إني لأعلم كلمة لو قالها لذهب عنه ما يجد: أعوذ بالله من الشيطان الرجيم فأنت -يا أخي- كذلك استعذ بالله من الشيطان الرجيم. وهذا الطلاق الذي وقع منك يختلف بحسب نيتك، إن كنت نويت منعها من غسلها الملابس بعد ذلك، وأنك تستغني عنها، وأردت تخويفها وتهديدها بهذا الطلاق، فلك أن تسمح عنها، وتكفر عن يمينك، له حكم اليمين، إذا كنت قصدك منعها من الغسل غضبًا عليها، ولم ترد فراقها إن غسلت ثيابك، إنما أردت تهديدها بهذا، والشره عليها والغضب عليها، ولم ترد فراقها بهذا لو غسلت، فهذا حكمه حكم اليمين، وعليك كفارة اليمين، وهي إطعام عشرة مساكين، إطعام عشرة، كل واحد يعطى نصف الصاع، تمر أو رز كيلو ونصف كل واحد، أو كسوة على قميص قميص، أو عتق رقبة، فمن عجز يصوم ثلاثة أيام. أما إن كنت أردت الطلاق، أردت إيقاع الطلاق عليها إن غسلت يقع طلقة واحدة، إذا كنت أردت إيقاع الطلاق إن غسلت ثيابك، فإنها إذا غسلتها يقع عليها طلقة واحدة وتراجعها، تقول: اشهد يا فلان وفلان أني مراجع زوجتي، تشهد اثنين من الطيبين من جيرانك أو أصحابك أنك مراجعها، هكذا السنة إذا كان ما قبلها طلقتان، إذا كنت ما طلقتها قبلها طلقتين، أما إذا كان قبلها طلقتين ما تصلح إلا بعد زوج، لكن إذا كنت ما طلقتها قبلها طلقتين، وأنت أردت الطلاق إذا غسلت ثيابك تكون طلقة واحدة، وتراجعها بإشهاد اثنين، تقول: اشهد يا فلان وفلان أني راجعت زوجتي فلانة، ما دامت في العدة. أما إن كنت ما أردت الطلاق مثلما تقدم، وإنما أردت منعها والغضب عليها وتهديدها حتى لا تغسل ثيابك مرة أخرى من أجل غضبك، ولم ترد إيقاع الطلاق، ولا فراقها، ولكن أردت المنع، فهذا حكمه حكم اليمين، وعليك كفارة اليمين، وهي إطعام عشرة مساكين غداء أو عشاء، أو تعطي كل واحد نصف الصاع كيلو ونصف كل واحد من التمر أو الحنطة أو غيرهما من قوت البلد، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13739/حكم-من-حلف-بالطلاق-الا-تغسل-زوجته-ملابسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49705.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15255,"question":"هذه رسالة من السائل سليم محمد، من جمهورية مصر العربية، يقول: حصل بيني وبين زوجتي خلاف في يوم من الأيام، وقد قلت لها وأنا في حالة غضب: أنت خالصة، وقد كررت هذا القول مرتين. فإنني أرجو التكرم بالإفادة هل يعتبر هذا طلاقًا أم لا؟","title":"حكم من قال لزوجته: أنت خالصة","answer":"الجواب: إذا كنت أردت الطلاق فهو طلاق؛ لأن هذا كناية، يسميه العلماء: كناية، فإذا كنت أردت الطلاق بقولك: أنت خالصة، يكون طلاقًا واحدًا طلقة واحدة، والمكرر مثل ذلك إذا كنت أردت طلاقًا ثانيًا تكون طلقة ثانية.  أما إن كنت أردت التأكيد لكلامك الأول، ما أردت طلاقًا ثانيًا، أردت التأكيد أو التفهيم للمرأة فلا يقع إلا واحدة، بالكلام الأول إذا كنت أردت الطلاق. أما إن كنت أردت طلاقًا ثاني بالتكرار فيقع عليها طلقتان، وإن كنت ما أردت الطلاق، قلت: أنت خالصة، ما أردت الطلاق وإنما أردت يعني إزعاجها أو تكديرها وتحزينها أو خالصة من كذا وكذا غير الطلاق ما أردت الطلاق فأنت على نيتك؛ لأن الرسول ﷺ يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فأنت على نيتك. وإذا كان ما قبل هذا طلاق فلك مراجعتها إن كنت أردت طلقة واحدة فقط، وأردت بالتكرار التأكيد أو الإفهام، فلا يقع إلا واحدة، ويبقى لها طلقتان، ولك مراجعتها ما دامت في العدة، والسنة أن تشهد شاهدين، السنة أن تشهد شاهدين من العدول، تقول لهما: اشهدا أني راجعت زوجتي فلانة، ما دامت في العدة، فإن لم تحصل مراجعة وهي في العدة، فلا بد من عقد جديد برضاها بمهر جديد، بشروطه المعتبرة شرعًا، إذا خرجت من العدة، وأنت لم تراجع لم تحل لك إلا بنكاح جديد بشروطه المعتبرة شرعًا. أما إن كان قبل هذا طلاق إن كان قبلها طلقتان انتهى الأمر، وأنت أردت الطلاق بقولك: أنت خالصة، فهذا تمام الثلاث فلا تحل لك إلا بعد زوج، زوج شرعي يطؤها، وإن كان قبله طلقة وأنت أردت بقولك: أنت خالصة أنت خالصة طلقتين تمت الثلاث فلا تحل لك إلا بعد زوج شرعي، زوج شرعي يدخل بها ويطؤها. وإن أشكل عليك المقام تسأل أهل العلم عندك العلماء الفقهاء تسألهم عما أشكل عليك، نعم.\nالمقدم: إنما يصح لو راجعها بينه وبينها بالقول أو بالفعل؟\nالشيخ: يصح، لكن السنة أن يشهد شاهدين. أما الرجعة بقوله إذا راجعها أو وطئها بنية الرجعة كفى، لكن السنة أن يشهد شاهدين على قوله: إني راجعتها، نعم.\nالمقدم: إنما على العموم يفهم من هذا أن جميع الكنايات تفتقر إلى اقتران النية؟ الشيخ: لا بد من النية. المقدم: نعم، إذا لم يكن هناك نية فلا يعتبر. الشيخ: نعم، لا بد من النية، الألفاظ التي غير صريحة في الطلاق: أنت خالصة، أنت ما أنت في ذمتي، أنت خارجة من ذمتي، أو ما أشبه ذلك، نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13771/حكم-من-قال-لزوجته-انت-خالصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67407.mp3","categories":["الطلاق"]},{"id":15256,"question":"هذه في البداية رسالة موجهة من السائل عبدالرحمن علي ناجي اليماني، يقول: رجل طلق زوجته ثلاث طلقات، ثم استرجعها، وعاشت معه عدة سنين، ثم طلقها مرة أخرى ثلاث طلقات، فبقيت في منزل والدها شهرين، ثم استرجعها بعد ذلك بدون عقد جديد، ومن غير أن يتزوجها رجل آخر، فهل استرجاعه لها صحيح بهذا الشكل، أم أن عشرتهم محرمة؟أفيدونا، بارك الله فيكم.","title":"حكم من طلاق زوجته ثلاث طلقات ثم أرجعها وتكرار ذلك","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه المسألة مسألة عظيمة وخطيرة، ونرى أن على السائل أن يراجع مع المرأة ووليها القاضي الذي لديه في اليمن، حتى ينظر القاضي في الموضوع، ويحل المشكل، ويخبرهم بما يجب -إن شاء الله-، ولا يكفي أن يجاب عنها من طريق الإذاعة، نعم.","link":"https://binbaz.org.sa/fatwas/13750/حكم-من-طلاق-زوجته-ثلاث-طلقات-ثم-ارجعها-وتكرار-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67401.mp3","categories":["الطلاق"]},{"id":15260,"question":"هذه رسالة من السائل سليم محمد، من جمهورية مصر العربية، يقول: حصل بيني وبين زوجتي خلاف في يوم من الأيام، وقد قلت لها وأنا في حالة غضب: أنت خالصة، وقد كررت هذا القول مرتين. فإنني أرجو التكرم بالإفادة هل يعتبر هذا طلاقًا أم لا؟","title":"حكم من قال لزوجته: أنت خالصة","answer":"الجواب: إذا كنت أردت الطلاق فهو طلاق؛ لأن هذا كناية، يسميه العلماء: كناية، فإذا كنت أردت الطلاق بقولك: أنت خالصة، يكون طلاقًا واحدًا طلقة واحدة، والمكرر مثل ذلك إذا كنت أردت طلاقًا ثانيًا تكون طلقة ثانية.  أما إن كنت أردت التأكيد لكلامك الأول، ما أردت طلاقًا ثانيًا، أردت التأكيد أو التفهيم للمرأة فلا يقع إلا واحدة، بالكلام الأول إذا كنت أردت الطلاق. أما إن كنت أردت طلاقًا ثاني بالتكرار فيقع عليها طلقتان، وإن كنت ما أردت الطلاق، قلت: أنت خالصة، ما أردت الطلاق وإنما أردت يعني إزعاجها أو تكديرها وتحزينها أو خالصة من كذا وكذا غير الطلاق ما أردت الطلاق فأنت على نيتك؛ لأن الرسول ﷺ يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فأنت على نيتك. وإذا كان ما قبل هذا طلاق فلك مراجعتها إن كنت أردت طلقة واحدة فقط، وأردت بالتكرار التأكيد أو الإفهام، فلا يقع إلا واحدة، ويبقى لها طلقتان، ولك مراجعتها ما دامت في العدة، والسنة أن تشهد شاهدين، السنة أن تشهد شاهدين من العدول، تقول لهما: اشهدا أني راجعت زوجتي فلانة، ما دامت في العدة، فإن لم تحصل مراجعة وهي في العدة، فلا بد من عقد جديد برضاها بمهر جديد، بشروطه المعتبرة شرعًا، إذا خرجت من العدة، وأنت لم تراجع لم تحل لك إلا بنكاح جديد بشروطه المعتبرة شرعًا. أما إن كان قبل هذا طلاق إن كان قبلها طلقتان انتهى الأمر، وأنت أردت الطلاق بقولك: أنت خالصة، فهذا تمام الثلاث فلا تحل لك إلا بعد زوج، زوج شرعي يطؤها، وإن كان قبله طلقة وأنت أردت بقولك: أنت خالصة أنت خالصة طلقتين تمت الثلاث فلا تحل لك إلا بعد زوج شرعي، زوج شرعي يدخل بها ويطؤها. وإن أشكل عليك المقام تسأل أهل العلم عندك العلماء الفقهاء تسألهم عما أشكل عليك، نعم.\nالمقدم: إنما يصح لو راجعها بينه وبينها بالقول أو بالفعل؟\nالشيخ: يصح، لكن السنة أن يشهد شاهدين. أما الرجعة بقوله إذا راجعها أو وطئها بنية الرجعة كفى، لكن السنة أن يشهد شاهدين على قوله: إني راجعتها، نعم.\nالمقدم: إنما على العموم يفهم من هذا أن جميع الكنايات تفتقر إلى اقتران النية؟ الشيخ: لا بد من النية. المقدم: نعم، إذا لم يكن هناك نية فلا يعتبر. الشيخ: نعم، لا بد من النية، الألفاظ التي غير صريحة في الطلاق: أنت خالصة، أنت ما أنت في ذمتي، أنت خارجة من ذمتي، أو ما أشبه ذلك، نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13771/حكم-من-قال-لزوجته-انت-خالصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67407.mp3","categories":["الطلاق"]},{"id":15272,"question":"هذه رسالة من المرسل (ح. ع) من عمان، الأردن، يقول: عندي امرأة، وقد تشاجرت معها، وحصل خلاف، وغضبت غضبًا شديدًا، فأنا رجل عصبي المزاج، شديد الإثارة، لا أتحمل المشاكل، وحلًا لهذه المشكلة قلت ونطقت للزوجة: يا فلانة، أنت طالق، وكلمة أخرى أنت طالق، وأنا في حيرة من أمري، فكلما تعصيني هي أنطق هذه الكلمات، وصدرت مني عدة مرات ربما أكثر من ثلاث مرات، فما حكم الإسلام في ذلك؟","title":"حكم طلاق شديد الغضب","answer":"الجواب: إن كان الطلاق وقع في غضب شديد، يعني: أغلق عليه مقصده وشعوره، ولم يتملك نفسه، ولم يستطع حبسها عن الطلاق لشدة الغضب، وشدة النزاع والكلمات الجارحة من الزوجة، فإن الطلاق لا يقع على الصحيح، وقد اختلف العلماء في ذلك، لكن الصحيح أن الطلاق لا يقع في شدة الغضب. والغضب أنواع ثلاثة:\nغضب يزيل الشعور، ويكون صاحبه كالمجنون، ما يبقى عنده شعور، فهذا لا يقع طلاقه عند جميع أهل العلم.\nالغضب الثاني: يشتد معه الغضب بسبب النزاع الطويل، أو الكلمات الجارحة من الزوجة أو غيرها حتى لا يملك نفسه، وحتى لا يستطيع التغلب على أعصابه، بل ينطق بالطلاق كالمكره كالمدفوع، فهذا لا يقع طلاقه. الحال الثالث: أن يكون غضبًا عاديًا، ليس معه شدة، بل غضب عادي، فهذا يقع الطلاق فيه عند الجميع. فالسائل أعلم بنفسه، السائل هذا أعلم بنفسه، إن كان اشتد معه الغضب شدة كبيرة، حتى لم يستطع حبس نفسه عن ذلك، بل أزعجه الغضب، ودفعه دفعًا شديدًا، حتى نطق بغير اختيار بسبب كلماتها الجارحة، أو سبها له، ولعنها له أو لأبويه، أو وصفها له بأوصاف قبيحة أثارته حتى اشتد معه الغضب، فإنه في هذه الحال لا يقع طلاقه، أما في الغضب العادي الذي يغضب الإنسان عند العادة بسبب كلمات ما تناسب، أو عمل ما يناسب، فهذا يقع فيه الطلاق عند أهل العلم، نعم.","link":"https://binbaz.org.sa/fatwas/13783/حكم-طلاق-شديد-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67505.mp3","categories":["الطلاق"]},{"id":15275,"question":"هذه رسالة مقدمة من المستمع حسن بن حسن، يمني الجنسية، مقيم بالقويعية، يقول: أنا كنت متزوج امرأة فحصل بيننا خلاف، فطلقتها المرة الأولى، فردت إلي، وجاء أيضًا سبب ثانٍ فطلقتها للمرة الثانية، فردت لي، وفي المرة الثالثة جاءت بأقوال كذب تقول: إني عملت لها سمًا وسحرًا، فغضبت لهذا الموضوع فطلقتها برغم أن لي منها ابن وبنت، ولنا حوالي أربع سنوات منذ فراقنا، ولم تتزوج هي حتى الآن، وأنا الآن أريدها وهي تريدني، فهل يصح لي أن أرجعها وماذا أفعل كي يتحقق ذلك؟","title":"حكم من طلق امرأته الثالثة وهو غضبان","answer":"الجواب: عليه أن يحضر عند فضيلة قاضي القويعية، مع المرأة ووليها حتى يسجل كلام الجميع، وهل كان غضبه شديدًا في المرة الأخيرة بأسباب كلامها القبيح أم لا؟  ثم ننظر في الأمر، يحضر به لدينا وننظر في الأمر -إن شاء الله-، عند قاضي القويعية، ما دام في القويعية يحضر عند فضيلة القاضي، فإما أن يفتيه، وإما أن يكتب كلامه وكلام المرأة، وكلام وليها، ويبين لنا غضبه، هل كان شديدًا أم لا؟ وأسبابه، ثم ننظر في الأمر -إن شاء الله-، ثم يبلغ ذلك إما من طريق الإذاعة، وإلا من طريق الكتابة، نعم.","link":"https://binbaz.org.sa/fatwas/13792/حكم-من-طلق-امراته-الثالثة-وهو-غضبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67510.mp3","categories":["الطلاق"]},{"id":15279,"question":"هذه رسالة من المرسل (ح. ع) من عمان، الأردن، يقول: عندي امرأة، وقد تشاجرت معها، وحصل خلاف، وغضبت غضبًا شديدًا، فأنا رجل عصبي المزاج، شديد الإثارة، لا أتحمل المشاكل، وحلًا لهذه المشكلة قلت ونطقت للزوجة: يا فلانة، أنت طالق، وكلمة أخرى أنت طالق، وأنا في حيرة من أمري، فكلما تعصيني هي أنطق هذه الكلمات، وصدرت مني عدة مرات ربما أكثر من ثلاث مرات، فما حكم الإسلام في ذلك؟","title":"حكم طلاق شديد الغضب","answer":"الجواب: إن كان الطلاق وقع في غضب شديد، يعني: أغلق عليه مقصده وشعوره، ولم يتملك نفسه، ولم يستطع حبسها عن الطلاق لشدة الغضب، وشدة النزاع والكلمات الجارحة من الزوجة، فإن الطلاق لا يقع على الصحيح، وقد اختلف العلماء في ذلك، لكن الصحيح أن الطلاق لا يقع في شدة الغضب. والغضب أنواع ثلاثة:\nغضب يزيل الشعور، ويكون صاحبه كالمجنون، ما يبقى عنده شعور، فهذا لا يقع طلاقه عند جميع أهل العلم.\nالغضب الثاني: يشتد معه الغضب بسبب النزاع الطويل، أو الكلمات الجارحة من الزوجة أو غيرها حتى لا يملك نفسه، وحتى لا يستطيع التغلب على أعصابه، بل ينطق بالطلاق كالمكره كالمدفوع، فهذا لا يقع طلاقه. الحال الثالث: أن يكون غضبًا عاديًا، ليس معه شدة، بل غضب عادي، فهذا يقع الطلاق فيه عند الجميع. فالسائل أعلم بنفسه، السائل هذا أعلم بنفسه، إن كان اشتد معه الغضب شدة كبيرة، حتى لم يستطع حبس نفسه عن ذلك، بل أزعجه الغضب، ودفعه دفعًا شديدًا، حتى نطق بغير اختيار بسبب كلماتها الجارحة، أو سبها له، ولعنها له أو لأبويه، أو وصفها له بأوصاف قبيحة أثارته حتى اشتد معه الغضب، فإنه في هذه الحال لا يقع طلاقه، أما في الغضب العادي الذي يغضب الإنسان عند العادة بسبب كلمات ما تناسب، أو عمل ما يناسب، فهذا يقع فيه الطلاق عند أهل العلم، نعم.","link":"https://binbaz.org.sa/fatwas/13783/حكم-طلاق-شديد-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67505.mp3","categories":["الطلاق"]},{"id":15284,"question":"هذان سؤالان من المستمعة (س. ع) من الطائف، العقيق، تقول في سؤالها الأول: أنا امرأة متزوجة، وذات مرة حصلت مشاجرة بيني وبين زوجي، وتدخل والده، وأخذ يضربه، فقال -وهو في تلك الحالة-: أنت طالق ثلاثًا ورددها، ووقتها كانت بي العادة الشهرية، وبعد ذلك علمت أن الطلاق والمرأة حائض لا يقع، وبعد مضي سنة من هذا جاء مرة إلى البيت وهو سكران، فتشاجرت معه، وقد كان يبدو على وجهه الغضب، فقال لي: أنت طالق، ورددها مرتين، وبعد أن أفاق أحس بالندم والحسرة، فذهبنا إلى أحد القضاة وقال: إن طلاق السكران لا يقع، وبعد مضي سنتين من هذه حصل أيضًا شجار وتدخل أهلي في الموضوع، فقلت له: إني لا أريدك، ولكن أريد طلاقي منك، فخرجنا ولم يتلفظ بطلاق ووقتها كان في كامل وعيه، وبعد مضي نصف شهر بعث بورقة مكتوب فيها: طلاق السنة، فقط ولم يحدد، وعلى ذلك شهود، وكنت وقتها حاملًا، فبقيت بعيدة عن بيته حتى وضعت حملي، وبعد مرور سنة طلب الرجوع إليه، وأعلن لي توبته واستقامته، فهل يصح لي الرجوع إليه بعد هذا كله، فأنا راغبة في العودة إليه حفاظًا على نفسي وعلى طفلتي من الضياع؟علمًا أن والدي يرفض العودة إليه، ومع ذلك لا يساعدني في الإنفاق على نفسي وعلى ابنتي، فأنا بنفسي أنفق من مالي حيث أسكن في بيت بمفردي؟أفيدوني، بارك الله فيكم.","title":"حكم من طلق وزوجته حائض ثم وهو سكران ثم وهي حامل","answer":"الجواب: نرى أن تحضري معه لدى الحاكم الشرعي لديكم، الذي ينظر في مثل هذه المسائل، حتى ينظر في الموضوع، وإذا تاب توبة صادقة، واستقام فلا مانع من الرجوع إليه، وإذا أبى والدك الرجوع إليه، فالقاضي يحكم بما يرى في هذا، ويكون الوالد عاضلًا، ويمكن أن يزوجك أحد إخوتك إذا كان لك إخوة بدلًا من أبيك إذا رأى القاضي ذلك، أو يحضره القاضي وينصحه ويشير عليه حتى يزوجك والدك.  المقصود: أن هذا الطلاق الأخير يعتبر طلقة واحدة، طلاق السنة يعتبر طلقة واحدة، لا تمنع من رجوعك إليه بعقد جديد. أما الطلاق الأول في حال الحيض، والطلاق الأول في حال السكر إذا كان ليس معه عقله لا يقعان على الصحيح من أقوال العلماء، الصحيح من أقوال العلماء: أن السكران الذي زال عقله لا يقع طلاقه في حال السكر، وزوال العقل كالمجنون والمعتوه. وكذلك في حال الحيض والنفاس، لا يقع على الصحيح؛ لما ثبت في الصحيح من حديث ابن عمر -رضي الله تعالى عنهما- أن النبي ﷺ لما أخبره عمر أن ابن عمر طلق امرأته وهي حائض، أمره أن يردها، ثم يمسكها حتى تحيض، ثم تطهر، وبعد ذلك يطلقها إذا شاء، أو يمسكها، وقال -عليه الصلاة والسلام-: تلك العدة التي أمر الله أن تطلق لها النساء يعني: في قوله سبحانه: فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ[الطلاق:1]. فالحاصل: أن الطلقة الأولى والثانية إذا كان الأمر على ما قلت لا تقعان، والطلقة الأخيرة طلاق السنة تقع واحدة،\nوله الرجوع إليك بعقد جديد، بعد وضع الحمل، إذا كان لم يراجع مدة الحمل، فله الرجوع إليك بعقد جديد، وعلى والدك أن يزوجه عليك إذا كان صالحًا إذا كان مسلمًا يصلي، أما إذا كان لا يصلي فلا يزوج، ولا كرامة، لكن إذا كان مسلمًا بعيدًا عن المكفرات -عن أسباب الكفر- فالوالد يزوجك إياه لرغبتك ولوجود الطفلة معك، فإذا أبى والدك من دون علة ترفعين الأمر إلى الحاكم والحاكم ينظر في الأمر القاضي يعني.  نسأل الله للجميع التوفيق والهداية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/13779/حكم-من-طلق-وزوجته-حاىض-ثم-وهو-سكران-ثم-وهي-حامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68102.mp3","categories":["الطلاق"]},{"id":15288,"question":"هذان سؤالان من السائل (أ. ش) من الرياض، يقول: قال رجل لصديق له: علي الطلاق ألا تشتري الثلاجة والغسالة إذا عزمت على الزواج، يقصد أنه هو الذي سيشتريهما ويهديهما إليه، فهل يجوز أن يعطيه قيمتهما مقدمًا نقدًا؟","title":"حكم من حلف بالطلاق أن يشتري لصديقه شيئًا ثم أعطاه قيمته","answer":"الجواب: الذي يظهر أنه لا حرج في ذلك، إذا شراها بنفسه، أو سلم له القيمة، اشتراها، إذا كان مقصوده مساعدته بالثمن، وليس مقصوده نفس الشراء، إنما المقصود أن يساعده في الثمن، فإذا شراها بنفسه، أو بوكيله، أو شراها صاحب الحاجة، وسلم له ثمنها، فالأمر في هذا واسع، ولا يقع عليه شيء بذلك؛ لأن طلاقه قد حصل به المقصود؛ لأن الشرط المطلوب قد حصل، نعم.\nالمقدم: إنما لو حصل وسبقه هذا الشخص واشتراهما؟\nالشيخ: إذا كان المقصود أن يساعده بالثمن هذا المقصود، وسلم له الثمن فإنه قد وفى بيمينه.\nالمقدم: حتى لو اشتراه.\nالشيخ: حتى لو اشتراها له.\nالمقدم: سؤاله الآخر يقول: رجل عليه نذر منذ عام ألف وثلاثمائة وأربعة وتسعين هجري.....\nالشيخ: ويتعلق بالسؤال الأول أمر آخر قد يخفى على بعض الناس، وهو أنه إذا كان مقصوده بالطلاق منعه من الشراء، وحثه على قبول الهدية، وليس قصده فراق زوجته إن لم يسمح له بالشراء، فإن هذا الطلاق في حكم اليمين، فلو فرضنا أن الرجل ما سمح واشتراها هو، ولم يقبل الثمن فإن الطلاق لا يقع، وعليه كفارة اليمين إذا كان مقصوده نفعه بهذا الشيء، وحثه على قبول الهدية، وليس مقصوده فراق زوجته إن لم يقبل، وإنما المقصود مقصود اليمين يعني: حث الرجل على قبول الهدية، أو قبول الثمن، وليس المقصود فراق أهله إن لم يقبل، فهذا له حكم اليمين، فلو لم يقبل صاحب الزواج شراء الشخص للثلاجة والغسالة، أو لم يقبل الثمن، فإن الرجل لا يقع على زوجته طلاق؛ لأنه ليس المقصود إيقاع الطلاق، المقصود: حث الرجل على قبول الهدية هذه، ولكن يكفيه كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13780/حكم-من-حلف-بالطلاق-ان-يشتري-لصديقه-شيىا-ثم-اعطاه-قيمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67503.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15290,"question":"هذه رسالة من المرسل (ح. ع) من عمان، الأردن، يقول: عندي امرأة، وقد تشاجرت معها، وحصل خلاف، وغضبت غضبًا شديدًا، فأنا رجل عصبي المزاج، شديد الإثارة، لا أتحمل المشاكل، وحلًا لهذه المشكلة قلت ونطقت للزوجة: يا فلانة، أنت طالق، وكلمة أخرى أنت طالق، وأنا في حيرة من أمري، فكلما تعصيني هي أنطق هذه الكلمات، وصدرت مني عدة مرات ربما أكثر من ثلاث مرات، فما حكم الإسلام في ذلك؟","title":"حكم طلاق شديد الغضب","answer":"الجواب: إن كان الطلاق وقع في غضب شديد، يعني: أغلق عليه مقصده وشعوره، ولم يتملك نفسه، ولم يستطع حبسها عن الطلاق لشدة الغضب، وشدة النزاع والكلمات الجارحة من الزوجة، فإن الطلاق لا يقع على الصحيح، وقد اختلف العلماء في ذلك، لكن الصحيح أن الطلاق لا يقع في شدة الغضب. والغضب أنواع ثلاثة:\nغضب يزيل الشعور، ويكون صاحبه كالمجنون، ما يبقى عنده شعور، فهذا لا يقع طلاقه عند جميع أهل العلم.\nالغضب الثاني: يشتد معه الغضب بسبب النزاع الطويل، أو الكلمات الجارحة من الزوجة أو غيرها حتى لا يملك نفسه، وحتى لا يستطيع التغلب على أعصابه، بل ينطق بالطلاق كالمكره كالمدفوع، فهذا لا يقع طلاقه. الحال الثالث: أن يكون غضبًا عاديًا، ليس معه شدة، بل غضب عادي، فهذا يقع الطلاق فيه عند الجميع. فالسائل أعلم بنفسه، السائل هذا أعلم بنفسه، إن كان اشتد معه الغضب شدة كبيرة، حتى لم يستطع حبس نفسه عن ذلك، بل أزعجه الغضب، ودفعه دفعًا شديدًا، حتى نطق بغير اختيار بسبب كلماتها الجارحة، أو سبها له، ولعنها له أو لأبويه، أو وصفها له بأوصاف قبيحة أثارته حتى اشتد معه الغضب، فإنه في هذه الحال لا يقع طلاقه، أما في الغضب العادي الذي يغضب الإنسان عند العادة بسبب كلمات ما تناسب، أو عمل ما يناسب، فهذا يقع فيه الطلاق عند أهل العلم، نعم.","link":"https://binbaz.org.sa/fatwas/13783/حكم-طلاق-شديد-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67505.mp3","categories":["الطلاق"]},{"id":15299,"question":"أيها الإخوة، أول رسالة نستعرضها اليوم وردت إلينا من المستمع عمر محمود، من جمهورية مصر العربية الشرقية، يقول: لي زوجة طيبة مطيعة وقورة، وهي تذهب إلى العمل في غير ما تبرج ولا زينة، ولكني أنا لست راضٍ عن عملها هذا، ولا أريد منها الذهاب، واختلفنا على ذلك، وحلفت عليها بالطلاق بقولي: علي الطلاق ما أنت ذاهبة إلى العمل مرة أخرى.الشيخ: علي...؟المقدم: علي الطلاق ما أنت ذاهبة إلى العمل مرة أخرى، وكررت هذه الكلمة مرتين، وفي الثالثة قلت: علي الطلاق بالثلاث ما أنت ذاهبة إلى الشغل في السنة القادمة، وكان ذلك في جلسة واحدة، وكان غرضي ونيتي هو المنع من العمل، وكانت هي في ذلك الوقت في إجازة وضع لمدة ثلاثة أشهر، وكنت أريد أن نستفيد من مرتبها خلال هذه الإجازة في تسديد ديوننا، وبعدها لن تذهب إلى العمل، ولم تذهب إلى العمل في هذه المدة، وكانوا يرسلون إليها مرتبها، وبعدما انتهت مدة إجازتها، وحان وقت عودتها إلى العمل، ناقشني أحد أقاربي في ذلك بقصد رغبته في ذهابها إلى العمل، فقلت له: علي الطلاق ما هي ذاهبة، وكررت هذا اللفظ مرة أخرى، وكان ذلك أيضًا في جلسة واحدة، وكان غرضي ونيتي هذه المرة هو الطلاق إن هي ذهبت إلى العمل.الشيخ: أعد.المقدم: نعم.الشيخ: أعد.المقدم: يقول: وبعدما انتهت مدة إجازتها، وحان وقت عودتها إلى العمل، ناقشني أحد أقاربي في ذلك، أي: يريد أن تذهب إلى العمل، فقلت له: علي الطلاق ما هي ذاهبة الشغل، وكررت هذا اللفظ مرة أخرى، وكان ذلك في جلسة واحدة، وكان غرضي ونيتي هذه المرة هو الطلاق إن هي ذهبت إلى العمل.وفي اليوم المحدد لعودتها إلى العمل قلت لها: إن ذهبت الشغل فلن تكوني زوجة لي، كتأكيد ليميني السابق، ولكنها ذهبت إلى العمل، فما الذي يأمرني به ديني في هذه الحالة؟ وهل هذه الأيمان طلاقًا رجعيًا أم طلاقًا بائنًا لا رجعة فيه، مع العلم أنها الآن تعيش معي، وتتمسك بالبقاء معي، وترفض مغادرة منزلي، والذهاب إلى منزل أبيها.","title":"حكم الحلف بالطلاق بنية المنع وتكراره بنية الطلاق","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الواجب على المرأة السمع والطاعة لزوجها فيما أباح الله، لا في المعصية، وكونه السائل منعها من الذهاب إلى العمل هذا ليس بمعصية، بل أمر له حق فيه، فالواجب عليها أن تسمع وتطيع له في ذلك، وألا تذهب إلى العمل، وقد نوى في الطلاق الأول المنع فقط، فيكون عليه في ذلك كفارة يمين بسبب ذهابها إلى العمل؛ لأنه لم يقصد إلا منعها فقط، وهذا هو الصواب من قولي العلماء فيما إذا علق الزوج الطلاق على أمر يقصد منعًا منه، أو الحمل عليه، أو التصديق أو التكذيب، هذا هو المختار عند جمع من أهل العلم.  أما طلاقه الأخير فقد أراد به إيقاع الطلاق وقد كرره مرتين.\nوالجواب عن ذلك: إن كان أراد به التكرار إيقاع الطلاق في المرة الثانية كالأولى، وقد وقع عليها طلقتان، وبقي لها واحدة، وله مراجعتها ما دامت في العدة، وإن كان لم يرد إيقاع الطلاق في المرة الثانية حين كرر، وإنما أراد تأكيد الكلام السابق، أو إفهامها فإنه لا يقع بذلك إلا طلقة واحدة، ويبقى لها طلقتان، وله مراجعتها ما دامت في العدة؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى وقد نوى في الطلاق الأخير إيقاع الطلاق فيقع ما قال، والله  ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13801/حكم-الحلف-بالطلاق-بنية-المنع-وتكراره-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67601.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15301,"question":"سؤاله الثاني يقول: لو أن شخصًا غضب من زوجته، وقال لها: لا أريد أن أراك، وسأتخلص منك، وسأعاملك مثل أختي، وكانت نيته تهديدها فقط، وخاصة لو قال لها: أنت بالنسبة لي مثل أختي، فما الحكم في ذلك؟ هل هي طالق بالنسبة له؟علمًا بأنه يجهل كلمة أنت مثل أختي، أو لا أريد أن أراك، ويعتقد فقط أن المرأة لا تطلق إلا بحلف بالطلاق بلفظه، فما الحكم في ذلك؟ وهل هي طالق؟ وماذا يفعل إذا كانت طالقًا ليستردها؟","title":"حكم قوله لزوجته: لا أريد أن أراك، وأنت مثل أختي","answer":"الجواب: هذا الكلام وأشباهه ليس بطلاق؛ إذا قال: لا أريدك، أو لا أحب أن أراك، أو سوف أطلقك، هذا وعيد، سوف أطلقك، هذا وعيد من باب الوعيد، أو لا أحب أن أراك، هذا يبين كراهته لها، وليس هذا بطلاق.\nالمقدم: ولا كناية؟\nالجواب: ولا كناية، أما إذا قال: أنت علي مثل أختي، أو مثل أمي، هذا يسمى ظهارًا، إذا كان أراد بذلك تحريمها أو أراد بذلك كراهتها، وإنزالها منزلة محارمه، أما إذا كان أراد بذلك إكرامها، وأنها مثل أخته في المحبة، يعني: يحبها كأخته ويقدرها تقديرًا هذا ما يصير ظهار. أما إذا قال: أنت مثل أختي، أو مثل أمي، أو خالتي قصده تحريمها عليه، وأنها لا تحل له، هذا معناه الظهار، يعني معناه: أنها حرام عليه، فعليه كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، وإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا كل صاع بين اثنين من قوت البلد من حنطة أو أرز أو نحو ذلك، قبل أن يمسها، قبل أن يجامعها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13815/حكم-قوله-لزوجته-لا-اريد-ان-اراك-وانت-مثل-اختي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68204.mp3","categories":["الطلاق","الظهار"]},{"id":15320,"question":"هذا سؤال من المستمع: أحمد خليل الشريف، من جمهورية السودان، مدرس باليمن الشمالي، يقول: حدثت خمس مشاكل مع زوجتي منذ حوالي ثمان سنوات، وعلى إثرها تركت البيت إلى بيت أبيها، وطالت المدة، وطلبتها من أهلها وأقاربها؛ وذلك لحاجتي إليها؛ ولعدم اتساع المشاكل كلما طالت المدة، وقد حان موعد عيد الفطر، وكنت أريد أن تكون زوجتي في بيتها، وعلى أمل أن تعود، وعندما جاءني خبر بأنها لن تعود حلفت يمينًا، قلت: علي الطلاق إذا لم ترجع قبل العيد، أو قبل الشهر؛ تكون مطلقة، واتصلت بعد اليمين بأهلها حتى تحضر قبل الميعاد، لكن والدها رفض ذلك، ولم تحضر، وكذلك زوجتي لم تسمع بهذه اليمين إلا بعد أن تصالحنا، وذهبت بعدها إلى أحد المشايخ لرد اليمين، ولم أتذكر بماذا أفتاني هذه مرة.والمرة الأخرى حلفت يمينًا بالطلاق على زوجتي، قلت: علي الطلاق إذا سلمت على فلان تكوني مطلقة، أريد منعها من السلام على هذا الإنسان الذي لا أستريح له، ولا سيما قد يجمعنا مكان واحد؛ لأنه قريب، ولكنها سلمت عليه.يقول: وفي المرة الثالثة على إثر خلاف أرادت الخروج من البيت، وكنت أريد منعها من الخروج، وتهديدها حتى لا تخرج، فيكون هناك مشاكل أكثر، فحلفت يمين طلاق، وقلت في نفس اليمين: تكوني محرمة علي مثل أمي وأختي إذا خرجت من باب البيت، فرجوتها ألا تخرج من باب البيت، ولكنها خرجت، وسألت عن هذا أيضًا، فقيل: أطعم ستين مسكينًا، وفعلت، وقال: لك طلقة واحدة.وفي المرة الرابعة سمعت زوجتي تقول لأحد أبنائي: (يا ابن الكلب) فحلفت يمينًا، قلت: علي الطلاق لو قلت ذلك مرةً ثانية تكوني طالقة، ولم أسمعها قالت شيئًا، وإنما قالت لي بعد هذا اليمين: أنا سهوت وقلت: (يا أولاد الكلب) لأولادي، علمًا بأنني حلفت هذه اليمين، وهي لم تتطهر بعد من العادة الشهرية.وفي المرة الخامسة على إثر سوء تفاهم معها هددتها بالطلاق إذا لم تكف عن الصياح، ولكنها لم تكف مرة تلو المرة، وزادت من صياحها، فغضبت غضبًا شديدًا، وخرج الكلام بعد مقاومة مني له مندفعًا بالغضب قلت: علي الطلاق أنت مطلقة في ذلك الوقت، وتكوني محرمة علي مثل أمي وأختي، وبعدها تيقنت أنني خسرت أولادي وزوجتي، غير أني من شدة الغضب لم أتذكر أنني قلت لها: تكوني محرمة علي مثل أمي وأختي، وأسأل؛ هل بالغضب الشديد لا يقع الطلاق؟ وما شدته؟ وهل من الضرورة ألا أتذكر شيئًا مما قلته على الإطلاق؟ وهل هذا اليمين يقع؟ رغم أني قلته نتيجة لغضب شديد، فماذا ترون في هذه الحالات الخمس؟أفيدوني بارك الله فيكم، هل بقيت لي فرصة للعيش مع زوجتي أم لا؟","title":"مسائل في الحلف بالحرام والطلاق","answer":"الجواب: على كل حال ما ينبغي للسائل أن يتساهل بهذا الأمر، ويكثر من الطلاق، ويهدد بالطلاق، بل ينبغي له أن يحفظ لسانه، وهكذا كل مسلم، ينبغي له أن لا يتساهل في الطلاق، بل ينبغي له أن يحفظ لسانه من الطلاق، وأن يهدد بغير الطلاق، ويتوعد بغير الطلاق، وينصح زوجته عند المخالفة بما يرى من النصيحة، أما الطلاق فينبغي أن يكون بعيدًا؛ لأن ذلك قد يضر بحاله مع زوجته، وقد يفضي إلى فراقها، فينبغي له ألا يهدد بالطلاق، وألا يستعمله مهما أمكن. وأما ما وقع منه في هذه المسائل الخمس؛ فالطلاق الذي أراد به تهديدها، ومنعها، وما أراد إيقاع الطلاق حين قال لها: إن جاء العيد، أو خرج الشهر قبل أن تحضري؛ فأنت طالق، إن كان أراد بهذا إيقاع الطلاق؛ وقع طلقة، وإن كان ما أراد بذلك إيقاع الطلاق، وإنما أراد منعها من البقاء عند أهلها؛ حتى تأتي قبل العيد، وأراد بهذا تخويفها من مغبة هذه اليمين فإنه لا يقع شيء، وعليه كفارة يمين. وهكذا منعها من السلام على الشخص المعين، إذا كان أراد منعها كما قال، ولم يرد إيقاع الطلاق؛ فإن الطلاق لا يقع، وعليه كفارة يمين عن سلامها له، إذا كان أراد منعها من السلام، ولم يرد إيقاع الطلاق. وهكذا منعها من الخروج من البيت، إذا كان أراد عدم خروجها، وإنما أراد تخويفها بالطلاق حتى لا تخرج، ثم خرجت، فعليه كفارة يمين، في هذا كله، أما إذا كان أراد إيقاع الطلاق؛ فإنها تقع طلقة. وهذا طلاق متعدد، والمسألة تحتاج إلى عناية، ونظر في موضوعه، فإن كانت الزوجة موجودة في الرياض؛ فنرى أنه يحضر عندي هو وزوجته؛ حتى ننظر في أمرهما جميعًا بالتفصيل، وحتى تكون الفتوى على أمرٍ واضح. والشيء الذي فعلته ناسيةً؛ لا يقع به شيء، إذا كانت كلمت من منعها من تكليمه، سهوًا ناسيةً، فلا يقع شيء بذلك، ولا عليك كفارة، فيما إذا كانت فعلت المحلوف عليه ناسيةً -ساهية-؛ لأن الله يقول سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا[البقرة:286]. وهكذا إذا اشتد الغضب، ولم يملك نفسه.......، الغضب شديدًا؛ لأنها خالفته، ونازعته شديدًا، وتكلمت عليه كلامًا يعني: سبب شدة غضبه، وعدم استطاعته قهر نفسه؛ فإنه بهذه الحالة لا يقع الطلاق، فإنه في هذه الحال يشبه حال من لا عقل له عند شدة الغضب؛ لأنه لا يملك نفسه، ولا يستطيع قهرها بسبب الغضب الشديد، والنزاع الشديد، أو الكلام الخبيث الذي قالت له؛ حتى اشتد غضبه، فإنه لا يقع به الطلاق. وقولها: يا ابن الكلب، أو يا بني الكلب؛ إذا كانت ساهيةً؛ فإنه لا يقع شيء بذلك، ولا يلزمه كفارة يمين بذلك، فينبغي له أن يتوقف عن الطلاق، ويحذر هذا الاستعمال الذي قد يفضي به إلى فراق أهله، وقد يسبب مشاكل عليه، فينبغي له أن يحذرها. ينبغي لك -أيها السائل- أن تحذر مثل هذا، وإذا حضرت مع زوجتك عندي؛ فهو يكون أولى، حتى نسألها عما قلت، ونسألك عما قلت، وحتى يحضر معها وليها كأخيها، أو أبيها؛ حتى ننهي الموضوع على طريقة واضحة، وبعد سؤالكما جميعًا والولي عن كل ما وقع، هذا يكون أحوط وأولى.\nالمقدم: السائل مقيم في اليمن علي أي حال.\nالشيخ: إذا كان في اليمن فعليه أن يتصل بالعلماء هو وزوجته ووليها، أحسن، حتى يفصل له العلماء ما وقع فيه، يتصل ببعض العلماء هناك أهل الفقه، من القضاة، ونحوهم من أهل العلم، أهل البصيرة، فيخبرهم بكل ما وقع منه، حتى يكون على بينه، وعلى بصيرة في فتواه، وفيما يراه أهل العلم -إن شاء الله- البركة والخير، وقد بيَّنا له ما يلزم حسب ما قد عرفنا من سؤاله. المقدم: ماذا عن مظاهرته، التي يقول: تكوني مثل أمي وأختي؟ الشيخ: هذا عليه كفارة الظهار، عليه أن يكفر إذا كان يستطيع الصيام، يصوم شهرين متتابعين، فإن كان ما يستطيع الصيام؛ يطعم ستين مسكينًا، عليه أن يطعم ستين مسكينًا.\nالمقدم: هو حسب سؤاله يقول: ذكر هذا الكلام مرتين، في المرة الأولى يقول: سألت عنه وكفرت بإطعام ستين مسكينًا، وقيل لي: لك طلقة.\nالشيخ: تجزئه، إذا كان لا يستطيع الصيام، يجزيه إطعام ستين مسكينًا، إذا كان لا يستطيع الصيام، ويقع عليها طلقة إذا كان ما أراد منعها، إنما أراد إيقاع الطلاق يكون عليه طلقة، أما إن كان أراد منعها، وكفها عن هذا الشيء، ولم يرد إيقاع الطلاق، وإنما أراد تخويفها، وتحذيرها، وكفها عن ذلك؛ فإن عليه كفارة يمين. المقدم: حتى في الظهار؟ الشيخ: مع كفارة الظهار، عن الطلقة يعني، عن الطلقة التي أوقعها، نعم. المقدم: إذًا معنى هذا بقي عليه كفارة ظهار واحدة؛ لأنه ذكر أنه ظاهر مرتين. الشيخ: نعم، نعم، وكفارة اليمين عن الطلقة إذا كان أراد منعها وكفها، نعم.","link":"https://binbaz.org.sa/fatwas/13832/مساىل-في-الحلف-بالحرام-والطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_683/nour_68302.mp3","categories":["الطلاق","الظهار"]},{"id":15327,"question":"هذا سؤال من المستمع محمد زاهي الحربي من حائل، قرية النحيتية، يقول: طلقت امرأتي، وقلت لها: إذا وافقت خيرًا فاستخيريه، أي: إذا طلبك رجل فتزوجيه، وأعطيتها ورقتها، فهل يمكن لي أن أعود لها مرة ثانية؟أفيدونا، رحمكم الله.","title":"حكم قول الرجل لزوجته: إذا وافقت خيرًا فاستخيري","answer":"الجواب: إذا كان الطلاق بهذا اللفظ، فإنه يقع به واحدة، إذا قال لها: إذا وافقك خير فوافقيه، أو إذا خطبك زوج فتزوجي، أو ما أشبهها ذلك، أو أنت مطلقة، أو أنت طالق، أو ما أشبه ذلك، فإن هذا يعتبر واحدة؛ طلقة واحدة فقط، فله أن يراجعها ما دامت في العدة، بأن يشهد شاهدين بأنه راجعها، يقول: قد راجعت امرأتي، أو ارتجعت امرأتي، أو رددت امرأتي، وما أشبهه من الألفاظ الدالة على عوده إليها، والأفضل أنه يشهد شاهدين عدلين، يقول: اشهدا بأني راجعت زوجتي، ما دامت في العدة، يعني: ما دامت لم تحض ثلاث حيضات إذا كانت تحيض، وإن كانت لا تحيض فعدتها ثلاثة أشهر. فإذا راجعها قبل مضي الأشهر الثلاثة حلت، وصارت زوجة له، أما إن كانت قد اعتدت يعني: مضى عليها بعد الطلاق ثلاث حيضات إن كانت تحيض، أو مضى عليها ثلاثة أشهر إن كانت لا تحيض، كالعجوز الكبيرة، والبنت الصغيرة، فإنها حينئذٍ تكون أجنبية، ولا تحل له إلا بعقد جديد، ..... جديد، كسائر الخطباء، وسائر الخطاب الذين يخطبونها، لا تحل إلا بنكاح جديد، بشروطه المعتبرة شرعًا، نعم.","link":"https://binbaz.org.sa/fatwas/13824/حكم-قول-الرجل-لزوجته-اذا-وافقت-خيرا-فاستخيري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67702.mp3","categories":["الطلاق"]},{"id":15331,"question":"هذه أول رسالة في حلقتنا اليوم، من المستمع: حسين علي محمد اليماني، مقيم بالرياض، يقول: حصل بيني وبين زوجتي خصام، فاشتد غضبي، فقلت لها: جعلتك كمثل أمي وكرائمي، وقد سألت بعض العلماء في ذلك، فقالوا: يجب عليك كفارة ظهار، ولكني لم أستطع فعل شيء منها، فقد أطعمت ستة مساكين، فقط، ثم اتصلت بزوجتي بعد ذلك، وهي الآن عندي، فما رأيكم في هذا؟أفيدوني، وفقكم الله.","title":"حكم من جامع أهله قبل الوفاء بكفارة الظهار","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالقول للمرأة: أنت علي حرام، أو مثل أمي، أو مثل أختي.. أو نحو ذلك، هذا أمر لا يجوز، لأن الله -جل وعلا- حرم المظاهرة منها، وتشبيهها بالأم، أو بالأخت، وذكر سبحانه أنه منكر من القول، وزور، فلا يجوز للمسلم أن يقول لزوجته: أنت مثل أمي، أو أنت حرام علي كأمي، أو كأختي، أو كظهر أمي، كل هذا لا يجوز، والواجب عليه أن يحفظ لسانه عن مثل هذا، والله سبحانه قال: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا[المجادلة:3] الآية، فبيَّن -جل وعلا- أن المظاهر له أحكام، فيجب على المؤمن أن يتقيد بحكم الله -جل وعلا-، ولا يتساهل في الأحكام. فإذا قال هذا الكلام، وأحب الرجوع إليها، والعود إليها؛ فإن عليه كفارة بينها ربنا  في قوله : وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا ذَلِكُمْ تُوعَظُونَ بِهِ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ ۝ فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِنْ قَبْلِ أَنْ يَتَمَاسَّا فَمَنْ لَمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ذَلِكَ لِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ[المجادلة:3-4] . فالمؤمن يتقيد بحكم الله ورسوله، ولا يعجل، ولا يتساهل، وإذا حصل غضب أو مشاجرة؛ فالواجب عليه أن يتثبت في الأمور، ويتعوذ بالله من الشيطان، ولا يعجل في أمرٍ يضره، فإن الإقدام على ما حرم الله من جملة المعاصي التي تضر العبد، وتسبب غضب الله عليه ، والطلاق كذلك قد يفضي به إلى ما لا تحمد عقباه، فلا يعجل في الطلاق، بل ينبغي له التثبت في الأمور، وعدم العجلة، وأن يتعوذ بالله من الشيطان عند حدوث النزاع، والخصام. وهذا الرجل الذي حرم زوجته يلزمه عتق رقبة، يعني: إما عبد، وإما أمة، فإذا لم يتيسر ذلك؛ فإنه يصوم شهرين متتابعين، قبل أن يتصل بها -قبل أن يجامعها- فإن عجز عن ذلك أطعم ستين مسكينًا، لا ستة، بل عليه أن يطعم ستين مسكينًا، كما أمر الله بهذا ، وإطعامهم؛ بكونه يعشيهم، أو يغديهم، أو يعطي كل واحد نصف صاع من قوت البلد من تمر، أو أرز، أو حنطة، أو ذرة، من قوت بلده، قبل أن يمسها، وهذا معنى: مِنْ قَبْلِ أَنْ يَتَمَاسَّا[المجادلة:4] يعني: من قبل أن يتصل بها ويجامعها. والسائل قد أخطأ في جماعه لها قبل أن يكمل الكفارة، فعليك -أيها السائل- أن تمتنع منها، وأن تكف عن جماعها؛ حتى تكفر الكفارة الواجبة، وإذا كنت لا تستطيع صيام شهرين متتابعين؛ فإنك تكمل الإطعام، أطعمت ستة، بقي عليك أربعة وخمسون، عليك أن تطعم أربعة وخمسين مسكينًا، مع الستة حتى يكون الجميع ستين مسكينًا، تعطي كل واحد نصف صاع، وهو كيلو ونصف تقريبًا من الحنطة، أو من التمر، أو من الأرز، أو من قوت بلدك، إن كان بلدك عندكم فيه الذرة، فمن الذرة، حتى تكمل الستين، ومقدار هذا بالوزن كيلو ونصف تقريبًا، فإذا كملت ذلك؛ جاز لك أن تأتيها، وعليك التوبة إلى الله مما فعلت، عليك التوبة إلى الله سبحانه من قربانك إياها، عليك التوبة إلى الله ، فإن قربانك إياها قبل الكفارة؛ معصية، فعليك أن تتوب إلى الله  من ذلك، وعليك أن تكمل الكفارة بإطعام أربعة وخمسين مسكينًا، كل واحد يعطى نصف الصاع من التمر، أو غيره من قوت البلد، هذا إذا كنت لا تستطيع الصيام، وبعد هذا كله تحل لك زوجتك، وعليك التوبة إلى الله، والندم على ما فعلت، والاستغفار، كسائر الذنوب، نعم.\nالمقدم: لو أراد أن يطعمهم كما تفضلتم بأن يغديهم، أو يعشيهم فهل يجوز له أن يطعمهم على دفعات مثلًا؟\nالشيخ: ما في بأس، لا حرج أن يفرقهم.\nالمقدم: ليس بلازم، ما هو بلازم أن يطعمهم دفعة واحدة؟ الشيخ: ما هو بلازم أن يجمعهم جميعًا لو غدى هؤلاء في وقت عشرة، وعشرين في وقت آخر، أو خمسة، أو ستة حتى يكملهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13825/حكم-من-جامع-اهله-قبل-الوفاء-بكفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_683/nour_68301.mp3","categories":["الطلاق","الظهار"]},{"id":15333,"question":"هذا سؤال من المستمع: إبراهيم أحمد شاويش من السودان، يقول: أنا رجل متزوج، وقد حصلت بيني وبين زوجتي خصومة، مما أغضبني أشد الغضب، جعلني لا أشعر بما أفعله، فقلت لها: أنت طالقة، فقالت لي: اشهد يا فلان من الحاضرين، فقلت: تشهد علي عشر طلقات، ولكن من حولي من الناس بعد هدوئي قالوا لي: إني قلت لها: أنت طالقة عشر مرات، فأرجو إفادتي، هل يقع طلاق بهذا أم لا؟علمًا أنني كما أسلفت كنت وقتها في أشد الغضب.","title":"حكم من طلق وهو في حالة غضب شديد","answer":"الجواب: مثلما تقدم، إذا كان في أشد الغضب؛ لا يقع الطلاق، إذا كان هناك أسباب توجب شدة الغضب حتى كان شبه المجنون، شبه عادم الشعور، إذا اشتد به الغضب، وعظم عليه الأمر حتى ما ملك نفسه، ولا استطاع ملك نفسه، ولا قهرها، بسبب سوء مخاصمتها له، وكلامها عليه من سب، وتعيير، ونحو ذلك؛ فإنه لا يقع الطلاق في أصح أقوال العلماء، يكون حكمه حكم طلاق المجنون والمعتوه، نعم.\nنسأل الله السلامة، نعم.","link":"https://binbaz.org.sa/fatwas/13836/حكم-من-طلق-وهو-في-حالة-غضب-شديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_683/nour_68303.mp3","categories":["الطلاق"]},{"id":15342,"question":"هذا سؤال من المستمع (م. ح. ش. ع) من الأردن، عمان، المفرق، يقول: أنا شخص عقدت على فتاة عقد زواج رسمي، وفي يوم من الأيام غضبت من الأهل عندما كانوا يتكلمون معي في عمل يخص مخطوبتي، فتلفظت بكلمة: طالقة، ورددتها ثلاث مرات، دون أن تعلم هي، وإلى الآن لم تعلم، فهل وقع الطلاق هنا وما نوعية الطلاق؟أفيدوني، جزاكم الله خيرًا.","title":"حكم طلاق المرأة قبل الدخول بها","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل، فإنه يقع لها طلقة واحدة فقط، إذا كان لم يدخل بها، إنما عقد، ولكن لم يدخل بها، فإنه يقع عليها طلقة واحدة، وله العود لها بنكاح جديد، بعقد جديد، من غير حاجة إلى زوج جديد، بل نكاح جديد، يكفي، والطلاق الثاني والثالث لا يلحقها؛ لأن المرأة إذا لم يدخل بها لا يلحقها إلا طلقة واحدة، تبينها بينونة صغرى، والطلاق الثاني والثالث لا يلحق؛ لأنها ليست في عدة، وله العود إليها بنكاح جديد إذا رضيت بذلك كخاطب من الخطاب.","link":"https://binbaz.org.sa/fatwas/13849/حكم-طلاق-المراة-قبل-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_678/nour_67804.mp3","categories":["الطلاق"]},{"id":15343,"question":"هذه في البداية رسالة موجهة من المستمع من الكويت (م. ف. ي) يقول:تشاجرت أنا وزوجتي قبل مدة، فقلت لها: طالق؛ لأجل أن تسكت، فقالت كلمة ثانية، وكنت غاضبًا منها جدًا، ومن كلامها، فقلت لها مرة أخرى: طالق، ومكثت مدة، لا أتكلم معها، وأما اليوم فإني أحيانًا أتكلم معها في أغراض البيت، أو إذا لزم شيء للأولاد، وغير هذا لا يوجد شيء، فما الحكم في هذا؟أفيدونا، ولكم الشكر.","title":"حكم من طلق زوجته مرتين ولم يراجعها وتعيش في بيته","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالله -جل وعلا- شرع لعباده الطلاق؛ ليتخلص كل واحد من الزوجين، من صاحبه إذا لم تستقم الحال، ولم يحصل ما يقيم العلاقة على الوجه المرضي، وجعله سبحانه ثلاثًا، يراجع بعد الأولى، وبعد الثانية، وليس له الرجعة بعد الثالثة، وحرم إيقاعه بالثلاث جميعًا، بل يكون واحدة بعد واحدة، كما قال -جل وعلا-: الطَّلاقُ مَرَّتَانِ فَإمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ [البقرة:229]. فإذا طلقها طلقة واحدة، فله مراجعتها، ما دامت في العدة، ثم إذا راجعها بقيت على حالها زوجة شرعية، كحالها الأولى، فإن طلقها الثانية فله مراجعتها أيضًا من دون عقد نكاح كما بعد الطلقة الأولى. فأنت -أيها السائل- طلقتها طلقتين، فلك المراجعة، ما دامت في العدة، ما دامت لم تحض ثلاث حيضات بعد الطلقة الأولى، ولا تزال زوجة لك حتى تطلقها الطلقة الثالثة، هذا إذا كان الغضب خفيفًا، أما إذا كان الغضب شديدًا حيث حصل بينكما تنازع شديد، وكلمات جارحة منها شديدة، حتى اشتد غضبك، ولم تملك نفسك للإمساك عن الطلاق، فهذا الطلاق حينئذٍ عند الغضب الشديد لا يقع على الصحيح من أقوال العلماء، والغضب ثلاثة أحوال، الناس في الغضب لهم ثلاثة أحوال:\nإحداها: أن يشتد الغضب حتى يفقد الشعور، ويكون كالمجنون والمعتوه، فهذا لا يقع طلاقه عند جميع أهل العلم؛ لأنه بمثابة المجنون والمعتوه زائل العقل، فهذا لا يقع طلاقه إذا زال عقله بشدة الغضب، ولم يملك نفسه، ولم يضبط ما يقول، ولم يحفظ ما يقول. الحال الثاني: أن يشتد معه الغضب، ولكنه يفهم ما يقول ويعقل، إلا أن الغضب اشتد معه كثيرًا، ولم يستطع أن يملك نفسه لطول النزاع، أو المسابة والمشاتمة أو المضاربة، فاشتد الغضب لأجل ذلك، فهذا فيه خلاف بين أهل العلم، والأرجح أنه لا يقع أيضًا، فإن كان غضبك من هذا القبيل فالطلاق غير واقع. وإن كان غضبك من الحال الثالثة وهي الغضب الخفيف الذي يحصل منه تكدر من الزوج وكراهة لما وقع من المرأة، ولكنه لم يشتد معه شدة كثيرة تمنعه من التعقل والنظر في نفسه، بل هو غضب عادي خفيف، فهذا يقع معه الطلاق عند جميع أهل العلم، لكن إذا كانت المرأة في حال حيض عند الطلاق، أو في حال نفاس، أو في حال طهر جامعتها فيه، فالجمهور من أهل العلم يرون وقوع الطلاق مع الإثم؛ لأن الطلاق يجب أن يكون في حال طهر لم تجامعها فيه، أو في حال حمل، هذا هو الطلاق الشرعي، أن تكون المرأة حاملًا، أو في طهر لم تجامعها فيه. فإن كانت في طهر جامعتها فيه، أو في حال حيض، أو نفاس، فقد اختلف العلماء في ذلك، فجمهور أهل العلم يرون أنه يقع الطلاق، مع الإثم، والقول الثاني: أنه لا يقع؛ لأنه طلاق غير شرعي، ولم يصادف الحال التي شرع الله فيها الطلاق، فلم يقع، وهذا القول هو الأرجح من حيث الدليل؛ لما ثبت في الصحيح من حديث عبدالله بن عمر -رضي الله تعالى عنهما- \"أنه طلق امرأته وهي حائض، فأنكر عليه النبي ذلك -عليه الصلاة والسلام-، وأمره بالمراجعة، وأن يمسكها حتى تحيض، ثم تطهر\" يمسكها أول حتى تطهر من حيضها الذي طلقها فيه، ثم تحيض، ثم تطهر بعد ذلك، ثم إن شاء طلق، وإن شاء أمسك. فهذا ظاهر بأن طلاقه لم يقع كما قاله جمع من أهل العلم؛ لكونه أمره بالمراجعة، ثم بالإمساك حتى تطهر، ثم تحيض ثم تطهر، ثم قال: فإن شئت فأمسكها، وإن شئت فطلقها قبل أن تمسها، فتلك العدة التي أمر الله أن تطلق لها النساء يعني: في قوله سبحانه: فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] فهذا يدل على أن الطلاق في طهر جامعها فيه، أو في حال حيض أو نفاس طلاق غير شرعي، وطلاق في العدة التي لم يأمر الله بالطلاق فيها، وهذا هو المختار، وإن كان خلاف قول الجمهور. فأنت أعلم بنفسك، وما جرى عليك حين الطلاق، فإن كان الغضب قد اشتد معك شدة واضحة قوية لطول النزاع بينكما، وسوء الكلام الذي صدر منها، حتى لم تملك نفسك، أو كانت في طهر جامعتها فيه، أو في حيض، فالطلاق غير واقع، وإن كانت في حال حمل، أو في حال طهر لم تجامعها فيه، وكان الغضب ليس بشديد، بل غضب عادي، فإن الطلاق واقع، قد مضى عليها طلقتان، ولك مراجعتها ما دامت في العدة، فإذا طلقتها بعد هذا مرة ثالثة حرمت عليك حتى تنكح زوجًا غيرك. والواجب على المؤمن أن يتقي الله في كل شيء، وأن ينظر في الأمر إذا أراد الطلاق، لا يعجل في الطلاق، بل ينظر، فإن كانت الزوجة مستقيمة، والحال مستقيمة، فلا وجه للطلاق، ولا ينبغي الطلاق، وهكذا إذا أمكن التعديل وأمكن العلاج فلا تنبغي العجلة في الطلاق، ثم إذا عزم على الطلاق فلينظر هل هي في طهر لم يجامعها فيه، أو في حال حمل فلا بأس بالطلاق، إذا كانت في طهر لم يجامعها فيه، أو في حال حمل، أما إن كانت في طهر جامعها فيه، أو في حال حيض، أو في نفاس، فلا يجوز الطلاق. فالواجب على المؤمن أن ينظر في هذه الأمور، وألا يعجل في طلاقه لأهله، بل ينظر ويتأمل وينظر في العواقب ولا يعجل، ثم ينظر في حال المرأة هل هي حبلى، أو في طهر لم يجامعها فيه، أو في حالة أخرى، حتى يطلق على بصيرة، وحتى يكون طلاقه طلاقًا شرعيًا موافقًا لما جاء به النص، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13844/حكم-من-طلق-زوجته-مرتين-ولم-يراجعها-وتعيش-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_678/nour_67801.mp3","categories":["الطلاق"]},{"id":15347,"question":"هذا سائل للبرنامج الحقيقة أرسل بمجموعة من الأسئلة، أبو محمد، سوداني، ومقيم بعفيف، يقول في سؤاله هذا: رجل حلف بالطلاق ألا يفعل شيئًا، ولكنه فعل ذلك ماذا عليه؟ علمًا بأنه عندما حلف أراد بذلك أن يلزم نفسه بعدم فعل ذلك الشيء، فأفيدونا، مأجورين.","title":"حكم من حلف بالطلاق ألا يفعل شيئًا معينًا ثم فعله","answer":"الجواب: إذا حلف بالطلاق بأن قال مثلًا: عليه الطلاق ألا يكلم فلانًا قصده الامتناع منه، أو عليه الطلاق ألا يسافر، ثم سافر، ومقصوده الامتناع ليس قصده سوى ذلك، فهذا فيه كفارة اليمين، ليس فيه إلا كفارة يمين، حكمه حكم اليمين؛ لأن قصده الحث والمنع؛ فيكون عليه كفارة اليمين. ومثله لو قال: عليه الطلاق إن فعلت زوجتي كذا وكذا. قصده منعها، أو عليه الطلاق إن فعل فلان كذا، قصده منعه، فهذا حكمه حكم اليمين، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13850/حكم-من-حلف-بالطلاق-الا-يفعل-شيىا-معينا-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56620.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15372,"question":"محمد حامد من دمشق، يقول: فضيلة الشيخ، أمد الله بعمركم على طاعة الله، سؤالي هو كالتالي: بأنني اعتدت على أن أحلف يمينًا عندما أغضب وأزعل من أي شيء، سواء في العمل أو في المنزل، وأقول: علي الطلاق، أو علي الحرام بأن هذا كذا وكذا، وصار هذا اليمين عادة في يومي وليلتي أردده باستمرار، حاولت التخلص منه، ولكنني لم أستطع، فبماذا تنصحونني؟ وما حكم هذا اليمين يا سماحة الشيخ؟","title":"توجيه لمن يكثر الحلف بالطلاق والحرام","answer":"الجواب: نوصيك بالحذر من هذا، وعدم اعتياده، نوصيك بترك اليمين بالطلاق والتحريم، هذا الذي نوصيك به، وإذا فعلت ذلك وأنت صادق، فليس عليك شيء، قلت: علي الطلاق إن فلان سافر، علي الطلاق إني ما فعلت كذا، وأنت صادق لا شيء عليك، أو علي الحرام إني ما أفعل كذا، ولم تفعله، أو علي الحرام إن فلان قد سافر، أو علي الحرام أني ما أكلت كذا، وأنت صادق لا شيء عليك. أما إذا قلته تريد المنع، تقول: علي الطلاق ما تقومين يا فلانة من كذا، علي الطلاق ما تروحين لأهلك، وأنت قصدك منعها، فهذا حكمه حكم اليمين، عليك كفارة اليمين، أو علي الحرام إني ما أكل هذا الشيء وأكلته، قصدك الامتناع منه، فعليك كفارة اليمين، أو عليك الحرام ما تزور فلانًا، ثم زرته، وأنت قصدك الامتناع من زيارته، عليك كفارة اليمين والحمد لله، وعليك الاستغفار من ذكر التحريم، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/13875/توجيه-لمن-يكثر-الحلف-بالطلاق-والحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15389,"question":"سؤاله الثاني يقول: رجل طلق زوجته وراجعها قبل تمام العدة، ومكثوا حوالي عشر سنوات، والآن حصل بينهما نزاع، وكان الطلب من الزوجة للطلاق، والحث عليه في طلب الطلاق أكثر من خمس مرات أمام الجيران، فقام الزوج وأخذ ورقة، وكتب فيها: أنا فلان بن فلان قد طلقت زوجتي فلانة بنت فلان طلاقًا شرعيًا، لا رجعة فيه، وأشهد رجلين على ذلك، وبعد مضي شهر واحد حضر الجيران، وأصلحوا بينهما في الإرجاع، فأرجعها، فهل هذا الإرجاع صحيح؛ لأنه قال: لا رجعة فيه؟الشيخ: أعد السؤال، أعده.المقدم: السؤال يقول: رجل طلق زوجته وراجعها قبل تمام العدة، ومكثوا حوالي عشر سنوات، والآن حصل بينهما نزاع، وكان الطلب من الزوجة للطلاق، والحث عليه في طلب الطلاق أكثر من خمس مرات أمام الجيران، فقام الزوج وأخذ ورقة وكتب فيها: أنا فلان بن فلان قد طلقت زوجتي فلانة بنت فلان طلاقًا شرعيًا لا رجعة فيه، وأشهد رجلين، وبعد مضي شهر واحد حضر الجيران وأصلحوا بينهما في الإرجاع فاسترجعها، فهل هذا الإرجاع صحيح؛ لأنه قال في تلك الورقة: لا رجعة فيه؟أفتوني، شكر الله لكم.","title":"حكم مراجعة الزوجة بعد قول الزوج طلاق لا رجعة فيه","answer":"الجواب: هذا فيه تفصيل، إذا كان الطلاق الأول طلقة واحدة التي راجعها فيه طلقة واحدة، ثم طلقها هذا الطلاق، فإن هذا الطلاق يحسب طلقة واحدة أيضًا، تكون ثانية، ولو قال فيه: لا رجعة فيه، فإن الصواب أنه في حكم الواحدة فقط، ولو قال فيه: بائنًا، أو قال: لا رجعة فيه، أو قال: بالثلاث بلفظ واحد، فإن الصواب الذي نفتي به، وهو الثابت عن النبي ﷺ من حديث ابن عباس: «أن الطلاق كان يجعل طلاق الثلاث يجعل واحدة على عهد النبي ﷺ وعلى عهد الصديق أبي بكر، وعلى عهد عمر  في أول خلافته» يعني: طلاق الثلاث بلفظ واحد، هذا هو الصواب أنه يجعل واحدة تضاف إلى الطلقة الأولى، فيكون الجميع ثنتين، ويكون له المراجعة، ويبقى لها واحدة، ما دامت في العدة، ما دامت حبلى، ما دامت في العدة، فإنه يراجعها، ويبقى لها طلقة واحدة.  أما إذا كان الطلاق السابق طلقتين الذي راجع فيه، إذا كان طلقتين فليس له الرجوع بعد ذلك؛ لأن هذه تكون ثالثة، تكمل الثالثة، وليس له الرجوع، هذا هو قول أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13890/حكم-مراجعة-الزوجة-بعد-قول-الزوج-طلاق-لا-رجعة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68402.mp3","categories":["الطلاق","الرجعة"]},{"id":15395,"question":"سؤاله الثاني يقول: أنا رجل متزوج من ابنة عمي، ولي منها طفلان؛ ولأنها كثيرة الشجار والشتم لي، فقد غضبت منها ذات مرة فطلقتها المرة الأولى، ثم عقدت عليها من جديد، واسترجعتها، كان ذلك قبل حوالي ثلاث سنوات، ومرة أخرى لنفس السبب طلقتها مرتين طلقتين متفرقتين، بينهما حوالي أربعة أشهر وخرجت من منزلي، وسكنت بجوار منزلي، فأنا أقرب الناس لها، فهي يتيمة، وليس لها واليًا بعد الله سواي، وقد رغبت في استرجاعها مراعاة لظروفها ولأطفالي منها؛ ولأنها ندمت على ما كانت تفعله معي، وسألت عن إمكانية استرجاعها فقيل لي: لا بد من أن يتزوجها رجل آخر؛ لأنها تعتبر مطلقة بائنة مني، فما هو الحل الصحيح في هذا؟أفيدونا، أفادكم الله.","title":"حكم من طلق زوجته ثلاث طلقات ويريد استرجاعها","answer":"الجواب: نعم إذا كان الواقع كما ذكرت طلقتها أولًا طلقة واحدة، ثم عقدت عليها بعد العدة، ثم طلقتها طلقتين متفرقتين هذه تمت الثلاث، فلا تحل إلا بعد زوج؛ لأن الله قال سبحانه: فَإِنْ طَلَّقَهَا[البقرة:230] يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ[البقرة:230]. فإذا تزوجت زوجًا شرعيًا لا حيلة، ليس بنكاح تحليل، بل تزوجت زواجًا شرعيًا، ووطئها الزوج، ثم طلقها، أو مات عنها، واعتدت فلا بأس أن ترجع إليها؛ لأن الطلقة الثالثة ليس بعدها رجعة، بل لا بد من زوج شرعي لا محلل، بل زوج شرعي ينكحها عن رغبة فإذا وطئها ثم طلقها بعد ذلك عن رغبة، أو مات عنها حلت لزوجها الذي طلقها الثلاث متفرقات، نعم.","link":"https://binbaz.org.sa/fatwas/13915/حكم-من-طلق-زوجته-ثلاث-طلقات-ويريد-استرجاعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68409.mp3","categories":["الطلاق"]},{"id":15418,"question":"سؤاله الآخر يقول: قبل سنتين تشاجرت أنا وزوجتي، فقلت لها عدة مرات وأنا في حالة غضب: أنت مثل أمي، وبعدها بثلاثة أيام تصالحنا دون أن يعلم أحد بمشاجرتنا مطلقًا، إلا الله ، فهل علينا إثم في ذلك أو كفارة؟","title":"حكم من قال لزوجته في حالة غضب: أنت مثل أمي","answer":"الجواب: عليك التوبة إلى الله؛ لأن الظهار منكر من القول وزور، كما قال الله : وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا[المجادلة:2] فالظهار لا يجوز، فالله سبحانه أباح الزوجة، ولم يحرمها، فجعلها كظهر أمك وأختك من المنكرات، فعليك التوبة إلى الله سبحانه من ذلك، وعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم تستطع فصيام شهرين متتابعين، فإن لم تستطع فإطعام ستين مسكينًا قبل أن تمسها، هذا هو الواجب؛ لقوله : وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا..[المجادلة:3] الآيات. فعليك أن تعتق رقبة إن وجدت ذلك، فإن لم يتيسر ذلك، فعليك صيام شهرين متتابعين، فإن لم تستطع فعليك أن تطعم ستين مسكينًا، ثلاثين صاعًا من قوت البلد كل واحد يعطى نصف الصاع من قوت البلد، وهو كيلو ونصف تقريبًا من رز أو تمر أو حنطة، أو نحو ذلك، من قوت البلد، قبل أن تمسها، مع التوبة إلى الله، والاستغفار والندم على ما حصل منك، والله -جل وعلا- يتوب على التائبين إذا صدقوا في التوبة، نعم.\nالمقدم: وبالنسبة لما حصل منه قبل أن يعلم بهذا الحكم؟ الشيخ: عليه التوبة إلى الله، والامتناع والتوقف حتى يكفر هذه الكفارة، نعم.","link":"https://binbaz.org.sa/fatwas/13936/حكم-من-قال-لزوجته-في-حالة-غضب-انت-مثل-امي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_685/nour_68502.mp3","categories":["الطلاق","الظهار"]},{"id":15422,"question":"هذا سؤال من المستمع (م. ع. ع) من الرياض، يقول: تزوجت فتاةً، ولم أدخل بها، وقد حصل نزاع بيننا بسبب رغبتها في الذهاب إلى بيت أهلها، ومنعي لها، ولكنها حينما لم تمتنع غضبت منها غضبًا شديدًا، فقلت لها: أنت طالق، أنت طالق، أنت طالق، أريدها أن تخاف وترجع، ولكنها لم ترض، ثم سافرت من بلدي إلى بلد آخر، وبعثت لها بمال ولأهلها، ولما عدت راجعتها دون أن أكفر، فهل علي شيء في ذلك أم لا؟ أفيدونا، حفظكم الله.","title":"حكم من طلق امرأته في حالة غضب","answer":"الجواب: نرى حضورك معها عند فضيلة القاضي، في طرفكم، حتى ينظر في الموضوع، ويكتب ما جرى بينكما، ويفتيكم بما يرى، أو يكتب لي في هذا الموضوع؛ لأن هذا يحتاج إلى النظر في صفة غضبك وأسبابه، فأنت تحضر عند القاضي في طرفكم، وهو -إن شاء الله- ينظر في الأمر، ويفتيكم بما يرى، أو يكتب إلي بصفة الواقع، وأنا أنظر بذلك، مع بيان أسباب الغضب، وحالك عند الغضب وشدته، نعم.","link":"https://binbaz.org.sa/fatwas/13947/حكم-من-طلق-امراته-في-حالة-غضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_685/nour_68505.mp3","categories":["الطلاق"]},{"id":15425,"question":"تقول هذه السائلة: أصبح الناس في المجتمع ينظرون إلى المرأة التي لم تكمل تعليمها بنظرة حزن واحتقار وإهانة، فهل يصح هذا العمل؟ وأنا أريد أن أكمل دراستي، لكن زوجي رافض، فهل يحق لي أن أطلب الطلاق لكي أكمل دراستي؟","title":"هل تطلب المرأة الطلاق لإكمال تعليمها؟","answer":"الجواب: لا، لا تطلبي الطلاق، ولكن بالأسلوب الحسن؛ لعل الله يهديه، حتى يسمح لك، وفي الإمكان أن تستفيدي من إذاعة القرآن، ومن خطب الجمعة التي تذاع، ومن إذاعة القرآن فيها خير عظيم، محاضرات، وندوات، ونور على الدرب، كل هذا علم عظيم، وفي الإمكان أن يسمح لك بطريقة حسنة إذا حاولت ذلك بالكلام الطيب، والأسلوب الحسن. المقدم: جزاكم الله خيرًا، قضية يا شيخ عبدالعزيز -حفظكم الله- تقول السائلة: بأن المجتمع ينظر إلى هذه المرأة التي لم تكمل هذا التعليم بنظرة حزن واحتقار، هل هذا صحيح؟ الشيخ: لا، لا ليس بصحيح، إذا كانت تقية لله، مستقيمة، لا يجوز احتقارها؛ لأن الدراسة قد تتيسر لها، وقد لا تتيسر، ليس كل أحد يستطيع الدراسة، ولكن يقدر أمرها بتقواها لله، فمن كانت من الأتقياء فلها شأن عظيم، ولها منزلة كبيرة، وجديرة بأن لا تحتقر لإيمانها وتقواها لله، وعقلها وتمييزها، فلا ينبغي ولا يجوز احتقارها؛ لأنها لم تدرس، والمؤمن لا يحتقر أخاه، يقول النبي ﷺ: كل المسلم على المسلم حرام، فالمسلم أخو المسلم لا يحقره ولا يكذبه ولا يخذله بحسب امرئ من الشر أن يحقر أخاه المسلم لا يجوز هذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13935/هل-تطلب-المراة-الطلاق-لاكمال-تعليمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50006.mp3","categories":["الطلاق","قضايا المرأة"]},{"id":15435,"question":"هذا سؤال من المستمع (س. م. س) من الطائف يقول: ذهبت زوجتي إلى بيت أحد الجيران، فقررت أن أطلقها بسبب ذهابها بدون إذن مني، فقلت لها: خذي جميع ما يخصك في هذا المنزل، وأنا محرمك، ولكن والديَّ الاثنين قالا لي: أنت الذي تخرج، وهي تجلس معنا، وأجبروني على عدم تنفيذ كلامي.علمًا أنني لم ألفظ بالطلاق، ولكن قلت لها: أنا محرمك، وقد سألت بعض الناس فقالوا لي: هذا لا يعتبر طلاقًا، وليس له كفارة، أفيدوني -جزاكم الله خيرًا- بالقول الصحيح في هذا الموضوع.","title":"حكم من قال لزوجته: أنا محرمك","answer":"الجواب: إذا كان الأمر كما قاله السائل، فإن عليك كفارة الظهار عن قولك: أنا محرمك، كما لو قلت على: أنت علي كظهر أمي، فعليك كفارة الظهار إذا كنت ما أردت الطلاق بهذا، ما نويت الطلاق بهذا، فهذا حكمه حكم الظهار في أصح أقوال أهل العلم. فعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم تجد صمت شهرين متتابعين، فإن شق عليك ذلك، ولم تستطع أطعمت ستين مسكينًا ستين فقيرًا، تعطي كل واحد نصف صاع من التمر، أو من الأرز، أو من الحنطة، أو من قوت بلدك إن كان قوت بلدك الذرة، أو الدخن، كذلك مقدار كيلو ونص تقريبًا؛ لكل واحد من الستين قبل أن تمسها قبل أن تجامعها، هذا هو الواجب عليك إذا كنت ما أردت الطلاق. أما إذا كنت أردت الطلاق بـ: أنا محرمك، يعني: قصدك طلاقها فهذا على الصحيح طلقة واحدة، يكون حكمه حكم الطلقة الواحدة، فإذا كان ما قبلها طلقتين ليس قبله طلقتان فلك أن تراجعها بأن تقول: راجعت امرأتي أو أنا مراجع امرأتي، أو رددت امرأتي أو نحو ذلك بإشهاد اثنين، تشهد رجلين عدلين بأنك راجعتها، وتحل لك ما دامت في العدة.\nالمقدم: حتى لو كررها بنية الطلاق؟ لو كرر هذه الكلمات؟\nالشيخ: المقصود: ما دام قالها مرة بنية الطلاق يكون طلقةً واحدة، إذا كان ما سبقها طلقتان يراجعها، أما إن كان سبقها طلقتان تكون هذه الثالثة ما فيها رجعة إلا بعد زوج.\nأما إن كررها قال: محرمك محرمك محرمك، قصده الطلاق الثلاث تكون ثلاثًا، وإن كررها لأجل إفهامها، أو لأجل تأكيد الكلام، فلا يكون إلا طلقة واحدة، إذا كان نوى الطلاق، وأما إذا كان ما نوى الطلاق فهو ظهار، وإن كرر مائة مرة هو ظهار فيه كفارة واحدة فقط. والظهار هو أن يقول: أنت علي كظهر أمي، أنت علي محرمة، أنت علي كأختي، هذا يكون ظهار فيه كفارة الظهار كما تقدم، وهي عتق رقبة مؤمنة، فإن لم يتيسر هذا صام شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا الصاع ثلاثة كيلو تقريبًا، يعطي كل واحد كيلو ونصف تقريبًا من قوت بلده من حنطة من أرز من تمر من ذرة، يكفي ستين فقيرًا، ثلاثين صاعًا، فالصاع مقدار ثلاثة كيلو تقريبًا بين اثنين لكل واحد نصف الصاع كيلو ونصف تقريبًا قبل أن يمسها، هذا إذا ما أراد الطلاق، أما إذا كان أراد بقوله: محرمك الطلاق، فالصواب: أنه يكون طلاقًا يكون طلقة واحدة، ولو كررها بنية التأكيد أو نية الإفهام تكون واحدة.\nأما إذا ما أراد الطلاق، وإنما أراد تحريمها، أو ما أراد شيئًا فيكون فيه كفارة الظهار، نعم. المقدم: لو فرض أنه سيكفر عن الظهار بصيام، ولكنه بعد أن صام عدة أيام طرأ له مرض مما يسبب له عجزًا عن إتمام الصيام، فهل يجوز له أن يعدل إلى الإطعام؟\nالشيخ: يبني على ما مضى، إذا شفي يبني على ما مضى يكمل الستين اليوم.\nالمقدم: لا يجوز أن يعدل إلى الإطعام بعد أن بدأ...؟\nالشيخ: لا، إذا كان مرضًا يرجى برؤه، لا يعجل، إذا شفي يبدأ بالحال؛ لأنه قادر على الصيام، هذا مرض عارض، أما إذا كان مرضًا يعني: لا يرجى برؤه، أو شيخًا كبيرًا عاجزًا أو امرأةً أو شيخًا كبيرًا عاجزًا، فهذا عليه الإطعام فقط؛ لأنه عاجزـ أو عنده أعمال كثيرة شاقة يتكسب، أو في عمل يشق عليه الصيام معه أجزأه الانتقال إلى الإطعام، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13968/حكم-من-قال-لزوجته-انا-محرمك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_686/nour_68604.mp3","categories":["الطلاق","الظهار"]},{"id":15453,"question":"هذه رسالة من المستمع مصطفى رمضان علي رمضان، من الجمهورية العربية اليمنية، يقول: كنت أريد فعل شيء من زوجتي، وأقسمت عليها يمينًا هذا نصه: علي الطلاق لو ما جئت بهذا الشيء؛ لتكوني طالقة، فلم تحضر هذا الشيء الذي كنت أريده. ثم أقسمت يمينًا بالطلاق شافعي ومالكي وأبي حنيفة بيني وبين شريك لي في أرض، وكانت زوجتي جالسةً في هذا المجلس، حيث قلت في هذا اليمين: علي الطلاق شافعي ومالكي وأبو حنيفة لأبيع هذه الأرض بعد هذه الزرعة، ومرت الزرعة والأخرى، ولم تبع الأرض، وأنا في أثناء اليمين كنت أشير بيدي على زوجتي. ثم أقسمت يمينًا بالطلاق على زوجتي بأن ترد علي بالنداء بقول: نعم، حينما أناديها في كل مرة، وهذا نصه: علي الطلاق لو لم تقولي: نعم كلما أناديك لتكوني مطلقة، فأحيانًا تقول، وأحيانًا لا تقول، أفيدونا بارك الله فيكم عن الحل في هذه الأيمان، مع عزمي على التوبة من هذه الأقوال؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق في وقائع مختلفة","answer":"الجواب: هذا غلط منك، استعمال الطلاق هكذا تلاعب لا خير فيه، غلط منك في هذا -أيها السائل-، ولا ينبغي منك استعمال هذا الطلاق، وأبغض الحلال إلى الله الطلاق، فلا ينبغي للمؤمن أن يستعمل الطلاق هكذا، بل يخاطب بغير الطلاق باليمين بالله بالتأكيد بدون يمين، أما هذا العمل هو عمل لا ينبغي منك، ولا ينبغي منك العود إليه. أما الحكم، فإن كنت أردت حكم اليمين، يعني: أردت التأكيد عليها أنها ترد عليك بنعم، والتأكيد أن تبيع الأرض، والتأكيد عليها أن تأتي بالحاجة، ولم ترد إيقاع الطلاق، إنما أردت التأكيد في هذا الأمر، والتشديد على نفسك، ولم ترد إيقاع الطلاق، ولكن للتأكيد على نفسك أن تبيع أو للتأكيد على زوجتك أنها تأتي بالحاجة أو تقول: نعم، ولم تقصد إيقاع الطلاق عليها وفراقها، فهذا حكمه حكم اليمين، فعليك في كل واحدة كفارة يمين في الحاجة وفي قول: نعم، وفي بيع الأرض عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، والإطعام نصف صاع من قوت البلد، مقداره كيلو ونصف من تمر أو أرز أو ذرة، إن كانت قوت البلد، أو دخن إن كانت قوت البلد، أو بر، أو تكسو الفقراء عشرة، كل واحد يعطى قميصًا أو إزارًا ورداءً، أو عتق رقبة مؤمنة، فإن عجزت عن هذا كله تصوم ثلاثة أيام عن كل يمين. فطلاقك لها أن تأتي بالحاجة، ولم تأت بها؛ هذه يمين، والطلاق عليها أنها تقول: نعم يمين، والطلاق على بيع الأرض يمين، هذا إذا كنت ما أردت إلا التأكيد والتشديد على نفسك أنك تبيع الأرض، والتشديد عليها أنها تقول: نعم، والتأكيد عليها أنها تأتي بالحاجة، ولا أردت فراقها، وإيقاع الطلاق عليها في هذه المسائل، هذا فيه كفارة يمين، ثلاث كفارات. أما إن كنت أردت إيقاع الطلاق فيها، أو في إحداها، يقع الطلاق، أنت أردت الطلاق في مسألة الأرض، ما بعتها فالزوجة طالق، يقع عليها الطلاق، فيقع عليها الطلاق، وهكذا مسألة قول: نعم ومسألة الحاجة إن أردت إيقاع الطلاق، وقع الطلاق وعلى حسب. والطلقة الواحدة فيها مراجعة، الطلقة الثانية فيها مراجعة، والثالثة الأخيرة ليس فيها مراجعة تنتهي، تكون قد بانت منك حتى تنكح زوجًا غيرك في الطلقة الأخيرة الثالثة، إذا كنت أردت إيقاع الطلاق في المسائل هذه، فعند الأخيرة إن كان الأخيرة الأرض، أو قول: نعم، أو المسألة الأولى الحاجة الأخيرة منهم من هذه الثلاث تكون هي النهاية، فلا تصلح إلا بعد زوج، إذا كنت أردت إيقاع الطلاق في المسائل الثلاث، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13983/حكم-من-حلف-بالطلاق-في-وقاىع-مختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15454,"question":"هذه رسالة من المستمع مصطفى رمضان علي رمضان، من الجمهورية العربية اليمنية، يقول: كنت أريد فعل شيء من زوجتي، وأقسمت عليها يمينًا هذا نصه: علي الطلاق لو ما جئت بهذا الشيء؛ لتكوني طالقة، فلم تحضر هذا الشيء الذي كنت أريده. ثم أقسمت يمينًا بالطلاق شافعي ومالكي وأبي حنيفة بيني وبين شريك لي في أرض، وكانت زوجتي جالسةً في هذا المجلس، حيث قلت في هذا اليمين: علي الطلاق شافعي ومالكي وأبو حنيفة لأبيع هذه الأرض بعد هذه الزرعة، ومرت الزرعة والأخرى، ولم تبع الأرض، وأنا في أثناء اليمين كنت أشير بيدي على زوجتي. ثم أقسمت يمينًا بالطلاق على زوجتي بأن ترد علي بالنداء بقول: نعم، حينما أناديها في كل مرة، وهذا نصه: علي الطلاق لو لم تقولي: نعم كلما أناديك لتكوني مطلقة، فأحيانًا تقول، وأحيانًا لا تقول، أفيدونا بارك الله فيكم عن الحل في هذه الأيمان، مع عزمي على التوبة من هذه الأقوال؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق في وقائع مختلفة","answer":"الجواب: هذا غلط منك، استعمال الطلاق هكذا تلاعب لا خير فيه، غلط منك في هذا -أيها السائل-، ولا ينبغي منك استعمال هذا الطلاق، وأبغض الحلال إلى الله الطلاق، فلا ينبغي للمؤمن أن يستعمل الطلاق هكذا، بل يخاطب بغير الطلاق باليمين بالله بالتأكيد بدون يمين، أما هذا العمل هو عمل لا ينبغي منك، ولا ينبغي منك العود إليه. أما الحكم، فإن كنت أردت حكم اليمين، يعني: أردت التأكيد عليها أنها ترد عليك بنعم، والتأكيد أن تبيع الأرض، والتأكيد عليها أن تأتي بالحاجة، ولم ترد إيقاع الطلاق، إنما أردت التأكيد في هذا الأمر، والتشديد على نفسك، ولم ترد إيقاع الطلاق، ولكن للتأكيد على نفسك أن تبيع أو للتأكيد على زوجتك أنها تأتي بالحاجة أو تقول: نعم، ولم تقصد إيقاع الطلاق عليها وفراقها، فهذا حكمه حكم اليمين، فعليك في كل واحدة كفارة يمين في الحاجة وفي قول: نعم، وفي بيع الأرض عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، والإطعام نصف صاع من قوت البلد، مقداره كيلو ونصف من تمر أو أرز أو ذرة، إن كانت قوت البلد، أو دخن إن كانت قوت البلد، أو بر، أو تكسو الفقراء عشرة، كل واحد يعطى قميصًا أو إزارًا ورداءً، أو عتق رقبة مؤمنة، فإن عجزت عن هذا كله تصوم ثلاثة أيام عن كل يمين. فطلاقك لها أن تأتي بالحاجة، ولم تأت بها؛ هذه يمين، والطلاق عليها أنها تقول: نعم يمين، والطلاق على بيع الأرض يمين، هذا إذا كنت ما أردت إلا التأكيد والتشديد على نفسك أنك تبيع الأرض، والتشديد عليها أنها تقول: نعم، والتأكيد عليها أنها تأتي بالحاجة، ولا أردت فراقها، وإيقاع الطلاق عليها في هذه المسائل، هذا فيه كفارة يمين، ثلاث كفارات. أما إن كنت أردت إيقاع الطلاق فيها، أو في إحداها، يقع الطلاق، أنت أردت الطلاق في مسألة الأرض، ما بعتها فالزوجة طالق، يقع عليها الطلاق، فيقع عليها الطلاق، وهكذا مسألة قول: نعم ومسألة الحاجة إن أردت إيقاع الطلاق، وقع الطلاق وعلى حسب. والطلقة الواحدة فيها مراجعة، الطلقة الثانية فيها مراجعة، والثالثة الأخيرة ليس فيها مراجعة تنتهي، تكون قد بانت منك حتى تنكح زوجًا غيرك في الطلقة الأخيرة الثالثة، إذا كنت أردت إيقاع الطلاق في المسائل هذه، فعند الأخيرة إن كان الأخيرة الأرض، أو قول: نعم، أو المسألة الأولى الحاجة الأخيرة منهم من هذه الثلاث تكون هي النهاية، فلا تصلح إلا بعد زوج، إذا كنت أردت إيقاع الطلاق في المسائل الثلاث، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13983/حكم-من-حلف-بالطلاق-في-وقاىع-مختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15462,"question":"سؤاله الآخر يقول: طلقت زوجتي، والسبب أنها تخاصمت مع أمي، ولدي منها أربع بنات، ولما طلقتها سافرت من المغرب إلى فرنسا، ومكثت بها ما يزيد على سبعة أشهر، ثم عدت إلى بلدي، ووجدت بناتي في أسوأ حال، وأمي كبيرة في السن، لا تستطيع رعايتهم، فلما وجدت تلك الحالة السيئة استرجعت زوجتي إلى أبنائها، وأديت لها صداقها مرة أخرى، وهي الآن في بيتي، مع أولادها، فهل علي من كفارة؟ أو هل عملي هذا صحيح؟أفيدوني، وفقكم الله.","title":"حكم من طلق زوجته ثم أرجعها بعد العدة","answer":"الجواب: إذا كان الطلاق طلقة واحدة أو طلقتين فإن العودة إليها بنكاح جديد لا بأس به، إذا كان الطلاق الذي وقع منك -أيها السائل- طلقة واحدة، قلت: أنت طالق، أو أنت مطلقة، ثم رجعت إليها بنكاح جديد؛ لأنها خرجت من العدة فلا بأس، أو كانت طلقتين، قلت: أنت طالق، أنت طالق، أو أنت مطلقة، أنت مطلقة، أو أنت طالق، ثم طالق، أو أنت طالق وطالق، تسمى طلقتين، يبقى لها واحدة. فإذا راجعتها بعقد جديد فلا بأس، وهكذا لو قلت: أنت طالق بالثلاث على الصحيح يعتبر واحدة، خلاف قول الجمهور، الجمهور يمضونها ويحرمونها بهذا، لكن الصحيح أنه إذا قال: أنت طالق بالثلاث بكلمة واحدة، أو مطلقة بالثلاث، أو طلقتك بالثلاث بهذا اللفظ، أو بالكتابة تعتبر واحدة؛ لما ثبت في الصحيح من حديث ابن عباس -رضي الله عنهما- قال: \"كان الطلاق على عهد النبي ﷺ طلاق الثلاث واحدة، فلما كان عمر قال: إن الناس قد استعجلوا في أمر كانت لهم فيه أناة، فلو أمضيناه عليهم، فأمضاه عليهم\" أمضى عليهم الثلاث، يعني: بلفظ واحد. هذا القول ذهب إليه الجمهور -رحمهم الله-، ولكن الصواب: أنه يحتسب واحدة، كما كان الحال في عهد النبي ﷺ، وعهد الصديق، وأول خلافة عمر يحسب واحدة إذا قال: هي مطلقة ثلاثًا، أو أنت طالق بالثلاث، أو كتب لها هذا، فهذا يكون طلقة واحدة على الصحيح، عملًا بحديث ابن عباس هذا. أما إذا قال: أنت طالق، ثم طالق، ثم طالق، فتحسب ثلاث؛ لأنه كررها، أو قال: أنت طالق وطالق وطالق، أو أنت مطلقة ومطلقة ومطلقة، أو ما أشبه ذلك، تحسب ثلاثًا، وإذا حسبت ثلاثًا لم تحل، حتى تنكح زوجًا غيره إذا حسبت ثلاثًا، فإنها لا تحل له حتى تنكح زوجًا آخر، نكاح رغبة، ما هو نكاح تحليل، إنما نكاح رغبة، ويطؤها، فإذا نكحها ووطئها ثم طلقها أو مات عنها حلت للأول.  أما نكاح ليس فيه وطء لا يحلها للأول، أو نكاح بنية التحليل إنه يحلل للأول، فهذا نكاح باطل، لا ينفع، يسمى صاحبه التيس المستعار، ما يصلح، ولا يحلها للزوج الأول، فلا بد أن يكون الزوج الثاني زوجًا شرعيًا تزوجها للرغبة، ثم طلقها بعد الوطء بعد دخوله بها، أو مات عنها، فإنها تحل للأول بهذا النكاح الشرعي الذي فيه الوطء، وليس فيه نية التحليل، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13982/حكم-من-طلق-زوجته-ثم-ارجعها-بعد-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_701/nour_70103.mp3","categories":["الطلاق"]},{"id":15473,"question":"هذه رسالة من المستمع: محمد دسوقي محمد، مصري، يعمل بالمملكة، وادي الدواسر، يقول: أنا رجل متزوج، وكنت أتشاجر مع زوجتي كثيرًا، وكنت مع غضبي أقول لها: علي اليمين لتخرجي من منزلي، فكانت أحيانًا لا تخرج، ويقع علي اليمين، وأنا كنت في سن التاسعة عشرة، وجاهل للحكم، وأحيانًا تذهب إلى منزل والدها، وكان والدها لا يوافق على العودة إلى منزلي بسبب اليمين، فكنت أذهب وأحضر واحدًا يحفظ القرآن، ويجتمع أناس من عائلتي ومن عائلتها في منزل والدها، وكان الذي يحفظ القرآن يقول لي: قل: أستغفر الله، فكنت أقول مثله، أستغفر الله، ثلاثًا، ويقول لي: قل: إني رددت زوجتي إلى عصمتي، والله يشهد بذلك والحاضرون والله خير الشاهدين، وعند ذلك يسمح والدها وتذهب معي إلى منزلي، فهل صحيح أن هذا القول هو كفارة اليمين، وليس له كفارة مثل الطلاق؛ لأن فيه أناس يقولون: لفظ (علي اليمين) لا تخص الزوجة بشيء؟فأفيدوني، أفادكم الله.","title":"ما حكم قول الزوج لزوجته: علي اليمين أن تفعلي؟","answer":"الجواب: إذا قال الرجل لزوجته: علي اليمين لتخرجن من البيت، أو لا تخرجي من البيت، أو لا تكلمي فلانًا، أو لا تعملي كذا وكذا، فهو على نيته، إن كان نيته الطلاق طلاق، وإن كان نيته اليمين بالله على نيته، وإذا كان مقصوده منعها من الخروج، ولو نوى الطلاق المقصود منعها، ليس المقصود طلاقها، بل المقصود منعها من الخروج ليرهبها ويخوفها إذا سمعت هذا الكلام حتى لا تخرج فعليه كفارة يمين. وهكذا إذا كان قصد اليمين بالله، أو قصد التحريم ليمنعها من الخروج لا ليحرمها، فعليه كفارة يمين، وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد، يعني: كيلو ونصف من قوت البلد، أو كسوتهم لكل واحد قميص، يعني: مدرعة يلبسها، أو إزار ورداء يكفي. والرجل إذا كان له نية أخرى، إذا كان ناويًا بهذا الكلام تحريمها عليه، إن خرجت، أو إن كان أراد خروجها فهو على نيته، تحريمها، أو أراد طلاقها، يقع طلقة، أراد تحريمها تكون محرمة عليه، وعليه كفارة الظهار، وهي عتق رقبة مؤمنة، وإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا. أما إن كان ما أراد إلا منعها، لم يرد إلا منعها فقط، ولم يرد طلاقها، ولا تحريمها، ولم يرد إلا مجرد منعها من الخروج، أو أراد أن تبقى في البيت، لا تخرج، أو لا تكلم فلانًا، أو لا تزور فلانًا، فهو على نيته، وعليه كفارة يمين؛ لأنه إذا كان ما أراد إلا منعها، فإنه يكون عليه كفارة يمين فقط، ولو كان أراد الطلاق، أو أراد التحريم، يعني: ألا تخرج، يعني: أراد بهذا منعها، عليه الطلاق ألا تخرجي، عليه الحرام ألا تخرجي، عليه اليمين بالله ألا تخرجي، أو عليه اليمين بالله أن تخرجي، أو عليه الطلاق أن تخرجي، أو عليه التحريم أن تخرجي، ما دام قصده المنع بهذه الأمور، وليس قصده تحريمًا ولا طلاقًا، وإنما قصده منعها من الخروج، فهذا كله حكمه حكم اليمين، على الصحيح، ولا يقع طلاقًا، ولا تحريمًا ما دام قصده المنع، ما دام أن قصده في هذا الكلام منعها من الخروج، فعليه كفارة اليمين، وهي ما تقدم، إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، ومقداره كيلو ونصف تقريبًا، وإن كساهم -كسا العشرة- بقميص لكل واحد، أو أعطى كل واحد إزارًا ورداءً كفى، فإن عجز صار فقيرًا ما يقدر، يصوم ثلاثة أيام، نعم.\nالمقدم: أما فعله الذي فعله على أساس الكفارة؟\nالشيخ: أما هذا الفعل الذي فعله، ما له أصل، هذا ما له أصل، كونه القارئ يقرأ يقول: أستغفر الله، هذا ما يكفي، وليس هذا حلًا للمشكلة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13998/ما-حكم-قول-الزوج-لزوجته-علي-اليمين-ان-تفعلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68802.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15477,"question":"هذا سؤال من المستمع (أ. ب. ش) من الرياض، يقول: حلفت على زوجتي بالطلاق في وقت الغضب ألا تذهب إلى الجيران، فقلت لها: علي الطلاق بالثلاث إن ذهبت إلى الجيران تكوني طالق، وفعلًا لم تذهب إلى أن جاء ذات يوم ابن الجيران يخبرها أن أمه مريضة التي هي جارتنا، فأمرتها أن تذهب لزيارتها، فماذا يجب علي في هذه الحالة؟ وهل تعتبر زوجتي طالقة أم لا؟أفيدونا، جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق ألا تذهب إلى جيرانه ثم أذن","answer":"الجواب: إذا كان المقصود من هذا الطلاق منعها من الخروج، وليس المقصود إيقاع الطلاق إن خرجت أو ذهبت، إنما مقصودك -أيها السائل- منعها من خروجها إلى الجيران، وليس المقصود أنها إن خرجت يقع الطلاق، تريد تخويفها وتحذيرها، فهذا فيه كفارة اليمين؛ لما خرجت لأجل عيادة المريضة عليك كفارة يمين، ولو كان بإذنك، كفارة اليمين إطعام عشرة مساكين أو كسوتهم -عشرة- تعطيهم على نصف صاع تمر، أو كيلو ونصف تمر، أو رز، حسب قوت البلد، وإن كسوتهم على قميص قميص، أو أعطيتهم على إزار ورداء كفى ذلك. إلا إذا كنت ناويًا في يمينك هذا (إلا بإذنك)، إن كنت نويت بقولك: عليك الطلاق بالثلاث إن ذهبت يعني: إلا بإذني، إذا كنت ناويًا أنها إذا خرجت بإذنك فلا بأس، فأنت على نيتك، فلا شيء عليك حينئذٍ؛ لأنك أذنت لها، وأما إن كنت ما نويت إلا بإذنك قلتها: منعًا باتًا، فإنها إذا خرجت ولو بإذنك عليك كفارة يمين، التي عرفت إذا كان المقصود منعها. أما إن كان المقصود إيقاع الطلاق إن خرجت، ولم تنو (إلا بإذنك) وإنما قصدت منعها، وقصدت إيقاع الطلاق إن خرجت، فإنها بخروجها إليهم يقع طلقة واحدة، طلقة واحدة، ولك مراجعتها في العدة إذا كنت لم تطلقها قبل هذا مرتين، فإن لك أن تراجعها في العدة قبل أن تخرج منها، فإن خرجت من العدة، ولم تراجعها حُرمت عليك إلا بنكاح جديد، ومهر جديد، هذا إذا كنت ما طلقتها قبلها مرتين، أما إن كنت طلقتها قبل هذا مرتين وأنت قصدت إيقاع الطلاق بهذا الكلام، فإنها تحرم بذلك تكون الطلقة الأخيرة، إذا كنت أردت إيقاع الطلاق إن ذهبت إلى الجارة، يكون هذا الطلاق واقعًا، ويكون مكملًا للثلاث، إذا كان قبلها طلقتان، نعم. المقدم: إنما قوله: بالثلاث لا يعتبر العدد؟\nالشيخ: تعتبر واحدة على الصحيح؛ لأن الثلاث بلفظ واحد على الصحيح يعتبر واحدة؛ لأنه ثبت في الحديث الصحيح من حديث ابن عباس ما يدل على هذا، نعم. المقدم: ولو كرر الطلاق؟ الشيخ: على حسبه، إن كرره ناويًا التأكيد لم يقع شيء، وإن كان كرره يريد إيقاع الطلاق ثانية وثالثة، وقع.\nالمقدم: وقع؟\nالشيخ: نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/14003/حكم-من-حلف-بالطلاق-الا-تذهب-الى-جيرانه-ثم-اذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68805.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15480,"question":"هذا سؤال من المستمع: سعود عبدالله الحربي من حائل، يقول: عندي امرأة، وقد طلقتها طلقتين، فهل يجوز لي أن أرجع إليها مرة أخرى أم لا؟","title":"هل يجوز مراجعة من طُلِقت طلقتين؟","answer":"الجواب: إذا طلق الرجل زوجته مرتين، فله طلقة ثالثة باقية، فله مراجعتها إذا كانت في العدة، ولم يطلقها على مال، بل طلاقًا من دون مال، له أن يراجعها، وإذا طلقها الثالثة انتهى الأمر، وليس له الرجوع إليها، إلا بعد زوج جديد، بعد زوج يتصل بها -يجامعها- بنكاح شرعي صحيح. أما إن كانت قد خرجت من العدة، بأن طلقها طلقة ثانية، واعتدت، ولم يراجعها، فإنها لا تحل له إلا بنكاح جديد؛ لأنها بالعدة بانت منه بينونة صغرى، فله أن يتزوجها زواجًا جديدًا كسائر الخطاب، ما دام بقي لها طلقة، فإذا انتهت الطلقة الثالثة حرمت عليه، حتى تنكح زوجًا غيره، كما هو نص القرآن الكريم، نعم.","link":"https://binbaz.org.sa/fatwas/14009/هل-يجوز-مراجعة-من-طلقت-طلقتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_689/nour_68903.mp3","categories":["الطلاق"]},{"id":15486,"question":"سؤاله الثالث يقول: رجل غضب غضبًا شديدًا، وقال لزوجته: أنت طالق ثلاث مرات، في مجلس واحد وبعد ذلك ندم على فعله، وقال: ما كنت أريد الطلاق، وإنما قصدي التهديد، فهل له أن يراجعها بعد ذلك، أم لا؟!","title":"حكم من قال لزوجته: أنت طالق ثلاث مرات بقصد تهديدها","answer":"الجواب: هذا إذا كان عقله معه، وهو ضابط نفسه ولم يقصد إلا التهديد، فمعناه: أن غضبه ليس بمستغرق، فيقع عليه الطلاق، يقع عليها الطلاق في هذه الحال، قال: أنت طالق، أنت طالق، أنت طالق، أو أنت طالق ثم طالق، ثم طالق، يقع طلاق الثلاث في هذه الحال.\nإذا كان غضبه ليس بالشديد جدًا حيث يعقل ما يقول، ويفهم ما يقول، بل قصد تخويفها أو تهديدها على ما قال، ولم يعني يغلب عليه الغضب، هذا يقع، أما إذا كان اشتد معه الغضب، وصار يعني: كالمكره الذي انغلق عليه قصده، ولم يستطع ملك نفسه بسبب شدة النزاع الذي جرى بينهما والمسابة والمشاتمة بينها وبينه، أو كونها عيرته بأشياء أوجبت شدة غضبه، أو ما أشبه ذلك مما يدل على صحة الدعوى، فإن الحادث يفهم منه صدق المدعي وعدمه. فإذا كان الحادث منازعات شديدة أو مضاربة أو مسابة أو ما أشبه ذلك مما يدل على شدة الغضب وصدقه في شدة غضبه، فإن الطلاق لا يقع على الصحيح من أقوال أهل العلم، وهو القول: بأن شدة الغضب تمنع وقوع الطلاق، ومرتبة ثانية من المراتب الثلاث فإن الغضب له ثلاث مراتب:\nإحداها: أن يكون مزيلًا لعقله، قد زال عقله بسبب شدة الغضب، حتى صار كالمجنون، فلا يقع طلاقه عند الجميع.\nالمرتبة الثانية: أن يكون اشتد معه الغضب وغلب عليه، وأفقده ضبط نفسه حتى صار كالمعتوه من شدة الغضب فهذا أيضًا لا يقع طلاقه على الصحيح.\nوالحال الثالثة: الغضب العادي الذي لا يفقده شعوره، ولا يكون غلب عليه غضبه، ولا أغلق عليه قصده، بل هو غضب عادي لا شدة فيه، فهذا لا يمنع وقوع الطلاق، بل يقع معه الطلاق، ولكن ينظر في حال المرأة أيضًا إن كانت حائضًا في حال حيض أو في حال نفاس، أو في طهر جامعها فيه، فإنه لا يقع الطلاق أيضًا على الصحيح؛ لأنه يكون طلاقًا بدعيًا، فإن الطلاق الشرعي هو الذي يكون في طهر لم يجامع فيه أو في حال ظهور الحمل، هذا هو الطلاق الشرعي الواقع.\nأما إذا كان في حيض أو نفاس أو في طهر جامعها فيه فإن القول المختار أنه لا يقع، وإن كان خلاف قول الجمهور، لكنه هو الأرجح من جهة الدليل؛ لأنه حينئذٍ طلق لغير العدة، والله يقول: فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ[الطلاق:1] والعدة فسرها أهل العلم بأن تكون طاهرًا من غير جماع ولا حمل، هذه هي العدة التي يطلق لها النساء، تكون طاهرًا أو حاملًا، فإذا طلقها طاهرًا أو حاملًا ولم يجامعها في حال الطهر، وهي حائل فإنه الطلاق شرعي، أما إذا طلقها في حال الحيض أو في حال النفاس أو في طهر جامعها فيه ولم يستبن حملها فإنه يكون طلاقًا بدعيًا، مخالفًا لقوله تعالى: فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ[الطلاق:1] وما خالف أمر الله لا يقع؛ لقوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد.\nفالحاصل: أن هذا السائل يحتاج إلى أن يتصل بأهل العلم هو وزوجته ووليها حتى ينظر في أمره وإلى شدة غضبه، وإذا كان في الرياض أو في غير الرياض وأحب أن يتصل بي للنظر في موضوعه فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14023/حكم-من-قال-لزوجته-انت-طالق-ثلاث-مرات-بقصد-تهديدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_690/nour_69003.mp3","categories":["الطلاق"]},{"id":15488,"question":"هذا سؤال من المستمع: (ق. ع. أ) من بلاد زهران، قلوة، يقول: أنا رجل متزوج، وقد حصلت خصومة ذات يوم مع زوجتي، فطلبت منها فعل شيء، ولكنها رفضت، فكررت عليها وهي مصرة على رفضها، فقلت لها: لو رفضت فأنت محرمة علي كما حرمت علي أمي، ولكنها أصرت على رفضها، ثم استمرت حياتنا الزوجية بعد ذلك دون أن أكفر. علمًا أنني كثيرًا ما أحلف بالطلاق على أشياء وأحنث في يميني ولا أكفر، ولكني لا أقصد الطلاق، وإنما نتيجة الغضب والحماقة، والآن لي مع زوجتي أربع سنين، ولي منها طفلان، فماذا علي الآن؟أفيدوني، وفقكم الله.","title":"حكم التلفظ بالحرام والطلاق بنية التخويف","answer":"الجواب: أولًا: لا ينبغي تعاطي هذه الأمور، ينبغي لك -أخي- ألا تتعاطى هذه الأمور، لا التحريم ولا الطلاق، بل تخاطبها بغير ذلك، وتأمرها وتنهاها بغير ذلك، وينبغي أن تنزه نفسك ولسانك عن هذا حتى لا تقع في مشاكل، وفي أمور قد تحرم عليك زوجتك وأنت لا تشعر، فعليك أن تجتنب هذه الألفاظ تمامًا. أما حكم ما وقع فإذا كان الواقع منك بقصد التخويف، وحثها على أن تعمل ما قلت لها، وليس القصد من ذلك فراقها، فإنه عليك كفارة يمين، وليس عليك طلاق، ولا ظهار، إذا كان المقصود حملها على العمل، وأن تنفذ ما قلت لها، وليس قصدك إيقاع الطلاق وفراقها إن لم تفعل، فإن عليك في هذا كفارة يمين، وإن كفرت كفارة ظهار؛ لأنك قلت: كأمي من باب الاحتياط فحسن، ولكن يكفي هذا كفارة يمين؛ لأن المقصود حملها على ما قلت لها حتى تفعل. وهكذا لو تلفظت بلفظ الطلاق، عليك الطلاق أن تفعلي كذا، أو إن لم تفعلي كذا، فأنت طالق، والمقصود حملها على الفعل، وحثها، وتخويفها، فهذا كله ليس فيه إلا كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، والإطعام نصف صاع من التمر أو الرز أو الحنطة كيلو ونصف تقريبًا من قوت البلد، والكسوة إزار ورداء أو قميص يستر في الصلاة هذه الكسوة، أو عتق عبد أو عبدة، تحرير عبد أو عبدة، هذه هي الكفارة، فإن عجزت عن هذا كله، كفاك صيام ثلاثة أيام، كما نص عليه كتاب الله في سورة المائدة في كفارة اليمين. لكن بكل حال ننصحك أن تحذر هذه الألفاظ، وتحذر التساهل بها دائمًا، وعليك أن تبادر بالكفارة عما فعلت، كفارة الأيمان عما فعلت سابقًا، عن كل واحدة تطعم عشرة مساكين، خمسة أصواع من التمر، أو الرز أو الحنطة، كل واحد له نصف الصاع، يعني: كيلو ونصف من هذه الأطعمة، أو تكسو عشرة بإزار ورداء، أو بقميص كفارة يمينك؛ لأن هذه الأشياء في حكم اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14024/حكم-التلفظ-بالحرام-والطلاق-بنية-التخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_690/nour_69004.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15494,"question":"هذه رسالة وصلت عن طريق البريد الممتاز، يقول السائل: أرجو عرض رسالتي وأسئلتي على سماحة الشيخ عبدالعزيز بن باز -حفظه الله-.والسؤال الأول يقول: كنايات الطلاق إذا تلفظ بها الإنسان ولم ينو شيئًا لا طلاق ولا غير ذلك، هل يقع بها الطلاق؟","title":"ما حكم كنايات الطلاق إلا لم يقصد بها الطلاق؟","answer":"الجواب: الكنايات لا يقع بها الطلاق إلا بالنية، فإذا قال: روحي إلى أهلك، أو اذهبي إلى أهلك، أو أنت حرة، وهو لا يقصد الطلاق لا يقع طلاقًا، إنما يقع بالنية؛ لقوله ﷺ: إنما الأعمال بالنيات وهذه ألفاظ محتملة، فلا تكون للطلاق إلا بالنية، هذا الذي قرره أهل العلم، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14027/ما-حكم-كنايات-الطلاق-الا-لم-يقصد-بها-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69102.mp3","categories":["الطلاق"]},{"id":15495,"question":"من أسئلة هذا السائل يقول: إذا أنشد الإنسان قصيدة أو أغنية فيها ألفاظ الطلاق من الصراحة، فما الحكم في ذلك؟","title":"حكم من أنشد قصيدة فيها ألفاظ الطلاق الصريحة","answer":"الجواب: إذا كان أنشدها يريد قراءتها، ما أراد الطلاق، ما عليه شيء، الأعمال بالنيات، نعم.","link":"https://binbaz.org.sa/fatwas/14028/حكم-من-انشد-قصيدة-فيها-الفاظ-الطلاق-الصريحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69103.mp3","categories":["الطلاق"]},{"id":15496,"question":"يقول السائل يا سماحة الشيخ: قلت لزوجتي: إذا كنت مجبرة على الزواج فلا علي، أو كلامًا نحو هذا، لا أذكر ماذا قلت بالضبط لطول المدة، فهل هذا الكلام يكون تخييرًا؟ وإذا كان تخييرًا فهل يترتب علي شيء؟","title":"حكم من قال لزوجته: إذا كنت مجبرة على الزواج فلا علي","answer":"الجواب: لا يترتب شيء؛ لأن معناه: لست المسؤول الذي أجبرك يعني، فلا يترتب عليها شيء، لكن ينظر في الأمر، إذا كانت مجبرة ولم ترض فلها الخيار على الصحيح.  أما إذا أجبرت ورضيت، فالصواب: أنه صح النكاح، والحمد لله، نعم، إذا أجبرها أبوها ثم دخلت راضية، فالحمد لله، صح النكاح، نعم. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14029/حكم-من-قال-لزوجته-اذا-كنت-مجبرة-على-الزواج-فلا-علي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69104.mp3","categories":["الطلاق"]},{"id":15504,"question":"هذا السائل (أ. أ. أ) بعث بسؤالين، سؤاله الأول يقول: في العام الأول من زواجنا، وعلى إثر غضب شديد، حلفت على زوجتي بالطلاق، وكانت صيغته كالآتي:إذا دخلت أمك هنا تكوني طالقة، وكنت أقصد بذلك التهديد فعلًا لا الطلاق، وبعد ذلك دخلت أمها، ومضى على زواجنا حتى الآن أكثر من عشرين عامًا، وأنجبت منها أولادًا، ولم أحلف بالطلاق مرة أخرى طيلة هذه المدة، فما حكم هذا الطلاق، هل يقع أم لا؟","title":"ما حكم الحلف بالطلاق إذا قصد به التهديد؟","answer":"الجواب: الصواب: أن هذا الطلاق له حكم اليمين؛ لأنك لم تقصد إيقاعه، وإنما قصدت المنع من دخول أمها وتهديدها بهذا الأمر، فهذا الطلاق يكون له حكم اليمين في أصح قولي العلماء.  وعليك كفارتها، وإن طال المدى، عليك أن تكفر عن يمينك بإطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة مؤمنة، كما بينه الله في كتابه العظيم في سورة المائدة، ويكون الفقير الواحد له نصف الصاع من التمر، أو من الأرز أو غيرهما من قوت البلد، يدفع إلى عشرة مساكين لا ينقص عنهم، أو تكسوهم كسوة تجزئهم في الصلاة كقميص أو إزار ورداء، ويكفي هذا والحمد لله، ولا يقع الطلاق، زوجتك معك وعشرتكما -العشرة التي بينكما- باقية، ولا حرج في هذه المدة الطويلة إلا أنك أخطأت في عدم إخراج الكفارة هذه المدة الطويلة.  وأما القول بأنه يقع الطلاق فهو قول ضعيف مرجوح، والصواب: أنه لا يقع ما دام للتهديد والمنع، وليس للإيقاع، نعم.","link":"https://binbaz.org.sa/fatwas/14036/ما-حكم-الحلف-بالطلاق-اذا-قصد-به-التهديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_702/nour_70206.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15506,"question":"هذا السائل صلاح خيري حسن، من جمهورية مصر العربية، يقول: أنا رجل متزوج، وقد حصل شجار بيني وبين زوجتي، وفي حالة غضبي طلبت مني أن أعطيها كلمة الطلاق، فقلت لها أثناء هذا الشجار: أنت ستون مرة طالق، وحصل هذا الكلام مني مرتين في خلال عشرة أيام، وعاشرتها بعد ذلك لمدة شهر، وبعدها سافرت إلى خارج بلدي، أفيدوني؛ لأنني في حيرة كبيرة؛ ولأنني مسافر إلى بلدي بعد فترة قصيرة، فماذا أفعل، هل هي طالق فعلًا وتحتاج إلى عقد جديد لإعادتها إلى عصمتي؟ مع العلم أن كل الكلام مني لم يكن من القلب.","title":"حكم قول الزوج عند الغضب لزوجته: أنت ستون مرة طالق","answer":"الجواب: هذا الطلاق أولًا منكر، لا يجوز أن يقول: ستون طلقة، ولا ثلاث طلقات، ولا أربع، ولا عشر، المشروع أن يطلق المؤمن طلقةواحدة، ويقول لها: أنت مطلقة، أنت طالق، وأن لا يأتي بأزيد من هذا، فيقول: عشرين، أو ثلاثين، أو ستين، كل هذا منكر؛ ولما سمع النبي ﷺ أن رجلًا طلق بالثلاث غضب، وقال: أيلعب بكتاب الله وأنا بين أظهركم قال ابن عمر لما بلغه أن رجلًا طلق ثلاثًا، قال: \"قد عصيت ربك فيما أمرك به من طلاق امرأتك\" فلا يجوز للزوج أن يطلق بالثلاث أو بالستين أو بالمائة، كل هذا لا يجوز. أما الواقع وهو أنك قلت لها: ستون طالق، في عشرة أيام مرتين، فهذا ينظر فيه، فإن كان الغضب قد اشتد معك حتى صار عقلك غير مضبوط، فاختل شعورك، أو اشتد معك الغضب جدًا حتى لم تملك نفسك بسبب شدة النزاع والكلام الذي جرى بينكما؛ فهذا على الصحيح لا يقع به طلاق عند شدة الغضب الذي يغلب عليه عدم قدرته على ضبط نفسه، ومنعه من الطلاق، وعدم تعقله مضار الطلاق؛ فهو شبه المجنون، وشبه المعتوه، أو ما يقرب من ذلك، فهذا لا يقع طلاقه، وهكذا لو كان عنده بعض العقل، ولكنه قد اشتد به الغضب، وصار سبعين في المائة، ثمانين في المائة أخو المجنون، وأخو المعتوه لشدة الغضب؛ فهذا لا يقع طلاقه في هذه الأحوال التي اشتد فيها الغضب، وغلب عليه الغضب حتى عجز عن ضبط نفسه، وعن ملكها، وعن الإمساك عن الطلاق. وهكذا لو كانت في طهر جامعتها فيه، وليست حاملًا، وليست آيسة، بل تحيض أو في نفاس، أو في حيض، فإن هذا الطلاق لا يقع إذا كان في حال حيض أو نفاس أو طهر جامعتها فيه وليست حاملًا، وهي ممن يحيض؛ فإن الطلاق لا يقع في هذه الحالة على الصحيح من أقوال أهل العلم. أما إن كانت في طهر لم تجامعها فيه أو في حال حمل؛ فإن الطلقتين واقعتان إذا كان شعورك معك والغضب ليس قد بلغ الشدة التي تمنع من وقوع الطلاق، الغضب العادي؛ فإن الطلاق يقع ويقع بكل جملة طلقة في المرة الأولى طلقة، والثانية طلقة على الصحيح؛ لأن الصحيح أن الطلاق بالثلاث بلفظ واحد، وهكذا ما في حكمه: كالطلاق بالأربع وبالعشر وبالمائة، فالصحيح: أنه يقع واحدة؛ لما ثبت عن ابن عباس -رضي الله عنهما- قال: \"كان الطلاق على عهد النبي ﷺ وعهد الصديق، وأول خلافة عمر  طلاق الثلاث واحدة، فقال عمر : إن الناس قد استعجلوا في أمر كانت لهم فيه أناة فلو أمضيناه عليهم؛ فأمضاه عليهم\" خرجه مسلم في الصحيح. وثبت معناه من حديث ابن عباس في قصة أبي ركانة عند أحمد بإسناد جيد أنه طلقها بالثلاث، فردها عليه النبي ﷺ وجعلها واحدة، فهذا هو الصواب فيما يقع من قول الرجل: أنت طالق بالثلاث، أو بالستين، أو بالمائة أو بالألف أو ما أشبه ذلك، فهذا حكمه حكم الطلاق واحدة على الصحيح، فتكون هذه المرأة قد وقع عليها طلقتان إذا كان شعور المطلق معه، وليس عنده الغضب السابق، بل كان غضبه عاديًا، فإنه يقع عليها طلقتان إذا كانت حاملًا أو في طهر لم تجامعها فيه طلقتان، ويبقى لك واحدة. وإذا كنت جامعتها بعد هذا فإن الجماع في معنى الرجعة، فتكون في حبالك وفي عصمتك، ويبقى لك واحدة، ولك الرجوع إليها ومباشرتها، وإن أشهدت شاهدين على الرجعة علاوة على الجماع فهذا حسن، لأن: بعض أهل العلم يرى أن الجماع لا يكفي في الرجعة، وبعضهم يرى أنه لا بد من النية معه بنية الرجعة، فإذا أشهدت شاهدين أنك راجعتها فالمدة قريبة، الشهر بعد جماعك لها، أو بعد الطلقتين الشهر قريب ليس في الغالب حصول خروجها من العدة، بل تحتاج إلى أكثر من ذلك في مرور ثلاث حيض عليها بعد الطلقة الثانية. فالحاصل: أن الرجعة حصلت بالجماع، وبقي لها طلقة، ولك العود إليها والاتصال بها؛ لأنها زوجتك، لكن إن أشهدت شاهدين عدلين على أنك راجعتها؛ حرصًا على اتباع السنة، فهذا أولى وأفضل؛ لأن الله أمر بذلك  في قوله: وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ [الطلاق:2] فهذا اللفظ في هذه الآية الكريمة تعم شهادة الطلاق وشهادة الرجعة، مع مراعاة ما تقدم في إن كان الطلاق حال الغضب العادي، أو الغضب الشديد الذي أفقدك شعورك، أو قارب ذلك، ومع مراعاة أيضًا كونها في طهر جامعتها فيه، أو في حيض، أو في نفاس، أما إذا كانت في حالة من هذه الأحوال الثلاث: في حيض أو نفاس أو في طهر جامعتها فيه، وليست حاملًا؛ فإن الطلاق لا يقع، علاوة على ما حصل منك من شدة الغضب، نعم.","link":"https://binbaz.org.sa/fatwas/14038/حكم-قول-الزوج-عند-الغضب-لزوجته-انت-ستون-مرة-طالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_702/nour_70208.mp3","categories":["الطلاق"]},{"id":15516,"question":"هذا السائل سوري، بعث بهذا السؤال يقول: سماحة الشيخ، وقع خلاف بيني وبين زوجتي، وبحال غضب لم أسيطر على أعصابي، وطلقتها ثلاث طلقات، وكنت فاقد للوعي من الغضب، ولي منها خمسة أطفال، وهي الآن في منزلي، وأنا نادم على كل شيء حصل مني، وأنا الآن لا أريد أن أفرط بها، فأرشدوني يا سماحة الشيخ ماذا أفعل؟جزاكم الله خيرًا.","title":"حكم من طلق زوجته ثلاث طلقات وهو غضبان","answer":"الجواب: عليك أن تراجع المحكمة في بلدك، وفيما تراه المحكمة الكفاية -إن شاء الله-، نعم.","link":"https://binbaz.org.sa/fatwas/14054/حكم-من-طلق-زوجته-ثلاث-طلقات-وهو-غضبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56916.mp3","categories":["الطلاق"]},{"id":15556,"question":"هذا سؤال من المستمع علي بن علي اليماني، مقيم بينبع، يقول: أنا رجل متزوج من امرأة عاصية لأوامري، فلا تطيعني في شيء، ودائمًا تخرج من البيت بغير إذني، إلى جانب ارتكابها بعض الأعمال التي أثارت غضبي؛ مما جعلني أفكر في طلاقها، وفعلًا كتبت ورقة طلقتها فيها طلقتين، وسميتها باسمها، واسم أبيها، وكنت آنذاك في البيت بمفردي، وليس عندي أحد، ولكني بعد ذلك مزقت الورقة، ولم يعلم أحد بما حصل ولا هي، وكان ذلك قبل حوالي خمسة أشهر، فهل يقع طلاق بهذا أم لا؟","title":"حكم الطلاق بالكتابة إذا لم يعلم به أحد","answer":"الجواب: نعم يقع عليها طلقتان، إذا طلقتها كتابة أو لفظًا، ولو ما علمت، ولو لم تشهد؛ فإنه يقع الطلاق، لكن يبقى لك واحدة، إذا كنت لم تطلقها قبل ذلك؛ فقد بقي لك واحدة، فلك مراجعتها، ولك العقد الجديد عليها إن كانت قد خرجت من العدة.  المقصود: أنه باقي واحدة، إذا كنت ما طلقتها -أيها السائل- قبل هذا الطلاق المكتوب.\nالمقدم: هو يقول: إنه مضى خمسة أشهر من وقت الكتابة ألا تكون قد خرجت من العدة؟\nالشيخ: نعم، الغالب أنها قد خرجت من العدة، يعني: بالحيض، وبالأشهر إن كانت بالأشهر أيضًا، إلا إذا كانت حبلى ولم تضع فهي في العدة، لكن إذا كان وطئها على نية الرجعة؛ صارت رجعية بالوطأ الذي حصل منه قبل أن تخرج من العدة، لو كانت يعني: لما رجعت إلى البيت وطئها بعد الطلقتين، وناويًا مراجعتها تمت الرجعة، إذا كان هذا قبل مرور الثلاث الحيض عليها، نعم. المقدم: لكن ناحية وقت كتابته ورقة الطلاق فيما لو كانت مثلًا في طهر جامعها فيه.\nالشيخ: الصحيح إذا كانت في طهر جامعها فيه، أو في حيض لا يقع على الصحيح، وهو قول جمع من أهل العلم، خلاف رأي الجمهور، نعم.","link":"https://binbaz.org.sa/fatwas/14095/حكم-الطلاق-بالكتابة-اذا-لم-يعلم-به-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70307.mp3","categories":["الطلاق"]},{"id":15561,"question":"هذه رسالة من المستمع صالح بن عبد الله بن حمود الضبعان، سؤاله يقول: ما الحكم في رجل مسلم استخرج لزوجته صك ترمل باسم رجل آخر؛ ليصرف لها راتب من الضمان الاجتماعي؟ وما الحكم في الشهود الذين شهدوا في هذا الصك؟","title":"حكم استخراج صك للمتزوجة بأنها مطلقة لأجل الضمان الاجتماعي","answer":"الجواب: إذا كان الواقع هو ما ذكر؛ فهذا منكر، وهو آثم والشهود آثمون، وإن كان أخبر عن طلاق سابق من شخص سابق طلقها ثم تزوجها بعده؛ فهو وإن كان صدق أنها قد طلقت، لكنهم عموا المسألة وأخفوا الحقيقة، فهي طلقت ثم تزوجت، وهي زوجة للذي أخذ لها الصك، فعلى كل حال هو زور ومنكر: إما في الحقيقة وإما في ظاهر الأمر بالنسبة إلى المقصود، فهو تدليس وكذب على المحكمة؛ حتى يحصل لهم مرادهم من المال بغير حق، فعلى كل حال يستحقون عليه العقوبة؛ لأنه منكر وتدليس وتلبيس على المحاكم والدولة، وهذا المال لا يجوز؛ لأنه أخذ بغير حق بطريق غير شرعي. نعم.\nالمقدم: أيضًا له سؤال آخر يقول: ما الحكم في رجل مسلم يقدم على استخراج صك طلاق لزوجته باسم رجل آخر وهي في ذمته؛ ليصرف لها معاش أيضًا من الضمان الاجتماعي شبيه بالأول ..؟\nالشيخ: مثلما تقدم كله منكر، كله منكر والمال حرام الذي صرف لها بهذا الصك المزور. نعم.\nالمقدم: أيضًا له بقية أسئلة شبيهة به يقول: ما حكم امرأة طلقت وتزوجت رجلًا آخر وبعد مدة طويلة طلبت من زوجها الأول صك طلاق لتحصل على معاش من الضمان الاجتماعي، رغم أنها لا زالت في ذمة الرجل الحالي مع العلم..\nالشيخ: مثلما تقدم، وإن كان حقًا في نفس الواقع أنها مطلقة، لكنها أخفت الحقيقة من كونها مزوجة بعد ذلك، فهذا منكر ملبس فيه، فيه حيلة وخداع. نعم، نسأل الله العافية، لا حول ولا قوة إلا بالله، نعوذ بالله، أخذ المال بغير حق أمر منكر وسحت، فنسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/14101/حكم-استخراج-صك-للمتزوجة-بانها-مطلقة-لاجل-الضمان-الاجتماعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70308.mp3","categories":["الطلاق","الأخلاق المذمومة"]},{"id":15579,"question":"هذا سؤال من المستمع (ج. ج. ق) من المغرب فاس، يقول: أحيانًا أقول: زوجتي طالق علي أو حرام أن لا أفعل ذلك الشيء، ثم تغريني نفسي وأفعله، والآن أريد أن أتوب إلى الله توبة خالصة.أفيدوني، جزاكم الله خيرًا، ما الحل في قولي هل يقع الطلاق، أم علي كفارة، أم علي صيام؟","title":"حلف بالطلاق وقال: حرام علي إن فعلت كذا وفعل؛ فما الحكم؟","answer":"الجواب: إذا قلت ذلك فالحكم يختلف بحسب النية؛ لأن الرسول ﷺ قال: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فإذا قلت: علي الطلاق أني لا أفعل كذا، أو حرام علي أن لا أفعل كذا، فإن كنت أردت إيقاع الطلاق بهذا، فإنه يقع الطلاق طلقة واحدة، وإذا كررت ذلك وقع ما كررته من ثنتين أو ثلاث. أما إن كنت ما أردت الطلاق، وإنما أردت المنع، منع نفسك من هذا الشيء، لم ترد الطلاق، وإنما أردت أن تمنع نفسك، كأن تقول: علي الطلاق لا أزور فلانًا، علي الطلاق لا أكلم فلانًا، تريد منع نفسك من هذا الشيء، ولم ترد إيقاع الطلاق، فإن عليك كفارة يمين، ولا يقع الطلاق، وكفارة اليمين إطعام عشرة مساكين، أو كسوتهم، إما أن تطعمهم غداءً أو عشاءً، أو نصف صاع من قوت البلد كيلو ونصف من قوت البلد، لكل واحد تمر أو رز أو نحو ذلك، وإما أن تكسوهم كسوة قميص لكل واحد أو إزار ورداء لكل واحد، والعاجز الفقير الذي لا يستطيع هذه الأشياء يصوم ثلاثة أيام، كما دل عليه كتاب الله . وهكذا الحرام إذا قلت: علي الحرام ما أفعل كذا، فإذا أردت أنك تحرمها إن فعلته، وأنها حرام عليك إن فعلته، كان ظهارًا فيه كفارة الظهار إذا فعلت هذا الشيء وهي عتق رقبة مؤمنة، فإن عجزت صمت شهرين متتابعين، فإن عجزت أطعمت ستين مسكينًا، ثلاثين صاعًا، توزع بينهم لكل واحد نصف صاع من قوت البلد من تمر أو رز أو حنطة ونحو ذلك، هذا إذا كنت أردت التحريم تحريمها عليك إن فعلت. أما إن كنت أردت المنع منع نفسك من هذا الشيء كأن تقول: علي الحرام ما أكلم فلانًا، أو علي الحرام ما أزور فلانًا، فإن هذا حكمه حكم اليمين كما تقدم، فعليك كفارة يمين؛ لقوله تعالى: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝  قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ[التحريم:2] فسمى التحريم يمينًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14120/حلف-بالطلاق-وقال-حرام-علي-ان-فعلت-كذا-وفعل-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69205.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15583,"question":"هذه رسالة من الأخت (ع. ش) مصرية، مقيمة بمكة المكرمة، تقول: إنها تزوجت منذ سنوات طويلة، برجل يشرب الخمر بعد أن أقنعها أهلها بأنه سيتوب، وبعد زواجها حاولت أن تقنعه بالامتناع عن ذلك الشراب المحرم مرات كثيرة، ولكنه لم يقتنع، وبعد أن أنجبت منه أربعة أطفال أتى ذات مرة وشرب أمامها؛ فحملت الإناء الذي شرب فيه وكسرته؛ عندها غضب عليها، وقال لها: أنت طالق ومحرمة علي مثل أمي وأختي. فما الحكم الشرعي في قوله هذا؟ وهل تبقى معه على هذه الحال، أم تفارقه؟","title":"حكم من قال لزوجته: أنت طالق ومحرمة علي","answer":"الجواب: إذا كان حين قوله هذا عاقلًا؛ فإن الطلاق يقع، ويقع به طلقة واحدة، وتحرم به المرأة بالتحريم حتى يكفر، إذا كان عقله معه يقع طلقة، وله مراجعتها ما دامت في العدة إذا كان لم يطلقها قبل هذا طلقتين، وعليه كفارة الظهار: وهي عتق رقبة مؤمنة. فإن عجز صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكينًا، لكل مسكين نصف صاع، من قوت البلد: من تمر أو أرز أو غير ذلك، قبل أن يطأها، قبل أن يقربها. أما إن كان حين قوله هذا قد لعب به الخمر، قد ذهبت بعقله الخمرة؛ فلم يبق يعقل ما يقول، فإنه لا يقع طلاقه في أصح قولي العلماء، كما أفتى بذلك عثمان بن عفان الخليفة الراشد ، وذهب إلى قوله جماعة من أهل العلم وهو الصواب. وهكذا لا يقع تحريمه ولا يؤثر؛ لأنه صدر من غير عاقل، والأحكام مناطة بالعقل، فمتى عرفت السائلة منه أنه ذاك الوقت ليس في عقله؛ فإن هذا الطلاق وهذا التحريم لا يعول عليهما، وهي زوجته، وباقية في عصمته. أما إن كان عاقلًا، وليس متغيرًا بسبب الخمر؛ فإن الطلاق يقع -كما تقدم- طلقة واحدة، وله المراجعة ما دام أنه لم يطلقها قبل هذا طلقتين، وعليه كفارة الظهار كما تقدم، اللهم إلا أن تكون حال إيقاع الطلاق في طهر جامعها فيه أو في نفاس، أو في حيض؛ فإنه لا يقع على الصحيح، وبه قال جمع من أهل العلم. وثبت عن ابن عمر  ما يدل على ذلك؛ لحديث ابن عمر الثابت في الصحيحين أن النبي ﷺ لما بلغه أن ابن عمر طلق امرأته؛ وهي حائض غضب، وأنكر عليه، وأمره بمراجعتها؛ فإذا طهرت من الحيضة التي بعد الحيضة التي طلقها فيها؛ فإنه بعد ذلك إن شاء طلق، وإن شاء أمسك قبل أن يمسها، إن شاء طلق قبل أن يمسها، وإن شاء أمسك، وفي لفظ قال له: فليطلقها طاهرًا أو حاملًا يعني: بعد طهرها من حيضتها التي طلق فيها، ثم بعد طهرها من الحيضة الأخرى، وهذا قول نصره جماعة من أهل العلم، منهم شيخ الإسلام ابن تيمية -رحمه الله- والعلامة ابن القيم -رحمه الله-، ويدل عليه قوله -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد وهذا عمل ليس عليه أمر النبي ﷺ، بل هو خلاف الشرع، فإن السنة أن يطلق الزوج زوجته طاهرة من غير جماع، أما طلاقها في الحيض، أو في النفاس، أو في طهر جامعها فيه، وهي ليست حاملًا؛ فإنه طلاق بدعة، لا يقع على الصحيح عند جمع من أهل العلم، كما تقدمت الإشارة إلى ذلك، نعم.\nالمقدم: لكن هل الأفضل لها أن تعيش مع هذا الزوج المدمن لهذا الشراب أو تفارقه؟ الشيخ: هذا محل نظر؛ إن رأت أن المصلحة تقتضي بقاءها معه ونصيحته؛ لأنها في ضرورة إليه لحفظ أولاده، والإنفاق عليها، ورجت أن الله ينفعه بكلامها ونصيحتها؛ فهذا قد يكون أولى؛ لئلا تضيع إذا كانت في بلد ليس هناك من يصونها، ولا من يقوم عليها، وإن رأت أن فراقه أصلح؛ لأن عندها من يصونها، ويحسن إليها، وإلى أولادها، ولا ترجو رجوعه عن هذا الباطل؛ ففراقه أصلح، ترفع الأمر إلى المحكمة، أو تطلب منه الطلاق لعله يطلق، أو المحكمة الشرعية تنظر، أو توسط من الأخيار والأعيان من يتوسط بينهما حتى يطلقها، أو يتوب إلى الله من عمله السيئ، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14124/حكم-من-قال-لزوجته-انت-طالق-ومحرمة-علي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_704/nour_70402.mp3","categories":["الطلاق"]},{"id":15587,"question":"ونعرض عليه أول سؤال ورد إلينا من المستمع: (ص. خ. ن) مقيم بالمملكة، يقول: هو شاب متزوج، وقد أصابه مرض شبيه بالجنون، فهو دائم القلق والتشنج، وكثير الوساوس؛ ولسوء الحظ فهو يعيش بين أسرة تؤمن بالتنجيم والتطير؛ ولذلك فقد أشاروا عليه بأن يطلق زوجته، فهي السبب في كل ما أصابه؛ لأن نجمها نحس كما يقولون، ولا يزول مرضه إلا بفراقها وطمعًا في الشفاء فقد نطق بطلاقها بالثلاث، وليس عنده أحد، ولا حتى زوجته، ولم يخبر أحدًا بذلك؛ خوفًا من خروجها من بيته، وعدم عودتها إليه، وبقيت مدة عنده إلى أن وضعت مولودًا، يقول: وقد سألت عن هذا فقيل لي: عليها عدة بعد أن تخبرها، ثم تسترجعها، ومضى إلى الآن أربع سنين، وقد سألت أيضًا آخر فقال: ليس عليك طلاق، ولا عليها عدة، ولكن تب إلى الله. فأرجو إفادتي عما يترتب على هذا الطلاق، فالزوجة لا زالت عندي في البيت، وحالتي الصحية كما هي لم أستفد شيئًا من فعل ذلك. وما هي نصيحتكم لمن يعتقد الصحة والنفع في مثل تلك الأعمال؟","title":"حكم التنجيم وطلاق مختل الشعور","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن التنجيم أمر منكر، وهو من شعب السحر، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: من اقتبس شعبة من النجوم فقد اقتبس شعبة من السحر زاد ما زاد والتنجيم محرم عند أهل العلم إجماعًا، وهو اعتقاد أن النجوم لها أثر في الحوادث من صحة ومرض وفقر وغنى وغير ذلك، بل هذا من أوهام المنجمين، فإن هذه النجوم خلقها الله زينة للسماء، ورجومًا للشياطين، وعلامات يهتدى بها في البر والبحر، وليس لها أثر فيما يتعلق بالحوادث لا في الصحة، ولا في المرض، ولا في الغناء، ولا في الفقر، ولا في نزول المطرن ولا في غير ذلك.  وإنما هي أوهام باطلة من أصحابها لا أساس لها من الصحة، ولا يجوز للمسلم أن يأتيهم، ولا أن يسألهم لا المنجمين، ولا الرمالين، ولا جميع الكهنة والعرافين الذين يدعون بعض علوم الغيب بهذه الأشياء، بل يجب هجرهم وتأديبهم، والقضاء عليهم من جهة ولاة الأمور، حتى لا يضروا الناس، ولا يضلوهم، ولا يجوز سؤالهم، ولا تصديقهم، قال النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا. والعراف: هو المنجم والرمال والكاهن ونحوهم ممن يدعي علم بعض المغيبات بالطرق التي سلكها، الطرق الشيطانية من تنجيم أو ضرب بالحصى أو أشباه ذلك من طرقهم الفاسدة. وقال -عليه الصلاة والسلام- أيضًا: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد -عليه الصلاة والسلام-، فأخبارهم باطلة، ولا يجوز سؤالهم، ولا تصديقهم، وعلى من فعل هذا التوبة إلى الله  والإنابة إليه، والندم على ما مضى، وعدم العود إلى ذلك. أما هذا الرجل المطلق، فإن كان عقله معه، فإنه يقع الطلاق، لكن يكون واحدة؛ لأن الصحيح من أقوال العلماء أن الطلاق بالثلاث بكلمة واحدة كتابيًا أو لفظًا لا يقع به إلا واحدة؛ لما ثبت عن رسول الله ﷺ في حديث ابن عباس: \"أن الطلاق كان على عهده طلاق الثلاث واحدة، وهكذا على عهد الصديق، وعهد عمر في أول خلافته، ثم إن عمر  أمضى ذلك -أمضى الثلاث- وقال: إن الناس استعجلوا في أمر كانت لهم فيه أناة، فلو أمضيناه عليهم، فأمضاه عليهم\". أما في عهده ﷺ، فكانت الثلاث بلفظ واحد تعتبر واحدة، قال ابن عباس: «كان الطلاق على عهد النبي ﷺ طلاق الثلاث واحدة». وهكذا في عهد الصديق، وفي أول خلافة عمر ، لكن إن كان عقله غير مستقيم بسبب ما أصابه، وعرف الثقات العارفون به أن مثله يعتبر معتوهًا، فإنه لا يقع طلاقه، أما إن كان عقله مضبوطًا، والمرض ما أثر على عقله، فإنه يقع عليها طلقة بهذا الطلاق، ويكون بقاؤها عنده من غير رجعة غلطًا منه، ويعتبر جماعه لها مراجعة لها إذا كان أراد ذلك، أراد بمجامعتها مراجعتها وردها إليه، فإن الجماع على الصحيح يكون رجعة لها مع النية.  أما مع غير النية من غير نية فهذا محل خلاف قوي بين أهل العلم، ولعل الصواب: أنه يتم بذلك الرجعة لجهله بذلك، فيكون راجعها بالجماع حال حملها، وتكون زوجة له، ويكون مضى عليها طلقة، تعتبر هذه طلقة واحدة، ويكون راجعها بالجماع. أما إن كان ما جامعها، ولا اتصل بها، حتى الآن، فإنها بوضعها الحمل خرجت من عدته، ومضى عليها طلقة، وله أن يعود إليها بنكاح جديد، ومهر جديد، كخاطب من الخطاب، كأنه أجنبي، يخطبها على نفسها، فإذا وافقت، فإنه يتزوجها بزواج جديد، ومهر جديد؛ لكونها خرجت من العدة بوضع الحمل، هذا إذا كان ما جامعها بعد الطلاق، أما إن كان جامعها بعد الطلاق، فإنه يعتبر رجعة لها، وتبقى عنده على طلقتين، ومضى عليها طلقة إذا كان ما طلقها قبل ذلك سوى هذه الطلقة، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين. إذًا هؤلاء الذين أفتوه في قضيته هذه ليسوا على حق في كلامهم؟ الشيخ: الذين قالوا: إنه لا يقع الطلاق غلط، إلا إذا كان عقله غير مضبوط، إذا كان عقله مختلًا كالمعتوه، فإنه لا يقع طلاقه، لكن سؤاله هذا يعطي أن له عقلًا، سؤاله هذا مضبوط، فإن كان السؤال منه هذا يدل على ثبات عقله، فإن كان هذا السؤال وضعه له واضع، فعلى كل حال ينظر، يسأل أهل الخبرة به من الثقات الذين يعرفونه، فإن كانوا يعرفون عنه اختلال عقله، وأنه لا يضبط ما يقول، ولا يحسن ما يقول، وأن أقواله وأفعاله تدل على اختلال عقله كالمجانين والمعاتيه والسكارى، فهذا لا يقع طلاقه، نعم. المقدم: هل من نصيحة إلى مثل هؤلاء الذين يفتون بغير علم، وخاصة في مثل هذه القضايا المهمة؟ الشيخ: ننصح جميع طلبة العلم، وجميع من يسأل أن يتقي الله، وأن لا يفتي إلا بعلم؛ لأن القول على الله بغير علم من أكبر الكبائر، ومن أعظم الضلال، حتى جعله الله سبحانه فوق الشرك، قال : قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[الأعراف:33].\nفجعل القول على الله بغير علم فوق الشرك، وهذا خطر عظيم، وأخبر في آية أخرى أنه من أمر الشيطان، قال تعالى: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[البقرة:169] فجعل سبحانه القول على الله بغير علم من أوامر الشيطان، نسأل الله العافية.  فالواجب على المؤمن أن يحذر ذلك، وأن لا يقول إلا بعلم وبصيرة، يعلم حكم الله بالدليل، قال الله وقال رسوله، أو بإجماع أهل العلم. المقصود: لا يفتي إلا على بصيرة، على علم، على بينة، وإلا فليحذر عاقبة ذلك، فإن العاقبة وخيمة لمن قال على الله بغير علم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14125/حكم-التنجيم-وطلاق-مختل-الشعور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_693/nour_69301.mp3","categories":["الطلاق"]},{"id":15599,"question":"هذا سؤال من المستمع (م.ع. م) مصري يعمل مدرسًا باليمن الشمالي، يقول: تزوجت وبعد مدة من زواجي ذهبت زوجتي إلى منزل والدها بإذني، وكان بيني وبين والدها سوء تفاهم؛ ولما تأخرت عن الحضور ظننت أنهم منعوها من الحضور، فغضبت وذهبت إلى منزل والدها، وخرج والدها وعندما سألته عن عدم حضورها، قال: هي مريضة، فقلت له: أخرجها إلي حتى أطلقها، فقال لي: قل وأنا أبلغها، فقلت له: قل لها: إنها طالق، وخرجت من البيت، وقلت عند خروجي تمتمات أذكر منها: علي الطلاق ثلاثة، ما هي، أو ما تلزمني، وعندما وصلت بيتي ورجعت إلى نفسي، وجدت أنني قد تسرعت وندمت، وذهبت إلى أحد المشايخ للفتوى في هذا، حيث كانت حاملة في الشهر التاسع وقت ذاك، فسألت اثنين فقالا: إنها طلقة واحدة، وذهبت ومعي رجلين، وأرجعت زوجتي قبل الوضع، وأنجبت منها ابنتين، ولكنني أحسست أنني طلقتها ثلاثًا؛ لأنها كانت نيتي، فما العمل الآن؟ وإذا طلقت فما هي حقوقها الواجبة علي؟علمًا بأنها الآن غير حامل؟ نعم.","title":"حكم من شك في عدد الطلقات","answer":"الجواب: هذا يرجع إلى ما صدر منك إذا كنت إنما طلقتها واحدة فقط حين قلت: هي طالق، فإرجاعها لا بأس، ولم يمض عليها إلا طلقة إذا كان ما طلقتها سابقًا. أما التمتمة التي بعد ذلك فأنت أعلم بها، إن كنت طلقتها طلقة ثانية، وثالثة، فأنت أعلم، ما تصلح لك، وعليك أن تردها إلى أهلها، وعليك أن تتوب إلى الله عما فعلت من جماعها وقد طلقتها، وعليك الاستغفار والتوبة والندم، والأولاد يلحقون بك للشبهة التي عرضت لك.  أما إن كانت التمتمة ما فيها طلاقًا صريح، وإنما كلام يعني: لم تعقله، ولم تعرف وجهه، فهذا لا يضرك، وهي زوجتك، ولم يقع عليها إلا طلقة واحدة، والذي عليك خوف الله ومراقبته ، فإذا كنت تعلم أنك طلقتها طلقتين أخريين بعد ما فارقت أباها، فقد تمت الثلاث، وعليك أن تردها إلى أهلها، مع التوبة والاستغفار، وأولادك لاحقون بك للشبهة، وعليك الإحسان إليها، وإلى أولادها، حسب الأمر الشرعي في الإنفاق على أولادها. وإما إن كنت تمتمت بشيء لا يعقل، ولا يفهم، أو لا تفهمه أنت، أو لا تعقله أنت من شدة الغضب، أو من الوساوس أو من أشياء أخرى، فليس عليها عمل ولا تعتبر، والمعتبر هو الطلقة التي قلتها لأبيها واحدة فقط، والمراجعة صحيحة، وزوجتك معك، والحمد لله، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14139/حكم-من-شك-في-عدد-الطلقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69404.mp3","categories":["الطلاق"]},{"id":15611,"question":"هذا سؤال من المستمع (م. ع. ع. م) من الرياض البطحاء:أنا رجل متزوج، وقد حصلت خصومة بيني وبين زوجتي، فغضبت منها، وطلقتها ثلاث مرات، فأرادت الذهاب إلى أهلها، فحلفت عليها أن لا تذهب، وحينما أصرت على الذهاب قلت لها: أنت طالق، وكررت هذا الكلام ثلاث مرات، ثم سافرت أنا إلى الخارج، ومكثت سنتين، ثم رجعت، وذهبت إلى أهلها وصالحتها وراجعتها. علمًا أنها لم تخبر أهلها بما حدث، ولا زالت عندي إلى الآن وقد حدث بعد عودتها مشكلة فطلقتها، وإلى الآن لم أراجعها لا قولًا ولا فعلًا، فما الحكم في هذا؟ أرشدوني، بارك الله فيكم إلى ما يجب أن أعمله؟","title":"خطورة إخفاء طلاق المرأة على أهلها","answer":"الجواب: هذا عمل خطير، ليس لك فعله إخفاء الطلاق على أهلها، الطلاق ثلاث مرات، هذا عمل خطير، والقاعدة: أن الطلاق الثلاث إذا لم يكن له مانع يحرمها، لو طلقتها، ثم طلقتها، ثم طلقتها، القاعدة: أنها انتهت، وأنها بالطلقة الأخيرة انتهت، ولا تحل إلا بعد زوج جديد.  فالواجب أن تسأل أهل العلم عن الطلاق الأول والأخير، أنت وهي تسألان أهل العلم، وتبينان الحقيقة، لا تكتمان شيئًا، وأهل العلم يفتونكم، سواء عندي إذا حضرتما عندي، أو عند أهل العلم في الرياض، أو غير الرياض، حتى ينظر في أمر الطلاق، وأسباب الطلاق، وحال المرأة عند الطلاق. المقصود: لا بد من النظر، ولا يجوز الكتمان، ولا التساهل في هذا الأمر، فردها بعد الطلقات الأولى الثلاث هذا أمر خطير، ولا يجوز إلا بعد الاستفتاء والنظر في وقوع الطلقات الثلاث أو عدم وقوعها، فإنه قد يمنع من وقوعها مانع، يجب على المطلق أن يستفتي، وينظر فيما يقوله أهل العلم حتى يراجع زوجته على بصيرة. أما أن يطلق، ويطلق، ويطلق، ويراجع، ويخفي ما وقع، هذا لا يجوز، وليس من شأن المسلم، بل هذا من شأن غير المسلم.  فعليك أن تشرح الحال لأهل العلم، وتبين لهم ما وقع منك بحضرتها وحضرة وليها حتى يكون الأمر جليًا، ثم تأخذ الفتوى من أهل العلم، والله المستعان، ولا حول ولا قوة إلا بالله.  وليس لك أن تقربها، ولا أن تعود إليها حتى تستفتي أهل العلم، وقد وقعت في أمر خطير لا يجوز لك الوقوع فيه، فنسأل الله أن يهدينا وإياك صراطه المستقيم، نعم. المقدم: طيب بالنسبة لبقائها في البيت؟ الشيخ: لا يبقيها في البيت، يجب أن يوصلها إلى أهلها حتى يستفتي، نعم. المقدم: وإذا كانوا أهلها مثلًا خارج المملكة؟ الشيخ: ولو خارج المملكة. المقدم: لا بد أن يعيدها إلى أهلها. الشيخ: أو إلى محل أمين عند نساء أمينات. المقدم: أو محارم لها. الشيخ: أو محارم، تبقى عندهم حتى تتم الفتوى، من جيرانه أو أقاربه المأمونين، تبقى عندهم حتى يستفتي، نعم. المقدم: أحسن الله إليكم، وأثابكم.","link":"https://binbaz.org.sa/fatwas/14153/خطورة-اخفاء-طلاق-المراة-على-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_695/nour_69504.mp3","categories":["الطلاق"]},{"id":15617,"question":"سؤاله الثاني يقول: هناك أخوان شقيقان حصل بينهما شجار بسبب المال، وحضر جماعة للإصلاح، وطلبوا من الصغير إعطاء الكبير شيئًا من المال، ويتم التراضي بينهما، ولكنه غضب، وقال: طلاق ثلاثًا لا أسامحه لا في الدنيا ولا في الآخرة، فماذا عليه الآن؟ وهل يقع طلاق بهذا لو سامح أخاه؟","title":"حكم من حلف بالطلاق ألا يسامح أخاه","answer":"الجواب: ما كان ينبغي لهذا المسلم أن يتسرع في الطلاق، وكان ينبغي له أن يقدر إخوانه الذين جاؤوا للإصلاح، وأن يعرف لهم فضلهم، ونبل مقصدهم، وأنهم جديرون بالتقدير والاعتراف بالفضل، حيث جاؤوا للإصلاح، والله شرع لنا الإصلاح، قال : لا خَيْرَ فِي كَثِيرٍ مِنْ نَجْوَاهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلاحٍ بَيْنَ النَّاسِ[النساء:114] وجاء في الحديث الحث على إصلاح ذات البين، والله يقول سبحانه: فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ[الأنفال:1] فكان ينبغي لهما جميعًا أن يقدرا لهؤلاء الجماعة قصدهم الطيب، ولا سيما الأصغر، فإن حق الكبير عليه عظيم. أما وقد وقع ما وقع، فإنه ينظر في قصده، فإن كان قصده بالطلاق منع نفسه من المسامحة لأخيه، وليس من قصده فراق أهله إن سامح أخاه؛ فهذا حكمه حكم اليمين، وعليه كفارتها، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فإن عجز صام ثلاثة أيام، هذا هو الواجب في هذه المسألة إذا كان هذا المطلق إنما قصد منع نفسه من المسامحة، ولم يقصد فراق زوجته إن سامح أخاه، فهو بهذه النية يكون طلاقه هذا في حكم اليمين في أصح قولي العلماء، وعليه كفارتها إذا سامح أخاه، وهو الأولى به أن يسامح أخاه، وأن يصل رحمه، وأن يتعوذ بالله من الشيطان، ولو كان أخوه قد أخطأ عليه، لو فرضنا أن أخاه الكبير قد أخطأ عليه، فكونه يسامح أخاه الكبير ويتنازل عن حقه هذا خير له في الدنيا والآخرة، وقد قال النبي -عليه الصلاة والسلام- في الحديث الصحيح: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها فهذا هو الحكم في هذه المسألة إن كان قصده منع نفسه من مسامحة أخيه، ولم يقصد فراق زوجته إن سامح أخاه. أما إن كان قصده فراق زوجته، قصد منع نفسه وفراق زوجته إن سمح أخاه هذا قصده، يعني: يقصد منع نفسه من المسامحة، ويقصد مع ذلك أنه يفارقها، وأن الطلاق يقع إذا سامح أخاه، فهو في هذه الحال ينبغي له أن يسامح أخاه، وتقع عليه طلقة واحدة، ويراجعها؛ لأن الثلاث بلفظ واحد تعتبر واحدة على الصحيح من أقوال العلماء، فقد ثبت عن النبي ﷺ من حديث ابن عباس في صحيح مسلم ما يدل على أن الثلاث إذا كانت بلفظ واحد تعتبر واحدة، فيكون له الرجعة، إذا سامح أخاه وقعت طلقة واحدة فقط من هذا اللفظ، وله أن يراجعها في العدة بقوله: راجعت امرأتي، أو أمسكت امرأتي، أو رددت امرأتي، وعليه أن يشهد على ذلك شخصين، هذا هو السنة، أن يشهد عدلين على هذه المراجعة. هذا هو الذي ينبغي إذا كان لم يطلقها قبل هذا طلقتين، أما إن كان قد طلقها قبلها طلقتين تكون هذه هي الثالثة يكون ما فيها رجعة، لكن إذا كان ما طلقها طلقتين فإنه إذا كان قصد إيقاع الطلاق فإنه يسامح أخاه، وتقع طلقة، ويراجع زوجته، والحمد لله، فصلحه مع أخيه أسهل وخير له من مسألة الطلقة إذا وقعت، فإن أمرها لا يضر ما دام له فسحة في الرجعة، ولم يطلق قبل هذا طلقتين، فإن أولى به أن يسامح أخاه، ولو وقعت على زوجته طلقة، فإن أمرها بحمد الله سهل، ومصالحة أخيه مهمة كبيرة، وقربة عظيمة إذا كان أخوه من أهل الخير والإيمان من المسلمين. أما إذا كان أخوه ليس بمسلم، أو ممن يظهر الفسوق والعصيان والكبائر، فتركه وعدم المصالحة قد يكون خيرًا لأخيه حتى يسلم من شره، وما لديه من فجور أو كفر، لكن ما دام أخوه مسلمًا مستورًا فمصالحته مطلوبة، وصلة رحم، ولو وقع بها طلقة لا تمنعه من مراجعة الزوجة، والله المستعان، نعم. المقدم: بارك الله فيكم، لو فرضنا أنه كان يقصد إيقاع الطلاق لو سامح أخاه وفعلًا كان الحكم كما تفضلتم بإيقاع طلقة عليه، لكن لو لم يعلم بهذا الحكم إلا بعد أن انقضت العدة فكيف العمل؟\nالشيخ: يعني: سامح أخاه؟ المقدم: يقصد إيقاع الطلاق لو سامح أخاه، وتفضلتم بقولكم أنه يقع عليه طلقة واحدة في هذه الحالة إذا سامح أخاه؟\nالشيخ: هي تقع منه حين المسامحة، ما هو من سابق، الطلقة تقع حين المسامحة. المقدم: وليس حين التلفظ؟ الشيخ: لا. حين المسامحة.\nالمقدم: حين المسامحة؟ الشيخ: تبدأ العدة من حين المسامحة، وتقع الطلقة من حين المسامحة. المقدم: أقصد إذا كان لم يعلم بهذا الحكم إلا بعد أن وقع الطلاق وسامح أخاه، وانتهت عدتها؟ الشيخ: ما راجعها يعني؟ المقدم: ما راجعها. الشيخ: تصلح بعقد جديد، يتزوجها من جديد إذا كان ما طلقها إلا طلقة واحدة، أو ما طلقها إلا هذه الطلقة التي سامح فيها أخاه، نعم. المقدم: يعني: إذا كانت الأولى أو الثانية فيسترجعها بعقد جديد إذا انقضت العدة، ولم يراجعها؟ الشيخ: نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14161/حكم-من-حلف-بالطلاق-الا-يسامح-اخاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_696/nour_69602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15618,"question":"هذا سؤال أيضًا للمستمع (ع. ح) صومالي، مقيم في دولة الإمارات العربية المتحدة، أبو ظبي، يقول: أنا رجل متزوج، وقبل سبع سنوات تقريبًا طلقت زوجتي طلقتين لسبب خلاف بينها وبين أهلي، وكنت في ذلك الوقت خارج البلاد، ووقع الطلاق بخطاب بعثته من صورتين، وبشهادة اثنين من أصدقائي، صورة للزوجة وصورة لوالدي، وبعد ذلك عدت إلى البلاد، وعلمت أن صورة الخطاب لم تصل إليها، ولم تعرف شيئًا عن ذلك الطلاق، وبعد استشارة بعض الناس عندنا، قيل لي: يمكن إرجاعها بعقد جديد، وتم ذلك، وبعد أربع سنوات حصل خلاف مرة أخرى، وأمام قاضي المحكمة الشرعية طلقتها طلقة واحدة، والآن بعد مرور سنتين أريد إرجاعها خوفًا على مستقبل أطفالي، فهل يجوز لي ذلك أم لا؟","title":"حكم من طلق امرأته ولم يبلغها","answer":"الجواب: ما دام الطلاق الأول طلقتين فهذه الثالثة انتهى، ما بقي شيء، نعم. لأنه طلقها الثالثة حرمت حتى تنكح زوجًا غيره، فما دام أنه طلقها طلقتين الطلاق الأول ولو ما بلغها، فما دام طلقها طلقتين ما بقي له إلا واحدة فإذا تزوجها، ثم طلقها، انتهى، نعم. المقدم: إذًا لا تحل له إلا بعد زوج جديد؟ الشيخ: نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14168/حكم-من-طلق-امراته-ولم-يبلغها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_696/nour_69605.mp3","categories":["الطلاق"]},{"id":15622,"question":"هذا سؤال من المستمع رمضان حسن درويش، من العراق، محافظة التأميم، يقول: تزوجت منذ أكثر من ثلاث سنين، بعد أخذ موافقة الزوجة وأهلها، وبعد مضي هذه المدة طلبت زوجتي الطلاق، بحجة أنها غير راضية بي وقت الزواج، وأيدها أخوها في هذا الطلب، وأصروا عليه، وهددني أخوها إن لم أفعل، وفعلًا طلقتها تحت وطأة التهديد والخوف من شره، فما الحكم في مثل هذا الطلاق؟","title":"ما حكم طلاق المكره؟","answer":"الجواب: هذا يرجع إلى المحكمة، والمحكمة تنظر في الأمر، تنظر في الأدلة والواقع وأدلة الزوج، وغير ذلك، تنظر في الأمر والله يوفق القاضي للخير، نعم. المقدم: إنما من حيث الحكم الطلاق بالإكراه؟ الشيخ: ما نقول شيء في هذا، نخشى أن القائل ليس بصحيح، ليس بصادق. المقدم: أقصد كحكم عام، يعني للمكره؟ الشيخ: المكره لا يقع طلاقه. المقدم: المكره لا يقع طلاقه. الشيخ: المكره بالضرب والتهديد ممن يظن إيقاعه به لا يقع، إذا طلق تبعًا لقوله أن القصد الإكراه، لا؛ لأنه طابت نفسه منها، لكن الحكم في هذا يرجع إلى القاضي؛ لأن المدعي قد يكون ما هو مصيب، قد يكون ما أكره، نعم.","link":"https://binbaz.org.sa/fatwas/14165/ما-حكم-طلاق-المكره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_696/nour_69604.mp3","categories":["الطلاق"]},{"id":15644,"question":"سؤاله الثالث يقول: بينه وبين زوجته، يقول: حلفت عليها مرة قائلًا: والله العظيم إن لم تذهبي اليوم إلى بيتنا لتكوني طالقة، وكانت في بيت أبيها في حالة نفاس، ولم يمر عليها خمسة أيام من وضعها لسوء تفاهم نشب بيني وبين أبيها، وكنت لا أقصد طلاقها، وإنما أقصد أن تخاف على نفسها من الطلاق، وتذهب إلى بيتنا تاركة بيت أبيها، ولكنني بعد أن هدأت لمت نفسي على هذا الحلف وخوفًا من إصابتها بمرض أثناء ذهابها، المهم لم ينفذ الذهاب إلى بيتنا، وبعد مرور عدة سنين ولكثرة كلامها في موضوع لا أرغب في الاستماع إليه حلفت عليها قائلًا: والله العظيم إن لم تسكتي عن الحديث في هذا الموضع الآن لتكوني طالقة، ولكنها تكلمت، وكان قصدي أيضًا أن أمنعها من الحديث، وأخوفها بالطلاق، ولا أقصد تطليقها، إنما أقصد طاعتي في السكوت، فهل في هذين الحلفين وقع علي يمين أو طلاق رجعي، أو يمين وطلاق معًا؟ وبمرور السنين أيضًا حلفت عليها قائلاً: إذا تصرفت في أي موضوع بدون مشورتي لتكوني علي حرام كأمي وأختي، أقصد أيضًا تهديدها بعدم التصرف بدون مشورتي وطاعتي، فهل هذا ظهار أم يمين؟ أفيدونا عن ذلك، جزاكم الله خيرًا.","title":"حكم الطلاق والحرام بنية التخويف والزجر","answer":"الجواب: هذا التصرف لا يليق منك، بل ينبغي التثبت، وعدم المسارعة إلى الطلاق، ولا إلى التحريم أيضًا، ولكن ما دام الواقع هو ما ذكرت، وليس قصدك إلا تخويفها وحثها على امتثال أمرك، فإن هذه الوقائع الثلاث كلها في حكم اليمين، كل واحدة منها في حكم اليمين، الطلاق الأول والثاني والتحريم الأخير كله في حكم اليمين، وعليك كفارة اليمين عن هذه الوقائع الثلاث.  عليك كفارات ثلاث، عن كل واحدة كفارة يمين، وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد من تمر أو غيره؛ وذلك يقارب كيلو ونصف، أو كسوتهم بما يجزئ في الصلاة، أو ما هو أكمل من ذلك مثل: إزار ورداء، مثل: قميص وعمامة يكفي لكل واحد، وإن عشيتهم في بيتك أو غديتهم في بيتك كفى ذلك أيضًا. وعليك التوبة إلى الله من التحريم؛ لأنه لا يجوز التحريم لما أحل الله ، وهذا الذي قلنا لك هو الأصح من أقوال أهل العلم أن في هذا كفارة يمين، ولا يلحقك طلاق ولا تحريم، هذا هو الأرجح من أقوال أهل العلم في هذه المسائل الثلاث، نسأل الله لنا ولك الهداية، نعم.\nالمقدم: اللهم آمين. المقدم: في الحلف الأخير بالظهار لا يكون ظهارًا هذا؟\nالشيخ: لا. يمين، حكمه حكم اليمين. المقدم: حكمه حكم اليمين؟ الشيخ: حكمه حكم اليمين، نعم.","link":"https://binbaz.org.sa/fatwas/14189/حكم-الطلاق-والحرام-بنية-التخويف-والزجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15645,"question":"هذا السائل محمد أحمد علي من الأردن، عمان، يقول: تزوجت منذ خمسة عشر سنة من امرأة مسلمة وأنجبت لي أربعة أولاد وابنتين، إلا أن العلاقة الزوجية بيننا قد ساءت بادئ الأمر، ثم تم الصلح بتدخل الأقارب، ولكن ما لبث أن عاد الخلاف بيننا، وقد حاولت إصلاح أمرها بشتى الطرق، ولكن لا فائدة، وذات مرة اشتد غضبي عليها، فقلت لها: أنت طالق، وقد استفتيت أحد المشايخ فأفتاني باسترجاعها وفعلًا، ولم يدم الوفاق بيننا، بل عادت إلى ماضيها وإساءتها إلي بكل ما تستطيع فعله، فقلت لها: أنت طالق يا فلانة، وسميتها باسمها، ومرة ثالثة وربما رابعة كلما تسيء إلي أقول لها: أنت طالق دون أن تسمعني، وحدث هذا أكثر من ثلاث مرات، فهل تحرم علي بعد ذلك أم لا؟","title":"حكم من طلق زوجته ثلاث طلقات","answer":"الجواب: إذا كان الطلاق صدر منك وأنت في شعورك، وضبط عقلك، وكملت الثلاث حرمت عليك؛ لأن الطلقة الثالثة هي الأخيرة، والله يقول سبحانه: فَإِنْ طَلَّقَهَا فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ[البقرة:230] وهذه الطلقة هي الثالثة، فإذا كنت في الطلقات الثلاث قد حضر شعورك وقلتها وأنت ضابط عقلك فإنها تقع هذه الطلقات إلا إذا كان شيء منها في حال حيض أو نفاس أو طهر جامعتها فيه فإنها لا تقع في أصح قولي العلماء. والمسألة فيها خلاف، وعند الجمهور أن الطلاق يقع حتى في حال البدعة في حال الحيض والنفاس، ولكن أرجح القولين عدم الوقوع إذا كان الطلاق وقع منك في حال كونها حائضًا أو نفساء أو في طهر جامعتها فيه، ولا يجوز الطلاق في حال الحيض ولا في النفاس، ولا في طهر جامعتها فيه، يحرم الطلاق في هذه الأحوال الثلاث؛ لما ثبت من حديث ابن عمر -رضي الله تعالى عنهما- «أنه طلق امرأته وهي حائض، فأنكر عليه النبي ﷺ وأمره أن يراجعها، ثم يمسكها حتى تطهر ثم تحيض ثم تطهر، ثم إن شاء طلق قبل أن يمس، ثم قال له النبي ﷺ: فتلك العدة التي أمر الله أن تطلق لها النساء يعني: في قوله سبحانه: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ[الطلاق:1].\nفطلاقهن للعدة أن تطلق المرأة في حال طهر لم يجامعها فيه الرجل، أو في حال كونها حاملًا، هذا هو الطلاق الشرعي، أن تطلق المرأة حال كونها حاملًا أو في طهر لم يجامعها الزوج فيه، ولم يتبين حملها؛ لقوله ﷺ لابن عمر: ثم ليطلقها طاهرًا أو حاملًا وفي اللفظ الآخر: قبل أن يمسها فهذا يدل على أن الطلاق في حال الحيض أو النفاس أو في طهر مسها فيه -أي: جامعها فيه- يكون بدعة، يكون محرمًا، لكن هل يقع أم لا؟\nعلى قولين: أكثر أهل العلم على أنه يقع مع الإثم.\nوالقول الثاني: أنه يأثم، وعليه التوبة إلى الله، ولكن لا يقع؛ لقول النبي ﷺ لابن عمر: راجعها ولم يقل له: إن الطلاق وقع، فقال: راجعها يعني: ردها، وفي لفظ: \"فردها علي، ولم يرها شيئًا\" قال ابن عمر: \"فردها علي ولم يرها شيئاً\" يعني: لم يرها شيئًا واقعًا على الصحيح، ولكن عليك مع هذا التوبة إلى الله إذا كنت راجعتها بعد الثالثة ولم تتبصر ولم تسأل، الواجب على المؤمن أن يسأل ولا يقدم على شيء إلا على بصيرة، فالطلاق الثالث يحرمها إلا إذا وجد مانع من وقوعه. فعليك أن تتصل بأهل العلم، مع المرأة ووليها حتى يحقق في أمركما، وحتى يعرف حالها حين الطلاق، وبعد ذلك يفتيك العالم بما يتضح له شرعًا عند حضورك مع المرأة ووليها لديه وسؤالكم جميعًا عما وقع، وقد عرفت من هذا الكلام أن الطلقة الأخيرة الثالثة تحرمها عليك حتى تنكح زوجًا غيرك إذا كانت الطلقات الثلاث وقعت في حال طهر لم تجامعها فيه، أو وقعت في حال كونها حاملًا فإنها تحرم عليك حتى تنكح زوجًا غيرك، أما إن كانت إحدى الطلقات وقعت في حيض أو نفاس أو طهر جامعتها فيه فإنها لا تقع ويبقى لها طلقة إذا كان الطلاق الواقع ثلاثًا، وإن كان الواقع أربعًا فهذا أكبر وأشنع كيف يحل لك أن تتصل بها بعد الثالثة، ولم تسأل ولم تستفت أهل العلم؟ المقصود: أن عليك أن تسأل أهل العلم، وأن تتبصر في أمرك، ويكون معك وليها والمرأة أيضًا عند السؤال حتى يتبصر العالم مما وقع بينكم وحتى يفتيكم بما يراه شرعًا، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/14190/حكم-من-طلق-زوجته-ثلاث-طلقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69705.mp3","categories":["الطلاق"]},{"id":15651,"question":"هذه رسالة من المستمع (ف. ك) من إيران - طهران، هي في الواقع مطولة، ولكن لعله من الأفضل أن نقرأها كلها حتى تتضح الرؤية.يقول: أنا رجل متزوج من ابنة خالي قبل ستة عشر عامًا، ولي منها خمسة أولاد، وقد حدث بعد مرور ثلاث سنوات من زواجنا أن حصلت مشكلة، وكنت وقتها في حالة عصبية، ولكني أعي ما أقول، فقلت: أنت طالق ثلاث مرات، وهي ترفض ذلك، وتبين لي بعد ذلك أنها وقت الطلاق كانت حاملًا، وأنا كنت أنوي فراقها إلى الأبد، وبعد يومين جاءت وتوسلت وحاولت العودة، ولكني رفضت ذلك.الشيخ: أعد، أنت طالق وماذا؟المقدم: نعم، ثلاث مرات يقول.الشيخ: أنت طالق؟المقدم: أنت طالق ثلاث مرات، وتبين لي بعد ذلك أنها وقت الطلاق كانت حاملًا، وأنا كنت أنوي فراقها إلى الأبد، وبعد يومين جاءت وتوسلت وحاولت العودة، ولكني رفضت ذلك، وكررت الطلاق مرة أخرى.وبعد محاولة منها ومن الأهل واجتهاد من بعضنا في البحث عن حل في هذا الطلاق فقد رجعت وعادت الحياة بيننا طبيعية إلى أن حدث مرة أخرى، وقبل خمس سنوات أن حصلت مشكلة أخرى فغضبت، ولكني أيضًا أعي ما أقول، فقلت لها: أنت السبب في كل هذا، فأنت طالق ثلاث مرات، فجاء الجيران وقال الجميع: فكر في الأطفال ومصيرهم، واعدل عن قرارك؛ لأنك كنت غضبانًا، فقلت لهم: أنا في حالة طبيعية، فاشهدوا فهي طالق ثلاث مرات، وكنت أنوي إيقاع الطلقات الثلاث؛ لئلا تعود الحياة الزوجية بيننا أبدًا.علمًا بأن الحادثتين الأخيرتين اللتين وقع فيهما الطلاق كانت في طهر جامعتها فيه، لكنها لم تتركني، بل ظلت تحاول وتصر على الرجعة، فخوفًا على ديني قررت السفر من بلدي، وهي لا زالت مع أولادها، ومضى الآن خمس سنوات، ولكن بلغني أنها أصبحت مستقيمة في كل شيء، مؤدية لواجباتها الدينية، وقد كان في بعدي عنها هذه السنين درسًا لها.فهل بعد هذا يجوز لنا الرجوع إلى بعض بحياة زوجية أم لا؟ فهي تمر بوضع سيئ جدًا من الناحية المادية والاجتماعية، فقد طلب أهلها منها مغادرة بيتهم، والخروج منه، وليس لها أحد إلا الله.","title":"حكم إرجاع المرأة بعد طلاقها ثلاثًا","answer":"الجواب: هذا في الحقيقة من السائل تساهل لا يليق، وكان الواجب على السائل أن يسأل أهل العلم قبل أن يعيدها إلى بيته، قبل أن يتصل بها؛ لأن الطلاق الآن طلاق منكر، وطلاق مستوفٍ لشروط إيقاع الطلاق بخصوص الطلاق الثاني، فإنه طلقها الطلاق الأول بالثلاث: أنت طالق، أنت طالق، وهو في حالة عصبية، فهذه الحالة الأولى إن كان قد اشتد بك -أيها السائل- الغضب شدة تشبه فيها فاقد الشعور، تشبه فيها المعتوه، اشتد بك الغضب شدة يعني: لا تستطيع أن تملك نفسك، ولا أن تمتنع من الطلاق، فهذا لا يقع على الصحيح، لكنك تقول: إنك تعي ما تقول، وأنك لست في حالة يعني: تشبه حال فاقد الشعور، ثم إنك بعدما أشاروا عليك، وزال الغضب أبيت إلا أن تعيد الطلاق مرة أخرى، طلقتها وهي حامل، فهي لم تقع إن لم تطلق بالأول طلقت بالثاني الذي زال معه الغضب، فالواجب عليك فراقها، وعدم الرجوع إليها. أما عودها إليك بعد هذا كله غلط، وعليك التوبة إلى الله مما فعلت، ومن اتصالك بها، عليك التوبة إلى الله، وعليك النفقة على أولادك، عليك أن تنفق عليهم، وتقوم بالواجب، تسكنها وأولادها، وتقوم بواجب النفقة عليها وعلى أولادها؛ لأنها تقوم عليهم، وتحضنهم، وتربيهم، فعليك أن تحسن إلى أولادك وإلى أمهم بقيامها بخدمتهم، وإحسانها إليهم، وعليك التوبة إلى الله مما فعلت، فقد أخطأت خطًأ كبيرًا حيث أعدتها إليك من دون فتوى شرعية من أهل العلم. والطلاق الأول والثاني، الأول ظاهره الوقوع؛ لأن ما ذكرت من العصبية ذكرت أنك تعي ما تقول، وأنه ليس هناك شيء يعني قد اشتد معك حتى أفقدك شعورك، أو حتى صرت شبه فاقد الشعور، ثم بعد هذا طلقتها عندما أشاروا عليك بالرجوع إليها، وطلقتها طلاقًا مكررًا ثلاثًا، فهذا كله يدل على أنك راغب في تركها، وأنك حريص على إبعادها، وأنه ليس هناك يعني غضب أزال شعورك، أو جعلك شبه فاقد للشعور، فالذي يظهر لنا من هذا الواقع أنها لا تحل لك، وأن الواجب عليك التوبة إلى الله مما سلف منك، والإحسان إليها. فإذا تزوجت زوجًا شرعيًا وطلقها بعد الدخول بها بعد وطئها حلت لك بنكاح جديد، لكن لا يكون بالتحليل، نكاح التحليل محرم، إذا تزوجها إنسان ليحللها لك هذا لا يجوز؛ لكن إذا تزوجها إنسان راغب فيها، ثم دخل بها، ووطئها، ثم طلقها، أو مات عنها، فإنها تحل لك بعد العدة بنكاح جديد. هذا هو الذي نرى في هذه المسألة، وهو ظاهر الأدلة الشرعية، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14193/حكم-ارجاع-المراة-بعد-طلاقها-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_698/nour_69803.mp3","categories":["الطلاق"]},{"id":15658,"question":"سؤاله الثاني يقول: أثناء إقامتي في بلدي حلفت على زوجتي: لو ذهبت إلى المكان الفلاني تكوني محرمة علي، ووقت بقائي هناك لم تذهب، ولكن الآن في غيابي لو ذهبت فما الحكم؟ وعلى من يكون الإثم؟ وماذا أفعل لو ذهبت وأنا لم أعلم بذلك؟","title":"حكم من قال لزوجته: أنت محرمة علي لو ذهبت إلى كذا","answer":"الجواب: إذا لم تعلم فالإثم عليها؛ لأن عليها السمع والطاعة، وعدم الخروج إلى المحل الذي منعتها منه إلا بأمر شرعي، ومسوغ شرعي، فإذا خرجت ولم تعلم فإن الإثم عليها، أما إذا علمت ففيه تفصيل:\nإن كنت أردت بهذا تحريمها إن فعلت هذا الشيء فعليك كفارة الظهار.\nوإن كنت أردت منعها فقط، أردت أن تمنعها من هذا الشيء لا تحريمها، فعليك كفارة اليمين: إطعام عشرة مساكين، أو كسوتهم، عشرة، يطعمهم على كل واحد يعطى كل واحد نصف صاع من التمر من قوت البلد من التمر، أو من الأرز، أو من الحنطة، أو من الذرة، إن كان قوت البلد، ويكفي عشرة، كل واحد يعطى نصف صاع، يعني: كيلو ونصف تقريبًا؛ لأن حكمها حكم اليمين، إذا كان يعني قال: هي محرمة إن فعلت كذا وكذا، إذا كان المقصود المنع وليس المقصود تحريمها تحريم الظهار، فإن عليه كفارة اليمين، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، مقداره كيلو ونصف تقريبًاً، أو كسوتهم على قميص قميص، أو إزار ورداء. أما إن كان المقصود تحريمها تحريم الظهار، تكون حرام عليه إذا فعلت، فعليه كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع، كيلو ونصف تقريبًا، قبل أن يمسها إذا كان قصده تحريمها، قبل أن يمسها. أما إن كان قصد بهذا الطلاق، أنها متى فعلت تطلق، فهذا يقع به طلقة واحدة، إذا كان قصده الطلاق، وأنها متى فعلت تطلق، يقع به واحدة، أما إن كان أراد المنع لم يرد طلاقًا ولا تحريمًا، وإنما أراد المنع فعليه كفارة اليمين فقط كما تقدم، نعم.\nالمقدم: لو فعلت ذلك وكان يقصد الطلاق فعلًا فتكون طالقًا من وقت الفعل أو من وقت؟\nالشيخ: إذا كان أراد الطلاق، إذا كان أراد إيقاع الطلاق تكون طالقة من وقت الفعل. المقدم: من وقت الفعل؟\nالشيخ: أما إذا كان أراد منعها فقط وتخويفها، ولم يرد منعها، ولا تحريمها، هذا فيه كفارة يمين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14203/حكم-من-قال-لزوجته-انت-محرمة-علي-لو-ذهبت-الى-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69909.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15661,"question":"هذا سؤال من المستمع أحمد بن أحمد غالب اليماني، من ينبع البحر، يقول: هو متزوج من امرأة وقد أنجبت له سبعة أولاد ذكورًا وإناثًا، وقد سافر عنها وتركها في بلده.الشيخ: ماذا؟المقدم: يقول: هو متزوج من امرأة، وقد أنجبت له سبعة أولاد ذكورًا وإناثًا، وقد سافر عنها، وتركها في بلده، وبعد مدة علم بأمر حصل منها أغضبه منها، فطلقها طلقتين بينه وبين نفسه، ولم يخبر أحدًا بذلك، فهل يقع مثل هذا الطلاق؟","title":"حكم من طلق زوجته دون معرفتها أو معرفة أحد","answer":"الجواب: نعم، ما دام تكلم به يقع، ما دام نطق به يقع يبقى لها واحدة، نعم.\nيبقى لها طلقة، ويقع عليها طلقتان. المقدم: يقع طلقتين؟ الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/14201/حكم-من-طلق-زوجته-دون-معرفتها-او-معرفة-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69907.mp3","categories":["الطلاق"]},{"id":15664,"question":"هذا سؤال من المستمع (م. ج الحارثي) من الرياض يقول: حصل بيني وبين زوجتي ذات يوم خلاف، وغضبت غضبًا شديدًا، وطلقتها بالثلاث كل طلقة لوحدها، بأن قلت: طالق، ثم طالق، ثم طالق، وقد أتتها العادة الشهرية في ذلك اليوم بعد الطلاق، وقد استفتيت أحد العلماء وأفتاني بجواز رجوعها، واسترجعتها بأن أشهدت شاهدين، وبعد مرور عام منعتها من أن تذهب إلى أحد الجيران، ولم تمتنع، وجاءتني وأنا غاضب، وطلقتها طلقتين، وأريد الآن أن أسترجعها مرة أخرى، وقد سمعت بأن طلاقي الأول لا يجوز أن أسترجعها بعده، فما هو الحكم الصحيح في هذا الموضوع؟أفيدوني، بارك الله فيكم.","title":"حكم طلاق المرأة في حال طهرها","answer":"الجواب: الطلاق الأول فيه تفصيل، فإن كان في طهر جامعتها فيه، فالصحيح: أنه لا يقع؛ لما ثبت عن ابن عمر -رضي الله تعالى عنهما-: أنه طلق امرأته وهي حائض، فقال له النبي ﷺ: راجعها وبين له أن الطلاق الشرعي يطلقها في في قبول عدتها، طاهرًا أو حاملًا؛ لقوله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ[الطلاق:1] قال العلماء: معنى ذلك: طلقوهن طاهرات من غير جماع، فإذا كان الطلاق وقع في طهر لم يجامعها فيه، وكان الغضب ليس بشديد فقد وقع الطلاق، والرجعة لا محل لها، الذي أفتاه في ذلك قد أفتاه بغير صواب. أما إن كان الطلاق وقع في شدة الغضب؛ لأن كان بينهما خصام شديد حتى استحكم عليه الغضب، واشتد به الغضب، ولم يملك نفسه في ذلك، فإن الطلاق حينئذٍ لا يقع، ويكون السائل حينئذٍ قد أمسك زوجته، ولا يسمى رجعة، وإنما ردها إليه لكون الطلاق لم يقع. والخلاصة: أن السائل المذكور له حالان:\nإحداهما: أن يكون طلق في طهر جامع فيه، فهذا لا يقع على الصحيح، وإن كان الجمهور على خلاف ذلك، لكن هذا قول جماعة من السلف أنه لا يقع؛ لحديث ابن عمر؛ لكونه طلق في غير العدة فلا يقع.\nالحال الثاني: أن يكون طلق في طهر لم يجامع فيه؛ لكنه قد اشتد به الغضب شدة واضحة، ليس غضبًا عاديًا، بل غضب شديد؛ لأنه طال النزاع بينهما، أو المسابة والمشاتمة، حتى استحكم به الغضب، واشتد به الغضب حتى قارب عدم الشعور بسبب شدة الغضب، فهذا لا يقع أيضًا على الصحيح؛ لأن شدة الغضب تجعل الإنسان كالمجنون وكالمعتوه لا يميز ما يضره وما ينفعه، ويكون كالمكره المدفوع بالقوة حتى أوقع الطلاق، في هاتين الحالتين هذا الطلاق غير واقع. أما إن كان الغضب ليس شديدًا، بل عاديًا، وكان طلقها في طهر لم يجامعها فيه، فإن الطلاق ماضٍ، وعليه أن يفارقها، ويبتعد عنها، والطلاق الأخير غير واقع؛ لأنه صادفها غير زوجة، وإن كان قد وطئها فوطؤه لها ليس في محله، ويكون الطلاق الأخير صادفها في غير نكاح فلا يقع، وتكون قد بانت بالطلاق الأول. وعليك -أيها السائل- التوبة من ردك إياها، وجماعك إياها بعد الطلاق، هذا هو الجواب عن هذا السؤال، وأرجو أن السائل فهمه، فإن السؤال هذا مهم، والجواب مهم. وأعيده مرة أخرى:\nأيها السائل! لك حالان:\nإحداهما: أن تكون طلقتها في طهر جامعتها فيه.\nأو في حالة ثانية: وهي شدة الغضب الشديد الذي يشبه أن تكون فاقد الشعور لشدة الغضب، بسبب طول النزاع أو المضاربة أو المشاتمة، فالطلاق في هاتين الحالتين غير واقع، وزوجتك معك وينظر في الطلاق الأخير.\nأما إن كنت طلقتها في طهر لم تجامع فيه، وغضب ليس بالشديد، فالطلاق قد وقع، وهي غير زوجة لك، وعليك أن تسرحها، والطلاق الأخير لا يقع عليها إن صادفها ليس بزوجة. أما الطلاق الثاني إذا صادف أنها زوجة، وأن الطلاق الأول لم يقع لشدة الغضب، أو لكون المرأة طلقت في طهر جامعتها فيه، أو للأمرين، وقع الطلاق في طهر جامعتها فيه، مع شدة الغضب أيضًا، فإن هذا لا يقع، والطلاق الثاني يقع، إذا كنت طلقتها طلقتين بألفاظ دل على ذلك بأن قلت: طالق ثم طالق، أو طالق وطالق، أو قلت: طالق طالق وأردت الطلقتين فإنها تقع الطلقتان. أما إن كنت قلت: طالق طالق، ولم تنو الطلقتين، قلت: طالق طالق بلفظك بغضب أو شبهه، ولكن لم تنو الطلقتين فإن الطلاق الثاني يكون مؤكدًا للطلاق الأول، ولا يقع به إلا واحدة، إذا قلت: طالق طالق بدون واو وبدون ثم وبدون شيء آخر؛ طالق طالق، هذا عند العلماء في حكم الطلقة الواحدة، ويكون اللفظ الثاني مؤكدًا للفظ الأول، ولا يقع به طلقة ثانية، أما إذا كنت قلت: طالق وطالق، أو طالق ثم طالق، أو أنت طالق أنت طالق، أو تراك طالق تراك طالق، ولم تنو تأكيدًا في قولك: تراك طالق، تراك طالق، ولم تنو إفهامًا لها، وهكذا لو قلت: طالق طالق ونويت الثنتين، فإن هذا يقع، يقع به الطلقتان: طالق وطالق، طالق ثم طالق، أنت طالق أنت طالق، تراك طالق، تراك طالق، يقع به اثنتان إلا إن كنت نويت بالثانية في قولك: طالق طالق نويت به تأكيدًا أو إفهامًا، أو ما نويت شيئًا في قولك: طالق طالق، فإنه لا يقع إلا واحدة، وهكذا إذا قلت: أنت طالق أنت طالق، أو تراك طالق، تراك طالق، ونويت التأكيد بالثانية أو الإفهام لم يقع إلا واحدة، وإلا فالأصل وقوع الثنتين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14207/حكم-طلاق-المراة-في-حال-طهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_700/nour_70003.mp3","categories":["الطلاق"]},{"id":15738,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: مقيم في المملكة (ص. ع. أ) يبدو من خطه أنه سوداني، يسأل تفسير قول الحق -تبارك وتعالى-: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا ذَلِكُمْ تُوعَظُونَ بِهِ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ [المجادلة:3] صدق الله العظيم.","title":"تفسير قوله تعالى: {وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ...}","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه الآية الكريمة تبين حكم الظهار، والمظاهرة معناها: أن يقول: زوجته كظهر أمه، أنت عليّ كظهر أمي، أو كظهر أختي، أو ظهر خالتي، أو ما أشبه ذلك، وهذه تسمى ظهار، والله أوجب فيه سبحانه الكفارة إذا عاد إلى زوجته بالعزم، إذا عزم أن يعود وجب عليه كفارة قبل أن يعود قَبْلِ أَنْ يَتَمَاسَّا[المجادلة: 3] وهي عتق رقبة مؤمنة ذكر أو أنثى، فإن عجز صام شهرين متتابعين، ستين يومًا قبل أن يمسها، فإن عجز أطعم ستين مسكينًا، لكل مسكين نصف صاع، من صاع النبي -عليه الصلاة والسلام-، مقداره كيلو ونصف تقريبًا من قوت البلد تمر أو رز أو حنطة من شعير أو قوت البلد قبل أن يمسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14318/تفسير-قوله-تعالى-والذين-يظاهرون-من-نساىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74101.mp3","categories":["الطلاق","الظهار","الرجعة"]},{"id":15763,"question":"هل هناك أشياء أحلها الله وهو يبغضها غير الطلاق؟","title":"هل هناك أشياء أحلها الله وهو يبغضها؟","answer":"الجواب: ما أذكر شيئًا، لا أذكر شيئًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14351/هل-هناك-اشياء-احلها-الله-وهو-يبغضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70710.mp3","categories":["الطلاق"]},{"id":15780,"question":"رسالة وصلت إلى البرنامج من المستمع خير الله درهم عايد، أبو التوم، من جمهورية مصر العربية، يقول: لي قريب متزوج من ثلاثين سنة، وهو كثير الحلف بالطلاق على أي شيء، يقول لزوجته: إذا لم تفعلي كذا، فأنت محرمة عليّ، أو يقول: طلاق منك لازم تفعلي كذا، رغم أنه لا ينوي طلاقها، بل من شدة الزعل، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"ما التوجيه لمن يكثر الحلف بالطلاق","answer":"الجواب: المشروع أن ينصح هذا الرجل، ويعلم حتى يدع هذا التصرف، وحتى لا يستعمل الطلاق والتحريم، ينصح ويوجه إلى الخير، أما كونه يقع أو لا يقع هذا محل نظر؛ إن كان قصده التهديد والمنع والتخويف فعليه كفارة يمين، ولا يقع، إذا خالفته قال: إن فعلت كذا فأنت طالق، أو محرمة فخالفته، وهو قصده التهديد والتحذير والترهيب، فإن عليه كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة كل واحد يعطى نصف الصاع، يعني: كيلو ونصف من الحنطة، أو من الرز، أو من التمر، أو تعشيه في البيت، أو تغديه في البيت، أو في المطعم لا بأس، أو يعطى كسوة يعني: عشرة، كفارة اليمين، هذا هو الذي ينبغي، ولكن ينصح ألا يتعاطى هذه الأمور بل يعالج الأمور بغير الطلاق، وبغير التحريم بالكلام الطيب، والترغيب والترهيب بدون الطلاق وبدون التحريم. فإن طلق يريد إيقاع الطلاق يقع الطلاق إذا خالفت شرطه، ويقع التحريم إذا خالفت شرطه، أما إذا كان المقصود تهديدها وتحذيرها وترهيبها فقط، ليس قصده الطلاق، فهذا مثلما تقدم، فيه كفارة يمين عند المخالفة، إذا خالفته ولم تنفذ ما قال، فعليه كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فإن كان عاجزًا فقيرًا لا يقدر، صام ثلاثة أيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14369/ما-التوجيه-لمن-يكثر-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74206.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15784,"question":"رسالة وصلت إلى البرنامج من المستمع خير الله درهم عايد، أبو التوم، من جمهورية مصر العربية، يقول: لي قريب متزوج من ثلاثين سنة، وهو كثير الحلف بالطلاق على أي شيء، يقول لزوجته: إذا لم تفعلي كذا، فأنت محرمة عليّ، أو يقول: طلاق منك لازم تفعلي كذا، رغم أنه لا ينوي طلاقها، بل من شدة الزعل، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"ما التوجيه لمن يكثر الحلف بالطلاق","answer":"الجواب: المشروع أن ينصح هذا الرجل، ويعلم حتى يدع هذا التصرف، وحتى لا يستعمل الطلاق والتحريم، ينصح ويوجه إلى الخير، أما كونه يقع أو لا يقع هذا محل نظر؛ إن كان قصده التهديد والمنع والتخويف فعليه كفارة يمين، ولا يقع، إذا خالفته قال: إن فعلت كذا فأنت طالق، أو محرمة فخالفته، وهو قصده التهديد والتحذير والترهيب، فإن عليه كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة كل واحد يعطى نصف الصاع، يعني: كيلو ونصف من الحنطة، أو من الرز، أو من التمر، أو تعشيه في البيت، أو تغديه في البيت، أو في المطعم لا بأس، أو يعطى كسوة يعني: عشرة، كفارة اليمين، هذا هو الذي ينبغي، ولكن ينصح ألا يتعاطى هذه الأمور بل يعالج الأمور بغير الطلاق، وبغير التحريم بالكلام الطيب، والترغيب والترهيب بدون الطلاق وبدون التحريم. فإن طلق يريد إيقاع الطلاق يقع الطلاق إذا خالفت شرطه، ويقع التحريم إذا خالفت شرطه، أما إذا كان المقصود تهديدها وتحذيرها وترهيبها فقط، ليس قصده الطلاق، فهذا مثلما تقدم، فيه كفارة يمين عند المخالفة، إذا خالفته ولم تنفذ ما قال، فعليه كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فإن كان عاجزًا فقيرًا لا يقدر، صام ثلاثة أيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14369/ما-التوجيه-لمن-يكثر-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74206.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15832,"question":"في ثاني أسئلته يقول: اختلفت أنا وزوجتي، وقلت لها: أنت مطلقة، أفتونا ماذا يلزمني؟","title":"مسائل الطلاق تراجع فيها المحاكم الشرعية","answer":"الجواب: عليك أن تراجع المحكمة في بلدكم أنت والمرأة ووليها، وهي تفتيكم -إن شاء الله-، أو تكتب لنا، ونحن ننظر في الأمر -إن شاء الله-، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14421/مساىل-الطلاق-تراجع-فيها-المحاكم-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57524.mp3","categories":["الطلاق"]},{"id":15861,"question":"سماحة الشيخ -حفظكم الله-، السائل يقول: ما حكم من قال لزوجته: أنت طالق -إن شاء الله-، هل تطلق الزوجة؟ وإن كان هناك طلاق ما نوعه؟جزاكم الله خيرًا.","title":"ما حكم من قال لزوجته: أنت طالق إن شاء الله؟","answer":"الجواب: إن كان قصده التعليق لا يقع الطلاق، إن كان قصده إيقاع الطلاق...، وقال: (إن شاء الله) من غير قصد تعليق، كان قصده إيقاع الطلاق تقع طلقة واحدة بهذا اللفظ: أنت طالق، أما إذا قال: (إن شاء الله) قصد التعليق، فهذا ما يقع شيء، مثل لو قال: والله -إن شاء الله- ما أفعل كذا، ما فيه شيء، يقول النبي ﷺ: من حلف فقال في يمينه: إن شاء الله؛ فلا حنث عليه نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14452/ما-حكم-من-قال-لزوجته-انت-طالق-ان-شاء-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57623.mp3","categories":["الطلاق"]},{"id":15909,"question":"هذا السائل خالد من مدينة إب، يقول في هذا السؤال -سماحة الشيخ-: أول أسئلتي أسأل وأقول: هل يصح طلاق المريض بالحالة النفسية؟","title":"حكم طلاق المريض المصاب بحالة نفسية","answer":"الجواب: الطلاق فيه تفصيل ونظر، إذا وقع شيء من هذا تراجع المحكمة، محكمة البلد الذي هو فيها المطلق، يراجع المحكمة مع زوجته ووليها حتى ينظر القاضي في ذلك. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14500/حكم-طلاق-المريض-المصاب-بحالة-نفسية","audio":"","categories":["الطلاق"]},{"id":15977,"question":"هذا سؤال من السائل (ع. ط. أ. هـ) من الرياض، يقول: أنا رجل متزوج، وقد غضبت من فعل فعلته زوجتي فلم أتمالك نفسي ثم قلت لها: أنت علي كظهر أمي، ثم كررت ذلك مرات ومرات، وطردتها إلى بيت أبيها لمدة ثلاثة أشهر، وبعد مضي هذه المدة راجعتها لفرط حبي لها، وقد أنجبت أربعة أطفال منذ رجوعها، وإلى اليوم ما زلت أذكر ذلك الموقف المشؤوم، علمًا بأني لم أكفر عن ظهاري طيلة هذه المدة.ثم نقلت من مقر عملي القديم إلى مدينة بعيدة عن موطني، ومقر أهلي، فتركت هذه الزوجة هي ووالدتي وأولادي منها، ثم قضيت تسعة أشهر بعيدًا عنهم، وبعد هذه المدة رجعت إليهم في عطلة سنوية وعند وصولي إليهم، وسؤالي عن أحوالهم، وطريقة حياتهم في مدة غيابي أجابني ابني الأكبر بأن فلانًا من الناس يقيم عندنا في بيتنا، علمًا بأن هذا الرجل المذكور واحدًا من أقارب زوجتي، ولكنه ليس من محارمها، ولا حتى ممن كانوا يزورون بيتي طيلة فترة وجودي، وعندما علمت ذلك من ابني سألت زوجتي عن سبب مجيء ذلك الرجل ليقيم في بيتي، وأنا غائب عنه، ودون إذني، فأجابت إجابة واهية تقول فيها: طلب مني ذلك، فاستحيت أن أمنعه؛ لأنه أحد أقاربي، وأنا أشك في صحة مقصدها في تصرفها الأول والثاني، وليس عندي ما يؤكد صدق ظنوني فيها، وعمومًا أطلب منكم رأيكم من الناحية الشرعية؛ لأنني لا أريد أن أتصرف إلا وفق الشريعة الإسلامية التي تحمي زوجتي مني، وتحميني منها، فهل أطلقها، وأشرد أولادي وبناتي أم أبقيها هي وأولادها وأتزوج غيرها أم أصبر معها حتى يأتي الله بالفرج؟علمًا بأنني أستطيع أن أعول أكثر من امرأة. وما الحكم في ظهاري الأول الذي أرجعتها بعده دون كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم الجماع قبل كفارة الظهار والخلوة بالأجنبية","answer":"الجواب: أولًا: ردك إياها وجماعك إياها بعد الظهار قبل الكفارة هذا منكر ومحرم، وقد عصيت الله في ذلك؛ لأن الله سبحانه إنما أباح لك ذلك بعد الكفارة، فعليك أن تتوب إلى الله  وأن تبادر بالكفارة قبل أن تقربها عليك أن تمسك عن قربانها حتى تبادر بالكفارة، وهي عتق رقبة مؤمنة، فإن لم تجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، ثلاثين صاعًا قبل أن تقربها، وعليك التوبة إلى الله -جل وعلا- والندم على ما مضى منك، والإقلاع من ذلك، والعزم ألا تعود في ذلك عزمًا صادقًا، هذا هو الواجب عليك من جهة الظهار، فإذا كنت لا تستطيع العتق ولا الصيام فعليك أن تطعم ستين مسكينًا، ستين فقيرًا ثلاثين صاعًا من التمر أو من الحنطة أو من الأرز لكل مسكين نصف صاع، مقدار كيلو ونصف تقريبًا، هذا هو الواجب عليك، وعليك أن تمسك عن جماعها حتى تخرج هذه الكفارة، الصيام إن قدرت أو الإطعام بعد ذلك، فهي مرتبة: أولًا العتق، ثم الصيام إن قدرت، ثم الإطعام فهو الأخير الإطعام، ستين مسكينًا ستين فقيرًا ثلاثين صاعًا من الحنطة أو التمر أو الأرز تفرقها عليهم، كل واحد له نصف الصاع؛ كيلو ونصف بالوزن. أما هذا الرجل الذي صار إلى البيت فلا شك أن هذا منكر، ويوجب الريبة، وهي قد أخطأت، وكذلك أهلك حين أقروها على هذا، أمك وأهلك الذين أقروها على بقائه في البيت، لكن إذا كانت هناك أسباب وجيهة لوجوده في البيت من حاجة، وعدم وجود مكان له يستقر فيه، والوالدة وأهلك قد رضوا بهذا لأجل ..... يأكل عندهم، وليس هناك ريبة، فالحمد لله.  أما إن كان هناك ريبة فإن الواجب طرده من البيت، والواجب توبيخها أيضًا، والإنكار عليها، ولا مانع من تأديبها التأديب المناسب الذي لا يجرح ولا يكسر، لا يجرح لحمًا ولا يكسر عظمًا، حتى لا تعود لمثل هذا، وزوجتك باقية في عصمتك. وإن كانت ألمت بشيء فعليها التوبة إلى الله فيما بينها وبين الله، والتوبة تجب ما قبلها، وهي زوجتك، وعليك ملاحظتها، وتوصي أهلك بملاحظتها، وعليك أن تنصحها كثيرًا، وتخوفها من الله ، وتعلمها أن الخلوة بالرجل الأجنبي أمر محرم، وعدم الحجاب عن الأجنبي أمر محرم، والزنا من أقبح الكبائر، وأعظم السيئات، فعليك أن تنصحها وتوجهها إلى الخير، وتعلمها ما ينفعها، وتوصي أهلك بذلك، وتوصي أهلها بذلك أيضًا، ولعل الله -جل وعلا- يهديها ويوفقها فتصلح الأحوال بينك وبينها، ونسأل الله لنا ولكم الهداية والتوفيق، نعم.\nالمقدم: لو حصل أولاد خلال هذه العشرة المحرمة بعد الظهار، وقبل أن يكفر، فما الحكم؟\nالجواب: هذا شيء آخر يسأل عنه أهل العلم إذا وقع شيء، يسأل أهل العلم القضاة في بلده، أو يكتب إلينا في ذلك، لا نستعجل في هذا، نعم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/14593/حكم-الجماع-قبل-كفارة-الظهار-والخلوة-بالاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_679/nour_67902.mp3","categories":["الطلاق","الظهار"]},{"id":15981,"question":"هذا سؤال من السائل (ع. ط. أ. هـ) من الرياض، يقول: أنا رجل متزوج، وقد غضبت من فعل فعلته زوجتي فلم أتمالك نفسي ثم قلت لها: أنت علي كظهر أمي، ثم كررت ذلك مرات ومرات، وطردتها إلى بيت أبيها لمدة ثلاثة أشهر، وبعد مضي هذه المدة راجعتها لفرط حبي لها، وقد أنجبت أربعة أطفال منذ رجوعها، وإلى اليوم ما زلت أذكر ذلك الموقف المشؤوم، علمًا بأني لم أكفر عن ظهاري طيلة هذه المدة.ثم نقلت من مقر عملي القديم إلى مدينة بعيدة عن موطني، ومقر أهلي، فتركت هذه الزوجة هي ووالدتي وأولادي منها، ثم قضيت تسعة أشهر بعيدًا عنهم، وبعد هذه المدة رجعت إليهم في عطلة سنوية وعند وصولي إليهم، وسؤالي عن أحوالهم، وطريقة حياتهم في مدة غيابي أجابني ابني الأكبر بأن فلانًا من الناس يقيم عندنا في بيتنا، علمًا بأن هذا الرجل المذكور واحدًا من أقارب زوجتي، ولكنه ليس من محارمها، ولا حتى ممن كانوا يزورون بيتي طيلة فترة وجودي، وعندما علمت ذلك من ابني سألت زوجتي عن سبب مجيء ذلك الرجل ليقيم في بيتي، وأنا غائب عنه، ودون إذني، فأجابت إجابة واهية تقول فيها: طلب مني ذلك، فاستحيت أن أمنعه؛ لأنه أحد أقاربي، وأنا أشك في صحة مقصدها في تصرفها الأول والثاني، وليس عندي ما يؤكد صدق ظنوني فيها، وعمومًا أطلب منكم رأيكم من الناحية الشرعية؛ لأنني لا أريد أن أتصرف إلا وفق الشريعة الإسلامية التي تحمي زوجتي مني، وتحميني منها، فهل أطلقها، وأشرد أولادي وبناتي أم أبقيها هي وأولادها وأتزوج غيرها أم أصبر معها حتى يأتي الله بالفرج؟علمًا بأنني أستطيع أن أعول أكثر من امرأة. وما الحكم في ظهاري الأول الذي أرجعتها بعده دون كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم الجماع قبل كفارة الظهار والخلوة بالأجنبية","answer":"الجواب: أولًا: ردك إياها وجماعك إياها بعد الظهار قبل الكفارة هذا منكر ومحرم، وقد عصيت الله في ذلك؛ لأن الله سبحانه إنما أباح لك ذلك بعد الكفارة، فعليك أن تتوب إلى الله  وأن تبادر بالكفارة قبل أن تقربها عليك أن تمسك عن قربانها حتى تبادر بالكفارة، وهي عتق رقبة مؤمنة، فإن لم تجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، ثلاثين صاعًا قبل أن تقربها، وعليك التوبة إلى الله -جل وعلا- والندم على ما مضى منك، والإقلاع من ذلك، والعزم ألا تعود في ذلك عزمًا صادقًا، هذا هو الواجب عليك من جهة الظهار، فإذا كنت لا تستطيع العتق ولا الصيام فعليك أن تطعم ستين مسكينًا، ستين فقيرًا ثلاثين صاعًا من التمر أو من الحنطة أو من الأرز لكل مسكين نصف صاع، مقدار كيلو ونصف تقريبًا، هذا هو الواجب عليك، وعليك أن تمسك عن جماعها حتى تخرج هذه الكفارة، الصيام إن قدرت أو الإطعام بعد ذلك، فهي مرتبة: أولًا العتق، ثم الصيام إن قدرت، ثم الإطعام فهو الأخير الإطعام، ستين مسكينًا ستين فقيرًا ثلاثين صاعًا من الحنطة أو التمر أو الأرز تفرقها عليهم، كل واحد له نصف الصاع؛ كيلو ونصف بالوزن. أما هذا الرجل الذي صار إلى البيت فلا شك أن هذا منكر، ويوجب الريبة، وهي قد أخطأت، وكذلك أهلك حين أقروها على هذا، أمك وأهلك الذين أقروها على بقائه في البيت، لكن إذا كانت هناك أسباب وجيهة لوجوده في البيت من حاجة، وعدم وجود مكان له يستقر فيه، والوالدة وأهلك قد رضوا بهذا لأجل ..... يأكل عندهم، وليس هناك ريبة، فالحمد لله.  أما إن كان هناك ريبة فإن الواجب طرده من البيت، والواجب توبيخها أيضًا، والإنكار عليها، ولا مانع من تأديبها التأديب المناسب الذي لا يجرح ولا يكسر، لا يجرح لحمًا ولا يكسر عظمًا، حتى لا تعود لمثل هذا، وزوجتك باقية في عصمتك. وإن كانت ألمت بشيء فعليها التوبة إلى الله فيما بينها وبين الله، والتوبة تجب ما قبلها، وهي زوجتك، وعليك ملاحظتها، وتوصي أهلك بملاحظتها، وعليك أن تنصحها كثيرًا، وتخوفها من الله ، وتعلمها أن الخلوة بالرجل الأجنبي أمر محرم، وعدم الحجاب عن الأجنبي أمر محرم، والزنا من أقبح الكبائر، وأعظم السيئات، فعليك أن تنصحها وتوجهها إلى الخير، وتعلمها ما ينفعها، وتوصي أهلك بذلك، وتوصي أهلها بذلك أيضًا، ولعل الله -جل وعلا- يهديها ويوفقها فتصلح الأحوال بينك وبينها، ونسأل الله لنا ولكم الهداية والتوفيق، نعم.\nالمقدم: لو حصل أولاد خلال هذه العشرة المحرمة بعد الظهار، وقبل أن يكفر، فما الحكم؟\nالجواب: هذا شيء آخر يسأل عنه أهل العلم إذا وقع شيء، يسأل أهل العلم القضاة في بلده، أو يكتب إلينا في ذلك، لا نستعجل في هذا، نعم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/14593/حكم-الجماع-قبل-كفارة-الظهار-والخلوة-بالاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_679/nour_67902.mp3","categories":["الطلاق","الظهار"]},{"id":16004,"question":"من أبو ظبي رسالة بعث بها مستمع من هناك يقول: أحمد شيخو أبو جهاد الأخ أحمد له قضية مطولة، ملخص ما فهمته من هذه القضية سماحة الشيخ يقول: إن أهله يطلبون منه أن يطلق زوجته، وهو يحبها، وله منها أولاد وبنات، بم توجهونه؟جزاكم الله خيرًا.","title":"هل يطيع الزوج أهله في طلاق زوجته؟","answer":"الجواب: إن كانت تؤذيهم وتضرهم فانصحها حتى تتوب وترجع عن أذاها، فإذا رجعت وتابت فالحمد لله، أما إن كانت لا تؤذيهم، ولا تضرهم، فلا يلزمك طاعتهم إنما الطاعة في المعروف فإن استمرت في الأذى، ولم ترجع، فالواجب عليك طلاقها إرضاء لوالديك، إذا كان الآمر والديك. أما إذا كان الآمر غير الوالدين فلا يلزمك طاعة أخ أو غيره، لكن إذا كان الآمر لك بالطلاق والديك، فأمرهما عظيم، وبرهما متعين، إذا كان لذلك سبب وجيه من كونها تؤذيهما بكلامها أو أفعالها. المقصود: إذا كان عليهما أذى منها فطلقها إلا أن تتوب، وتدع الأذى، أما إذا كانت مستمرة في الأذى، فإنك تسمع وتطيع والديك إذا لم يسمحا إلا بطلاقها، لكن إذا كانت مطيعة مستقيمة، وإنما أبغضاها فقط، فإنه لا يلزمك طاعتهما؛ لأن هذا ليس من المعروف إنما الطاعة في المعروف، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14629/هل-يطيع-الزوج-اهله-في-طلاق-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74713.mp3","categories":["الطلاق"]},{"id":16026,"question":"له سؤال آخر أيضًا في باب الطلاق، يقول: في إحدى مشاجراتي مع زوجتي قلت لها: اعتبري نفسك مطلقة، فهل هذا طلاق؟ ولو فرض أن هذا طلاق فما هو الحل؟ جزاكم الله خيرًا.الشيخ: أعد.المقدم: يقول: في أحد مشاجراتي مع زوجتي قلت لها: اعتبري نفسك مطلقة، فهل هذا طلاق؟ ولو فرض أن هذا طلاق فما هو الحل؟ جزاكم الله خيرًا.","title":"حكم قول الزوج لزوجته: اعتبري نفسك مطلقة","answer":"الجواب: نعم يعتبر طلاقًا، ولكن طلقة واحدة، إذا كان ما سبق طلقتان؛ له مراجعتها ما دامت في العدة، فإذا قال: اعتبري نفسك مطلقة أو طالقة يقع بذاك واحدة، طلقة واحدة، وله مراجعتها ما دامت في العدة، إذا كان لم يطلقها قبل ذلك طلقتين. أما إذا كانت قد طلقها طلقتين فهنا تكون هذه الثالثة، وتبين، ولا تحل له إلا بعد زوج وإصابة، يعني: بعد زوج شرعي، وإصابة، يعني: وجماع من غير تحليل، فهو يعني: نكاح شرعي، لا يقصد به التحليل. لكن لو طلقها في طهر جامعها فيه، وليست حاملًا، ولا آيسة، لا يقع الطلاق على الصحيح، وهكذا لو طلقها في حيض أو نفاس لا يقع الطلاق؛ لأنه ثبت عن النبي ﷺ من حديث ابن عمر -رضي الله عنهما- أن ابن عمر طلق امرأته وهي حائض، فأنكر عليه النبي ﷺ وأمره أن يراجعها، وقال: أمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شئت طلق، وإلا أمسك وقال له: طلقها قبل أن تمسها هذا يدل على أن الطلاق في الطهر الذي مسها فيه جامعها فيه لا يقع، وهذا هو الصحيح، وهو قول جماعة من العلماء، وهكذا إذا طلقها في الحيض، أو في النفاس لا يقع. أما إن طلقها وهي حامل، أو في طهرٍ ما جامعها فيه، أو في طهر جامعها فيه، لكنها حبلى، أو آيسة يقع الطلاق في هذه الأحوال، في حال الحمل يقع الطلاق، وفي حال طهر لم يجامعها فيه، أو جامعها فيه لكنها حبلى أو آيسة يقع الطلاق، ما لم يمنع مانع من كونه اشتد غضبه شدة تغير شعوره، أو يمنع مانع من جهة أنه سكران تكلم بغير عقل لا يشعر بما صدر منه لكونه سكران، أو أصابه شيء غير عقله، فهذا لا يقع. من شرط وقوع الطلاق أن يكون يعقله الزوج، فأما إذا تعاطى شيئًا يفقده عقله، أو غضب غضبًا يفقده عقله وشعوره ما يضبط ما يقع منه، أو يضبط لكن غلب عليه الغضب واشتد به الغضب من أجل مضاربة بينهما، أو مسابة بينهما، فالصحيح: أنه لا يقع في هذه الحالة لشدة الغضب كالذي زال عقله، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14653/حكم-قول-الزوج-لزوجته-اعتبري-نفسك-مطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80102.mp3","categories":["الطلاق"]},{"id":16158,"question":"يقول: رجل يكثر الحلف بالطلاق، هل أكون آثمًا إذا سرت معه؟ وجهوني جزاكم الله خيرًا.","title":"توجيه لمن يرافق كثير الحلف بالطلاق","answer":"الجواب: ينصح ويوجه إلى الخير، ينصح بعدم الحلف بالطلاق، يحلف بالله، لا يطلق، يترك الطلاق عنه، عليكم أن توصوه بالخير، وترشدوه إلى الخير حتى لا يعتاد الطلاق، إذا كان ولابد يحلف بالله يقول: والله ما تفعل كذا، والله لا أفعل كذا، ويترك الطلاق؛ لأن الطلاق قد يترتب عليه وقوعه، والتفريق بينه وبين أهله، فينبغي له الحذر من استعمال الطلاق حتى لا يندم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14826/توجيه-لمن-يرافق-كثير-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75009.mp3","categories":["الطلاق"]},{"id":16247,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر فيها عدم ذكر اسمه إلا بقوله: المرسل عوض يقول: يا سماحة الشيخ! لدي عم أنا متزوج ابنته، وهو لا يصلي، وأنا محتار كيف أعامله، فهل أطلق ابنته من أجل أبيها؟ علمًا بأنها مؤدية للصلاة، ولا ذنب لها، وجهوني جزاكم الله خيرًا.","title":"حكم طلاق المرأة لأن والدها لا يصلي","answer":"الجواب: يقول الله سبحانه: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] ويقول النبي ﷺ: لا يجني الجاني إلا على نفسه فلا تطلقها من أجل أبيها، ما دامت مستقيمة؛ فالحمد لله، الزمها، وأحسن إليها، وعاملها بما ينبغي من المعاملة الطيبة: خياركم خياركم لنسائهم فعليك بالخلق الطيب، والمعاملة الحسنة مع زوجتك. أما أبوها فعليك أن تدعو له بالهداية، ادع الله له بالهداية، وانصحه كثيرًا، أنت ومن معك من إخوانك الطيبين، تذهبون إليه.. تنصحونه؛ لأن أداء الصلاة أمر مفترض، والصلاة ركن من أركان الإسلام، بل هي عمود الإسلام. فعليك أنت وإخوانك الطيبين أن تنصحوه، وتوجهوه إلى الخير، وأن تلاحظوه دائمًا، ولعل الله يهديه على أيديكم، فإن أبى؛ فيستحق الهجر؛ يهجر.. لا تدعوه لوليمة، ولا تجب لدعوته إن دعاك حتى يتوب. لكن مهما استطعت أن تنصح أنت وإخوانك الطيبون من جيرانه وأقاربه؛ فاحرصوا، يقول النبي ﷺ في الحديث الصحيح: لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم ويقول ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه وأنتم تستطيعون -بحمد الله- باللسان؛ فأنكروا عليه باللسان، وأشيروا عليه، وانصحوه، وكرروا عليه؛ لعل الله يجعل الهداية على أيديكم، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14934/حكم-طلاق-المراة-لان-والدها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75202.mp3","categories":["الطلاق","نصائح وتوجيهات"]},{"id":16389,"question":"رسالة من أحد الإخوة المستمعين يقول: كان عندي شيء، وحلفت بالطلاق أن لا أبيعه، وبعد ذلك احتجت لقيمته؛ ثم بعته، هل وقع الطلاق؟ ثم حصل لي قضية أخرى، وقلت لزوجتي: إني لن أفعل الشيء الفلاني؛ لأنه حرام، وحلفت ألا أفعله، لكني فعلته بعد أن حلفت بالطلاق، ما الحكم فيما فعلت، وهل زوجتي حلال؟ جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق على عدم فعل شيء ثم فعله","answer":"الجواب: إن كان المقصود إيقاع الطلاق؛ وقع الطلاق بالفعل بالبيع، وبالشيء الذي طلقت ألا تفعله، أما إذا كان المقصود: الامتناع من البيع، والامتناع من الفعل الذي أردت ألا تفعله، ليس قصدك إيقاع الطلاق، إنما قصدك التشديد على نفسك بأن تمتنع، وتحذر هذا الشيء، ثم فعلته؛ فعليك كفارة يمين: وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز؛ صام ثلاثة أيام، هذا إذا كان قصده الامتناع من البيع، والامتناع من الشيء الذي أردت ألا تفعله، وليس قصدك إيقاع الطلاق، أما إن كان قصدك الامتناع، وإيقاع الطلاق جميعًا؛ فإنه يقع بهذا طلقة على الزوجة، إذا فعلت ما حلفت على تركه. وننصحك بألا تعتاد هذه الأمور، وأن تجتنب الطلاق، وإذا دعت الحاجة؛ تكتفي باليمين، تقول: والله ما أفعل كذا، أو والله لأفعلن كذا، يكفي اليمين فيها كفاية، أما... الطلاق فهو شيء خطير، وربما فات ذلك زوجتك، وأنت لا تشعر بسبب تساهلك بهذا الأمر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15106/حكم-من-حلف-بالطلاق-على-عدم-فعل-شيء-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75420.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":16452,"question":"المستمع عبد رب النبي أحمد عبد المقصود يونس بعث برسالة، وضمنها سؤالًا واحدًا في الطلاق، يقول فيه: رجل طلق زوجته الطلقة الأولى، ثم راجعها، ثم الثانية، وراجعها، ثم الثالثة؛ فهل تحل له، أم لا؟","title":"هل تحل الزوجة لزوجها بعد الطلقة الثالثة؟","answer":"الجواب: يقول الله -جل وعلا-: فَإِنْ طَلَّقَهَا فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230] إذا طلقها الثالثة انتهت، هي آخر شيء، الطلاق الشرعي واحدة بعد واحدة، يطلق واحدة، ثم يراجع، ثم إذا أطلق الثانية، وله رغبة؛ راجعها، ثم الثالثة ما بعدها رجعة، إذا كانت كل واحدة واقعة. أما إذا كان هناك مانع من وقوع بعض الطلقات، هذه ينظر فيه من جهة المفتي، يعرض أمره على المفتي، على العالم الشرعي؛ حتى ينظر في كيفية وقوع الطلقات الثلاث، فإن كان هناك أسباب تمنع وقوع بعض هذه الطلقات؛ أفتاه وأخبره، أما إذا كانت الطلقات واقعة؛ طلقها طلقة واقعة، وراجعها، ثم طلقها طلقة واقعة، ثم راجعها، ثم طلقها الثالثة؛ حرمت عليه حتى تنكح زوجًا غيره. أو قال: طالق، ثم طالق، ثم طالق وهي حبلى، أو في طهر لم يجامعها فيه؛ فإنها تحرم عليه بذلك، وتكون قد بانت منه، أما إذا كانت في طهر جامعها فيه، أو في حال الحيض والنفاس؛ هذه مسألة خلاف بين أهل العلم، أكثر العلماء على أنها تقع الطلقة، تقع الطلاق في الحيض والنفاس، وفي الطهر الذي حصل فيه جماع، وليست حبلى، ولا آيسة. وذهب بعض أهل العلم إلى أنها لا تقع؛ لأنه صح عن النبي ﷺ من حديث ابن عمر -رضي الله عنهما- أنه أمره بمراجعتها لما طلقها وهي حائض، وقال لأبيه عمر: مره فليراجعها، ثم ليمسكها حتى تطهر، ثم تحيض ثم تطهر، ثم يطلقها -إن شاء- قبل أن يمسها وفي رواية: أنه لم يرها شيئًا، قال: ... لم يرها شيئًا، وقال: إذا طهرت؛ فليطلق، أو ليمسك. هذا الراجح: أنها لا تقع في هذه الحال في الحيض والنفاس، وفي الطهر الذي حصل فيه جماع، وليست حبلى ولا آيسة، إلا إذا حكم به حاكم، يعني: حكم به قاضي، وأمضاه تبع الجمهور؛ فإنه يمضي؛ لأن حكم الحاكم يرفع الخلاف. والواجب على المؤمن ألا يطلق إلا على الوجه الشرعي، لا يعجل في الطلاق، الواجب أن يطلق طلاقًا شرعيًا في حال كونها حاملًا، أو في حال كونها طاهرًا طهرًا ليس فيه جماع، هذا هو الطلاق الشرعي، إلا إذا كانت آيسة، كبيرة السن؛ فإنه يطلقها متى شاء، ليس لها وقت بدعة لكبر سنها. وهكذا إذا كانت حاملًا له أن يطلقها لقوله ﷺ لابن عمر: طلقها طاهرًا، أو حاملًا يعني: طاهرًا طهرًا لا جماع فيه، أو حاملًا. وبكل حال، فالمشروع للمؤمن إذا أراد الطلاق أن يطلق عن بصيرة، وألا يعجل، فإذا كانت حاملًا وأراد طلاقها؛ لا بأس، أو كانت في طهر لم يجامع فيه؛ فلا بأس، أما في الحيض، أو في النفاس؛ فالطلاق بدعة لا يجوز، أو في طهر جامع فيه، وهي ليست حبلى، ولا آيسة، بل هي شابة؛ فإن الطلاق لا يجوز في هذه الحالة، بل هو بدعة؛ لحديث ابن عمر المذكور، والله يقول -جل وعلا-: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] قال العلماء: معنى لعدتهن معناه: أن يكن طاهرات من غير جماع، أو حبالى، هذا معنى لعدتهن فطلقوهن لعدتهن أن تكون طاهرة لم يجامعها، أو آيسة، أو حاملًا، هذا الطلاق للعدة. فالواجب على المؤمن أن يتحرى الطلاق الشرعي، وأن يمتثل أمر الله  وأن يحذر الطلاق البدعي الذي أنكره النبي ﷺ وغضب على من فعله، وبذلك لا يقع في الحرج، إذا تحرى السنة، لم يقع في الحرج، نعم. المقدم: جزاكم الله خيرًا من العجائب -سماحة الشيخ- أن تتفضلوا بالحديث عن هذا الموضوع، وأمامي رسالة من المستمع (ب. م. م) من الدمام يسأل ويقول: هل يقع طلاق غير السنة أي: في طهر تماس الزوجان فيه؟ جزاكم الله خيرًا. الشيخ: تقدم الكلام على هذا، وأنه لا يقع على الصحيح إذا كان في طهر جامعها فيه، وليست حبلى ولا آيسة، أما إذا كانت حاملًا أو آيسة؛ يقع الطلاق، ولو جامعها، لكن إذا كانت في طهر لم يجامعها فيه، وهي ليست حبلى، وليست آيسة؛ فإنه لا يقع على الصحيح؛ لحديث ابن عمر أمره أن يطلقها قبل أن يمسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15176/هل-تحل-الزوجة-لزوجها-بعد-الطلقة-الثالثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75520.mp3","categories":["الطلاق","الرجعة"]},{"id":16486,"question":"ما حكم الطلاق الرجعي سماحة الشيخ، مع البيان على ذلك؟ وما حكم الطلاق الثلاث في لفظ واحد؟","title":"حكم الطلاق الرجعي وطلاق الثلاث بلفظ واحد","answer":"الجواب: الطلاق الرجعي بينه الله -جل وعلا- قال : وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلاثَةَ قُرُوءٍ وَلا يَحِلُّ لَهُنَّ أَنْ يَكْتُمْنَ مَا خَلَقَ اللَّهُ فِي أَرْحَامِهِنَّ إِنْ كُنَّ يُؤْمِنَّ بِاللَّهِ وَالْيَوْمِ الآخِرِ [البقرة:228]، ثم قال سبحانه: وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَلِكَ إِنْ أَرَادُوا إِصْلاحًا [البقرة:228]. فإذا طلقها طلقة واحدة بعدما دخل بها، بعدما خلا بها، أو جامعها طلقة واحدة هذه رجعية؛ فله أن يراجعها قبل أن تخرج من العدة، وهكذا لو طلقها طلقتين؛ فله أن يراجعها قبل خروجها من العدة إذا أراد الإصلاح، لا الإضرار بها، والإيذاء. أما إذا كان ما خلا بها، ولا دخل بها، فإنه إذا طلقها ولو طلقة واحدة؛ بانت منه بينونة صغرى، لا يحل له الرجوع إليها إلا بعقد جديد، إذا كان عقد، ثم طلق قبل أن يخلو، وقبل أن يجامع، فهذه طلقة واحدة تبينها منه بينونة صغرى، كما قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا [الأحزاب:49] فإذا طلقها قبل الدخول، والخلوة؛ فليس لها عدة، وليس له الرجوع إليها إلا بعقد جديد.  أما إذا كان طلقها بعد الخلوة، أو بعد الوطء طلقة واحدة؛ فله الرجوع إليها في العدة من دون عقد، وهكذا إذا طلق طلقتين؛ فله الرجوع إليها في العدة من دون عقد. أما إذا طلقها الثالثة؛ فإنها تحرم عليه، وتبين بينونة كبرى، ولا تحل له إلا بعد زوج يطؤها، لقوله -جل وعلا-: فَإِنْ طَلَّقَهَا [البقرة:230] يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230] يعني: نكاح رغبة، لا نكاح تحليل، ويطأها، هذا هو الحق. فإذا طلقها الثالثة؛ فإنها تعتد، وتحرم عليه حتى تنكح زوجًا غيره نكاح رغبة، لا نكاح تحليل، ويطأها، ثم يطلقها، أو يفارقها بخلع، أو موت؛ فله الرجوع إليها بعد ذلك، إذا تزوجها زوج آخر، ووطئها نكاح رغبة، لا نكاح تحليل، ثم فارقها بموت، أو غيره؛ فله الرجوع إليها بعقد جديد، الذي طلقها الثالثة.  أما إذا طلقها بالثلاث بكلمة واحدة؛ فالأرجح أنها تحسب واحدة، إذا قال: هي طالق بالثلاث، أو طالق طالق طالق بهذا اللفظ، وليس له نية في التكرار؛ فإنها تحسب واحدة، إذا قال طالق بالثلاث، أو طالق طالق طالق، وليس له نية في التكرار، إنما كرر للتأكيد، أو بلا نية؛ فهذا تحسب واحدة على الصحيح؛ لأنه صح عن النبي ﷺ من حديث ابن عباس: أن طلاق الثلاث بلفظ واحد يحتسب طلقة واحدة، إذا قال بالثلاث، أو طالق بالثلاث، أو أنت بالثلاث؛ تحسب واحدة، وهكذا إذا قال: طالق طالق طالق، ولا نية له تحسب واحدة، وله مراجعتها ما دامت في العدة. أما إذا قال: طالق ثم طالق ثم طالق، أو أنت طالق، أنت طالق، أنت طالق؛ فهذه تحسب ثلاثًا، إلا إذا نوى التأكيد بقوله: أنت طالق أنت... نوى التأكيد، أو الإفهام تكون واحدة، كما لو قال: طالق طالق طالق، وليس له نية؛ تحسب واحدة. أما إذا قال: أنت طالق، أنت طالق، أنت طالق، ونيته الثلاث، أو ليس له نية تفهيم، ولا تأكيد تكون ثلاثًا، أو قال: طالق ثم طالق ثم طالق، أو طالق وطالق وطالق؛ كلها تحسب ثلاثًا، تبين منه حتى تنكح زوجاً غيره، هذا الأصل، هذا المعتمد، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15194/حكم-الطلاق-الرجعي-وطلاق-الثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58214.mp3","categories":["الطلاق"]},{"id":16488,"question":"ما هو الطلاق البدعي يا سماحة الشيخ؟ وهل هناك طلاق بدعي؟","title":"صور الطلاق البدعي","answer":"الجواب: البدعي طلاق بالثلاث، أو في الحيض، أو في النفاس، أو في طهر جامعها فيه، وهي ليست حاملًا، ولا آيسة، يسمى: بدعيًا، إذا طلقها بالثلاث طلاقًا بدعيًا، أو طلقها في الحيض، أوفي النفاس طلاقًا بدعيًا، أو طلقها في طهر جامعها فيه، وليست حبلى، ولا آيسة يسمى طلاقًا بدعيًا، أما إذا كانت آيسة؛ فليس بدعيًا، أو كانت حاملًا فليس بدعيًا، نعم. المقدم: أحسن الله إليكم، إذًا يا سماحة الشيخ إذا طلقت المرأة وهي حامل يعتبر الطلاق؟ الشيخ: طلاقًا شرعيًا نعم؛ لأن النبي ﷺ قال لابن عمر: طلقها طاهرًا، أو حاملًا صلى الله عليه وسلم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15196/صور-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58215.mp3","categories":["الطلاق"]},{"id":16493,"question":"هذا السائل خالد من مدينة إب، يقول في هذا  سماحة الشيخ! أول أسئلتي أسأل وأقول: هل يصح طلاق المريض بالحالة النفسية؟","title":"حكم طلاق المريض نفسيًّا","answer":"الجواب: الطلاق فيه تفصيل، ونظر، إذا وقع شيء من هذا؛ تراجع المحكمة، محكمة البلد التي هو فيها، المطلق، يراجع المحكمة مع زوجته ووليها حتى ينظر القاضي في ذلك. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15205/حكم-طلاق-المريض-نفسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58220.mp3","categories":["الطلاق"]},{"id":16729,"question":"رسالة وصلت إلى البرنامج من الطائف، وباعثها المستمع محمد أحمد إبراهيم، رسالته بدأها بمقدمة يقول: بسم الله الرحمن الرحيم، بعد تحيتكم بتحية الإسلام، فسلام الله عليكم ورحمته وبركاته، وكل عام وأنتم بخير، وبعد يطيب لي أن أكتب هذه الرسالة البسيطة معبرًا عن كل مشاعر الحب والتقدير لهذا البرنامج العظيم؛ لمقدار ما يقدمه من إيضاح وتوضيح لكثير من الأسئلة والمواضيع الغامضة، أو الغير مدركة لكثير من الإخوة المسلمين المؤمنين، وديننا يحث على العلم والمعرفة، ولا حرج في الدين، والعلم طالما هناك منفعة الجميع، ومزيدًا من تقديري، ومشاعري للإخوة الذين يساهمون في إنتاج هذا البرنامج، جزى الله الجميع خير الجزاء، ولا أطيل عليكم فأبدأ أسئلتي، بدأ أسئلته بالسؤال التالي سماحة الشيخ فيقول: عندنا كثير من الناس حينما يحلف يقول: والنبي، هل الحلفان بالنبي ﷺ يعتبر شركًا بالله؟ وهل إذا لم يكن شركًا عليه إثم؟ أم هو خير؟ أرجو التوضيح، أو الحلفان بغير ذلك، كمن يقول: وحياتي، بشرفي، وغير ذلك، ومن الناس من يقول لمن يريد أن يأخذ منه شيئًا بفضل الله، ثم بفضل كذا وكذا ستنقضي حاجتي، وجهوني إلى هذه الأمور، جزاكم الله خيرًا.","title":"هل الحلف بالنبي شرك بالله؟","answer":"الجواب: أولًا: جزاك الله خيرًا عن دعواتك، وعما ذكرت من السرور بهذا البرنامج، لا شك أنه برنامج مفيد، وعظيم النفع، فنسأل الله أن ينفع به المسلمين، وأن يضاعف المثوبة لمن يقوم عليه، وأن يمنحهم التوفيق للعلم النافع، والعمل الصالح. أما سؤالك فلا ريب أنه من الشرك، الحلف بالنبي ﷺ أو بالأولياء، أو بالملائكة، أو بالجن، أو بالنجوم، أو بشرف فلان، أو بحياته، كله لا يجوز؛ لقول النبي ﷺ: من كان حالفًا؛ فليحلف بالله، أو ليصمت، ويقول أيضًا -عليه الصلاة والسلام-: من كان حالفًا؛ فلا يحلف إلا بالله، أو ليصمت ويقول -عليه الصلاة والسلام-: من حلف بشيء دون الله؛ فقد أشرك ويقول أيضًا -عليه الصلاة والسلام-: من حلف بغير الله؛ فقد كفر، أو أشرك ويقول أيضًا -عليه الصلاة والسلام-: من حلف بالأمانة فليس منا، ويقول: من حلف باللات والعزى فليقل: لا إله إلا الله. والمقصود: أن الحلف بغير الله أمر لا يجوز، وهو من المحرمات الشركية، لكنه شرك أصغر، ليس بشرك أكبر. فالواجب على المسلمين الحذر من ذلك، وأن يكون الحلف بالله وحده، أو بصفة من صفاته، ولا يجوز الحلف بغير الله كائنًا من كان، لا بالأنبياء، ولا غيرهم، ومن فعل هذا؛ فعليه التوبة إلى الله، والإنابة إليه، والندم على ما مضى، والعزم الصادق ألا يعود في ذلك. والله -سبحانه- بعث الرسل -عليهم الصلاة والسلام- لبيان الحق، وإيضاح الحق، وختمهم بمحمد -عليه الصلاة والسلام-وقد أوضح في ذلك، قد أوضح ما يجب في ذلك، وكان الناس في أول الإسلام، وفي أول الهجرة يحلفون بآبائهم، ثم نهاهم النبي ﷺ وقال: لا تحلفوا بآبائكم، ولا بأمهاتكم، ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون. فإن قصد بالحلف بغير الله أن هذا المحلوف به يتصرف في الكون، أو أنه يصلح أن يعبد من دون الله؛ صار شركًا أكبر، نسأل الله العافية. أما إذا جرى على لسانه من غير قصد، بل لمحبته لمحبوبه، أو لتعظيمه له فقط من دون أن يعتقد فيه أنه يصلح يعبد من دون الله، أو أنه يتصرف في الكون؛ هذا شرك أصغر يجب تركه، والتوبة إلى الله منه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، آخر فقرة في سؤاله يقول: من قال: سأفعل كذا، أو فعل كذا بفضل الله، ثم بفضل فلان؟ الشيخ: هذا لا حرج فيه، قال: بفضل الله، ثم بفضل فلان، أو قال: بالله، ثم فلان، أو قال: هذا من الله، ثم من فلان، أو أنا أستعيذ بالله، ثم بك؛ فلا حرج فيه، ليس من الشرك؛ لأنه قال: ثم بك، نعم. المقدم: جزاكم الله خيرًا، أيضًا الحلف بالشرف كما يذكر، أو بحياة الإنسان؟ الشيخ: كله منكر، كله لا يجوز، بشرف فلان، أو بحياة فلان، أو بحياة النبي، أو شرف النبي؛ ما يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15483/هل-الحلف-بالنبي-شرك-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76111.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":16819,"question":"سماحة الشيخ! هذه أختنا السائلة تقول: سؤالي يا سماحة الشيخ هو أنها فتاة متزوجة من رجل دائمًا ما يحلف بالطلاق في جميع أفعاله، وأقواله، وكثيرًا ما يردد هذه الكلمة: علي الطلاق، تقول: هل يقع الطلاق؟ فأنا أذهب إلى أهلي، وأكون حاملًا، وأضع مولودًا، وأرجع عند زوجي، هل أأثم في هذه الحياة معه؟","title":"حكم من يكثر من الحلف بالطلاق","answer":"الجواب: الواجب إذا حصل من الزوج الطلاق أن يستفتي، وإذا طلق اذهبي لأهلك حتى يستفتي أهل العلم، ولا ينبغي للرجل أن يستعمل الطلاق، وأن يتساهل في الطلاق، فالطلاق هو عنوان الفرقة، فالواجب على المؤمن أن يحفظ لسانه، وأن يصونها عما لا ينبغي، وأن يحذر الطلاق إلا على بصيرة، إذا رأيت الفراق؛ لا بأس، لكن كونه يستعمل الطلاق على غير بصيرة، ويتلاعب بالطلاق، هذا لا يجوز، في الحديث: أبغض الحلال إلى الله الطلاق.  ثم الطلاق هو وسيلة الفراق، فالواجب على المؤمن أن يحفظ لسانه، وأن يصون لسانه عما لا ينبغي، وإذا طلق؛ فالواجب عليه سؤال أهل العلم؛ حتى يتبصر، وهي عليها أن تذهب إلى أهلها، وأن تمتنع منه حتى يسأل أهل العلم عما وقع منه، وحتى يفتيه أهل العلم في طلاقه، نسأل الله للجميع الهداية. المقدم: اللهم آمين، أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15563/حكم-من-يكثر-من-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58516.mp3","categories":["الطلاق"]},{"id":16824,"question":"ننتقل بعد هذا إلى المملكة الأردنية الهاشمية عمان، عبر رسالة وصلت إلى البرنامج من المستمع همام العبادي فيما يبدو، الأخ همام له سؤال يقول: أهدى قريب زوجتي لنا هدية، فلما رأيتها قلت: علي الحرام لا تدخل بيتي، فأبقوها عند الجيران، وفي اليوم الثاني أدخلت إلى بيتي، واستعملناها، واستفدنا منها، ما هو كفارة ذلك القول؟ جزاكم الله خيرًا.","title":"حكم من حلف ألا تدخل بيته هدية معينة ثم دخلت","answer":"الجواب: أولًا: هذا لغو لا يجوز، تحريم الحلال لا يجوز، عليك التوبة إلى الله من ذلك. الأمر الثاني: على حسب نيتك، إن كنت قصدت الامتناع منها، ولم تقصد تحريم زوجتك، ولا طلاقها؛ فعليك كفارة يمين، والحمد لله، إطعام عشرة مساكين، أو كسوتهم.. عشرة، كل واحد له نصف الصاع من التمر، أو الرز، أو الحنطة، كيلو ونصف كل واحد. أما إن كنت أردت تحريم الزوجة؛ فعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا قبل أن تقرب زوجتك، كل صاع بين اثنين، يعني: كل صاع ثلاثة كيلو ... كيلو ونصف من قوت البلد، من تمر، أو غيره، أو حنطة، أو أرز. أما إن كنت أردت الطلاق، أردت أنها إذا دخلت بيتك تكن امرأتك طالقًا؛ فإنه يقع بها طلقة واحدة إذا كنت أردت الطلاق، وتراجعها في الحال، تشهد اثنين من إخوانك الطيبين، تشهدهم أنك راجعت زوجتك. الخلاصة: أن لك في هذا ثلاثة أمور: الأمر الأول: أن تكون أردت الامتناع فقط، فهذا فيه كفارة يمين لما استعملتموها، ودخلت البيت، وهي إطعام عشرة مساكين، أو كسوتهم، عشرة، كل واحد له نصف الصاع، كيلو ونصف، أو كسوة ........ تجزئه في الصلاة. الحال الثاني: أن تكون أردت التحريم، تحريمها عليك، تحريم الزوجة بذلك إن دخلت البيت، فهذا فيه كفارة الظهار، كما بينها الله في سورة المجادلة، وهي: عتق رقبة مؤمنة قبل أن تمس زوجتك، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا قبل أن تمس زوجتك، فإن لم تقدر -لا هذا ولا هذا- فعليك إطعام ستين مسكينًا، ثلاثين صاعًا كل صاع بين اثنين، ومقدار ذلك تسعين كيلو، كل واحد له كيلو ونصف من قوت البلد، من تمر، أو أرز، أو حنطة، أو ذرة، ونحو ذلك، مع التوبة والاستغفار. الحال الثالث: أن تكون أردت الطلاق، أردت أنها إن دخلت بيتك فهي مطلقة زوجتك، فهذا الكلام يقع به طلقة، ولك مراجعتها في العدة، بشهادة اثنين، تشهد اثنين من أهل السنة، تشهد اثنين أنك راجعتها، إذا كنت ما طلقتها قبل هذا طلقتين، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، إذا أذنتم لي سماحة الشيخ بعرض ما أعرفة عن أحوال الناس في مثل هذا الباب. الشيخ: نعم. المقدم: مثل هذا الباب يغلب عليه أنهم يريدون توفير الهدية للمهدي، بحيث لا يكلف نفسه، فحينئذٍ لا بد لسماحتكم من تعليق وحكم آخر؟ الشيخ: على كل حال هو هذا التفصيل إذا كان أراد الامتناع من قبولها توفيرًا له، ورحمة له، وعدم تكليف له؛ فهو إذا قبلها فيها كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15579/حكم-من-حلف-الا-تدخل-بيته-هدية-معينة-ثم-دخلت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76314.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":16912,"question":"إذا قال الشخص لزوجته: أنت طالق، أكثر من ثلاث مرات في نفس اللحظة، هل يعتبر ذلك طلقةً واحدة؟","title":"حكم تكرار الطلاق في مجلس واحد","answer":"الجواب: إذا قال لها: أنت طالق ثلاث مرات، أو تراك طالق ثلاث مرات، يعتبر ثلاث طلقات؛ لأنها جمل متعددة، تراك طالق، أو أنت طالق، كررها ثلاث مرات... يكون ثلاث طلقات، إلا إذا نوى التأكيد، أو التفهيم، فلا بأس، إذا قال: ما أردت إلا واحدة، لكن تكررت؛ أبي أفهمها، أو أكدها، أكد طلاق الأول، ما قصدت تكرار الطلاق، فهو على نيته الأعمال بالنيات أما إذا كان ما له نية، تقع الثلاث على المرأة، إذا كانت صالحةً لذلك. أما إذا كان الطلاق في الحيض، أو في النفاس، أو في طهر جامعها فيه، وليست حبلى، ولا آيسة، فهذا الصحيح أنه لا يقع؛ لأنه ثبت من حديث ابن عمر -رضي الله عنهما- أن النبي ﷺ أمره لما طلق امرأته وهي حائض أن يمسكها، حتى تحيض، ثم تطهر، ثم تحيض، ثم تطهر، ثم إن شاء طلق، أمره أن يمسكها حتى تطهر من حيضتها التي طلقها فيه، ثم تحيض مرةً أخرى، ثم تطهر، ثم يطلق إن شاء، وقال: فليطلقها قبل أن يمسها. وفي اللفظ الآخر: فليطلقها طاهرًا، أو حاملًا فدل ذلك على أن تطليق المرأة وهي حائض، أو نفساء، أو في طهرٍ قد مسها فيه، قد جامعها فيه، وهي ليست حبلى، ولا آيسة، يكون طلاقًا بدعيًا، منكرًا لا يقع على الصحيح. وذهب الجمهور إلى أنه يقع، ولكن قول الأكثرين مرجوح، الأقرب أنه لا يقع، إلا إذا حكم به حاكم، إذا حكم حاكم بوقوعه؛ يثبت، ينفذ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15695/حكم-تكرار-الطلاق-في-مجلس-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82611.mp3","categories":["الطلاق"]},{"id":16920,"question":"إذا قال الشخص: بالحرام، بالطلاق -ولعدة مرات- فلان لن يتزوج فلانة، فإذا حصل الزواج؛ هل يقع عليه الطلاق؟","title":"حلف بالطلاق والحرام على عدم حصول شيء وحصل، فهل يقع؟","answer":"الجواب: هذا يختلف، حسب نيته، إذا قال: علي الطلاق ........... يتزوج فلان، هذا أولًا لا يجوز الحلف بالطلاق، ولا يجوز الحلف بالحرام، لا يجوز، الحلف يكون بالله وحده، لا يجوز لأحد يحلف بالطلاق، ولا بالحرام، ولا بالأمانة، ولا بالنبي، ولا برأس فلان، ولا شرف فلان، ولا حياة فلان؛ كل هذا لا يجوز، يقول النبي ﷺ: من كان حالفًا؛ فليحلف بالله، أو ليصمت ويقول ﷺ: من حلف بشيءٍ دون الله؛ فقد أشرك. لكن إذا كان قصده، يعني: أنه عليه الطلاق، عليه الحرام أن فلانًا ما يتزوج فلانة، وقصده منعه، فهذا إذا فعل؛ عليه كفارة يمين، حكمه حكم اليمين، إذا ما طاعوه، زوجوه... بالطلاق بالحرام ما يتزوج فلانة؛ يكون عليه كفارة يمين، ولا يقع الطلاق في أصح أقوال أهل العلم، إذا كان قصده المنع. أما إذا كان قصده أن يقع الطلاق، والتحريم، إذا كان قصده بالطلاق إذا تزوج فلانة، قصده إن زوجه طالق، أو قصده إنه حرام عليه... هذا، ويريد أنها تحرم عليه، أو تطلق؛ فله نيته، فهو على ما نوى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15693/حلف-بالطلاق-والحرام-على-عدم-حصول-شيء-وحصل-فهل-يقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82610.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":17138,"question":"هذه رسالة بعث بها المستمع محمد علي عبدالله يحيى القيسي، أخونا رسالته مطولة بعض الشيء؛ لأنها تتضمن قضية طلاق، يقول: أرفع لسماحتكم بموضوعي هذا طالبًا من سماحتكم إفتائي فيه بالطريقة الشرعية المطهرة التي تبرئ الذمة، وقضيتي هي: إن لي زوجة حصل بيني وبينها اختلاف، وسوء تفاهم عدة مرات، مما جعلني أطلقها طلقتين متفرقتين، حيث أن الطلقة الأولى أعادها لي إخوانها في يومها، أما الطلقة الثانية فقد استحصلت بموجبها على صك شرعي من المحكمة، وبعثته لأهل الزوجة، إلا أن فضيلة القاضي ذكر لي في الصك أنني سبق أن استرجعت مرتين، بينما الصحيح أنني استرجعت مرة واحدة فقط، وهذه هي المرة الثانية التي فيها حصل الطلاق، واستخرجت بموجبه صكًا، ولم أطلق ثلاث طلقات، لا لفظًا، ولا استرجاعًا، وحيث أنني أرغب في استرجاع زوجتي، وهي كذلك ترغب العودة بعد أن راحت نزوات الشيطان، وهدأت النفوس، لذا أرجو من سماحتكم إفتائي في هذا الموضوع، ومدى تحليل استرجاع زوجتي من عدمه، مع وجود الرغبة بين الطرفين، وأؤكد لسماحتكم أنه لم تحدث أكثر من طلقتين سابقتين، إحداها استرجعت بعدها، والأخرى حصل بموجبها صك الطلاق الحالي المغلوط فيه، راجيًا من الله أن يوفق سماحتكم لما فيه الخير، والرشاد، ويجعلكم هداة مهتدين، وعلى طريق الحق، وبشرعة سيدنا محمد سائرين، إنه سميع مجيب والله يحفظكم ويرعاكم.","title":"حكم من حكم عليه القاضي بأنه قد طلق ثلاثًا","answer":"الجواب: الجواب عليك أن تراجع القاضي، هذا يتعلق بالقاضي، فعليك أن تراجع القاضي، وفيما يراه القاضي -إن شاء الله- البركة، والقاضي ليس بمتهم في حقك، ولا في حق غيرك، لعلك نسيت أنت، القاضي أحفظ منك وأثبت، فأنت راجع القاضي، وبين له ما عندك، والقاضي فيه البركة، والكفاية، إن شاء الله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16003/حكم-من-حكم-عليه-القاضي-بانه-قد-طلق-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83205.mp3","categories":["الطلاق"]},{"id":17144,"question":"رسالة وصلت إلى البرنامج من المستمع رشيد محمد صالح الزرقاء، يقول: أنا رجل كبير السن، تزوجت بأخت زوجتي بعد وفاة زوجتي، وهي أيضًا كبيرة في السن وأرملة، بعد مضي أربعة أشهر طلبت مني الطلاق، وبدون أي سبب، والله على ما أقول شهيد، مما اضطرني لطلاقها اضطرارًا، وبعد فترة أسبوع راجعت نفسها، ورجعت، ومكثت فترة لا تزيد عن شهر، وعاودت الكرة مرة أخرى، وطلبت الطلاق، علمًا أن المذكورة وقع لي ولها حادث سيارة، مما أثر على نفسيتها، إنني أيها الشيخ الفضيل! قمت بطلاقها غصبًا عني، هل يحق لي إرجاعها؟ جزاكم الله خيرًا.","title":"ما حكم طلاق المضطر؟","answer":"الجواب: ننصحك بمراجعة المفتي لديكم، أو القاضي، وهو ينظر في الأمر -إن شاء الله- تراجع المفتي، أو القاضي أنت والمرأة ووليها حتى يسألكم عن الواقع بالتفصيل، ثم يفتيكم، إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15963/ما-حكم-طلاق-المضطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83202.mp3","categories":["الطلاق"]},{"id":17169,"question":"من المستمع (س. س. ع. الشهري) من المنطقة الشرقية سؤال يقول فيه: ما حكم الطلاق في حالة الغضب، حيث أنه حصل بيني وبين أهلي نوع من الزعل، إذ قلت: طلاقي ما عاد تبقون في هذا البيت، أي: ما تجلسون فيه، وذلك تكرر مني مرتين، أو أكثر، والله أعلم حيث أني لا أدري كم مرة إذ أنني كنت في حالة غضب، وأعوذ بالله من الشيطان الرجيم، ثم إنه بعد قليل فات الشيطان، وتراضيت أنا وأهلي، وهم معي الآن في البيت، ما هو توجيه سماحتكم؟ جزاكم الله خيرًا.","title":"ما حكم الطلاق في حالة الغضب؟","answer":"الجواب: الغضب فيه تفصيل: قد يكون يزول معه الشعور، قد يشتد حتى يقارب زوال الشعور، قد يكون خفيفًا، فيه تفصيل، فننصحك أن تتصل بالقاضي عندك أنت، والمرأة ووليها حتى تشرحوا له الواقع كلكم، ثم يفتيكم بما يرى، أو تكتب لي وأنا أحيلك إلى الجهة المختصة حتى ينظروا فيما وقع منك، ومن زوجتك. المقصود: أن الغضب فيه تفصيل، فارجع إلى القاضي عندك عندكم، وفيما يراه الكفاية -إن شاء الله- تحضر عنده، وتبين له الواقع أنت، والمرأة ووليها، وفيما يراه القاضي -إن شاء الله- الخير، والحق، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15988/ما-حكم-الطلاق-في-حالة-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72217.mp3","categories":["الطلاق"]},{"id":17173,"question":"هذا السائل لم يذكر الاسم في رسالته، يقول: سماحة الشيخ! ما حكم من طلق امرأته، ثم قال: بأنني قمت بتطليقها لأنني كنت في غضب شديد، ولم أتمالك نفسي؟","title":"حكم الطلاق في حالة الغضب","answer":"الجواب: حكمه أن يراجع المحكمة، أو العلماء الذين عنده حتى ينظروا في الأمر، أو يكتب لنا حتى ننظر في الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/15992/حكم-الطلاق-في-حالة-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59003.mp3","categories":["الطلاق"]},{"id":17232,"question":"تقول: يا سماحة الشيخ -هذه الأخت الطبيبة- أبي عليه ديونٌ، رغم أنه يشتغل، إلا أنه لا يستطيع تسديد هذه الديون، ولقد طلب منا نحن الأخوات البنات على مساعدته، واتفقن مع أخواتي على مبلغٍ محدد يدفع من الكل، زوجي يرفض أن أساعد أهلي، بالرغم من، أولًا: أصرف على نفسي، وعلى ابنتي، وعلى البيت من كل النواحي: إيجار، وكهرباء، ومأكل، وملبس، وغير ذلك، بل العكس أنا أساعده بالرغم من أن راتبه كبير، زوجي يصرف جميع ما يملك من الراتب على أهله، لبناء بيتٍ لأبيه، وأنا لم أعترض، بل العكس أساعده، المبلغ الذي أساعد به أهلي يعتبر جزءًا بسيطًا بالنسبة للراتب الذي أتقاضاه، أهلي موجودون في المنطقة التي أدرس بها، وهم الذين ساعدوني في أمور الحياة، مثلًا: لو احتجت الذهاب إلى مكان ما، أو طبيب، وغير ذلك، لعل لكم توجيه؟","title":"ما حكم إعانة المرأة لوالدها وزوجها رافض؟","answer":"الجواب: نعم، الواجب مساعدة والدك، عليكم أن تساعدوا الوالد، النبي ﷺ يقول: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فعليكم أن تساعدوا والدكم، ولو لم يرض الزوج، ما له حق يمنعكم، ولو منعكم ما له حق، عليكم أن تساعدوا الوالد، ولو لم يرض الزوج، هذا من أهم الصلة، ومن أهم البر، فعليكن أن تساعدن والدكن في قضاء دينه، وفي نفقة بيته، ولو لم يرض الزوج. نعم.","link":"https://binbaz.org.sa/fatwas/16060/ما-حكم-اعانة-المراة-لوالدها-وزوجها-رافض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59109.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":17286,"question":"هذا سائل من الرياض يقول: رجل ذهب إلى زملائه، فسألوه عن أهله، فقال لهم: طلقتها، أي: يعني الزوجة زوجة هذا الرجل، وذلك مزاحًا معهم، هل يعتبر هذا طلاقًا؟","title":"ما حكم طلاق المازح؟","answer":"الجواب: نعم يعتبر طلقة واحدة، يحسب عليه طلقة واحدة، ويؤخذ بإقراره، والطلاق جده جد وهزله جد، وليس له أن يلعب بذلك. فالمقصود أنه متى أقر بهذا يحسب عليه طلقة واحدة، إذا قال: هي أني طلقتها تحسب طلقة واحدة. نعم. المقدم: تساهل كثير من الناس في الطلاق، هل لسماحة الشيخ توجيه لهم؟ الجواب: ما ينبغي، لا ينبغي التساهل في الطلاق، يقول النبي ﷺ: أبغض الحلال إلى الله الطلاق فلا يجوز التساهل به، ولا التلاعب؛ لأنه تلاعب بأحكامٍ شرعية، فالواجب على المسلم أن يتثبت، وألا يطلق إلا عن بصيرة، عن عزم، إذا دعت الحاجة إلى الطلاق لا بأس، لكن لا يتلاعب به. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16126/ما-حكم-طلاق-المازح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59305.mp3","categories":["الطلاق"]},{"id":17302,"question":"من الدمام هذه رسالة بعث بها مستمع رمز إلى اسمه بالحروف (ع. ع) يقول: نويت بقلبي ترك شيء، وأن لا أفعل هذا الشيء، وإلا فزوجتي طالق، قلت: هذا في قلبي، ثم فعلت هذا الشيء بعد هذه النية، فهل علي كفارة؟ وماذا يكون؟ وجهوني جزاكم الله خيرًا.","title":"حكم الطلاق إذا كان بالنية فقط","answer":"الجواب: ما يتعلق بعمل القلب لا يترتب عليه حكم، ولا تطلق المرأة بذلك، لقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل، أو تكلم فإذا كان نية فقط، فإنه لا يقع به الطلاق، وإنما الطلاق يقع بالألفاظ التي تصدر منك بنية الطلاق، أو بألفاظ الطلاق، كأن تقول: زوجتي فلان طالق، أو هي طالق، أو مطلقة، باللفظ لا بالنية، أو إذا فعلت كذا إذا خرجت من البيت فهي طالق، ناويًا الطلاق أنها تطلق، لا تنوي المنع، ليس قصدك المنع فقط، إنما تقصد منعها، وإيقاع الطلاق عليها يقع، هكذا لو قلت: إذا كلمت فلانًا، إذا لم تصنع كذا -قصدك الطلاق- قصده إيقاع الطلاق يقع. نعم.","link":"https://binbaz.org.sa/fatwas/16144/حكم-الطلاق-اذا-كان-بالنية-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72402.mp3","categories":["الطلاق"]},{"id":17360,"question":"سماحة الشيخ! هذه سائلة تقول: رجل طلق زوجته طلقتين متباينتين منفردتين، والطلقة الثالثة على ورقة، والتي على هذه الورقة هو عرفي، وبدون أن يتلفظ به، فهل تحرم عليه الزوجة؟ وإذا حرمت عليه هذه الزوجة هل لها أن تساكنه في بيت من طابقين هو في الأعلى، وهي في الأسفل لسبب أن لها أولادًا لتربيتهم، أفتونا مأجورين؟","title":"الأولى في مسائل الطلاق التوجه للمحكمة أو مفتي البلد","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  الطلاق أمره مهم، ويقع فيه مشاكل، فالذي أرى في مثل هذا أن المطلق والمطلقة يتوجهان إلى مفتي البلد، أو المحكمة؛ حتى ينظر في أمر الطلاق الواقع، وينظروا لأسبابه، وهل هناك موانع من وقوعه، وهل هناك غضب شديد أوجب الطلاق؛ لأن المقام مقام عظيم، فالذي أراه في هذا أن المطلق، والمطلقة في أي بلد يتوجهان إلى الحاكم، أو إلى المفتي؛ حتى ينظرا في أمر الطلاق، ويكون مع المرأة وليها، كأخيها، أو أبيها، أو نحو ذلك؛ حتى تكون الفتوى على بصيرة، وعلى بينة. نعم.","link":"https://binbaz.org.sa/fatwas/16196/الاولى-في-مساىل-الطلاق-التوجه-للمحكمة-او-مفتي-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77001.mp3","categories":["الطلاق"]},{"id":17364,"question":"سماحة الشيخ -حفظكم الله- في زماننا هذا كثر التلفظ بالطلاق، والتهاون به من بعض الناس حيث صار ديدنهم، ما هي الأسباب في نظركم؟ وما العلاج؟ وما توجيهكم للإخوة الذين وقعوا في ذلك؟","title":"بعض أسباب الطلاق وعلاج ذلك","answer":"الجواب: هذا نعم هذا واقع كثيرًا، الطلاق واقع من الناس كثيرًا، بأسباب كثيرة، تارةً من الزوج، وتارةً من المرأة، وتارةً منهما جميعًا، فقد تكون المرأة بذيئة اللسان، سليطة اللسان، فتسبه وتتكلم عليه بكلام غير لائق، فلا يتحمل، ويطلق، وقد تطالبه بأشياء لا تجب، وتكثر عليه، وتتعبه فيطلق، وقد يكون هو سريع الغضب، قليل الصبر؛ فلا يتحمل شيئًا، وقد يكون عنده أعمال أخرى قد أشغلته، وكلفته، وأقظت مضجعه، فلا يتحمل، قد يكون يتعاطى المسكرات فلا يتحمل إلى غير هذا من الأسباب. فالواجب على المطلق، والمطلقة تقوى الله، وأن يتعاونا على البر والتقوى، وأن تحذر المرأة إيذاء زوجها، وإيقاعه فيما لا ينبغي بسبب سلاطة لسانها، ومطالباتها الكثيرة بغير حق. والواجب على الزوج أن يتقي الله في المرأة، وأن يعطيها حقوقها، وألا يظلمها؛ حتى لا يلجئها إلى إيذائه، وإلى المطالبة بما يجب لها حتى يقع منه الطلاق.  الواجب على الجميع التعاون على البر والتقوى، والتواصي بالحق، فالزوج ينبغي له أن يحلم، ولا يعجل، والواجب عليه أن يعطيها حقوقها، وألا يلجئها إلى المطالبة، وإغضابه. والواجب عليها هي أيضًا السمع والطاعة لزوجها في المعروف، وحسن المعاشرة، وطيب الكلام، وتحمل بعض ما يقع من الخلل من الزوج؛ لقول الله -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]؛ ولقوله سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] وقوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. فينبغي للزوجين التعاون على البر والتقوى، والتواصي بالحق، والتعاون على الخير، هو يجتهد في أداء حقها، والإحسان إليها، وإحسان عشرتها، وهي تجتهد في أداء حقه، وعدم إلجائه إلى الطلاق، وعدم إغضابه بغير حق، فإذا حصل التعاون؛ قل الطلاق، وإذا لم يحصل التعاون؛ كثر الطلاق، نسأل الله للجميع الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16199/بعض-اسباب-الطلاق-وعلاج-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77002.mp3","categories":["الطلاق","نصائح وتوجيهات"]},{"id":17549,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. ع. ع) مقيم في المدينة المنورة، أخونا يسأل ويقول: أنا كنت في إحدى الدول الشقيقة ونويت أن أطلق زوجتي بدون أي سبب، وفي نيتي أن أتزوج امرأة ثانية، وبعدما رجعت إلى البلد لم أطلقها، هل صارت زوجتي طالقًا بالنية أم لا؟ جزاكم الله خيرًا.","title":"هل يقع الطلاق بالنية دون تلفظ؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفإن النية لا يقع بها الطلاق؛ لقول النبي ﷺ في الحديث الصحيح: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تكلم، فالنية لا يقع بها الطلاق ولا العتق ولا الأحكام الأخرى من جهة العقود، لا بد من لفظ وهذا من رحمة الله وتيسيره جل وعلا، فإن القلوب يقع لها خطرات ووساوس ونيات فلا تؤاخذ بهذه الخطرات والنيات في طلاقها وعقودها وعتقها ونحو ذلك حتى يتكلم أو يعمل كأن يكتب الطلاق أو يكتب العتق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16465/هل-يقع-الطلاق-بالنية-دون-تلفظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83801.mp3","categories":["الطلاق"]},{"id":17557,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. ع. ع) مقيم في المدينة المنورة، أخونا يسأل ويقول: أنا كنت في إحدى الدول الشقيقة ونويت أن أطلق زوجتي بدون أي سبب، وفي نيتي أن أتزوج امرأة ثانية، وبعدما رجعت إلى البلد لم أطلقها، هل صارت زوجتي طالقًا بالنية أم لا؟ جزاكم الله خيرًا.","title":"هل يقع الطلاق بالنية دون تلفظ؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفإن النية لا يقع بها الطلاق؛ لقول النبي ﷺ في الحديث الصحيح: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تكلم، فالنية لا يقع بها الطلاق ولا العتق ولا الأحكام الأخرى من جهة العقود، لا بد من لفظ وهذا من رحمة الله وتيسيره جل وعلا، فإن القلوب يقع لها خطرات ووساوس ونيات فلا تؤاخذ بهذه الخطرات والنيات في طلاقها وعقودها وعتقها ونحو ذلك حتى يتكلم أو يعمل كأن يكتب الطلاق أو يكتب العتق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16465/هل-يقع-الطلاق-بالنية-دون-تلفظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83801.mp3","categories":["الطلاق"]},{"id":17583,"question":"يقول: نعلم أن كفارة الظهار عتق رقبة أو صيام شهرين متتابعين، أو إطعام ستين مسكينًا، والله  يقول في آخر الآية: مِنْ قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3] إذا حصل المساس قبل الكفارة فما الحكم؟","title":"حكم المساس قبل أداء كفارة الظهار","answer":"الجواب: تلزمه الكفارة، تلزمه الكفارة وتتعين بعدما وطئها تتعين، أما قبل ذلك غير متعينة، متى عزم أتى بها وإن طلقها قبل أن يأتي بها فلا عليه شيء أو ماتت، لكن إذا وطئها لزمت الكفارة، وهي مرتبة ماهي مخيرة، أولًا العتق فإن عجز يصوم شهرين متتابعين، فإن عجز يطعم ستين مسكينًا قبل أن يمسها، على الترتيب كما رتبها الله ، أولًا العتق إذا تيسر، فإن عجز يصوم شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، كل فقير له نصف الصاع قبل أن يمسها. فإذا وطئها استعجل ووطئها وجبت عليه الكفارة وعليه التوبة إلى الله من ذلك؛ لأنه استعجل فعليه التوبة والندم خوفًا من الله  وتعظيمًا له، وتعينت عليه الكفارة حينئذ، إن كان مستطيعًا أعتق وإن كان لا يستطيع صام شهرين متتابعين ستين يومًا، وإن عجز أطعم ستين مسكينًا حتى ولو ماتت حتى ولو طلقها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16534/حكم-المساس-قبل-اداء-كفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84117.mp3","categories":["الطلاق","الظهار"]},{"id":17591,"question":"يقول: نعلم أن كفارة الظهار عتق رقبة أو صيام شهرين متتابعين، أو إطعام ستين مسكينًا، والله  يقول في آخر الآية: مِنْ قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3] إذا حصل المساس قبل الكفارة فما الحكم؟","title":"حكم المساس قبل أداء كفارة الظهار","answer":"الجواب: تلزمه الكفارة، تلزمه الكفارة وتتعين بعدما وطئها تتعين، أما قبل ذلك غير متعينة، متى عزم أتى بها وإن طلقها قبل أن يأتي بها فلا عليه شيء أو ماتت، لكن إذا وطئها لزمت الكفارة، وهي مرتبة ماهي مخيرة، أولًا العتق فإن عجز يصوم شهرين متتابعين، فإن عجز يطعم ستين مسكينًا قبل أن يمسها، على الترتيب كما رتبها الله ، أولًا العتق إذا تيسر، فإن عجز يصوم شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، كل فقير له نصف الصاع قبل أن يمسها. فإذا وطئها استعجل ووطئها وجبت عليه الكفارة وعليه التوبة إلى الله من ذلك؛ لأنه استعجل فعليه التوبة والندم خوفًا من الله  وتعظيمًا له، وتعينت عليه الكفارة حينئذ، إن كان مستطيعًا أعتق وإن كان لا يستطيع صام شهرين متتابعين ستين يومًا، وإن عجز أطعم ستين مسكينًا حتى ولو ماتت حتى ولو طلقها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16534/حكم-المساس-قبل-اداء-كفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84117.mp3","categories":["الطلاق","الظهار"]},{"id":17682,"question":"من أسئلة هذا السائل يقول: ما حكم الشرع في نظركم سماحة الشيخ في طلب الزوجة من الزوج الطلاق بدون سبب شرعي؟ وما توجيهكم للزوجين؟","title":"حرمة طلب المرأة الطلاق دون سبب شرعي","answer":"الجواب: لا يجوز للزوجة طلب الطلاق من غير علة، والواجب عليها حسن العشرة لزوجها وعدم طلب الطلاق، إلا من بأس إذا كان يظلمها ويؤذيها، أو ما كتب الله بينهما مودة تبغضه؛ فلا بأس أن تطلب المخالعة، أما ما دام ليس بينهما شيء فالأفضل لها عدم الطلاق، وأن تتعاون مع زوجها كما قال تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، فالمرأة والرجل يتعاونان على الخير، وعلى فعل ما شرع الله، وعلى ترك ما نهى الله عنه، كل منهما يعين الآخر، ولكن إذا كان هناك أسباب بأن لم يكتب الله بينهما مودة، وطلبت الخلع أو طلبت الطلاق؛ لأنه ما بينهما مودة أو لأنه يظلمها أو يؤذيها بالضرب أو غير ذلك فلا بأس إذا كان لسبب. نعم.\nالمقدم: جزاكم الله خير يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16621/حرمة-طلب-المراة-الطلاق-دون-سبب-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59511.mp3","categories":["الطلاق","قضايا المرأة"]},{"id":17791,"question":"من السودان السائلة التي رمزت لاسمها بـ (أ. م. ع) تقول في هذا  هل يجوز للمرأة المطلقة أن تسكن مع مطلقها في منزل واحد من أجل أولادها؟","title":"حكم سكنى المطلقة مع من طلقها","answer":"الجواب: هذه فيه تفصيل: إذا كان سكنها في البيت لا خطر فيه، ولا يخشى منه وقوع المحرم بينها وبين زوجها الذي قد بانت منه بالطلاق الأخير الثالث أو بخروجها من العدة؛ إذا كان لا خشية في هذا بأن كان في البيت ناس كثير، وصار لها عزلة، ولزوجها وأهله عزلة أو في عزل أخرى.\nالمقصود: إذا كان في مكان ليس فيه خطر، ومعها غيرها، وليس هناك خلوة، وجلست مع أولادها مع تحجبها عنه إذا كانت قد حرمت عليه بالبينونة بخروجها من العدة، أو بكونه طلق آخر الثلاث فلا حرج في ذلك. أما إن كان بقاؤها في البيت فيه شبهة أو خطر فلا تبقى معه، إذا كان يخشى أن يخلو بها فإن هذا فيه شر ووسيلة إلى الشر، وظن السوء، فالواجب أن تكون بعيدة مع أولادها في بيت آخر. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16774/حكم-سكنى-المطلقة-مع-من-طلقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77811.mp3","categories":["الطلاق"]},{"id":17956,"question":"من مصر السائل (م. أ) يقول سماحة الشيخ: أنا شاب أعيش في مجتمع يفضل الزواج المبكر، وتزوجت منذ تخرجي من الدراسة، وكان ذلك برغبة الوالدين دون اقتناع مني، وعشت مع زوجتي ثلاث سنوات كانت كلها دون أي شعور بالمسئولية، وكنت في سن العشرين إلى ثلاثة وعشرين سنة وأنجبت منها طفلين، ثم لم أستطع إكمال المشوار، وقمت بتطليقها، فغضب علي الوالد، وعانيت من ذلك الشدائد والمضايقات، وظللت على هذه الحال حتى رضي عني والدي بعد ثلاث سنوات، وتزوجت من امرأة أخرى، ولكن لم أجد السعادة أيضًا فطلقتها رغبة منها، وتلبية لطلبها، والآن يا سماحة الشيخ أشعر بأنني أخطأت في حق زوجتي الأولى فأخطأت في حقي الثانية وظلمتني، وأشعر بالمعاتبة لنفسي رغم زواج الأولى من رجل آخر، بماذا تنصحونني مأجورين؟","title":"نصيحة لمن طلق زوجته ويشعر بندم","answer":"الجواب: إذا كنت ترى من نفسك الرغبة، وعندك القدرة على العشرة للنساء، وجماع النساء؛ فتزوج ثالثة والحمد لله، واسأل ربك أن يوفق بينك وبين الثالثة، وأن يجعلها صالحة طيبة، والذي مضى مضى لا تعلق بالماضي، عليك بالمستقبل التمس الزوجة الصالحة الطيبة، واخطبها وتزوجها، وأبشر بالخير إن شاء الله، ما دمت عندك الرغبة في الخير، وعليك التوبة من ذنوبك وسيئاتك، واسأل ربك التوفيق والإعانة، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، والحمد لله.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16989/نصيحة-لمن-طلق-زوجته-ويشعر-بندم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78018.mp3","categories":["الطلاق","نصائح وتوجيهات"]},{"id":18048,"question":"المستمع العوني أبو عونية فيما يبدو بعث يسأل ويقول: رجل طلق زوجته ثلاث طلقات، وكانت الطلقة الثالثة وهي حامل، وأوصى عمته أن تذهب إلى زوجته لإرجاعها قبل الولادة، وحضرت العمة، وقالت بصوت عالٍ أمام الزوجة وأمام بعض الأقارب: أرجعناها، وبناءً عليه عادت الزوجة إلى زوجها، ما حكم هذا التصرف، جزاكم الله خيرًا.","title":"حكم إرجاع المرأة الحامل التي طلقت ثلاثًا","answer":"الجواب: هذا تصرف باطل، وليس الإرجاع إلى المرأة، ولا إلى الزوج في مثل هذا، مادام طلقها الطلقة الأخيرة الثالثة، ولو أنها حامل. تـحرم عليه، حتى تنكح زوجًا غيره، إلا أن تكون الطلقتان السابقتان فيهما ما يوجب عدم وقوعهما أو إحداهما، وإلا فطلاق الحامل واقع، طلاق الحامل شرعي، يقول ﷺ لـابن عمر: طلقها طاهرًا أو حاملًا يعني: من دون مسيس، لو طلقها من دون مسيس وهي حائل، أو طلقها وهي حامل كله طلاق شرعي، إنما المنكر أن يطلقها في حيض أو في نفاس، أو في طهر جامعها فيه، هذا هو الذي لا يجوز، أما طلاق الحامل فهو طلاق شرعي، ولكن بعض العامة يظن أن طلاق الحامل لا يقع، جهلاً منه. فهذا الذي طلق زوجته الطلقة الثالثة وهي حامل، طلاقه واقع، إذا كان لا مانع به، عاقل لا مانع به فطلاقه واقع، وهكذا الطلقتان السابقتان، إذا كانتا ليس فيهما ما يوجب عدم وقـوعهما أو إحداهما، فإن الطلاق ماضي، ولا تحل له حتى تنكح زوجًا غيره؛ لأن الله سبحانه يقول: فَإِنْ طَلَّقَهَا [البقرة:230] يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230]. فالواجب على المؤمن في مثل هذا أن يتبصر وأن لا يعجل، أما إرساله المرأة وأن تقول: أرجعناها فهذا شيء لا وجه له ولا أساس له، بل هو من خرافات العامة. لكن ينظر في الطلقتين السابقتين، فإذا كانتا وقعتا في طهر ليس فيه مسيس أو في حال حمل، فقد وقعتا، وتمت الثلاث، وليس له رجوع إليها إلا بعد زوج شرعي، بعد زوج يطؤها في نكاح شرعي، ثم يفارقها بموت، أو طلاق، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17081/حكم-ارجاع-المراة-الحامل-التي-طلقت-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60012.mp3","categories":["الطلاق"]},{"id":18058,"question":"هذا سؤال من المستمع محمود العراف الإبراهيم، سوري الجنسية، يعمل في مدينة عرعر يقول: أنا شاب متزوج حصل بيني وبين زوجتي نزاع بسيط وأرادت أن تذهب إلى أهلها وهي حامل، فانزعجت منها وقلت لها: إذا ذهبت إلى أهلك فأنت مطلقة. بهذا الكلام ولم أزد عليه شيئًا أبدًا، وكنت أقصد بهذا عدم ذهابها إلى أهلها، ولا أقصد الطلاق وقد ذهبت، فما الحكم في مثل هذا الأمر؟","title":"حكم من قال لزوجته: إذا ذهبت لأهلك فأنت مطلقة","answer":"الجواب: إذا كان المقصود من هذا الكلام منعها من الذهاب إلى أهلها، وليس المقصود إيقاع الطلاق؛ فإن هذا يكون في حكم اليمين، هذا الطلاق يكون في حكم اليمين، وعليك أيها السائل! كفارة اليمين؛ وهي إطعام عشرة مساكين أو كسوتهم، والطعام يعطى كل واحد نصف صاع من التمر أو الأرز أو غيرهما من قوت البلد كيلو ونص تقريبًا، أو تعشيهم أو تغديهم، أو تكسوهم كسوة كل واحد يعطى إزارًا ورداء أو يعطى قميصًا. هذا هو الواجب في مثل هذا على الصحيح من قولي العلماء، وقال بعض أهل العلم: إنه يقع الطلاق لكن الصحيح أنه لا يقع إذا كانت النية المنع، وليس النية إيقاع الطلاق؛ لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى نعم.","link":"https://binbaz.org.sa/fatwas/17091/حكم-من-قال-لزوجته-اذا-ذهبت-لاهلك-فانت-مطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90102.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18061,"question":"المستمع: يوسف كلبالي غيني الجنسية، بعث برسالة مطولة جدًا سماحة الشيخ، ملخص ما في هذه الرسالة: أن أمه تطلب منه أن يطلق زوجته دون سبب وجيه، ويسأل سماحتكم: هل يطيع أمه، ويطلق زوجته؟","title":"ما حكم طاعة الأم في تطليق الزوجة؟","answer":"الجواب: إذا كانت الزوجة تؤذيها، أو تظلمها، أو فاسقة، فعليك أن تطيع الوالدة، أو الوالد، أما إذا كانت المرأة مطيعة لله، مستقيمة على دين الله، غير مؤذية لوالديك، فلا يلزمك طاعة والدك، ولا والدتك في ذلك؛ لقول النبي ﷺ: إنما الطاعة في المعروف، هكذا جاء الحديث عن رسول الله ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق، وتطليق المرأة بدون سبب ليس بطاعة، ولا معروف، بل ما ينبغي، أقل أحواله الكراهة، فإذا كانت امرأة مستقيمة، غير مؤذية للأم، ولا للوالد، بل مطيعةٌ لله، تقوم بحق الوالد، والوالدة، فليس لك أن تطيعهم في طلاقها، ولا يلزمك. أما إن كانت تؤذيهم بسلاطة لسانها، أو بأفعالها، أو لأنها معروفة بالمعاصي والشرور؛ فينبغي لك تطليقها، حتى ولو ما طلبوا منك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17096/ما-حكم-طاعة-الام-في-تطليق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72917.mp3","categories":["الطلاق"]},{"id":18119,"question":"في سؤاله الثاني يقول هذا السائل: هل يجوز للأب أن يطلق زوجة ابنه؛ بحيث إن الولد يوكل أباه؟ وكذلك الزوجة هل يجوز للأب أن يتولى العقد نيابة عن ابنه أثناء غيابه؟","title":"حكم التوكيل في الزواج والطلاق","answer":"الجواب: التوكيل لا بأس به حتى لغير الأب، إذا وكل الزوج من يطلق زوجته أباه أو وكل أخاه أو أجنبي لا بأس، إذا كان الزوج عاقل مرشد، إذا كان عاقل عنده يعني عقل تصرف ووكل لا بأس، إذا طلق بنفسه أو وكل، إذا كان عاقلًا ليس مجنونًا، ولا معتوهًا؛ بل عقله معه، فالتوكيل لا بأس في الطلاق، وهكذا الأب إذا زوج بنت ابنه إذا كان أبوها وكل أباه يعني جدها، إذا وكل الإنسان أباه في تزويج بنته فلا بأس. أما أنه يزوج والابن حاضر لا، الابن هو الذي يتولى ذلك في زواج بنته غير الجد، فالأب يتولى زواج ابنته لكن لو وكل أباه يعني زوجها جدها بالوكالة لا بأس، أو زوجها غيره غير جدها بالوكالة لا بأس مثلما تقدم. أما كون الأب يتولى إنكاح ابنة ابنه من دون وكالة لا؛ لأن الابن أقرب وهو أبوها، هو أقرب إليها، والولاية تكون بالأقرب، أبوها ثم أبوه، ثم جده وإن علا، ثم ابنها ثم بنوه وإن نزل، ثم أخوها الشقيق ثم أخوها لأب وهكذا كالميراث، فلا يزوج ولي بعيد عن ولي قريب، الولي القريب أحق به إلا إذا وكله القريب، أو كان القريب له عذر كالغيبة لا يمكن الاتصال به، أو لا يعرف مكانه، فيكون حكمه كالعدم، يزوج الذي بعده الذي يليه. فإذا غاب مثلًا أبوها مثلًا زوجها ابنها، إذا كان أبوها غائبًا لا يدرى مكانه حتى يوكل، لا يمكن الاتصال به ولا يتيسر الاتصال به، زوجها ابنها، وهكذا لو غاب ابنها وأبوها زوجها أخوها إذا لم يتيسر الوصول إلى وليها الأقرب بالمكالمة أو بالمكاتبة. فالحاصل أن الولاية بالأقرب الأقرب فالأقرب، فإذا وجد الأقرب قدم في التزويج إلا أن يوكل وهو يعني صحيح العقل إذا وكل فلا بأس .نعم. المقدم: أحسن الله إليكم وأثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17150/حكم-التوكيل-في-الزواج-والطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78105.mp3","categories":["الطلاق"]},{"id":18181,"question":"الرسالة التالية وصلت إلى البرنامج من الأنبار في العراق، وباعثتها إحدى الأخوات المستمعات من هناك تقول (أ. ب. م) أختنا كتبت رسالتها بلهجتها العامية، وفهمت منها أن حال زوجها تغير، وقد طلقها خمس مرات، وترجو من سماحتكم التوجيه، كيف تتصرف هذه المرأة؟","title":"حكم امرأة طلقها زوجها خمس مرات","answer":"الجواب: على زوجك أن يرجع إلى أهل العلم في بلده ويسألهم عما جرى وأنت حاضرة، حتى يعرف العالم ما لديك وما لدى زوجك، ثم يفتي على ما عرفه من شرع الله  هذا هو الذي ينبغي أن يحضر الزوج معك عند العالم المعروف في بلدك حتى يفتيه بما يعلمه من الشرع المطهر. أو يكتب الزوج إلى أهل العلم في أي بلد ليسألهم إذا كان ما عنده في بلده علماء يكتب إلى أهل العلم في البلدان الأخرى ويسألهم كتابة عما جرى منه حتى يرشدوه إلى ما يجوز شرعًا. نعم.","link":"https://binbaz.org.sa/fatwas/17214/حكم-امراة-طلقها-زوجها-خمس-مرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85402.mp3","categories":["الطلاق"]},{"id":18331,"question":"من العراق -الموصل- جامعة الموصل رسالة بعث بها أخونا عبد الحميد محمد أبو الهوى يقول: إنني قد خرج مني لفظ بالطلاق لزوجتي ثلاث، وكان هذا بسبب خلافات عائلية بالمنزل، وبعد هذه الألفاظ بالطلاق أخذتها إلى منزل أهلها، وبعد مدة ألح أهلي علي برجوع الزوجة إلي، وفي نفس الوقت كنت غاضبًا، فكررت ألفاظ الطلاق إنها طالق طالق طالق.فعندما وجدت نفسي منهارًا فكرت بالسفر؛ لكي أبتعد عن المشاكل التي واجهتني، وبعد سفري بشهرين جاءني خطاب من أهلي بأن زوجتك أعدناها في المنزل، حيث أنها حامل في شهرها الرابع، ومعها طفلان آخران وهم أولادي؟ هل من الممكن الرجوع إليها بأطفالها الثلاثة وهم أطفالي إنهم زينة الحياة الدنيا؟ الرجاء الرد الواضح جزاكم الله خيرًا.","title":"حكم من طلق زوجته ثلاثًا في مجلسين","answer":"الجواب: نوصيك بالرجوع إلى المفتي لديكم؛ لينظر في الأمر، وفيما يراه الكفاية إن شاء الله، تحضر أنت والمرأة ووليها عنده، حتى يعلم ما صدر منك، ويفتيك إن شاء الله في ذلك، وإن كتب إلي في ذلك نظرت في الكتابة؛ لأن هذا إليه؛ هو المسئول. نعم. المقدم: جزاكم الله خيرًا، إذًا: لا ترون أن يقال له شيء في هذا الموضوع يا سماحة الشيخ! الشيخ: لا، نرى أن يراجع المفتي عندهم وفيه بركة إن شاء الله، وإن رأى المفتي يكتب إليّ أو إلى غيري من أهل العلم، فهذا إليه إذا أشكل عليه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17393/حكم-من-طلق-زوجته-ثلاثا-في-مجلسين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_860/nour_86003.mp3","categories":["الطلاق"]},{"id":18332,"question":"أيضًا عن موضوع الطلاق، رسالة بعث بها أخونا عبد الله محمد هلال مصري، ومقيم في جدة، أخونا يقول:في لحظة غضب وانفعال ومشادة مع زوجتي قلت لها: عليّ الطلاق ما أنت ذاهبة إلى المدرسة باكر، وكررت ذلك ثلاث مرات من شدة غضبي، وكان هدفي من ذلك هو منعها من الذهاب إلى المدرسة؛ حيث تعمل مدرسة، ولا أقصد الطلاق أبدًا؛ لأنني أبغضه ولا أعرف أحكامه.في صباح اليوم التالي ألحت عليّ زوجتي بأن من الضروري ذهابها إلى المدرسة؛ لأن ذلك هو أول يوم في العام الدراسي، فقمت بتوصيلها إلى المدرسة، منذ ذلك الوقت وأنا أعيش في قلق نفسي وخوف من الله  لذا أرجو الإفادة عن حكم هذا اليمين، هل هو حلف بغير الله؟ أم يمين طلاق تحرم بموجبه زوجتي عليه؟ أرجو إيضاح ذلك، علمًا بأنني ندمت ندمًا شديدًا، وعزمت على ألا أعود إلى ذلك أبدًا، جزاكم الله خيرًا.","title":"حكم الطلاق بنية منع الزوجة من المدرسة","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل، فهذا الطلاق له حكم اليمين، وعليك كفارتها، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة؛ فإن عجزت تصوم ثلاثة أيام، والإطعام يكون نصف صاع لكل واحد، كيلو ونص لكل واحد من التمر أو الأرز أو الحنطة، أو تعشيه أو تغديه، عشرة، أو تكسو العشرة كسوة إزار ورداء، أو قميص، هكذا يجب ولا طلاق عليك، لا يقع الطلاق؛ لأنك لم ترد الطلاق، وإنما أردت منعها كما قلت، وما كان بهذه المثابة، فله حكم اليمين في أصح قولي العلماء. ونوصيك بالحذر من العود إلى ذلك، والتوبة مما حصل والصبر، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17395/حكم-الطلاق-بنية-منع-الزوجة-من-المدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_860/nour_86004.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18423,"question":"المستمع (م. م) من الدمام بعث برسالة يقول فيها: أعرض عليكم مشكلتي والتي تتلخص في أنني عزمت على ترك التدخين ولكن بدلًا من أؤكد كلامي على عزمي بذلك أمام السامع بالحلف بالله كما ينبغي أن يكون عليه المسلم أكدت بالحلف بالحرام، هل يقع الطلاق في هذه الحالة مع العلم أنني صمت ثلاثة أيام وعدت إلى فعل ما عزمت على ترك فعله على اعتقادي أن الحلف حلف يمين وليس بالطلاق، وإنما نطقت بالحرام للتأكيد للسامع فقط، هل يلزم كفارة في هذه الحالة؟","title":"أكدت الحلف بالحرام على ترك التدخين، هل يقع الطلاق؟","answer":"الجواب: نعم، إذا كنت قصدت منع نفسك من شرب الدخان بالتحريم أو باليمين أو بالطلاق، قلت: علي الحرام وعلي الطلاق أني ما أشرب هذا الدخان، أني لا أعود إليه، ومقصودك منع نفسك والتأكيد على نفسك، ليس قصدك تحريم زوجتك إن فعلت، وليس قصدك طلاقها إن فعلت وإنما أردت التأكيد على نفسك وإلزامها بالكف عن التدخين، فهذا حكمه حكم اليمين وعليك كفارتها وهي إطعام عشرة مساكين أو كسوتهم، ولا يجزئ الصيام إذا كنت قادر على الطعام أو الكسوة لا يجزئ الصيام؛ لأن الصيام إنما يجزئ مع العجز في حق من عجز عن الطعام أو الكسوة أو العتق، أما من قدر على واحد من الثلاثة، قدر على أن يطعم عشرة مساكين، أو يكسوهم، أو يعتق رقبة فإنه يلزمه واحد من هذه الثلاثة، فإن عجز عنها كلها صام ثلاثة أيام كما نص عليه القرآن الكريم في سورة المائدة. أما إن كنت أردت تحريم زوجتك إن فعلت أو أردت طلاقها إن فعلت فإنها تحرم عليك وعليك كفارة الظهار وهي عتق رقبة مع القدرة، فإن عجزت تصوم شهرين متتابعين ستين يومًا، فإن عجزت تطعم ستين مسكينًا ثلاثين صاعًا كل صاع بين اثنين من قوت البلد من تمر أو أرز أو غيرهما، كل صاع يكون بين اثنين، والصاع نحو ثلاثة كيلو تقريبًا. وهكذا إذا أردت الطلاق، إذا قلت: علي الطلاق وأردت طلاقها إن دخنت يكون طلقة واحدة، وعليك أن تراجعها إذا رجعت إلى التدخين إذا كنت لم تطلقها قبل هذا طلقتين فإنه يحل لك مراجعتها إذا كنت أردت إيقاع الطلاق، فتقول: اشهد يا فلان وفلان أني راجعت زوجتي، هذا هو السنة؛ تشهد اثنين أنك راجعت زوجتك بعد أن باشرت الدخان. والواجب عليك يا أخي تقوى الله، وأن تحذر التدخين لمضرته العظيمة وخبثه الكثير، والله سبحانه إنما أباح لعباده الطيبات، كما قال : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4]، هكذا في سورة المائدة، وقال سبحانه في سورة الأعراف في وصف النبي عليه الصلاة والسلام قال: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157]. ولا شك أن التدخين أمر منكر وأن الدخان من الخبائث، وقد قرر الأطباء العارفون به وكل من استعمله أنه مضر وخبيث، فعليك يا أخي أن تتقي الله وأن تحذر شر هذا البلاء، وأن تبتعد عنه، وأن تعزم عزمًا صادقًا عزم الرجال أن لا تعود إليه، رزقنا الله وإياك التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/17528/اكدت-الحلف-بالحرام-على-ترك-التدخين-هل-يقع-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_864/nour_86404.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":18507,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع بدوي سرحان، أخونا عرضنا جزءًا من أسئلته في حلقات مضت، وفي هذه الحلقة يسأل ويقول: لدينا عادة مستجدة وهي الحلف بالذمة، أو بالشباب، بدل الحلف بالله، فهل هذا جائز؟","title":"حكم الحلف بالذمة والشباب","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالحلف بغير الله لا يجوز؛ لقول النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وقال أيضًا عليه الصلاة والسلام: من كان حالفًا فلا يحلف إلا بالله أو ليصمت، وقال أيضًا عليه الصلاة والسلام: من حلف بشيء دون الله فقد أشرك خرجه الإمام أحمد رحمه الله في المسند بإسناد صحيح عن عمر . وخرج أبو داود والترمذي رحمهما الله بإسناد صحيح عن ابن عمر رضي الله عنهما عن النبي ﷺ أنه قال: من حلف بغير الله فقد كفر أو أشرك وهذا يحتمل أنه شك من الراوي هل قال النبي ﷺ كفر أو قال أشرك، أو المعنى أنه حصل له هذا وهذا وتكون (أو) بمعنى الواو، يعني: كفر وأشرك. وبهذا يعلم أن الحلف بغير الله أمر لا يجوز مطلقًا، لا بالأنبياء ولا بالملائكة ولا بالكعبة ولا بالأمانة ولا بذمة فلان ولا رأس فلان ولا شرف فلان ولا حياة فلان.. ولا غير ذلك، فإذا قال: بذمتي أو برأسي أو بشرفي أو بحياتي أو حياة فلان.. أو ما أشبه ذلك كل هذا لا يجوز، أو قال: بالأمانة أو بالنبي أو بالكعبة كل ذلك لا يجوز، وفي الحديث الصحيح يقول ﷺ من حلف بالأمانة فليس منا. وبهذا يعلم أن الواجب على المسلمين الحذر من هذه الأيمان الباطلة وأن يعود نفسه الحلف بالله وحده  وأن يحذر من الحلف بغيره  كائنًا من كان، وهكذا لا يقول: ما شاء الله وشاء فلان، ولا يقول: لولا الله وفلان، ولا يقول: هذا من الله ومن فلان بل يأتي بـ(ثم) يقول: ما شاء الله ثم شاء فلان، إذا كان له تسبب الشخص بأن دفع عنك شرًا وحماك من شر تقول: ما شاء الله ثم شاء فلان جرى كذا وكذا، لولا الله ثم فلان، لأنه فعل معك معروف، هذا من الله ثم من فلان لا بأس، أما أن تقول: لولا الله وفلان أو هذا من الله وفلان، أو ما شاء الله وشاء فلان هذا لا يجوز، بل هو من المحرمات الشركية. فالواجب الحذر من هذه الكلمات ومن الحلف بغير الله ؛ تعظيمًا لله وطاعة لأمره وأمر رسوله عليه الصلاة والسلام ووقوفًا عند حدود الله . نعم.","link":"https://binbaz.org.sa/fatwas/17602/حكم-الحلف-بالذمة-والشباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_868/nour_86801.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":18555,"question":"من جدة، حي الكندرة، هذه رسالة بعث بها أحد الإخوة المستمعين من هناك، يقول: المرسل عبد الله السيد، أخونا بدأ رسالته بقوله: سماحة الشيخ عبد العزيز بن باز -حفظه الله- السلام عليكم ورحمة الله وبركاته.مشكلتي أنه صدر مني كلمة طلاق لزوجتي، حيث أنني كنت عائدًا إلى منزلي بعد نهاية الدوام، وفوجئت بزوجتي تقابلني بالغضب، ولم أجد طعام الغداء بعد نهاية الدوام، وكل شيء متوفر في المنزل، فقلت لها: لماذا لم تطبخي اليوم الغداء؟ فأجابت: لا أريد أن أطبخ، بل أحضر طعامك من المطعم، حيث فقدت في تلك اللحظة شعوري، وصدرت مني كلمة: أنت طالق طالق طالق، حيث أنني أرغب من سماحتكم الآن إفادتي بالفتوى، هل يحق لي أن أراجع زوجتي حيث أن لي الرغبة في العودة، وهي كذلك ترغب العودة إلي، حيث لي منها طفل صغير عمره ستة أشهر؟أفتوني جزاكم الله خيرًا.","title":"حكم من قال لزوجته: أنت طالق طالق طالق؛ وأراد مراجعتها","answer":"الجواب: نرى أن تحضر أنت والمرأة ووليها لدى فضيلة قاضي طرفكم حتى ينظر في الأمر، ويفتيكم بما يراه فضيلته، أو يكتب الواقع إلي، وأنا أنظر في ذلك، أنت والمرأة والولي، تحضرون جميعًا عند المحكمة والقاضي -وفقه الله- ينظر في الأمر، فإن أفتاكم والحمد لله، وإن رأى أن يثبت كلامك وكلام المرأة ووليها، وصفة الواقع، وهل سبقه ولحقه طلاق وصفة غضبك وأسبابه، ثم بعد ذلك إذا جاء الجواب ننظر في الأمر -إن شاء الله- وهذا هو الطريقة التي نسير عليها في مثل هذا، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17664/حكم-من-قال-لزوجته-انت-طالق-طالق-طالق-واراد-مراجعتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91606.mp3","categories":["الطلاق"]},{"id":18585,"question":"رسالة وصلت إلى البرنامج من المخواه، وباعثها أخونا أحمد علي العمري، أخونا يسأل ويقول: أنا رجل أمي لا أقرأ ولا أكتب، وعندي ولد يدرس في الصف الرابع لا يذاكر، وهددته بأن قلت له: عليّ الطلاق من ظهر أمك إنك لو ما تدرس إنني لأفعل بك كذا وكذا، وزعلت أمه من كلمة الطلاق، ونرجو أن تفتونا في ذلك، جزاكم الله خيرًا.","title":"حكم طلاق من هدد ابنه بطلاق أمه إذا لم يطعه","answer":"الجواب: إذا كان المقصود من هذا الطلاق حث ولدك على المذاكرة، والعناية بدروسه، وليس قصدك تطليق أمه وفراقها، وإنما قصدك تخويفه وتخويف أمه حتى يجتهدا جميعًا فيما يتعلق بالدروس، وحتى تحرص أمه عليه؛ فلا بأس عليك بذلك، وعليك كفارة يمين إذا لم يحصل منه المطلوب، إذا تساهل ولم يقدر كلامك ولم يجتهد؛ فعليك كفارة اليمين، ولا طلاق عليك، لا يقع عليها شيء على الصحيح من أقوال العلماء. أما إذا كان مقصودك فراقها إن لم يجتهد الولد ناويًا فراقها، أنك تفارقها إذا لم يجتهد ولدها؛ لأنك تظن فيها أنها تتساهل معه، وأنها لا تشجعه، فإذا كنت أردت ذلك؛ فإنه يقع عليها طلقة إذا تساهل ولم يبال بكلامك؛ يقع عليها طلقة واحدة، وتراجعها في الحال، ولا بأس عليك، هذا إذا أردت طلاقها إذا كنت أردت الطلاق. أما إذا كنت أردت التخويف والتحذير فقط، فهذه الكلمة في حكم اليمين، وعليك كفارتها في أصح أقوال أهل العلم: وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فإن عجزت تصوم ثلاثة أيام، هذه كفارة اليمين. ونوصيك بعدم العجلة في الأمور، وعدم استعمال الطلاق، بل تحرضه وتوصيه بالكلام الطيب، وتؤدبه إذا رأيت تأديبه بالضرب الخفيف، أما الطلاق فاتركه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17742/حكم-طلاق-من-هدد-ابنه-بطلاق-امه-اذا-لم-يطعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_871/nour_87105.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18700,"question":"مستمع من مكة المكرمة رمز إلى اسمه بالحروف (ع. ج. د) يقول: أرجو من سماحة الشيخ أن يتفضل بإجابتي على القضية التالية:يقول: أنا رجل سعودي، ومقيم في مكة المكرمة، وقد بلغت من العمر عتيًا، وسبق بيني وبين زوجتي سوء تفاهم في منزلي قبل ستة وثلاثين عامًا، ثم إني خرجت من المنزل، ثم عدت إلى المنزل، فوجدت زوجتي في دكاني قائمة أمام درج النقود، وكان الدكان في نفس المنزل، فقلت لها: ماذا تفعلين؟ فأجابتني بقولها: لا شيء، فقلت: وماذا أخذت من نقود؟قالت: لم آخذ شيئًا، فقلت: أرجعي ما أخذت من نقود وإلا فأنت طالق، فقالت: إني لم آخذ شيئًا، فقلت: اذهبي لوالدك، فذهبت لوالدها، ثم إنه بعد أسبوع أتى بها والدها إلى عندي، وقال: استلم زوجتك إنها لم تأخذ شيئًا من النقود، ثم ذهب وتركها عندي، وهي مقيمة -كما قلت- معي الآن، رزقت منها بأولاد بنين وبنات، فأرجو أن توجهوني، ماذا عليّ فيما سلف؟جزاكم الله خيرًا.","title":"الطلاق المعلق بشرط يقع بوقوعه","answer":"الجواب: عليك أن تراجع المحكمة في ذلك، وهي تفتيك -إن شاء الله- بما ترى، أو تحضر مع زوجتك وأبيها عند مندوبنا في مكة الشيخ جابر بن محمد المدخلي، حتى يكتب كلامكم، وننظر في ذلك -إن شاء الله-. المقدم: جزاكم الله خيرًا. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/17790/الطلاق-المعلق-بشرط-يقع-بوقوعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73510.mp3","categories":["الطلاق"]},{"id":18704,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع علي أحمد رحمة الله، أخونا علي له قضية يقول فيها: تخاصم رجلان، وأراد الناس أن يصلحوا بينهما، فحلف أحدهما بالطلاق ثلاثًا أن لا يصالح الثاني.وبعد فترة خفت ثورة الغضب، وأراد مصالحة صاحبه، وفعلًا تم الصلح بينهما، فماذا عليه أن يفعل؟ وهل زوجته محرمة عليه؟ وإذا قال: علي الطلاق، وكان يقصد واحدة -أي: طلقة واحدة- ولم تسبقها أي طلقة قبل ذلك، فماذا يفعل؟جزاكم الله خيرًا.","title":"من حلف بالطلاق ثم حنث فهو بحسب نيته","answer":"الجواب: هذا فيه تفصيل: إن كان أراد المنع؛ فحكمه حكم اليمين،  الامتناع من المصالحة، وليس قصده إيقاع الطلاق، إنما قصد الامتناع من المصالحة فقط، فهذا حكمه حكم اليمين؛ وعليه كفارة يمين. أما إن كان أراد إيقاع الطلاق إن صالح؛ فإنه يقع به طلقة واحدة؛ لهذه المصالحة التي أراد بها إيقاع الطلاق، إذا كان أراد أنه إن صالح صاحبه، فإنه يقع عليه الطلاق، فإنه يقع الطلاق. الأحسن أن يسأل المحكمة، أو يتصل بنا مع ولي زوجته؛ حتى ينظر في الأمر على بصيرة، وإلا فهذا هو التفصيل، نعم، هذا هو التفصيل في حقه، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/17809/من-حلف-بالطلاق-ثم-حنث-فهو-بحسب-نيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73515.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18803,"question":"أخونا في سؤاله الأخير يسأل ويقول: تشاجرت مع زوجتي، وقلت لها بعصبية: علي الطلاق بالثلاثة ما أنت ذاهبة إلى العمل على الإطلاق، وبالفعل ثاني يوم ما ذهبت إلى العمل، وذهبت أنا إلى عملها؛ لكي أقدم لها استقالة؛ فرفض المسؤولون، وعادت إلى العمل، ماذا أفعل؟جزاكم الله خيرًا.","title":"حكم الحلف بالطلاق ثلاث بلفظ واحد","answer":"الجواب: هذا فيه تفصيل يا أخي: إن كان المقصود من كلامك هذا منعها من العمل، وليس قصدك إيقاع الطلاق، وإنما أردت تهديدها وتخويفها لعلها تستجيب؛ فعليك كفارة يمين، ويكون هذا الطلاق في حكم اليمين في أصح قولي العلماء، كما أفتى بذلك جماعة من أهل العلم منهم: شيخ الإسلام ابن تيمية -رحمه الله- وتلميذه العلامة ابن القيم -رحمه الله- وجماعة من أهل العلم. هذا إذا كان قصدك منعها وتهديدها وتخويفها، ثم رجعت عن ذلك ورأيت أن تسمح لها؛ فلا بأس وعليك كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فمن لم يجد فصيام ثلاثة أيام -كما بينه الله في سورة المائدة- وإطعام المساكين: هو أن يعطى كل واحد نصف صاع من قوت البلد من تمر أو أرز، يعني: كيلو ونصف تقريبًا، أو كسوة تجزئهم في الصلاة كإزار ورداء أو قميص، أو إعتاق رقبة كما بينه الله . أما إن كنت قصدت إيقاع الطلاق، يعني: نيتك إيقاع الطلاق، أو ناو هذا وهذا: قصدت منعها وقصدت إيقاع الطلاق جميعًا؛ فإنه يقع عليها بهذا طلقة على الصحيح، ولو قلت بالثلاث يقع طلقة واحدة؛ لأن الطلاق بالثلاث بكلمة واحدة ولفظ واحد يعتبر طلقة واحدة في أصح قولي أهل العلم؛ لأنه ثبت من حديث ابن عباس -رضي الله عنهما- عن النبي ﷺ أنه جعل الطلاق الثلاث واحدة لفظ ابن عباس قال: \"كان الطلاق على عهد النبي ﷺ وعهد الصديق أبي بكر وأول خلافة عمر طلاق الثلاث بواحدة\"، وفي لفظ سئل: \"ألم تكن الثلاث تجعل واحدة في عهد النبي ﷺ وعهد أبي بكر وفي أول خلافة عمر؟ قال: بلى\" يعني: ابن عباس -رضي الله عنهما-. فالمقصود: أنه أخبر ابن عباس أن الطلاق كان يجعل واحدة في عهد النبي ﷺ، يعني: الطلاق بالثلاث بكلمة واحدة يجعل واحدة في عهد الصديق ، ثم في عهد عمر ، كما كان في عهد النبي ﷺ، ثم رأى عمر إمضاء الثلاث ولو بكلمة واحدة، فأمضاها  وأرضاه ردعًا للناس عن التساهل بالطلاق. فالحاصل: أنك إذا كنت أردت الطلاق أو أردت الأمرين: الطلاق والمنع جميعًا، ثم سمحت لها أو عصتك وذهبت إلى العمل؛ فإنه يقع عليها طلقة واحدة بهذا، ولك مراجعتها ما دامت في العدة، إذا كنت لم تطلقها طلقتين قبل ذلك، أما إن كنت طلقتها طلقتين قبل ذلك تكون هذه هي الأخيرة، ولا تحل إلا بعد زوج، بعد زوج شرعي، وبعد وطئه لها، ثم فراقه لها بموت أو طلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17965/حكم-الحلف-بالطلاق-ثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_877/nour_87708.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18848,"question":"إذا رجل حلف يمينًا بالله، أو يمين طلاق، وهو في حالة غضب، فهل يكتب عليه هذه اليمين؟ وهل من الواجب عليه دفع الفدية؟","title":"حكم اليمين بالطلاق وغيره أثناء الغضب","answer":"الجواب: هذا مقام تفصيل يحتاج إلى تفصيل وعناية، فاليمين ضابطها: أن يعلق الطلاق أو التحريم على شرط يقصد منه المنع أو الحث أو التصديق أو التكذيب، هذه يقال له يمين، كأن يقول: عليه الطلاق إن كلم فلانًا، يقصد منع نفسه من كلامه، أو يقول: عليه الطلاق إن لم يزر فلانًا، يقصد حث نفسه على زيارته، أو يقول: عليه الطلاق إن فلانًا قد مات، يقصد أنه يصدق في ذلك، حتى يصدق، أو عليه الطلاق أن هذا الشيء لم يقع حتى يصدق أنه لم يقع. فالحاصل: أن التعليق إنما يكون يمينًا إذا كان لقصد الحث، أو المنع، أو التصديق، أو التكذيب، فهذا إذا كان هذا قصد المتكلم يكون حكمها حكم اليمين على الصحيح، ويكفي كفارة اليمين في ذلك، ولا يقع الطلاق، ولا التحريم بهذه النية. أما إذا كان المقصود التعليق فقط، فهذا يقال له: تعليق، ولا يقال له يمين، كأن يقول: إذا دخل رمضان فزوجته طالق، فهذا يسمى تعليق إذا دخل رمضان طلقت، ليس بيمين، وكأن يقول: إذا وضعت الحمل فهي طالق، أو يقول: إذا دخل شهر ذي الحجة فهي طالق، وما أشبه ذلك من التعليقات التي ليس فيها حث ولا منع ولا تصديق ولا تكذيب، إنما هي تعليقات محضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17974/حكم-اليمين-بالطلاق-وغيره-اثناء-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92113.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18853,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من جمهورية مصر العربية، تقول: (ن. م. ع) أختنا بدأت رسالتها بقولها:بسم الله الرحمن الرحيمإلى سماحة الشيخ عبد العزيز بن باز، بعد تقديم وافر الشكر والاحترام لسيادتكم بالتفضل والإجابة على سؤالي هذا:أنا شابة في العشرين من عمري، متزوجة منذ عامين، رزقت خلالهما بطفلة، ومنذ حوالي ثمانية أشهر حدث خلاف بيني وبين زوجي تبادلنا فيه الأخطاء، وقام زوجي بطردي من المنزل، وبالتالي ذهبت أنا إلى بيت أبي، وهو كذلك، وفي أثناء تواجده عند أهله، قام بقول هذه العبارة: أشهد الله بأنها طالق بعد النفاس، فهل يقع هذا الطلاق؟مع العلم بأنني كنت نفساء في هذه الفترة، وإن كان يقع، فإن زوجي يرفض تطليقي عند المأذون -أي: الطلاق القانوني- إلا بعد أن أبريه من كافة مستحقاتي: مؤخر الصداق، ونفقة المتعة، وغير ذلك، وكذلك إعطاؤه ألفين جنيه على سبيل التعويض، وإلا فسوف يتركني هكذا معلقة، مع العلم بأنه لا ينفق علي أو على ابنته خلال هذه الشهور. أرجو من سيادتكم إبداء النصح والإرشاد لي ولزوجي فيما فيه الخير، جزاكم الله خيرًا.","title":"خصومات الطلاق يرجع فيها إلى المحكمة الشرعية","answer":"الجواب: أيها الأخت في الله، هذه مسألة خصومة ونزاع بينك وبين زوجك، والواجب أن تحل من طريق المحكمة، من طريق القاضي، فعليك أن ترفعي الأمر إلى الحاكم، والحاكم ينظر في الأمر، فيحضرك وزوجك ووليك، ثم ينظر في الأمر ويحكم بينكما بما يقتضيه الشرع المطهر، وإن تيسر الصلح بينكما على وجه لا يخالف الشرع؛ فلا مانع من ذلك، ولكن النظر في الطلاق ووقوعه وعدم وقوعه يكون للقاضي الشرعي، للعالم الذي ينظر في قضيتكم، وفيما يراه الحاكم الشرعي أو العالم البصير بدين الله فيه الكفاية -إن شاء الله-. فأنصح أن تحضري معه عند أحد العلماء المعروفين بالعلم والفضل والبصيرة في أمر الشرع، حتى ينظر في أمركما، وينصحكما، ويصلح بينكما، أو عند الحاكم الشرعي، وهو ينظر في الأمر، نسأل الله لك وله التوفيق. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/18009/خصومات-الطلاق-يرجع-فيها-الى-المحكمة-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_879/nour_87905.mp3","categories":["الطلاق"]},{"id":18891,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من ليبيا هو سالم علي سالم أمانة التعليم بسرف، أخونا له قضية يقول فيها: يجري اليمين على لساني دائمًا على أبسط الأشياء في حياتي اليومية، وكثيرًا ما حاولت التخلص من هذه العادة، ولكن دون جدوى، لا أدري ولا أعلم حتى أنطق باليمين، فما هو رأي الشرع في هذه المشكلة مع ملاحظة الآتي:أولًا: أنطق باليمين سرًا أي: بيني وبين نفسي، ليس لي نية في الحلف باليمين الطلاق، لا تتحرك به شفتاي أي: في السر فقط، لا يسمعه أحد مني أبدًا، فهل ينفذ الطلاق في هذه الحالات؟جزاكم الله خيرًا، ووفقكم لصالح الإسلام والمسلمين.","title":"حكم القسم بالطلاق في النفس دون التلفظ به","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن كان الطلاق الذي وقع في نفسك، تكلمت به، ونطقت به فهذا له حكمه، فإن كنت طلقت امرأتك طلقة واحدة فلها حكمها، كأن تقول: هي طالق، أو امرأتي طالق، أو فلانة بنت فلان طالق، هذا يقع، وهكذا إذا قلت: طالق ثم طالق، ثم طالق، يقع.  أما إن كنت تحدثت به في نفسك، ولم تتكلم بشيء إنما هو حديث النفس، وخاطر القلب، ولم تتلفظ بشيء فإن هذا لا يقع؛ لقول النبي -عليه الصلاة والسلام-: إن الله تجاوز عن أمتي ما حدثت بها أنفسها لم تعمل أو تكلم فالخواطر القلبية، والأحاديث النفسية لا يقع بها شيء، وإنما يقع بما يصدر لفظًا من لسانك، وأنت قاصد له هذا هو الذي يقع، مثل ما تقدم: أنت طالق، هي طالق، امرأتي طالق، فلانة بنت فلان طالق. أما ما يقع في نفسك، ولم تتكلم به، ولم يحصل بذلك تلفظ، فإن هذا من حديث النفس، والله قد عفا عنه ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18027/حكم-القسم-بالطلاق-في-النفس-دون-التلفظ-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92301.mp3","categories":["الطلاق"]},{"id":19089,"question":"رسالة وصلت إلى البرنامج من المستمع: أبو النجار إبراهيم مصري مقيم في الأفلاج، أخونا يقول: قلت لزوجتي: إن ذهبت إلى منزل والدك فأنت طالق، وأنا الآن مقيم في المملكة، وحدث خلاف بين زوجتي وأهلي فذهبت إلى بيت والدها، أرجو إفادتي ماذا علي أن أفعل؟ ولكم جزيل الشكر.","title":"حكم من قال لزوجته: إن ذهبت إلى كذا فأنت طالق فذهبت","answer":"الجواب: إن كنت قصدت إيقاع الطلاق إن ذهبت فإنه يقع عليها طلقة ولك مراجعتها في العدة، إذا كانت لم تطلق قبل هذا طلقتين. أما إن كنت أردت منعها وتهديدها وتخويفها ولم تقصد إيقاع الطلاق، فإن هذا له حكم اليمين في أصح قولي العلماء، يكون عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم لكل مسكين نصف صاع من قوت البلد من تمر أو غيره بصاع النبي ﷺ ومقدار ذلك كيلو ونصف تقريبًا، أو كسوتهم بأن تعطي كل واحد ما يجزئه في الصلاة كقميص أو إزار ورداء والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18253/حكم-من-قال-لزوجته-ان-ذهبت-الى-كذا-فانت-طالق-فذهبت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93004.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":19117,"question":"رسالة وصلت إلى البرنامج من اليمن الشمالي وباعثها أحد الإخوة يقول: (ع. ع. ح) أخونا له سؤالان:في سؤاله الأول يقول: رجل طلق زوجته ثم راجعها، ثم طلقها الطلقة الثانية ثم راجعها، ثم طلقها الثالثة وقبل أن تكمل العدة توفي هذا الزوج، فهل عليها عدة المتوفى عنها زوجها؟وهل ترث من مال زوجها الذي طلقها الطلقة الثالثة، ولكنها لم تكمل العدة بعد؟","title":"حكم المطلقة ثلاثًا إذا مات مطلقها قبل انقضاء عدتها","answer":"الجواب: إذا كان الواقع كما قال السائل فليس عليها عدة وفاة، وإنما عليها أن تكمل عدة الطلاق، وليس لها إرث؛ لأنها بالطلقة الأخيرة الثالثة بانت من زوجها. فإذا مات بعد الطلقة الأخيرة، فإنها لا ترث منه ولا تعتد منه عدة الوفاة، ولكنها تكمل عدة الطلاق إذا كانت طلقات المذكورة طلقات شرعية واقعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18291/حكم-المطلقة-ثلاثا-اذا-مات-مطلقها-قبل-انقضاء-عدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_931/nour_93106.mp3","categories":["الطلاق"]},{"id":19124,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (م.أ.م) المنياوي، أخونا له مجموعة من الأسئلة، في سؤاله الأول يقول: أنا متزوج، وفي مرة حدث خلاف بيننا، فقلت لها: أنت محرمة علي إن لم ترجعي عن الأمور التي تفعليها، وبعد أيام تصالحنا، وكان بيننا المعاشرة الزوجية، ثم سافرت إلى اليمن حيث أعمل.والآن ما هو موقفي بالنسبة لما صدر مني؟ هل تكون طلقة؟ أم يمين؟ وإذا كانت يمين فما هي الكفارة التي تكون علي؟ أسمع في الإجابة عن بعض الأسئلة والاستفسارات عن كفارتين: الأولى تقول: عتق رقبة، أو إطعام عشرة مساكين، أو صيام ثلاثة أيام، الثانية تقول: عتق رقبة، أو إطعام ستين مسكينًا، أو صيام ثلاثة أشهر، فما الفرق بين الكفارتين في الحكم الشرعي؟وهل من الممكن إخراج الكفارة على هيئة نقود توزع على الفقراء بما يساوي الإطعام؟جزاكم الله خيرًا.","title":"حكم قول الرجل لزوجته: أنت محرمة علي وما يترتب عليه","answer":"الجواب: هذا الكلام يحتاج إلى تفصيل حسب نية المتكلم، فإذا قال: هي محرمة عليه إذا لم تدع الأمور الفلانية، هذا إذا تركتها فلا تحريم، انتهى الأمر؛ لأنها امتثلت الأمر وتركت، فليس عليه شيء، أما إذا لم تترك بأن عاندت، وخالفت ولم تبالي بالكلام فهذا فيه تفصيل: إن كان أراد بهذا الكلام تحريمها أو تطليقها فهو على ما أراد، إن كان أراد التحريم فهي محرمة، وإن كان أراد الطلاق وقع الطلاق، وإن كان أراد منعها ولم يرد تحريمًا ولا طلاقًا وإنما أراد منعها والتشديد عليها وتخويفها وتحذيرها فهذا له حكم اليمين. فالمسألة تختلف بحسب النية، فإذا كان نوى بهذا الكلام تخويفها وتحذيرها ولكن لم تمتثل، فإن عليه كفارة يمين، وهي عتق رقبة مؤمنة، أو إطعام عشرة مساكين، أو كسوتهم، مخير بين الثلاث: عتق رقبة مؤمنة، أو إطعام عشرة مساكين، أو كسوتهم، والإطعام كونه يعشيهم أو يغديهم، أو يدفع إليهم نصف صاع لكل واحد، من التمر أو من الأرز من قوت البلد، يعني: كيلو ونصف تقريبًا، أو يكسوهم كسوة، كل واحد يعطيه إزار ورداء، أو قميص يستره في الصلاة، هذه هي الكفارة، فإن عجز عن هذا كله، عجز عن الإطعام وعن الكسوة وعن العتق، أجزأه أن يصوم ثلاثة أيام، عند العجز أن يصوم ثلاثة أيام، هذه كفارة اليمين. أما إن كان أراد تحريمها إذا لم تدع الأمور، أراد تحريمها فهذا حكمه حكم الظهار، كما لو قال: أنت علي كظهر أمي، أو ظهر أختي ونحو ذلك، فإذا حرمها بهذا التحريم، أو قال: أنت علي حرام أو محرمة إذا لم تدعي هذا الأمر، فلم تدعه قصده تحريمها فإن عليه كفارة الظهار: وهي عتق رقبة مؤمنة، فإن عجز فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، وليس في الكفارة ثلاثة أشهر، ما فيها إلا شهران ما هي بثلاثة أشهر، الكفارة إما شهران وإما صيام ثلاثة أيام في كفارة اليمين، كما تقدم. والشهران في الظهار، يعني: تحريم الزوجة، وفي الوطء في رمضان، وفي قتل الخطأ وشبه العمد، أولاً: عتق رقبة مؤمنة، فإن عجز في تحريمه زوجته أو في وطئه في رمضان أو في قتله نفسًا بغير حق، إن عجز عن الرقبة صام شهرين متتابعين، ستين يومًا، فإن عجز بقيت الكفارة معلقة في ذمته حتى يستطيع إذا كان قتلًا، إذا كانت المعصية قتلًا، لأن الحادث قتلًا فليس فيه إطعام، بل تبقى الكفارة معلقة وهي عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، هذه كفارة القتل كما بينه الله في كتابه العظيم، فإذا عجز عن الصيام والعتق تبقى في ذمته متى قدر على العتق أعتق، ومتى استطاع الصيام صام. أما في الظهار، وتحريم الزوجة وفي الوطء في رمضان فهذا فيه أمر ثالث وهو الإطعام، عند العجز عن الرقبة وعند العجز عن الصيام يطعم ستين مسكينًا، ثلاثين صاعاً، في هاتين المسألتين: في مسألة الجماع في رمضان وفي مسألة تحريم الزوجة تحريمًا مطلقًا لا معلقًا بفعل كذا وفعل كذا، يقصد منعها، بل تحريم مطلق كأن يقول: أنت علي محرمة، أنت علي كظهر أمي، أو أنت علي محرمة إذا دخل رمضان، هذا هو التحريم المطلق، أو المعلق تعليقًا ليس فيه حث ولا منع، بل تعليقًا تامًا، فيترتب عليه حكم، فيلزم بعتق رقبة مؤمنة إذا قدر، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، وفي الظهار قبل أن يمسها، في تحريم الزوجة يأتي بهذه الكفارة قبل أن يمسها، قبل أن يقربها، وهي مرتبة على هذا الترتيب: العتق ثم الصيام عند العجز عن العتق، ثم الإطعام عند العجز عن الصيام، والإطعام يكون لستين مسكينًا، طعامًا لا نقودًا، يطعمهم يعشيهم أو يغديهم أو يعطيهم على نصف صاع من التمر أو من الأرز أو من الحنطة حسب قوت البلد، ومقداره بالوزن نحو كيلو ونصف تقريبًا من جهة الوزن. وأما في التحريم المعلق تعليقًا مراد منه الحث أو المنع أو التصديق أو التكذيب هذا فيه كفارة اليمين كما تقدم، فإذا قال: أنت محرمة علي إن فعلت كذا، أو أنت طالق إن فعلت كذا، إن كلمت فلانًا، إن فعلت الأمر الفلاني، إن عصيت أمي، إن خرجت من البيت قصده تحذيرها، ليس قصده طلاقها، قصده تحذيرها وتخويفها فهذا حكم اليمين. وهكذا لو قال: أنت علي، أنت مطلقة إن فعلت كذا، قصده منعها، تحذيرها، وليس قصده فراقها، فهذا له حكم اليمين، في أصح قولي العلماء كما تقدم، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18314/حكم-قول-الرجل-لزوجته-انت-محرمة-علي-وما-يترتب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88506.mp3","categories":["الأيمان والنذور","الطلاق","الظهار"]},{"id":19131,"question":"بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، أنا من المعجبات ببرنامجكم، ونشكر المسئولين عليه لما فيه من النفع الكثير، وأرجوكم شاكرة عرض رسالتي على سماحة الشيخ عبد العزيز بن عبد الله بن باز.والسؤال هو كما يلي: اختلفت أنا وزوجي، فوقع منه طلاق على أن لا يكمل بناتي تعليمهن، أي: عند سنة معينة يقوم بفصلهن عن المدرسة، وفي ذلك الوقت كانت إحدى بناتي صغيرة حديثة الولادة، والآن وصلت هذه الصغيرة المرحلة نفسها، هل يقع الطلاق عندما تكمل هذه الصغيرة تعليمها؟ أم أنها لا تدخل في موضوع الطلاق؟ علمًا بأن الموضوع الذي اختلفنا فيه ليس من شأن التعليم أو المدارس، أجيبونا مشكورين، وصاحبة الرسالة هي الأخت (ل.ع. ر) من القصيم_ بريدة؟","title":"حكم الطلاق المعلق","answer":"الجواب: هذه المسألة وأشباهها ترجع إلى نية المطلق والحالف، فإذا كان المطلق أراد بذلك منعهن ولم يرد إيقاع الطلاق، وإنما أراد التشديد والتحذير والتهديد، ومنع نفسه من الإذن لهن، وليس قصده إيقاع الطلاق على أهله إذا وقع خلاف ما طلق عليه، فهذه الواقعة لها حكم اليمين، ويكون على المطلق كفارة اليمين إذا سمح لهن بالدراسة؛ لأنه لم يقصد إيقاع الطلاق وإنما قصد منعهن وشدد على نفسه بالطلاق، فهذا مثل لو قال: عليه الطلاق لا يكلم فلانًا، وعليه الطلاق لا يزور فلانًا، أو قال: عليه الطلاق في حق امرأته لا تزوري فلانًا، أو لا تذهبي إلى فلان، أو إلى فلانة، وقصده المنع والترهيب، والحث على ترك هذا الشيء، فهذا حكمه حكم اليمين، وليس له حكم الطلاق، وعليه كفارة اليمين في أصح قولي العلماء، بخلاف إذا كان قصد الطلاق فإنه يقع الطلاق، كما لو قال: عليه الطلاق إذا دخل رمضان، أو إذا خرج رمضان أو ما أشبه ذلك، فإنه يقع الطلاق؛ لأنه من الطلاق المعلق تعليقًا كاملًا، تامًا ليس فيه قصد حث أو منع.. إلى غير ذلك. فالحاصل أن التعليق قسمان: تعليق يقتضي إيقاع الطلاق، كالتعليق على دخول رمضان ونحو ذلك. وتعليق فيه تفصيل، مثل هذا الطلاق الذي علقه على الدراسة، فإن كان قصد إيقاع الطلاق، وقع الطلاق إذا درسن، وإن كان أراد منعهن فقط ولم يرد إيقاع الطلاق، وإنما أراد تخويفهن، وإلزام نفسه بمنعهن، فهذا حكمه حكم اليمين، وعليه كفارتها كفارة اليمين في أصح قولي أهل العلم. نعم. المقدم: جزاكم الله خيراً، إذًا هذه الصغيرة هل تدرس؟ الشيخ: نعم، تدخل تدخل. نعم. المقدم: تدرس. الشيخ: تدخل في الحكم. المقدم: تدخل في اليمين. الشيخ: في اليمين. نعم. المقدم: في اليمين. الشيخ: لأن قصده بناته عمومًا. المقدم: سواء من كان حاضرًا أو كان غائبًا؟ الشيخ: أما لو قال: معينات فلانة و فلانة، فإنها لا تدخل، أما إذا قال: بناتي، دخلت الصغيرة والكبيرة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18308/حكم-الطلاق-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88502.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":19134,"question":"في الحديث -كما تقول أختنا-: (متى أحب الله عبدًا ابتلاه)، هل الطلاق مصيبة من المصائب التي يبتلي الله بها عباده فيكفر بها سيئاتهم ويغفر ذنوبهم؟","title":"الطلاق من المصائب المكفرة للسيئات","answer":"الجواب: نعم، من المصائب لا شك إنه من المصائب، كون المرأة تطلق من زوج صالح مصيبة، لكن تسأل ربها أن يعوضها خيرًا، يقول الله سبحانه: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130]، أما طلاقها من زوج فاسق أو زوج يضرها فهي نعمة من الله ما هي بمصيبة نعمة من الله، لكن طلاقها من زوج طيب، من زوج يعينها على الخير، لا شك أنها مصيبة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18306/الطلاق-من-المصاىب-المكفرة-للسيىات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73709.mp3","categories":["الطلاق"]},{"id":19143,"question":"مستمع بعث برسالة وآثر فيها عدم ذكر اسمه، يقول في أحد أسئلته: في ذات يوم تلفظت بلفظ الظهار، ولم يكن في نيتي الانفصال عن زوجتي، وكنت لا أعرف الفرق بين الظهار والطلاق، ثم إني فعلت الشيء الذي كان عليه الحلفان، فأطعمت عشرة مساكين، فهل هذا يكفي أم يقع علي حد الظهار؟ أفيدوني أفادكم الله وجزاكم الله خيرًا.","title":"حكم من ظاهر من زوجته جاهلًا بحكم الظهار","answer":"الجواب: إذا كنت ظاهرت من امرأتك قلت: علي زوجتي مثل ظهر أمي، أو مثل ظهر أختي فهذا الظهار ما يكفي عشرة مساكين لا بد من عتق رقبة مؤمنة، فإن عجزت فصيام شهرين متتابعين، فإن عجزت فإطعام ستين مسكينًا قبل أن تمسها؛ لكل مسكين نصف صاع يعني ثلاثين صاعًا. ونوصيك بمراجعة العلماء في بلدك القاضي، أو غيره من العلماء المعروفين بالعلم تسألهم عما جرى منك توضح لهم الواقع، إذا كنت ظاهرت من امرأتك يعني: قلت لها هي حرام عليك كأمك، أو كأختك، أو هي كظهر أمك، أو أختك، أو ما أشبه ذلك، فهذا كفارته مثلما بين الله في القرآن في سورة قد سمع، سورة المجادلة، كفارته مرتبة أولًا عتق رقبة مؤمنة إذا استطاع الإنسان، فإن عجز يصوم شهرين متتابعين ستين يومًا، فإن عجز يطعم ستين مسكين ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد مقداره كيلو ونص تقريبًا قبل أن يمس المرأة، وعليه التوبة من ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18323/حكم-من-ظاهر-من-زوجته-جاهلا-بحكم-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79801.mp3","categories":["الطلاق","الظهار"]},{"id":19234,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد بن عبد الغني السقطي المصري، أخونا له قضية يقول فيها: أخبركم سماحة الشيخ أنني قد حلفت أن أبقى في مصر حتى أنجب ولدًا، وكان ذلكم الحلف بالطلاق إلا أنه حتى الآن لم يأتني ولد، وجهوني -جزاكم الله خيرًا- كيف أتصرف؟","title":"حكم الحلف بالطلاق على البقاء في بلد حتى ينجب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذا الطلاق يفسر على حالين: أحدهما: أن تكون أردت إيقاع الطلاق إن خرجت من مصر قبل أن تنجب، فإن كنت أردت هذا؛ فإنه يقع عليك طلقة، إذا خرجت يقع على زوجتك طلقة واحدة، ولك مراجعتها ما دامت في العدة إذا كنت لم تطلقها قبل هذا طلقتين، هذا إذا كنت أردت إيقاع الطلاق إن خرجت قبل أن تنجب. الحال الثاني: أن تقصد حث نفسك على البقاء حتى تنجب ولم ترد إيقاع الطلاق، وإنما أردت حث نفسك على البقاء حتى تنجب، فهذا يكون حكم اليمين في أصح قولي العلماء، كما اختار ذلك أبو العباس شيخ الإسلام ابن تيمية رحمه الله وجماعة، وروي عن جماعة من السلف ما يدل على ذلك. وهذا القول هو الأصح إذا كنت أردت حث نفسك على البقاء في مصر حتى تنجب ولم ترد إيقاع الطلاق إن خرجت ولم تنجب؛ فإن هذا يكون في حكم اليمين لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى، وهذا كلام محتمل فالنية تفسره. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18422/حكم-الحلف-بالطلاق-على-البقاء-في-بلد-حتى-ينجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73806.mp3","categories":["الطلاق"]},{"id":19357,"question":"يسأل أخونا أيضًا ويقول: رجل كبير السن وعنده زوجة كبيرة في السن ويقول لها: أنت مسامحة؛ يعني: أنت طالق ولا عليك عدة تعتدين بها، فما رأيكم في ذلك؟ جزاكم الله خيرًا.","title":"حكم من قصد الطلاق بلفظ لا يدل على الطلاق","answer":"الجواب: إذا كان قصده من قوله: أنت مسامحة قصده الطلاق فإن له نيته تكون طالقة طلقة واحدة، وإذا مات قبل خروجها من العدة فعليها الإحداد وترث وعدتها ثلاثة أشهر إذا كانت يائسة ما تحيض، عدتها ثلاثة أشهر، فإذا مات في الثلاثة الأشهر فهي زوجة وعليها العدة ولها الميراث، وعليها الإحداد إذا كان لم يطلقها قبل هذا طلقتين. أما إن كان طلقها قبل هذا طلقتين فتكون هذه هي الثلاثة وتكون بائنة منه وليس عليها عدة ولا إحداد وليس لها إرث. أما إن كانت هذه الطلقة فقط واحدة، أو ليس قبلها إلا طلقة واحدة تكون هذه ثانية؛ فإنها تكون رجعية، فإن مات في العدة ورثته وحادت عليه وعليها الإحداد كما تقدم، وإن مات بعد خروجها من العدة -بعد ثلاثة أشهر- فإنها أجنبية ليس عليها عدة، ولا إحداد وليس لها ميراث.  المقدم: جزاكم الله خيرًا، كأنه يقول شيخ عبد العزيز: إنه لا يقصد الطلاق طالما أنه ذكر أنه لا عدة عليها؟\nالشيخ: لابد ..... نيته، من قصده الطلاق فإنها تكون طلقة، وإذا مات بعد مضي ثلاثة أشهر عليها وهي يائسة لا تحيض؛ فإنها بهذا تكون أجنبية بعد الثلاثة الأشهر، فلا ترث ولا عدة عليها ولا إحداد عليها. أما إن كان قصده بأنت مسامحة يعني: ما عليك عدة لا تعتدي مني فهذا ليس إليه هذا إلى الشرع ولو قال: ما عليك عدة. عليها العدة إذا مات وهي زوجة له فعليها العدة أربعة أشهر وعشر، وعليها الإحداد وترك الزينة، وترك الطيب، وترك الحلي، والكحل ونحوه كما على غيرها من النساء. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18564/حكم-من-قصد-الطلاق-بلفظ-لا-يدل-على-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_900/nour_90002.mp3","categories":["الطلاق"]},{"id":19435,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أنا شاب أبلغ من العمر سبعة وعشرين عامًا، وإنني متعود على الطلاق في أي مناقشة مع الآخرين، وبعد أن عقدت قراني على إحدى الفتيات تناقشت مع أحد الأشخاص وطلقت ناسيًا، وقد تكرر مني ذلكم ثلاث مرات بين الواحدة والأخرى عدة أيام وفي مناسبات مختلفة، ثم تكرر ذلك مني أمام أشخاص معينين، والآن أسأل: ما الحكم؟ علمًا بأنني لم أدخل على زوجتي بعد؟ جزاكم الله خيرًا. وصاحب الرسالة هو المستمع (م.م.أ) الشهري من شرورة.","title":"حكم من حلف بالطلاق وهو لم يدخل بامرأته بعد","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفعليك يا أيها السائل أن تراجع المحكمة لديك وتوضح لها صفة الواقع، وفيما تراه المحكمة الكفاية إن شاء الله، أو تكتب لنا في الواقع ونحن نحيلك إلى المحكمة مع زوجتك ووليها حتى نعرف الحقيقة وتكون الفتوى بعد ذلك.\nالمقدم: جزاكم الله خيرًا. وإن لم يدخل بها بعد؟\nالشيخ: ولو كان ما دخل بها حتى نعرف صفة الواقع، هل هو طلاق معلق، أو طلاق منجز، وإذا كان معلق فهل أراد به إيقاع الطلاق، أم أراد منع شيء أو حثًا على شيء، إلى غير ذلك، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18669/حكم-من-حلف-بالطلاق-وهو-لم-يدخل-بامراته-بعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93801.mp3","categories":["الطلاق"]},{"id":19485,"question":"إذا طلق الرجل زوجته بعد العقد عليها، وكان قد خلا بها بعد العقد، وقبل الدخول؛ فهل عليها عدة تعتدها، ولها الصداق أم غير ذلك؟","title":"حكم من طلق زوجته قبل الدخول وقد خلا بها","answer":"الجواب: في هذا خلاف بين أهل العلم، والصواب أن عليها العدة، وأن لها الصداق، وأنه إذا خلا بها حكم ذلك حكم المسيس، والوطء، وهذا الذي أفتى به الخلفاء الراشدون  وهو في حكم المسيس، في حكم الدخول بها، فإذا خلا بها وليس معهما أحد خلوة تمكنه من اتصاله بها؛ فإن ذلك حكمه حكم ما إذا جامعها، لها المهر كاملًا، وعليها العدة إذا طلقها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18740/حكم-من-طلق-زوجته-قبل-الدخول-وقد-خلا-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94509.mp3","categories":["الطلاق"]},{"id":19546,"question":"يقول السائل -سماحة الشيخ-: ما حكم طلب الزوجة من الزوج الطلاق بدون سبب شرعي؟","title":"حكم طلب المرأة الطلاق بدون سبب","answer":"الجواب: لا يجوز لها ذلك بدون سبب، ليس لها طلب الطلاق بدون سبب. نعم. المقدم: وإذا طلبت الزوجة من الزوج الطلاق؛ لأنه لم يحصل بينهم مودة وبينهم أطفال هل يجوز لها؟ الشيخ: لا يجوز لها إلا بأسباب كظلمه لها، أو بغضاء لا تستطيع البقاء معها، بغضاء شديدة لا تستطيع البقاء معه، أو أسباب أخرى وجيهة، وهو لا يطلق إلا إذا رأى مصلحة، إذا رأى المصلحة بالطلاق طلقها طلقة واحدة فقط، وإلا فلا يطلق، لكن إذا رأى المصلحة لا بأس.","link":"https://binbaz.org.sa/fatwas/18800/حكم-طلب-المراة-الطلاق-بدون-سبب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94628.mp3","categories":["الطلاق"]},{"id":19607,"question":"تقول السائلة يا سماحة الشيخ: أرجو فتوى منكم في طلاق المرأة وهي حائض، هل يقع الطلاق والمرأة حائض أثابكم الله؟","title":"هل يقع الطلاق والمرأة حائض؟","answer":"الجواب: هذا الموضوع فيه خلاف بين العلماء، أكثر العلماء يرون أنه يقع الطلاق في الحيض، هذا الذي عليه أكثر أهل العلم، وذهب بعض أهل العلم إلى أنه لا يقع، إذا كان يعلم الزوج أنها في الحيض، إذا طلقها في الحيض فقد أثم ولا يقع إذا كان يعلم، أما إذا كان ما يعلم إلا بعد الطلاق منها فالطلاق يقع إذا كان لا يعلم. أما إذا كان يعلم أنها حائض قبل أن يطلق، ثم أقدم على الطلاق فالصواب أنه لا يقع، وعليه التوبة لأنه لا يجوز، أما إذا كان لا يعلم حالها وطلقها، ثم أخبرته أنها حائض فالطلاق يقع، طلاقه يقع إذا كان لا يعلم. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18875/هل-يقع-الطلاق-والمراة-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94917.mp3","categories":["الطلاق","الحيض والنفاس","قضايا المرأة"]},{"id":19707,"question":"الرسالة التالية رسالة المستمع المختار ولد أبيك من موريتانيا ومقيم في ليبيا، بعث برسالة يسأل فيها هذا السؤال، ويقول: ما هي كيفية رجوع المرأة الطالق بالثلاث إلى زوجها السابق بعد أن تزوجت بعده؟ وما هي الشروط التي يجوز لها ولأهلها أن يشترطوها على الزوج الجديد بعد أن ينكحها لكي يطلقها لتحل لزوجها الأول، هل تجوز الشروط في مثل هذا الزواج؟ أفيدونا أفادكم الله وجزاكم خير الجزاء","title":"كيفية رجوع المرأة الطالق بالثلاث إلى زوجها السابق","answer":"الجواب:\nلا يجوز أن يشترط عليه أن يطلقها وأن ينكحها للتحليل، هذا محرم، الرسول ﷺ: لعن المحلل والمحلل له وسماه \"التيس المستعار\". فلا يجوز، لا بد أن يكون نكاح رغبة، إذا تزوجت إنساناً يرغب فيها ثم طلقها بعد الدخول بها يعني بعدما وطئها ثم طلقها عن رغبته لا عن شروط مشروطة عليه فإنها تحل للأول. أما إذا نكحها للثاني من أجل أن يحلها الأول فإنها لا تحل، بل هذا نكاح تحليل صاحبه ملعون إذا قصد ذلك، نسأل الله العافية، لا في حلها للأول أن يكون النكاح الثاني نكاح رغبة نكاحاً شرعياً لا مشروطاً على صاحبه أن يطلق، ولا بد أن يطأها أيضاً ثم يطلق باختياره أو يموت عنها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/26510/كيفية-رجوع-المراة-الطالق-بالثلاث-الى-زوجها-السابق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D9%83%D9%8A%D9%81%D9%8A%D8%A9%20%D8%B1%D8%AC%D9%88%D8%B9%20%D8%A7%D9%84%D9%85%D8%B1%D8%A3%D8%A9%20%D8%A7%D9%84%D8%B7%D8%A7%D9%84%D9%82%20%D8%A8%D8%A7%D9%84%D8%AB%D9%84%D8%A7%D8%AB%20%D8%A5%D9%84%D9%89%20%D8%B2%D9%88%D8%AC%D9%87%D8%A7%20%D8%A7%D9%84%D8%B3%D8%A7%D8%A8%D9%82.mp3","categories":["الطلاق","الرجعة"]}]
